    "status" "text" DEFAULT 'verify_before_relying'::"text" NOT NULL,
    "last_verified_on" "date",
    "review_due_on" "date",
    "guidance_scope" "text" NOT NULL,
    "limitations" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."bob_owner_rulings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ruling_key" "text" NOT NULL,
    "title" "text" NOT NULL,
    "ruling_text" "text" NOT NULL,
    "domain" "text" DEFAULT 'general'::"text" NOT NULL,
    "ruling_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "superseded_by" "uuid",
    "authored_by" "text" DEFAULT 'owner'::"text" NOT NULL,
    "source" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."bob_owner_rulings" IS 'Owner decisions that override general knowledge. The "one sentence a human already knows" that prevents verified-but-wrong answers. Owner-authored only; never machine-generated. Bob queries these via bob_recall_prior_context (0301) at HIGHER AUTHORITY than knowledge cards. Issue #232, epic #228.';

CREATE TABLE IF NOT EXISTS "public"."bob_repo_read_progress" (
