);
COMMENT ON TABLE "public"."canonical_scv" IS 'SCV certification per plate. Source of truth: NZSCV registry. Synced via proxy-server.';
COMMENT ON COLUMN "public"."canonical_scv"."id" IS 'Global SCV registry identity. Used for Freedom Camping self-contained vehicle search independently of organization ownership.';

CREATE TABLE IF NOT EXISTS "public"."canonical_scv_links" (
