    "canonical_vehicle_id" "uuid",
    "candidate_label" "text",
    "candidate_plate" "text",
    "animal_type" "text",
    "candidate_embedding" "jsonb",
    "model_confidence" real,
    "frame_sha256" "text",
    "thumbnail" "text",
