    "person_record_id" "uuid",
    "cctv_import_id" "uuid",
    "location_id" "uuid",
    "canonical_place_id" "uuid",
    "quality_state" "text" DEFAULT 'clear'::"text" NOT NULL,
    "species_confidence" real,
    "is_pest" boolean,
    "attributes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "appearance_embedding" "jsonb",
    "face_vec" "public"."vector"(128),
    "appearance_vec" "public"."vector"(256),
    "portfolio_key" "uuid",
    "portfolio_state" "text" DEFAULT 'unmatched'::"text" NOT NULL,
