CREATE TABLE IF NOT EXISTS "public"."location_zones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "nightly_limit_consecutive" integer,
    "nightly_limit_monthly" integer,
    "scv_required" boolean DEFAULT false NOT NULL,
    "jurisdiction_rule_set_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "boundary" "public"."geometry"(MultiPolygon,4326),
    "center_point" "public"."geometry"(Point,4326),
    "radius_meters" integer,
    "zone_type" "text" DEFAULT 'freedom_camping'::"text" NOT NULL,
    "module_key" "text" DEFAULT 'freedom_camping'::"text" NOT NULL,
    "bylaw_clause" "text",
    "bylaw_source_url" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "repeat_stay_window_nights" integer,
    "enforcement_workflow_override" "text",
    "repeat_stay_radius_m" integer,
    "onsite_profile" "text" DEFAULT 'boundary'::"text" NOT NULL,
    "active_schedule" "jsonb",
    "rule_overrides" "jsonb",
    "is_adhoc" boolean DEFAULT false NOT NULL,
    "parking_time_limit_minutes" integer,
    "parking_disabled_multiplier" numeric DEFAULT 2 NOT NULL,
    "parking_signage_photo_url" "text",
    "parking_limit_source" "text",
    "parking_limit_set_by" "uuid",
    "parking_limit_set_at" timestamp with time zone,
    "external_ref" "text",
    "internal_client_ref" "text",
    "despatch_zone_code" "text",
    "location_id" "uuid" NOT NULL,
    "rule_type" "text" DEFAULT 'overnight_limited'::"text" NOT NULL,
    "boundary_status" "text" DEFAULT 'authoritative'::"text" NOT NULL,
    "scv_exempts_restriction" boolean DEFAULT true NOT NULL,
    "boundary_verification" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "boundary_verified_by" "uuid",
    "boundary_verified_at" timestamp with time zone,
    "configuration_version" integer DEFAULT 1 NOT NULL
);
COMMENT ON TABLE "public"."location_zones" IS 'Canonical Zone table. A Zone is a SIBLING of a Site (Org -> Site XOR Zone; see docs/LOCATION_HIERARCHY.md), so site_id and boundary are OPTIONAL: a Zone may stand alone and may be imported before its geometry is set (geometry applied later via the governed geofence step). The 0100 site/boundary NOT-NULL guards were removed in 0111 to match the 0108 sibling model.';
COMMENT ON COLUMN "public"."location_zones"."boundary" IS 'PostGIS MultiPolygon boundary (EPSG:4326). Widened from Polygon in 0279 (Q7 ruling). Used for GPS-to-zone detection and map rendering.';
COMMENT ON COLUMN "public"."location_zones"."center_point" IS 'Centroid of the zone polygon. Used for fast proximity queries.';
COMMENT ON COLUMN "public"."location_zones"."radius_meters" IS 'For circular zones: radius in metres from center_point. NULL for polygon zones.';
COMMENT ON COLUMN "public"."location_zones"."zone_type" IS 'Enforcement type. Determines which compliance rules and notice templates apply.';
COMMENT ON COLUMN "public"."location_zones"."repeat_stay_window_nights" IS 'Repeat-stay rule window in nights: a vehicle may not return within the radius for this many nights. NULL = rule disabled.';
COMMENT ON COLUMN "public"."location_zones"."enforcement_workflow_override" IS 'Per-zone enforcement workflow override. NULL = inherit the org default.';
COMMENT ON COLUMN "public"."location_zones"."onsite_profile" IS 'On-site activation profile: boundary (patrol/parking/freedom/static = polygon + onsite radius) or approach_10m (alarm/noise/biosecurity/smoke = 10 m pre-attendance ring).';
COMMENT ON COLUMN "public"."location_zones"."active_schedule" IS 'Optional time-of-day/day schedule (jsonb) when this module geofence is active. Lets the same area be e.g. freedom_camping overnight and parking 08:00-20:00 as two rows.';
COMMENT ON COLUMN "public"."location_zones"."rule_overrides" IS 'Optional site/geofence-level rule overrides (jsonb) applied on top of the jurisdiction (council, module) ruleset. Override wins where present.';
COMMENT ON COLUMN "public"."location_zones"."is_adhoc" IS 'True for ad-hoc geofences created at incident time (noise/biosecurity/smoke/alarm), distinct from pre-mapped module geofences.';
COMMENT ON COLUMN "public"."location_zones"."parking_time_limit_minutes" IS 'Posted parking time limit in minutes (e.g. P60=60, P120=120, P150=150, P90=90). Null = metered / no fixed limit. Editable in the zone Rules editor; settable from a Bob-read signage photo.';
COMMENT ON COLUMN "public"."location_zones"."parking_disabled_multiplier" IS 'Multiplier applied to the time limit for disabled (mobility) parking. Default 2 = double the posted time. Adjustable per zone.';
COMMENT ON COLUMN "public"."location_zones"."parking_signage_photo_url" IS 'Storage path/URL of the photographed time-limit sign that is the legal authority for the limit (court-defensible provenance).';
COMMENT ON COLUMN "public"."location_zones"."parking_limit_source" IS 'Provenance of the time limit: bob_signage (OCR + human-approved), manual (admin set), rfp_seed (seeded from the contract).';
COMMENT ON COLUMN "public"."location_zones"."despatch_zone_code" IS 'Operational patrol-route despatch code (e.g. 587 Nelson, 586 Richmond, 584 Stoke, 583 Motueka). The pivot that joins a billable patrol/alarm visit (Despatch Zone in the billing feeds) to its patrol route zone. Patrol route zones use zone_type=''patrol_route''; nesting/support relationships use parent_zone_id. text because these are external identifiers, not arithmetic values.';
COMMENT ON COLUMN "public"."location_zones"."location_id" IS 'FK to the Location ("house") this zone is a facet of. Nullable during migration; once backfilled, every zone belongs to exactly one house. The zone is the area facet of the house.';
COMMENT ON COLUMN "public"."location_zones"."rule_type" IS 'Compliance rule class. Act-aligned values (Freedom Camping Act 2011): prohibited (no camping, no SCV exception), restricted (SCV-only; see scv_exempts_restriction), unrestricted (no restriction; night-limit columns may still apply as a bylaw condition). Legacy values from 0179 (overnight_limited, day_visit_only) remain valid during transition -- reclassify per zone via the actual council bylaw (propose_freedom_camping_org_strategy), not by guessing. #74.';
COMMENT ON COLUMN "public"."location_zones"."boundary_status" IS 'Fence provenance: authoritative (LINZ parcel polygon, or a confirmed Google-backed polygon) or provisional (point-buffer created when no polygon was found, awaiting a human to draw the real boundary). Partial index surfaces the review queue: WHERE boundary_status = ''provisional''. Mirrors client_sites.boundary_status (0133).';
COMMENT ON COLUMN "public"."location_zones"."scv_exempts_restriction" IS 'For rule_type=restricted zones: whether holding a valid SCV certificate exempts a vehicle from the restriction (the normal Freedom Camping Act reading). Default true. #74.';

CREATE TABLE IF NOT EXISTS "public"."locations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "address" "text",
    "address_match_key" "text",
    "suburb" "text",
    "postcode" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_request_id" "uuid",
    "canonical_place_id" "uuid" NOT NULL
);
COMMENT ON TABLE "public"."locations" IS 'An organisation''s house: its link to one registry place (canonical_place_id). Site and zone facets hang off the house as siblings.';
COMMENT ON COLUMN "public"."locations"."organization_id" IS 'The CLIENT org that owns this physical place (place-axis ownership). A provider may patrol this place only when an active service_agreement authorises the cross-org link.';
COMMENT ON COLUMN "public"."locations"."name" IS 'Human-readable name for the house / location (e.g. "12 Lowburn Terrace").';
COMMENT ON COLUMN "public"."locations"."address" IS 'Full street address of the location.';
COMMENT ON COLUMN "public"."locations"."address_match_key" IS 'Normalised address key for deduplication and import matching (lowercase, stripped punctuation).';
COMMENT ON COLUMN "public"."locations"."suburb" IS 'Suburb or locality name.';
COMMENT ON COLUMN "public"."locations"."postcode" IS 'NZ postcode.';
COMMENT ON COLUMN "public"."locations"."notes" IS 'Free-text notes about the location (access instructions, hazards, etc.).';
COMMENT ON COLUMN "public"."locations"."created_by" IS 'User who created this location record.';
COMMENT ON COLUMN "public"."locations"."canonical_place_id" IS 'The registry place this house is a link to. Assigned by trigger from the address key (site) or the house id (zone).';

CREATE TABLE IF NOT EXISTS "public"."module_catalog" (
    "module_key" "text" NOT NULL,
    "base_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "per_seat_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "per_site_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "billing_period" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."module_catalog" IS 'Layer 1 (owner->provider) platform price list: owner-set base + per-seat + per-site price per module_key. No organization_id (applies to all providers; overridden per subscription in org_module_subscriptions). Which modules are sellable is defined by moduleManifest.ts (sellable:true), not here; this table carries only the price. Grand_master write; all authenticated read.';

CREATE TABLE IF NOT EXISTS "public"."module_dependencies" (
    "module_key" "text" NOT NULL,
    "depends_on_module_key" "text" NOT NULL,
    "reason" "text" NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."module_rule_sets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "name" "text" NOT NULL,
    "evidence_requirements" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "approval_policy" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "report_template_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."module_rule_sets" IS 'Operational rules per module: evidence requirements, approval policy, report templates.';

CREATE TABLE IF NOT EXISTS "public"."monthly_report_packs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
    "template_code" "text" NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "data" "jsonb",
    "pdf_path" "text",
    "generated_at" timestamp with time zone,
    "generated_by" "uuid",
    "sent_at" timestamp with time zone,
    "sent_to" "text",
    "delivery_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pdf_mime_type" "text",
    "pdf_sha256" "text",
    "pdf_renderer_version" "text"
);
COMMENT ON TABLE "public"."monthly_report_packs" IS 'Generated monthly report packs per service agreement. One row per period+template, with a JSONB data snapshot, PDF path, and delivery log. Feeds the client portal (3.3).';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_path" IS 'Private bob-uploads storage path for the generated client report pack PDF.';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_sha256" IS 'SHA-256 checksum of the generated report pack PDF bytes.';
COMMENT ON COLUMN "public"."monthly_report_packs"."pdf_renderer_version" IS 'Renderer identifier used to produce the report pack PDF.';

CREATE TABLE IF NOT EXISTS "public"."noise_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid",
    "officer_user_id" "uuid",
    "location_id" "uuid",
    "decibel_reading" real,
    "noise_source" "text",
    "prior_notice_count" integer DEFAULT 0 NOT NULL,
    "prior_notice_types" "text"[],
    "permanent_end_active" boolean DEFAULT false NOT NULL,
    "hs_flag_active" boolean DEFAULT false NOT NULL,
    "hs_notes" "text",
    "bob_recommendation" "text",
    "action_taken" "text",
    "scene_description" "text",
    "assessed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "officer_id" "uuid",
    "officer_name" "text",
    "site_id" "uuid",
    "source" "text",
    "time_of_day" time without time zone,
    "prior_notices" integer DEFAULT 0 NOT NULL,
    "action" "text",
    "notice_number" "text",
    "follow_up_required" boolean DEFAULT false NOT NULL,
    "follow_up_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "notes" "text",
    "bob_classification" "text",
    "bob_confidence" real,
    "volume_score" smallint,
    "time_score" smallint,
    "tone_score" smallint,
    "matrix_total" smallint,
    "visit_number_tonight" integer DEFAULT 1 NOT NULL,
    "is_problem_address" boolean DEFAULT false NOT NULL,
    "end_number" "text",
    "occupant_name" "text",
    "prior_end_within_72hrs" boolean DEFAULT false NOT NULL,
    "permanent_abatement_active" boolean DEFAULT false NOT NULL,
    "occupant_cooperative" boolean,
    "police_requested" boolean DEFAULT false NOT NULL,
    "police_present" boolean DEFAULT false NOT NULL,
    "received_at" timestamp with time zone,
    "arrived_at" timestamp with time zone,
    "departed_at" timestamp with time zone,
    "hs_checklist_completed" boolean DEFAULT false NOT NULL,
    "hs_checklist_items" "jsonb" DEFAULT '[]'::"jsonb",
    "hs_abort_reason" "text",
    "referred_animal_control" boolean DEFAULT false NOT NULL,
    "incident_report_text" "text",
    "complainant_protected" boolean DEFAULT true NOT NULL,
    "assessment_location" "text",
    "assessment_gps_lat" double precision,
    "assessment_gps_lng" double precision,
    "assessment_gps_accuracy" real,
    "noise_source_address" "text",
    "noise_source_gps_lat" double precision,
    "noise_source_gps_lng" double precision,
    "arrival_gps_lat" double precision,
    "arrival_gps_lng" double precision,
    "arrival_gps_accuracy" real,
    "address_discrepancy_noted" boolean DEFAULT false NOT NULL,
    "address_discrepancy_reason" "text",
    "photo_assessment_point" "jsonb" DEFAULT '[]'::"jsonb",
    "photo_source_address" "jsonb" DEFAULT '[]'::"jsonb",
    "photo_service_evidence" "jsonb" DEFAULT '[]'::"jsonb",
    "evidence_package_url" "text",
    "job_number" "text",
    "occupant_dob" "date",
    "is_large_event_or_commercial" boolean,
    "supplementary_scores" "jsonb",
    "photo_urls" "jsonb" DEFAULT '[]'::"jsonb",
    "complaint_address" "text",
    "complainant_site_id" "uuid",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "review_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "client_request_id" "uuid",
    "shift_id" "uuid",
    "source_stop_id" "uuid",
    "complainant_stop_id" "uuid",
    "assessment_distance_to_complainant_m" numeric(10,1),
    "assessment_distance_to_source_m" numeric(10,1),
    "end_expires_at" timestamp with time zone,
    "end_given_orally" boolean,
    "end_recipient_role" "text",
    "entry_notice_left" boolean
);
COMMENT ON TABLE "public"."noise_assessments" IS 'Noise control assessments. 6-step workflow: attend, identify, measure, history, action, follow-up.';
COMMENT ON COLUMN "public"."noise_assessments"."dispatch_job_id" IS 'FK to dispatch_jobs when this noise job was created via dispatch integration. Null for standalone jobs.';
COMMENT ON COLUMN "public"."noise_assessments"."site_id" IS 'FK to client_sites — anchored to the NOISE SOURCE property (the offending address). Owner rule (#157): repeat-offender counts, problem-address flags, prior-END-within-72hrs all key off this site. Never the complainant''s address.';
COMMENT ON COLUMN "public"."noise_assessments"."bob_classification" IS 'Bob AI classification result for noise source identification from photo evidence';
COMMENT ON COLUMN "public"."noise_assessments"."bob_confidence" IS 'Bob AI confidence score (0-100) for the classification result';
COMMENT ON COLUMN "public"."noise_assessments"."volume_score" IS 'TDC matrix: 0=No Noise, 1=Barely Audible, 2=Clearly Audible, 3=Loud, 4=Extremely Loud';
COMMENT ON COLUMN "public"."noise_assessments"."time_score" IS 'TDC matrix: 1=7am-9pm, 2=9pm-midnight, 3=midnight-2am, 4=2am-7am. Ignored when volume_score=0.';
COMMENT ON COLUMN "public"."noise_assessments"."tone_score" IS 'TDC matrix: 0=No bass, 1=Slight bass, 2=Heavy bass';
COMMENT ON COLUMN "public"."noise_assessments"."matrix_total" IS 'TDC matrix total: volume+time+tone (time ignored when volume=0). 0=no action, 1-4=acceptable, 5+=excessive.';
COMMENT ON COLUMN "public"."noise_assessments"."end_number" IS 'Excessive Noise Direction number. Required on incident report when END issued.';
COMMENT ON COLUMN "public"."noise_assessments"."occupant_name" IS 'Name of occupant served with END. Required on incident report.';
COMMENT ON COLUMN "public"."noise_assessments"."prior_end_within_72hrs" IS 'END issued at this address within last 72 hours — triggers equipment seizure authority.';
COMMENT ON COLUMN "public"."noise_assessments"."permanent_abatement_active" IS 'Permanent Abatement Notice in effect at this address — triggers equipment seizure authority.';
COMMENT ON COLUMN "public"."noise_assessments"."hs_checklist_completed" IS 'Officer confirmed H&S pre-visit checklist before attending. Required gate.';
COMMENT ON COLUMN "public"."noise_assessments"."complainant_protected" IS 'Complainant identity must never be disclosed to the offending address. Always true.';
COMMENT ON COLUMN "public"."noise_assessments"."assessment_location" IS 'Where the officer stood to conduct the assessment. May differ from complaint address.';
COMMENT ON COLUMN "public"."noise_assessments"."noise_source_address" IS 'The actual property producing the noise (text). May differ from complaint_address. The site_id FK anchors to this address. #159.';
COMMENT ON COLUMN "public"."noise_assessments"."arrival_gps_lat" IS 'GPS coordinates logged automatically when officer starts the job. Proves officer location.';
COMMENT ON COLUMN "public"."noise_assessments"."address_discrepancy_noted" IS 'True when noise_source_address differs from complaint address. Officer must record reason.';
COMMENT ON COLUMN "public"."noise_assessments"."photo_assessment_point" IS 'Mandatory photo(s) showing where officer stood and street context.';
COMMENT ON COLUMN "public"."noise_assessments"."photo_source_address" IS 'Mandatory photo(s) of source address letterbox/number before END can be finalised.';
COMMENT ON COLUMN "public"."noise_assessments"."photo_service_evidence" IS 'Photo of notice location or person served (where policy permits).';
COMMENT ON COLUMN "public"."noise_assessments"."job_number" IS 'Human-readable job number, e.g. NC-2026-001245. Auto-generated on job creation.';
COMMENT ON COLUMN "public"."noise_assessments"."occupant_dob" IS 'Date of birth of the person served. Only captured when org config (noise_module_config.require_occupant_dob) is enabled.';
COMMENT ON COLUMN "public"."noise_assessments"."is_large_event_or_commercial" IS 'Whether this assessment is for a large event or commercial premises. Only captured when org config enables it.';
COMMENT ON COLUMN "public"."noise_assessments"."supplementary_scores" IS 'Supplementary factor scores for this assessment (e.g. { day_of_week: 2, duration: 1 }). Null when org uses TDC-only.';
COMMENT ON COLUMN "public"."noise_assessments"."photo_urls" IS 'Array of photo storage paths with metadata: [{"id": "...", "name": "...", "storage_path": "...", "uploaded_at": "...", "metadata": {"gps_latitude": 0, "gps_longitude": 0, "gps_accuracy": 0, "address": "...", "zone": "...", "officer_id": "...", "officer_name": "..."}}]';
COMMENT ON COLUMN "public"."noise_assessments"."complaint_address" IS 'The complainant''s address (where the complaint originates). Distinct from noise_source_address (the offending property). Searchable. #159.';
COMMENT ON COLUMN "public"."noise_assessments"."complainant_site_id" IS 'Optional FK to client_sites for the complainant''s property. Allows linking complaints to known sites for pattern detection (e.g. vexatious complaints from the same address). #159.';
COMMENT ON COLUMN "public"."noise_assessments"."external_refs" IS 'Generic external system reference IDs. E.g. {"wilsar": {"dispatch_id": "54011208", "docket": "54011208", "imported_historic": true}}';
COMMENT ON COLUMN "public"."noise_assessments"."assessment_distance_to_complainant_m" IS 'Server-computed distance from the assessment GPS to the complainant place. The report states the position without the address (s326: judged as it affects a person other than one at the emitting place).';
COMMENT ON COLUMN "public"."noise_assessments"."end_expires_at" IS 'assessed_at + noise_module_config.end_validity_hours when an END was given (s327(3)).';
COMMENT ON COLUMN "public"."noise_assessments"."entry_notice_left" IS 's328(5): copy of the written END and the entry notice left in a prominent position when the place was unoccupied.';

CREATE TABLE IF NOT EXISTS "public"."noise_module_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "volume_bands" "jsonb",
    "time_bands" "jsonb",
    "tone_bands" "jsonb",
    "excessive_threshold" smallint DEFAULT 5 NOT NULL,
    "supplementary_factors" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "supplementary_factor_config" "jsonb" DEFAULT '{}'::"jsonb",
    "permanent_abatement_list" "jsonb" DEFAULT '[]'::"jsonb",
    "legislative_text" "text" DEFAULT 'Resource Management Act 1991 s.326 (Abatement Notice) / s.327 (Seizure of Noise Source)'::"text",
    "require_occupant_dob" boolean DEFAULT false NOT NULL,
    "require_large_event_flag" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "skip_verbal_warning" boolean DEFAULT false NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_current" boolean DEFAULT true NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "effective_to" "date",
    "source_document_url" "text",
    "created_by" "uuid",
    "end_validity_hours" smallint DEFAULT 192 NOT NULL
);
COMMENT ON TABLE "public"."noise_module_config" IS 'Per-org noise control module configuration: matrix band definitions, supplementary factors, excessive threshold, permanent abatement list, and legislative text override. Issue #94.';
COMMENT ON COLUMN "public"."noise_module_config"."excessive_threshold" IS 'Organization triage threshold for the configurable volume/time/tone matrix. It is not a replacement for the RMA 1991 s.326 enforcement-officer opinion that noise is excessive.';
COMMENT ON COLUMN "public"."noise_module_config"."supplementary_factors" IS 'Array of well-known supplementary factor type keys enabled for this org (e.g. day_of_week, duration, location_type). Combines with the base TDC score, does not replace it.';
COMMENT ON COLUMN "public"."noise_module_config"."permanent_abatement_list" IS 'Admin-managed list of addresses with permanent abatement notices. Replaces the static PDF. Each entry: { address, site_id, notes, added_at, added_by }.';
COMMENT ON COLUMN "public"."noise_module_config"."legislative_text" IS 'Organization document wording/reference. Default cites RMA 1991 ss.326-328; verify current wording against official legislation before issuing a notice.';
COMMENT ON COLUMN "public"."noise_module_config"."skip_verbal_warning" IS 'When true, the TDC matrix skips the verbal warning step and issues an END (Excessive Noise Direction) on the first excessive noise finding. Issue #105.';
COMMENT ON COLUMN "public"."noise_module_config"."end_validity_hours" IS 'Period an excessive noise direction binds. RMA s327(3) (amended 21 Aug 2025): 8 days (192 h) or such shorter period as the officer specifies. Councils may configure shorter; never longer.';

CREATE TABLE IF NOT EXISTS "public"."noise_seizures" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "noise_assessment_id" "uuid" NOT NULL,
    "notice_id" "uuid",
    "item_description" "text" NOT NULL,
    "make" "text",
    "model" "text",
    "serial_number" "text",
    "evidence_id" "uuid",
    "storage_location" "text",
    "seized_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "returned_at" timestamp with time zone,
    "police_present" boolean DEFAULT false NOT NULL,
    "police_name" "text",
    "photo_urls" "jsonb" DEFAULT '[]'::"jsonb",
    "seizure_form_number" "text",
    "legal_authority" "text" DEFAULT 'RMA 1991 s.327'::"text"
);
COMMENT ON TABLE "public"."noise_seizures" IS 'Equipment seized under noise Enforcement Notices (RMA s.327). Requires police presence. Each item individually recorded with photo evidence and seizure form number.';
COMMENT ON COLUMN "public"."noise_seizures"."police_present" IS 'Police must be present for any equipment seizure or property entry. Mandatory.';
COMMENT ON COLUMN "public"."noise_seizures"."legal_authority" IS 'Legislative authority for seizure. Default: RMA 1991 s.327.';

CREATE TABLE IF NOT EXISTS "public"."notice_counters" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "notice_type" "text" NOT NULL,
    "prefix" "text" NOT NULL,
    "last_number" integer DEFAULT 0 NOT NULL
);
COMMENT ON TABLE "public"."notice_counters" IS 'Atomic sequential notice number generation per org and notice type.';

CREATE TABLE IF NOT EXISTS "public"."notice_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "notice_type" "text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "issuing_authority" "text",
    "authorising_act" "text" DEFAULT 'Freedom Camping Act 2011'::"text" NOT NULL,
    "authorising_section" "text",
    "bylaw_reference" "text",
    "body_html" "text" DEFAULT ''::"text" NOT NULL,
    "fine_amount" numeric(10,2),
    "payment_url" "text",
    "payment_deadline_days" integer DEFAULT 28 NOT NULL,
    "objections_email" "text",
    "objections_address" "text",
    "objections_deadline_days" integer DEFAULT 28 NOT NULL,
    "vacate_by_hour" integer DEFAULT 7 NOT NULL,
    "vacate_by_minute" integer DEFAULT 0 NOT NULL,
    "logo_url" "text",
    "footer_text" "text",
    "source_document_url" "text",
    "bob_extracted" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "module_key" "text" DEFAULT 'freedom_camping'::"text" NOT NULL
);
COMMENT ON TABLE "public"."notice_templates" IS 'Per-council, per-notice-type reusable notice templates. Councils upload a sample; Bob extracts and proposes; admins edit manually. Versioned; is_active=true row is authoritative. Variables use {{placeholder}} syntax. #77.';
COMMENT ON COLUMN "public"."notice_templates"."notice_type" IS 'Notice type: written_warning, notice_to_vacate, infringement (FC), end (Excessive Noise Direction), seizure (equipment seizure). Extended in 0218 for noise control (#60).';
COMMENT ON COLUMN "public"."notice_templates"."module_key" IS 'Enforcement module this template belongs to. A single organization can hold one active template per (module_key, notice_type) pair -- e.g. NCC freedom_camping infringement wording differs from NCC parking_enforcement infringement wording.';

CREATE TABLE IF NOT EXISTS "public"."notices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "breach_id" "uuid",
    "vehicle_id" "uuid",
    "person_id" "uuid",
    "location_id" "uuid",
    "officer_user_id" "uuid",
    "notice_type" "text" NOT NULL,
    "notice_number" "text",
    "legal_basis" "text",
    "fine_amount" numeric(10,2),
    "comply_by" timestamp with time zone,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "authorized_by" "text",
    "authorized_at" timestamp with time zone,
    "issued_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."notices" IS 'All notice types: warning, infringement, NTV, abatement, direction, enforcement, biosecurity, smoke.';

CREATE TABLE IF NOT EXISTS "public"."notices_to_vacate" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "observation_id" "uuid",
    "breach_alert_id" "uuid",
    "zone_id" "uuid",
    "plate_number" "text" NOT NULL,
    "vacate_by" timestamp with time zone,
    "reason" "text",
    "authorising_act" "text" DEFAULT 'Freedom Camping Act 2011'::"text" NOT NULL,
    "authorising_section" "text" DEFAULT 's.16'::"text" NOT NULL,
    "issued_by" "uuid" NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pdf_url" "text",
    "pdf_generated_at" timestamp with time zone,
    "status" "text" DEFAULT 'issued'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."notices_to_vacate" IS 'Issued Notice to Vacate documents. Step 3 in the enforcement ladder.';

CREATE TABLE IF NOT EXISTS "public"."notifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "recipient_user_id" "uuid",
    "recipient_role" "text",
