COMMENT ON TABLE "public"."officer_field_reports" IS 'Officer field evidence. Authenticated creation and review are owned by governed RPCs; direct client mutations are revoked.';
COMMENT ON COLUMN "public"."officer_field_reports"."address" IS 'Physical address of the report. Complements existing gps_lat/lng + location_name + site_id so every report is fully location-anchored.';

CREATE TABLE IF NOT EXISTS "public"."officer_gps_log" (
