    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."org_geofence_config" IS 'Per-org geofence configuration (Q8 ruling). Keys: site_provisional_radius_m (default 50), zone_provisional_radius_m (default 100), checkpoint_radius_m (default 5). Optional zone_type for per-zone-type overrides.';

CREATE TABLE IF NOT EXISTS "public"."org_module_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "base_price" numeric(12,2),
    "per_seat_price" numeric(12,2),
    "per_site_price" numeric(12,2),
    "discount_pct" numeric(5,2) DEFAULT 0 NOT NULL,
    "billing_period" "text",
    "currency" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "started_at" "date" DEFAULT CURRENT_DATE NOT NULL,
    "ended_at" "date",
    "effective_from" "date",
    "effective_to" "date",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid"
);
COMMENT ON TABLE "public"."org_module_subscriptions" IS 'Layer 1 (owner->provider) subscription lines: what each provider org is actually charged per module (per-provider price overrides + discount applied after the resolved price, else inherits module_catalog). effective_from/to version price changes. Aligned to organization_modules enablement. Grand_master write; provider reads its own.';

CREATE TABLE IF NOT EXISTS "public"."org_printer_settings" (
    "organization_id" "uuid" NOT NULL,
    "paper_width" "text" DEFAULT '58mm'::"text" NOT NULL,
    "connection_type" "text" DEFAULT 'browser_print'::"text" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid"
);
COMMENT ON TABLE "public"."org_printer_settings" IS 'One row per organization: preferred paper width and connection path for printing module notices/infringements.';

CREATE TABLE IF NOT EXISTS "public"."org_rate_settings" (
    "organization_id" "uuid" NOT NULL,
    "gst_rate" numeric DEFAULT 0.15 NOT NULL,
    "invoice_prefix" "text" DEFAULT 'INV'::"text" NOT NULL,
    "payment_terms_days" integer DEFAULT 20 NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "pay_policy" "text" DEFAULT 'max_of_both'::"text" NOT NULL,
    "overtime_multiplier" numeric DEFAULT 1.5 NOT NULL,
    "double_multiplier" numeric DEFAULT 2.0 NOT NULL,
    "target_margin_pct" numeric DEFAULT 0 NOT NULL,
    "rounding" "text" DEFAULT 'cent'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "default_platform_fee_treatment" "text" DEFAULT 'passthrough'::"text" NOT NULL
);
COMMENT ON COLUMN "public"."org_rate_settings"."default_platform_fee_treatment" IS 'B6 (#2): default platform_fee_treatment applied to NEW Layer 2 quotes for this provider. passthrough (default) | passthrough_marked_up | absorb. Per-quote value still overridable on the quote.';

CREATE TABLE IF NOT EXISTS "public"."organization_brand_assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "asset_kind" "text" NOT NULL,
    "variant" "text" DEFAULT 'default'::"text" NOT NULL,
