CREATE TABLE IF NOT EXISTS "public"."quotes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_org_id" "uuid" NOT NULL,
    "client_org_id" "uuid",
    "client_name" "text",
    "title" "text" DEFAULT 'Service quote'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "target_margin_pct" numeric(5,2) DEFAULT 0 NOT NULL,
    "discount_pct" numeric(5,2) DEFAULT 0 NOT NULL,
    "gst_rate" numeric(5,4) DEFAULT 0.15 NOT NULL,
    "platform_fee_treatment" "text" DEFAULT 'passthrough'::"text" NOT NULL,
    "total_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "subtotal_charge" numeric(12,2) DEFAULT 0 NOT NULL,
    "discount_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "gst_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "total_charge" numeric(12,2) DEFAULT 0 NOT NULL,
    "valid_until" "date",
    "notes" "text",
    "accepted_at" timestamp with time zone,
    "accepted_by" "uuid",
    "service_agreement_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "client_request_id" "uuid",
    "tender_id" "uuid",
    "discount_schedule_id" "uuid"
);
COMMENT ON TABLE "public"."quotes" IS 'Layer 2 (provider->client) quote/proposal. Cost-vs-charge with target margin + client discount; platform_fee_treatment controls how the Layer-1 platform module fee surfaces (default passthrough = own client line at cost). On accept (B5) it writes crm_commercial_settings + site_financial_config and links a service_agreement. Provider-scoped RLS + grand_master.';

