    "row_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."scv_import_rows" IS 'Per-row staging and validation result for canonical SCV CSV imports.';

CREATE TABLE IF NOT EXISTS "public"."service_agreement_continuity_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_location_id" "uuid" NOT NULL,
    "service_agreement_module_id" "uuid" NOT NULL,
    "continuity_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "client_coverage_start" time without time zone,
    "client_coverage_end" time without time zone,
    "provider_coverage_start" time without time zone,
    "provider_coverage_end" time without time zone,
    "share_active_cases" boolean DEFAULT false NOT NULL,
    "share_open_tasks" boolean DEFAULT false NOT NULL,
    "share_recent_history_hours" integer DEFAULT 24 NOT NULL,
    "share_attachments_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "share_presence_mode" "text" DEFAULT 'none'::"text" NOT NULL,
    "require_handoff_ack" boolean DEFAULT true NOT NULL,
    "continuity_retention_hours" integer DEFAULT 24 NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."service_agreement_delivery_schedules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "service_agreement_id" "uuid" NOT NULL,
