    "client_request_id" "uuid" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_breaks" IS 'Rest and meal breaks taken during a shift. Rest breaks are paid, meal breaks unpaid, per Employment Relations Act 1990 Part 6D.';

CREATE TABLE IF NOT EXISTS "public"."shift_coverage_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_template_id" "uuid",
    "shift_date" "date" NOT NULL,
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "site_id" "uuid",
    "patrol_route_id" "uuid",
    "required_staff_count" integer DEFAULT 1 NOT NULL,
    "required_credentials" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "urgency" "text" DEFAULT 'normal'::"text" NOT NULL,
    "claimed_by" "uuid",
    "claimed_at" timestamp with time zone,
    "filled_at" timestamp with time zone,
    "notes" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "roster_slot_id" "uuid"
);
COMMENT ON TABLE "public"."shift_coverage_requests" IS 'Open shifts needing coverage. Staff can claim these. Supports credential-aware matching.';

CREATE TABLE IF NOT EXISTS "public"."shift_debriefs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "client_event_id" "uuid" NOT NULL,
    "summary" "text" NOT NULL,
    "safety_incident_reported" boolean DEFAULT false NOT NULL,
    "equipment_issue_reported" boolean DEFAULT false NOT NULL,
    "follow_up_required" boolean DEFAULT false NOT NULL,
    "follow_up_notes" "text",
    "submitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_debriefs" IS 'Append-only officer handover submitted after operational work. Shift completion remains a separate lifecycle truth.';

CREATE TABLE IF NOT EXISTS "public"."shift_stop_actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_stop_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "action_type" "text" NOT NULL,
    "result_record_id" "uuid",
    "result_table" "text",
    "outcome" "text",
    "notes" "text",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "performed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shift_stop_module_id" "uuid",
    "client_request_id" "uuid",
    "gps_accuracy_metres" double precision,
    "evidence_metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "receipt" "jsonb"
);
COMMENT ON TABLE "public"."shift_stop_actions" IS 'Module-specific actions completed at each shift stop. Audit trail for vehicle scans, checkpoints, evidence, and other field actions.';
COMMENT ON COLUMN "public"."shift_stop_actions"."shift_stop_module_id" IS 'Optional link to the specific module task this action belongs to (unified stop model, !709). Null = a stop-level event (e.g. arrival GPS); set = a module-level event (e.g. an FC inspection outcome).';

CREATE TABLE IF NOT EXISTS "public"."shift_stop_modules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_stop_id" "uuid" NOT NULL,
    "module_key" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "outcome" "text",
    "result_record_id" "uuid",
    "result_table" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "service_agreement_module_id" "uuid",
    "service_agreement_location_id" "uuid"
);
COMMENT ON TABLE "public"."shift_stop_modules" IS 'Run-time module task for a shift stop (unified stop model, !709). One attendance (shift_stop) can have N module tasks, each with its own completion/outcome. Attendance KPIs (shift_stops) and module-outcome KPIs (this table) are cleanly separable.';
COMMENT ON COLUMN "public"."shift_stop_modules"."service_agreement_module_id" IS 'The authorising service_agreement_module for this run-time module attendance. Inherited from patrol_route_stop_modules at shift generation (generate_shift_stops). Nullable for back-compat. Exactly ONE authorising contract per attendance. Owner ruling 2026-08-15: contract attribution at MODULE grain, #328.';
COMMENT ON COLUMN "public"."shift_stop_modules"."service_agreement_location_id" IS 'The authorising service_agreement_location (place-contract) for this run-time module. Inherited from patrol_route_stop_modules at shift generation. Nullable for back-compat.';

CREATE TABLE IF NOT EXISTS "public"."shift_stops" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "patrol_config_id" "uuid",
    "site_id" "uuid",
    "zone_id" "uuid",
    "module_key" "text" NOT NULL,
    "stop_order" integer DEFAULT 0 NOT NULL,
    "visit_number" integer DEFAULT 1 NOT NULL,
    "is_adhoc" boolean DEFAULT false NOT NULL,
    "dispatch_job_id" "uuid",
    "sla_window_open" timestamp with time zone,
    "sla_arrive_by" timestamp with time zone NOT NULL,
    "sla_depart_by" timestamp with time zone,
    "required_dwell_minutes" integer DEFAULT 15 NOT NULL,
    "estimated_arrival_at" timestamp with time zone,
    "estimated_departure_at" timestamp with time zone,
    "travel_distance_metres" integer,
    "travel_time_seconds" integer,
    "sla_status" "text" DEFAULT 'on_track'::"text" NOT NULL,
    "actual_arrived_at" timestamp with time zone,
    "actual_departed_at" timestamp with time zone,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "officer_notes" "text",
    "arrived_gps_lat" double precision,
    "arrived_gps_lng" double precision,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "external_dispatch_id" "text",
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "place_role" "text" DEFAULT 'work_place'::"text" NOT NULL,
    "arrived_gps_accuracy" double precision,
    "arrival_verification" "text",
    "arrival_distance_m" numeric(10,1),
    "departed_gps_lat" double precision,
    "departed_gps_lng" double precision,
    "bwc_reference" "text",
    "officer_instructions" "text"
);
COMMENT ON TABLE "public"."shift_stops" IS 'Materialised stop list per shift. Generated from client_site_patrol_config when shift is published. SLA windows locked at generation. Updated live by the patrol engine.';
COMMENT ON COLUMN "public"."shift_stops"."zone_id" IS 'The zone attended at this stop, when the stop is a ZONE rather than a SITE (unified stop model, !709). Exactly one of site_id / zone_id is set (shift_stops_place_xor).';
COMMENT ON COLUMN "public"."shift_stops"."external_dispatch_id" IS 'External dispatch/job ID from the source billing system (e.g. Wilsar Internal DespatchId: 59199448). Used for per-visit billing reconciliation.';
COMMENT ON COLUMN "public"."shift_stops"."external_refs" IS 'Generic external system reference IDs for this patrol visit. E.g. {"wilsar": {"dispatch_id": "59199448", "client_id": "NCC200", "visit_charge_exgst": "6.05", "status": "Completed"}}';
COMMENT ON COLUMN "public"."shift_stops"."place_role" IS 'work_place = the place the job is done at (noise source); harmed_party_place = the complainant / protected place. One ad-hoc stop per place attended, per visit.';
COMMENT ON COLUMN "public"."shift_stops"."arrival_verification" IS 'Server-computed geofence result at arrival. Loud, never blocking: verified_on_site | near_site | off_site | unverified_boundary | no_geofence | no_gps.';
COMMENT ON COLUMN "public"."shift_stops"."bwc_reference" IS 'Body-worn camera recording reference spoken/logged at arrival (job number, type, address).';
COMMENT ON COLUMN "public"."shift_stops"."officer_instructions" IS 'Instruction for the officer at this stop, copied from client_site_patrol_config at generation (quote schedule -> patrol config -> stop).';

CREATE TABLE IF NOT EXISTS "public"."shift_swaps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "original_shift_id" "uuid" NOT NULL,
    "original_staff_id" "uuid" NOT NULL,
    "swap_with_staff_id" "uuid",
    "swap_type" "text" DEFAULT 'direct'::"text" NOT NULL,
    "reason" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "declined_reason" "text",
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_swaps" IS 'Shift swap requests. Direct swaps, open coverage, or urgent coverage requests. Requires admin approval.';

CREATE TABLE IF NOT EXISTS "public"."shift_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "shift_type" "text" NOT NULL,
    "start_time" time without time zone NOT NULL,
    "end_time" time without time zone NOT NULL,
    "recurrence_type" "text" DEFAULT 'weekly'::"text" NOT NULL,
