    "required_staff_count" integer DEFAULT 1 NOT NULL,
    "site_id" "uuid",
    "patrol_route_id" "uuid",
    "required_credentials" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "effective_from" "date",
    "effective_to" "date",
    "color" "text" DEFAULT '#D32F2F'::"text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."shift_templates" IS 'Recurring shift patterns. Used to generate actual shifts with coverage requirements and credential validation.';

CREATE TABLE IF NOT EXISTS "public"."shifts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "officer_user_id" "uuid" NOT NULL,
    "service_type" "text" NOT NULL,
    "location_id" "uuid",
    "zone_id" "uuid",
    "scheduled_start" timestamp with time zone NOT NULL,
    "scheduled_end" timestamp with time zone NOT NULL,
    "actual_start" timestamp with time zone,
    "actual_end" timestamp with time zone,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "patrol_route_id" "uuid",
    "generated_at" timestamp with time zone,
    "shift_health" "text",
    "osrm_matrix_cached_at" timestamp with time zone,
    "total_stops" integer DEFAULT 0 NOT NULL,
    "completed_stops" integer DEFAULT 0 NOT NULL,
    "external_refs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "roster_slot_id" "uuid",
    "service_agreement_location_id" "uuid",
    "service_agreement_module_id" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "work_unit_id" "uuid",
    "module_key" "text",
    "shift_origin" "text" DEFAULT 'rostered'::"text" NOT NULL
);
COMMENT ON TABLE "public"."shifts" IS 'Officer shift records. Links officer, service type, location, and roster status.';
COMMENT ON COLUMN "public"."shifts"."patrol_route_id" IS 'Optional named patrol route/run assigned to this shift. Used for mobile patrols covering multiple sites/zones.';
COMMENT ON COLUMN "public"."shifts"."external_refs" IS 'Generic external system reference IDs. E.g. {"deputy": {"timesheet_id": "59199448"}}';
COMMENT ON COLUMN "public"."shifts"."updated_at" IS 'Timestamp when the shift record was last updated.';

CREATE TABLE IF NOT EXISTS "public"."site_financial_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "site_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid",
    "billing_model" "text" DEFAULT 'hourly'::"text" NOT NULL,
