);
COMMENT ON TABLE "public"."site_services" IS 'Per-place service selection: which modules are active at a Site (site_id) XOR Zone (zone_id). Composes with organization_modules (org bought it) + access profiles (user may touch it).';

CREATE TABLE IF NOT EXISTS "public"."sla_clocks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_agreement_id" "uuid",
    "obligation_id" "uuid",
    "dispatch_job_id" "uuid",
    "alarm_event_id" "uuid",
    "site_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "target_minutes" integer,
    "arrived_at" timestamp with time zone,
    "elapsed_minutes" integer,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."sla_clocks" IS 'SLA response clocks. One per dispatch/alarm event: started_at -> arrived_at, verdict met/breached vs target_minutes. Feeds the obligation dashboard + report packs.';

CREATE TABLE IF NOT EXISTS "public"."sla_discount_bands" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_type" "text",
    "over_by_minutes_min" integer NOT NULL,
    "over_by_minutes_max" integer,
    "discount_pct" numeric NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."sla_discount_bands" IS 'Per-org SLA discount bands. over_by_minutes range -> discount_pct. A 100% band (discount_pct=1) = non-billable cutoff. service_type NULL = wildcard (all service types). Epic #226, Phase E billing refinement.';

CREATE TABLE IF NOT EXISTS "public"."smoke_assessment_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "smoke_assessment_id" "uuid" NOT NULL,
    "evidence_item_id" "uuid" NOT NULL,
    "ordinal" integer DEFAULT 0 NOT NULL,
    "purpose" "text" DEFAULT 'primary_evidence'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."smoke_assessment_evidence" IS 'Explicit junction table linking smoke complaint assessments to canonical evidence_items.';

CREATE TABLE IF NOT EXISTS "public"."smoke_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "dispatch_job_id" "uuid",
    "officer_user_id" "uuid",
    "location_id" "uuid",
    "complaint_source" "text",
    "smoke_source_type" "text",
    "checklist" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "bob_recommendation" "text",
    "action_taken" "text",
    "is_out_of_hours" boolean DEFAULT false NOT NULL,
    "scene_description" "text",
    "assessed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "officer_id" "uuid",
    "officer_name" "text",
    "site_id" "uuid",
    "smoke_source" "text",
    "source_confirmed" boolean DEFAULT false NOT NULL,
    "bob_classification" "text",
    "bob_confidence" real,
    "severity" "text",
    "action" "text",
    "notice_number" "text",
    "legal_basis" "text" DEFAULT 'RMA s.17A'::"text",
    "follow_up_required" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "notes" "text",
    "photo_urls" "jsonb" DEFAULT '[]'::"jsonb",
    "address" "text",
    "complaint_address" "text",
    "complainant_site_id" "uuid",
    "client_request_id" "uuid",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "gps_accuracy" double precision,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "review_notes" "text",
    "smoke_ai_analysis" "jsonb",
    "smoke_ai_analyzed_at" timestamp with time zone,
    "evidence_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "review_state" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "shift_id" "uuid"
);
COMMENT ON TABLE "public"."smoke_assessments" IS 'Smoke complaint assessments. 6-step workflow with Bob AI source classification and abatement notices.';
COMMENT ON COLUMN "public"."smoke_assessments"."photo_urls" IS 'Array of photo storage paths with metadata: [{"id": "...", "name": "...", "storage_path": "...", "uploaded_at": "...", "metadata": {"gps_latitude": 0, "gps_longitude": 0, "gps_accuracy": 0, "address": "...", "zone": "...", "officer_id": "...", "officer_name": "..."}}]';
COMMENT ON COLUMN "public"."smoke_assessments"."address" IS 'Free-text complaint address entered by the officer. Added in 0236 — the SmokeControlPage UI was built against this column but it never existed live (same drift class as photo_urls/0033).';
COMMENT ON COLUMN "public"."smoke_assessments"."complaint_address" IS 'The harmed/protected party''s address (where the affected party is located). Distinct from the source-side address column (the property producing the smoke). complaint_source is classification text (e.g. "neighbour"), NOT this anchor. Write-contract slice 1; mirrors noise_assessments.complaint_address (0238).';
COMMENT ON COLUMN "public"."smoke_assessments"."complainant_site_id" IS 'Optional FK to client_sites for the harmed/protected party''s property. Distinct from site_id (the smoke SOURCE property). complaint_source is classification text, NOT this anchor. Enables pattern detection (e.g. repeat complaints from the same address). Write-contract slice 1; mirrors noise_assessments.complainant_site_id (0238).';
COMMENT ON COLUMN "public"."smoke_assessments"."shift_id" IS 'Shift the assessment was made on (submit_smoke_assessment_receipt); mirrors noise_assessments.shift_id.';

CREATE TABLE IF NOT EXISTS "public"."staff_area_grants" (
