CREATE TABLE IF NOT EXISTS "public"."staff_skills" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "skill_name" "text" NOT NULL,
    "skill_category" "text",
    "proficiency_level" "text",
    "certified" boolean DEFAULT false NOT NULL,
    "certification_expiry" "date",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "skill_id" "uuid"
);
COMMENT ON TABLE "public"."staff_skills" IS 'Skills and qualifications per staff member. Used for roster matching and site coverage planning.';

CREATE TABLE IF NOT EXISTS "public"."staff_training_records" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "staff_id" "uuid",
    "officer_id" "uuid",
    "training_name" "text" NOT NULL,
    "training_type" "text" DEFAULT 'internal'::"text" NOT NULL,
    "provider" "text",
    "completed_date" "date" NOT NULL,
    "expiry_date" "date",
    "passed" boolean,
    "score" numeric,
    "notes" "text",
    "recorded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."task_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "basis" "text" NOT NULL,
    "observation_id" "uuid",
    "noise_assessment_id" "uuid",
    "smoke_assessment_id" "uuid",
    "biosecurity_assessment_id" "uuid",
    "incident_id" "uuid",
    "notice_id" "uuid",
    "enforcement_case_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ended_at" timestamp with time zone,
    "end_reason" "text",
    "granted_by" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."task_assignments" IS 'Situational-entitlement substrate for user_has_task_entitlement (ACCESS_MODEL.md). Logged, time-bounded task-basis records for the signals not on existing columns: direct_module_initiation (claim), backup_attachment, and universal follow_up_ownership. A live basis has ended_at IS NULL; expired rows are retained for audit. Grants ACCESS basis only -- never touches the underlying record. Polymorphic record ref via typed nullable FKs (one-of); extend as the re-anchor worklist grows.';

CREATE TABLE IF NOT EXISTS "public"."team_members" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "team_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role_in_team" "text" DEFAULT 'member'::"text" NOT NULL,
    "joined_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "left_at" timestamp with time zone,
    "added_by" "uuid"
);
COMMENT ON TABLE "public"."team_members" IS 'Membership in teams. UNIQUE(team_id, user_id). left_at NULL = active member. #224.';

CREATE TABLE IF NOT EXISTS "public"."teams" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "team_lead_user_id" "uuid",
    "scope_org_id" "uuid",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."teams" IS 'Named user groups with a team lead. scope_org_id NULL = org-wide team (Q6). Team lead is NOT auto the line manager (Q1). #224.';

CREATE TABLE IF NOT EXISTS "public"."tender_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tender_id" "uuid" NOT NULL,
    "document_name" "text" NOT NULL,
    "document_type" "text",
    "storage_path" "text" NOT NULL,
    "uploaded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."tender_documents" IS 'Document attachments for tenders.';

CREATE TABLE IF NOT EXISTS "public"."tenders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "client_organization_id" "uuid",
    "title" "text" NOT NULL,
    "service_type" "text",
    "estimated_value" numeric(12,2),
    "currency" "text" DEFAULT 'NZD'::"text" NOT NULL,
    "due_date" "date",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "lead_author_id" "uuid",
