);
COMMENT ON TABLE "public"."tenders" IS 'Tender/proposal workspace. Master role only per instruction manual.';

CREATE TABLE IF NOT EXISTS "public"."timesheet_work_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "timesheet_id" "uuid" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "work_status" "text" NOT NULL,
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "calculated_minutes" integer DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);

CREATE TABLE IF NOT EXISTS "public"."timesheets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "staff_id" "uuid" NOT NULL,
    "shift_id" "uuid",
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "scheduled_hours" numeric(6,2),
    "actual_hours" numeric(6,2),
    "overtime_hours" numeric(6,2) DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_at" timestamp with time zone,
    "payroll_export_batch_id" "uuid",
    "client_event_id" "uuid",
    "review_notes" "text",
    "work_derived_hours" numeric(6,2),
    "adjustment_hours" numeric(6,2) DEFAULT 0 NOT NULL,
    "work_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "branch_reviewed_by" "uuid",
    "branch_reviewed_at" timestamp with time zone,
    "branch_review_notes" "text",
    "branch_reviewed_organization_id" "uuid"
);
COMMENT ON TABLE "public"."timesheets" IS 'Timesheet records per staff member per period. Feeds into invoicing and payroll export.';

CREATE TABLE IF NOT EXISTS "public"."travel_allowances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "callout_shift_id" "uuid",
    "officer_user_id" "uuid" NOT NULL,
    "journey_type" "text" NOT NULL,
    "distance_km" numeric(8,2),
    "duration_minutes" integer,
    "rate_per_km" numeric(6,4),
    "time_rate" numeric(10,2),
    "outside_jurisdiction" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."travel_allowances" IS 'Travel reimbursement per callout. Calculated from officer registered office location.';

CREATE TABLE IF NOT EXISTS "public"."user_management_audit" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "target_user_id" "uuid" NOT NULL,
    "action_type" "text" NOT NULL,
    "performed_by" "uuid" NOT NULL,
    "old_value" "jsonb",
    "new_value" "jsonb",
    "metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."user_management_audit" IS 'Audit trail for user management actions (invites, deactivations, role changes)';
COMMENT ON COLUMN "public"."user_management_audit"."action_type" IS 'Type of action: user_invited, user_activated, role_changed, display_name_changed, user_deactivated, user_reactivated, invite_resent';
COMMENT ON COLUMN "public"."user_management_audit"."metadata" IS 'Additional context such as deactivation reason';

CREATE TABLE IF NOT EXISTS "public"."user_profiles" (
    "id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "display_name" "text",
    "authorized_organization_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deactivated_at" timestamp with time zone,
    "deactivated_by" "uuid",
    "email" "text",
    "phone" "text",
    "address" "text",
    "photo_url" "text",
    "module_access" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "employer_organization_id" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."user_profiles" IS 'Application profile mapped to auth.users. RLS helper functions read this table.';
COMMENT ON COLUMN "public"."user_profiles"."role" IS 'User rank (naval-tier model): grand_master (admiral) / master (captain) / admin (commander) / admin_officer (officer) / officer (ensign) / guest. Bob''s system user (00000000-0000-0000-0000-00000000b0b0) is grand_master within Iron Eagle (owner org) as of 0185. Note: there is no code-level guard preventing a human from approving a Bob-originated action -- bob-proposal-approver permits this by design. Attribution of approved_by to a real human is a design discipline, not an enforced invariant.';
COMMENT ON COLUMN "public"."user_profiles"."email" IS 'Invite/contact email. Stored at invite time so the UI can show Resend without service-role access.';
COMMENT ON COLUMN "public"."user_profiles"."phone" IS 'Primary contact phone number (mobile preferred).';
COMMENT ON COLUMN "public"."user_profiles"."address" IS 'Physical/residential address. Used for payroll, emergency contact, and compliance records.';
COMMENT ON COLUMN "public"."user_profiles"."photo_url" IS 'Supabase Storage path to head-and-shoulders profile photo. Validated by Bob AI before saving. Used for ID cards, face recognition, and access control.';
COMMENT ON COLUMN "public"."user_profiles"."module_access" IS 'Modules the officer can access directly without a roster shift.
   Set by admin. Empty array = roster-gated (default).
   Values: freedom_camping, parking, noise_control, biosecurity,
   smoke_control, site_guard, ems, patrol';

CREATE TABLE IF NOT EXISTS "public"."vehicle_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "vehicle_id" "uuid",
    "plate_raw" "text" NOT NULL,
    "plate_confidence" real,
    "location_id" "uuid",
    "zone_id" "uuid",
    "gps_lat" double precision,
    "gps_lng" double precision,
    "officer_user_id" "uuid",
    "patrol_id" "uuid",
    "shift_id" "uuid",
    "module_key" "text" NOT NULL,
    "compliance_status" "text",
    "compliance_detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "primary_evidence_id" "uuid",
    "previous_observation_id" "uuid",
    "movement_result" "text",
    "is_offline_queued" boolean DEFAULT false NOT NULL,
    "synced_at" timestamp with time zone,
    "observed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);
COMMENT ON TABLE "public"."vehicle_observations" IS 'Every vehicle scan/observation. Links vehicle, zone, officer, patrol, evidence, and compliance verdict.';

CREATE TABLE IF NOT EXISTS "public"."vehicle_overnight_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "plate_number" "text" NOT NULL,
    "zone_id" "uuid",
    "site_id" "uuid",
    "location_id" "uuid",
    "overnight_date" "date" NOT NULL,
    "timezone" "text" DEFAULT 'Pacific/Auckland'::"text" NOT NULL,
    "evening_observation_id" "uuid",
    "evening_seen_at" timestamp with time zone,
    "evening_gps_lat" double precision,
    "evening_gps_lng" double precision,
    "evening_photo_url" "text",
    "morning_observation_id" "uuid",
    "morning_seen_at" timestamp with time zone,
    "morning_gps_lat" double precision,
    "morning_gps_lng" double precision,
    "morning_photo_url" "text",
    "verification_status" "text" DEFAULT 'candidate_evening'::"text" NOT NULL,
    "movement_decision" "text",
    "movement_similarity" double precision,
    "gps_distance_meters" double precision,
    "same_position_confidence" double precision,
    "evidence_strength" "text" DEFAULT 'pending'::"text" NOT NULL,
    "manual_review_required" boolean DEFAULT false NOT NULL,
    "observation_count" integer DEFAULT 1 NOT NULL,
    "is_scv" boolean,
    "is_compliant" boolean,
    "compliance_reason" "text",
    "breach_alert_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_org_id" "uuid"
);
COMMENT ON TABLE "public"."vehicle_overnight_sessions" IS 'Two-photo Freedom Camping overnight verification sessions. Evening candidates are verified by morning scans after local midnight.';
COMMENT ON COLUMN "public"."vehicle_overnight_sessions"."evidence_strength" IS 'Evidence quality grade. pending/weak/moderate/strong = live two-photo pipeline grades. manual_review = requires human review. inferred = overnight presence inferred from consecutive-day historical observations (not court-grade evidence). Added in 0330 for issue #262/#257.';

CREATE TABLE IF NOT EXISTS "public"."vehicles" (
