CREATE TABLE IF NOT EXISTS "public"."zone_legal_config" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "zone_id" "uuid" NOT NULL,
    "payment_url" "text",
    "payment_deadline_days" integer DEFAULT 28 NOT NULL,
