CREATE OR REPLACE FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- CLAUSE 1: grand_master sees ALL orgs.
  select o.id
  from public.organizations o
  where exists (
    select 1 from public.user_profiles p
    where p.id = p_user_id and p.role = 'grand_master'
  )

  union

  -- CLAUSE 2: own org + authorized_organization_ids.
  select target.id
  from public.organizations target
  join public.user_profiles p on p.id = p_user_id
  where target.id = p.organization_id
     or target.id = any(p.authorized_organization_ids)

  union

  -- CLAUSE 3: master/admin ownership-tree descent (org + employer anchors).
  select d.org_id
  from public.user_profiles p
  cross join lateral (
    select unnest(
      public.get_descendant_organizations(p.organization_id)
      || case
           when p.employer_organization_id is not null
           then public.get_descendant_organizations(p.employer_organization_id)
           else array[]::uuid[]
         end
    ) as org_id
  ) d
  where p.id = p_user_id
    and p.role in ('grand_master', 'master', 'admin')

  union

  -- CLAUSE 4: provider_client_access_grants (active).
  select g_target.org_id
  from public.provider_client_access_grants g
  join public.user_profiles p on p.id = p_user_id
  cross join lateral (
    values (g.provider_organization_id), (g.client_organization_id)
  ) as g_target(org_id)
  where (
      p.organization_id = g.provider_organization_id
      or p.organization_id = g.client_organization_id
    )
    and (g.ends_at is null or g.ends_at > now())

  union

  -- CLAUSE 5 (0271): agreement-based, bidirectional.
  select sa_target.org_id
  from public.service_agreements sa
  join public.user_profiles p on p.id = p_user_id
  cross join lateral (
    values
      (case when (p.organization_id = sa.provider_organization_id
                  or p.employer_organization_id = sa.provider_organization_id)
            then sa.client_organization_id end),
      (case when (p.organization_id = sa.client_organization_id
                  or p.employer_organization_id = sa.client_organization_id)
            then sa.provider_organization_id end)
  ) as sa_target(org_id)
  where (sa.ends_on is null or sa.ends_on >= current_date)
    and sa_target.org_id is not null;
$function$;
COMMENT ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) IS 'INTERNAL shared entitlement resolver: the five org_access_allowed clauses keyed on an EXPLICIT resolved user id. NOT user-callable (revoked from public / authenticated / anon) - it accepts an arbitrary user id, so it is reachable ONLY through the governed wrappers my_entitled_org_ids() (self-only) and my_entitled_org_ids_for_user() (service-role only). Single source of truth for both; 0352 parity matrix applies. #306.';
REVOKE ALL ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_entitled_org_ids_for"(p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(MAX(version), 0) + 1
    FROM public.geofence_boundary_history
   WHERE entity_type = p_entity_type
     AND entity_id   = p_entity_id;
$function$;
REVOKE ALL ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_gbh_next_version"(p_entity_type text, p_entity_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_local   timestamp := p_at at time zone 'Pacific/Auckland';
  v_minutes int := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_dow     int := extract(dow from v_local)::int;   -- 0=Sunday
  v_start   text;
  v_end     text;
  v_start_m int;
  v_end_m   int;
  v_days    jsonb;
begin
  if p_schedule is null or p_schedule = '{}'::jsonb then
    return true;
  end if;

  -- Day-of-week filter.
  v_days := p_schedule -> 'days';
  if v_days is not null and jsonb_typeof(v_days) = 'array' and jsonb_array_length(v_days) > 0 then
    if not exists (
      select 1 from jsonb_array_elements_text(v_days) d where d::int = v_dow
    ) then
      return false;
    end if;
  end if;

  -- Time-of-day window.
  v_start := p_schedule ->> 'start';
  v_end   := p_schedule ->> 'end';
  if v_start is null or v_end is null then
    return true;  -- day matched (or no day filter) and no time window = active
  end if;

  v_start_m := split_part(v_start, ':', 1)::int * 60 + split_part(v_start, ':', 2)::int;
  v_end_m   := split_part(v_end,   ':', 1)::int * 60 + split_part(v_end,   ':', 2)::int;

  if v_start_m <= v_end_m then
    return v_minutes >= v_start_m and v_minutes < v_end_m;            -- same-day window
  else
    return v_minutes >= v_start_m or v_minutes < v_end_m;             -- overnight wrap
  end if;
end;
$function$;
COMMENT ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) IS 'True if a module geofence active_schedule (jsonb {start,end,days}) is in force at the given time (Pacific/Auckland). Null schedule = always active; start>end wraps midnight.';
REVOKE ALL ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."_geofence_active_at"(p_schedule jsonb, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb DEFAULT NULL::jsonb, p_verify boolean DEFAULT false, p_note text DEFAULT NULL::text)
 RETURNS TABLE(entity_type text, entity_id uuid, area_m2 numeric, human_edited boolean, verified boolean, history_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_p public.boundary_proposals%rowtype;
  v_final geometry;
  v_edited boolean := false;
  v_area numeric;
  v_gate record;
  v_version integer;
  v_owner_org uuid;
  v_source text;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_p FROM public.boundary_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Proposal not found'; END IF;
  IF v_p.status <> 'proposed' THEN RAISE EXCEPTION 'Proposal is already %', v_p.status; END IF;
  IF v_p.entity_id IS NULL THEN RAISE EXCEPTION 'Proposal has no target entity; create the site or zone first'; END IF;

  IF p_final_geojson IS NOT NULL THEN
    v_final := ST_Multi(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(p_final_geojson::text), 4326)));
    IF v_final IS NULL OR ST_IsEmpty(v_final) OR NOT ST_IsValid(v_final) THEN RAISE EXCEPTION 'Final geometry is empty or invalid'; END IF;
    v_edited := NOT ST_Equals(v_final, v_p.proposed_boundary);
  ELSE
    v_final := v_p.proposed_boundary;
  END IF;
  v_area := ST_Area(v_final::geography);
  SELECT * INTO v_gate FROM public.geofence_area_gate(v_area, v_p.zone_type);
  IF NOT v_gate.ok THEN RAISE EXCEPTION 'Boundary fails the % area gate: %', coalesce(v_p.zone_type, 'default'), v_gate.reason; END IF;

  v_source := CASE WHEN v_edited THEN 'user_drawn' ELSE v_p.source END;

  IF v_p.entity_type = 'client_site' THEN
    SELECT client_organization_id INTO v_owner_org FROM public.client_sites WHERE id = v_p.entity_id FOR UPDATE;
    IF v_owner_org IS NULL OR NOT public.org_access_allowed(v_owner_org) THEN RAISE EXCEPTION 'Site not found or access denied'; END IF;
    -- client_sites.boundary is Polygon(4326); a single-part multipolygon is unwrapped.
    IF ST_NumGeometries(v_final) <> 1 THEN RAISE EXCEPTION 'A site boundary must be a single polygon'; END IF;
    UPDATE public.client_sites
      SET boundary = ST_GeometryN(v_final, 1), center_point = ST_Centroid(v_final),
          boundary_status = CASE WHEN v_p.source = 'google_point_radius' THEN 'provisional' ELSE 'authoritative' END,
          boundary_verification = 'unverified', boundary_verified_by = NULL, boundary_verified_at = NULL,
          configuration_version = configuration_version + 1
      WHERE id = v_p.entity_id;
    v_version := public._gbh_next_version('client_site', v_p.entity_id);
    INSERT INTO public.geofence_boundary_history (entity_type, entity_id, boundary, boundary_source, verification_state, changed_by, changed_via, change_reason, version)
    VALUES ('client_site', v_p.entity_id, ST_GeometryN(v_final, 1), v_source, 'unverified', v_actor, 'direct_edit',
      format('Accepted boundary proposal %s (%s%s)', v_p.id, v_p.source, CASE WHEN v_edited THEN ', human-edited' ELSE '' END), v_version);
  ELSIF v_p.entity_type = 'location_zone' THEN
    SELECT organization_id INTO v_owner_org FROM public.location_zones WHERE id = v_p.entity_id FOR UPDATE;
    IF v_owner_org IS NULL OR NOT public.is_admin_for_org(v_owner_org) THEN RAISE EXCEPTION 'Zone not found or access denied'; END IF;
    UPDATE public.location_zones
      SET boundary = v_final, center_point = ST_Centroid(v_final),
          boundary_status = CASE WHEN v_p.source = 'google_point_radius' THEN 'provisional' ELSE 'authoritative' END,
          boundary_verification = 'unverified', boundary_verified_by = NULL, boundary_verified_at = NULL,
          configuration_version = configuration_version + 1
      WHERE id = v_p.entity_id;
    v_version := public._gbh_next_version('location_zone', v_p.entity_id);
    INSERT INTO public.geofence_boundary_history (entity_type, entity_id, boundary, boundary_source, verification_state, changed_by, changed_via, change_reason, version)
    VALUES ('location_zone', v_p.entity_id, v_final, v_source, 'unverified', v_actor, 'direct_edit',
      format('Accepted boundary proposal %s (%s%s)', v_p.id, v_p.source, CASE WHEN v_edited THEN ', human-edited' ELSE '' END), v_version);
  ELSE
    -- Org jurisdiction is SENSITIVE (Q5): it must go through the governed proposal flow.
    RAISE EXCEPTION 'Entity type % cannot be accepted through the workbench', v_p.entity_type;
  END IF;

  UPDATE public.boundary_proposals
    SET status = 'accepted', decided_by = v_actor, decided_at = clock_timestamp(), decision_note = p_note,
        final_boundary = v_final, human_edited = v_edited, history_version = v_version
    WHERE id = v_p.id;

  IF p_verify THEN
    PERFORM public.verify_boundary(v_p.entity_type, v_p.entity_id);
  END IF;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_p.organization_id, v_actor, 'boundary_proposal_accepted', v_p.entity_type || 's', v_p.entity_id,
    jsonb_build_object('proposal_id', v_p.id, 'source', v_p.source, 'human_edited', v_edited, 'area_m2', round(v_area), 'verified', p_verify, 'history_version', v_version));

  RETURN QUERY SELECT v_p.entity_type, v_p.entity_id, v_area, v_edited, p_verify, v_version;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accept_boundary_proposal"(p_proposal_id uuid, p_final_geojson jsonb, p_verify boolean, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_client_capability_share"(p_token text)
 RETURNS service_agreements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invite public.onboarding_invites%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_hash text := encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex');
BEGIN
  SELECT * INTO v_invite FROM public.onboarding_invites
  WHERE token_hash = v_hash AND invite_kind IN ('reporting_share', 'finance_share')
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invite not found'; END IF;
  IF v_invite.status <> 'pending' THEN RAISE EXCEPTION 'Invite is no longer pending'; END IF;
  IF v_invite.expires_at < now() THEN
    UPDATE public.onboarding_invites SET status = 'expired' WHERE id = v_invite.id;
    RAISE EXCEPTION 'Invite has expired';
  END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = v_invite.service_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;

  IF v_invite.invite_kind = 'reporting_share' THEN
    UPDATE public.service_agreements SET client_portal_reports_enabled = true WHERE id = v_agreement.id RETURNING * INTO v_agreement;
  ELSE
    UPDATE public.service_agreements SET client_portal_finance_enabled = true WHERE id = v_agreement.id RETURNING * INTO v_agreement;
  END IF;

  UPDATE public.onboarding_invites SET status = 'accepted', accepted_at = now() WHERE id = v_invite.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, auth.uid(), 'client_capability_share_accepted', 'service_agreements', v_agreement.id, jsonb_build_object('invite_kind', v_invite.invite_kind));

  RETURN v_agreement;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."accept_client_capability_share"(p_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."accept_client_capability_share"(p_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."accept_quote"(p_quote_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote            public.quotes%rowtype;
  v_role             text;
  v_caller_org       uuid;
  v_employer_org     uuid;
  v_agreement_id     uuid;
  v_base_rate        numeric;
  v_callout_rate     numeric;
  v_travel_rate      numeric;
  v_site             record;
  v_site_rate        numeric;
begin
  select * into v_quote from public.quotes where id = p_quote_id;
  if not found then
    raise exception 'accept_quote: quote % not found', p_quote_id;
  end if;

  select role, organization_id, employer_organization_id into v_role, v_caller_org, v_employer_org
  from public.user_profiles where id = auth.uid();

  if not (
    public.is_grand_master()
    or (
      v_role in ('master','admin','admin_officer')
      and v_quote.provider_org_id = any(public.get_descendant_organizations(coalesce(v_employer_org, v_caller_org)))
    )
  ) then
    raise exception 'accept_quote: not authorised to accept quotes for this provider';
  end if;

  if v_quote.status = 'accepted' and v_quote.service_agreement_id is not null then
    return v_quote.service_agreement_id;
  end if;

  if v_quote.status not in ('draft','sent') then
    raise exception 'accept_quote: quote status % cannot be accepted', v_quote.status;
  end if;
  if v_quote.client_org_id is null then
    raise exception 'accept_quote: quote has no client organisation; a service agreement requires a real client (set client_org_id before accepting)';
  end if;

  v_agreement_id := v_quote.service_agreement_id;

  if v_agreement_id is null then
    select id into v_agreement_id
    from public.service_agreements
    where provider_organization_id = v_quote.provider_org_id
      and client_organization_id  = v_quote.client_org_id
      and name = v_quote.title
    limit 1;
  end if;

  if v_agreement_id is null then
    insert into public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, agreement_type, invitation_status)
    values (v_quote.provider_org_id, v_quote.client_org_id, v_quote.title, current_date, 'operational', 'accepted')
    returning id into v_agreement_id;
  else
    update public.service_agreements
    set agreement_type = 'operational',
        invitation_status = 'accepted'
    where id = v_agreement_id;
  end if;

  select avg(unit_charge) into v_base_rate
  from public.quote_lines where quote_id = p_quote_id and kind in ('labour','module') and unit_charge > 0;

  select avg(unit_charge) into v_travel_rate
  from public.quote_lines where quote_id = p_quote_id and kind = 'travel' and unit_charge > 0;

  select avg(unit_charge) into v_callout_rate
  from public.quote_lines where quote_id = p_quote_id and kind in ('platform_fee','custom')
    and unit_charge > 0 and lower(description) like '%callout%';

  if exists (select 1 from public.crm_commercial_settings where service_agreement_id = v_agreement_id) then
    update public.crm_commercial_settings set
      currency            = v_quote.currency,
      base_rate_per_hour  = coalesce(v_base_rate, base_rate_per_hour),
      callout_rate_per_hour = coalesce(v_callout_rate, callout_rate_per_hour),
      travel_rate_per_km  = coalesce(v_travel_rate, travel_rate_per_km)
    where service_agreement_id = v_agreement_id;
  else
    insert into public.crm_commercial_settings
      (service_agreement_id, currency, base_rate_per_hour, callout_rate_per_hour, travel_rate_per_km)
    values
      (v_agreement_id, v_quote.currency, v_base_rate, v_callout_rate, v_travel_rate);
  end if;

  for v_site in
    select distinct site_id from public.quote_lines
    where quote_id = p_quote_id and site_id is not null
  loop
    select avg(unit_charge) into v_site_rate
    from public.quote_lines
    where quote_id = p_quote_id and site_id = v_site.site_id and kind in ('labour','module') and unit_charge > 0;
    v_site_rate := coalesce(v_site_rate, v_base_rate);

    if exists (
      select 1 from public.site_financial_config
      where site_id = v_site.site_id and service_agreement_id = v_agreement_id
    ) then
      update public.site_financial_config set
        billing_model = 'hourly',
        hourly_rate   = coalesce(v_site_rate, hourly_rate),
        updated_at    = now()
      where site_id = v_site.site_id and service_agreement_id = v_agreement_id;
    else
      insert into public.site_financial_config
        (organization_id, site_id, service_agreement_id, billing_model, hourly_rate)
      values
        (v_quote.provider_org_id, v_site.site_id, v_agreement_id, 'hourly', v_site_rate);
    end if;
  end loop;

  update public.quotes set
    status               = 'accepted',
    accepted_at          = now(),
    accepted_by          = auth.uid(),
    service_agreement_id = v_agreement_id,
    updated_by           = auth.uid()
  where id = p_quote_id;

  return v_agreement_id;
end $function$;
COMMENT ON FUNCTION "public"."accept_quote"(p_quote_id uuid) IS 'B5 (#2): accept a Layer 2 quote -> create/link a service_agreement, write crm_commercial_settings + per-site site_financial_config from the quote lines, stamp the quote accepted. Atomic, security-definer, authz = grand_master or provider admin/master. Idempotent; requires a real client_org_id.';
REVOKE ALL ON FUNCTION "public"."accept_quote"(p_quote_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."accept_quote"(p_quote_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."accept_quote"(p_quote_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text DEFAULT NULL::text, p_continuation_location_event_id uuid DEFAULT NULL::uuid)
 RETURNS operational_continuity_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_item public.operational_continuity_items%rowtype; v_receipt public.operational_continuity_receipts%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_receipt from public.operational_continuity_receipts where recipient_organization_id = (select recipient_organization_id from public.operational_continuity_items where id = p_continuity_item_id) and client_request_id = p_client_request_id;
  if found then return v_receipt; end if;
  select * into v_item from public.operational_continuity_items where id=p_continuity_item_id for update;
  if not found or not public.is_admin_for_org(v_item.recipient_organization_id) then raise exception 'Continuity item not available to your organization'; end if;
  insert into public.operational_continuity_receipts(continuity_item_id,recipient_organization_id,acknowledged_by,continuation_location_event_id,acknowledgement_notes,client_request_id)
  values(v_item.id,v_item.recipient_organization_id,v_actor,p_continuation_location_event_id,nullif(trim(coalesce(p_acknowledgement_notes,'')),''),p_client_request_id)
  returning * into v_receipt;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_item.recipient_organization_id,v_actor,'operational_continuity_acknowledged','operational_continuity_receipts',v_receipt.id,jsonb_build_object('continuity_item_id',v_item.id,'source_organization_id',v_item.source_organization_id));
  return v_receipt;
end; $function$;
REVOKE ALL ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_operational_continuity_item"(p_client_request_id uuid, p_continuity_item_id uuid, p_acknowledgement_notes text, p_continuation_location_event_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text)
 RETURNS TABLE(shift_id uuid, acknowledged_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_shift public.shifts%rowtype; v_user uuid; v_at timestamptz := clock_timestamp(); v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  if v_notes is null then raise exception 'Attendance exception notes are required'; end if;
  if p_exception_type not in ('late_start', 'active_overrun') then raise exception 'Unsupported attendance exception type'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then raise exception 'Shift not found'; end if;
  if not public.is_admin_for_org(v_shift.organization_id) then raise exception 'Roster administrator required'; end if;
  select coalesce(sp.user_id, sp.id) into v_user from public.staff_profiles sp where sp.id = (select rs.staff_id from public.roster_slots rs where rs.linked_shift_id = v_shift.id limit 1);
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_shift.organization_id, v_actor, 'roster_attendance_exception_acknowledged', 'shifts', v_shift.id, jsonb_build_object('exception_type', p_exception_type, 'notes', v_notes, 'acknowledged_at', v_at));
  if v_user is not null then perform public.enqueue_notification(p_organization_id => v_shift.organization_id, p_category => 'roster', p_title => 'Attendance exception acknowledged', p_body => v_notes, p_severity => 'warning', p_recipient_user_id => v_user, p_link_page => 'schedule', p_link_payload => jsonb_build_object('shift_id', v_shift.id, 'exception_type', p_exception_type), p_dedup_key => 'attendance_exception_ack:' || v_shift.id::text || ':' || p_exception_type || ':' || v_at::text); end if;
  return query select v_shift.id, v_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."acknowledge_roster_attendance_exception"(p_shift_id uuid, p_exception_type text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_crm_account"(p_account_organization_id uuid, p_agreement_id uuid, p_expected_organization_updated_at timestamp with time zone, p_expected_ledger_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_org public.organizations%rowtype;
  v_ledger public.crm_onboarding_ledgers%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_readiness jsonb;
BEGIN
  SELECT organization_id INTO v_provider
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;

  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active CRM administrator required';
  END IF;

  SELECT * INTO v_org
  FROM public.organizations
  WHERE id = p_account_organization_id
    AND parent_organization_id = ANY(public.get_descendant_organizations(v_provider))
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Managed CRM account not found'; END IF;
  IF v_org.status <> 'prospect' OR v_org.active THEN RAISE EXCEPTION 'Only an inactive prospect can be activated'; END IF;
  IF v_org.updated_at IS DISTINCT FROM p_expected_organization_updated_at THEN RAISE EXCEPTION 'Organization changed since activation review'; END IF;

  SELECT * INTO v_ledger
  FROM public.crm_onboarding_ledgers
  WHERE provider_organization_id = ANY(public.get_descendant_organizations(v_provider))
    AND account_organization_id = v_org.id
  ORDER BY started_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR v_ledger.version <> p_expected_ledger_version THEN RAISE EXCEPTION 'Onboarding ledger changed since activation review'; END IF;
  IF v_ledger.current_stage <> 'review' THEN RAISE EXCEPTION 'Onboarding must be in review before activation'; END IF;
  IF v_ledger.assigned_to IS NULL OR nullif(trim(v_ledger.stage_note), '') IS NULL THEN RAISE EXCEPTION 'Named onboarding owner and review note required before activation'; END IF;

  SELECT * INTO v_agreement
  FROM public.service_agreements
  WHERE id = p_agreement_id
    AND provider_organization_id = ANY(public.get_descendant_organizations(v_ledger.provider_organization_id))
    AND client_organization_id = v_org.id
    AND agreement_type = 'operational'
  FOR UPDATE;

  IF NOT FOUND OR v_agreement.invitation_status <> 'accepted' THEN RAISE EXCEPTION 'Accepted operational agreement required'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.crm_contacts c WHERE c.organization_id = v_org.id AND c.is_primary AND c.deactivated_at IS NULL) THEN RAISE EXCEPTION 'Active primary contact required'; END IF;
  v_readiness := public.get_crm_operational_readiness(v_agreement.id);
  IF NOT coalesce((v_readiness->>'ready')::boolean, false) THEN RAISE EXCEPTION 'Operational readiness blockers remain'; END IF;

  UPDATE public.organizations
  SET status = 'active', active = true, updated_at = clock_timestamp()
  WHERE id = v_org.id
  RETURNING * INTO v_org;

  UPDATE public.crm_onboarding_ledgers
  SET current_stage = 'activated', status = 'activated', version = version + 1, activated_at = clock_timestamp(), activated_by = v_actor, updated_at = clock_timestamp()
  WHERE id = v_ledger.id
  RETURNING * INTO v_ledger;

  INSERT INTO public.crm_onboarding_events(ledger_id,provider_organization_id,account_organization_id,event_type,from_stage,to_stage,ledger_status,assigned_to,note,actor_user_id,ledger_version)
  VALUES(v_ledger.id,v_ledger.provider_organization_id,v_org.id,'activated','review','activated','activated',v_ledger.assigned_to,'Account activated after governed readiness review',v_actor,v_ledger.version);
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_ledger.provider_organization_id,v_actor,'crm_account_activated','organizations',v_org.id,jsonb_build_object('agreement_id',v_agreement.id,'ledger_id',v_ledger.id,'assigned_to',v_ledger.assigned_to,'ledger_version',v_ledger.version));

  RETURN jsonb_build_object('account_organization_id',v_org.id,'organization_status',v_org.status,'ledger_status',v_ledger.status,'activated_at',v_ledger.activated_at);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."activate_crm_account"(p_account_organization_id uuid, p_agreement_id uuid, p_expected_organization_updated_at timestamp with time zone, p_expected_ledger_version integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_crm_account"(p_account_organization_id uuid, p_agreement_id uuid, p_expected_organization_updated_at timestamp with time zone, p_expected_ledger_version integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_crm_account"(p_account_organization_id uuid, p_agreement_id uuid, p_expected_organization_updated_at timestamp with time zone, p_expected_ledger_version integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."activate_crm_account"(p_account_organization_id uuid, p_agreement_id uuid, p_expected_organization_updated_at timestamp with time zone, p_expected_ledger_version integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_branch public.organizations%rowtype;
  v_parent public.organizations%rowtype;
begin
  select * into v_branch from public.organizations where id = p_branch_organization_id for update;
  if not found or v_branch.organization_type <> 'branch' then raise exception 'Internal provider branch not found'; end if;
  select * into v_parent from public.organizations where id = v_branch.parent_organization_id;
  if not found or v_parent.organization_type not in ('owner', 'service_provider', 'branch') or not public.is_admin_for_org(v_parent.id) then raise exception 'Parent provider administrator required'; end if;
  if v_branch.active and v_branch.status = 'active' then return v_branch; end if;
  if v_branch.status <> 'prospect' then raise exception 'Only a provider branch in prospect status can be activated'; end if;
  if p_expected_updated_at is not null and v_branch.updated_at <> p_expected_updated_at then raise exception 'Provider branch changed since activation review'; end if;
  update public.organizations set active = true, status = 'active', updated_at = now() where id = v_branch.id returning * into v_branch;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_parent.id,auth.uid(),'provider_branch_activated','organizations',v_branch.id,jsonb_build_object('parent_provider_organization_id',v_parent.id));
  return v_branch;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."activate_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."activate_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_quote_proposal_modules"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare scope public.quote_proposal_modules%rowtype;
begin
  if new.status = 'accepted' and new.service_agreement_id is not null and old.status is distinct from 'accepted' then
    for scope in select * from public.quote_proposal_modules where quote_id = new.id loop
      insert into public.service_agreement_modules(service_agreement_id,module_key,enabled,sla_minutes,settings)
      values(new.service_agreement_id,scope.module_key,true,scope.sla_minutes,jsonb_build_object('proposal_service_window',scope.service_window,'work_model',scope.work_model,'pricing_basis',scope.pricing_basis,'rate_rule_id',scope.rate_rule_id))
      on conflict(service_agreement_id,module_key) do update set enabled=true,sla_minutes=coalesce(excluded.sla_minutes,service_agreement_modules.sla_minutes),settings=service_agreement_modules.settings || excluded.settings;
    end loop;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."activate_quote_proposal_modules"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_modules"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_modules"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_quote_proposal_places"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE place public.quote_proposal_places%rowtype;v_site_id uuid;v_zone_id uuid;v_point geometry;v_key text;v_house uuid;
BEGIN
  IF new.status='accepted' AND new.service_agreement_id IS NOT NULL AND old.status IS DISTINCT FROM 'accepted' THEN
    FOR place IN SELECT * FROM public.quote_proposal_places WHERE quote_id=new.id LOOP
      v_key:=public.address_match_key(place.address);
      IF place.place_kind='site' THEN
        IF place.resolution='use_existing' THEN v_site_id:=place.candidate_site_id;
        ELSE
          IF EXISTS(SELECT 1 FROM public.client_sites site WHERE site.client_organization_id=new.client_org_id AND site.address_match_key=v_key) THEN RAISE EXCEPTION 'Proposed Site requires duplicate resolution before acceptance';END IF;
          v_point:=CASE WHEN place.proposed_geometry IS NOT NULL AND place.proposed_geometry->>'type'='Point' THEN ST_SetSRID(ST_GeomFromGeoJSON(place.proposed_geometry::text),4326) ELSE NULL END;
          INSERT INTO public.client_sites(client_organization_id,name,address,address_match_key,site_type,active,site_origin,boundary_status,boundary_verification,center_point) VALUES(new.client_org_id,place.name,place.address,v_key,place.site_type,true,'contracted','provisional','unverified',v_point) RETURNING id INTO v_site_id;
        END IF;
        INSERT INTO public.service_agreement_locations(service_agreement_id,site_id,status,created_by) VALUES(new.service_agreement_id,v_site_id,'active',new.accepted_by) ON CONFLICT(service_agreement_id,site_id) DO UPDATE SET status='active',updated_at=clock_timestamp();
        INSERT INTO public.site_services(organization_id,service_agreement_id,module_key,site_id,service_hours,enabled,active,created_by) SELECT new.provider_org_id,new.service_agreement_id,place.module_key,v_site_id,'{}'::jsonb,true,true,new.accepted_by WHERE NOT EXISTS(SELECT 1 FROM public.site_services service WHERE service.service_agreement_id=new.service_agreement_id AND service.module_key=place.module_key AND service.site_id=v_site_id);
        UPDATE public.quote_proposal_places SET converted_site_id=v_site_id,converted_at=clock_timestamp() WHERE id=place.id;
      ELSE
        IF place.resolution='use_existing' THEN v_zone_id:=place.candidate_zone_id;
        ELSE
          SELECT id INTO v_house FROM public.locations house WHERE house.organization_id=new.client_org_id AND ((v_key IS NOT NULL AND house.address_match_key=v_key) OR (v_key IS NULL AND lower(house.name)=lower(place.name))) ORDER BY house.created_at LIMIT 1;
          IF v_house IS NOT NULL AND EXISTS(SELECT 1 FROM public.location_zones zone WHERE zone.organization_id=new.client_org_id AND zone.location_id=v_house AND zone.module_key=place.module_key AND lower(zone.name)=lower(place.name)) THEN RAISE EXCEPTION 'Proposed Zone requires duplicate resolution before acceptance';END IF;
          IF v_house IS NULL THEN
            INSERT INTO public.locations(organization_id,name,address,address_match_key,created_by) VALUES(new.client_org_id,place.name,place.address,v_key,new.accepted_by) RETURNING id INTO v_house;
          END IF;
          INSERT INTO public.location_zones(organization_id,location_id,name,zone_type,module_key,is_active,boundary_status,boundary_verification) VALUES(new.client_org_id,v_house,place.name,place.zone_type,place.module_key,true,'provisional','unverified') RETURNING id INTO v_zone_id;
        END IF;
        INSERT INTO public.service_agreement_locations(service_agreement_id,zone_id,status,created_by) VALUES(new.service_agreement_id,v_zone_id,'active',new.accepted_by) ON CONFLICT(service_agreement_id,zone_id) DO UPDATE SET status='active',updated_at=clock_timestamp();
        INSERT INTO public.site_services(organization_id,service_agreement_id,module_key,zone_id,service_hours,enabled,active,created_by) SELECT new.provider_org_id,new.service_agreement_id,place.module_key,v_zone_id,'{}'::jsonb,true,true,new.accepted_by WHERE NOT EXISTS(SELECT 1 FROM public.site_services service WHERE service.service_agreement_id=new.service_agreement_id AND service.module_key=place.module_key AND service.zone_id=v_zone_id);
        UPDATE public.quote_proposal_places SET converted_zone_id=v_zone_id,converted_at=clock_timestamp() WHERE id=place.id;
      END IF;
    END LOOP;
  END IF;
  RETURN new;
END;$function$;
REVOKE ALL ON FUNCTION "public"."activate_quote_proposal_places"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_places"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_places"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_places"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_quote_proposal_scope_schedules"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF new.status='accepted' AND new.service_agreement_id IS NOT NULL AND old.status IS DISTINCT FROM 'accepted' THEN
    INSERT INTO public.service_agreement_delivery_schedules(service_agreement_id,proposal_scope_schedule_id,site_id,zone_id,module_key,capability_key,work_model,active_days,active_months,visits_per_shift,min_gap_between_visits_minutes,window_start,window_end,response_sla_minutes,depart_sla_minutes,dwell_minutes,preferred_stop_order,pricing_basis,rate_rule_id,chargeable_conditions,notes,officer_instructions)
    SELECT new.service_agreement_id,schedule.id,coalesce(scope.site_id,place.converted_site_id),coalesce(scope.zone_id,place.converted_zone_id),scope.module_key,schedule.capability_key,schedule.work_model,schedule.active_days,schedule.active_months,schedule.visits_per_shift,schedule.min_gap_between_visits_minutes,schedule.window_start,schedule.window_end,schedule.response_sla_minutes,schedule.depart_sla_minutes,schedule.dwell_minutes,schedule.preferred_stop_order,schedule.pricing_basis,schedule.rate_rule_id,schedule.chargeable_conditions,schedule.notes,schedule.officer_instructions
    FROM public.quote_proposal_scope_schedules schedule
    JOIN public.quote_proposal_service_scopes scope ON scope.id=schedule.proposal_scope_id
    LEFT JOIN public.quote_proposal_places place ON place.id=scope.proposed_place_id
    WHERE scope.quote_id=new.id
    ON CONFLICT(proposal_scope_schedule_id) DO NOTHING;

    INSERT INTO public.client_site_patrol_config(organization_id,site_id,zone_id,module_key,active_days,visits_per_shift,min_gap_between_visits_minutes,time_window_type,window_start,window_end,active_months,dwell_minutes,sla_arrive_within_minutes,sla_depart_within_minutes,preferred_stop_order,officer_instructions,proposal_scope_schedule_id)
    SELECT new.provider_org_id,coalesce(scope.site_id,place.converted_site_id),coalesce(scope.zone_id,place.converted_zone_id),
      CASE schedule.capability_key WHEN 'patrol' THEN 'general_patrol' ELSE schedule.capability_key END,
      schedule.active_days,schedule.visits_per_shift,schedule.min_gap_between_visits_minutes,
      'fixed',schedule.window_start,schedule.window_end,schedule.active_months,schedule.dwell_minutes,
      coalesce(schedule.response_sla_minutes,30),coalesce(schedule.depart_sla_minutes,45),
      schedule.preferred_stop_order,schedule.officer_instructions,schedule.id
    FROM public.quote_proposal_scope_schedules schedule
    JOIN public.quote_proposal_service_scopes scope ON scope.id=schedule.proposal_scope_id
    LEFT JOIN public.quote_proposal_places place ON place.id=scope.proposed_place_id
    WHERE scope.quote_id=new.id AND schedule.capability_key<>'alarm_response'
    ON CONFLICT (proposal_scope_schedule_id) WHERE proposal_scope_schedule_id IS NOT NULL DO NOTHING;
  END IF;
  RETURN new;
END;$function$;
REVOKE ALL ON FUNCTION "public"."activate_quote_proposal_scope_schedules"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_scope_schedules"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_scope_schedules"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."activate_quote_proposal_service_scopes"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE scope public.quote_proposal_service_scopes%rowtype;module_intent public.quote_proposal_modules%rowtype;place public.quote_proposal_places%rowtype;v_site_id uuid;v_zone_id uuid;
BEGIN
  IF new.status='accepted' AND new.service_agreement_id IS NOT NULL AND old.status IS DISTINCT FROM 'accepted' THEN
    FOR scope IN SELECT * FROM public.quote_proposal_service_scopes WHERE quote_id=new.id LOOP
      SELECT * INTO module_intent FROM public.quote_proposal_modules WHERE quote_id=new.id AND module_key=scope.module_key;
      IF NOT FOUND THEN RAISE EXCEPTION 'Accepted proposal scope has no quoted module';END IF;
      IF scope.proposed_place_id IS NOT NULL THEN SELECT * INTO place FROM public.quote_proposal_places WHERE id=scope.proposed_place_id;v_site_id:=place.converted_site_id;v_zone_id:=place.converted_zone_id;IF v_site_id IS NULL AND v_zone_id IS NULL THEN RAISE EXCEPTION 'Proposed place was not converted during quote acceptance';END IF;ELSE v_site_id:=scope.site_id;v_zone_id:=scope.zone_id;END IF;
      INSERT INTO public.service_agreement_locations(service_agreement_id,site_id,zone_id,status,created_by) SELECT new.service_agreement_id,v_site_id,v_zone_id,'active',new.accepted_by WHERE NOT EXISTS(SELECT 1 FROM public.service_agreement_locations location WHERE location.service_agreement_id=new.service_agreement_id AND location.site_id IS NOT DISTINCT FROM v_site_id AND location.zone_id IS NOT DISTINCT FROM v_zone_id);
      INSERT INTO public.site_services(organization_id,service_agreement_id,module_key,site_id,zone_id,service_hours,response_sla_minutes,config,enabled,active,created_by) SELECT new.provider_org_id,new.service_agreement_id,scope.module_key,v_site_id,v_zone_id,module_intent.service_window,module_intent.sla_minutes,jsonb_build_object('proposal_scope_id',scope.id,'pricing_basis',module_intent.pricing_basis,'rate_rule_id',module_intent.rate_rule_id),true,true,new.accepted_by WHERE NOT EXISTS(SELECT 1 FROM public.site_services service WHERE service.service_agreement_id=new.service_agreement_id AND service.module_key=scope.module_key AND service.site_id IS NOT DISTINCT FROM v_site_id AND service.zone_id IS NOT DISTINCT FROM v_zone_id);
    END LOOP;
  END IF;
  RETURN new;
END;$function$;
REVOKE ALL ON FUNCTION "public"."activate_quote_proposal_service_scopes"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_service_scopes"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."activate_quote_proposal_service_scopes"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."add_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_description text, p_quantity numeric, p_unit_price numeric)
 RETURNS TABLE(line_id uuid, invoice_id uuid, subtotal numeric, gst_amount numeric, total_amount numeric, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_invoice public.invoices%rowtype;
  v_line public.invoice_line_items%rowtype;
  v_description text := nullif(trim(coalesce(p_description, '')), '');
  v_next_seq integer;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select i.* into v_invoice from public.invoices i where i.id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found';
  end if;

  if not public.is_admin_for_org(v_invoice.organization_id) then
    raise exception 'Not authorised to manage invoices for this organization';
  end if;

  if v_invoice.status <> 'draft' then
    raise exception 'Only draft invoices can be updated';
  end if;

  if v_description is null then
    raise exception 'Line description is required';
  end if;

  if p_quantity is null or p_quantity <= 0 or p_unit_price is null or p_unit_price < 0 then
    raise exception 'Invoice line quantity and price must be positive numbers';
  end if;

  select coalesce(max(line_number), 0) + 1 into v_next_seq
  from public.invoice_line_items where invoice_line_items.invoice_id = v_invoice.id;

  insert into public.invoice_line_items (
    invoice_id, line_number, description, quantity, unit_price, line_total, organization_id
  )
  values (
    v_invoice.id, v_next_seq, v_description, p_quantity, p_unit_price, round(p_quantity * p_unit_price, 2), v_invoice.organization_id
  )
  returning * into v_line;

  update public.invoices i set
    subtotal = totals.subtotal,
    gst_amount = round(totals.subtotal * 0.15, 2),
    total_amount = round(totals.subtotal * 1.15, 2),
    updated_at = now()
  from (
    select coalesce(sum(l.line_total), 0)::numeric(12,2) subtotal
    from public.invoice_line_items l
    where l.invoice_id = v_invoice.id
  ) totals
  where i.id = v_invoice.id
  returning i.* into v_invoice;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_invoice.organization_id,
    v_actor,
    'crm_invoice_line_added',
    'invoice_line_items',
    v_line.id,
    jsonb_build_object(
      'invoice_id', v_invoice.id,
      'description', v_description,
      'quantity', p_quantity,
      'unit_price', p_unit_price,
      'line_total', v_line.line_total,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_line.id, v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."add_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_description text, p_quantity numeric, p_unit_price numeric) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."add_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_description text, p_quantity numeric, p_unit_price numeric) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."add_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_description text, p_quantity numeric, p_unit_price numeric) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."add_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_description text, p_quantity numeric, p_unit_price numeric) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."add_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_kind text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric, p_module_key text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(line_id uuid, quote_id uuid, total_cost numeric, subtotal_charge numeric, discount_amount numeric, gst_amount numeric, total_charge numeric, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_quote public.quotes%rowtype;v_line public.quote_lines%rowtype;v_created boolean:=true;v_description text:=nullif(trim(coalesce(p_description,'')),'');
begin
  select q.* into v_quote from public.quotes q where q.id=p_quote_id for update;if not found then raise exception 'Quote not found';end if;
  if not public.is_admin_for_org(v_quote.provider_org_id) then raise exception 'Not authorised to price this quote';end if;
  if v_quote.status<>p_expected_status then raise exception 'Quote changed from expected status % to %',p_expected_status,v_quote.status;end if;if v_quote.status<>'draft' then raise exception 'Only draft quotes can be priced';end if;
  if p_client_request_id is null then raise exception 'client_request_id is required';end if;if p_kind not in('labour','travel','overhead','module','custom','materials','equipment') then raise exception 'Unsupported quote line kind';end if;if v_description is null then raise exception 'Line description is required';end if;
  if p_quantity is null or p_quantity<=0 or p_quantity>100000 or p_unit_cost is null or p_unit_cost<0 or p_unit_cost>1000000 or p_unit_charge is null or p_unit_charge<0 or p_unit_charge>1000000 then raise exception 'Quote line amounts are outside the accepted range';end if;
  if p_kind='module' and nullif(trim(coalesce(p_module_key,'')),'') is null then raise exception 'Module key is required for module lines';end if;
  if p_site_id is not null and not exists(select 1 from public.client_sites s where s.id=p_site_id and s.organization_id=v_quote.client_org_id) then raise exception 'Quote site must belong to the client organization';end if;
  select l.* into v_line from public.quote_lines l where l.quote_id=v_quote.id and l.client_request_id=p_client_request_id;if found then v_created:=false;else insert into public.quote_lines(quote_id,kind,description,quantity,unit_cost,unit_charge,module_key,site_id,line_order,client_request_id) values(v_quote.id,p_kind,v_description,p_quantity,p_unit_cost,p_unit_charge,nullif(trim(coalesce(p_module_key,'')),''),p_site_id,coalesce((select max(l.line_order)+1 from public.quote_lines l where l.quote_id=v_quote.id),0),p_client_request_id) returning * into v_line;end if;
  update public.quotes q set total_cost=totals.total_cost,subtotal_charge=totals.subtotal_charge,discount_amount=round(totals.subtotal_charge*q.discount_pct/100,2),gst_amount=round((totals.subtotal_charge-round(totals.subtotal_charge*q.discount_pct/100,2))*q.gst_rate,2),total_charge=round((totals.subtotal_charge-round(totals.subtotal_charge*q.discount_pct/100,2))*(1+q.gst_rate),2),updated_by=v_actor from (select coalesce(sum(l.quantity*l.unit_cost),0)::numeric(12,2) total_cost,coalesce(sum(l.quantity*l.unit_charge),0)::numeric(12,2) subtotal_charge from public.quote_lines l where l.quote_id=v_quote.id) totals where q.id=v_quote.id returning q.* into v_quote;
  if v_created then insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_quote.provider_org_id,v_actor,'crm_quote_line_added','quote_lines',v_line.id,jsonb_build_object('quote_id',v_quote.id,'kind',v_line.kind,'site_id',v_line.site_id,'module_key',v_line.module_key,'total_cost',v_quote.total_cost,'total_charge',v_quote.total_charge));end if;
  return query select v_line.id,v_quote.id,v_quote.total_cost,v_quote.subtotal_charge,v_quote.discount_amount,v_quote.gst_amount,v_quote.total_charge,v_created;
end;$function$;
REVOKE ALL ON FUNCTION "public"."add_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_kind text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric, p_module_key text, p_site_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."add_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_kind text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric, p_module_key text, p_site_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."add_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_kind text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric, p_module_key text, p_site_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."add_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_kind text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric, p_module_key text, p_site_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."add_crm_quote_lines_from_bom_template"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_template_id uuid, p_site_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(lines_added integer, lines_needing_price integer, quote_id uuid, total_cost numeric, subtotal_charge numeric, discount_amount numeric, gst_amount numeric, total_charge numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote public.quotes%rowtype;
  v_tpl public.workshop_bom_templates%rowtype;
  v_line record;
  v_cost numeric; v_price numeric;
  v_kind text;
  v_receipt record;
  v_added integer := 0;
  v_unpriced integer := 0;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select q.* into v_quote from public.quotes q where q.id = p_quote_id;
  if not found then raise exception 'Quote not found'; end if;
  if not public.is_admin_for_org(v_quote.provider_org_id) then raise exception 'Not authorised to price this quote'; end if;
  select t.* into v_tpl from public.workshop_bom_templates t where t.id = p_template_id and t.organization_id = v_quote.provider_org_id and t.active;
  if not found then raise exception 'Template not found for this quote''s provider'; end if;
  if not exists (select 1 from public.workshop_bom_template_lines l where l.template_id = v_tpl.id) then raise exception 'Template "%" has no lines', v_tpl.name; end if;

  for v_line in select l.* from public.workshop_bom_template_lines l where l.template_id = v_tpl.id order by l.position loop
    v_cost := null; v_price := null;
    if v_line.item_id is not null then
      select cp.unit_cost, cp.unit_price into v_cost, v_price from public.workshop_current_prices(v_line.item_id) cp;
    end if;
    if coalesce(v_price, 0) = 0 then v_unpriced := v_unpriced + 1; end if;
    v_kind := case v_line.line_kind when 'material' then 'materials' when 'equipment' then 'equipment' when 'travel' then 'travel' else 'labour' end;
    -- Deterministic per-line request id: the same call replayed adds nothing twice.
    select * into v_receipt from public.add_crm_quote_line(
      md5(p_client_request_id::text || ':' || v_line.id::text)::uuid, v_quote.id, p_expected_status, v_kind,
      v_tpl.name || ' — ' || v_line.description, v_line.quantity, coalesce(v_cost, 0), coalesce(v_price, 0), null, p_site_id);
    if v_receipt.created then v_added := v_added + 1; end if;
  end loop;

  select q.* into v_quote from public.quotes q where q.id = p_quote_id;
  if v_added > 0 then
    insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_quote.provider_org_id, auth.uid(), 'crm_quote_lines_added_from_bom_template', 'quotes', v_quote.id,
            jsonb_build_object('template_id', v_tpl.id, 'template_name', v_tpl.name, 'lines_added', v_added, 'lines_needing_price', v_unpriced, 'client_request_id', p_client_request_id));
  end if;
  return query select v_added, v_unpriced, v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge;
end;
$function$;
COMMENT ON FUNCTION "public"."add_crm_quote_lines_from_bom_template"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_template_id uuid, p_site_id uuid) IS 'Copy a workshop BOM template onto a draft quote as priced lines (current approved price-book cost/sell). Idempotent per line on the caller''s request id; audited.';
REVOKE ALL ON FUNCTION "public"."add_crm_quote_lines_from_bom_template"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_template_id uuid, p_site_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."add_crm_quote_lines_from_bom_template"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_template_id uuid, p_site_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."add_crm_quote_lines_from_bom_template"(p_client_request_id uuid, p_quote_id uuid, p_expected_status text, p_template_id uuid, p_site_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."add_finance_budget_line"(p_budget_id uuid, p_pl_period_id uuid, p_cost_type text, p_budget_amount numeric, p_cost_centre_id uuid DEFAULT NULL::uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS finance_budget_lines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_budget public.finance_budgets%rowtype;
  v_period public.finance_pl_periods%rowtype;
  v_line public.finance_budget_lines%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_budget FROM public.finance_budgets WHERE id = p_budget_id AND organization_id = v_org;
  IF NOT FOUND OR v_budget.status <> 'draft' THEN RAISE EXCEPTION 'Only draft budgets can be changed'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND OR v_period.status IN ('closed','archived') THEN RAISE EXCEPTION 'Budget period is unavailable'; END IF;
  IF p_budget_amount IS NULL OR p_budget_amount < 0 THEN RAISE EXCEPTION 'Budget amount cannot be negative'; END IF;
  INSERT INTO public.finance_budget_lines(organization_id, budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type, budget_amount, notes, created_by)
  VALUES (v_org, p_budget_id, p_pl_period_id, p_cost_centre_id, p_service_agreement_id, p_cost_type, p_budget_amount, p_notes, v_actor)
  ON CONFLICT (budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type)
  DO UPDATE SET budget_amount = EXCLUDED.budget_amount, notes = EXCLUDED.notes
  RETURNING * INTO v_line;
  RETURN v_line;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."add_finance_budget_line"(p_budget_id uuid, p_pl_period_id uuid, p_cost_type text, p_budget_amount numeric, p_cost_centre_id uuid, p_service_agreement_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."add_finance_budget_line"(p_budget_id uuid, p_pl_period_id uuid, p_cost_type text, p_budget_amount numeric, p_cost_centre_id uuid, p_service_agreement_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."add_finance_budget_line"(p_budget_id uuid, p_pl_period_id uuid, p_cost_type text, p_budget_amount numeric, p_cost_centre_id uuid, p_service_agreement_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."add_finance_budget_line"(p_budget_id uuid, p_pl_period_id uuid, p_cost_type text, p_budget_amount numeric, p_cost_centre_id uuid, p_service_agreement_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."add_workshop_work_order_line"(p_client_request_id uuid, p_work_order_id uuid, p_line_kind text, p_item_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_quantity numeric DEFAULT 1, p_unit_price numeric DEFAULT NULL::numeric, p_unit_cost numeric DEFAULT NULL::numeric)
 RETURNS workshop_work_order_lines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wo public.workshop_work_orders%rowtype;
  v_actor uuid := auth.uid();
  v_role text;
  v_line public.workshop_work_order_lines%rowtype;
  v_cost numeric; v_price numeric;
  v_item public.finance_item_catalog%rowtype;
  v_pos integer;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_wo from public.workshop_work_orders w where w.id = p_work_order_id for update;
  if not found then raise exception 'Work order not found'; end if;
  v_role := public.workshop_line_actor_role(v_wo);
  select * into v_line from public.workshop_work_order_lines l where l.organization_id = v_wo.organization_id and l.client_request_id = p_client_request_id;
  if found then return v_line; end if;
  if v_wo.status in ('completed', 'cancelled') then raise exception 'Lines cannot be added once the work order is %', v_wo.status; end if;
  if p_line_kind not in ('material', 'labour', 'travel', 'equipment') then raise exception 'Line kind must be material, labour, travel or equipment'; end if;
  if coalesce(p_quantity, 0) <= 0 then raise exception 'Quantity must be above zero'; end if;
  if v_role = 'worker' and p_item_id is null then
    raise exception 'Pick the item from the price list — free-text lines and prices are set by a workshop administrator';
  end if;
  if p_item_id is not null then
    select * into v_item from public.finance_item_catalog i where i.id = p_item_id and i.organization_id = v_wo.organization_id and i.active;
    if not found then raise exception 'Item is not in this organisation''s price book'; end if;
    select cp.unit_cost, cp.unit_price into v_cost, v_price from public.workshop_current_prices(p_item_id) cp;
  end if;
  if nullif(trim(coalesce(p_description, '')), '') is null and v_item.id is null then raise exception 'Describe the line or pick a price-book item'; end if;
  select coalesce(max(position), 0) + 1 into v_pos from public.workshop_work_order_lines where work_order_id = v_wo.id;

  insert into public.workshop_work_order_lines (work_order_id, organization_id, client_request_id, line_kind, item_id, description, quantity, unit_of_measure, unit_cost, unit_price, position, created_by)
  values (v_wo.id, v_wo.organization_id, p_client_request_id, p_line_kind, v_item.id,
          coalesce(nullif(trim(coalesce(p_description, '')), ''), v_item.name), p_quantity, v_item.unit_of_measure,
          case when v_role = 'admin' then coalesce(p_unit_cost, v_cost, 0) else coalesce(v_cost, 0) end,
          case when v_role = 'admin' then coalesce(p_unit_price, v_price, 0) else coalesce(v_price, 0) end,
          v_pos, v_actor)
  returning * into v_line;
  update public.workshop_work_orders set updated_at = now(), updated_by = v_actor where id = v_wo.id;
  return v_line;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."add_workshop_work_order_line"(p_client_request_id uuid, p_work_order_id uuid, p_line_kind text, p_item_id uuid, p_description text, p_quantity numeric, p_unit_price numeric, p_unit_cost numeric) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."add_workshop_work_order_line"(p_client_request_id uuid, p_work_order_id uuid, p_line_kind text, p_item_id uuid, p_description text, p_quantity numeric, p_unit_price numeric, p_unit_cost numeric) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."add_workshop_work_order_line"(p_client_request_id uuid, p_work_order_id uuid, p_line_kind text, p_item_id uuid, p_description text, p_quantity numeric, p_unit_price numeric, p_unit_cost numeric) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."address_match_key"(p_address text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT NULLIF(regexp_replace(lower(trim(coalesce(p_address, ''))), '[^a-z0-9]+', '', 'g'), '')
$function$;
COMMENT ON FUNCTION "public"."address_match_key"(p_address text) IS 'The single address dedup key: lowercase, every non-alphanumeric run removed. Used by triggers on locations/client_sites; edge code mirrors it.';
REVOKE ALL ON FUNCTION "public"."address_match_key"(p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."address_match_key"(p_address text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."address_match_key"(p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."address_match_key"(p_address text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."address_match_key"(p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."address_match_key"(p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, status text, shift_id uuid, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job public.dispatch_jobs%rowtype;
  v_allowed boolean := false;
begin
  select * into v_job
  from public.dispatch_jobs
  where dispatch_jobs.id = p_job_id
  for update;

  if not found then raise exception 'Dispatch job not found'; end if;

  if not public.is_admin_for_org(v_job.organization_id) and not exists (
    select 1 from public.dispatch_resources dr
    where dr.id = v_job.dispatch_resource_id
      and dr.assigned_officer_id = auth.uid()
  ) then
    raise exception 'Not authorised to update this dispatch job';
  end if;

  if v_job.status <> p_expected_status then
    raise exception 'Dispatch job changed from expected status % to %', p_expected_status, v_job.status;
  end if;

  v_allowed := case v_job.status
    when 'pending' then p_next_status in ('dispatched', 'cancelled')
    when 'dispatched' then p_next_status in ('acknowledged', 'en_route', 'cancelled')
    when 'acknowledged' then p_next_status in ('en_route', 'cancelled')
    when 'en_route' then p_next_status in ('on_scene', 'cancelled')
    when 'on_scene' then p_next_status in ('completed', 'cancelled')
    else false
  end;

  if not v_allowed then
    raise exception 'Invalid dispatch transition from % to %', v_job.status, p_next_status;
  end if;

  if p_next_status in ('completed', 'cancelled') and nullif(trim(p_outcome_notes), '') is null then
    raise exception 'Outcome notes are required for terminal dispatch transitions';
  end if;

  update public.dispatch_jobs
  set status = p_next_status,
      acknowledged_at = case when p_next_status = 'acknowledged' then now() else dispatch_jobs.acknowledged_at end,
      en_route_at = case when p_next_status = 'en_route' then now() else dispatch_jobs.en_route_at end,
      on_scene_at = case when p_next_status = 'on_scene' then now() else dispatch_jobs.on_scene_at end,
      completed_at = case when p_next_status = 'completed' then now() else dispatch_jobs.completed_at end,
      outcome_notes = case when p_next_status in ('completed', 'cancelled') then nullif(trim(p_outcome_notes), '') else dispatch_jobs.outcome_notes end
  where dispatch_jobs.id = p_job_id;

  if p_next_status in ('completed', 'cancelled') and v_job.dispatch_resource_id is not null and not exists (
    select 1 from public.dispatch_jobs other
    where other.dispatch_resource_id = v_job.dispatch_resource_id
      and other.id <> p_job_id
      and other.status in ('dispatched', 'acknowledged', 'en_route', 'on_scene')
  ) then
    update public.dispatch_resources
    set status = 'available'
    where dispatch_resources.id = v_job.dispatch_resource_id;
  end if;

  -- Live financials on completion. Pay and charge lines are written now (unmatched rules
  -- become 'UNRESOLVED' rows for finance review); a failure here is recorded, not raised,
  -- so the officer's completion is never lost.
  if p_next_status = 'completed' then
    begin
      perform public.resolve_dispatch_job_financials_internal(auth.uid(), gen_random_uuid(), p_job_id, null);
    exception when others then
      insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
      values (v_job.organization_id, auth.uid(), 'dispatch_financials_auto_resolution_failed', 'dispatch_jobs', p_job_id, jsonb_build_object('error', sqlerrm));
    end;
  end if;

  return query select p_job_id, p_next_status, v_job.shift_id,
    case when p_next_status = 'completed' then now() else v_job.completed_at end;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."advance_dispatch_job_status"(p_job_id uuid, p_expected_status text, p_next_status text, p_outcome_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wo public.workshop_work_orders%rowtype;
  v_actor uuid := auth.uid();
  v_line record;
  v_tx public.finance_inventory_transactions%rowtype;
  v_on_hand numeric;
  v_is_admin boolean;
begin
  select * into v_wo from public.workshop_work_orders w where w.id = p_work_order_id for update;
  if not found then raise exception 'Work order not found'; end if;
  v_is_admin := public.is_admin_for_org(v_wo.organization_id);
  -- The assigned worker may start and complete; approving, cancelling and re-opening stay with an administrator.
  if not (v_is_admin or (v_wo.assigned_user_id = v_actor and p_status in ('in_progress', 'completed'))) then
    raise exception 'Only a workshop administrator or the assigned worker can move this work order';
  end if;
  if v_wo.status = p_status then return v_wo; end if;
  if not (
       (v_wo.status = 'draft' and p_status in ('approved', 'cancelled'))
    or (v_wo.status = 'approved' and p_status in ('in_progress', 'cancelled', 'draft'))
    or (v_wo.status = 'in_progress' and p_status in ('completed', 'cancelled'))
  ) then
    raise exception 'A % work order cannot move to %', v_wo.status, p_status;
  end if;

  if p_status = 'completed' then
    if not exists (select 1 from public.workshop_work_order_lines l where l.work_order_id = v_wo.id) then
      raise exception 'Add at least one line (materials, labour or travel) before completing';
    end if;
    -- Strict stock draw-down when the order names a stock location: every material/equipment line with a
    -- price-book item is consumed there. A shortfall stops completion with a plain message.
    if v_wo.inventory_location_id is not null then
      if not v_is_admin then
        raise exception 'This order draws stock from a location, so a workshop administrator must complete it (or clear the stock location first)';
      end if;
      for v_line in select l.* from public.workshop_work_order_lines l
                     where l.work_order_id = v_wo.id and l.line_kind in ('material', 'equipment') and l.item_id is not null and l.inventory_transaction_id is null
                     order by l.position loop
        select coalesce(b.on_hand - b.reserved, 0) into v_on_hand from public.finance_inventory_balances b where b.item_id = v_line.item_id and b.location_id = v_wo.inventory_location_id;
        if coalesce(v_on_hand, 0) < v_line.quantity then
          raise exception 'Not enough "%" in stock at this location (on hand %, needed %). Record the stock receipt first, or clear the stock location on the work order.',
            v_line.description, coalesce(v_on_hand, 0), v_line.quantity;
        end if;
        v_tx := public.record_finance_inventory_transaction(
          v_line.item_id, v_wo.inventory_location_id, 'consumption', v_line.quantity, v_line.unit_cost,
          'workshop_line:' || v_line.id::text, 'workshop_work_order:' || v_wo.order_number, null, v_wo.asset_id, null, null);
        update public.workshop_work_order_lines set inventory_transaction_id = v_tx.id where id = v_line.id;
      end loop;
    end if;
    update public.workshop_work_orders
       set status = 'completed', completed_at = now(), completion_note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now(), updated_by = v_actor
     where id = v_wo.id returning * into v_wo;
  elsif p_status = 'in_progress' then
    update public.workshop_work_orders set status = 'in_progress', started_at = coalesce(started_at, now()), updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  elsif p_status = 'cancelled' then
    update public.workshop_work_orders set status = 'cancelled', cancelled_at = now(), completion_note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  else
    update public.workshop_work_orders set status = p_status, updated_at = now(), updated_by = v_actor where id = v_wo.id returning * into v_wo;
  end if;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_wo.organization_id, v_actor, 'workshop_work_order_' || p_status, 'workshop_work_orders', v_wo.id,
          jsonb_build_object('order_number', v_wo.order_number, 'kind', v_wo.kind, 'note', nullif(trim(coalesce(p_note, '')), ''),
                             'charge_total', (select coalesce(sum(line_total), 0) from public.workshop_work_order_lines where work_order_id = v_wo.id)));
  return v_wo;
end;
$function$;
COMMENT ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) IS 'draft→approved→in_progress→completed (cancel from any open state). Completion draws material/equipment lines down from the named stock location through record_finance_inventory_transaction and leaves the lines billable for generate_crm_invoice_from_completed_work.';
REVOKE ALL ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."advance_workshop_work_order_status"(p_work_order_id uuid, p_status text, p_note text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_actor public.user_profiles%rowtype;
  v_rule public.rate_rules%rowtype;
begin
  select * into v_action from public.bob_agentic_actions where id=p_action_id for update;
  if not found or v_action.action_type<>'create_rate_rule' or v_action.status<>'approved' then raise exception 'Only approved create_rate_rule actions can be executed'; end if;
  if v_action.result_record_id is not null then return v_action.result_record_id; end if;
  select * into v_actor from public.user_profiles where id=v_action.approved_by and deactivated_at is null;
  if not found or v_actor.organization_id<>v_action.organization_id or not public.is_admin_for_org(v_action.organization_id) then raise exception 'An active finance administrator approval is required'; end if;
  v_payload:=coalesce(v_action.amended_payload,v_action.proposed_payload);
  if nullif(trim(coalesce(v_payload->>'name','')),'') is null or v_payload->>'rule_kind' not in ('pay','billing') or v_payload->>'rate_type' not in ('hourly','flat','daily','per_km','per_unit','percentage','per_hour_travel','per_hour_allowance','oncall_flat','callout','higher_duties_flat','per_visit','per_notice') or (v_payload->>'amount')::numeric<0 then raise exception 'Approved rate-rule proposal is invalid'; end if;
  insert into public.rate_rules(organization_id,rule_kind,name,rate_type,amount,pay_code,service_type,job_type,day_category,priority,active,created_by,updated_by,client_request_id)
  values(v_action.organization_id,v_payload->>'rule_kind',trim(v_payload->>'name'),v_payload->>'rate_type',(v_payload->>'amount')::numeric,nullif(trim(coalesce(v_payload->>'pay_code','')),''),nullif(trim(coalesce(v_payload->>'service_type','')),''),nullif(trim(coalesce(v_payload->>'job_type','')),''),nullif(trim(coalesce(v_payload->>'day_category','')),''),coalesce((v_payload->>'priority')::integer,0),true,v_action.approved_by,v_action.approved_by,gen_random_uuid()) returning * into v_rule;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_rule.organization_id,v_action.approved_by,'bob_rate_rule_proposal_applied','rate_rules',v_rule.id,jsonb_build_object('action_id',v_action.id));
  return v_rule.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_rate_rule_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid)
 RETURNS TABLE(plan_id uuid, assignments_applied integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action public.bob_agentic_actions%rowtype;
  v_payload jsonb;
  v_plan public.bob_roster_plans%rowtype;
  v_item jsonb;
  v_slot public.roster_slots%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_count integer := 0;
  v_actor uuid;
begin
  select a.* into v_action from public.bob_agentic_actions a where a.id = p_action_id for update;
  if not found then raise exception 'Bob action not found'; end if;
  if v_action.action_type <> 'apply_roster_fill_plan' or v_action.status <> 'approved' then
    raise exception 'Only approved apply_roster_fill_plan actions can be executed';
  end if;

  select p.* into v_plan from public.bob_roster_plans p where p.action_id = v_action.id;
  if found then
    return query select v_plan.id, (select count(*)::integer from public.bob_roster_plan_slots where bob_roster_plan_slots.plan_id = v_plan.id);
    return;
  end if;

  v_payload := coalesce(v_action.amended_payload, v_action.proposed_payload);
  if jsonb_typeof(v_payload->'assignments') <> 'array' or jsonb_array_length(v_payload->'assignments') = 0 then
    raise exception 'Roster plan requires at least one assignment';
  end if;

  v_actor := v_action.approved_by;
  insert into public.bob_roster_plans(organization_id, action_id, period_start, period_end, applied_by)
  values (
    v_action.organization_id, v_action.id,
    (v_payload->>'period_start')::timestamptz,
    (v_payload->>'period_end')::timestamptz,
    v_actor
  ) returning * into v_plan;

  for v_item in select value from jsonb_array_elements(v_payload->'assignments') loop
    select s.* into v_slot from public.roster_slots s where s.id = (v_item->>'roster_slot_id')::uuid for update;
    if not found or v_slot.organization_id <> v_action.organization_id then
      raise exception 'Proposed roster slot is unavailable';
    end if;
    if v_slot.status <> 'draft' or v_slot.staff_id is not null then
      raise exception 'Roster slot % changed after Bob proposed it; revise the plan', v_slot.id;
    end if;

    select sp.* into v_staff from public.staff_profiles sp where sp.id = (v_item->>'staff_id')::uuid;
    if not found or v_staff.organization_id <> v_action.organization_id or not v_staff.work_ready then
      raise exception 'Proposed staff member is unavailable';
    end if;
    if public.staff_has_roster_availability_conflict(v_staff.id, v_slot.scheduled_start, v_slot.scheduled_end)
      or public.staff_fatigue_conflict(v_staff.id, v_slot.scheduled_start, v_slot.scheduled_end, v_slot.id) is not null then
      raise exception 'Proposed staff member no longer meets availability or fatigue requirements';
    end if;

    update public.roster_slots set staff_id = v_staff.id where id = v_slot.id;
    insert into public.bob_roster_plan_slots(plan_id, roster_slot_id, staff_id, score, rationale)
    values (v_plan.id, v_slot.id, v_staff.id, coalesce((v_item->>'score')::numeric, 0), coalesce(nullif(trim(v_item->>'rationale'), ''), 'Bob roster proposal'));
    v_count := v_count + 1;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_action.organization_id, v_actor, 'bob_roster_plan_applied', 'bob_roster_plans', v_plan.id,
    jsonb_build_object('action_id', v_action.id, 'assignments_applied', v_count));

  return query select v_plan.id, v_count;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_roster_fill_plan"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.bob_agentic_actions%rowtype; sp public.staff_profiles%rowtype; l public.staff_onboarding_ledgers%rowtype; p jsonb; approver public.user_profiles%rowtype;
begin
 select * into a from public.bob_agentic_actions where id=p_action_id for update;
 if not found or a.action_type<>'start_staff_onboarding' or a.status<>'approved' then raise exception 'Only approved start_staff_onboarding actions can be executed'; end if;
 if a.result_record_id is not null then return a.result_record_id; end if;
 select * into approver from public.user_profiles where id=a.approved_by and deactivated_at is null;
 if not found or approver.organization_id<>a.organization_id or not public.is_admin_for_org(a.organization_id) then raise exception 'An active HR administrator approval is required'; end if;
 p:=coalesce(a.amended_payload,a.proposed_payload);
 select * into sp from public.staff_profiles where id=(p->>'staff_id')::uuid and organization_id=a.organization_id for update;
 if not found then raise exception 'Proposed staff profile is unavailable'; end if;
 select * into l from public.staff_onboarding_ledgers where staff_id=sp.id;
 if found then return l.id; end if;
 insert into public.staff_onboarding_ledgers(organization_id,staff_id,assigned_to,target_start,stage_note) values(a.organization_id,sp.id,nullif(p->>'assigned_to','')::uuid,nullif(p->>'target_start','')::date,coalesce(nullif(trim(p->>'note'),''),'Bob proposed onboarding start')) returning * into l;
 insert into public.staff_onboarding_events(ledger_id,organization_id,to_stage,to_status,note,actor_user_id,version) values(l.id,l.organization_id,l.current_stage,l.status,l.stage_note,a.approved_by,l.version);
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(a.organization_id,a.approved_by,'bob_staff_onboarding_started','staff_onboarding_ledgers',l.id,jsonb_build_object('action_id',a.id,'staff_id',sp.id));
 return l.id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_bob_staff_onboarding_proposal"(p_action_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text DEFAULT NULL::text, p_issuing_authority text DEFAULT NULL::text, p_issued_date date DEFAULT NULL::date, p_expiry_date date DEFAULT NULL::date, p_authorized_activities text[] DEFAULT '{}'::text[])
 RETURNS TABLE(proposal_id uuid, credential_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_org_id uuid;
  v_storage_path text;
  v_credential_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_credential_type NOT IN ('certificate_of_authority','warrant_of_authority','drivers_licence','first_aid','security_licence','firearms_licence','noise_control_warrant','biosecurity_warrant','other') THEN RAISE EXCEPTION 'Unsupported credential type'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'credential' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved credential proposals can be applied'; END IF;
  SELECT sp.organization_id INTO v_org_id FROM public.staff_profiles sp WHERE sp.id = p_staff_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_org_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Staff profile is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Credential application denied'; END IF;
  SELECT d.storage_object_ref INTO v_storage_path FROM public.document_versions dv JOIN public.documents d ON d.id = dv.document_id WHERE dv.id = v_proposal.document_version_id;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_credential_id FROM public.staff_credentials WHERE staff_id = p_staff_id AND organization_id = v_org_id AND credential_type = p_credential_type AND credential_number IS NOT DISTINCT FROM p_credential_number AND expiry_date IS NOT DISTINCT FROM p_expiry_date LIMIT 1;
  IF v_credential_id IS NULL THEN
    INSERT INTO public.staff_credentials (staff_id, organization_id, credential_type, credential_number, issuing_authority, issued_date, expiry_date, authorized_activities, document_storage_path, verified, notes, client_request_id)
    VALUES (p_staff_id, v_org_id, p_credential_type, nullif(trim(p_credential_number), ''), nullif(trim(p_issuing_authority), ''), p_issued_date, p_expiry_date, coalesce(p_authorized_activities, '{}'::text[]), v_storage_path, false, 'Created from document promotion proposal ' || v_proposal.id::text, v_proposal.id)
    RETURNING id INTO v_credential_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_credential_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_promotion_proposal_applied', 'staff_credentials', v_credential_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'verified', false));
  RETURN QUERY SELECT v_proposal.id, v_credential_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_credential_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_credential_type text, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_authorized_activities text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date DEFAULT NULL::date, p_ends_on date DEFAULT NULL::date, p_enabled_modules text[] DEFAULT '{}'::text[])
 RETURNS TABLE(proposal_id uuid, agreement_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_agreement_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_name, '')), '') IS NULL THEN RAISE EXCEPTION 'Agreement name is required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Promotion proposal not found'; END IF;
  IF v_proposal.target_type <> 'crm_agreement' OR v_proposal.status <> 'approved' THEN
    RAISE EXCEPTION 'Only approved CRM agreement proposals can be applied';
  END IF;
  IF NOT public.is_admin_for_org(p_provider_organization_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'CRM agreement application denied';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_client_organization_id AND active) THEN
    RAISE EXCEPTION 'Active client organisation is required';
  END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN
    RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false;
    RETURN;
  END IF;
  SELECT id INTO v_agreement_id
  FROM public.service_agreements
  WHERE provider_organization_id = p_provider_organization_id
    AND client_organization_id = p_client_organization_id
    AND name = trim(p_name)
  LIMIT 1;
  IF v_agreement_id IS NULL THEN
    INSERT INTO public.service_agreements (provider_organization_id, client_organization_id, name, starts_on, ends_on, agreement_type, invitation_status, enabled_modules, external_refs)
    VALUES (p_provider_organization_id, p_client_organization_id, trim(p_name), p_starts_on, p_ends_on, 'operational', 'not_invited', coalesce(p_enabled_modules, '{}'::text[]), jsonb_build_object('document_promotion_proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id))
    RETURNING id INTO v_agreement_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals
  SET status = 'applied', applied_target_id = v_agreement_id, applied_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'service_agreements', v_agreement_id,
    jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created));
  RETURN QUERY SELECT v_proposal.id, v_agreement_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_crm_agreement_promotion_proposal"(p_proposal_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_name text, p_starts_on date, p_ends_on date, p_enabled_modules text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb DEFAULT '[]'::jsonb, p_people jsonb DEFAULT '[]'::jsonb, p_slots jsonb DEFAULT '[]'::jsonb, p_leave jsonb DEFAULT '[]'::jsonb, p_manifest jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_batch public.file_import_batches%rowtype;
  v_existing jsonb;
  v_item jsonb;
  v_unit_id uuid;
  v_workplace_id uuid;
  v_staff_id uuid;
  v_units jsonb := '{}'::jsonb;         -- deputy location code -> work unit id
  v_people jsonb := '{}'::jsonb;        -- deputy export code -> staff id
  v_units_created integer := 0;
  v_units_matched integer := 0;
  v_people_matched integer := 0;
  v_slots_created integer := 0;
  v_slots_existing integer := 0;
  v_slots_unresolved integer := 0;
  v_leave_created integer := 0;
  v_leave_existing integer := 0;
  v_leave_unresolved integer := 0;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if not public.is_admin_for_org(p_operating_organization_id) then
    raise exception 'Active authorized operating branch administrator required';
  end if;

  -- Replay: the batch already exists for this request id.
  select manifest_json->'receipt' into v_existing from public.file_import_batches
  where organization_id = p_operating_organization_id and parser = 'deputy_roster' and manifest_json->>'client_request_id' = p_client_request_id::text
  limit 1;
  if v_existing is not null then return v_existing; end if;

  -- 1. Places: match to an existing work unit, or create internal work (workplace + unit).
  for v_item in select * from jsonb_array_elements(coalesce(p_locations, '[]'::jsonb)) loop
    if v_item->>'action' = 'match' and (v_item->>'work_unit_id') is not null then
      select id into v_unit_id from public.roster_work_units
      where id = (v_item->>'work_unit_id')::uuid and organization_id = p_operating_organization_id and active;
      if v_unit_id is null then raise exception 'Work unit % is not an active unit of this branch', v_item->>'work_unit_id'; end if;
      update public.roster_work_units
      set external_refs = external_refs || jsonb_build_object('deputy', jsonb_build_object('code', v_item->>'deputy_code', 'name', v_item->>'deputy_name')), updated_at = now()
      where id = v_unit_id;
      v_units_matched := v_units_matched + 1;
    elsif v_item->>'action' = 'create_internal' then
      select id into v_unit_id from public.roster_work_units
      where organization_id = p_operating_organization_id and external_refs->'deputy'->>'code' = v_item->>'deputy_code' limit 1;
      if v_unit_id is null then
        insert into public.organization_workplaces(organization_id, name, active, created_by)
        values (p_operating_organization_id, v_item->>'deputy_name', true, v_actor)
        returning id into v_workplace_id;
        insert into public.roster_work_units(organization_id, name, work_unit_type, service_type, workplace_id, active, created_by, external_refs)
        values (p_operating_organization_id, v_item->>'deputy_name', 'internal', coalesce(nullif(trim(v_item->>'service_type'), ''), 'administration'), v_workplace_id, true, v_actor,
          jsonb_build_object('deputy', jsonb_build_object('code', v_item->>'deputy_code', 'name', v_item->>'deputy_name', 'areas', coalesce(v_item->'areas', '[]'::jsonb))))
        returning id into v_unit_id;
        v_units_created := v_units_created + 1;
      else
        v_units_matched := v_units_matched + 1;
      end if;
    else
      continue;
    end if;
    v_units := v_units || jsonb_build_object(v_item->>'deputy_code', v_unit_id);
  end loop;

  -- 2. People: only admin-confirmed matches to existing staff of this branch; nothing is created.
  for v_item in select * from jsonb_array_elements(coalesce(p_people, '[]'::jsonb)) loop
    if (v_item->>'staff_id') is null then continue; end if;
    select sp.id into v_staff_id from public.staff_profiles sp
    where sp.id = (v_item->>'staff_id')::uuid and sp.organization_id = p_operating_organization_id;
    if v_staff_id is null then raise exception 'Staff % does not belong to this branch', v_item->>'staff_id'; end if;
    update public.staff_profiles
    set external_refs = external_refs || jsonb_build_object('deputy_export_code', v_item->>'export_code')
    where id = v_staff_id;
    v_people := v_people || jsonb_build_object(v_item->>'export_code', v_staff_id);
    v_people_matched := v_people_matched + 1;
  end loop;

  -- 3. Schedules -> draft roster slots, idempotent on the deterministic slot key.
  for v_item in select * from jsonb_array_elements(coalesce(p_slots, '[]'::jsonb)) loop
    v_unit_id := nullif(v_units->>(v_item->>'deputy_code'), '')::uuid;
    v_staff_id := nullif(v_people->>(v_item->>'export_code'), '')::uuid;
    if v_unit_id is null or v_staff_id is null then v_slots_unresolved := v_slots_unresolved + 1; continue; end if;
    if (v_item->>'starts_at')::timestamptz >= (v_item->>'ends_at')::timestamptz then v_slots_unresolved := v_slots_unresolved + 1; continue; end if;
    insert into public.roster_slots(organization_id, work_unit_id, staff_id, scheduled_start, scheduled_end, status, client_request_id, notes, created_by, external_refs)
    values (p_operating_organization_id, v_unit_id, v_staff_id, (v_item->>'starts_at')::timestamptz, (v_item->>'ends_at')::timestamptz, 'draft', (v_item->>'key')::uuid,
      nullif(trim(coalesce(v_item->>'notes', '')), ''), v_actor,
      jsonb_strip_nulls(jsonb_build_object(
        'source', 'deputy',
        'deputy_location_code', v_item->>'deputy_code', 'deputy_location_name', v_item->>'deputy_name',
        'area_name', v_item->>'area_name', 'area_export_code', v_item->>'area_code', 'pay_code', v_item->>'pay_code',
        'ems_minutes', (v_item->>'ems_minutes')::integer, 'ncr_minutes', (v_item->>'ncr_minutes')::integer,
        'purchase_order', nullif(v_item->>'purchase_order', ''), 'req_ritm', nullif(v_item->>'req_ritm', ''),
        'schedule_warning', nullif(v_item->>'warning', ''), 'deputy_published', (v_item->>'published')::boolean)))
    on conflict (organization_id, client_request_id) do nothing;
    if found then v_slots_created := v_slots_created + 1; else v_slots_existing := v_slots_existing + 1; end if;
  end loop;

  -- 4. Leave -> approved leave, idempotent on client_event_id.
  for v_item in select * from jsonb_array_elements(coalesce(p_leave, '[]'::jsonb)) loop
    v_staff_id := nullif(v_people->>(v_item->>'export_code'), '')::uuid;
    if v_staff_id is null then v_leave_unresolved := v_leave_unresolved + 1; continue; end if;
    if (v_item->>'leave_type') not in ('annual', 'sick', 'bereavement', 'parental', 'unpaid', 'other') then v_leave_unresolved := v_leave_unresolved + 1; continue; end if;
    if exists (select 1 from public.leave_requests where client_event_id = (v_item->>'key')::uuid) then v_leave_existing := v_leave_existing + 1; continue; end if;
    insert into public.leave_requests(staff_id, organization_id, leave_type, starts_on, ends_on, status, reason, approved_by, approved_at, notes, client_event_id)
    values (v_staff_id, p_operating_organization_id, v_item->>'leave_type', (v_item->>'starts_on')::date, (v_item->>'ends_on')::date,
      case when v_item->>'status' = 'Approved' then 'approved' else 'pending' end,
      'Imported from Deputy: ' || coalesce(v_item->>'deputy_type', 'leave'),
      case when v_item->>'status' = 'Approved' then v_actor end, case when v_item->>'status' = 'Approved' then now() end,
      case when nullif(trim(coalesce(v_item->>'hours', '')), '') is not null then 'Deputy hours: ' || trim(v_item->>'hours') end,
      (v_item->>'key')::uuid);
    v_leave_created := v_leave_created + 1;
  end loop;

  v_receipt := jsonb_build_object(
    'work_units_created', v_units_created, 'work_units_matched', v_units_matched, 'people_matched', v_people_matched,
    'slots_created', v_slots_created, 'slots_already_imported', v_slots_existing, 'slots_unresolved', v_slots_unresolved,
    'leave_created', v_leave_created, 'leave_already_imported', v_leave_existing, 'leave_unresolved', v_leave_unresolved,
    'timesheets_not_imported', coalesce((p_manifest->>'timesheet_rows')::integer, 0));

  insert into public.file_import_batches(organization_id, batch_name, source_file, source_sha256, parser, status, manifest_json, schema_json, row_count, duplicate_count, unresolved_count, created_by, reviewed_by, reviewed_at, review_reason)
  values (p_operating_organization_id, 'Deputy roster import ' || to_char(now() at time zone 'Pacific/Auckland', 'DD Mon YYYY HH24:MI'), coalesce(p_source_file, 'deputy.csv'), p_source_sha256, 'deputy_roster', 'applied',
    coalesce(p_manifest, '{}'::jsonb) || jsonb_build_object('client_request_id', p_client_request_id, 'receipt', v_receipt),
    jsonb_build_object('locations', (select coalesce(jsonb_agg(l - 'areas'), '[]'::jsonb) from jsonb_array_elements(coalesce(p_locations, '[]'::jsonb)) l), 'people_matched', v_people_matched),
    greatest(coalesce(p_row_count, 0), 0), v_slots_existing + v_leave_existing, v_slots_unresolved + v_leave_unresolved, v_actor, v_actor, now(), 'Applied through the Deputy import walkthrough')
  returning * into v_batch;

  v_receipt := v_receipt || jsonb_build_object('batch_id', v_batch.id);
  update public.file_import_batches set manifest_json = manifest_json || jsonb_build_object('receipt', v_receipt) where id = v_batch.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_operating_organization_id, v_actor, 'deputy_roster_import_applied', 'file_import_batches', v_batch.id, v_receipt);

  return v_receipt;
end;
$function$;
COMMENT ON FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb, p_people jsonb, p_slots jsonb, p_leave jsonb, p_manifest jsonb) IS 'Apply an admin-reviewed Deputy export: Deputy Locations -> existing work units (or new internal workplace+unit), Deputy people -> existing staff only (never creates identities), Schedules -> draft roster_slots keyed on a deterministic client_request_id with billing evidence in external_refs, Is Leave -> leave_requests keyed on client_event_id. Timesheet actuals are counted, not imported. Records a file_import_batches row (parser deputy_roster) and an audit event; idempotent on client_request_id.';
REVOKE ALL ON FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb, p_people jsonb, p_slots jsonb, p_leave jsonb, p_manifest jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb, p_people jsonb, p_slots jsonb, p_leave jsonb, p_manifest jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb, p_people jsonb, p_slots jsonb, p_leave jsonb, p_manifest jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_deputy_roster_import"(p_client_request_id uuid, p_operating_organization_id uuid, p_source_file text, p_source_sha256 text, p_row_count integer, p_locations jsonb, p_people jsonb, p_slots jsonb, p_leave jsonb, p_manifest jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_invoice_number text DEFAULT NULL::text, p_invoice_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT NULL::date, p_subtotal numeric DEFAULT 0, p_gst_amount numeric DEFAULT 0, p_total_amount numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, invoice_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_invoice_id uuid;
  v_due_date date := coalesce(p_due_date, p_invoice_date + 20);
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'finance_reconciliation' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved finance proposals can be applied'; END IF;
  IF NOT public.is_admin_for_org(v_proposal.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Finance proposal application denied'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_client_organization_id AND organization_type = 'client' AND active) THEN RAISE EXCEPTION 'Active client organisation is required'; END IF;
  IF p_invoice_number IS NULL OR nullif(trim(p_invoice_number), '') IS NULL THEN RAISE EXCEPTION 'Invoice number is required'; END IF;
  IF p_invoice_date IS NULL OR v_due_date < p_invoice_date THEN RAISE EXCEPTION 'Valid invoice and due dates are required'; END IF;
  IF p_subtotal < 0 OR p_gst_amount < 0 OR p_total_amount <= 0 OR p_total_amount <> p_subtotal + p_gst_amount THEN RAISE EXCEPTION 'Invoice totals must be positive and reconcile'; END IF;
  IF p_service_agreement_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_agreements WHERE id = p_service_agreement_id AND provider_organization_id = v_proposal.organization_id AND client_organization_id = p_client_organization_id) THEN RAISE EXCEPTION 'Service agreement does not match provider and client'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_invoice_id FROM public.invoices WHERE organization_id = v_proposal.organization_id AND invoice_number = trim(p_invoice_number) LIMIT 1;
  IF v_invoice_id IS NULL THEN
    INSERT INTO public.invoices (organization_id, client_organization_id, service_agreement_id, invoice_number, invoice_date, due_date, status, subtotal, gst_amount, total_amount, currency, notes, created_by)
    VALUES (v_proposal.organization_id, p_client_organization_id, p_service_agreement_id, trim(p_invoice_number), p_invoice_date, v_due_date, 'draft', p_subtotal, p_gst_amount, p_total_amount, 'NZD', concat_ws(E'\n', nullif(trim(p_notes), ''), 'Created from document promotion proposal ' || v_proposal.id::text || ' / version ' || v_proposal.document_version_id::text), v_actor)
    RETURNING id INTO v_invoice_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_invoice_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'invoices', v_invoice_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'status', 'draft'));
  RETURN QUERY SELECT v_proposal.id, v_invoice_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_finance_reconciliation_proposal"(p_proposal_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_invoice_number text, p_invoice_date date, p_due_date date, p_subtotal numeric, p_gst_amount numeric, p_total_amount numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, staff_document_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_org_id uuid;
  v_document_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_document_type NOT IN ('credential_evidence','contract','certificate','policy_acknowledgement','other') THEN RAISE EXCEPTION 'Unsupported staff document type'; END IF;
  IF nullif(trim(coalesce(p_file_name, '')), '') IS NULL OR nullif(trim(coalesce(p_storage_path, '')), '') IS NULL THEN RAISE EXCEPTION 'File name and secure storage path are required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'hr_case' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved HR proposals can be applied'; END IF;
  SELECT sp.organization_id INTO v_org_id FROM public.staff_profiles sp WHERE sp.id = p_staff_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_org_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Staff profile is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'HR document application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  SELECT id INTO v_document_id FROM public.staff_documents WHERE staff_id = p_staff_id AND organization_id = v_org_id AND storage_path = trim(p_storage_path) LIMIT 1;
  IF v_document_id IS NULL THEN
    INSERT INTO public.staff_documents (staff_id, organization_id, document_type, file_name, storage_path, expiry_date, notes, uploaded_by)
    VALUES (p_staff_id, v_org_id, p_document_type, trim(p_file_name), trim(p_storage_path), p_expiry_date, nullif(trim(p_notes), ''), v_actor)
    RETURNING id INTO v_document_id;
    v_created := true;
  END IF;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_document_id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_promotion_proposal_applied', 'staff_documents', v_document_id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'document_type', p_document_type));
  RETURN QUERY SELECT v_proposal.id, v_document_id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_hr_document_promotion_proposal"(p_proposal_id uuid, p_staff_id uuid, p_document_type text, p_file_name text, p_storage_path text, p_expiry_date date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text DEFAULT 'supporting'::text, p_link_reason text DEFAULT NULL::text)
 RETURNS TABLE(proposal_id uuid, link_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_investigation public.investigations%rowtype;
  v_link public.investigation_links%rowtype;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_entity_type NOT IN ('observation','field_report','incident','evidence','site','zone','person','vehicle','dispatch_job') THEN RAISE EXCEPTION 'Unsupported investigation entity type'; END IF;
  IF p_link_role NOT IN ('primary','supporting','context','lead','excluded') THEN RAISE EXCEPTION 'Unsupported investigation link role'; END IF;
  IF nullif(trim(coalesce(p_link_reason, '')), '') IS NULL THEN RAISE EXCEPTION 'Investigation link reason is required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'investigation_link' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved investigation-link proposals can be applied'; END IF;
  SELECT * INTO v_investigation FROM public.investigations WHERE id = p_investigation_id FOR UPDATE;
  IF NOT FOUND OR v_investigation.organization_id <> v_proposal.organization_id THEN RAISE EXCEPTION 'Investigation is outside proposal organisation'; END IF;
  IF NOT public.is_admin_for_org(v_investigation.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Investigation link application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  v_link := public.link_investigation_entity(p_investigation_id, p_entity_type, p_entity_id, p_link_role, trim(p_link_reason));
  IF v_link.id IS NULL THEN RAISE EXCEPTION 'Investigation link receipt was not confirmed'; END IF;
  v_created := true;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_link.id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'investigation_links', v_link.id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'entity_type', p_entity_type, 'entity_id', p_entity_id));
  RETURN QUERY SELECT v_proposal.id, v_link.id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_investigation_link_promotion_proposal"(p_proposal_id uuid, p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(proposal_id uuid, work_unit_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_proposal public.document_promotion_proposals%rowtype;
  v_unit public.roster_work_units%rowtype;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_proposal FROM public.document_promotion_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR v_proposal.target_type <> 'site_brief' OR v_proposal.status <> 'approved' THEN RAISE EXCEPTION 'Only approved site brief proposals can be applied'; END IF;
  IF NOT public.is_admin_for_org(v_proposal.organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Site brief application denied'; END IF;
  IF v_proposal.applied_target_id IS NOT NULL THEN RETURN QUERY SELECT v_proposal.id, v_proposal.applied_target_id, false; RETURN; END IF;
  IF p_work_unit_type NOT IN ('patrol','static','internal') THEN RAISE EXCEPTION 'Unsupported work unit type'; END IF;
  IF nullif(trim(coalesce(p_name, '')), '') IS NULL OR nullif(trim(coalesce(p_service_type, '')), '') IS NULL THEN RAISE EXCEPTION 'Work unit name and service type are required'; END IF;
  SELECT * INTO v_unit FROM public.create_roster_work_unit(trim(p_name), p_work_unit_type, trim(p_service_type), p_patrol_route_id, p_service_agreement_location_id, p_service_agreement_module_id, p_workplace_id, p_team_id, p_cost_centre_id);
  IF v_unit.id IS NULL THEN RAISE EXCEPTION 'Work unit creation was not confirmed'; END IF;
  v_created := true;
  UPDATE public.document_promotion_proposals SET status = 'applied', applied_target_id = v_unit.id, applied_at = clock_timestamp(), updated_at = clock_timestamp() WHERE id = v_proposal.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_proposal.organization_id, v_actor, 'document_promotion_proposal_applied', 'roster_work_units', v_unit.id, jsonb_build_object('proposal_id', v_proposal.id, 'document_version_id', v_proposal.document_version_id, 'created', v_created, 'work_unit_type', p_work_unit_type));
  RETURN QUERY SELECT v_proposal.id, v_unit.id, v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."apply_site_brief_promotion_proposal"(p_proposal_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
BEGIN
  IF actor_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_approval_state NOT IN ('submitted', 'approved', 'rejected') THEN RAISE EXCEPTION 'Invalid export approval state'; END IF;
  SELECT * INTO export_row FROM public.cctv_exports WHERE id = p_export_id FOR UPDATE;
  IF NOT FOUND OR NOT public.org_access_allowed(export_row.organization_id) THEN RAISE EXCEPTION 'CCTV export not found or access denied'; END IF;
  IF export_row.approval_state IN ('sealed', 'issued') THEN RAISE EXCEPTION 'Sealed exports cannot be changed'; END IF;

  UPDATE public.cctv_exports
     SET approval_state = p_approval_state,
         approved_by = CASE WHEN p_approval_state = 'approved' THEN actor_id ELSE NULL END,
         approved_at = CASE WHEN p_approval_state = 'approved' THEN clock_timestamp() ELSE NULL END
   WHERE id = p_export_id
   RETURNING * INTO export_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (export_row.organization_id, actor_id, 'cctv_export_approval_changed', 'cctv_exports', p_export_id,
    jsonb_build_object('approval_state', p_approval_state));
  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_export"(p_export_id uuid, p_approval_state text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid DEFAULT NULL::uuid, p_review_notes text DEFAULT NULL::text)
 RETURNS cctv_identity_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  draft_row public.cctv_identity_drafts;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'User must be authenticated to approve a draft identity';
  END IF;

  SELECT * INTO draft_row
    FROM public.cctv_identity_drafts
   WHERE id = p_draft_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Identity draft not found';
  END IF;

  IF NOT public.org_access_allowed(draft_row.organization_id) THEN
    RAISE EXCEPTION 'Identity draft access denied';
  END IF;

  IF p_final_action NOT IN ('approve_draft', 'create_new_record', 'match_existing', 'reject', 'relocate', 'manual_review') THEN
    RAISE EXCEPTION 'Invalid final action';
  END IF;

  IF p_final_action IN ('match_existing', 'relocate', 'approve_draft') AND p_final_person_record_id IS NULL THEN
    RAISE EXCEPTION 'Final person record is required for an identity action';
  END IF;

  IF p_final_person_record_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.person_records
    WHERE id = p_final_person_record_id
      AND organization_id = draft_row.organization_id
  ) THEN
    RAISE EXCEPTION 'Final person record is not in the draft organization';
  END IF;

  IF p_final_action = 'create_new_record' THEN
    RAISE EXCEPTION 'Create the new canonical record before approving this draft';
  END IF;

  UPDATE public.cctv_identity_drafts
     SET status = CASE
       WHEN p_final_action = 'reject' THEN 'rejected'
       WHEN p_final_action = 'manual_review' THEN 'escalated'
       WHEN p_final_action = 'relocate' THEN 'relocated'
       WHEN p_final_action = 'create_new_record' THEN 'approved'
       WHEN p_final_action = 'match_existing' THEN 'approved'
       WHEN p_final_action = 'approve_draft' THEN 'approved'
       ELSE 'draft'
     END,
     authority_level = CASE
       WHEN p_final_action = 'reject' THEN 'provisional'
       ELSE 'approved'
     END,
     final_action = p_final_action,
     final_person_record_id = p_final_person_record_id,
     review_notes = NULLIF(trim(p_review_notes), ''),
     approved_by = auth.uid(),
     approved_at = clock_timestamp(),
     updated_at = clock_timestamp()
   WHERE id = p_draft_id
   RETURNING * INTO draft_row;

  RETURN draft_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_cctv_identity_draft"(p_draft_id uuid, p_final_action text, p_final_person_record_id uuid, p_review_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."approve_finance_budget"(p_budget_id uuid)
 RETURNS finance_budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_budget public.finance_budgets%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_budget FROM public.finance_budgets WHERE id = p_budget_id AND organization_id = v_org FOR UPDATE;
  IF NOT FOUND OR v_budget.status <> 'draft' THEN RAISE EXCEPTION 'Only draft budgets can be approved'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.finance_budget_lines WHERE budget_id = p_budget_id) THEN RAISE EXCEPTION 'Budget requires at least one line'; END IF;
  UPDATE public.finance_budgets SET status = 'approved', approved_by = v_actor, approved_at = now(), updated_at = now() WHERE id = p_budget_id RETURNING * INTO v_budget;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_budget_approved', 'finance_budgets', v_budget.id, jsonb_build_object('version', v_budget.version));
  RETURN v_budget;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."approve_finance_budget"(p_budget_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_branch public.organizations%rowtype;
  v_key text;
begin
  select * into v_branch from public.organizations where id = p_branch_organization_id for update;
  if not found or v_branch.organization_type <> 'branch' then raise exception 'Branch not found'; end if;
  if v_actor is null or not public.user_can_operate_organization(v_branch.parent_organization_id) or not public.is_admin_for_org(v_branch.parent_organization_id) then
    raise exception 'Active organisation administrator required';
  end if;
  if v_branch.status = 'archived' then return v_branch; end if;
  if p_expected_updated_at is not null and v_branch.updated_at <> p_expected_updated_at then raise exception 'Branch changed since it was opened'; end if;
  if exists (select 1 from public.user_profiles u where u.organization_id = v_branch.id and u.deactivated_at is null) then
    raise exception 'Move or deactivate the branch''s staff before archiving it';
  end if;
  if exists (select 1 from public.organizations c where c.parent_organization_id = v_branch.id and c.status <> 'archived') then
    raise exception 'Archive the branch''s own branches first';
  end if;

  for v_key in
    select om.module_key from public.organization_modules om
    where om.organization_id = v_branch.id and om.enabled
    order by (exists (select 1 from public.module_dependencies d where d.depends_on_module_key = om.module_key)), om.module_key
  loop
    update public.organization_modules set enabled = false where organization_id = v_branch.id and module_key = v_key;
  end loop;
  update public.staff_branch_authorisations set status = 'ended', ends_on = least(coalesce(ends_on, current_date), current_date)
   where branch_org_id = v_branch.id and status = 'active';

  update public.organizations set active = false, status = 'archived', updated_at = now()
   where id = v_branch.id returning * into v_branch;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_branch.parent_organization_id, v_actor, 'provider_branch_archived', 'organizations', v_branch.id, jsonb_build_object('name', v_branch.name));
  return v_branch;
end;
$function$;
COMMENT ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) IS 'Organisation settings: archive a branch that has no active staff or sub-branches; disables its modules and ends its branch authorisations. Requires the parent organisation''s administrator.';
REVOKE ALL ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."archive_provider_branch"(p_branch_organization_id uuid, p_expected_updated_at timestamp with time zone) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text DEFAULT 'work_place'::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_gps_accuracy double precision DEFAULT NULL::double precision, p_bwc_reference text DEFAULT NULL::text)
 RETURNS TABLE(stop_id uuid, created boolean, arrived_at timestamp with time zone, arrival_verification text, arrival_distance_m numeric, visit_number integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_job public.dispatch_jobs%rowtype;
  v_site public.client_sites%rowtype;
  v_stop public.shift_stops%rowtype;
  v_receipt public.officer_command_requests%rowtype;
  v_site_id uuid;
  v_shift_id uuid;
  v_point geometry;
  v_distance numeric;
  v_verification text;
  v_onsite_m numeric;
  v_approach_m numeric;
  v_next_visit integer;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_place_role NOT IN ('work_place', 'harmed_party_place') THEN RAISE EXCEPTION 'place_role must be work_place or harmed_party_place'; END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_receipt FROM public.officer_command_requests r WHERE r.request_id = p_client_request_id::text;
  IF FOUND AND v_receipt.actor_user_id IS DISTINCT FROM v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
  IF FOUND AND v_receipt.command_status = 'completed' THEN
    RETURN QUERY SELECT (v_receipt.response->>'stop_id')::uuid, false, (v_receipt.response->>'arrived_at')::timestamptz,
      v_receipt.response->>'arrival_verification', (v_receipt.response->>'arrival_distance_m')::numeric, (v_receipt.response->>'visit_number')::integer;
    RETURN;
  END IF;

  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found in the officer organisation'; END IF;
  IF NOT (v_job.assigned_officer_id = v_user OR public.is_admin_for_org(v_org)
      OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)) THEN
    RAISE EXCEPTION 'Only the assigned officer may record attendance for this job';
  END IF;

  v_site_id := CASE p_place_role WHEN 'work_place' THEN v_job.client_site_id ELSE v_job.harmed_party_site_id END;
  IF p_place_role = 'harmed_party_place' AND v_site_id IS NULL AND v_job.harmed_party_address IS NULL THEN
    RAISE EXCEPTION 'This job has no harmed-party place recorded';
  END IF;

  v_shift_id := v_job.shift_id;
  IF v_shift_id IS NULL THEN
    SELECT s.id INTO v_shift_id FROM public.shifts s
    WHERE s.officer_user_id = v_user AND s.organization_id = v_org AND s.status = 'in_progress'
    ORDER BY s.actual_start DESC NULLS LAST LIMIT 1;
  END IF;
  IF v_shift_id IS NULL THEN RAISE EXCEPTION 'An in-progress shift is required to record attendance'; END IF;

  -- Geofence verification: loud, never blocking (GEOFENCE_PRINCIPLES P1/P2).
  IF p_gps_lat IS NULL OR p_gps_lng IS NULL THEN
    v_verification := 'no_gps';
  ELSE
    v_point := ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326);
    IF v_site_id IS NOT NULL THEN SELECT * INTO v_site FROM public.client_sites cs WHERE cs.id = v_site_id; END IF;
    IF v_site.id IS NULL OR (v_site.boundary IS NULL AND v_site.center_point IS NULL) THEN
      v_verification := 'no_geofence';
    ELSE
      v_distance := round((CASE WHEN v_site.boundary IS NOT NULL
        THEN ST_Distance(v_site.boundary::geography, v_point::geography)
        ELSE ST_Distance(v_site.center_point::geography, v_point::geography) END)::numeric, 1);
      v_onsite_m := COALESCE(v_site.onsite_radius_meters, 10);
      SELECT c.config_value::numeric INTO v_approach_m FROM public.org_geofence_config c
      WHERE c.organization_id = v_org AND c.config_key = 'approach_radius_m' AND c.zone_type IS NULL LIMIT 1;
      v_approach_m := COALESCE(v_approach_m, v_site.prompt_radius_meters, 50);
      IF v_site.boundary_verification IS DISTINCT FROM 'verified' THEN v_verification := 'unverified_boundary';
      ELSIF v_distance <= v_onsite_m THEN v_verification := 'verified_on_site';
      ELSIF v_distance <= v_approach_m THEN v_verification := 'near_site';
      ELSE v_verification := 'off_site';
      END IF;
    END IF;
  END IF;

  SELECT * INTO v_stop FROM public.shift_stops st
  WHERE st.dispatch_job_id = v_job.id AND st.place_role = p_place_role AND st.status NOT IN ('completed', 'cancelled', 'skipped')
  ORDER BY st.visit_number DESC LIMIT 1;
  IF NOT FOUND THEN
    SELECT COALESCE(max(st.visit_number), 0) + 1 INTO v_next_visit FROM public.shift_stops st WHERE st.dispatch_job_id = v_job.id AND st.place_role = p_place_role;
    INSERT INTO public.shift_stops (organization_id, shift_id, site_id, module_key, stop_order, visit_number, is_adhoc, dispatch_job_id,
      sla_arrive_by, required_dwell_minutes, status, place_role)
    VALUES (v_org, v_shift_id, v_site_id, COALESCE(v_job.module_key, 'noise_control'),
      (SELECT COALESCE(max(so.stop_order), 0) + 1 FROM public.shift_stops so WHERE so.shift_id = v_shift_id),
      v_next_visit, true, v_job.id, COALESCE(v_job.sla_respond_by, now()), COALESCE(v_job.expected_dwell_minutes, 15), 'on_scene', p_place_role)
    RETURNING * INTO v_stop;
  END IF;

  UPDATE public.shift_stops
  SET actual_arrived_at = COALESCE(shift_stops.actual_arrived_at, now()),
      arrived_gps_lat = COALESCE(p_gps_lat, shift_stops.arrived_gps_lat),
      arrived_gps_lng = COALESCE(p_gps_lng, shift_stops.arrived_gps_lng),
      arrived_gps_accuracy = COALESCE(p_gps_accuracy, shift_stops.arrived_gps_accuracy),
      arrival_verification = v_verification,
      arrival_distance_m = v_distance,
      bwc_reference = COALESCE(nullif(trim(coalesce(p_bwc_reference, '')), ''), shift_stops.bwc_reference),
      status = 'on_scene',
      sla_status = CASE WHEN COALESCE(shift_stops.actual_arrived_at, now()) > shift_stops.sla_arrive_by THEN 'breached' ELSE shift_stops.sla_status END,
      updated_at = now()
  WHERE id = v_stop.id
  RETURNING * INTO v_stop;

  IF p_place_role = 'work_place' THEN
    UPDATE public.dispatch_jobs
    SET on_scene_at = COALESCE(dispatch_jobs.on_scene_at, v_stop.actual_arrived_at),
        status = CASE WHEN dispatch_jobs.status IN ('dispatched', 'acknowledged', 'en_route') THEN 'on_scene' ELSE dispatch_jobs.status END,
        sla_breached = CASE WHEN dispatch_jobs.sla_respond_by IS NOT NULL AND v_stop.actual_arrived_at > dispatch_jobs.sla_respond_by THEN true ELSE dispatch_jobs.sla_breached END
    WHERE id = v_job.id;
  END IF;

  INSERT INTO public.officer_command_requests (request_id, organization_id, actor_user_id, shift_id, site_id, command_type, command_status, response)
  VALUES (p_client_request_id::text, v_org, v_user, v_shift_id, v_site_id, 'arrive_at_dispatch_place', 'completed',
    jsonb_build_object('stop_id', v_stop.id, 'arrived_at', v_stop.actual_arrived_at, 'arrival_verification', v_verification,
      'arrival_distance_m', v_distance, 'visit_number', v_stop.visit_number, 'place_role', p_place_role))
  ON CONFLICT (request_id) DO UPDATE SET command_status = 'completed', response = EXCLUDED.response;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'dispatch_place_arrival_recorded', 'shift_stops', v_stop.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'place_role', p_place_role, 'arrival_verification', v_verification,
      'arrival_distance_m', v_distance, 'visit_number', v_stop.visit_number, 'bwc_reference_recorded', v_stop.bwc_reference IS NOT NULL));

  RETURN QUERY SELECT v_stop.id, true, v_stop.actual_arrived_at, v_verification, v_distance, v_stop.visit_number;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."arrive_at_dispatch_place"(p_client_request_id uuid, p_dispatch_job_id uuid, p_place_role text, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_bwc_reference text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assess_bob_nz_finance_readiness"()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_tax_periods integer;
  v_tax_transactions integer;
  v_timesheets integer;
  v_labour_postings integer;
  v_finance_costs integer;
  v_results jsonb;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT count(*)::integer INTO v_tax_periods FROM public.finance_tax_periods WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_tax_transactions FROM public.finance_tax_transactions WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_timesheets FROM public.timesheets WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_labour_postings FROM public.finance_labour_cost_postings WHERE organization_id = v_org;
  SELECT count(*)::integer INTO v_finance_costs FROM public.finance_service_costs WHERE organization_id = v_org;

  INSERT INTO public.bob_nz_finance_readiness_checks(organization_id, source_key, check_code, check_title, status, score, evidence, bob_can_do, human_or_provider_needed, measured_at)
  VALUES
    (v_org, 'ird-gst-overview', 'gst', 'GST calculation and period control', CASE WHEN v_tax_periods > 0 AND v_tax_transactions > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_tax_periods > 0 AND v_tax_transactions > 0 THEN 60 ELSE 30 END, 'GST periods and tax transactions exist: ' || v_tax_periods || ' periods, ' || v_tax_transactions || ' transactions. Filing submission and payment integration are not present.', 'Prepare GST figures, explain output/input tax, identify missing transactions, and create a filing checklist.', 'A person or approved tax/accounting provider must confirm the return and submit/pay it to IRD.', now()),
    (v_org, 'ird-gst-records', 'gst_record_keeping', 'GST evidence and record keeping', CASE WHEN v_finance_costs > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_finance_costs > 0 THEN 65 ELSE 25 END, 'Finance service costs provide source references and audit entries; source documents and full tax-invoice evidence are not automatically complete.', 'Collect provenance, flag missing receipts/invoices, and explain which records support each figure.', 'The owner and accountant must retain complete tax invoices and decide whether evidence supports a GST position.', now()),
    (v_org, 'ird-employers', 'employers', 'Employer cost and staff finance controls', CASE WHEN v_timesheets > 0 AND v_labour_postings > 0 THEN 'partial' ELSE 'gap' END, CASE WHEN v_timesheets > 0 AND v_labour_postings > 0 THEN 60 ELSE 30 END, 'Timesheets and actual labour-cost postings exist: ' || v_timesheets || ' timesheets, ' || v_labour_postings || ' labour postings. Employment compliance and PAYE calculations are not statutory payroll.', 'Check approved hours, rates, on-cost assumptions, missing pay rules, and management labour cost.', 'A payroll provider or payroll specialist must calculate and file PAYE and employment obligations.', now()),
    (v_org, 'ird-provisional-tax', 'provisional_tax', 'Provisional tax planning', 'gap', 15, 'No dedicated provisional-tax liability, estimate, payment schedule, or IRD submission workflow exists.', 'Explain that provisional tax may need planning and prepare questions for the accountant using management results.', 'An accountant or tax agent must calculate the liability, method, dates, and payment instruction.', now()),
    (v_org, 'ird-payroll', 'payday_filing', 'Payday filing integration', 'gap', 10, 'Timesheets and cost postings exist, but no IRD payday-file generation, submission, response, or correction workflow exists.', 'Prepare a clean hours/rates export and identify unresolved payroll inputs.', 'An approved payroll system/provider must generate and submit payday files to IRD.', now()),
    (v_org, 'xrb-nz-accounting-standards', 'accounting_standards', 'Accounting standards and statutory reporting', 'partial', 45, 'Management P&L, budgets, costs, invoices, tax records, and audit trails exist; general-ledger journals, statutory statements, and reporting-entity classification are not implemented.', 'Keep management measures separate, show assumptions, preserve evidence, and prepare an accountant handoff.', 'A qualified accountant must determine applicable standards, classifications, adjustments, and statutory statements.', now())
  ON CONFLICT (organization_id, source_key) DO UPDATE SET check_code = EXCLUDED.check_code, check_title = EXCLUDED.check_title, status = EXCLUDED.status, score = EXCLUDED.score, evidence = EXCLUDED.evidence, bob_can_do = EXCLUDED.bob_can_do, human_or_provider_needed = EXCLUDED.human_or_provider_needed, measured_at = EXCLUDED.measured_at;

  SELECT jsonb_build_object('measured_at', now(), 'overall_score', round(avg(score)), 'checks', jsonb_agg(jsonb_build_object('source_key', source_key, 'title', check_title, 'status', status, 'score', score, 'evidence', evidence, 'bob_can_do', bob_can_do, 'human_or_provider_needed', human_or_provider_needed) ORDER BY source_key)) INTO v_results
  FROM public.bob_nz_finance_readiness_checks WHERE organization_id = v_org;
  RETURN v_results;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assess_bob_nz_finance_readiness"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assess_bob_nz_finance_readiness"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid)
 RETURNS dispatch_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_job public.dispatch_jobs%rowtype;
BEGIN
  SELECT * INTO v_job FROM public.dispatch_jobs WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND OR v_actor IS NULL OR NOT public.is_admin_for_org(v_job.organization_id) THEN RAISE EXCEPTION 'Dispatch job access denied'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles u
    JOIN public.service_agreements sa ON sa.id=v_job.service_agreement_id
    JOIN public.organizations officer_org ON officer_org.id=u.organization_id
    WHERE u.id=p_officer_user_id AND u.deactivated_at IS NULL AND u.role IN ('officer','admin_officer')
      AND (officer_org.id=sa.provider_organization_id OR sa.provider_organization_id=ANY(public.get_descendant_organizations(officer_org.id)))
  ) THEN RAISE EXCEPTION 'Target officer is not authorized for this service agreement'; END IF;
  UPDATE public.dispatch_jobs SET assigned_officer_id=p_officer_user_id WHERE public.dispatch_jobs.id=p_job_id RETURNING * INTO v_job;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_job.organization_id,v_actor,'dispatch_job_assigned_to_officer','dispatch_jobs',v_job.id,jsonb_build_object('officer_user_id',p_officer_user_id,'roster_independent',true));
  RETURN v_job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_dispatch_job_to_officer"(p_job_id uuid, p_officer_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text DEFAULT NULL::text)
 RETURNS face_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  observation public.face_observations;
  source_metadata jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    IF auth.uid() IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.face_observations
       WHERE id = p_observation_id AND public.org_access_allowed(organization_id)
    ) THEN RAISE EXCEPTION 'Observation access denied'; END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.face_observations o
    JOIN public.person_records p ON p.organization_id = o.organization_id
   WHERE o.id = p_observation_id AND p.id = p_person_record_id
  ) THEN RAISE EXCEPTION 'Person record does not belong to the observation organization'; END IF;

  SELECT metadata INTO source_metadata FROM public.face_observations WHERE id = p_observation_id;
  IF NULLIF(trim(p_display_name), '') IS NOT NULL THEN
    UPDATE public.person_records SET display_name = trim(p_display_name) WHERE id = p_person_record_id;
  END IF;
  UPDATE public.person_records
     SET metadata = jsonb_set(
       metadata,
       '{face_reference}',
       jsonb_build_object(
         'embedding', source_metadata->'embedding',
         'thumbnail', source_metadata->>'original_thumbnail',
         'evidence_item_id', source_metadata->>'evidence_item_id',
         'event_id', source_metadata->>'source_event_id'
       ),
       true
     )
   WHERE id = p_person_record_id
     AND jsonb_typeof(metadata->'face_reference'->'embedding') IS DISTINCT FROM 'array'
     AND jsonb_typeof(source_metadata->'embedding') = 'array';

  UPDATE public.face_observations SET person_record_id = p_person_record_id, review_state = 'reviewed'
   WHERE id = p_observation_id RETURNING * INTO observation;
  RETURN observation;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_face_observation_person"(p_observation_id uuid, p_person_record_id uuid, p_display_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean DEFAULT false, p_certification_expiry date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS staff_skills
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_org uuid; v_skill public.roster_skill_catalog%rowtype; v_row public.staff_skills%rowtype;
begin
  select organization_id into v_org from public.user_profiles where id = v_actor and deactivated_at is null;
  if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Roster administrator required'; end if;
  select * into v_skill from public.roster_skill_catalog where id = p_skill_id and organization_id = v_org and active;
  if not found then raise exception 'Active catalog skill required'; end if;
  if not exists (select 1 from public.staff_profiles where id = p_staff_id and organization_id = v_org) then raise exception 'Staff profile not found'; end if;
  insert into public.staff_skills(staff_id, organization_id, skill_id, skill_name, skill_category, proficiency_level, certified, certification_expiry, notes) values (p_staff_id, v_org, v_skill.id, v_skill.skill_name, v_skill.skill_category, p_proficiency_level, p_certified, p_certification_expiry, nullif(trim(p_notes), '')) returning * into v_row;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_org, v_actor, 'roster_skill_assigned_to_staff', 'staff_skills', v_row.id, jsonb_build_object('staff_id', p_staff_id, 'skill_id', p_skill_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_roster_skill_to_staff"(p_staff_id uuid, p_skill_id uuid, p_proficiency_level text, p_certified boolean, p_certification_expiry date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid)
 RETURNS shift_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_asset public.assets%rowtype;
  v_link public.shift_assets%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then
    raise exception 'Shift not found';
  end if;

  if not public.is_admin_for_org(v_shift.organization_id) and v_shift.officer_user_id <> v_actor then
    raise exception 'Not authorised to assign assets to this shift';
  end if;

  select l.* into v_link from public.shift_assets l
  where l.organization_id = v_shift.organization_id and l.client_request_id = p_client_request_id;
  if found then
    return v_link;
  end if;

  select a.* into v_asset from public.assets a where a.id = p_asset_id for update;
  if not found then
    raise exception 'Asset not found';
  end if;

  if v_asset.organization_id <> v_shift.organization_id then
    raise exception 'Asset belongs to another organization';
  end if;

  if v_asset.status <> 'available' then
    raise exception 'Asset is not available (current status %)', v_asset.status;
  end if;

  insert into public.shift_assets(organization_id, shift_id, asset_id, assigned_by, client_request_id)
  values (v_shift.organization_id, v_shift.id, v_asset.id, v_actor, p_client_request_id)
  returning * into v_link;

  update public.assets
  set status = 'in_use', assigned_to = v_shift.officer_user_id
  where id = v_asset.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'shift_asset_assigned', 'shift_assets', v_link.id,
    jsonb_build_object(
      'shift_id', v_shift.id,
      'asset_id', v_asset.id,
      'asset_type', v_asset.asset_type,
      'registration', v_asset.registration,
      'client_request_id', p_client_request_id
    )
  );

  return v_link;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."assign_shift_asset"(p_client_request_id uuid, p_shift_id uuid, p_asset_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid)
 RETURNS client_sites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_provider uuid; v_site public.client_sites%rowtype;
BEGIN
 SELECT up.organization_id INTO v_provider FROM public.user_profiles AS up WHERE up.id=v_actor AND up.deactivated_at IS NULL;
 SELECT site.* INTO v_site FROM public.client_sites AS site WHERE site.id=p_site_id FOR UPDATE;
 IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(v_site.client_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.locations AS house WHERE house.id=p_location_id AND house.organization_id=v_site.client_organization_id) THEN RAISE EXCEPTION 'Location house does not belong to the Site organization'; END IF;
 UPDATE public.client_sites SET location_id=p_location_id WHERE id=v_site.id RETURNING * INTO v_site;
 INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_provider,v_actor,'crm_site_attached_to_location','client_sites',v_site.id,jsonb_build_object('location_id',p_location_id));
 RETURN v_site;
END; $function$;
REVOKE ALL ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."attach_crm_site_to_location"(p_site_id uuid, p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."autolink_client_site_service_agreement"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.service_agreement_id is null and new.client_organization_id is not null then
    select sa.id
      into new.service_agreement_id
    from public.service_agreements sa
    where sa.client_organization_id = new.client_organization_id
      and (sa.ends_on is null or sa.ends_on >= current_date)
    order by sa.starts_on desc nulls last, sa.created_at desc, sa.id desc
    limit 1;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."autolink_client_site_service_agreement"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."autolink_client_site_service_agreement"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(published_count integer, materialized_count integer, conflict_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_provider uuid; v_slot record; v_unit public.roster_work_units%rowtype; v_pub integer := 0; v_mat integer := 0; v_conf integer := 0; v_res record; v_error text;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select actor.organization_id into v_provider from public.user_profiles actor where actor.id = v_actor and actor.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active roster administrator required'; end if;
  if p_organization_id <> v_provider then raise exception 'Organization is outside your managed account hierarchy'; end if;
  for v_slot in (select s.* from public.roster_slots s where s.organization_id = v_provider and s.status = 'draft' and s.scheduled_start >= p_from and s.scheduled_start < p_to for update) loop
    if v_slot.staff_id is not null and exists (select 1 from public.leave_requests l where l.staff_id = v_slot.staff_id and l.status = 'approved' and daterange(l.starts_on, l.ends_on, '[]') && daterange(v_slot.scheduled_start::date, v_slot.scheduled_end::date, '[]')) then v_conf := v_conf + 1; continue; end if;
    update public.roster_slots set status = 'published', updated_at = now() where id = v_slot.id; v_pub := v_pub + 1;
    select wu.* into v_unit from public.roster_work_units wu where wu.id = v_slot.work_unit_id;
    if found and v_unit.work_unit_type <> 'internal' then
      begin select * into v_res from public.materialize_roster_slot(v_slot.id, 'published'); v_mat := v_mat + 1;
      exception when others then
        get stacked diagnostics v_error = message_text;
        insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_provider, v_actor, 'roster_batch_publish_materialization_failed', 'roster_slots', v_slot.id, jsonb_build_object('client_request_id', p_client_request_id, 'error', v_error, 'work_unit_id', v_slot.work_unit_id));
      end;
    end if;
  end loop;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_provider, v_actor, 'roster_period_batch_published', 'roster_slots', v_provider, jsonb_build_object('from', p_from, 'to', p_to, 'published_count', v_pub, 'materialized_count', v_mat, 'conflict_count', v_conf, 'client_request_id', p_client_request_id));
  return query select v_pub, v_mat, v_conf;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."batch_publish_roster_slots"(p_client_request_id uuid, p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0)
 RETURNS TABLE(expectation_id uuid, spine text, assertion_kind text, from_type text, from_name text, to_type text, to_name text, via_type text, via_name text, expectation_status text, gap_kind text, rationale text, signal_weight numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive active_expectations as (
    select *
    from public.app_map_expectations
    where status = 'active'
  ), paths as (
    select
      e.id as expectation_id,
      e.from_type as entity_type,
      e.from_name as entity_name,
      0 as depth,
      array[e.from_type || ':' || e.from_name]::text[] as path
    from active_expectations e
    union all
    select
      p.expectation_id,
      edge.target_type,
      edge.target_name,
      p.depth + 1,
      p.path || (edge.target_type || ':' || edge.target_name)
    from paths p
    join public.bob_app_map_edges edge
      on edge.source_type = p.entity_type
     and edge.source_name = p.entity_name
     and edge.retirement_status = 'live'
     and edge.edge_kind in ('writes', 'reads', 'calls', 'invokes')
    where p.depth < 8
      and not (edge.target_type || ':' || edge.target_name) = any(p.path)
  ), evaluated as (
    select
      e.*,
      exists (
        select 1 from paths p
        where p.expectation_id = e.id
          and p.entity_type = e.to_type
          and p.entity_name = e.to_name
      ) as reaches_target,
      exists (
        select 1 from paths p
        where p.expectation_id = e.id
          and p.entity_type = e.to_type
          and p.entity_name = e.to_name
          and e.via_type is not null
          and (e.via_type || ':' || e.via_name) = any(p.path)
      ) as reaches_target_via
    from active_expectations e
  )
  select
    e.id,
    e.spine,
    e.assertion_kind,
    e.from_type,
    e.from_name,
    e.to_type,
    e.to_name,
    e.via_type,
    e.via_name,
    case
      when e.assertion_kind = 'must_reach' and e.reaches_target then 'satisfied'
      when e.assertion_kind = 'must_not_reach' and not e.reaches_target then 'satisfied'
      when e.assertion_kind = 'must_pass_through' and e.reaches_target_via then 'satisfied'
      else 'gap'
    end as expectation_status,
    case
      when e.assertion_kind = 'must_reach' and not e.reaches_target then 'broken_reach'
      when e.assertion_kind = 'must_not_reach' and e.reaches_target then 'prohibited_reach'
      when e.assertion_kind = 'must_pass_through' and not e.reaches_target_via then 'missing_required_hop'
      else null
    end as gap_kind,
    e.rationale,
    e.signal_weight
  from evaluated e
  order by e.spine, e.from_type, e.from_name, e.to_type, e.to_name
  limit greatest(1, least(coalesce(p_limit, 200), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) IS 'Atlas intent evaluator: tests active authored must_reach, must_not_reach, and must_pass_through assertions against directed live flow edges, cycle-guarded and capped at eight hops.';
REVOKE ALL ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_expectation_report"(p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer DEFAULT 8)
 RETURNS TABLE(entity_type text, entity_name text, depth integer, edge_kind text, edge_from text, edge_to text, path text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive walk as (
    select
      p_from_type::text as entity_type,
      p_from_name::text as entity_name,
      0                 as depth,
      null::text        as edge_kind,
      null::text        as edge_from,
      null::text        as edge_to,
      array[p_from_type || ':' || p_from_name]::text[] as path
    union all
    -- UNDIRECTED: step to whichever end of the FK edge is NOT the current node.
    select
      nb.n_type,
      nb.n_name,
      w.depth + 1,
      e.edge_kind,
      e.source_type || ':' || e.source_name,
      e.target_type || ':' || e.target_name,
      w.path || (nb.n_type || ':' || nb.n_name)
    from walk w
    join public.bob_app_map_edges e
      on e.retirement_status = 'live'
     and e.edge_kind in ('fk_references','references')
     and (
           (e.source_type = w.entity_type and e.source_name = w.entity_name)
        or (e.target_type = w.entity_type and e.target_name = w.entity_name)
         )
    cross join lateral (
      select
        case when e.source_type = w.entity_type and e.source_name = w.entity_name
             then e.target_type else e.source_type end as n_type,
        case when e.source_type = w.entity_type and e.source_name = w.entity_name
             then e.target_name else e.source_name end as n_name
    ) nb
    where w.depth < least(p_max_depth, 20)
      and not (nb.n_type || ':' || nb.n_name) = any(w.path)
  )
  select entity_type, entity_name, depth, edge_kind, edge_from, edge_to, path
  from walk
  where depth > 0
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) IS 'Atlas blast-radius: UNDIRECTED structural/FK relation reach (fk_references/references) from a node, live edges only, cycle-guarded + depth-capped. Returns the actual live edge direction (edge_from/edge_to) per #313 M4. This is a RELATION, never a proven data-flow path (see bob_atlas_flow_reach).';
REVOKE ALL ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_fk_reach"(p_from_type text, p_from_name text, p_max_depth integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text DEFAULT 'downstream'::text, p_max_depth integer DEFAULT 8)
 RETURNS TABLE(entity_type text, entity_name text, depth integer, edge_kind text, path text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive walk as (
    -- Seed: the origin node itself, depth 0.
    select
      p_from_type::text as entity_type,
      p_from_name::text as entity_name,
      0                 as depth,
      null::text        as edge_kind,
      array[p_from_type || ':' || p_from_name]::text[] as path
    union all
    select
      case when p_direction = 'upstream' then e.source_type else e.target_type end,
      case when p_direction = 'upstream' then e.source_name else e.target_name end,
      w.depth + 1,
      e.edge_kind,
      w.path || (
        (case when p_direction = 'upstream' then e.source_type else e.target_type end)
        || ':' ||
        (case when p_direction = 'upstream' then e.source_name else e.target_name end)
      )
    from walk w
    join public.bob_app_map_edges e
      on e.retirement_status = 'live'
     and e.edge_kind in ('writes','reads','calls','invokes')
     and (
           (p_direction = 'upstream'
              and e.target_type = w.entity_type and e.target_name = w.entity_name)
        or (p_direction <> 'upstream'
              and e.source_type = w.entity_type and e.source_name = w.entity_name)
         )
    where w.depth < least(p_max_depth, 20)
      -- cycle guard: do not revisit a node already on this path (#313 M1)
      and not (
        (case when p_direction = 'upstream' then e.source_type else e.target_type end)
        || ':' ||
        (case when p_direction = 'upstream' then e.source_name else e.target_name end)
      ) = any(w.path)
  )
  select entity_type, entity_name, depth, edge_kind, path
  from walk
  where depth > 0
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) IS 'Atlas blast-radius: directed data-FLOW reachability (writes/reads/calls/invokes) from a node, live edges only, cycle-guarded + depth-capped. FLOW only - never conflate with FK relation (bob_atlas_fk_reach).';
REVOKE ALL ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_flow_reach"(p_from_type text, p_from_name text, p_direction text, p_max_depth integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_atlas_gap_report"(p_limit integer DEFAULT 200, p_offset integer DEFAULT 0, p_include_columns boolean DEFAULT false, p_include_unknown_exercise boolean DEFAULT false)
 RETURNS TABLE(entity_type text, entity_name text, gap_kind text, present boolean, wired boolean, exercised boolean, caller_summary text, notes text, retirement_status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    c.entity_type,
    c.entity_name,
    case
      when c.present = true and c.wired = false then 'unwired'
      when c.present = true and c.exercised = false then 'unexercised'
      else 'exercise_unknown'
    end as gap_kind,
    c.present,
    c.wired,
    c.exercised,
    c.caller_summary,
    c.notes,
    c.retirement_status
  from public.bob_capability_map c
  where c.retirement_status <> 'retired'
    and c.present = true
    and (coalesce(p_include_columns, false) or c.entity_type <> 'column')
    and (
      c.wired = false
      or c.exercised = false
      or (coalesce(p_include_unknown_exercise, false) and c.exercised is null)
    )
  order by c.entity_type, c.entity_name
  limit greatest(1, least(coalesce(p_limit, 200), 500))
  offset greatest(0, coalesce(p_offset, 0));
$function$;
COMMENT ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) IS 'Atlas operational gaps: present but unwired or explicitly unexercised non-retired capabilities. Columns and unknown exercise state are opt-in diagnostics because static refresh cannot infer runtime execution.';
REVOKE ALL ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."bob_atlas_gap_report"(p_limit integer, p_offset integer, p_include_columns boolean, p_include_unknown_exercise boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."bob_cards_needing_embedding"(match_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, title text, content text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.title, c.content
  from public.bob_knowledge_cards c
  where c.is_active
    and (
      c.embedding is null
      or c.embedded_at is null
      or c.embedded_at < c.updated_at
    )
  order by c.embedded_at asc nulls first, c.updated_at asc
  limit greatest(1, least(match_limit, 100));
$function$;
COMMENT ON FUNCTION "public"."bob_cards_needing_embedding"(match_limit integer) IS 'Bob RAG embed backfill: active cards that are new or whose content changed since last embed (embedding IS NULL OR embedded_at IS NULL OR embedded_at < updated_at). Stalest-first. Service-role only.';
