CREATE OR REPLACE FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _job public.builder_jobs%rowtype;
BEGIN
  IF auth.role() <> 'authenticated' OR _uid IS NULL THEN RAISE EXCEPTION 'Authenticated human identity required'; END IF;
  IF _mode NOT IN ('none', 'human', 'independent_ai') THEN RAISE EXCEPTION 'Unsupported code review mode'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'intake' THEN RAISE EXCEPTION 'Code review policy can only be set during intake'; END IF;
  IF NOT public.can_approve_action(_uid, _job.organization_id) THEN RAISE EXCEPTION 'User cannot configure this job'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job.id AND step_id = 'code_review' AND builder_mode = 'code_reviewer') THEN
    RAISE EXCEPTION 'Code review step is missing';
  END IF;
  UPDATE public.builder_jobs SET code_review_mode = _mode,
    code_review_status = CASE WHEN _mode = 'none' THEN 'not_required' ELSE 'pending' END, updated_at = now()
  WHERE id = _job.id RETURNING * INTO _job;
  UPDATE public.builder_job_steps SET status = CASE WHEN _mode = 'none' THEN 'skipped' ELSE 'pending' END, updated_at = now()
  WHERE job_id = _job.id AND step_id = 'code_review';
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_user_id, actor_type, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'job_status_changed', _uid, 'user',
    jsonb_build_object('code_review_mode', _mode), 'Optional code review policy configured');
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_set_code_review_policy"(_job_id uuid, _mode text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text)
 RETURNS builder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _sibling_mode text; _next_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF _builder_mode NOT IN ('frontend_engineer', 'backend_engineer') THEN RAISE EXCEPTION 'Unsupported implementation mode'; END IF;
  IF NULLIF(btrim(_reason), '') IS NULL THEN RAISE EXCEPTION 'A skip reason is required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'implementation_pending' THEN RAISE EXCEPTION 'Job is not ready for an implementation skip'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> _builder_mode OR _step.status NOT IN ('pending', 'blocked') THEN RAISE EXCEPTION 'Implementation step cannot be skipped'; END IF;
  _sibling_mode := CASE WHEN _builder_mode = 'frontend_engineer' THEN 'backend_engineer' ELSE 'frontend_engineer' END;
  _next_status := CASE
    WHEN EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job_id AND builder_mode = _sibling_mode AND status IN ('completed', 'skipped')) THEN 'testing'
    ELSE 'implementation_pending'
  END;
  UPDATE public.builder_job_steps SET status = 'skipped', completed_at = now(), retryable = false,
    result_summary = left(btrim(_reason), 1000), error = NULL, updated_at = now() WHERE id = _step.id;
  UPDATE public.builder_jobs SET status = _next_status, current_step_name = _step.step_id,
    current_step_index = _step.ordinal_position, updated_at = now() WHERE id = _job.id RETURNING * INTO _job;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, previous_value, new_value, change_summary)
  VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode',
    jsonb_build_object('job_status', 'implementation_pending', 'step_status', _step.status),
    jsonb_build_object('job_status', _next_status, 'step_status', 'skipped', 'builder_mode', _builder_mode),
    left('Implementation step skipped: ' || btrim(_reason), 1000));
  RETURN _job;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_skip_implementation_step"(_job_id uuid, _step_id uuid, _builder_mode text, _reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _job public.builder_jobs%rowtype; _step public.builder_job_steps%rowtype; _approval public.builder_approvals%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  IF _job.id IS NULL OR _job.status <> 'security_review' THEN RAISE EXCEPTION 'Job is not ready for optional code review'; END IF;
  IF _step.id IS NULL OR _step.step_id <> 'code_review' OR _step.builder_mode <> 'code_reviewer' THEN RAISE EXCEPTION 'Code review step is missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.builder_job_steps WHERE job_id = _job.id AND step_id = 'security_review' AND status = 'completed') THEN
    RAISE EXCEPTION 'Independent security review must complete first';
  END IF;
  IF _job.code_review_mode = 'none' THEN
    UPDATE public.builder_job_steps SET status = 'skipped', completed_at = now(), result_summary = 'Optional code review not requested', updated_at = now() WHERE id = _step.id;
    UPDATE public.builder_jobs SET code_review_status = 'not_required', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary)
    VALUES (_job.organization_id, _job.id, 'step_completed', 'builder_mode',
      jsonb_build_object('step_id', 'code_review', 'status', 'skipped', 'target_sha', _job.target_sha),
      'Optional code review skipped by configured policy');
    RETURN jsonb_build_object('mode', 'none', 'status', 'skipped');
  END IF;

  IF _step.status <> 'pending' THEN RAISE EXCEPTION 'Code review step is not pending'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(ARRAY['code_implementation','changed_file_manifest','build_logs','security_review']) required_type
    WHERE NOT EXISTS (
      SELECT 1 FROM public.builder_artifacts artifact
      WHERE artifact.job_id = _job.id AND artifact.id = ANY(_reviewed_artifact_ids)
        AND artifact.artifact_type = required_type AND artifact.status = 'final'
    )
  ) OR (
    SELECT count(*) FROM public.builder_artifacts WHERE job_id = _job.id AND id = ANY(_reviewed_artifact_ids) AND status = 'final'
  ) <> cardinality(_reviewed_artifact_ids) THEN RAISE EXCEPTION 'Code review evidence snapshot is incomplete'; END IF;

  IF _job.code_review_mode = 'human' THEN
    UPDATE public.builder_job_steps SET status = 'blocked', blocked_reason = 'Waiting for human code review', input_context = jsonb_build_object('reviewed_artifact_ids', _reviewed_artifact_ids), updated_at = now() WHERE id = _step.id;
    INSERT INTO public.builder_approvals (organization_id, job_id, approval_type, triggered_at_status, status,
      requested_from_users, requested_target_sha, reviewed_artifact_ids)
    VALUES (_job.organization_id, _job.id, 'implementation_review', 'security_review', 'pending',
      COALESCE(_requested_from_users, '{}'), _job.target_sha, _reviewed_artifact_ids)
    RETURNING * INTO _approval;
    UPDATE public.builder_jobs SET code_review_status = 'pending', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids, related_approval_id)
    VALUES (_job.organization_id, _job.id, 'approval_requested', 'bot', jsonb_build_object('approval_type', 'implementation_review', 'target_sha', _job.target_sha),
      'Optional human code review requested', _reviewed_artifact_ids, _approval.id);
    RETURN jsonb_build_object('mode', 'human', 'status', 'pending', 'approval_id', _approval.id);
  ELSIF _job.code_review_mode = 'independent_ai' THEN
    UPDATE public.builder_job_steps SET status = 'running', attempt_count = attempt_count + 1, started_at = now(),
      input_context = jsonb_build_object('reviewed_artifact_ids', _reviewed_artifact_ids, 'target_sha', _job.target_sha), updated_at = now()
    WHERE id = _step.id;
    UPDATE public.builder_jobs SET code_review_status = 'pending', updated_at = now() WHERE id = _job.id;
    INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
    VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
      jsonb_build_object('step_id', 'code_review', 'mode', 'independent_ai', 'target_sha', _job.target_sha),
      'Independent AI code review started', _reviewed_artifact_ids);
    RETURN jsonb_build_object('mode', 'independent_ai', 'status', 'running');
  END IF;
  RAISE EXCEPTION 'Unsupported code review policy state';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_code_review"(_job_id uuid, _step_id uuid, _reviewed_artifact_ids uuid[], _requested_from_users uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _previous_step_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;

  IF _job.id IS NULL OR _job.status NOT IN ('intake', 'analysis_pending') THEN
    RAISE EXCEPTION 'Job is not ready for product analysis';
  END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'product_analyst' THEN
    RAISE EXCEPTION 'Product Analyst step is missing';
  END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN
    RAISE EXCEPTION 'Product Analyst step cannot be started';
  END IF;

  _previous_step_status := _step.status;
  UPDATE public.builder_job_steps
  SET status = 'running',
      attempt_count = attempt_count + 1,
      started_at = now(),
      completed_at = NULL,
      error = NULL,
      retryable = false,
      updated_at = now()
  WHERE id = _step.id
  RETURNING * INTO _step;

  UPDATE public.builder_jobs
  SET status = 'analysis_pending',
      current_step_name = _step.step_id,
      current_step_index = _step.ordinal_position,
      last_error = NULL,
      updated_at = now()
  WHERE id = _job.id;

  INSERT INTO public.builder_audit_events (
    organization_id, job_id, event_type, actor_type,
    previous_value, new_value, change_summary
  ) VALUES (
    _job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('job_status', _job.status, 'step_status', _previous_step_status),
    jsonb_build_object('job_status', 'analysis_pending', 'step_status', 'running', 'step_id', _step.step_id),
    'Product Analyst step started'
  );

  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_product_analysis"(_job_id uuid, _step_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _security_run public.builder_worker_runs%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _security_run FROM public.builder_worker_runs
  WHERE id = _security_worker_run_id AND job_id = _job_id AND profile = 'security-review';
  IF _job.id IS NULL OR _job.status <> 'security_review' THEN RAISE EXCEPTION 'Job is not ready for release preparation'; END IF;
    IF _step.id IS NULL OR _step.step_id <> 'release_prep' OR _step.builder_mode <> 'release_engineer'
      OR (_step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable)) THEN
    RAISE EXCEPTION 'Release Engineer step is not pending';
  END IF;
  IF _security_run.id IS NULL OR _security_run.status <> 'completed'
     OR _security_run.organization_id IS DISTINCT FROM _job.organization_id
     OR _security_run.target_sha IS DISTINCT FROM _job.target_sha
     OR _security_run.review_summary->>'passed' <> 'true'
     OR COALESCE((_security_run.review_summary->>'critical')::integer, 0) <> 0
     OR COALESCE((_security_run.review_summary->>'high')::integer, 0) <> 0 THEN
    RAISE EXCEPTION 'A clean independent security review is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_job_steps
    WHERE job_id = _job.id AND step_id = 'security_review' AND status = 'completed'
      AND artifact_ids && _security_run.output_artifact_ids
  ) THEN RAISE EXCEPTION 'Security review step evidence is incomplete'; END IF;

  UPDATE public.builder_job_steps
  SET status = 'running', attempt_count = attempt_count + 1, started_at = now(), retryable = false,
      input_context = jsonb_build_object('security_worker_run_id', _security_run.id,
        'security_artifact_ids', _security_run.output_artifact_ids, 'target_sha', _job.target_sha), updated_at = now()
  WHERE id = _step.id RETURNING * INTO _step;
  UPDATE public.builder_jobs SET current_step_name = _step.step_id, current_step_index = _step.ordinal_position, updated_at = now()
  WHERE id = _job.id;
  INSERT INTO public.builder_audit_events (organization_id, job_id, event_type, actor_type, new_value, change_summary, related_artifact_ids)
  VALUES (_job.organization_id, _job.id, 'step_started', 'builder_mode',
    jsonb_build_object('step_id', _step.step_id, 'target_sha', _job.target_sha, 'security_worker_run_id', _security_run.id),
    'Release preparation started from clean security evidence', _security_run.output_artifact_ids);
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_release_preparation"(_job_id uuid, _step_id uuid, _security_worker_run_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid)
 RETURNS builder_job_steps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _job public.builder_jobs%rowtype;
  _step public.builder_job_steps%rowtype;
  _specification public.builder_artifacts%rowtype;
  _previous_step_status text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service identity required'; END IF;
  SELECT * INTO _job FROM public.builder_jobs WHERE id = _job_id FOR UPDATE;
  SELECT * INTO _step FROM public.builder_job_steps WHERE id = _step_id AND job_id = _job_id FOR UPDATE;
  SELECT * INTO _specification FROM public.builder_artifacts WHERE id = _specification_artifact_id AND job_id = _job_id;

  IF _job.id IS NULL OR _job.status <> 'design_pending' THEN RAISE EXCEPTION 'Job is not ready for UX design'; END IF;
  IF _step.id IS NULL OR _step.builder_mode <> 'ux_designer' THEN RAISE EXCEPTION 'UX Designer step is missing'; END IF;
  IF _step.status <> 'pending' AND NOT (_step.status = 'failed' AND _step.retryable) THEN RAISE EXCEPTION 'UX Designer step cannot be started'; END IF;
  IF _specification.id IS NULL OR _specification.artifact_type <> 'product_specification' OR _specification.status <> 'final' THEN
    RAISE EXCEPTION 'Final product specification artifact is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_approvals
    WHERE job_id = _job.id AND approval_type = 'specification_review' AND status = 'approved'
      AND _specification.id = ANY(reviewed_artifact_ids)
  ) THEN RAISE EXCEPTION 'Product specification has not been approved'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.builder_job_steps
    WHERE job_id = _job.id AND builder_mode = 'product_analyst' AND status = 'completed'
      AND _specification.id = ANY(COALESCE(artifact_ids, '{}'))
  ) THEN RAISE EXCEPTION 'Product analysis dependency is incomplete'; END IF;

  _previous_step_status := _step.status;
  UPDATE public.builder_job_steps
  SET status='running', attempt_count=attempt_count+1, started_at=now(), completed_at=NULL,
      error=NULL, retryable=false, input_context=jsonb_build_object('specification_artifact_id', _specification.id), updated_at=now()
  WHERE id=_step.id RETURNING * INTO _step;
  UPDATE public.builder_jobs SET current_step_name=_step.step_id, current_step_index=_step.ordinal_position, updated_at=now() WHERE id=_job.id;
  INSERT INTO public.builder_audit_events (organization_id,job_id,event_type,actor_type,previous_value,new_value,change_summary,related_artifact_ids)
  VALUES (_job.organization_id,_job.id,'step_started','builder_mode',jsonb_build_object('job_status',_job.status,'step_status',_previous_step_status),jsonb_build_object('job_status','design_pending','step_status','running','step_id',_step.step_id),'UX Designer step started from approved specification',ARRAY[_specification.id]);
  RETURN _step;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."builder_start_ux_design"(_job_id uuid, _step_id uuid, _specification_artifact_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid)
 RETURNS SETOF finance_cost_centre_rolls
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  RETURN QUERY
  INSERT INTO public.finance_cost_centre_rolls(organization_id, pl_period_id, cost_centre_id, cost_centre_code, cost_centre_name, total_labour, total_vehicle, total_materials, total_equipment, total_overhead, total_depreciation, total_cost, attribution_count)
  SELECT v_org, p_pl_period_id, cc.id, cc.code, cc.name,
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'labour' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'vehicle' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'materials' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'equipment' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'overhead' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN fsc.cost_type = 'depreciation' THEN fsc.total_cost ELSE 0 END), 0),
    COALESCE(SUM(fsc.total_cost), 0), COUNT(fsc.id)
  FROM public.cost_centres cc LEFT JOIN public.finance_service_costs fsc ON cc.id = fsc.cost_centre_id AND fsc.pl_period_id = p_pl_period_id AND fsc.organization_id = v_org
  WHERE cc.organization_id = v_org GROUP BY cc.id, cc.code, cc.name
  RETURNING *;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_cost_centre_roll"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid)
 RETURNS SETOF finance_budget_variances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.finance_budgets WHERE id = p_budget_id AND organization_id = v_org AND status IN ('approved','locked')) THEN RAISE EXCEPTION 'Approved budget not found in organization'; END IF;
  RETURN QUERY
  INSERT INTO public.finance_budget_variances(organization_id, budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type, budget_amount, actual_amount, variance_amount, variance_pct, status)
  SELECT v_org, p_budget_id, p_pl_period_id, x.cost_centre_id, x.service_agreement_id, x.cost_type, x.budget_amount, x.actual_amount,
    x.actual_amount - x.budget_amount,
    CASE WHEN x.budget_amount > 0 THEN ROUND(((x.actual_amount - x.budget_amount) / x.budget_amount) * 100, 2) ELSE NULL END,
    CASE WHEN x.budget_amount = 0 AND x.actual_amount > 0 THEN 'no_budget' WHEN x.actual_amount <= x.budget_amount THEN 'on_track' WHEN x.actual_amount <= x.budget_amount * 1.10 THEN 'watch' ELSE 'over_budget' END
  FROM (
    SELECT COALESCE(bl.cost_centre_id, ac.cost_centre_id) AS cost_centre_id,
      COALESCE(bl.service_agreement_id, ac.service_agreement_id) AS service_agreement_id,
      COALESCE(bl.cost_type, ac.cost_type) AS cost_type,
      COALESCE(bl.budget_amount, 0) AS budget_amount,
      COALESCE(ac.actual_amount, 0) AS actual_amount
    FROM (SELECT cost_centre_id, service_agreement_id, cost_type, SUM(budget_amount) budget_amount FROM public.finance_budget_lines WHERE budget_id = p_budget_id AND pl_period_id = p_pl_period_id GROUP BY cost_centre_id, service_agreement_id, cost_type) bl
    FULL JOIN (SELECT cost_centre_id, service_agreement_id, cost_type, SUM(total_cost) actual_amount FROM public.finance_service_costs WHERE organization_id = v_org AND pl_period_id = p_pl_period_id GROUP BY cost_centre_id, service_agreement_id, cost_type) ac
      ON bl.cost_centre_id IS NOT DISTINCT FROM ac.cost_centre_id AND bl.service_agreement_id IS NOT DISTINCT FROM ac.service_agreement_id AND bl.cost_type = ac.cost_type
  ) x
  ON CONFLICT (budget_id, pl_period_id, cost_centre_id, service_agreement_id, cost_type)
  DO UPDATE SET budget_amount = EXCLUDED.budget_amount, actual_amount = EXCLUDED.actual_amount, variance_amount = EXCLUDED.variance_amount, variance_pct = EXCLUDED.variance_pct, status = EXCLUDED.status, calculated_at = now()
  RETURNING *;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_budget_variance"(p_budget_id uuid, p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_hours numeric := greatest(0, coalesce((p_inputs->>'labour_hours')::numeric, 0));
  v_km numeric := greatest(0, coalesce((p_inputs->>'vehicle_km')::numeric, 0));
  v_base numeric := greatest(0, coalesce((p_inputs->>'base_hourly_rate')::numeric, 0));
  v_oncost numeric := greatest(0, coalesce((p_inputs->>'labour_oncost_pct')::numeric, 0));
  v_leave numeric := greatest(0, coalesce((p_inputs->>'leave_provision_pct')::numeric, 0));
  v_vehicle_fixed numeric := greatest(0, coalesce((p_inputs->>'vehicle_fixed_annual')::numeric, 0));
  v_vehicle_hours numeric := greatest(0, coalesce((p_inputs->>'vehicle_productive_hours')::numeric, 0));
  v_vehicle_km_rate numeric := greatest(0, coalesce((p_inputs->>'vehicle_variable_per_km')::numeric, 0));
  v_acquisition_cost numeric := greatest(0, coalesce((p_inputs->>'asset_acquisition_cost')::numeric, 0));
  v_setup_cost numeric := greatest(0, coalesce((p_inputs->>'asset_setup_cost')::numeric, 0));
  v_residual_value numeric := greatest(0, coalesce((p_inputs->>'asset_residual_value')::numeric, 0));
  v_useful_life_months numeric := greatest(0, coalesce((p_inputs->>'asset_useful_life_months')::numeric, 0));
  v_depreciation numeric := 0;
  v_equipment numeric := greatest(0, coalesce((p_inputs->>'equipment_cost')::numeric, 0));
  v_direct numeric := greatest(0, coalesce((p_inputs->>'direct_operating_cost')::numeric, 0));
  v_overhead_pct numeric := greatest(0, coalesce((p_inputs->>'overhead_pct')::numeric, 0));
  v_margin_pct numeric := greatest(0, least(99.99, coalesce((p_inputs->>'target_margin_pct')::numeric, 0)));
  v_labour numeric;
  v_vehicle numeric;
  v_direct_cost numeric;
  v_overhead numeric;
  v_true_cost numeric;
  v_charge numeric;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF v_hours <= 0 THEN RAISE EXCEPTION 'Labour hours are required'; END IF;
  IF v_base <= 0 THEN RAISE EXCEPTION 'Base hourly rate is required'; END IF;
  IF v_km > 0 AND v_vehicle_km_rate <= 0 THEN RAISE EXCEPTION 'Vehicle per-km cost is required when travel is entered'; END IF;
  IF v_vehicle_fixed > 0 AND v_vehicle_hours <= 0 THEN RAISE EXCEPTION 'Vehicle productive hours are required for fixed vehicle cost'; END IF;
  IF v_acquisition_cost + v_setup_cost > 0 AND v_useful_life_months <= 0 THEN RAISE EXCEPTION 'Asset useful life is required when an acquisition cost is entered'; END IF;
  IF v_residual_value > v_acquisition_cost + v_setup_cost THEN RAISE EXCEPTION 'Asset residual value cannot exceed capitalized cost'; END IF;
  v_labour := v_hours * v_base * (1 + (v_oncost + v_leave) / 100);
  v_depreciation := (v_acquisition_cost + v_setup_cost - v_residual_value) / nullif(v_useful_life_months / 12, 0);
  IF v_depreciation > 0 AND v_vehicle_hours <= 0 THEN RAISE EXCEPTION 'Vehicle productive hours are required to allocate asset depreciation'; END IF;
  v_vehicle := CASE WHEN v_vehicle_fixed + v_depreciation > 0 THEN v_hours * ((v_vehicle_fixed + v_depreciation) / v_vehicle_hours) ELSE 0 END + v_km * v_vehicle_km_rate;
  v_direct_cost := v_labour + v_vehicle + v_equipment + v_direct;
  v_overhead := v_direct_cost * v_overhead_pct / 100;
  v_true_cost := round(v_direct_cost + v_overhead, 2);
  v_charge := round(greatest(coalesce((p_inputs->>'client_charge')::numeric, 0), v_true_cost / nullif(1 - v_margin_pct / 100, 0)), 2);
  RETURN jsonb_build_object('organization_id', v_org, 'currency', coalesce(p_inputs->>'currency', 'NZD'), 'true_cost', v_true_cost, 'client_charge', v_charge, 'gross_margin', round(v_charge - v_true_cost, 2), 'gross_margin_pct', round((v_charge - v_true_cost) / nullif(v_charge, 0) * 100, 2), 'breakdown', jsonb_build_object('loaded_labour', round(v_labour, 2), 'vehicle_travel', round(v_vehicle, 2), 'depreciation_annual', round(v_depreciation, 2), 'equipment', round(v_equipment, 2), 'direct_operating', round(v_direct, 2), 'allocated_overhead', round(v_overhead, 2)), 'inputs', p_inputs, 'basis', 'server_calculated_estimate', 'approval_required', true);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_finance_quote_cost"(p_inputs jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid)
 RETURNS SETOF finance_service_profitability
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_row public.finance_service_profitability%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;

  RETURN QUERY
  WITH quote_estimates AS (
    SELECT
      sa.id as service_agreement_id,
      sa.client_organization_id,
      'quote' as service_type,
      NULL::uuid as location_id,
      COALESCE(SUM(CASE WHEN ct.category_name = 'labour' THEN qci.cost_amount ELSE 0 END), 0) as est_labour,
      COALESCE(SUM(CASE WHEN ct.category_name = 'vehicle' THEN qci.cost_amount ELSE 0 END), 0) as est_vehicle,
      COALESCE(SUM(CASE WHEN ct.category_name = 'materials' THEN qci.cost_amount ELSE 0 END), 0) as est_materials,
      COALESCE(SUM(CASE WHEN ct.category_name = 'overhead' THEN qci.cost_amount ELSE 0 END), 0) as est_overhead,
      COALESCE(SUM(qci.cost_amount), 0) as est_total,
      COALESCE(SUM(qci.invoice_amount), 0) as quoted_charge
    FROM public.service_agreements sa
    LEFT JOIN public.quotes q ON sa.id = q.service_agreement_id AND q.status IN ('approved','accepted','invoiced')
    LEFT JOIN public.quote_cost_items qci ON q.id = qci.quote_id
    LEFT JOIN public.finance_cost_categories ct ON qci.cost_category_id = ct.id
    WHERE sa.provider_organization_id = v_org
    GROUP BY sa.id, sa.client_organization_id
  ),
  actual_costs AS (
    SELECT
      fsc.service_agreement_id,
      fsc.client_organization_id,
      fsc.site_id as location_id,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'labour' THEN fsc.total_cost ELSE 0 END), 0) as act_labour,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'vehicle' THEN fsc.total_cost ELSE 0 END), 0) as act_vehicle,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'materials' THEN fsc.total_cost ELSE 0 END), 0) as act_materials,
      COALESCE(SUM(CASE WHEN fsc.cost_type = 'overhead' THEN fsc.total_cost ELSE 0 END), 0) as act_overhead,
      COALESCE(SUM(fsc.total_cost), 0) as act_total,
      COUNT(*) as cost_lines
    FROM public.finance_service_costs fsc
    WHERE fsc.organization_id = v_org AND fsc.pl_period_id = p_pl_period_id
    GROUP BY fsc.service_agreement_id, fsc.client_organization_id, fsc.site_id
  ),
  combined AS (
    SELECT
      COALESCE(qe.service_agreement_id, ac.service_agreement_id) as sa_id,
      COALESCE(qe.client_organization_id, ac.client_organization_id) as client_org,
      qe.service_type,
      COALESCE(ac.location_id, qe.location_id) as loc_id,
      qe.est_labour, ac.act_labour,
      qe.est_vehicle, ac.act_vehicle,
      qe.est_materials, ac.act_materials,
      qe.est_overhead, ac.act_overhead,
      qe.est_total, ac.act_total,
      qe.quoted_charge
    FROM quote_estimates qe
    FULL JOIN actual_costs ac ON qe.service_agreement_id = ac.service_agreement_id AND qe.location_id IS NOT DISTINCT FROM ac.location_id
  )
  INSERT INTO public.finance_service_profitability(
    organization_id, pl_period_id, service_agreement_id, client_organization_id, service_type, location_id,
    estimated_labour, actual_labour, labour_variance_pct,
    estimated_vehicle, actual_vehicle, vehicle_variance_pct,
    estimated_materials, actual_materials, materials_variance_pct,
    estimated_overhead, actual_overhead, overhead_variance_pct,
    estimated_total_cost, actual_total_cost, total_variance_pct,
    estimated_margin_pct, actual_margin_pct, margin_impact_pct,
    client_invoice_total, net_profit, work_unit_count, invoice_count, created_by
  )
  SELECT
    v_org, p_pl_period_id, c.sa_id, c.client_org, c.service_type, c.loc_id,
    c.est_labour, c.act_labour, 
    CASE WHEN c.est_labour > 0 THEN ROUND(((c.act_labour - c.est_labour) / c.est_labour) * 100, 2) ELSE NULL END,
    c.est_vehicle, c.act_vehicle,
    CASE WHEN c.est_vehicle > 0 THEN ROUND(((c.act_vehicle - c.est_vehicle) / c.est_vehicle) * 100, 2) ELSE NULL END,
    c.est_materials, c.act_materials,
    CASE WHEN c.est_materials > 0 THEN ROUND(((c.act_materials - c.est_materials) / c.est_materials) * 100, 2) ELSE NULL END,
    c.est_overhead, c.act_overhead,
    CASE WHEN c.est_overhead > 0 THEN ROUND(((c.act_overhead - c.est_overhead) / c.est_overhead) * 100, 2) ELSE NULL END,
    c.est_total, c.act_total,
    CASE WHEN c.est_total > 0 THEN ROUND(((c.act_total - c.est_total) / c.est_total) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.est_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.act_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    CASE WHEN c.quoted_charge > 0 THEN ROUND(((c.quoted_charge - c.act_total) / c.quoted_charge) * 100, 2) ELSE NULL END,
    c.quoted_charge, c.quoted_charge - c.act_total,
    NULL::integer, NULL::integer, v_actor
  FROM combined c;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_service_profitability_snapshot"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
declare
  v_rules             zone_compliance_matrix%rowtype;
  v_zone              location_zones%rowtype;
  v_scv               canonical_scv%rowtype;
  v_streak            integer := 0;   -- current consecutive-night streak
  v_nights_month      integer := 0;   -- distinct verified nights this calendar month
  v_is_compliant      boolean := true;
  v_reason            text := 'compliant';
  v_month_start_date  date := date_trunc('month', current_date)::date;
  v_rule_type         text;
  v_scv_exempts       boolean := true;
begin
  -- Fetch zone rule_type + scv_exempts_restriction (0191).
  select * into v_zone from location_zones where id = p_zone_id;
  if found then
    v_rule_type   := coalesce(v_zone.rule_type, 'overnight_limited');
    v_scv_exempts := coalesce(v_zone.scv_exempts_restriction, true);
  else
    v_rule_type   := 'overnight_limited';
    v_scv_exempts := true;
  end if;

  -- ── GATE 1: prohibited / day_visit_only (unchanged from 0194) ────────────
  if v_rule_type in ('prohibited', 'day_visit_only') then
    select count(distinct overnight_date)
    into v_streak
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
      and overnight_date >= v_month_start_date;

    if v_streak > 0 then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_overnight_permitted',
        'nights_this_zone',  v_streak,
        'nights_this_month', v_streak,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      false,
        'is_scv',            false
      );
    end if;
    return jsonb_build_object(
      'is_compliant',      true,
      'reason',            'no_overnight_yet',
      'nights_this_zone',  0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly',     null,
      'scv_required',      false,
      'is_scv',            false
    );
  end if;

  -- ── GATE 2: restricted / SCV gate (unchanged from 0194) ──────────────────
  if v_rule_type = 'restricted' and v_scv_exempts then
    select * into v_scv
    from canonical_scv
    where
      plate_number = p_plate
      and certificate_status = 'active'
      and (expiry_date is null or expiry_date >= current_date);

    if not found then
      return jsonb_build_object(
        'is_compliant',      false,
        'reason',            'no_scv_certificate',
        'nights_this_zone',  0,
        'nights_this_month', 0,
        'limit_consecutive', null,
        'limit_monthly',     null,
        'scv_required',      true,
        'is_scv',            false
      );
    end if;
  end if;

  -- ── Night-count path (unrestricted / overnight_limited / restricted+SCV) ──

  -- Get current compliance rules.
  select * into v_rules
  from zone_compliance_matrix
  where
    zone_id = p_zone_id
    and organization_id = p_org_id
    and is_current = true
    and effective_from <= current_date
    and (effective_to is null or effective_to >= current_date)
  order by version desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'is_compliant', true,
      'reason', 'no_rules_configured',
      'nights_this_zone', 0,
      'nights_this_month', 0,
      'limit_consecutive', null,
      'limit_monthly', null,
      'scv_required', false,
      'is_scv', (v_scv.id is not null)
    );
  end if;

  -- SCV gate for overnight_limited zones (unchanged from 0194).
  if v_rule_type not in ('restricted') and v_rules.scv_required then
    if v_scv.id is null then
      select * into v_scv
      from canonical_scv
      where
        plate_number = p_plate
        and certificate_status = 'active'
        and (expiry_date is null or expiry_date >= current_date);

      if not found then
        return jsonb_build_object(
          'is_compliant', false,
          'reason', 'no_scv_certificate',
          'nights_this_zone', 0,
          'nights_this_month', 0,
          'limit_consecutive', v_rules.max_consecutive_nights,
          'limit_monthly', v_rules.max_nights_per_month,
          'scv_required', true,
          'is_scv', false
        );
      end if;
    end if;
  end if;

  -- ── COUNTER 1: consecutive streak (THE FIX) ──────────────────────────────
  -- Reads from vehicle_overnight_sessions for BOTH verification modes.
  -- For two_photo_verified: sessions created by the two-photo morning scan.
  -- For single_daily_observation: sessions created by process-officer-scan
  --   using the movement-check result (stationary -> verified_overnight).
  -- For historical import (#79): sessions with evidence_strength='inferred'.
  -- All three produce verified_overnight rows; the streak algorithm is identical.
  --
  -- Algorithm: subtract ROW_NUMBER() (as an interval) from each date.
  -- Consecutive dates produce the same anchor (streak_group); a gap of >=1
  -- day produces a different anchor. Current streak = count of dates in the
  -- group containing max(overnight_date). No cursor, no loop.
  with dated as (
    select distinct overnight_date
    from vehicle_overnight_sessions
    where
      plate_number = p_plate
      and zone_id = p_zone_id
      and organization_id = p_org_id
      and verification_status = 'verified_overnight'
  ),
  grouped as (
    select
      overnight_date,
      overnight_date
        - (row_number() over (order by overnight_date))::integer * interval '1 day'
        as streak_group
    from dated
  ),
  current_group as (
    select streak_group
    from grouped
    order by overnight_date desc
    limit 1
  )
  select coalesce(count(*), 0)
  into v_streak
  from grouped
  where streak_group = (select streak_group from current_group);

  -- ── COUNTER 2: monthly total ────────────────────────────────────────────────
  -- Distinct verified overnight nights since the 1st of the calendar month,
  -- regardless of gaps or streaks. Resets on the 1st.
  select coalesce(count(distinct overnight_date), 0)
  into v_nights_month
  from vehicle_overnight_sessions
  where
    plate_number = p_plate
    and organization_id = p_org_id
    and verification_status = 'verified_overnight'
    and overnight_date >= v_month_start_date;

  -- ── Limit comparisons ────────────────────────────────────────────────────────────
  -- BREACH fires when the count EXCEEDS the limit (> not >=).
  -- Owner-confirmed: limit=3 means 3 nights are allowed; the 4th breaches.
  -- Consecutive checked first; if both trip simultaneously, consecutive wins.

  if v_rules.max_consecutive_nights is not null
    and v_streak > v_rules.max_consecutive_nights then
    v_is_compliant := false;
    v_reason := 'consecutive_night_limit_exceeded';
  end if;

  if v_is_compliant
    and v_rules.max_nights_per_month is not null
    and v_nights_month > v_rules.max_nights_per_month then
    v_is_compliant := false;
    v_reason := 'monthly_limit_exceeded';
  end if;

  -- nights_this_zone = streak (what the consecutive limit is about).
  -- nights_this_month = monthly total (what the monthly limit is about).
  -- process-officer-scan Step 8a at_risk detection reads both and fires
  -- when streak == max_consecutive_nights OR total == max_nights_per_month
  -- (AT the limit, next night would breach) -- no code change needed there.
  return jsonb_build_object(
    'is_compliant',      v_is_compliant,
    'reason',            v_reason,
    'nights_this_zone',  v_streak,
    'nights_this_month', v_nights_month,
    'limit_consecutive', v_rules.max_consecutive_nights,
    'limit_monthly',     v_rules.max_nights_per_month,
    'scv_required',      coalesce(v_rules.scv_required, false),
    'is_scv',            (v_scv.id is not null)
  );
end;
$function$;
COMMENT ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) IS 'Compliance engine. Layer 2 (0195): two independent counters. (1) Consecutive streak (nights_this_zone): length of the current unbroken run of verified_overnight sessions, using ROW_NUMBER()-subtraction streak-group algorithm -- resets to 1 after any gap. Breach fires when streak > max_consecutive_nights (the 4th night breaches when limit is 3). (2) Monthly total (nights_this_month): count(distinct overnight_date) from verified sessions since the 1st of the calendar month, regardless of gaps. Breach fires when total > max_nights_per_month. Both limits are independent; consecutive checked first. Unified source: both two_photo_verified and single_daily_observation modes read from vehicle_overnight_sessions (sessions created by process-officer-scan using movement-check for live single-daily orgs, or by historical import with evidence_strength=inferred). Layer 1 (0194) rule_type gate runs first. Layer 0 (0193) verified-session source. #74.';
REVOKE ALL ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."calculate_vehicle_compliance"(p_plate text, p_zone_id uuid, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
BEGIN
  SELECT up.role INTO v_role
  FROM user_profiles up
  WHERE up.id = p_user_id;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  -- grand_master can approve anything
  IF v_role = 'grand_master' THEN
    RETURN true;
  END IF;

  -- master/admin: check tree-based access
  IF v_role IN ('master', 'admin') THEN
    -- Use a direct check mirroring is_admin_for_org but parameterized by user
    RETURN EXISTS (
      SELECT 1 FROM user_profiles up
      WHERE up.id = p_user_id
        AND (
          -- master: descendant tree
          (up.role = 'master' AND (
            p_action_org_id = ANY(get_descendant_organizations(up.employer_organization_id))
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
          OR
          -- admin: direct org or descendant tree
          (up.role = 'admin' AND (
            up.organization_id = p_action_org_id
            OR p_action_org_id = ANY(get_descendant_organizations(up.organization_id))
            -- Agreement-based (0271 Model A)
            OR EXISTS (
              SELECT 1 FROM service_agreements sa
              WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
                AND sa.client_organization_id = p_action_org_id
                AND (up.organization_id = sa.provider_organization_id
                     OR up.employer_organization_id = sa.provider_organization_id)
            )
          ))
        )
    );
  END IF;

  RETURN false;
END;
$function$;
COMMENT ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) IS 'Tree-based authorization check: can user p_user_id approve actions for org p_action_org_id? Mirrors is_admin_for_org logic but parameterized by user_id (not auth.uid()). Used by bob-proposal-approver edge function. #16/#18.';
REVOKE ALL ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."can_approve_action"(p_user_id uuid, p_action_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text)
 RETURNS shift_swaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_swap public.shift_swaps%rowtype; v_user uuid; v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_reason is null then raise exception 'A cancellation reason is required'; end if;
  select sw.* into v_swap from public.shift_swaps sw where sw.id = p_swap_id for update;
  if not found then raise exception 'Shift swap request not found'; end if;
  if v_swap.status <> p_expected_status or v_swap.status <> 'pending' then raise exception 'Only the current pending swap request can be cancelled'; end if;
  select coalesce(sp.user_id, sp.id) into v_user from public.staff_profiles sp where sp.id = v_swap.original_staff_id;
  if v_user is distinct from v_actor then raise exception 'Only the requesting officer can cancel this swap'; end if;
  update public.shift_swaps set status = 'cancelled', declined_reason = v_reason where id = v_swap.id returning * into v_swap;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_swap.organization_id, v_actor, 'shift_swap_cancelled', 'shift_swaps', v_swap.id, jsonb_build_object('reason', v_reason, 'original_shift_id', v_swap.original_shift_id));
  return v_swap;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cancel_shift_swap"(p_swap_id uuid, p_expected_status text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_kind text;
BEGIN
  IF p_location_id IS NULL THEN RETURN NULL; END IF;
  v_kind := CASE WHEN p_key IS NOT NULL THEN 'site' WHEN p_kind_hint IN ('site', 'zone') THEN p_kind_hint ELSE 'zone' END;
  v_id := CASE WHEN p_key IS NOT NULL
    THEN public.ensure_canonical_place('site', 'site:' || p_key, p_name, p_address, jsonb_build_object('created_from', 'locations', 'source_id', p_location_id))
    ELSE public.ensure_canonical_place(v_kind, v_kind || ':' || p_location_id::text, p_name, NULL, jsonb_build_object('created_from', 'locations', 'source_id', p_location_id)) END;
  INSERT INTO public.canonical_place_links (canonical_place_id, source_table, source_id, organization_id, link_kind, source_key, metadata)
  VALUES (v_id, 'locations', p_location_id, p_org, 'projection', p_location_id::text, '{}'::jsonb)
  ON CONFLICT (source_table, source_id) DO UPDATE SET canonical_place_id = EXCLUDED.canonical_place_id;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."canonical_place_for_house"(p_location_id uuid, p_org uuid, p_name text, p_address text, p_key text, p_kind_hint text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."capture_accepted_quote_commercial_snapshot"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'accepted' and new.service_agreement_id is not null and old.status is distinct from 'accepted' then
    insert into public.quote_commercial_snapshots(
      quote_id,provider_organization_id,client_organization_id,tender_id,discount_schedule_id,
      currency,gst_rate,discount_pct,total_cost,subtotal_charge,discount_amount,gst_amount,total_charge,
      pricing_detail,accepted_at,accepted_by
    )
    values(
      new.id,new.provider_org_id,new.client_org_id,new.tender_id,new.discount_schedule_id,
      new.currency,new.gst_rate,new.discount_pct,new.total_cost,new.subtotal_charge,new.discount_amount,new.gst_amount,new.total_charge,
      jsonb_build_object(
        'quote_lines', coalesce((select jsonb_agg(jsonb_build_object('id',line.id,'kind',line.kind,'description',line.description,'quantity',line.quantity,'unit_cost',line.unit_cost,'unit_charge',line.unit_charge,'module_key',line.module_key,'site_id',line.site_id) order by line.line_order) from public.quote_lines line where line.quote_id = new.id), '[]'::jsonb),
        'proposal_modules', coalesce((select jsonb_agg(jsonb_build_object('module_key',module.module_key,'sla_minutes',module.sla_minutes,'service_window',module.service_window,'pricing_basis',module.pricing_basis,'rate_rule_id',module.rate_rule_id,'rate_rule_type',rule.rate_type,'rate_rule_amount',rule.amount) order by module.module_key) from public.quote_proposal_modules module left join public.rate_rules rule on rule.id = module.rate_rule_id where module.quote_id = new.id), '[]'::jsonb)
      ),
      coalesce(new.accepted_at, now()),coalesce(new.accepted_by, auth.uid())
    ) on conflict (quote_id) do nothing;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_accepted_quote_commercial_snapshot"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."capture_effective_rule_snapshot"(p_organization_id uuid, p_module_key text, p_governing_jurisdiction_id uuid DEFAULT NULL::uuid, p_governing_jurisdiction_name text DEFAULT NULL::text, p_matched_zone_id uuid DEFAULT NULL::uuid, p_matched_site_id uuid DEFAULT NULL::uuid, p_matched_location_id uuid DEFAULT NULL::uuid, p_rule_set_id uuid DEFAULT NULL::uuid, p_rule_set_name text DEFAULT NULL::text, p_jurisdiction_rule_set_id uuid DEFAULT NULL::uuid, p_effective_rules jsonb DEFAULT '{}'::jsonb, p_resolution_status text DEFAULT 'outside_all_geofences'::text, p_source_event_table text DEFAULT NULL::text, p_source_event_id uuid DEFAULT NULL::uuid, p_captured_at timestamp with time zone DEFAULT now())
 RETURNS effective_rule_snapshots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.effective_rule_snapshots%rowtype;
BEGIN
  IF p_organization_id IS NULL OR nullif(trim(coalesce(p_module_key, '')), '') IS NULL THEN
    RAISE EXCEPTION 'organization_id and module_key are required';
  END IF;

  INSERT INTO public.effective_rule_snapshots (
    organization_id, module_key, governing_jurisdiction_id, governing_jurisdiction_name,
    matched_zone_id, matched_site_id, matched_location_id, rule_set_id, rule_set_name,
    jurisdiction_rule_set_id, effective_rules, resolution_status,
    source_event_table, source_event_id, captured_at
  ) VALUES (
    p_organization_id, p_module_key, p_governing_jurisdiction_id,
    p_governing_jurisdiction_name, p_matched_zone_id, p_matched_site_id,
    p_matched_location_id, p_rule_set_id, p_rule_set_name,
    p_jurisdiction_rule_set_id, coalesce(p_effective_rules, '{}'::jsonb),
    coalesce(p_resolution_status, 'outside_all_geofences'),
    p_source_event_table, p_source_event_id, coalesce(p_captured_at, now())
  )
  ON CONFLICT (source_event_table, source_event_id) DO UPDATE
    SET organization_id = EXCLUDED.organization_id,
        module_key = EXCLUDED.module_key,
        governing_jurisdiction_id = EXCLUDED.governing_jurisdiction_id,
        governing_jurisdiction_name = EXCLUDED.governing_jurisdiction_name,
        matched_zone_id = EXCLUDED.matched_zone_id,
        matched_site_id = EXCLUDED.matched_site_id,
        matched_location_id = EXCLUDED.matched_location_id,
        rule_set_id = EXCLUDED.rule_set_id,
        rule_set_name = EXCLUDED.rule_set_name,
        jurisdiction_rule_set_id = EXCLUDED.jurisdiction_rule_set_id,
        effective_rules = EXCLUDED.effective_rules,
        resolution_status = EXCLUDED.resolution_status,
        captured_at = EXCLUDED.captured_at
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_effective_rule_snapshot"(p_organization_id uuid, p_module_key text, p_governing_jurisdiction_id uuid, p_governing_jurisdiction_name text, p_matched_zone_id uuid, p_matched_site_id uuid, p_matched_location_id uuid, p_rule_set_id uuid, p_rule_set_name text, p_jurisdiction_rule_set_id uuid, p_effective_rules jsonb, p_resolution_status text, p_source_event_table text, p_source_event_id uuid, p_captured_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_effective_rule_snapshot"(p_organization_id uuid, p_module_key text, p_governing_jurisdiction_id uuid, p_governing_jurisdiction_name text, p_matched_zone_id uuid, p_matched_site_id uuid, p_matched_location_id uuid, p_rule_set_id uuid, p_rule_set_name text, p_jurisdiction_rule_set_id uuid, p_effective_rules jsonb, p_resolution_status text, p_source_event_table text, p_source_event_id uuid, p_captured_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_effective_rule_snapshot"(p_organization_id uuid, p_module_key text, p_governing_jurisdiction_id uuid, p_governing_jurisdiction_name text, p_matched_zone_id uuid, p_matched_site_id uuid, p_matched_location_id uuid, p_rule_set_id uuid, p_rule_set_name text, p_jurisdiction_rule_set_id uuid, p_effective_rules jsonb, p_resolution_status text, p_source_event_table text, p_source_event_id uuid, p_captured_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."capture_effective_rule_snapshot"(p_organization_id uuid, p_module_key text, p_governing_jurisdiction_id uuid, p_governing_jurisdiction_name text, p_matched_zone_id uuid, p_matched_site_id uuid, p_matched_location_id uuid, p_rule_set_id uuid, p_rule_set_name text, p_jurisdiction_rule_set_id uuid, p_effective_rules jsonb, p_resolution_status text, p_source_event_table text, p_source_event_id uuid, p_captured_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."capture_observation_effective_rule_snapshot"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb := coalesce(NEW.geofence_context, '{}'::jsonb);
  v_jur_id uuid := CASE WHEN NULLIF(v_ctx->>'governing_jurisdiction_id', '') IS NOT NULL THEN (v_ctx->>'governing_jurisdiction_id')::uuid ELSE NULL END;
  v_jur_name text := NULLIF(v_ctx->>'governing_jurisdiction_name', '');
  v_effective jsonb := coalesce(v_ctx->'effective_rules', '{}'::jsonb);
  v_status text := coalesce(NULLIF(v_ctx->>'resolution_status', ''), 'outside_all_geofences');
BEGIN
  IF NEW.module_key IS NULL OR NULLIF(trim(NEW.module_key), '') IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.effective_rule_snapshots (
    organization_id,
    module_key,
    governing_jurisdiction_id,
    governing_jurisdiction_name,
    matched_zone_id,
    matched_site_id,
    matched_location_id,
    effective_rules,
    resolution_status,
    source_event_table,
    source_event_id,
    captured_at
  ) VALUES (
    NEW.organization_id,
    NEW.module_key,
    v_jur_id,
    v_jur_name,
    NEW.zone_id,
    NEW.site_id,
    NEW.location_id,
    v_effective,
    v_status,
    'observations',
    NEW.id,
    NEW.observed_at
  )
  ON CONFLICT (source_event_table, source_event_id) DO UPDATE
    SET organization_id = EXCLUDED.organization_id,
        module_key = EXCLUDED.module_key,
        governing_jurisdiction_id = EXCLUDED.governing_jurisdiction_id,
        governing_jurisdiction_name = EXCLUDED.governing_jurisdiction_name,
        matched_zone_id = EXCLUDED.matched_zone_id,
        matched_site_id = EXCLUDED.matched_site_id,
        matched_location_id = EXCLUDED.matched_location_id,
        effective_rules = EXCLUDED.effective_rules,
        resolution_status = EXCLUDED.resolution_status,
        captured_at = EXCLUDED.captured_at;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."capture_observation_effective_rule_snapshot"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV governance access denied'; END IF;
  SELECT jsonb_build_object(
    'organization_id', p_organization_id,
    'live_templates', count(*) FILTER (WHERE o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL),
    'live_face_templates', count(*) FILTER (WHERE o.face_vec IS NOT NULL),
    'oldest_live_template_at', min(o.created_at) FILTER (WHERE o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL),
    'expired_templates', count(*) FILTER (WHERE o.attributes ? 'biometric_templates_expired_at'),
    'rejected_still_holding_templates', count(*) FILTER (WHERE o.review_state = 'rejected' AND (o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL)),
    'last_expiry_run_at', (SELECT max(a.created_at) FROM public.audit_log a WHERE a.organization_id = p_organization_id AND a.action = 'cctv_biometric_templates_expired'),
    'purpose', 'Templates are used only to suggest same-or-similar sightings within this organisation; identity is always a reviewer decision.',
    'default_retention', '90 days'
  ) INTO v_result
  FROM public.cctv_entity_observations o
  WHERE o.organization_id = p_organization_id AND o.entity_kind = 'person';
  RETURN v_result;
END $function$;
COMMENT ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) IS 'Org-scoped biometric holdings readout: live/expired template counts, oldest live template, rejected sightings still holding templates, last expiry run, stated purpose and default retention.';
REVOKE ALL ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_biometric_governance"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_evidence public.evidence_items%rowtype;
  v_events jsonb;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.org_access_allowed(v_evidence.organization_id) THEN RAISE EXCEPTION 'CCTV custody access denied'; END IF;

  SELECT coalesce(jsonb_agg(event ORDER BY (event->>'at')::timestamptz), '[]'::jsonb) INTO v_events
  FROM (
    SELECT jsonb_build_object('at', a.created_at, 'kind', a.action, 'actor_user_id', a.actor_user_id,
             'detail', CASE a.action
               WHEN 'cctv_evidence_locked' THEN jsonb_build_object('reason', a.metadata->>'reason', 'sha256_hash', a.metadata->>'sha256_hash')
               WHEN 'cctv_bookmark_created' THEN jsonb_build_object('incident_id', a.metadata->>'incident_id', 'bookmark_at', a.metadata->>'bookmark_at', 'severity', a.metadata->>'severity')
               WHEN 'cctv_evidence_integrity_verified' THEN jsonb_build_object('checked_by', a.metadata->>'checked_by', 'check_count', a.metadata->>'check_count')
               WHEN 'cctv_evidence_integrity_mismatch' THEN jsonb_build_object('checked_by', a.metadata->>'checked_by', 'observed_sha256', a.metadata->>'observed_sha256', 'expected_sha256', a.metadata->>'expected_sha256')
               ELSE '{}'::jsonb END) AS event
      FROM public.audit_log a
     WHERE a.organization_id = v_evidence.organization_id
       AND ((a.target_table = 'evidence_items' AND a.target_id = v_evidence.id)
            OR (a.action = 'cctv_bookmark_created' AND (a.metadata->>'evidence_item_id')::uuid = v_evidence.id))
    UNION ALL
    SELECT jsonb_build_object('at', r.generated_at, 'kind', 'cctv_report_issued', 'actor_user_id', r.generated_by,
             'detail', jsonb_build_object('receipt_id', r.id, 'batch_id', r.batch_id, 'observation_count', r.observation_count, 'sha256', r.sha256))
      FROM public.cctv_report_receipts r
     WHERE r.evidence_item_id = v_evidence.id
  ) trail;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'evidence_item_id', v_evidence.id,
    'storage_path', v_evidence.storage_path,
    'captured_at', v_evidence.captured_at,
    'sha256_hash', v_evidence.sha256_hash,
    'source_size_bytes', (v_evidence.metadata->>'source_size_bytes')::bigint,
    'source_hashed_at', v_evidence.metadata->>'source_hashed_at',
    'is_court_ready', v_evidence.is_court_ready,
    'locked_at', v_evidence.locked_at,
    'lock', v_evidence.metadata->'evidence_lock',
    'retention_hold', v_evidence.retention_hold,
    'retention_reason', v_evidence.retention_reason,
    'integrity', v_evidence.metadata->'integrity',
    'events', v_events
  ));
END $function$;
COMMENT ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) IS 'Org-scoped custody record for one CCTV recording: hash and provenance, lock, retention hold, latest integrity check, and the ordered trail of lock / bookmark / integrity / export events.';
REVOKE ALL ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_evidence_custody"(p_evidence_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer)
 RETURNS vector
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_arr real[];
BEGIN
  IF p_embedding IS NULL OR jsonb_typeof(p_embedding) <> 'array' OR jsonb_array_length(p_embedding) <> p_dims THEN RETURN NULL; END IF;
  SELECT array_agg(t.x::real ORDER BY t.ord) INTO v_arr FROM jsonb_array_elements_text(p_embedding) WITH ORDINALITY AS t(x, ord);
  RETURN v_arr::public.vector;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $function$;
REVOKE ALL ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."cctv_jsonb_to_vector"(p_embedding jsonb, p_dims integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_count integer;
  v_org_count    integer;
begin
  -- Per-caller: max 5 invites in the last 5 minutes
  select count(*) into v_caller_count
    from invite_rate_log
   where caller_id = p_caller_id
     and attempted_at > now() - interval '5 minutes';

  if v_caller_count >= 5 then
    return false;
  end if;

  -- Per-target-org: max 1 invite in the last 2 minutes
  select count(*) into v_org_count
    from invite_rate_log
   where target_org_id = p_target_org_id
     and attempted_at > now() - interval '2 minutes';

  if v_org_count >= 1 then
    return false;
  end if;

  -- Allowed — record the attempt
  insert into invite_rate_log (caller_id, target_org_id)
  values (p_caller_id, p_target_org_id);

  return true;
end;
$function$;
COMMENT ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) IS 'Rate-limit gate for invite-org (#361). Returns true if allowed, false if rate-limited. Per-caller: 5/5min. Per-target-org: 1/2min.';
REVOKE ALL ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."check_invite_rate_limit"(p_caller_id uuid, p_target_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer DEFAULT 500, p_window_nights integer DEFAULT 1, p_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
declare
  v_nights      integer := 0;
  v_last_seen   timestamptz;
  v_point       geography;
  v_window_start timestamptz;
begin
  if p_radius_m is null or p_radius_m <= 0
     or p_window_nights is null or p_window_nights <= 0 then
    return jsonb_build_object(
      'breach', false,
      'nights_within_radius', 0,
      'radius_m', p_radius_m,
      'window_nights', p_window_nights,
      'last_seen_at', null,
      'reason', 'rule_disabled'
    );
  end if;

  v_point := st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography;
  -- Trailing window: p_window_nights calendar days back from p_at.
  v_window_start := (p_at at time zone 'Pacific/Auckland')::date
                    - (p_window_nights - 1) * interval '1 day';

  select
    count(distinct ((observed_at at time zone 'Pacific/Auckland')::date)),
    max(observed_at)
  into v_nights, v_last_seen
  from observations
  where organization_id = p_org_id
    and plate_number = p_plate
    and gps_point is not null
    and observed_at >= v_window_start
    and observed_at <= p_at
    and st_dwithin(gps_point::geography, v_point, p_radius_m);

  return jsonb_build_object(
    'breach', v_nights >= p_window_nights,
    'nights_within_radius', coalesce(v_nights, 0),
    'radius_m', p_radius_m,
    'window_nights', p_window_nights,
    'last_seen_at', v_last_seen,
    'reason', case when v_nights >= p_window_nights
                   then 'repeat_stay_within_radius' else 'within_limit' end
  );
end;
$function$;
COMMENT ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) IS 'Counts distinct nights a plate was observed within p_radius_m of a point over a trailing p_window_nights window. Returns JSON verdict (breach when nights >= window). Distances via ST_DWithin on geography. NCC 500m rule.';
REVOKE ALL ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."check_repeat_stay"(p_plate text, p_lat double precision, p_lng double precision, p_org_id uuid, p_radius_m integer, p_window_nights integer, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 900)
 RETURNS TABLE(id uuid, organization_id uuid, evidence_item_id uuid, domain text, status text, lease_token uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_job_id IS NULL OR p_lease_token IS NULL OR p_lease_seconds NOT BETWEEN 60 AND 7200 THEN
    RAISE EXCEPTION 'Valid job, lease, and lease duration are required';
  END IF;

  RETURN QUERY
  UPDATE public.inference_jobs j
     SET status = 'processing', stage = 'claimed', attempt_count = j.attempt_count + 1,
         lease_token = p_lease_token, lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
         heartbeat_at = clock_timestamp(), error_message = NULL
   WHERE j.id = p_job_id AND j.domain = 'video_motion' AND j.status = 'queued'
   RETURNING j.id, j.organization_id, j.evidence_item_id, j.domain, j.status, j.lease_token;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing_count integer;
begin
  -- Acquire an advisory lock scoped to this org. hashtext returns a stable
  -- int4 hash. The lock is transaction-scoped (released on COMMIT/ROLLBACK).
  perform pg_advisory_xact_lock(hashtext(p_org_id::text));

  -- Check for existing users INSIDE the lock
  select count(*) into v_existing_count
    from user_profiles
   where organization_id = p_org_id;

  if v_existing_count > 0 then
    raise exception 'Organisation already has users — duplicate first-user prevented'
      using errcode = '23505'; -- unique_violation
  end if;

  -- Insert the first user profile
  insert into user_profiles (id, organization_id, display_name, role, email)
  values (p_user_id, p_org_id, p_display_name, p_role, p_email)
  on conflict (id) do update set
    organization_id = excluded.organization_id,
    display_name    = excluded.display_name,
    role            = excluded.role,
    email           = excluded.email;
end;
$function$;
COMMENT ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) IS 'Race-safe first-user creation for invite-org (#361). Uses pg_advisory_xact_lock to serialise per-org, making duplicate-first-user impossible.';
REVOKE ALL ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."claim_first_org_user"(p_org_id uuid, p_user_id uuid, p_display_name text, p_role text, p_email text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text DEFAULT 'open'::text)
 RETURNS shift_coverage_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_profile public.user_profiles%rowtype;
  v_request public.shift_coverage_requests%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id = v_user_id and deactivated_at is null and role in ('officer', 'admin_officer');
  if not found then raise exception 'Active officer profile required'; end if;
  select * into v_request from public.shift_coverage_requests where id = p_request_id for update;
  if not found then raise exception 'Coverage request not found'; end if;
  if v_request.organization_id <> v_profile.organization_id then raise exception 'Coverage request is outside the officer organization'; end if;
  if v_request.status <> p_expected_status then raise exception 'Coverage request changed from expected status % to %', p_expected_status, v_request.status; end if;
  if v_request.status <> 'open' then raise exception 'Coverage request is no longer open'; end if;
  if v_request.shift_date < current_date then raise exception 'Past coverage cannot be claimed'; end if;
  update public.shift_coverage_requests set status = 'claimed', claimed_by = v_user_id, claimed_at = clock_timestamp()
  where id = p_request_id returning * into v_request;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_request.organization_id, v_user_id, 'shift_coverage_claimed', 'shift_coverage_requests', v_request.id,
    jsonb_build_object('shift_date', v_request.shift_date, 'start_time', v_request.start_time, 'site_id', v_request.site_id));
  return v_request;
end;
$function$;
COMMENT ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) IS 'Atomically claims open coverage for the authenticated active officer and records audit provenance.';
REVOKE ALL ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."claim_shift_coverage"(p_request_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text DEFAULT 'Pacific/Auckland'::text)
 RETURNS TABLE(overnight_date date, scan_window text)
 LANGUAGE sql
 STABLE
AS $function$
  select
    case
      when ((p_observed_at at time zone p_timezone)::time >= time '00:00'
        and (p_observed_at at time zone p_timezone)::time < time '12:00')
      then ((p_observed_at at time zone p_timezone)::date - 1)
      else (p_observed_at at time zone p_timezone)::date
    end as overnight_date,
    case
      when ((p_observed_at at time zone p_timezone)::time >= time '00:00'
        and (p_observed_at at time zone p_timezone)::time < time '12:00')
      then 'morning'
      else 'evening'
    end as scan_window;
$function$;
COMMENT ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) IS 'Returns overnight_date and scan window for the two-photo FC verification model using local midnight boundary.';
REVOKE ALL ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."classify_fc_overnight_window"(p_observed_at timestamp with time zone, p_timezone text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid)
 RETURNS finance_pl_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_snapshot public.finance_pl_snapshots%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  IF v_period.status IN ('closed','archived') THEN RAISE EXCEPTION 'Period is already closed or archived'; END IF;
  WITH cost_summary AS (
    SELECT COALESCE(SUM(CASE WHEN cost_type = 'labour' THEN total_cost ELSE 0 END), 0) AS total_labour,
      COALESCE(SUM(CASE WHEN cost_type = 'vehicle' THEN total_cost ELSE 0 END), 0) AS total_vehicle,
      COALESCE(SUM(CASE WHEN cost_type = 'materials' THEN total_cost ELSE 0 END), 0) AS total_materials,
      COALESCE(SUM(CASE WHEN cost_type = 'equipment' THEN total_cost ELSE 0 END), 0) AS total_equipment,
      COALESCE(SUM(CASE WHEN cost_type = 'overhead' THEN total_cost ELSE 0 END), 0) AS total_overhead,
      COALESCE(SUM(CASE WHEN cost_type = 'depreciation' THEN total_cost ELSE 0 END), 0) AS total_depreciation,
      COALESCE(SUM(total_cost), 0) AS total_cost, COUNT(*) AS cost_count
    FROM public.finance_service_costs WHERE pl_period_id = p_pl_period_id AND organization_id = v_org
  )
  INSERT INTO public.finance_pl_snapshots(organization_id, pl_period_id, total_labour, total_vehicle, total_materials, total_equipment, total_overhead, total_depreciation, total_cost, cost_line_count, total_revenue)
  SELECT v_org, p_pl_period_id, total_labour, total_vehicle, total_materials, total_equipment, total_overhead, total_depreciation, total_cost, cost_count,
    COALESCE((SELECT SUM(total_amount) FROM public.invoices WHERE organization_id = v_org AND invoice_date BETWEEN v_period.period_start AND v_period.period_end), 0)
  FROM cost_summary RETURNING * INTO v_snapshot;
  UPDATE public.finance_pl_periods SET status = 'closed', closed_at = now(), closed_by = v_actor, updated_at = now() WHERE id = p_pl_period_id RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_pl_period_closed', 'finance_pl_periods', v_period.id, jsonb_build_object('snapshot_id', v_snapshot.id, 'total_cost', v_snapshot.total_cost, 'total_revenue', v_snapshot.total_revenue));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."close_finance_pl_period"(p_pl_period_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text DEFAULT 'ended'::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(transmission_id uuid, state text, ended_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_trans public.ptt_transmissions%rowtype;
  v_final_state text := coalesce(p_state, 'ended');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;

  select t.* into v_trans from public.ptt_transmissions t where t.id = p_transmission_id for update;
  if not found then raise exception 'PTT transmission not found'; end if;
  if v_trans.speaker_user_id <> v_user_id and not public.is_admin_for_org(v_trans.organization_id) then
    raise exception 'Not authorised to update this PTT transmission';
  end if;

  if v_final_state not in ('ended', 'failed', 'emergency') then
    raise exception 'Invalid transmission end state %', p_state;
  end if;

  update public.ptt_transmissions
    set state = v_final_state,
        ended_at = clock_timestamp(),
        metadata = case when p_metadata is not null then metadata || p_metadata else metadata end
    where id = v_trans.id
    returning * into v_trans;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_trans.organization_id, v_user_id, 'ptt_transmission_ended', 'ptt_transmissions', v_trans.id,
    jsonb_build_object('state', v_final_state, 'duration_ms', extract(epoch from (v_trans.ended_at - v_trans.started_at)) * 1000)
  );

  return query select v_trans.id, v_trans.state, v_trans.ended_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."close_ptt_transmission"(p_transmission_id uuid, p_state text, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid)
 RETURNS TABLE(closure_id uuid, zone_id uuid, closure_type text, reason text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_point geometry := st_setsrid(st_point(p_lng, p_lat), 4326);
begin
  return query
  select
    zc.id,
    zc.zone_id,
    zc.closure_type,
    zc.reason
  from zone_closures zc
  join location_zones lz on lz.id = zc.zone_id
  where zc.organization_id = p_org_id
    and lz.organization_id = p_org_id
    and st_contains(lz.boundary, v_point)
    and zc.status = 'active'
    and zc.effective_from <= current_date
    and (zc.effective_to is null or zc.effective_to >= current_date)
  limit 1;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."closure_at_point"(p_lat double precision, p_lng double precision, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text)
 RETURNS double precision
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  geom_a geometry;
  geom_b geometry;
  dist double precision;
BEGIN
  -- Null/empty guard: return large sentinel (mismatch), never 0.
  IF p_geojson_a IS NULL OR p_geojson_b IS NULL
     OR trim(p_geojson_a) = '' OR trim(p_geojson_b) = '' THEN
    RETURN 1e9;
  END IF;

  BEGIN
    geom_a := ST_MakeValid(ST_GeomFromGeoJSON(p_geojson_a));
    geom_b := ST_MakeValid(ST_GeomFromGeoJSON(p_geojson_b));
  EXCEPTION WHEN OTHERS THEN
    -- Invalid GeoJSON: return large sentinel (mismatch), never 0.
    RETURN 1e9;
  END;

  -- Empty geometry guard
  IF geom_a IS NULL OR geom_b IS NULL
     OR ST_IsEmpty(geom_a) OR ST_IsEmpty(geom_b) THEN
    RETURN 1e9;
  END IF;

  -- ST_HausdorffDistance on geography returns metres.
  dist := ST_HausdorffDistance(ST_Transform(ST_SetSRID(geom_a, 4326), 2193), ST_Transform(ST_SetSRID(geom_b, 4326), 2193));

  -- Defensive: if the result is NULL or non-finite, return sentinel.
  IF dist IS NULL OR dist = 'NaN'::double precision
     OR dist = 'Infinity'::double precision THEN
    RETURN 1e9;
  END IF;

  RETURN dist;
END;
$function$;
COMMENT ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) IS 'Compare two GeoJSON boundaries via ST_HausdorffDistance (geography, metres). Returns distance in metres; returns 1e9 sentinel on null/invalid input (never 0). Used by canonicalSiteEntry.ts for Q-A3 reconciliation (threshold 5m per Q7).';
REVOKE ALL ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."compare_boundaries_hausdorff"(p_geojson_a text, p_geojson_b text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text DEFAULT NULL::text)
 RETURNS TABLE(activity_id uuid, completed_at timestamp with time zone, completed_by uuid, completed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_activity public.crm_account_activities%rowtype;
  v_notes text := nullif(trim(coalesce(p_completion_notes, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select a.* into v_activity from public.crm_account_activities a where a.id = p_activity_id;
  if not found then
    raise exception 'Activity not found';
  end if;

  if not public.is_admin_for_org(v_activity.provider_organization_id) then
    raise exception 'Not authorised to modify activity for this account';
  end if;

  if v_activity.completed_at is not null then
    return query select v_activity.id, v_activity.completed_at, v_activity.completed_by, true;
    return;
  end if;

  update public.crm_account_activities
  set
    completed_at = now(),
    completed_by = v_actor,
    completion_notes = coalesce(v_notes, completion_notes)
  where id = v_activity.id
  returning * into v_activity;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_activity.provider_organization_id,
    v_actor,
    'crm_follow_up_completed',
    'crm_account_activities',
    v_activity.id,
    jsonb_build_object(
      'account_organization_id', v_activity.account_organization_id,
      'subject', v_activity.subject,
      'completion_notes', v_notes,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_activity.id, v_activity.completed_at, v_activity.completed_by, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_crm_follow_up"(p_client_request_id uuid, p_activity_id uuid, p_completion_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[] DEFAULT '{}'::text[])
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  IF nullif(trim(p_provider_connection_reference), '') IS NULL OR nullif(trim(p_adapter_name), '') IS NULL THEN RAISE EXCEPTION 'Provider connection reference and adapter are required'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  UPDATE public.finance_external_connection_requests
  SET status = 'connected', provider_connection_reference = trim(p_provider_connection_reference), adapter_name = trim(p_adapter_name), requested_scopes = COALESCE(p_granted_scopes, requested_scopes), connected_at = now(), disconnected_at = NULL, last_error = NULL, updated_at = now()
  WHERE id = p_request_id
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_request.organization_id, NULL, 'finance_external_connection_completed', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', v_request.adapter_name, 'credentials_stored_in_browser', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_finance_external_connection"(p_request_id uuid, p_provider_connection_reference text, p_adapter_name text, p_granted_scopes text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result_id uuid;
  face_event record;
  candidate_list jsonb;
  import_id uuid;
  ready_import_id uuid;
  v_person_id uuid;
  v_canonical_id uuid;
  v_portfolio_key uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_job_id IS NULL OR p_evidence_id IS NULL OR p_org_id IS NULL OR p_motion_result IS NULL THEN
    RAISE EXCEPTION 'Job, evidence, organization, and motion result are required';
  END IF;
  IF jsonb_typeof(p_motion_result) <> 'object' OR jsonb_typeof(p_motion_result->'motion_segments') <> 'array' THEN
    RAISE EXCEPTION 'Motion result must contain a motion_segments array';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_org_id
      AND domain = 'video_motion'
      AND status = 'processing'
  ) THEN
    RAISE EXCEPTION 'Inference job is missing, mismatched, or not processing';
  END IF;
  SELECT evidence.cctv_import_id
    INTO import_id
    FROM public.evidence_items AS evidence
   WHERE evidence.id = p_evidence_id
     AND evidence.organization_id = p_org_id
     AND evidence.evidence_kind = 'video';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Video evidence is missing or belongs to another organization';
  END IF;

  INSERT INTO public.inference_results (inference_job_id, evidence_item_id, domain, status, result)
  VALUES (p_job_id, p_evidence_id, 'video_motion', 'complete', p_motion_result)
  RETURNING id INTO result_id;

  FOR face_event IN
    SELECT value AS event, ordinality AS event_number
    FROM jsonb_array_elements(COALESCE(p_motion_result #> '{consolidated_events,face_events}', '[]'::jsonb)) WITH ORDINALITY
  LOOP
    v_person_id := NULL;
    v_canonical_id := NULL;
    v_portfolio_key := NULL;
    SELECT observation.person_record_id, observation.canonical_person_id, observation.portfolio_key
      INTO v_person_id, v_canonical_id, v_portfolio_key
      FROM public.cctv_entity_observations AS observation
     WHERE observation.inference_job_id = p_job_id
       AND observation.organization_id = p_org_id
       AND observation.entity_kind = 'person'
       AND (
         observation.source_event_id = face_event.event->>'event_id'
         OR observation.attributes->>'face_event_id' = face_event.event->>'event_id'
       )
     ORDER BY (observation.source_event_id = face_event.event->>'event_id') DESC,
              observation.observed_at
     LIMIT 1;

    IF v_person_id IS NULL THEN
      v_portfolio_key := COALESCE(v_portfolio_key, gen_random_uuid());
      SELECT profile.person_record_id, profile.canonical_person_id
        INTO v_person_id, v_canonical_id
        FROM public.ensure_cctv_person_profile(
          p_org_id,
          v_portfolio_key,
          NULL,
          p_evidence_id,
          NULLIF(face_event.event->>'first_seen_at', '')::timestamptz
        ) AS profile;
    ELSIF v_canonical_id IS NULL THEN
      v_canonical_id := public.ensure_canonical_person_for_record(v_person_id);
    END IF;

    SELECT COALESCE(jsonb_agg(candidate ORDER BY similarity DESC), '[]'::jsonb)
      INTO candidate_list
      FROM (
        SELECT jsonb_build_object(
          'person_record_id', person.id,
          'display_name', COALESCE(person.display_name, 'Unnamed person'),
          'similarity', round(public.face_embedding_cosine(
            face_event.event->'face_embedding', person.metadata #> '{face_reference,embedding}'
          )::numeric, 4),
          'reference_thumbnail', person.metadata #>> '{face_reference,thumbnail}',
          'review_state', person.review_state
        ) AS candidate,
        public.face_embedding_cosine(face_event.event->'face_embedding', person.metadata #> '{face_reference,embedding}') AS similarity
        FROM public.person_records AS person
        WHERE person.organization_id = p_org_id
          AND jsonb_typeof(face_event.event->'face_embedding') = 'array'
          AND jsonb_typeof(person.metadata #> '{face_reference,embedding}') = 'array'
        ORDER BY similarity DESC
        LIMIT 5
      ) AS ranked;

    IF NOT EXISTS (
      SELECT 1
      FROM public.face_observations AS face_observation
      WHERE face_observation.evidence_item_id = p_evidence_id
        AND face_observation.metadata->>'source_event_id' = face_event.event->>'event_id'
    ) THEN
      INSERT INTO public.face_observations (
        organization_id,
        evidence_item_id,
        person_record_id,
        confidence,
        purpose,
        review_state,
        metadata
      )
      VALUES (
        p_org_id,
        p_evidence_id,
        v_person_id,
        NULL,
        'cctv_video_motion_candidate',
        'manual_review_required',
        jsonb_strip_nulls(jsonb_build_object(
          'source_event_id', face_event.event->>'event_id',
          'source_subject_id', face_event.event->>'subject_id',
          'original_thumbnail', face_event.event->>'thumbnail',
          'original_frame_hash', face_event.event->>'best_frame_hash',
          'embedding', face_event.event->'face_embedding',
          'canonical_person_id', v_canonical_id,
          'candidates', candidate_list
        ))
      );
    END IF;
  END LOOP;

  UPDATE public.inference_jobs
     SET status = 'complete',
         completed_at = clock_timestamp()
   WHERE id = p_job_id
     AND status = 'processing';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inference job changed before completion';
  END IF;

  IF import_id IS NOT NULL THEN
    PERFORM 1
      FROM public.cctv_imports
     WHERE id = import_id
     FOR UPDATE;
    UPDATE public.cctv_imports AS import_row
       SET status = 'review_ready',
           updated_at = clock_timestamp()
     WHERE import_row.id = import_id
       AND import_row.status IN ('registered', 'processing')
       AND EXISTS (
         SELECT 1
         FROM public.evidence_items AS import_evidence
         JOIN public.inference_jobs AS import_job
           ON import_job.evidence_item_id = import_evidence.id
        WHERE import_evidence.cctv_import_id = import_row.id
          AND import_job.domain = 'video_motion'
       )
       AND NOT EXISTS (
         SELECT 1
         FROM public.evidence_items AS import_evidence
         JOIN public.inference_jobs AS import_job
           ON import_job.evidence_item_id = import_evidence.id
        WHERE import_evidence.cctv_import_id = import_row.id
          AND import_job.domain = 'video_motion'
          AND import_job.status NOT IN ('complete', 'inconclusive', 'manual_review_required')
       )
    RETURNING import_row.id INTO ready_import_id;
    IF ready_import_id IS NOT NULL THEN
      INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
      VALUES (
        p_org_id,
        NULL,
        'cctv_import_review_ready',
        'cctv_imports',
        ready_import_id,
        jsonb_build_object('trigger_job_id', p_job_id, 'completed_video_jobs', (
          SELECT count(*)
          FROM public.evidence_items AS import_evidence
          JOIN public.inference_jobs AS import_job
            ON import_job.evidence_item_id = import_evidence.id
          WHERE import_evidence.cctv_import_id = ready_import_id
            AND import_job.domain = 'video_motion'
            AND import_job.status IN ('complete', 'inconclusive', 'manual_review_required')
        ))
      );
    END IF;
  END IF;

  RETURN result_id;
END;
$function$;
COMMENT ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) IS 'Stores a completed video-motion result, attaches face evidence to its inferred person profile, and advances the parent CCTV import to review_ready only when every video job is reviewable.';
REVOKE ALL ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_motion_inference"(p_job_id uuid, p_evidence_id uuid, p_org_id uuid, p_motion_result jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text)
 RETURNS TABLE(shift_id uuid, shift_status text, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_shift public.shifts%rowtype;v_completed_at timestamptz:=clock_timestamp();
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select s.* into v_shift from public.shifts s where s.id=p_shift_id for update;
  if not found then raise exception 'Shift not found';end if;
  if v_shift.officer_user_id<>v_actor then raise exception 'Shift does not belong to the authenticated officer';end if;
  if v_shift.status<>p_expected_status then raise exception 'Shift changed from expected status % to %',p_expected_status,v_shift.status;end if;
  if v_shift.status<>'in_progress' then raise exception 'Only an in-progress shift can be completed';end if;
  if not exists(select 1 from public.shift_debriefs d where d.shift_id=v_shift.id and d.officer_user_id=v_actor) then raise exception 'Submit the shift debrief before completing the shift';end if;
  if exists(select 1 from public.shift_stops st where st.shift_id=v_shift.id and st.status not in('completed','skipped','cancelled')) then raise exception 'Complete or skip every shift stop before completing the shift';end if;
  if exists(select 1 from public.shift_stop_modules sm join public.shift_stops st on st.id=sm.shift_stop_id where st.shift_id=v_shift.id and sm.is_required and sm.status not in('completed','skipped')) then raise exception 'Complete or skip every required module task before completing the shift';end if;
  if exists(select 1 from public.dispatch_jobs j where j.shift_id=v_shift.id and j.status not in('completed','cancelled')) then raise exception 'Complete or cancel every dispatch job before completing the shift';end if;
  if exists(select 1 from public.welfare_alerts w where w.shift_id=v_shift.id and w.status<>'resolved') then raise exception 'Resolve active welfare alerts before completing the shift';end if;
  update public.shifts set status='completed',actual_end=coalesce(actual_end,v_completed_at) where id=v_shift.id returning * into v_shift;
  update public.roster_slots set status='completed' where linked_shift_id=v_shift.id and status in('published','accepted');
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_shift.organization_id,v_actor,'officer_shift_completed','shifts',v_shift.id,jsonb_build_object('previous_status',p_expected_status,'actual_end',v_shift.actual_end));
  return query select v_shift.id,v_shift.status,v_shift.actual_end;
end;
$function$;
COMMENT ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text) IS 'Allows the owning officer to complete an in-progress shift only after debrief and all operational, module, dispatch, and welfare work is terminal.';
REVOKE ALL ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_officer_shift"(p_shift_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS patrols
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_patrol record;v_result public.patrols%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select p.*,s.patrol_route_id,s.zone_id as shift_zone_id into v_patrol from public.patrols p join public.shifts s on s.id=p.shift_id where p.id=p_patrol_id for update of p;
  if not found or v_profile.organization_id is distinct from v_patrol.organization_id or v_patrol.officer_user_id is distinct from v_actor then raise exception 'Active assigned Patrol session not found';end if;
  if v_patrol.status='completed' then select * into v_result from public.patrols where id=p_patrol_id;return v_result;end if;
  if v_patrol.status<>'in_progress' then raise exception 'Patrol session is not in progress';end if;
  if exists(select 1 from public.patrol_route_checkpoints c where c.patrol_route_id=v_patrol.patrol_route_id and c.is_active and c.is_mandatory and not exists(select 1 from public.patrol_checkpoint_visits v where v.patrol_id=v_patrol.id and v.route_checkpoint_id=c.id)) then raise exception 'One or more mandatory checkpoints remain';end if;
  if not exists(select 1 from public.patrol_route_checkpoints c where c.patrol_route_id=v_patrol.patrol_route_id and c.is_active and c.is_mandatory) and exists(select 1 from public.patrol_checkpoints c where c.active and((c.zone_id is not null and c.zone_id=v_patrol.shift_zone_id)or exists(select 1 from public.shift_stops st where st.shift_id=v_patrol.shift_id and((c.client_site_id is not null and st.site_id=c.client_site_id)or(c.zone_id is not null and st.zone_id=c.zone_id))))and not exists(select 1 from public.patrol_checkpoint_visits v where v.patrol_id=v_patrol.id and v.checkpoint_id=c.id)) then raise exception 'One or more mandatory checkpoints remain';end if;
  update public.patrols set status='completed',ended_at=clock_timestamp(),notes=coalesce(nullif(trim(coalesce(p_notes,'')),''),notes) where id=v_patrol.id returning * into v_result;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_result.organization_id,v_actor,'patrol.completed','patrols',v_result.id,jsonb_build_object('shift_id',v_result.shift_id,'checkpoint_count',(select count(*) from public.patrol_checkpoint_visits where patrol_id=v_result.id)));
  return v_result;
end;$function$;
REVOKE ALL ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_patrol_session"(p_patrol_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text DEFAULT NULL::text)
 RETURNS performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_review public.performance_reviews%rowtype;
begin
  select * into v_review from public.performance_reviews where id=p_review_id for update;
  if not found then raise exception 'Performance review not found'; end if;
  if v_review.reviewer_user_id<>v_actor and not public.is_admin_for_org(v_review.organization_id) then raise exception 'Only the reviewer or HR administrator can complete this review'; end if;
  if v_review.status<>p_expected_status then raise exception 'Performance review changed from expected status % to %',p_expected_status,v_review.status; end if;
  if v_review.status not in ('pending','in_progress') then raise exception 'Review is not available for completion'; end if;
  if p_rating not between 1 and 5 then raise exception 'Rating must be from 1 to 5'; end if;
  update public.performance_reviews set status='completed',rating=p_rating,strengths=nullif(trim(coalesce(p_strengths,'')),''),development_goals=nullif(trim(coalesce(p_development_goals,'')),''),employee_comments=nullif(trim(coalesce(p_employee_comments,'')),''),completed_at=now() where id=v_review.id returning * into v_review;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_review.organization_id,v_actor,'performance_review_completed','performance_reviews',v_review.id,jsonb_build_object('rating',p_rating));
  return v_review;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."complete_performance_review"(p_review_id uuid, p_expected_status text, p_rating smallint, p_strengths text, p_development_goals text, p_employee_comments text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text DEFAULT NULL::text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_stop record;
begin
  select * into v_stop from shift_stops where id = p_stop_id;
  if not found then
    raise exception 'Shift stop % not found', p_stop_id;
  end if;

  update shift_stops
  set status              = 'completed',
      sla_status          = case
                              when actual_arrived_at is null then 'completed'
                              when actual_arrived_at > sla_arrive_by then 'breached'
                              else 'completed'
                            end,
      actual_departed_at  = now(),
      officer_notes       = coalesce(p_officer_notes, officer_notes),
      updated_at          = now()
  where id = p_stop_id;

  -- Increment completed_stops on the shift.
  update shifts
  set completed_stops = completed_stops + 1
  where id = v_stop.shift_id;
end;
$function$;
COMMENT ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) IS 'Marks a shift stop as completed and updates shift progress counters.';
REVOKE ALL ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."complete_shift_stop"(p_stop_id uuid, p_officer_notes text, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  select round(
    (st_distance(
      st_setsrid(st_makepoint(lng1, lat1), 4326)::geography,
      st_setsrid(st_makepoint(lng2, lat2), 4326)::geography
    ) / 1000.0)::numeric,
    3
  );
$function$;
COMMENT ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) IS 'Returns the geodesic distance in km between two lat/lng points. Uses ST_Distance on geography (metres) / 1000. Called by the completion pipeline for travel distance computation.';
REVOKE ALL ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."compute_point_distance_km"(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_from_lat is null or p_from_lng is null or p_to_lat is null or p_to_lng is null then null
    else round((
      6371.0088 * 2 * asin(sqrt(
        power(sin(radians(p_to_lat - p_from_lat) / 2), 2)
        + cos(radians(p_from_lat)) * cos(radians(p_to_lat))
          * power(sin(radians(p_to_lng - p_from_lng) / 2), 2)
      ))
    )::numeric, 3)
  end;
$function$;
REVOKE ALL ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."compute_travel_distance_km"(p_from_lat double precision, p_from_lng double precision, p_to_lat double precision, p_to_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamp with time zone := now();
  v_ok boolean := false;
begin
  if p_nonce is null or length(trim(p_nonce)) < 16 then
    return false;
  end if;

  if p_expires_at is null or p_expires_at <= v_now or p_expires_at > (v_now + interval '10 minutes') then
    return false;
  end if;

  delete from public.bob_signing_nonces where expires_at < v_now;

  insert into public.bob_signing_nonces (nonce, expires_at)
  values (p_nonce, p_expires_at)
  on conflict (nonce) do nothing;

  get diagnostics v_ok = row_count;
  return coalesce(v_ok, false);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."consume_bob_signing_nonce"(p_nonce text, p_expires_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  IF p_jti IS NULL OR p_job_id IS NULL OR p_org_id IS NULL THEN
    RAISE EXCEPTION 'Token, job, and organization identifiers are required';
  END IF;

  INSERT INTO public.consumed_job_tokens (
    jti,
    inference_job_id,
    organization_id
  )
  VALUES (
    p_jti,
    p_job_id,
    p_org_id
  )
  ON CONFLICT (jti) DO NOTHING;

  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."consume_workload_token"(p_jti uuid, p_job_id uuid, p_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE
    WHEN p_start IS NULL OR p_end IS NULL OR p_start = p_end THEN true
    WHEN p_start < p_end THEN (p_at AT TIME ZONE 'Pacific/Auckland')::time >= p_start AND (p_at AT TIME ZONE 'Pacific/Auckland')::time < p_end
    ELSE (p_at AT TIME ZONE 'Pacific/Auckland')::time >= p_start OR (p_at AT TIME ZONE 'Pacific/Auckland')::time < p_end
  END;
$function$;
REVOKE ALL ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."continuity_party_on_duty"(p_start time without time zone, p_end time without time zone, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text)
 RETURNS TABLE(candidate_id uuid, onboarding_ledger_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_candidate public.recruitment_candidates%rowtype; v_staff public.staff_profiles%rowtype; v_ledger public.staff_onboarding_ledgers%rowtype; v_note text := nullif(trim(coalesce(p_note,'')), '');
begin
  select * into v_candidate from public.recruitment_candidates where id=p_candidate_id for update;
  if not found or not public.is_admin_for_org(v_candidate.organization_id) then raise exception 'Candidate not found in your organization'; end if;
  if v_candidate.stage<>'offer' or v_candidate.status<>'offered' then raise exception 'Only an offered candidate can be converted'; end if;
  if v_note is null then raise exception 'A conversion note is required'; end if;
  select * into v_staff from public.staff_profiles where id=p_staff_id and user_id=p_user_id and organization_id=v_candidate.organization_id;
  if not found then raise exception 'Provisioned user and staff records must belong to the recruiting organization'; end if;
  update public.recruitment_candidates set stage='hired',status='hired',offer_accepted_at=now(),provisioned_user_id=p_user_id,provisioned_staff_id=p_staff_id where id=v_candidate.id returning * into v_candidate;
  select * into v_ledger from public.staff_onboarding_ledgers where staff_id=v_staff.id;
  if not found then
    insert into public.staff_onboarding_ledgers(organization_id,staff_id,stage_note,target_start) values(v_candidate.organization_id,v_staff.id,v_note,v_candidate.offer_start_date) returning * into v_ledger;
    insert into public.staff_onboarding_events(ledger_id,organization_id,to_stage,to_status,note,actor_user_id,version) values(v_ledger.id,v_ledger.organization_id,'identity','in_progress',v_note,v_actor,v_ledger.version);
  end if;
  insert into public.recruitment_candidate_events(candidate_id,organization_id,from_stage,to_stage,note,actor_user_id) values(v_candidate.id,v_candidate.organization_id,'offer','hired',v_note,v_actor);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_candidate.organization_id,v_actor,'recruitment_candidate_converted','recruitment_candidates',v_candidate.id,jsonb_build_object('user_id',p_user_id,'staff_id',p_staff_id,'onboarding_ledger_id',v_ledger.id));
  return query select v_candidate.id,v_ledger.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."convert_recruitment_candidate_to_staff"(p_candidate_id uuid, p_user_id uuid, p_staff_id uuid, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text)
 RETURNS timesheets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_sheet public.timesheets%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_previous_actual numeric;
begin
  if v_reason is null then raise exception 'A correction reason is required'; end if;
  if p_actual_hours is null or p_actual_hours < 0 or p_actual_hours > 744 then raise exception 'Actual hours are outside the accepted range'; end if;
  if p_overtime_hours is null or p_overtime_hours < 0 or p_overtime_hours > p_actual_hours then raise exception 'Overtime hours are outside the accepted range'; end if;
  select t.* into v_sheet from public.timesheets t where t.id = p_timesheet_id for update;
  if not found then raise exception 'Timesheet not found'; end if;
  if not public.is_admin_for_org(v_sheet.organization_id) then raise exception 'Not authorised to correct this timesheet'; end if;
  if v_sheet.status <> p_expected_status or v_sheet.status not in ('submitted', 'branch_checked') then raise exception 'Only submitted or branch-checked timesheets can be corrected'; end if;
  v_previous_actual := v_sheet.actual_hours;

  update public.timesheets set actual_hours = p_actual_hours, overtime_hours = p_overtime_hours, adjustment_hours = p_actual_hours - coalesce(work_derived_hours, 0), review_notes = v_reason, status = 'submitted', branch_reviewed_by = null, branch_reviewed_at = null, branch_review_notes = null, branch_reviewed_organization_id = null where id = v_sheet.id returning * into v_sheet;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_sheet.organization_id, v_actor, 'timesheet_hours_corrected', 'timesheets', v_sheet.id, jsonb_build_object('previous_status', p_expected_status, 'previous_actual_hours', v_previous_actual, 'actual_hours', p_actual_hours, 'overtime_hours', p_overtime_hours, 'reason', v_reason));
  return v_sheet;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."correct_timesheet_hours"(p_timesheet_id uuid, p_expected_status text, p_actual_hours numeric, p_overtime_hours numeric, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb DEFAULT '[]'::jsonb, p_reference_metadata jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_document_id uuid;
  v_version_id uuid;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_type text := nullif(trim(coalesce(p_document_type, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_title IS NULL THEN RAISE EXCEPTION 'Document title is required'; END IF;
  IF nullif(trim(coalesce(p_authored_text, '')), '') IS NULL THEN RAISE EXCEPTION 'Document content is required'; END IF;
  IF jsonb_typeof(coalesce(p_reference_handles, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'Reference handles must be an array'; END IF;
  IF jsonb_typeof(coalesce(p_reference_metadata, '[]'::jsonb)) <> 'array' THEN RAISE EXCEPTION 'Reference metadata must be an array'; END IF;

  SELECT organization_id INTO v_org_id
  FROM public.user_profiles
  WHERE id = v_actor;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Organization context is required'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN
    RAISE EXCEPTION 'Document drafting requires an administrator';
  END IF;

  INSERT INTO public.documents (
    original_filename, mime_type, source_channel, organization_id, current_scope, uploaded_by
  ) VALUES (
    left(v_title || '.html', 255), 'text/html', 'system_generated', v_org_id, 'conversation_only', v_actor
  ) RETURNING id INTO v_document_id;

  INSERT INTO public.document_versions (
    document_id, version_label, extracted_text, metadata_json
  ) VALUES (
    v_document_id, 'v1', p_authored_text,
    jsonb_build_object(
      'authoring_html', coalesce(p_authored_html, ''),
      'content_format', 'html',
      'title', v_title,
      'document_type', v_type,
      'authoring_status', 'draft',
      'authored_by', v_actor,
      'reference_handles', coalesce(p_reference_handles, '[]'::jsonb),
      'references', coalesce(p_reference_metadata, '[]'::jsonb)
    )
  ) RETURNING id INTO v_version_id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_org_id, v_actor, 'bob_document_draft_created', 'documents', v_document_id,
    jsonb_build_object('document_version_id', v_version_id, 'document_type', v_type, 'title', v_title, 'reference_count', jsonb_array_length(coalesce(p_reference_handles, '[]'::jsonb)))
  );

  RETURN jsonb_build_object('ok', true, 'document_id', v_document_id, 'document_version_id', v_version_id, 'scope', 'conversation_only', 'status', 'draft');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_bob_document_draft"(p_title text, p_document_type text, p_authored_html text, p_authored_text text, p_reference_handles jsonb, p_reference_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text DEFAULT NULL::text, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_severity text DEFAULT 'standard'::text, p_observation_id uuid DEFAULT NULL::uuid, p_client_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_evidence public.evidence_items%rowtype;
  v_import public.cctv_imports%rowtype;
  v_incident uuid;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_severity text := lower(coalesce(nullif(trim(p_severity), ''), 'standard'));
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_title IS NULL THEN RAISE EXCEPTION 'A bookmark title is required'; END IF;
  IF p_at IS NULL THEN RAISE EXCEPTION 'A bookmark instant is required'; END IF;
  IF p_until IS NOT NULL AND p_until < p_at THEN RAISE EXCEPTION 'Bookmark end must not precede its start'; END IF;
  IF v_severity NOT IN ('low', 'standard', 'high', 'critical') THEN RAISE EXCEPTION 'Unknown bookmark severity %', p_severity; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.org_access_allowed(v_evidence.organization_id) THEN RAISE EXCEPTION 'CCTV bookmark access denied'; END IF;
  IF v_evidence.cctv_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_evidence.cctv_import_id;
  END IF;
  IF p_observation_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.cctv_entity_observations o WHERE o.id = p_observation_id AND o.evidence_item_id = v_evidence.id
  ) THEN RAISE EXCEPTION 'Observation does not belong to this recording'; END IF;
  -- incidents_place_anchor_present_chk: an incident is anchored to a place or it is not an incident.
  IF v_import.location_id IS NULL AND v_import.site_id IS NULL AND v_import.zone_id IS NULL THEN
    RAISE EXCEPTION 'This recording is not anchored to a place; import it against a location before bookmarking';
  END IF;

  -- Idempotent on the caller's request id so a retried click cannot double-book.
  IF p_client_request_id IS NOT NULL THEN
    SELECT (a.metadata->>'incident_id')::uuid INTO v_incident
      FROM public.audit_log a
     WHERE a.action = 'cctv_bookmark_created' AND a.metadata->>'client_request_id' = p_client_request_id::text
     LIMIT 1;
    IF v_incident IS NOT NULL THEN
      RETURN jsonb_build_object('incident_id', v_incident, 'deduped', true);
    END IF;
  END IF;

  INSERT INTO public.incidents (organization_id, officer_user_id, location_id, client_site_id, zone_id, canonical_place_id,
                                incident_type, severity, description, status, occurred_at)
  VALUES (v_evidence.organization_id, v_actor, v_import.location_id, v_import.site_id, v_import.zone_id, v_import.canonical_place_id,
          'cctv_bookmark', v_severity,
          v_title || CASE WHEN nullif(trim(coalesce(p_notes, '')), '') IS NULL THEN '' ELSE E'\n\n' || trim(p_notes) END,
          'open', p_at)
  RETURNING id INTO v_incident;

  -- incident_attachments_attachment_kind_check allows photo|video|audio|document|note.
  INSERT INTO public.incident_attachments (organization_id, incident_id, evidence_item_id, attachment_kind)
  VALUES (v_evidence.organization_id, v_incident, v_evidence.id, 'video');

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, v_actor, 'cctv_bookmark_created', 'incidents', v_incident,
          jsonb_strip_nulls(jsonb_build_object(
            'incident_id', v_incident, 'evidence_item_id', v_evidence.id, 'cctv_import_id', v_evidence.cctv_import_id,
            'camera_label', v_import.camera_label, 'bookmark_at', p_at, 'bookmark_until', p_until, 'severity', v_severity,
            'observation_id', p_observation_id, 'client_request_id', p_client_request_id)));

  RETURN jsonb_build_object('incident_id', v_incident, 'deduped', false);
END $function$;
COMMENT ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) IS 'Reviewer bookmark on a CCTV recording: an incidents row (incident_type cctv_bookmark) anchored to the import place, with the recording attached. Idempotent on p_client_request_id. Audited.';
REVOKE ALL ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_bookmark"(p_evidence_id uuid, p_at timestamp with time zone, p_title text, p_notes text, p_until timestamp with time zone, p_severity text, p_observation_id uuid, p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
  manifest_hash text;
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV export access denied';
  END IF;
  IF p_purpose IS NULL OR char_length(trim(p_purpose)) < 3 OR p_recipient_scope IS NULL OR char_length(trim(p_recipient_scope)) < 3 THEN
    RAISE EXCEPTION 'Export purpose and recipient scope are required';
  END IF;
  IF jsonb_typeof(p_selected_event_ids) <> 'array' OR jsonb_typeof(p_manifest) <> 'object' THEN
    RAISE EXCEPTION 'Export event selection and manifest shapes are invalid';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'CCTV evidence is missing or outside the organization';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(p_selected_event_ids) selected_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.cctv_review_events event
      WHERE event.id = selected_id::uuid
        AND event.organization_id = p_organization_id
        AND event.inference_job_id = p_job_id
        AND event.evidence_item_id = p_evidence_id
        AND event.review_state = 'accepted'
    )
  ) THEN
    RAISE EXCEPTION 'Only accepted CCTV review events may be exported';
  END IF;

  manifest_hash := encode(digest(convert_to(p_manifest::text, 'UTF8'), 'sha256'), 'hex');
  INSERT INTO public.cctv_exports (
    organization_id, inference_job_id, evidence_item_id, purpose, recipient_scope,
    legal_hold, selected_event_ids, manifest, manifest_sha256, generated_by
  ) VALUES (
    p_organization_id, p_job_id, p_evidence_id, trim(p_purpose), trim(p_recipient_scope),
    coalesce(p_legal_hold, false), p_selected_event_ids, p_manifest, manifest_hash, actor_id
  ) RETURNING * INTO export_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, actor_id, 'cctv_export_draft_created', 'cctv_exports', export_row.id,
    jsonb_build_object('purpose', p_purpose, 'recipient_scope', p_recipient_scope, 'legal_hold', p_legal_hold, 'manifest_sha256', manifest_hash));

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_export_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_purpose text, p_recipient_scope text, p_legal_hold boolean, p_selected_event_ids jsonb, p_manifest jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_source_device_kind text DEFAULT 'unknown'::text, p_source_timezone text DEFAULT 'Pacific/Auckland'::text, p_source_root_label text DEFAULT NULL::text, p_watermark_location_hint text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS cctv_imports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_house_org uuid; v_row public.cctv_imports%rowtype; v_tz_probe timestamp;
BEGIN
  IF v_actor IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  SELECT organization_id INTO v_house_org FROM public.locations WHERE id = p_location_id;
  IF v_house_org IS NULL THEN RAISE EXCEPTION 'Choose the location before importing camera files'; END IF;
  IF NOT public.org_access_allowed(v_house_org) THEN RAISE EXCEPTION 'No access to the chosen location'; END IF;
  BEGIN
    v_tz_probe := now() AT TIME ZONE coalesce(p_source_timezone, 'Pacific/Auckland');
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Unknown time zone %', p_source_timezone;
  END;
  INSERT INTO public.cctv_imports (organization_id, location_id, canonical_place_id, site_id, zone_id, camera_label, camera_key,
                                   source_device_kind, source_timezone, source_root_label, watermark_location_hint, notes, created_by)
  SELECT p_organization_id, p_location_id, l.canonical_place_id, p_site_id, p_zone_id, p_camera_label, 'pending',
         coalesce(nullif(p_source_device_kind, ''), 'unknown'), coalesce(nullif(p_source_timezone, ''), 'Pacific/Auckland'),
         nullif(trim(p_source_root_label), ''), nullif(trim(p_watermark_location_hint), ''), nullif(trim(p_notes), ''),
         (SELECT up.id FROM public.user_profiles up WHERE up.id = v_actor)
  FROM public.locations l WHERE l.id = p_location_id
  RETURNING * INTO v_row;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'cctv_import_created', 'cctv_imports', v_row.id,
          jsonb_build_object('location_id', p_location_id, 'canonical_place_id', v_row.canonical_place_id, 'camera_key', v_row.camera_key, 'device', v_row.source_device_kind));
  RETURN v_row;
END $function$;
REVOKE ALL ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cctv_import"(p_organization_id uuid, p_location_id uuid, p_camera_label text, p_site_id uuid, p_zone_id uuid, p_source_device_kind text, p_source_timezone text, p_source_root_label text, p_watermark_location_hint text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_cost_centre"(p_code text, p_name text)
 RETURNS cost_centres
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_row public.cost_centres%rowtype;
begin select up.organization_id into v_org from public.user_profiles up where up.id=v_actor and up.deactivated_at is null;if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Active roster administrator required';end if;if nullif(trim(coalesce(p_code,'')),'') is null or nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Cost centre code and name are required';end if;insert into public.cost_centres(organization_id,code,name,created_by)values(v_org,upper(trim(p_code)),trim(p_name),v_actor)returning * into v_row;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_org,v_actor,'cost_centre_created','cost_centres',v_row.id,jsonb_build_object('code',v_row.code,'name',v_row.name));return v_row;end;$function$;
REVOKE ALL ON FUNCTION "public"."create_cost_centre"(p_code text, p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_cost_centre"(p_code text, p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_cost_centre"(p_code text, p_name text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_cost_centre"(p_code text, p_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS crm_account_activities
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_activity public.crm_account_activities%rowtype;v_subject text:=nullif(trim(coalesce(p_subject,'')),'');
begin
  if v_actor is null or not public.crm_actor_can_manage_account(p_account_organization_id) then raise exception 'Not authorised to manage this CRM account';end if;
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if p_client_request_id is null then raise exception 'client_request_id is required';end if;if p_activity_type not in('call','email','meeting','note','task') then raise exception 'Unsupported CRM activity type';end if;if v_subject is null then raise exception 'Activity subject is required';end if;
  if p_occurred_at is null or p_occurred_at>now()+interval '5 minutes' or p_occurred_at<now()-interval '90 days' then raise exception 'Activity time is outside the accepted window';end if;
  if p_follow_up_at is not null and p_follow_up_at<p_occurred_at then raise exception 'Follow-up cannot be before the activity';end if;
  if p_service_agreement_id is not null and not exists(select 1 from public.service_agreements a where a.id=p_service_agreement_id and a.provider_organization_id=v_provider and a.client_organization_id=p_account_organization_id) then raise exception 'Agreement does not belong to this CRM account';end if;
  select a.* into v_activity from public.crm_account_activities a where a.provider_organization_id=v_provider and a.client_request_id=p_client_request_id;if found then return v_activity;end if;
  insert into public.crm_account_activities(provider_organization_id,account_organization_id,service_agreement_id,client_request_id,activity_type,subject,details,outcome,occurred_at,follow_up_at,created_by) values(v_provider,p_account_organization_id,p_service_agreement_id,p_client_request_id,p_activity_type,v_subject,nullif(trim(coalesce(p_details,'')),''),nullif(trim(coalesce(p_outcome,'')),''),p_occurred_at,p_follow_up_at,v_actor) returning * into v_activity;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_provider,v_actor,'crm_account_activity_created','crm_account_activities',v_activity.id,jsonb_build_object('account_organization_id',p_account_organization_id,'activity_type',p_activity_type,'follow_up_at',p_follow_up_at));
  return v_activity;
end;$function$;
REVOKE ALL ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_account_activity"(p_client_request_id uuid, p_account_organization_id uuid, p_service_agreement_id uuid, p_activity_type text, p_subject text, p_details text, p_outcome text, p_occurred_at timestamp with time zone, p_follow_up_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_draft_quote"(p_client_request_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric DEFAULT 0, p_valid_until date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_client public.organizations%rowtype;
  v_quote public.quotes%rowtype;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
begin
  select profile.organization_id into v_provider from public.user_profiles profile where profile.id = v_actor and profile.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if v_title is null then raise exception 'Quote title is required'; end if;
  if p_target_margin_pct < 0 or p_target_margin_pct >= 100 then raise exception 'Target margin must be between zero and 100'; end if;
  if p_valid_until is not null and p_valid_until < current_date then raise exception 'Quote validity date cannot be in the past'; end if;

  select * into v_client from public.organizations where id = p_client_org_id;
  if not found or not v_client.active or v_client.status <> 'active' then raise exception 'An active organization is required for a service proposal'; end if;
  if v_client.id = v_provider then raise exception 'A provider cannot create a service proposal for itself'; end if;

  select * into v_quote from public.quotes quote where quote.provider_org_id = v_provider and quote.client_request_id = p_client_request_id;
  if found then return v_quote; end if;

  insert into public.quotes(provider_org_id,client_org_id,title,status,currency,target_margin_pct,valid_until,notes,client_request_id,created_by,updated_by)
  values(v_provider,v_client.id,v_title,'draft','NZD',p_target_margin_pct,p_valid_until,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,v_actor,v_actor)
  returning * into v_quote;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_provider,v_actor,'crm_draft_quote_created','quotes',v_quote.id,jsonb_build_object('client_org_id',v_client.id,'title',v_title,'target_margin_pct',p_target_margin_pct,'valid_until',p_valid_until,'relationship_state','proposal_only'));
  return v_quote;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_crm_draft_quote"(p_client_request_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote"(p_client_request_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote"(p_client_request_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote"(p_client_request_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric DEFAULT 0, p_valid_until date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_service_agreement_id uuid DEFAULT NULL::uuid)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider public.organizations%rowtype;
  v_client public.organizations%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_quote public.quotes%rowtype;
  v_title text := nullif(trim(coalesce(p_title, '')), '');
  v_provider_tree uuid[];
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_provider from public.organizations where id = p_operating_provider_organization_id;
  if not found or not public.is_admin_for_org(v_provider.id) then raise exception 'Operating provider organization is not available for management'; end if;
  if v_provider.organization_type not in ('owner', 'service_provider', 'branch') then raise exception 'Operating provider must be a service provider or internal branch'; end if;
  v_provider_tree := public.get_descendant_organizations(coalesce(v_provider.parent_organization_id, v_provider.id));
  select * into v_client from public.organizations where id = p_client_org_id;
  if not found or not (
    (v_client.active and v_client.status = 'active')
    or (
      not v_client.active
      and v_client.status = 'prospect'
      and exists(
        select 1
        from public.crm_onboarding_ledgers ledger
        where ledger.provider_organization_id = any(v_provider_tree)
          and ledger.account_organization_id = v_client.id
          and ledger.status <> 'activated'
      )
    )
  ) then raise exception 'An active client organization is required for a service proposal'; end if;
  if v_client.id = v_provider.id then raise exception 'A provider cannot create a service proposal for itself'; end if;
  if v_title is null then raise exception 'Quote title is required'; end if;
  if p_target_margin_pct < 0 or p_target_margin_pct >= 100 then raise exception 'Target margin must be between zero and 100'; end if;
  if p_valid_until is not null and p_valid_until < current_date then raise exception 'Quote validity date cannot be in the past'; end if;

  if p_service_agreement_id is not null then
    select * into v_agreement from public.service_agreements where id = p_service_agreement_id;
    if not found then raise exception 'The agreement this variation changes could not be found'; end if;
    if v_agreement.client_organization_id <> v_client.id then raise exception 'A variation must change an agreement held by the same client'; end if;
    if v_agreement.agreement_type <> 'operational' then raise exception 'Only operational service agreements can be varied'; end if;
    if v_agreement.provider_organization_id <> v_provider.id and not (v_agreement.provider_organization_id = any(v_provider_tree)) then
      raise exception 'A variation must change an agreement delivered by this provider or its branches';
    end if;
    if v_agreement.ends_on is not null and v_agreement.ends_on < current_date then
      raise exception 'This agreement has ended. Raise a new agreement instead of a variation';
    end if;
  end if;

  select * into v_quote from public.quotes quote where quote.provider_org_id = v_provider.id and quote.client_request_id = p_client_request_id;
  if found then return v_quote; end if;

  insert into public.quotes(provider_org_id,client_org_id,title,status,currency,target_margin_pct,valid_until,notes,client_request_id,service_agreement_id,created_by,updated_by)
  values(v_provider.id,v_client.id,v_title,'draft','NZD',p_target_margin_pct,p_valid_until,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,p_service_agreement_id,v_actor,v_actor)
  returning * into v_quote;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_provider.id,v_actor,'crm_draft_quote_created_for_operating_provider','quotes',v_quote.id,jsonb_build_object(
    'operating_provider_organization_id',v_provider.id,
    'client_org_id',v_client.id,
    'title',v_title,
    'relationship_state',case when p_service_agreement_id is null then 'proposal_only' else 'variation_of_agreement' end,
    'service_agreement_id',p_service_agreement_id,
    'service_agreement_name',v_agreement.name));
  return v_quote;
end;
$function$;
COMMENT ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) IS 'Create an idempotent draft quote for a client on behalf of an operating provider/branch. When p_service_agreement_id is given the quote is a VARIATION of that existing operational agreement (same client, provider tree, not ended): on acceptance its places, delivery schedules, and prices are appended to that agreement instead of creating a new one.';
REVOKE ALL ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_crm_draft_quote_for_provider"(p_client_request_id uuid, p_operating_provider_organization_id uuid, p_client_org_id uuid, p_title text, p_target_margin_pct numeric, p_valid_until date, p_notes text, p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text DEFAULT 'commercial_premises'::text, p_center_lat double precision DEFAULT NULL::double precision, p_center_lng double precision DEFAULT NULL::double precision, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, name text, address text, site_type text, active boolean, boundary_status text, boundary_verification text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_provider uuid; v_site public.client_sites%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), ''); v_address text := nullif(trim(coalesce(p_address, '')), ''); v_address_key text;
BEGIN
  SELECT up.organization_id INTO v_provider FROM public.user_profiles AS up WHERE up.id=v_actor AND up.deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(p_account_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  PERFORM 1 FROM public.organizations AS org WHERE org.id=p_account_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CRM account organization not found'; END IF;
  IF p_location_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.locations AS house WHERE house.id=p_location_id AND house.organization_id=p_account_organization_id) THEN RAISE EXCEPTION 'Location house does not belong to the account'; END IF;
  SELECT site.* INTO v_site FROM public.client_sites AS site WHERE site.client_organization_id=p_account_organization_id AND site.client_request_id=p_client_request_id;
  IF FOUND THEN id:=v_site.id; name:=v_site.name; address:=v_site.address; site_type:=v_site.site_type; active:=v_site.active; boundary_status:=v_site.boundary_status; boundary_verification:=v_site.boundary_verification; created:=false; RETURN NEXT; RETURN; END IF;
  IF v_name IS NULL OR char_length(v_name)>200 THEN RAISE EXCEPTION 'Site name is required and must be 200 characters or fewer'; END IF;
  IF v_address IS NULL OR char_length(v_address)<4 OR char_length(v_address)>500 THEN RAISE EXCEPTION 'A complete site address is required'; END IF;
  IF p_center_lat IS NULL OR p_center_lng IS NULL OR p_center_lat NOT BETWEEN -90 AND 90 OR p_center_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Resolve the address before creating the site'; END IF;
  IF p_site_type NOT IN ('freedom_camping_area','parking_area','commercial_premises','residential_complex','government_facility','hospital','education_facility','industrial_site','public_space','other') THEN RAISE EXCEPTION 'Unsupported site type'; END IF;
  v_address_key:=regexp_replace(lower(v_address),'[^a-z0-9]+','','g');
  IF EXISTS (SELECT 1 FROM public.client_sites AS duplicate_site WHERE duplicate_site.client_organization_id=p_account_organization_id AND duplicate_site.address_match_key=v_address_key) THEN RAISE EXCEPTION 'A site with this address already exists for the account'; END IF;
  INSERT INTO public.client_sites(client_organization_id,location_id,name,address,address_match_key,site_type,active,site_origin,boundary_status,boundary_verification,center_point,client_request_id)
  VALUES(p_account_organization_id,p_location_id,v_name,v_address,v_address_key,p_site_type,true,'contracted','provisional','unverified',ST_SetSRID(ST_MakePoint(p_center_lng,p_center_lat),4326),p_client_request_id) RETURNING * INTO v_site;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_provider,v_actor,'crm_site_created','client_sites',v_site.id,jsonb_build_object('account_organization_id',p_account_organization_id,'location_id',p_location_id,'address_match_key',v_address_key,'center_source','resolved_address'));
  id:=v_site.id; name:=v_site.name; address:=v_site.address; site_type:=v_site.site_type; active:=v_site.active; boundary_status:=v_site.boundary_status; boundary_verification:=v_site.boundary_verification; created:=true; RETURN NEXT;
END; $function$;
REVOKE ALL ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_crm_site"(p_client_request_id uuid, p_account_organization_id uuid, p_name text, p_address text, p_site_type text, p_center_lat double precision, p_center_lng double precision, p_location_id uuid) TO "authenticated";
