CREATE OR REPLACE FUNCTION "public"."create_default_welfare_settings"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.role in ('officer', 'admin_officer') and new.organization_id is not null then
    insert into officer_welfare_settings (organization_id, officer_user_id)
    values (new.organization_id, new.id)
    on conflict (officer_user_id, organization_id) do nothing;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_default_welfare_settings"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."create_default_welfare_settings"() TO "postgres";
