CREATE OR REPLACE FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_briefing_notes text DEFAULT NULL::text, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, client_site_id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_place record;
  v_job record;
  v_client_org_id uuid;
BEGIN
  IF NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Not authorised to create dispatch jobs for this organisation'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF nullif(trim(coalesce(p_location_name, '')), '') IS NULL OR nullif(trim(coalesce(p_location_address, '')), '') IS NULL THEN RAISE EXCEPTION 'Incident location name and address are required'; END IF;
  IF p_location_lat IS NULL OR p_location_lng IS NULL OR p_location_lat NOT BETWEEN -90 AND 90 OR p_location_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Resolve the incident address before dispatching'; END IF;

  SELECT agreement.client_organization_id INTO v_client_org_id FROM public.service_agreements AS agreement
  WHERE agreement.id = p_service_agreement_id AND agreement.provider_organization_id = p_organization_id;
  IF v_client_org_id IS NULL THEN RAISE EXCEPTION 'Service agreement is not available to this provider'; END IF;

  SELECT * INTO v_place FROM public.resolve_or_create_dispatch_place_site(
    p_organization_id, v_client_org_id, trim(p_location_name), trim(p_location_address), p_location_lat, p_location_lng, auth.uid());

  INSERT INTO public.service_agreement_locations (service_agreement_id, site_id, status, created_by)
  VALUES (p_service_agreement_id, v_place.site_id, 'active', auth.uid()) ON CONFLICT (service_agreement_id, site_id) DO NOTHING;

  SELECT * INTO v_job FROM public.create_dispatch_job(p_organization_id, p_service_agreement_id, v_place.site_id, p_client_request_id, p_job_type, p_priority, p_sla_minutes, p_dispatch_resource_id, p_briefing_notes, p_shift_id);
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, auth.uid(), 'dispatch_intake_location_created', 'client_sites', v_place.site_id,
    jsonb_build_object('service_agreement_id', p_service_agreement_id, 'dispatch_job_id', v_job.id, 'site_created', v_place.site_created,
      'location_id', v_place.location_id, 'house_action', v_place.house_action, 'boundary_status', 'provisional'));
  RETURN QUERY SELECT v_job.id, v_place.site_id, v_job.created, v_job.status, v_job.sla_respond_by;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_intake_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_location_name text, p_location_address text, p_location_lat double precision, p_location_lng double precision, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_briefing_notes text DEFAULT NULL::text, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing public.dispatch_jobs%rowtype;
  v_created public.dispatch_jobs%rowtype;
  v_resource public.dispatch_resources%rowtype;
  v_shift public.shifts%rowtype;
begin
  if not public.is_admin_for_org(p_organization_id) then
    raise exception 'Not authorised to create dispatch jobs for this organisation';
  end if;

  if p_sla_minutes is null or p_sla_minutes < 1 or p_sla_minutes > 1440 then
    raise exception 'SLA minutes must be between 1 and 1440';
  end if;

  if not exists (
    select 1
    from public.service_agreements sa
    join public.service_agreement_locations sal on sal.service_agreement_id = sa.id
    join public.client_sites cs on cs.id = sal.site_id
    where sa.id = p_service_agreement_id
      and sa.provider_organization_id = p_organization_id
      and sal.site_id = p_client_site_id
      and sal.status = 'active'
      and cs.active = true
  ) then
    raise exception 'Site is not active under this service agreement';
  end if;

  select * into v_existing
  from public.dispatch_jobs
  where organization_id = p_organization_id
    and client_request_id = p_client_request_id;

  if found then
    return query select v_existing.id, false, v_existing.status, v_existing.sla_respond_by;
    return;
  end if;

  if p_dispatch_resource_id is not null then
    if p_shift_id is null then
      raise exception 'A shift is required when dispatching to a resource';
    end if;

    select * into v_resource
    from public.dispatch_resources
    where dispatch_resources.id = p_dispatch_resource_id
      and dispatch_resources.organization_id = p_organization_id
    for update;

    if not found or v_resource.status <> 'available' or v_resource.assigned_officer_id is null then
      raise exception 'Dispatch resource is not available with an assigned officer';
    end if;

    select * into v_shift
    from public.shifts
    where shifts.id = p_shift_id
      and shifts.organization_id = p_organization_id
      and shifts.status in ('accepted', 'in_progress')
    for share;

    if not found or v_shift.officer_user_id <> v_resource.assigned_officer_id then
      raise exception 'Shift officer does not match the selected dispatch resource';
    end if;
  elsif p_shift_id is not null then
    if not exists (
      select 1 from public.shifts
      where shifts.id = p_shift_id
        and shifts.organization_id = p_organization_id
        and shifts.status in ('accepted', 'in_progress')
    ) then
      raise exception 'Shift is not active in this organisation';
    end if;
  end if;

  begin
    insert into public.dispatch_jobs (
      organization_id, service_agreement_id, client_site_id, client_request_id,
      dispatch_resource_id, job_type, priority, status, sla_minutes,
      sla_respond_by, briefing_notes, shift_id, dispatched_at
    ) values (
      p_organization_id, p_service_agreement_id, p_client_site_id, p_client_request_id,
      p_dispatch_resource_id, p_job_type, p_priority,
      case when p_dispatch_resource_id is null then 'pending' else 'dispatched' end,
      p_sla_minutes, now() + make_interval(mins => p_sla_minutes),
      nullif(trim(p_briefing_notes), ''), p_shift_id,
      case when p_dispatch_resource_id is null then null else now() end
    ) returning * into v_created;

    if p_dispatch_resource_id is not null then
      update public.dispatch_resources
      set status = 'busy'
      where dispatch_resources.id = p_dispatch_resource_id;
    end if;
  exception when unique_violation then
    select * into v_created
    from public.dispatch_jobs
    where organization_id = p_organization_id
      and client_request_id = p_client_request_id;
    return query select v_created.id, false, v_created.status, v_created.sla_respond_by;
    return;
  end;

  return query select v_created.id, true, v_created.status, v_created.sla_respond_by;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_dispatch_job"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_dispatch_resource_id uuid, p_briefing_notes text, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_client_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_checkpoint_id uuid DEFAULT NULL::uuid, p_module_key text DEFAULT NULL::text, p_service_agreement_id uuid DEFAULT NULL::uuid, p_provider_organization_id uuid DEFAULT NULL::uuid, p_client_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_rule_set_id uuid DEFAULT NULL::uuid, p_authority_snapshot jsonb DEFAULT '{}'::jsonb, p_source_refs jsonb DEFAULT '{}'::jsonb, p_captured_at timestamp with time zone DEFAULT now())
 RETURNS event_context_snapshots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.event_context_snapshots%rowtype;
  v_context_org uuid := coalesce(p_provider_organization_id, p_client_organization_id, p_jurisdiction_organization_id);
BEGIN
  IF nullif(trim(coalesce(p_source_table, '')), '') IS NULL OR p_source_event_id IS NULL THEN RAISE EXCEPTION 'source_table and source_event_id are required'; END IF;
  IF auth.uid() IS NULL OR v_context_org IS NULL OR NOT public.org_access_allowed(v_context_org) THEN RAISE EXCEPTION 'Event context organization access denied'; END IF;
  IF p_client_site_id IS NOT NULL AND p_zone_id IS NOT NULL THEN RAISE EXCEPTION 'Event context Site and Zone are mutually exclusive'; END IF;
  IF p_client_site_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.client_sites s WHERE s.id=p_client_site_id AND (p_location_id IS NULL OR s.location_id=p_location_id)) THEN RAISE EXCEPTION 'Event context Site does not match the House'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.location_zones z WHERE z.id=p_zone_id AND (p_location_id IS NULL OR z.location_id=p_location_id)) THEN RAISE EXCEPTION 'Event context Zone does not match the House'; END IF;
  IF p_service_agreement_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.service_agreements sa WHERE sa.id=p_service_agreement_id
      AND (p_provider_organization_id IS NULL OR sa.provider_organization_id=p_provider_organization_id)
      AND (p_client_organization_id IS NULL OR sa.client_organization_id=p_client_organization_id)
  ) THEN RAISE EXCEPTION 'Event context service agreement does not match its parties'; END IF;
  IF p_checkpoint_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.patrol_checkpoints cp
    WHERE cp.id=p_checkpoint_id
      AND cp.organization_id=v_context_org
      AND ((cp.client_site_id IS NOT NULL AND cp.client_site_id=p_client_site_id AND p_zone_id IS NULL)
        OR (cp.zone_id IS NOT NULL AND cp.zone_id=p_zone_id AND p_client_site_id IS NULL))
  ) THEN RAISE EXCEPTION 'Checkpoint does not match the event Site/Zone and organization'; END IF;

  INSERT INTO public.event_context_snapshots (
    source_table, source_event_id, location_id, client_site_id, zone_id, checkpoint_id,
    module_key, service_agreement_id, provider_organization_id, client_organization_id,
    jurisdiction_organization_id, jurisdiction_rule_set_id, authority_snapshot, source_refs, captured_at
  ) VALUES (
    trim(p_source_table), p_source_event_id, p_location_id, p_client_site_id, p_zone_id, p_checkpoint_id,
    p_module_key, p_service_agreement_id, p_provider_organization_id, p_client_organization_id,
    p_jurisdiction_organization_id, p_jurisdiction_rule_set_id, coalesce(p_authority_snapshot, '{}'::jsonb),
    coalesce(p_source_refs, '{}'::jsonb), coalesce(p_captured_at, now())
  ) ON CONFLICT (source_table, source_event_id) DO NOTHING RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    SELECT * INTO v_row FROM public.event_context_snapshots WHERE source_table=trim(p_source_table) AND source_event_id=p_source_event_id;
  END IF;
  RETURN v_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_event_context_snapshot"(p_source_table text, p_source_event_id uuid, p_location_id uuid, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb, p_captured_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb DEFAULT '{}'::jsonb, p_schema_json jsonb DEFAULT '{}'::jsonb, p_row_count integer DEFAULT 0, p_duplicate_count integer DEFAULT 0, p_unresolved_count integer DEFAULT 0, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS file_import_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid := p_organization_id;
  v_batch public.file_import_batches%rowtype;
  v_duplicate_of uuid;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Organisation is required'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Import batch creation denied'; END IF;
  IF nullif(trim(coalesce(p_batch_name, '')), '') IS NULL OR nullif(trim(coalesce(p_source_file, '')), '') IS NULL THEN RAISE EXCEPTION 'Batch name and source file are required'; END IF;
  IF p_row_count < 0 OR p_duplicate_count < 0 OR p_unresolved_count < 0 THEN RAISE EXCEPTION 'Import counts cannot be negative'; END IF;
  IF nullif(trim(coalesce(p_source_sha256, '')), '') IS NOT NULL THEN
    SELECT id INTO v_duplicate_of
    FROM public.file_import_batches
    WHERE organization_id = v_org_id AND source_sha256 = trim(p_source_sha256)
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;
  INSERT INTO public.file_import_batches (
    organization_id, batch_name, source_file, source_sha256, duplicate_of_batch_id, parser,
    manifest_json, schema_json, row_count, duplicate_count, unresolved_count, created_by
  ) VALUES (
    v_org_id, trim(p_batch_name), trim(p_source_file), nullif(trim(coalesce(p_source_sha256, '')), ''), v_duplicate_of, trim(p_parser),
    coalesce(p_manifest_json, '{}'::jsonb), coalesce(p_schema_json, '{}'::jsonb),
    p_row_count, p_duplicate_count, p_unresolved_count, v_actor
  ) RETURNING * INTO v_batch;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'file_import_batch_created', 'file_import_batches', v_batch.id,
    jsonb_build_object('source_file', v_batch.source_file, 'parser', v_batch.parser, 'row_count', v_batch.row_count, 'duplicate_count', v_batch.duplicate_count, 'unresolved_count', v_batch.unresolved_count, 'duplicate_of_batch_id', v_batch.duplicate_of_batch_id));
  RETURN v_batch;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_file_import_batch"(p_batch_name text, p_source_file text, p_source_sha256 text, p_parser text, p_manifest_json jsonb, p_schema_json jsonb, p_row_count integer, p_duplicate_count integer, p_unresolved_count integer, p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer)
 RETURNS finance_budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_budget public.finance_budgets%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF nullif(trim(p_name), '') IS NULL OR p_fiscal_year NOT BETWEEN 2000 AND 2200 THEN RAISE EXCEPTION 'Budget name and fiscal year are required'; END IF;
  INSERT INTO public.finance_budgets(organization_id, name, fiscal_year, created_by)
  VALUES (v_org, trim(p_name), p_fiscal_year, v_actor)
  RETURNING * INTO v_budget;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_budget_created', 'finance_budgets', v_budget.id, jsonb_build_object('fiscal_year', p_fiscal_year));
  RETURN v_budget;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_finance_budget"(p_name text, p_fiscal_year integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date)
 RETURNS finance_pl_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF nullif(trim(p_name), '') IS NULL OR p_period_start IS NULL OR p_period_end IS NULL OR p_period_end < p_period_start THEN RAISE EXCEPTION 'Valid period name and dates are required'; END IF;
  INSERT INTO public.finance_pl_periods(organization_id, name, period_start, period_end, status, created_by)
  VALUES(v_org, trim(p_name), p_period_start, p_period_end, 'draft', v_actor)
  ON CONFLICT (organization_id, period_start, period_end) DO UPDATE SET name = EXCLUDED.name, updated_at = now()
  RETURNING * INTO v_period;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_org, v_actor, 'finance_pl_period_created', 'finance_pl_periods', v_period.id, jsonb_build_object('name', v_period.name, 'period_start', v_period.period_start, 'period_end', v_period.period_end));
  RETURN v_period;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) TO "postgres";
