GRANT EXECUTE ON FUNCTION "public"."create_finance_pl_period"(p_name text, p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_finance_tax_period"(p_period_start date, p_period_end date, p_filing_due_date date)
 RETURNS finance_tax_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_tax_periods%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
