CREATE OR REPLACE FUNCTION "public"."create_investigation"(p_organization_id uuid, p_client_request_id uuid, p_reference text, p_title text, p_investigation_type text DEFAULT 'other'::text, p_priority text DEFAULT 'medium'::text, p_summary text DEFAULT NULL::text, p_lead_user_id uuid DEFAULT NULL::uuid)
 RETURNS investigations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_item public.investigations%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Active organization administrator required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF nullif(trim(p_reference),'') IS NULL OR nullif(trim(p_title),'') IS NULL THEN RAISE EXCEPTION 'Investigation reference and title are required'; END IF;
  SELECT * INTO v_item FROM public.investigations WHERE organization_id=p_organization_id AND investigation_reference=trim(p_reference) FOR UPDATE;
  IF FOUND THEN RETURN v_item; END IF;
  INSERT INTO public.investigations (organization_id, investigation_reference, title, investigation_type, priority, summary, lead_user_id, created_by)
  VALUES (p_organization_id, trim(p_reference), trim(p_title), p_investigation_type, p_priority, nullif(trim(p_summary),''), p_lead_user_id, v_actor)
  RETURNING * INTO v_item;
  INSERT INTO public.investigation_events (investigation_id, organization_id, event_type, description, created_by)
  VALUES (v_item.id, p_organization_id, 'investigation_opened', 'Investigation opened', v_actor);
  RETURN v_item;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_investigation"(p_organization_id uuid, p_client_request_id uuid, p_reference text, p_title text, p_investigation_type text, p_priority text, p_summary text, p_lead_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_investigation"(p_organization_id uuid, p_client_request_id uuid, p_reference text, p_title text, p_investigation_type text, p_priority text, p_summary text, p_lead_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_investigation"(p_organization_id uuid, p_client_request_id uuid, p_reference text, p_title text, p_investigation_type text, p_priority text, p_summary text, p_lead_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_investigation"(p_organization_id uuid, p_client_request_id uuid, p_reference text, p_title text, p_investigation_type text, p_priority text, p_summary text, p_lead_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_investigation_follow_up_job"(p_investigation_id uuid, p_client_request_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_dispatch_resource_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, created boolean, status text, sla_respond_by timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_item public.investigations%rowtype; v_job record;
BEGIN
  SELECT * INTO v_item FROM public.investigations WHERE public.investigations.id=p_investigation_id FOR SHARE;
  IF NOT FOUND OR v_actor IS NULL OR NOT public.is_admin_for_org(v_item.organization_id) THEN RAISE EXCEPTION 'Investigation access denied'; END IF;
  SELECT * INTO v_job FROM public.create_dispatch_job(v_item.organization_id, p_service_agreement_id, p_client_site_id, p_client_request_id, p_job_type, p_priority, p_sla_minutes, p_dispatch_resource_id, p_briefing_notes, p_shift_id);
  UPDATE public.dispatch_jobs SET investigation_id=p_investigation_id, origin_type='investigation_follow_up', origin_reference_id=p_investigation_id WHERE public.dispatch_jobs.id=v_job.id;
  PERFORM public.link_investigation_entity(p_investigation_id, 'dispatch_job', v_job.id, 'primary', 'Investigation-directed follow-up dispatch');
  RETURN QUERY SELECT v_job.id, v_job.created, v_job.status, v_job.sla_respond_by;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_investigation_follow_up_job"(p_investigation_id uuid, p_client_request_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_dispatch_resource_id uuid, p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_investigation_follow_up_job"(p_investigation_id uuid, p_client_request_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_dispatch_resource_id uuid, p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_investigation_follow_up_job"(p_investigation_id uuid, p_client_request_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_dispatch_resource_id uuid, p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_investigation_follow_up_job"(p_investigation_id uuid, p_client_request_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text, p_dispatch_resource_id uuid, p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_location_event"(p_organization_id uuid, p_event_type text, p_client_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_checkpoint_id uuid DEFAULT NULL::uuid, p_module_key text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_status text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_external_ref text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb, p_observed_entity_type text DEFAULT NULL::text, p_observed_entity_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_provider_organization_id uuid DEFAULT NULL::uuid, p_client_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_organization_id uuid DEFAULT NULL::uuid, p_jurisdiction_rule_set_id uuid DEFAULT NULL::uuid, p_authority_snapshot jsonb DEFAULT '{}'::jsonb, p_source_refs jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(event_id uuid, context_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_event public.location_events%rowtype;
  v_context public.event_context_snapshots%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Location event organization access denied';
  END IF;
  IF nullif(trim(coalesce(p_event_type, '')), '') IS NULL THEN
    RAISE EXCEPTION 'event_type is required';
  END IF;

  INSERT INTO public.location_events (
    organization_id, client_site_id, zone_id, checkpoint_id, event_type, module_key,
    occurred_at, status, source, external_ref, payload, observed_entity_type,
    observed_entity_id, created_by
  ) VALUES (
    p_organization_id, p_client_site_id, p_zone_id, p_checkpoint_id, trim(p_event_type), p_module_key,
    coalesce(p_occurred_at, now()), p_status, p_source, p_external_ref, coalesce(p_payload, '{}'::jsonb),
    p_observed_entity_type, p_observed_entity_id, v_actor
  ) RETURNING * INTO v_event;

  SELECT * INTO v_context
  FROM public.create_event_context_snapshot(
    'location_events', v_event.id, p_location_id, p_client_site_id, p_zone_id, p_checkpoint_id,
    p_module_key, p_service_agreement_id, p_provider_organization_id, p_client_organization_id,
    p_jurisdiction_organization_id, p_jurisdiction_rule_set_id, p_authority_snapshot,
    coalesce(p_source_refs, '{}'::jsonb) || jsonb_build_object('event_type', p_event_type, 'source', p_source),
    p_occurred_at
  );

  RETURN QUERY SELECT v_event.id, v_context.id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_location_event"(p_organization_id uuid, p_event_type text, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_occurred_at timestamp with time zone, p_status text, p_source text, p_external_ref text, p_payload jsonb, p_observed_entity_type text, p_observed_entity_id uuid, p_location_id uuid, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_location_event"(p_organization_id uuid, p_event_type text, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_occurred_at timestamp with time zone, p_status text, p_source text, p_external_ref text, p_payload jsonb, p_observed_entity_type text, p_observed_entity_id uuid, p_location_id uuid, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_location_event"(p_organization_id uuid, p_event_type text, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_occurred_at timestamp with time zone, p_status text, p_source text, p_external_ref text, p_payload jsonb, p_observed_entity_type text, p_observed_entity_id uuid, p_location_id uuid, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_location_event"(p_organization_id uuid, p_event_type text, p_client_site_id uuid, p_zone_id uuid, p_checkpoint_id uuid, p_module_key text, p_occurred_at timestamp with time zone, p_status text, p_source text, p_external_ref text, p_payload jsonb, p_observed_entity_type text, p_observed_entity_id uuid, p_location_id uuid, p_service_agreement_id uuid, p_provider_organization_id uuid, p_client_organization_id uuid, p_jurisdiction_organization_id uuid, p_jurisdiction_rule_set_id uuid, p_authority_snapshot jsonb, p_source_refs jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_on_call_period"(p_client_request_id uuid, p_officer_user_id uuid, p_period_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_flat_rate numeric DEFAULT NULL::numeric, p_linked_shift_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS on_call_periods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_period public.on_call_periods%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select actor.organization_id into v_provider from public.user_profiles actor
  where actor.id = v_actor and actor.deactivated_at is null;

  if v_provider is null or not public.is_admin_for_org(v_provider) then
    raise exception 'Active roster administrator required';
  end if;

  select p.* into v_period from public.on_call_periods p
  where p.organization_id = v_provider and p.client_request_id = p_client_request_id;
  if found then
    return v_period;
  end if;

  if p_period_type not in ('standard', 'before_shift', 'after_shift', 'overnight') then
    raise exception 'Unsupported on-call period type';
  end if;

  if p_ends_at <= p_starts_at then
    raise exception 'On-call period must end after it starts';
  end if;

  if not exists (
    select 1 from public.user_profiles u
    where u.id = p_officer_user_id and u.organization_id = v_provider and u.deactivated_at is null
  ) then
    raise exception 'On-call officer must be an active member of your organization';
  end if;

  if exists (
    select 1 from public.on_call_periods p
    where p.officer_user_id = p_officer_user_id
      and p.status in ('pending', 'accepted')
      and tstzrange(p.starts_at, p.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')
  ) then
    raise exception 'Officer already holds an overlapping on-call period';
  end if;

  insert into public.on_call_periods(
    organization_id, officer_user_id, period_type, starts_at, ends_at,
    flat_rate, linked_shift_id, status, client_request_id, notes
  )
  values (
    v_provider, p_officer_user_id, p_period_type, p_starts_at, p_ends_at,
    p_flat_rate, p_linked_shift_id, 'pending', p_client_request_id,
    nullif(trim(coalesce(p_notes, '')), '')
  )
  returning * into v_period;

  perform public.enqueue_notification(
    v_provider, 'roster', 'On-call period assigned',
    format('You are on call from %s to %s.',
      to_char(p_starts_at at time zone 'Pacific/Auckland', 'DD Mon HH24:MI'),
      to_char(p_ends_at at time zone 'Pacific/Auckland', 'DD Mon HH24:MI')),
    'info', p_officer_user_id, null, 'roster', jsonb_build_object('on_call_period_id', v_period.id),
    'on_call_assigned:' || v_period.id::text
  );

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_provider, v_actor, 'on_call_period_created', 'on_call_periods', v_period.id,
    jsonb_build_object(
      'officer_user_id', p_officer_user_id,
      'period_type', p_period_type,
      'flat_rate', p_flat_rate,
      'client_request_id', p_client_request_id
    )
  );

  return v_period;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_on_call_period"(p_client_request_id uuid, p_officer_user_id uuid, p_period_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_flat_rate numeric, p_linked_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_on_call_period"(p_client_request_id uuid, p_officer_user_id uuid, p_period_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_flat_rate numeric, p_linked_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_on_call_period"(p_client_request_id uuid, p_officer_user_id uuid, p_period_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_flat_rate numeric, p_linked_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_on_call_period"(p_client_request_id uuid, p_officer_user_id uuid, p_period_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_flat_rate numeric, p_linked_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_operating_cost_centre"(p_operating_organization_id uuid, p_code text, p_name text)
 RETURNS cost_centres
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_row public.cost_centres%rowtype;
begin
  if not public.user_can_operate_organization(p_operating_organization_id)
    or not public.is_admin_for_org(p_operating_organization_id) then
    raise exception 'Active authorized operating branch administrator required';
  end if;
  if nullif(trim(coalesce(p_code, '')), '') is null or nullif(trim(coalesce(p_name, '')), '') is null then
    raise exception 'Cost centre code and name are required';
  end if;
  insert into public.cost_centres(organization_id, code, name, created_by)
  values(p_operating_organization_id, upper(trim(p_code)), trim(p_name), v_actor)
  returning * into v_row;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values(p_operating_organization_id, v_actor, 'cost_centre_created', 'cost_centres', v_row.id,
    jsonb_build_object('code', v_row.code, 'name', v_row.name, 'operating_organization_id', p_operating_organization_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_operating_cost_centre"(p_operating_organization_id uuid, p_code text, p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_operating_cost_centre"(p_operating_organization_id uuid, p_code text, p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_operating_cost_centre"(p_operating_organization_id uuid, p_code text, p_name text) TO "authenticated";
