CREATE OR REPLACE FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_unit public.roster_work_units%rowtype;
  v_agreement uuid;
begin
  if not public.user_can_operate_organization(p_operating_organization_id)
    or not public.is_admin_for_org(p_operating_organization_id) then
    raise exception 'Active authorized operating branch administrator required';
  end if;
  if nullif(trim(coalesce(p_name, '')), '') is null or nullif(trim(coalesce(p_service_type, '')), '') is null then
    raise exception 'Name and service type are required';
  end if;
  if p_work_unit_type = 'patrol' then
    if p_patrol_route_id is null or not exists(select 1 from public.patrol_routes route where route.id = p_patrol_route_id and route.organization_id = p_operating_organization_id and route.is_active) then raise exception 'Active patrol route in this operating branch required'; end if;
  elsif p_work_unit_type = 'static' then
    select location.service_agreement_id into v_agreement from public.service_agreement_locations location join public.service_agreements agreement on agreement.id = location.service_agreement_id and agreement.provider_organization_id = p_operating_organization_id where location.id = p_service_agreement_location_id and location.status = 'active';
    if v_agreement is null or not exists(select 1 from public.service_agreement_modules module where module.id = p_service_agreement_module_id and module.service_agreement_id = v_agreement and module.enabled and module.module_key = 'static_guarding') then raise exception 'Active static guarding agreement location and module required'; end if;
  elsif p_work_unit_type = 'internal' then
    if p_workplace_id is null or not exists(select 1 from public.organization_workplaces workplace where workplace.id = p_workplace_id and workplace.organization_id = p_operating_organization_id and workplace.active) then raise exception 'Active provider workplace required'; end if;
    if p_team_id is not null and not exists(select 1 from public.teams team where team.id = p_team_id and team.organization_id = p_operating_organization_id and team.status = 'active') then raise exception 'Active team in this operating branch required'; end if;
    if p_cost_centre_id is not null and not exists(select 1 from public.cost_centres centre where centre.id = p_cost_centre_id and centre.organization_id = p_operating_organization_id and centre.active) then raise exception 'Active cost centre in this operating branch required'; end if;
  else raise exception 'Unsupported work unit type'; end if;
  insert into public.roster_work_units(organization_id, name, work_unit_type, service_type, patrol_route_id, service_agreement_location_id, service_agreement_module_id, workplace_id, team_id, cost_centre_id, created_by)
  values(p_operating_organization_id, trim(p_name), p_work_unit_type, trim(p_service_type), p_patrol_route_id, p_service_agreement_location_id, p_service_agreement_module_id, p_workplace_id, p_team_id, p_cost_centre_id, v_actor)
  returning * into v_unit;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values(p_operating_organization_id, v_actor, 'roster_work_unit_created', 'roster_work_units', v_unit.id,
    jsonb_build_object('work_unit_type', v_unit.work_unit_type, 'service_type', v_unit.service_type, 'operating_organization_id', p_operating_organization_id));
  return v_unit;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_operating_roster_work_unit"(p_operating_organization_id uuid, p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_organization_workplace"(p_name text, p_address text DEFAULT NULL::text)
 RETURNS organization_workplaces
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_row public.organization_workplaces%rowtype;
begin select up.organization_id into v_org from public.user_profiles up where up.id=v_actor and up.deactivated_at is null;if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Active roster administrator required';end if;if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Workplace name is required';end if;insert into public.organization_workplaces(organization_id,name,address,created_by)values(v_org,trim(p_name),nullif(trim(coalesce(p_address,'')),''),v_actor)returning * into v_row;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_org,v_actor,'organization_workplace_created','organization_workplaces',v_row.id,jsonb_build_object('name',v_row.name));return v_row;end;$function$;
REVOKE ALL ON FUNCTION "public"."create_organization_workplace"(p_name text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_organization_workplace"(p_name text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_organization_workplace"(p_name text, p_address text) TO "authenticated";
