CREATE OR REPLACE FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text DEFAULT NULL::text)
 RETURNS TABLE(route_id uuid, route_name text, created boolean, attached_places integer, skipped_places integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_route public.patrol_routes%rowtype;
  v_config public.client_site_patrol_config%rowtype;
  v_existing_route uuid;
  v_replay uuid;
  v_config_ids uuid[];
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_attached integer := 0;
  v_skipped integer := 0;
  v_start time;
  v_end time;
  v_module_id uuid;
  v_location_id uuid;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  select * into v_agreement from public.service_agreements where id = p_service_agreement_id;
  if not found then raise exception 'Service agreement not found'; end if;
  if v_agreement.agreement_type <> 'operational' or v_agreement.invitation_status <> 'accepted' then
    raise exception 'A patrol run can only be built from an accepted operational agreement';
  end if;
  if not public.is_admin_for_org(v_agreement.provider_organization_id) then
    raise exception 'Active authorized operating branch administrator required';
  end if;

  -- Idempotent replay on the same client request id.
  select target_id into v_replay from public.audit_log
  where action = 'patrol_route_created_from_agreement' and metadata->>'client_request_id' = p_client_request_id::text
  limit 1;
  if v_replay is not null then
    select * into v_route from public.patrol_routes where id = v_replay;
    return query select v_route.id, v_route.name, false,
      (select count(*)::integer from public.client_site_patrol_config c where c.patrol_route_id = v_route.id), 0;
    return;
  end if;

  -- Contract configs for this agreement (joined through the accepted schedule they came from).
  select array_agg(cspc.id) into v_config_ids
  from public.client_site_patrol_config cspc
  join public.service_agreement_delivery_schedules sads on sads.proposal_scope_schedule_id = cspc.proposal_scope_schedule_id
  where sads.service_agreement_id = v_agreement.id
    and sads.active
    and cspc.organization_id = v_agreement.provider_organization_id
    and cspc.active;

  if v_config_ids is null then
    raise exception 'This agreement has no scheduled patrol places yet. Add delivery schedules in the quote or a variation first';
  end if;

  -- Already routed (fully): return that route instead of making a second one.
  select c.patrol_route_id into v_existing_route from public.client_site_patrol_config c
  where c.id = any(v_config_ids) and c.patrol_route_id is not null limit 1;
  if v_existing_route is not null and not exists (select 1 from public.client_site_patrol_config c where c.id = any(v_config_ids) and c.patrol_route_id is null) then
    select * into v_route from public.patrol_routes where id = v_existing_route;
    return query select v_route.id, v_route.name, false, cardinality(v_config_ids), 0;
    return;
  end if;

  if v_existing_route is not null then
    select * into v_route from public.patrol_routes where id = v_existing_route;
  else
    select min(c.window_start), max(c.window_end) into v_start, v_end from public.client_site_patrol_config c where c.id = any(v_config_ids);
    insert into public.patrol_routes(organization_id, name, description, route_type, assignment_type, checkpoint_mode, default_start_time, default_end_time, is_active)
    values (
      v_agreement.provider_organization_id,
      coalesce(v_name, v_agreement.name || ' patrol run'),
      'Built from the accepted agreement "' || v_agreement.name || '". Stops come from its delivery schedules.',
      'mobile', 'client_patrol', 'none', v_start, v_end, true
    )
    returning * into v_route;
  end if;

  for v_config in
    select cspc.* from public.client_site_patrol_config cspc
    where cspc.id = any(v_config_ids) and cspc.patrol_route_id is null
    order by cspc.preferred_stop_order, cspc.created_at
  loop
    begin
      update public.client_site_patrol_config
      set patrol_route_id = v_route.id, updated_at = now()
      where id = v_config.id;
    exception when unique_violation then
      -- Same site + module already on this route (duplicate schedule); leave it unrouted and report it.
      v_skipped := v_skipped + 1;
      continue;
    end;
    v_attached := v_attached + 1;

    if v_config.site_id is not null then
      insert into public.patrol_route_sites(patrol_route_id, site_id, expected_visits_per_shift, preferred_stop_order, dwell_minutes, sla_arrive_within_minutes, required_module, preferred_time_window, notes)
      values (
        v_route.id, v_config.site_id, v_config.visits_per_shift, v_config.preferred_stop_order, v_config.dwell_minutes, v_config.sla_arrive_within_minutes, v_config.module_key,
        case when v_config.window_start is not null then to_char(v_config.window_start, 'HH24:MI') || '-' || coalesce(to_char(v_config.window_end, 'HH24:MI'), '') end,
        v_config.officer_instructions
      )
      on conflict (patrol_route_id, site_id) do nothing;
    end if;

    -- Contract inheritance for generated stops: which agreement module and covered place this stop serves.
    select sam.id into v_module_id from public.service_agreement_modules sam
    where sam.service_agreement_id = v_agreement.id and sam.enabled
      and sam.module_key = any(case when v_config.module_key = 'general_patrol' then array['patrol', 'general_patrol'] else array[v_config.module_key] end)
    order by case when sam.module_key = v_config.module_key then 0 else 1 end
    limit 1;
    select sal.id into v_location_id from public.service_agreement_locations sal
    where sal.service_agreement_id = v_agreement.id and sal.status = 'active'
      and sal.site_id is not distinct from v_config.site_id and sal.zone_id is not distinct from v_config.zone_id
    limit 1;
    insert into public.patrol_route_stop_modules(organization_id, patrol_config_id, module_key, is_required, display_order, service_agreement_module_id, service_agreement_location_id)
    values (v_agreement.provider_organization_id, v_config.id, v_config.module_key, true, v_config.preferred_stop_order, v_module_id, v_location_id)
    on conflict (patrol_config_id, module_key) do nothing;
  end loop;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_agreement.provider_organization_id, v_actor, 'patrol_route_created_from_agreement', 'patrol_routes', v_route.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'service_agreement_id', v_agreement.id, 'created', v_existing_route is null,
      'attached_places', v_attached, 'skipped_places', v_skipped));

  return query select v_route.id, v_route.name, v_existing_route is null, v_attached, v_skipped;
end;
$function$;
COMMENT ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text) IS 'Build (once, idempotent on client_request_id) a patrol route for an accepted operational agreement from its contract-derived client_site_patrol_config rows: creates patrol_routes, sets patrol_route_id on the unrouted configs, adds patrol_route_sites (access-doctrine trigger validates), and seeds patrol_route_stop_modules with the agreement module/location so generated shift stops inherit the contract. Provider admin only; audited.';
REVOKE ALL ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_patrol_route_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text DEFAULT 'csv'::text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(batch_id uuid, timesheet_count integer, total_hours numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_batch public.payroll_export_batches%rowtype;
  v_count integer;
  v_hours numeric;
  v_blocked_timesheet uuid;
  v_pay_blocker text;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select actor.organization_id into v_provider from public.user_profiles actor where actor.id = v_actor and actor.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active payroll administrator required'; end if;
  if p_organization_id <> v_provider then raise exception 'Organization is outside your managed hierarchy'; end if;
  if p_period_to < p_period_from then raise exception 'Export period end must not precede its start'; end if;
  if p_format not in ('csv', 'json', 'ird_csv') then raise exception 'Unsupported payroll export format'; end if;

  select t.id, public.timesheet_dispatch_pay_review_blocker(t.id) into v_blocked_timesheet, v_pay_blocker
  from public.timesheets t
  where t.organization_id = v_provider and t.status = 'approved' and t.payroll_export_batch_id is null and t.period_start >= p_period_from and t.period_end <= p_period_to
    and public.timesheet_dispatch_pay_review_blocker(t.id) is not null
  order by t.period_start, t.id
  limit 1;
  if v_blocked_timesheet is not null then raise exception 'Payroll export blocked by timesheet %: %', v_blocked_timesheet, v_pay_blocker; end if;

  select count(*), coalesce(sum(coalesce(t.actual_hours, t.work_derived_hours, 0)), 0) into v_count, v_hours from public.timesheets t where t.organization_id = v_provider and t.status = 'approved' and t.payroll_export_batch_id is null and t.period_start >= p_period_from and t.period_end <= p_period_to;
  if v_count = 0 then raise exception 'No approved unexported timesheets in this period'; end if;

  insert into public.payroll_export_batches(organization_id, exported_by, period_from, period_to, format, timesheet_count, total_hours, notes) values (v_provider, v_actor, p_period_from, p_period_to, p_format, v_count, v_hours, nullif(trim(coalesce(p_notes, '')), '')) returning * into v_batch;
  update public.timesheets t set payroll_export_batch_id = v_batch.id, status = 'paid' where t.organization_id = v_provider and t.status = 'approved' and t.payroll_export_batch_id is null and t.period_start >= p_period_from and t.period_end <= p_period_to;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_provider, v_actor, 'payroll_export_batch_created', 'payroll_export_batches', v_batch.id, jsonb_build_object('period_from', p_period_from, 'period_to', p_period_to, 'timesheet_count', v_count, 'total_hours', v_hours, 'format', p_format, 'client_request_id', p_client_request_id));
  return query select v_batch.id, v_batch.timesheet_count, v_batch.total_hours;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_payroll_export_batch"(p_client_request_id uuid, p_organization_id uuid, p_period_from date, p_period_to date, p_format text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid)
 RETURNS performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_cycle public.performance_review_cycles%rowtype; v_review public.performance_reviews%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_cycle from public.performance_review_cycles where id=p_cycle_id for update;
  if not found or not public.is_admin_for_org(v_cycle.organization_id) then raise exception 'Open review cycle not found in your organization'; end if;
  if v_cycle.status<>'open' then raise exception 'Reviews can only be created for an open cycle'; end if;
  if not exists(select 1 from public.staff_profiles sp where sp.id=p_staff_id and sp.organization_id=v_cycle.organization_id) then raise exception 'Staff member not found in this organization'; end if;
  if not exists(select 1 from public.user_profiles u where u.id=p_reviewer_user_id and u.organization_id=v_cycle.organization_id and u.deactivated_at is null) then raise exception 'Reviewer must be an active organization member'; end if;
  select * into v_review from public.performance_reviews where organization_id=v_cycle.organization_id and client_request_id=p_client_request_id;
  if found then return v_review; end if;
  insert into public.performance_reviews(organization_id,cycle_id,staff_id,reviewer_user_id,client_request_id) values(v_cycle.organization_id,p_cycle_id,p_staff_id,p_reviewer_user_id,p_client_request_id) returning * into v_review;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_cycle.organization_id,v_actor,'performance_review_created','performance_reviews',v_review.id,jsonb_build_object('cycle_id',p_cycle_id,'staff_id',p_staff_id,'reviewer_user_id',p_reviewer_user_id));
  return v_review;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_performance_review"(p_client_request_id uuid, p_cycle_id uuid, p_staff_id uuid, p_reviewer_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_parent public.organizations%rowtype;
  v_branch public.organizations%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_key text;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if v_actor is null or not public.user_can_operate_organization(p_parent_organization_id) or not public.is_admin_for_org(p_parent_organization_id) then
    raise exception 'Active organisation administrator required';
  end if;
  select * into v_parent from public.organizations where id = p_parent_organization_id for update;
  if not found or not v_parent.active or v_parent.organization_type not in ('owner', 'service_provider', 'branch') then
    raise exception 'Branches can only be added to an active provider organisation';
  end if;

  select * into v_branch from public.organizations
  where parent_organization_id = v_parent.id and client_request_id = p_client_request_id;
  if found then return v_branch; end if;

  if v_name is null or char_length(v_name) > 200 then raise exception 'Branch name is required and must be 200 characters or fewer'; end if;
  if exists (select 1 from public.organizations o where o.parent_organization_id = v_parent.id and lower(trim(o.name)) = lower(v_name) and o.status <> 'archived') then
    raise exception 'A branch with this name already exists';
  end if;

  insert into public.organizations (name, organization_type, parent_organization_id, active, status, contact_email, contact_phone, client_request_id)
  values (v_name, 'branch', v_parent.id, true, 'active',
          nullif(lower(trim(coalesce(p_contact_email, ''))), ''), nullif(trim(coalesce(p_contact_phone, '')), ''), p_client_request_id)
  returning * into v_branch;

  -- Inherit the parent's enabled modules, dependencies first, so the branch is usable immediately.
  for v_key in
    select pm.module_key from public.organization_modules pm
    where pm.organization_id = v_parent.id and pm.enabled
    order by (exists (select 1 from public.module_dependencies d where d.module_key = pm.module_key)), pm.module_key
  loop
    insert into public.organization_modules (organization_id, module_key, enabled)
    values (v_branch.id, v_key, true)
    on conflict (organization_id, module_key) do update set enabled = true;
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_parent.id, v_actor, 'provider_branch_created', 'organizations', v_branch.id,
          jsonb_build_object('name', v_branch.name, 'client_request_id', p_client_request_id));
  return v_branch;
end;
$function$;
COMMENT ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) IS 'Organisation settings: an administrator of an active provider organisation adds a branch (active immediately, inherits the parent''s enabled modules). Idempotent on (parent, client_request_id).';
REVOKE ALL ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_provider_branch"(p_client_request_id uuid, p_parent_organization_id uuid, p_name text, p_contact_email text, p_contact_phone text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_resume_storage_path text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS recruitment_candidates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_vacancy public.recruitment_vacancies%rowtype; v_row public.recruitment_candidates%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_vacancy from public.recruitment_vacancies where id=p_vacancy_id for update;
  if not found or not public.is_admin_for_org(v_vacancy.organization_id) then raise exception 'Open vacancy not found in your organization'; end if;
  if v_vacancy.status<>'open' then raise exception 'Candidates can only be added to an open vacancy'; end if;
  select * into v_row from public.recruitment_candidates where organization_id=v_vacancy.organization_id and client_request_id=p_client_request_id;
  if found then return v_row; end if;
  if nullif(trim(p_first_name),'') is null or nullif(trim(p_last_name),'') is null or nullif(lower(trim(p_email)),'') is null then raise exception 'Candidate name and email are required'; end if;
  insert into public.recruitment_candidates(organization_id,vacancy_id,first_name,last_name,email,phone,source,resume_storage_path,notes,client_request_id,created_by)
  values(v_vacancy.organization_id,v_vacancy.id,trim(p_first_name),trim(p_last_name),lower(trim(p_email)),nullif(trim(coalesce(p_phone,'')),''),nullif(trim(coalesce(p_source,'')),''),nullif(trim(coalesce(p_resume_storage_path,'')),''),nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,v_actor) returning * into v_row;
  insert into public.recruitment_candidate_events(candidate_id,organization_id,to_stage,note,actor_user_id) values(v_row.id,v_row.organization_id,'applied','Candidate added',v_actor);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_row.organization_id,v_actor,'recruitment_candidate_created','recruitment_candidates',v_row.id,jsonb_build_object('vacancy_id',v_row.vacancy_id,'client_request_id',p_client_request_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_recruitment_candidate"(p_client_request_id uuid, p_vacancy_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_source text, p_resume_storage_path text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_patrol_route_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_publish boolean DEFAULT false)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_profile public.user_profiles%rowtype; v_staff public.staff_profiles%rowtype; v_shift public.shifts%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.user_profiles where id=p_officer_user_id and deactivated_at is null;
  if not found or v_profile.organization_id is null then raise exception 'Active officer profile not found'; end if;
  if not public.is_admin_for_org(v_profile.organization_id) then raise exception 'Not authorised to roster this officer'; end if;
  if v_profile.role not in ('officer','admin_officer') then raise exception 'Selected user is not rosterable as an officer'; end if;
  select * into v_staff from public.staff_profiles where (id=p_officer_user_id or user_id=p_officer_user_id) and organization_id=v_profile.organization_id limit 1;
  if not found or not v_staff.work_ready then raise exception 'Officer is not work ready'; end if;
  if p_scheduled_start is null or p_scheduled_end is null or p_scheduled_start>=p_scheduled_end then raise exception 'Shift end must be after shift start'; end if;
  if p_scheduled_start<now()-interval '5 minutes' or p_scheduled_end-p_scheduled_start>interval '24 hours' then raise exception 'Shift timing is outside the accepted range'; end if;
  if nullif(trim(coalesce(p_service_type,'')),'') is null then raise exception 'Service type is required'; end if;
  if exists(select 1 from public.leave_requests l where l.staff_id=v_staff.id and l.status='approved' and daterange(l.starts_on,l.ends_on,'[]') && daterange(p_scheduled_start::date,p_scheduled_end::date,'[]')) then raise exception 'Officer has approved leave during this shift'; end if;
  if exists(select 1 from public.shifts s where s.officer_user_id=p_officer_user_id and s.status not in ('declined','cancelled') and s.scheduled_end>s.scheduled_start and s.scheduled_start<p_scheduled_end and s.scheduled_end>p_scheduled_start) then raise exception 'Officer already has an overlapping shift'; end if;
  insert into public.shifts(organization_id,officer_user_id,service_type,location_id,zone_id,patrol_route_id,scheduled_start,scheduled_end,status,notes)
  values(v_profile.organization_id,p_officer_user_id,trim(p_service_type),p_location_id,p_zone_id,p_patrol_route_id,p_scheduled_start,p_scheduled_end,case when p_publish then 'published' else 'scheduled' end,nullif(trim(coalesce(p_notes,'')),'')) returning * into v_shift;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_profile.organization_id,v_actor,'roster_shift_created','shifts',v_shift.id,jsonb_build_object('officer_user_id',p_officer_user_id,'scheduled_start',p_scheduled_start,'scheduled_end',p_scheduled_end,'status',v_shift.status));
  return v_shift;
end;$function$;
REVOKE ALL ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_roster_shift"(p_officer_user_id uuid, p_service_type text, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_location_id uuid, p_zone_id uuid, p_patrol_route_id uuid, p_notes text, p_publish boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_unit public.roster_work_units%rowtype;
  v_staff public.staff_profiles%rowtype;
  v_slot public.roster_slots%rowtype;
BEGIN
  SELECT u.* INTO v_unit FROM public.roster_work_units u WHERE u.id=p_work_unit_id AND u.active;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_unit.organization_id) THEN RAISE EXCEPTION 'Active authorized work unit required'; END IF;

  SELECT sp.* INTO v_staff
  FROM public.staff_profiles sp
  WHERE sp.id=p_staff_id AND sp.work_ready;
  IF NOT FOUND OR NOT (
    v_staff.organization_id = v_unit.organization_id
    OR EXISTS(
      SELECT 1 FROM public.staff_branch_authorisations sba
      WHERE sba.user_id = v_staff.user_id
        AND sba.branch_org_id = v_unit.organization_id
        AND sba.status = 'active'
    )
  ) THEN RAISE EXCEPTION 'Work-ready staff profile required'; END IF;

  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_scheduled_start >= p_scheduled_end OR p_scheduled_start < now() - interval '5 minutes' OR p_scheduled_end - p_scheduled_start > interval '24 hours' THEN RAISE EXCEPTION 'Slot timing is outside the accepted range'; END IF;

  SELECT s.* INTO v_slot FROM public.roster_slots s WHERE s.organization_id=v_unit.organization_id AND s.client_request_id=p_client_request_id;
  IF FOUND THEN RETURN v_slot; END IF;
  IF EXISTS(SELECT 1 FROM public.leave_requests l WHERE l.staff_id=p_staff_id AND l.status='approved' AND daterange(l.starts_on,l.ends_on,'[]') && daterange(p_scheduled_start::date,p_scheduled_end::date,'[]')) THEN RAISE EXCEPTION 'Staff member has approved leave'; END IF;
  IF EXISTS(SELECT 1 FROM public.roster_slots s WHERE s.staff_id=p_staff_id AND s.status NOT IN('declined','cancelled') AND s.scheduled_start < p_scheduled_end AND s.scheduled_end > p_scheduled_start) THEN RAISE EXCEPTION 'Staff member already has an overlapping roster slot'; END IF;

  INSERT INTO public.roster_slots(organization_id,work_unit_id,staff_id,scheduled_start,scheduled_end,status,client_request_id,notes,created_by)
  VALUES(v_unit.organization_id,v_unit.id,p_staff_id,p_scheduled_start,p_scheduled_end,CASE WHEN p_publish THEN 'published' ELSE 'draft' END,p_client_request_id,nullif(trim(coalesce(p_notes,'')),''),v_actor)
  RETURNING * INTO v_slot;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_unit.organization_id,v_actor,'roster_slot_created','roster_slots',v_slot.id,jsonb_build_object('work_unit_id',v_unit.id,'work_unit_type',v_unit.work_unit_type,'staff_id',p_staff_id,'status',v_slot.status));
  RETURN v_slot;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_roster_slot"(p_client_request_id uuid, p_work_unit_id uuid, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_publish boolean, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid DEFAULT NULL::uuid, p_service_agreement_location_id uuid DEFAULT NULL::uuid, p_service_agreement_module_id uuid DEFAULT NULL::uuid, p_workplace_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_cost_centre_id uuid DEFAULT NULL::uuid)
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_unit public.roster_work_units%rowtype;v_agreement uuid;
begin
 select up.organization_id into v_org from public.user_profiles up where up.id=v_actor and up.deactivated_at is null;if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Active roster administrator required';end if;
 if nullif(trim(coalesce(p_name,'')),'') is null or nullif(trim(coalesce(p_service_type,'')),'') is null then raise exception 'Name and service type are required';end if;
 if p_work_unit_type='patrol' then if p_patrol_route_id is null or not exists(select 1 from public.patrol_routes r where r.id=p_patrol_route_id and r.organization_id=v_org and r.is_active) then raise exception 'Active patrol route in this organization required';end if;
 elsif p_work_unit_type='static' then select sal.service_agreement_id into v_agreement from public.service_agreement_locations sal join public.service_agreements sa on sa.id=sal.service_agreement_id and sa.provider_organization_id=v_org where sal.id=p_service_agreement_location_id and sal.status='active';if v_agreement is null or not exists(select 1 from public.service_agreement_modules sam where sam.id=p_service_agreement_module_id and sam.service_agreement_id=v_agreement and sam.enabled and sam.module_key='static_guarding') then raise exception 'Active static guarding agreement location and module required';end if;
 elsif p_work_unit_type='internal' then if p_workplace_id is null or not exists(select 1 from public.organization_workplaces w where w.id=p_workplace_id and w.organization_id=v_org and w.active) then raise exception 'Active provider workplace required';end if;if p_team_id is not null and not exists(select 1 from public.teams t where t.id=p_team_id and t.organization_id=v_org and t.status='active') then raise exception 'Active team in this organization required';end if;if p_cost_centre_id is not null and not exists(select 1 from public.cost_centres c where c.id=p_cost_centre_id and c.organization_id=v_org and c.active) then raise exception 'Active cost centre in this organization required';end if;
 else raise exception 'Unsupported work unit type';end if;
 insert into public.roster_work_units(organization_id,name,work_unit_type,service_type,patrol_route_id,service_agreement_location_id,service_agreement_module_id,workplace_id,team_id,cost_centre_id,created_by)
 values(v_org,trim(p_name),p_work_unit_type,trim(p_service_type),p_patrol_route_id,p_service_agreement_location_id,p_service_agreement_module_id,p_workplace_id,p_team_id,p_cost_centre_id,v_actor) returning * into v_unit;
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'roster_work_unit_created','roster_work_units',v_unit.id,jsonb_build_object('work_unit_type',v_unit.work_unit_type,'service_type',v_unit.service_type));return v_unit;
end;$function$;
REVOKE ALL ON FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_roster_work_unit"(p_name text, p_work_unit_type text, p_service_type text, p_patrol_route_id uuid, p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_workplace_id uuid, p_team_id uuid, p_cost_centre_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_shift_coverage_request"(p_organization_id uuid, p_shift_date date, p_start_time time without time zone, p_end_time time without time zone, p_required_staff_count integer DEFAULT 1, p_urgency text DEFAULT 'normal'::text, p_notes text DEFAULT NULL::text)
 RETURNS shift_coverage_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_row public.shift_coverage_requests%rowtype;
begin if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to create coverage requests';end if;if p_shift_date<current_date or p_start_time is null or p_end_time is null or p_start_time=p_end_time then raise exception 'Coverage timing is invalid';end if;if p_required_staff_count not between 1 and 50 then raise exception 'Required staff count is outside the accepted range';end if;if p_urgency not in('low','normal','high','urgent') then raise exception 'Unsupported coverage urgency';end if;insert into public.shift_coverage_requests(organization_id,shift_date,start_time,end_time,required_staff_count,urgency,notes,created_by)values(p_organization_id,p_shift_date,p_start_time,p_end_time,p_required_staff_count,p_urgency,nullif(trim(coalesce(p_notes,'')),''),v_actor)returning * into v_row;insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_organization_id,v_actor,'shift_coverage_request_created','shift_coverage_requests',v_row.id,jsonb_build_object('shift_date',p_shift_date,'start_time',p_start_time,'end_time',p_end_time,'required_staff_count',p_required_staff_count,'urgency',p_urgency));return v_row;end;$function$;
REVOKE ALL ON FUNCTION "public"."create_shift_coverage_request"(p_organization_id uuid, p_shift_date date, p_start_time time without time zone, p_end_time time without time zone, p_required_staff_count integer, p_urgency text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_shift_coverage_request"(p_organization_id uuid, p_shift_date date, p_start_time time without time zone, p_end_time time without time zone, p_required_staff_count integer, p_urgency text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_shift_coverage_request"(p_organization_id uuid, p_shift_date date, p_start_time time without time zone, p_end_time time without time zone, p_required_staff_count integer, p_urgency text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."create_shift_coverage_request"(p_organization_id uuid, p_shift_date date, p_start_time time without time zone, p_end_time time without time zone, p_required_staff_count integer, p_urgency text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."create_workshop_work_order"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_description text DEFAULT NULL::text, p_client_organization_id uuid DEFAULT NULL::uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_client_site_id uuid DEFAULT NULL::uuid, p_asset_id uuid DEFAULT NULL::uuid, p_inventory_location_id uuid DEFAULT NULL::uuid, p_assigned_user_id uuid DEFAULT NULL::uuid, p_scheduled_for timestamp with time zone DEFAULT NULL::timestamp with time zone, p_bom_template_id uuid DEFAULT NULL::uuid)
 RETURNS workshop_work_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := public.workshop_actor_org(p_organization_id);
  v_wo public.workshop_work_orders%rowtype;
  v_tpl_line record;
  v_cost numeric; v_price numeric; v_uom text;
  v_seq integer;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_wo from public.workshop_work_orders w where w.organization_id = p_organization_id and w.client_request_id = p_client_request_id;
  if found then return v_wo; end if;
  if p_kind not in ('fabrication', 'maintenance') then raise exception 'Kind must be fabrication or maintenance'; end if;
  if nullif(trim(coalesce(p_title, '')), '') is null then raise exception 'Give the work order a title'; end if;
  if p_kind = 'maintenance' and p_client_site_id is null and p_asset_id is null then raise exception 'A maintenance visit needs the place or the asset being maintained'; end if;
  if p_client_site_id is not null and not exists (select 1 from public.client_sites s where s.id = p_client_site_id) then raise exception 'Site not found'; end if;
  if p_asset_id is not null and not exists (select 1 from public.assets a where a.id = p_asset_id and a.organization_id in (p_organization_id, p_client_organization_id)) then raise exception 'Asset not found'; end if;
  if p_inventory_location_id is not null and not exists (select 1 from public.finance_inventory_locations l where l.id = p_inventory_location_id and l.organization_id = p_organization_id and l.active) then raise exception 'Stock location not found'; end if;
  if p_service_agreement_id is not null and not exists (select 1 from public.service_agreements a where a.id = p_service_agreement_id and a.provider_organization_id = p_organization_id) then raise exception 'Agreement not found for this organisation'; end if;
  if p_bom_template_id is not null and not exists (select 1 from public.workshop_bom_templates t where t.id = p_bom_template_id and t.organization_id = p_organization_id and t.active) then raise exception 'Template not found'; end if;

  select count(*) + 1 into v_seq from public.workshop_work_orders w where w.organization_id = p_organization_id;
  insert into public.workshop_work_orders (organization_id, client_request_id, order_number, kind, title, description, client_organization_id, service_agreement_id,
                                           client_site_id, asset_id, inventory_location_id, bom_template_id, assigned_user_id, scheduled_for, created_by, updated_by)
  values (p_organization_id, p_client_request_id, 'WO-' || to_char(now(), 'YYYYMM') || '-' || lpad(v_seq::text, 4, '0'), p_kind, trim(p_title),
          nullif(trim(coalesce(p_description, '')), ''), p_client_organization_id, p_service_agreement_id, p_client_site_id, p_asset_id, p_inventory_location_id,
          p_bom_template_id, p_assigned_user_id, p_scheduled_for, v_actor, v_actor)
  returning * into v_wo;

  -- Copy the template's lines at today's approved cost and sell price.
  for v_tpl_line in select * from public.workshop_bom_template_lines l where l.template_id = p_bom_template_id order by l.position loop
    v_cost := null; v_price := null; v_uom := null;
    if v_tpl_line.item_id is not null then
      select cp.unit_cost, cp.unit_price, cp.unit_of_measure into v_cost, v_price, v_uom from public.workshop_current_prices(v_tpl_line.item_id) cp;
    end if;
    insert into public.workshop_work_order_lines (work_order_id, organization_id, line_kind, item_id, description, quantity, unit_of_measure, unit_cost, unit_price, position)
    values (v_wo.id, p_organization_id, v_tpl_line.line_kind, v_tpl_line.item_id, v_tpl_line.description, v_tpl_line.quantity,
            coalesce(v_tpl_line.unit_of_measure, v_uom), coalesce(v_cost, 0), coalesce(v_price, 0), v_tpl_line.position);
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'workshop_work_order_created', 'workshop_work_orders', v_wo.id,
          jsonb_build_object('order_number', v_wo.order_number, 'kind', v_wo.kind, 'client_organization_id', v_wo.client_organization_id, 'bom_template_id', p_bom_template_id));
  return v_wo;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."create_workshop_work_order"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."create_workshop_work_order"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."create_workshop_work_order"(p_client_request_id uuid, p_organization_id uuid, p_kind text, p_title text, p_description text, p_client_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_asset_id uuid, p_inventory_location_id uuid, p_assigned_user_id uuid, p_scheduled_for timestamp with time zone, p_bom_template_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1
    from public.user_profiles actor
    join public.organizations account on account.id=p_account_organization_id
    where actor.id=auth.uid()
      and actor.deactivated_at is null
      and (
        account.id=actor.organization_id
        or account.parent_organization_id=actor.organization_id
        or account.parent_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id,actor.organization_id)))
        or exists(
          select 1
          from public.service_agreements agreement
          where agreement.provider_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id,actor.organization_id)))
            and agreement.client_organization_id=account.id
            and agreement.agreement_type='operational'
            and agreement.invitation_status='accepted'
            and public.is_admin_for_org(agreement.provider_organization_id)
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_account"(p_account_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.locations l
    JOIN public.user_profiles actor ON actor.id = auth.uid() AND actor.deactivated_at IS NULL
    WHERE l.id = p_location_id
      AND public.is_admin_for_org(actor.organization_id)
      AND (
        l.organization_id = actor.organization_id
        OR l.organization_id = ANY(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
        OR EXISTS (
          SELECT 1
          FROM public.service_agreements agreement
          JOIN public.service_agreement_locations coverage ON coverage.service_agreement_id = agreement.id AND coverage.status = 'active'
          LEFT JOIN public.client_sites site ON site.id = coverage.site_id
          LEFT JOIN public.location_zones zone ON zone.id = coverage.zone_id
          WHERE agreement.provider_organization_id = actor.organization_id
            AND agreement.invitation_status = 'accepted'
            AND agreement.agreement_type = 'operational'
            AND (site.location_id = l.id OR zone.location_id = l.id)
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."crm_actor_can_manage_location"(p_location_id uuid) TO "service_role";

