CREATE OR REPLACE FUNCTION "public"."dispatch_job_create_sla_clock"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_agreement_id uuid;
  v_obligation_id uuid;
begin
  -- Only meter jobs that carry an SLA target.
  if new.sla_minutes is null then
    return new;
  end if;

  -- Resolve the service agreement for the job's site (best effort).
  if new.client_site_id is not null then
    select sfc.service_agreement_id
      into v_agreement_id
    from site_financial_config sfc
    where sfc.site_id = new.client_site_id
      and sfc.service_agreement_id is not null
    order by sfc.active desc nulls last, sfc.created_at desc
    limit 1;
  end if;

  -- Resolve the governing response_time obligation for that agreement.
  if v_agreement_id is not null then
    select ao.id
      into v_obligation_id
    from agreement_obligations ao
    where ao.service_agreement_id = v_agreement_id
      and ao.obligation_type = 'response_time'
      and ao.active = true
    order by ao.created_at
    limit 1;
  end if;

  insert into sla_clocks (
    organization_id, service_agreement_id, obligation_id,
    dispatch_job_id, site_id, started_at, target_minutes, status
  ) values (
    new.organization_id, v_agreement_id, v_obligation_id,
    new.id, new.client_site_id, coalesce(new.created_at, now()),
    new.sla_minutes, 'running'
  );

  return new;
end;
$function$;
COMMENT ON FUNCTION "public"."dispatch_job_create_sla_clock"() IS 'AFTER INSERT on dispatch_jobs: creates a running sla_clocks row when sla_minutes is set, resolving the response_time obligation via site -> agreement (best effort).';
REVOKE ALL ON FUNCTION "public"."dispatch_job_create_sla_clock"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."dispatch_job_create_sla_clock"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text)
 RETURNS staff_area_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_grant public.staff_area_grants%rowtype; v_reason text := nullif(trim(coalesce(p_reason,'')), '');
begin
  if v_reason is null then raise exception 'A change reason is required'; end if;
  select * into v_grant from public.staff_area_grants where id = p_grant_id for update;
  if not found or v_grant.status <> 'active' then raise exception 'Active direct area grant not found'; end if;
  if not public.user_can_operate_organization(v_grant.scope_org_id) or not public.staff_branch_authorisation_manager_can_manage(v_actor, v_grant.scope_org_id, v_grant.user_id) then raise exception 'Not authorised to end this branch area grant'; end if;
  if p_expected_updated_at is not null and v_grant.updated_at <> p_expected_updated_at then raise exception 'Direct area grant changed since it was opened'; end if;
  update public.staff_area_grants set status = 'ended', updated_at = clock_timestamp() where id = v_grant.id returning * into v_grant;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values(v_grant.scope_org_id, v_actor, 'branch_area_grant_ended', 'staff_area_grants', v_grant.id, jsonb_build_object('user_id',v_grant.user_id,'area',v_grant.area,'level',v_grant.level,'reason',v_reason));
  return v_grant;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."end_branch_area_grant"(p_grant_id uuid, p_expected_updated_at timestamp with time zone, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS shift_breaks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_break public.shift_breaks%rowtype;
begin
  select b.* into v_break from public.shift_breaks b where b.id = p_break_id for update;
  if not found then
    raise exception 'Break not found';
  end if;

  if v_break.officer_user_id <> v_actor then
    raise exception 'Only the officer who started this break can end it';
  end if;

  if v_break.ended_at is not null then
    return v_break;
  end if;

  update public.shift_breaks
  set ended_at = now(), notes = nullif(trim(coalesce(p_notes, '')), '')
  where id = v_break.id
  returning * into v_break;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_break.organization_id, v_actor, 'shift_break_ended', 'shift_breaks', v_break.id,
    jsonb_build_object(
      'shift_id', v_break.shift_id,
      'break_type', v_break.break_type,
      'duration_minutes', round(extract(epoch from (v_break.ended_at - v_break.started_at)) / 60.0)
    )
  );

  return v_break;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."end_shift_break"(p_break_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."enforce_roster_slot_availability"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_fatigue text;
begin
  if new.staff_id is not null and new.status not in ('declined', 'cancelled') then
    if public.staff_has_roster_availability_conflict(new.staff_id, new.scheduled_start, new.scheduled_end) then
      raise exception 'Staff member is unavailable during this roster slot';
    end if;
    v_fatigue := public.staff_fatigue_conflict(new.staff_id, new.scheduled_start, new.scheduled_end, new.id);
    if v_fatigue is not null then
      raise exception 'Fatigue rule breach: %', v_fatigue;
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."enforce_roster_slot_availability"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enforce_roster_slot_availability"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."enforce_roster_slot_availability"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text DEFAULT NULL::text, p_severity text DEFAULT 'info'::text, p_recipient_user_id uuid DEFAULT NULL::uuid, p_recipient_role text DEFAULT NULL::text, p_link_page text DEFAULT NULL::text, p_link_payload jsonb DEFAULT NULL::jsonb, p_dedup_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_recipient_user_id is null and p_recipient_role is null then
    raise exception 'enqueue_notification requires a recipient_user_id or recipient_role';
  end if;

  -- Idempotent on dedup_key within the org.
  if p_dedup_key is not null then
    select id into v_id
    from notifications
    where organization_id = p_organization_id and dedup_key = p_dedup_key
    limit 1;
    if v_id is not null then
      return v_id;
    end if;
  end if;

  insert into notifications (
    organization_id, recipient_user_id, recipient_role, category, severity,
    title, body, link_page, link_payload, dedup_key
  ) values (
    p_organization_id, p_recipient_user_id, p_recipient_role, p_category, coalesce(p_severity, 'info'),
    p_title, p_body, p_link_page, p_link_payload, p_dedup_key
  )
  returning id into v_id;

  return v_id;
end;
$function$;
COMMENT ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) IS 'Layer 4.4 single write path for notifications. Idempotent on (organization_id, dedup_key). SECURITY DEFINER so triggers/edge fns can enqueue.';
REVOKE ALL ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."enqueue_notification"(p_organization_id uuid, p_category text, p_title text, p_body text, p_severity text, p_recipient_user_id uuid, p_recipient_role text, p_link_page text, p_link_payload jsonb, p_dedup_key text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
  v_rec record;
  v_key text;
BEGIN
  IF p_person_record_id IS NULL THEN RETURN NULL; END IF;

  SELECT canonical_person_id INTO v_id
  FROM public.canonical_person_links
  WHERE source_table = 'person_records' AND source_id = p_person_record_id
  LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  SELECT id, display_name, organization_id, review_state INTO v_rec
  FROM public.person_records WHERE id = p_person_record_id;
  IF v_rec.id IS NULL THEN RETURN NULL; END IF;

  v_key := 'person_record:' || v_rec.id::text;
  INSERT INTO public.canonical_people (canonical_key, display_name, normalized_name, metadata, review_state)
  VALUES (
    v_key, v_rec.display_name,
    regexp_replace(lower(trim(coalesce(v_rec.display_name, ''))), '[^a-z0-9]+', '', 'g'),
    jsonb_build_object('created_from', 'person_records', 'source_id', v_rec.id, 'source_organization_id', v_rec.organization_id),
    coalesce(v_rec.review_state, 'draft')
  )
  ON CONFLICT (canonical_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM public.canonical_people WHERE canonical_key = v_key;
  END IF;

  INSERT INTO public.canonical_person_links (canonical_person_id, source_table, source_id, organization_id, link_kind, metadata)
  VALUES (v_id, 'person_records', v_rec.id, v_rec.organization_id, 'projection', jsonb_build_object('review_state', v_rec.review_state))
  ON CONFLICT (source_table, source_id) DO NOTHING;

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) IS 'Find-or-create the global person identity for a tenant-scoped person_records row. Cross-organization merges remain a human review action.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_person_for_record"(p_person_record_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_into uuid; v_status text; v_hops integer := 0;
BEGIN
  IF p_key IS NULL OR p_kind NOT IN ('site', 'zone') THEN RETURN NULL; END IF;
  INSERT INTO public.canonical_places (place_kind, canonical_key, display_name, normalized_name, address, metadata)
  VALUES (p_kind, p_key, coalesce(nullif(trim(p_name), ''), p_address, p_key),
          regexp_replace(lower(trim(coalesce(p_name, ''))), '[^a-z0-9]+', '', 'g'), p_address, coalesce(p_meta, '{}'::jsonb))
  ON CONFLICT (canonical_key) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    SELECT id, status, merged_into_id INTO v_id, v_status, v_into FROM public.canonical_places WHERE canonical_key = p_key;
    WHILE v_status = 'merged' AND v_into IS NOT NULL AND v_hops < 10 LOOP
      SELECT id, status, merged_into_id INTO v_id, v_status, v_into FROM public.canonical_places WHERE id = v_into;
      v_hops := v_hops + 1;
    END LOOP;
  END IF;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place"(p_kind text, p_key text, p_name text, p_address text, p_meta jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house public.locations%rowtype; v_id uuid;
BEGIN
  SELECT * INTO v_house FROM public.locations WHERE id = p_location_id;
  IF v_house.id IS NULL THEN RETURN NULL; END IF;
  IF v_house.canonical_place_id IS NOT NULL THEN RETURN v_house.canonical_place_id; END IF;
  v_id := public.canonical_place_for_house(v_house.id, v_house.organization_id, v_house.name, v_house.address, v_house.address_match_key,
    CASE WHEN EXISTS (SELECT 1 FROM public.client_sites s WHERE s.location_id = v_house.id) THEN 'site' ELSE 'zone' END);
  UPDATE public.locations SET canonical_place_id = v_id, updated_at = now() WHERE id = v_house.id;
  RETURN v_id;
END $function$;
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_house"(p_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_house uuid; v_org uuid; v_id uuid;
BEGIN
  IF p_source_id IS NULL THEN RETURN NULL; END IF;
  IF p_source_table = 'locations' THEN
    v_house := p_source_id;
  ELSIF p_source_table = 'client_sites' THEN
    SELECT location_id, client_organization_id INTO v_house, v_org FROM public.client_sites WHERE id = p_source_id;
  ELSIF p_source_table = 'location_zones' THEN
    SELECT location_id, organization_id INTO v_house, v_org FROM public.location_zones WHERE id = p_source_id;
  ELSE
    RETURN NULL;
  END IF;
  IF v_house IS NULL THEN RETURN NULL; END IF;
  SELECT canonical_place_id INTO v_id FROM public.locations WHERE id = v_house;
  IF v_id IS NULL THEN v_id := public.ensure_canonical_place_for_house(v_house); END IF;
  IF v_id IS NULL THEN RETURN NULL; END IF;
  IF p_source_table <> 'locations' THEN
    INSERT INTO public.canonical_place_links (canonical_place_id, source_table, source_id, organization_id, link_kind, source_key, metadata)
    VALUES (v_id, p_source_table, p_source_id, v_org, 'projection', p_source_id::text, jsonb_build_object('location_id', v_house))
    ON CONFLICT (source_table, source_id) DO UPDATE SET canonical_place_id = EXCLUDED.canonical_place_id;
  END IF;
  RETURN v_id;
END $function$;
COMMENT ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) IS 'Find-or-create the global place identity for a locations/client_sites/location_zones row, mirroring the backfill precedence: a facet with a house links to the house identity.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_place_for_projection"(p_source_table text, p_source_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_alnum text := upper(regexp_replace(coalesce(p_plate, ''), '[^A-Za-z0-9]', '', 'g'));
  v_plate text := public.normalize_plate_number(p_plate);
  v_id uuid;
BEGIN
  IF v_plate IS NULL THEN RETURN NULL; END IF;
  -- A plate whose identity would be altered by the 10-char rule is not a valid
  -- vehicle identity; leave the record unlinked rather than assert a truncated one.
  IF length(v_alnum) > 10 THEN RETURN NULL; END IF;

  SELECT id INTO v_id FROM public.canonical_vehicles WHERE plate_number = v_plate;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  INSERT INTO public.canonical_vehicles (plate_number, make, model, colour, last_seen_at)
  VALUES (v_plate, p_make, p_model, p_colour, p_observed_at)
  ON CONFLICT (plate_number) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    -- A concurrent writer created it between the SELECT and the INSERT.
    SELECT id INTO v_id FROM public.canonical_vehicles WHERE plate_number = v_plate;
    RETURN v_id;
  END IF;

  INSERT INTO public.canonical_vehicle_links (canonical_vehicle_id, source_system, source_table, source_key, metadata)
  VALUES (
    v_id, 'field_observation', p_source_table, p_source_key,
    jsonb_build_object('created_from_record', true, 'observed_at', p_observed_at, 'raw_plate', p_plate)
  )
  ON CONFLICT (source_system, source_table, source_key) DO NOTHING;

  RETURN v_id;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) IS 'Find-or-create the global vehicle identity for a normalized plate. On create, records a canonical_vehicle_links provenance row pointing at the field record that first observed it.';
REVOKE ALL ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_canonical_vehicle"(p_plate text, p_make text, p_model text, p_colour text, p_source_table text, p_source_key text, p_observed_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid DEFAULT NULL::uuid, p_evidence_item_id uuid DEFAULT NULL::uuid, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(person_record_id uuid, canonical_person_id uuid, display_name text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_person_id uuid;
  v_canonical_id uuid;
  v_display_name text;
  v_unknown_number integer;
  v_created boolean := false;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_organization_id IS NULL OR p_portfolio_key IS NULL THEN
    RAISE EXCEPTION 'Organization and person portfolio are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_organization_id) THEN
    RAISE EXCEPTION 'Organization does not exist';
  END IF;

  -- Serialise the per-organisation number so concurrent clips cannot mint the same Unknown Person #N.
  PERFORM pg_advisory_xact_lock(hashtextextended('cctv_unknown_person:' || p_organization_id::text, 0));

  SELECT observation.person_record_id,
         COALESCE(observation.canonical_person_id, link.canonical_person_id),
         person.display_name
    INTO v_person_id, v_canonical_id, v_display_name
    FROM public.cctv_entity_observations AS observation
    LEFT JOIN public.person_records AS person
      ON person.id = observation.person_record_id
    LEFT JOIN public.canonical_person_links AS link
      ON link.source_table = 'person_records'
     AND link.source_id = observation.person_record_id
   WHERE observation.organization_id = p_organization_id
     AND observation.entity_kind = 'person'
     AND observation.portfolio_key = p_portfolio_key
     AND observation.review_state <> 'rejected'
     AND observation.person_record_id IS NOT NULL
   ORDER BY (observation.review_state = 'accepted') DESC,
            observation.reviewed_at DESC NULLS LAST,
            observation.observed_at
   LIMIT 1;

  IF v_person_id IS NULL THEN
    SELECT person.id, link.canonical_person_id, person.display_name
      INTO v_person_id, v_canonical_id, v_display_name
      FROM public.person_records AS person
      LEFT JOIN public.canonical_person_links AS link
        ON link.source_table = 'person_records'
       AND link.source_id = person.id
     WHERE person.organization_id = p_organization_id
       AND person.metadata->>'cctv_portfolio_key' = p_portfolio_key::text
     ORDER BY person.created_at
     LIMIT 1;
  END IF;

  IF v_person_id IS NULL THEN
    SELECT COALESCE(MAX(GREATEST(
      CASE WHEN person.metadata->>'cctv_unknown_person_number' ~ '^[0-9]+$'
        THEN (person.metadata->>'cctv_unknown_person_number')::integer ELSE 0 END,
      CASE WHEN person.display_name ~ '^Unknown Person #[0-9]+$'
        THEN regexp_replace(person.display_name, '^Unknown Person #', '')::integer ELSE 0 END
    )), 0) + 1
      INTO v_unknown_number
      FROM public.person_records AS person
     WHERE person.organization_id = p_organization_id;

    v_display_name := 'Unknown Person #' || v_unknown_number;
    INSERT INTO public.person_records (organization_id, display_name, review_state, metadata)
    VALUES (
      p_organization_id,
      v_display_name,
      'manual_review_required',
      jsonb_strip_nulls(jsonb_build_object(
        'origin', 'cctv_inference_profile',
        'identity_status', 'unknown_pending_human_review',
        'cctv_portfolio_key', p_portfolio_key,
        'cctv_unknown_person_number', v_unknown_number,
        'first_observation_id', p_observation_id,
        'first_evidence_item_id', p_evidence_item_id,
        'first_seen_at', p_observed_at
      ))
    )
    RETURNING id INTO v_person_id;
    v_canonical_id := public.ensure_canonical_person_for_record(v_person_id);
    UPDATE public.canonical_people
       SET metadata = metadata || jsonb_strip_nulls(jsonb_build_object(
             'origin', 'cctv_inference_profile',
             'identity_status', 'unknown_pending_human_review',
             'cctv_portfolio_key', p_portfolio_key,
             'cctv_unknown_person_number', v_unknown_number,
             'first_observation_id', p_observation_id,
             'first_evidence_item_id', p_evidence_item_id,
             'first_seen_at', p_observed_at
           )),
           review_state = 'manual_review_required',
           updated_at = clock_timestamp()
     WHERE id = v_canonical_id;
    v_created := true;

    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (
      p_organization_id,
      NULL,
      'cctv_unknown_person_profile_created',
      'person_records',
      v_person_id,
      jsonb_build_object(
        'canonical_person_id', v_canonical_id,
        'portfolio_key', p_portfolio_key,
        'unknown_person_number', v_unknown_number,
        'observation_id', p_observation_id,
        'evidence_item_id', p_evidence_item_id
      )
    );
  ELSE
    v_canonical_id := COALESCE(v_canonical_id, public.ensure_canonical_person_for_record(v_person_id));
  END IF;

  person_record_id := v_person_id;
  canonical_person_id := v_canonical_id;
  display_name := v_display_name;
  created := v_created;
  RETURN NEXT;
END;
$function$;
COMMENT ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) IS 'Service-only find-or-create of an Unknown Person #N person_records/canonical_people profile for a CCTV face/body portfolio. The profile remains manual_review_required until a human identifies it.';
REVOKE ALL ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_cctv_person_profile"(p_organization_id uuid, p_portfolio_key uuid, p_observation_id uuid, p_evidence_item_id uuid, p_observed_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."ensure_site_financial_config_from_site"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.service_agreement_id is null then
    return new;
  end if;

  insert into public.site_financial_config (
    organization_id,
    site_id,
    service_agreement_id,
    billing_model,
    billing_cycle,
    gst_registered,
    gst_rate,
    payment_terms_days,
    minimum_hours,
    active
  )
  values (
    new.client_organization_id,
    new.id,
    new.service_agreement_id,
    'hourly',
    'monthly',
    true,
    0.15,
    14,
    2,
    true
  )
  on conflict (site_id, service_agreement_id) do nothing;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."ensure_site_financial_config_from_site"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."ensure_site_financial_config_from_site"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean DEFAULT false, p_sign_time_limit_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule record;
  v_legacy_zone_limit integer;
  v_legacy_multiplier numeric;
  v_legacy_org_default integer;
  v_legacy_grace integer;
  v_effective_limit integer;
  v_grace integer;
  v_multiplier numeric;
  v_chalk record;
  v_minutes_elapsed numeric;
  v_is_overstay boolean := false;
  v_is_repeat boolean;
  v_repeat_count integer;
BEGIN
  SELECT * INTO v_rule
  FROM public.parking_rule_matrix
  WHERE organization_id = p_org_id
    AND is_current
    AND effective_from <= current_date
    AND (effective_to IS NULL OR effective_to >= current_date)
    AND (zone_id = p_zone_id OR zone_id IS NULL)
  ORDER BY (zone_id IS NULL), effective_from DESC, version DESC
  LIMIT 1;

  SELECT parking_time_limit_minutes, parking_disabled_multiplier INTO v_legacy_zone_limit, v_legacy_multiplier
  FROM public.location_zones WHERE id = p_zone_id;
  SELECT default_time_limit_minutes, grace_period_minutes INTO v_legacy_org_default, v_legacy_grace
  FROM public.parking_module_config WHERE organization_id = p_org_id;

  v_effective_limit := COALESCE(p_sign_time_limit_minutes, v_rule.time_limit_minutes, v_legacy_zone_limit, v_legacy_org_default, 60);
  v_grace := COALESCE(v_rule.grace_period_minutes, v_legacy_grace, 5);
  v_multiplier := COALESCE(v_rule.disabled_multiplier, v_legacy_multiplier, 1);
  IF p_is_disabled_bay THEN v_effective_limit := round(v_effective_limit * v_multiplier); END IF;

  SELECT * INTO v_chalk FROM public.parking_chalk_records
  WHERE organization_id = p_org_id AND plate = upper(p_plate) AND status = 'active'
    AND (p_zone_id IS NULL OR zone_id = p_zone_id)
  ORDER BY chalked_at DESC LIMIT 1;

  IF v_chalk.id IS NOT NULL THEN
    v_minutes_elapsed := extract(epoch FROM (now() - v_chalk.chalked_at)) / 60.0;
    v_is_overstay := v_minutes_elapsed > (v_effective_limit + v_grace);
  END IF;

  SELECT count(*) INTO v_repeat_count FROM public.parking_chalk_records
  WHERE organization_id = p_org_id AND plate = upper(p_plate)
    AND chalked_at >= date_trunc('day', current_timestamp AT TIME ZONE 'Pacific/Auckland') AT TIME ZONE 'Pacific/Auckland'
    AND status != 'compliant' AND (v_chalk.id IS NULL OR id != v_chalk.id);
  v_is_repeat := v_repeat_count > 0;

  RETURN jsonb_build_object(
    'verdict', CASE WHEN v_is_overstay AND v_is_repeat THEN 'repeat_offender' WHEN v_is_overstay THEN 'overstay' WHEN v_chalk.id IS NOT NULL THEN 'watch' ELSE 'clear' END,
    'effective_limit_minutes', v_effective_limit, 'grace_period_minutes', v_grace,
    'chalked_at', v_chalk.chalked_at, 'minutes_elapsed', v_minutes_elapsed,
    'is_overstay', v_is_overstay, 'is_repeat', v_is_repeat, 'repeat_count', v_repeat_count,
    'recommended_action', CASE WHEN v_is_overstay THEN 'infringement' WHEN v_chalk.id IS NOT NULL THEN 'warning' ELSE 'none' END,
    'rule_matrix_id', v_rule.id, 'rule_matrix_version', v_rule.version
  );
END;
$function$;
COMMENT ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) IS 'Evaluate parking compliance for a plate in a zone. Resolves effective time limit (sign OCR > zone default > org default), applies disabled multiplier, checks overstay and repeat offender status. Called by process-officer-scan when module_key=parking_enforcement. Issue #116. Fixed in 0233: C6 (numeric precision), C3 (zone filter tightening).';
REVOKE ALL ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."evaluate_parking_compliance"(p_org_id uuid, p_zone_id uuid, p_plate text, p_is_disabled_bay boolean, p_sign_time_limit_minutes integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval DEFAULT '90 days'::interval, p_organization_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_total integer := 0;
  v_org record;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_retention IS NULL OR p_retention < interval '1 day' THEN RAISE EXCEPTION 'Biometric retention must be at least one day'; END IF;

  FOR v_org IN
    WITH due AS (
      SELECT o.id, o.organization_id
        FROM public.cctv_entity_observations o
       WHERE (p_organization_id IS NULL OR o.organization_id = p_organization_id)
         AND (o.face_vec IS NOT NULL OR o.appearance_vec IS NOT NULL OR o.candidate_embedding IS NOT NULL OR o.appearance_embedding IS NOT NULL)
         AND (
           o.review_state = 'rejected'
           OR (o.review_state IN ('unreviewed', 'uncertain', 'needs_more_context', 'superseded') AND o.created_at < v_now - p_retention)
         )
       ORDER BY o.created_at
       LIMIT p_limit
    ), expired AS (
      UPDATE public.cctv_entity_observations o
         SET face_vec = NULL, appearance_vec = NULL, candidate_embedding = NULL, appearance_embedding = NULL,
             attributes = coalesce(o.attributes, '{}'::jsonb) || jsonb_build_object('biometric_templates_expired_at', v_now, 'biometric_templates_expiry_reason',
               CASE WHEN o.review_state = 'rejected' THEN 'rejected' ELSE 'retention_window' END)
        FROM due
       WHERE o.id = due.id
      RETURNING o.organization_id, (o.attributes->>'biometric_templates_expiry_reason') AS reason
    )
    SELECT organization_id, count(*) FILTER (WHERE reason = 'rejected') AS rejected, count(*) FILTER (WHERE reason = 'retention_window') AS aged, count(*) AS total
      FROM expired GROUP BY organization_id
  LOOP
    v_total := v_total + v_org.total;
    INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
    VALUES (v_org.organization_id, NULL, 'cctv_biometric_templates_expired', 'cctv_entity_observations', NULL,
            jsonb_build_object('expired', v_org.total, 'rejected', v_org.rejected, 'aged_out', v_org.aged, 'retention', p_retention::text, 'expired_at', v_now));
  END LOOP;

  RETURN jsonb_build_object('expired', v_total, 'retention', p_retention::text, 'expired_at', v_now);
END $function$;
COMMENT ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) IS 'Service-only: nulls the biometric template columns on rejected sightings and on undecided sightings older than the retention window (default 90 days). Keeps the sighting, thumbnail and decision. One audit_log row per organisation with counts only.';
REVOKE ALL ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."expire_cctv_biometric_templates"(p_retention interval, p_organization_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb)
 RETURNS real
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  left_value jsonb;
  right_value jsonb;
  left_norm double precision := 0;
  right_norm double precision := 0;
  dot_product double precision := 0;
  index integer;
  left_number double precision;
  right_number double precision;
BEGIN
  IF jsonb_typeof(p_left) <> 'array' OR jsonb_typeof(p_right) <> 'array'
     OR jsonb_array_length(p_left) = 0 OR jsonb_array_length(p_left) <> jsonb_array_length(p_right) THEN
    RETURN 0;
  END IF;
  FOR index IN 0..jsonb_array_length(p_left) - 1 LOOP
    left_value := p_left -> index;
    right_value := p_right -> index;
    IF jsonb_typeof(left_value) <> 'number' OR jsonb_typeof(right_value) <> 'number' THEN
      RETURN 0;
    END IF;
    left_number := left_value::text::double precision;
    right_number := right_value::text::double precision;
    dot_product := dot_product + left_number * right_number;
    left_norm := left_norm + left_number * left_number;
    right_norm := right_norm + right_number * right_number;
  END LOOP;
  IF left_norm = 0 OR right_norm = 0 THEN RETURN 0; END IF;
  RETURN (dot_product / sqrt(left_norm * right_norm))::real;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."face_embedding_cosine"(p_left jsonb, p_right jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb)
 RETURNS biosecurity_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_assessment public.biosecurity_assessments%rowtype;
  v_actor public.user_profiles%rowtype;
  v_storage_path text := p_photo ->> 'storage_path';
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO v_actor
  FROM public.user_profiles
  WHERE id = p_actor_user_id;

  IF NOT FOUND OR v_actor.role::text NOT IN ('grand_master', 'master', 'admin', 'admin_officer', 'officer') THEN
    RAISE EXCEPTION 'Authorized actor required';
  END IF;

  SELECT * INTO v_assessment
  FROM public.biosecurity_assessments
  WHERE id = p_assessment_id
  FOR UPDATE;

  IF NOT FOUND OR v_assessment.organization_id IS DISTINCT FROM v_actor.organization_id THEN
    RAISE EXCEPTION 'Assessment not found';
  END IF;
  IF v_actor.role::text = 'officer'
     AND v_assessment.officer_user_id IS DISTINCT FROM p_actor_user_id
     AND v_assessment.officer_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION 'Officer does not own assessment';
  END IF;
  IF jsonb_typeof(p_photo) IS DISTINCT FROM 'object'
     OR COALESCE(p_photo ->> 'id', '') = ''
     OR COALESCE(p_photo ->> 'storage_bucket', '') <> 'scans'
     OR v_storage_path NOT LIKE 'org/' || v_assessment.organization_id::text || '/biosecurity/' || v_assessment.id::text || '/%' THEN
    RAISE EXCEPTION 'Invalid evidence reference';
  END IF;
  IF p_confidence < 0 OR p_confidence > 1 OR p_confidence IS NULL THEN
    RAISE EXCEPTION 'Invalid inference confidence';
  END IF;
  IF jsonb_typeof(p_checklist) IS DISTINCT FROM 'object'
     OR COALESCE(p_checklist ->> 'photo_id', '') <> p_photo ->> 'id' THEN
    RAISE EXCEPTION 'Invalid inference checklist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(COALESCE(v_assessment.photo_urls, '[]'::jsonb)) AS existing_photo
    WHERE existing_photo ->> 'id' = p_photo ->> 'id'
  ) THEN
    RETURN v_assessment;
  END IF;

  UPDATE public.biosecurity_assessments
  SET photo_url = v_storage_path,
      photo_urls = COALESCE(photo_urls, '[]'::jsonb) || jsonb_build_array(p_photo),
      bob_species_id = NULLIF(BTRIM(p_species_id), ''),
      bob_confidence = p_confidence,
      bob_species_confirmed = false,
      bob_recommendation = NULLIF(BTRIM(p_recommendation), ''),
      bob_checklist = p_checklist
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  INSERT INTO public.audit_log (
    organization_id,
    actor_user_id,
    action,
    target_table,
    target_id,
    metadata
  )
  VALUES (
    v_assessment.organization_id,
    p_actor_user_id,
    'biosecurity.photo_classified',
    'biosecurity_assessments',
    v_assessment.id,
    jsonb_build_object(
      'photo_id', p_photo ->> 'id',
      'model', p_checklist ->> 'model',
      'confidence', p_confidence,
      'manual_review_required', COALESCE((p_checklist ->> 'manual_review_required')::boolean, true)
    )
  );

  RETURN v_assessment;
END;
$function$;
COMMENT ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) IS 'Atomically appends tenant-scoped biosecurity photo evidence, stores advisory inference, and writes its audit event. Service identity only; never confirms species.';
REVOKE ALL ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_biosecurity_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_photo jsonb, p_species_id text, p_confidence real, p_recommendation text, p_checklist jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, request_status text, roster_slot_id uuid, shift_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_request public.shift_coverage_requests%rowtype;v_staff public.staff_profiles%rowtype;v_unit public.roster_work_units%rowtype;v_slot public.roster_slots%rowtype;v_materialized record;v_shift_id uuid;v_start timestamptz;v_end timestamptz;
begin
  select r.* into v_request from public.shift_coverage_requests r where r.id=p_request_id for update;if not found then raise exception 'Coverage request not found';end if;
  if not public.is_admin_for_org(v_request.organization_id) then raise exception 'Active roster administrator required';end if;
  if v_request.status<>p_expected_status then raise exception 'Coverage request changed from expected status % to %',p_expected_status,v_request.status;end if;
  if v_request.status<>'claimed' or v_request.claimed_by is null then raise exception 'Only claimed coverage can be finalized';end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.organization_id=v_request.organization_id and (sp.user_id=v_request.claimed_by or sp.id=v_request.claimed_by);if not found then raise exception 'Claimant staff profile not found';end if;
  select u.* into v_unit from public.roster_work_units u where u.id=p_work_unit_id and u.organization_id=v_request.organization_id and u.active;if not found then raise exception 'Active work unit in this organization required';end if;
  if v_request.patrol_route_id is not null and v_unit.patrol_route_id is distinct from v_request.patrol_route_id then raise exception 'Work unit does not match requested patrol route';end if;
  v_start:=(v_request.shift_date+v_request.start_time) at time zone 'Pacific/Auckland';v_end:=(v_request.shift_date+v_request.end_time) at time zone 'Pacific/Auckland';if v_end<=v_start then v_end:=v_end+interval '1 day';end if;
  select * into v_slot from public.create_roster_slot(v_request.id,v_unit.id,v_staff.id,v_start,v_end,true,concat_ws(E'\n',nullif(trim(coalesce(v_request.notes,'')),''),nullif(trim(coalesce(p_notes,'')),'')));
  if v_unit.work_unit_type<>'internal' then select * into v_materialized from public.materialize_roster_slot(v_slot.id,'published');v_shift_id:=v_materialized.shift_id;end if;
  update public.shift_coverage_requests set status='filled',filled_at=clock_timestamp(),roster_slot_id=v_slot.id where id=v_request.id returning * into v_request;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_request.organization_id,v_actor,'shift_coverage_finalized','shift_coverage_requests',v_request.id,jsonb_build_object('claimed_by',v_request.claimed_by,'work_unit_id',v_unit.id,'roster_slot_id',v_slot.id,'shift_id',v_shift_id));
  perform public.enqueue_notification(p_organization_id=>v_request.organization_id,p_category=>'roster',p_title=>'Coverage assignment confirmed',p_body=>'Your claimed coverage is now a confirmed roster assignment.',p_severity=>'info',p_recipient_user_id=>v_request.claimed_by,p_link_page=>'schedule',p_link_payload=>jsonb_build_object('roster_slot_id',v_slot.id,'shift_id',v_shift_id),p_dedup_key=>'coverage_finalized:'||v_request.id::text);
  return query select v_request.id,v_request.status,v_slot.id,v_shift_id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."finalize_shift_coverage"(p_request_id uuid, p_expected_status text, p_work_unit_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text)
 RETURNS smoke_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_assessment public.smoke_assessments%rowtype;v_actor public.user_profiles%rowtype;
begin
  if auth.role() <> 'service_role' then raise exception 'Service identity required';end if;
  select * into v_actor from public.user_profiles where id=p_actor_user_id and deactivated_at is null;
  if not found or v_actor.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Authorized actor required';end if;
  select * into v_assessment from public.smoke_assessments where id=p_assessment_id for update;
  if not found or v_assessment.organization_id is distinct from v_actor.organization_id then raise exception 'Assessment not found';end if;
  if v_actor.role='officer' and v_assessment.officer_user_id is distinct from p_actor_user_id then raise exception 'Officer does not own assessment';end if;
  if v_assessment.status<>'open' then raise exception 'Only open Smoke assessments can be classified';end if;
  if jsonb_typeof(p_analysis) is distinct from 'object' or coalesce((p_analysis->>'schema_version')::integer,0)<>1 or coalesce((p_analysis->>'images_analyzed')::integer,0) not between 1 and 3 or jsonb_typeof(p_analysis->'confidence_by_field') is distinct from 'object' or nullif(p_analysis->>'legal_use_boundary','') is null then raise exception 'Invalid Smoke inference analysis';end if;
  if p_confidence is null or p_confidence<0 or p_confidence>1 then raise exception 'Invalid inference confidence';end if;
  if v_assessment.smoke_ai_analysis is not null then return v_assessment;end if;
  update public.smoke_assessments set bob_classification=nullif(btrim(p_summary),''),bob_confidence=p_confidence,bob_recommendation=nullif(btrim(p_recommendation),''),smoke_ai_analysis=p_analysis,smoke_ai_analyzed_at=clock_timestamp() where id=v_assessment.id returning * into v_assessment;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_assessment.organization_id,p_actor_user_id,'smoke.photo_classified','smoke_assessments',v_assessment.id,jsonb_build_object('model',p_analysis->>'model','confidence',p_confidence,'manual_review_required',coalesce((p_analysis->>'manual_review_required')::boolean,true),'images_analyzed',(p_analysis->>'images_analyzed')::integer));
  return v_assessment;
end;$function$;
COMMENT ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) IS 'Atomically stores advisory visible-image Smoke analysis and audit. Service identity only; never determines legal breach or action.';
REVOKE ALL ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."finalize_smoke_photo_inference"(p_assessment_id uuid, p_actor_user_id uuid, p_analysis jsonb, p_summary text, p_confidence real, p_recommendation text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb DEFAULT NULL::jsonb, p_appearance_embedding jsonb DEFAULT NULL::jsonb, p_plate text DEFAULT NULL::text, p_exclude_observation_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10)
 RETURNS TABLE(match_kind text, match_id uuid, observation_id uuid, portfolio_key uuid, display_name text, score real, basis text, last_seen_at timestamp with time zone, canonical_place_id uuid, plate_number text, person_record_id uuid, canonical_vehicle_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_face public.vector; v_app public.vector; v_plate text; v_n integer := greatest(coalesce(p_limit, 10), 1);
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin')
     AND (auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id)) THEN
    RAISE EXCEPTION 'CCTV portfolio access denied';
  END IF;
  IF p_entity_kind NOT IN ('person', 'vehicle', 'animal') THEN RAISE EXCEPTION 'Unknown entity kind %', p_entity_kind; END IF;
  v_face := public.cctv_jsonb_to_vector(p_face_embedding, 128);
  v_app := public.cctv_jsonb_to_vector(p_appearance_embedding, 256);
  v_plate := public.normalize_plate_number(p_plate);
  RETURN QUERY
  WITH face_hits AS (
    SELECT 'observation'::text AS match_kind, o.id AS match_id, o.id AS observation_id, o.portfolio_key,
           coalesce(pr.display_name, o.candidate_label)::text AS display_name,
           (1 - (o.face_vec <=> v_face))::real AS score, 'face'::text AS basis, o.observed_at AS last_seen_at,
           o.canonical_place_id, o.candidate_plate::text AS plate_number, o.person_record_id, o.canonical_vehicle_id
    FROM public.cctv_entity_observations o
    LEFT JOIN public.person_records pr ON pr.id = o.person_record_id
    WHERE v_face IS NOT NULL AND p_entity_kind = 'person'
      AND o.organization_id = p_organization_id AND o.entity_kind = 'person' AND o.face_vec IS NOT NULL
      AND o.review_state <> 'rejected' AND (p_exclude_observation_id IS NULL OR o.id <> p_exclude_observation_id)
    ORDER BY o.face_vec <=> v_face
    LIMIT v_n * 3
  ), legacy_face_hits AS (
    SELECT 'person_record'::text, fo.person_record_id, NULL::uuid, NULL::uuid, pr.display_name::text,
           public.face_embedding_cosine(fo.metadata->'embedding', p_face_embedding)::real, 'face_legacy'::text, fo.created_at,
           NULL::uuid, NULL::text, fo.person_record_id, NULL::uuid
    FROM public.face_observations fo
    JOIN public.person_records pr ON pr.id = fo.person_record_id
    WHERE p_face_embedding IS NOT NULL AND p_entity_kind = 'person'
      AND fo.organization_id = p_organization_id AND fo.metadata ? 'embedding'
  ), appearance_hits AS (
    SELECT 'observation'::text, o.id, o.id, o.portfolio_key,
           coalesce(cv.plate_number, pr.display_name, o.candidate_label)::text,
           (1 - (o.appearance_vec <=> v_app))::real, 'appearance'::text, o.observed_at,
           o.canonical_place_id, coalesce(cv.plate_number, o.candidate_plate)::text, o.person_record_id, o.canonical_vehicle_id
    FROM public.cctv_entity_observations o
    LEFT JOIN public.canonical_vehicles cv ON cv.id = o.canonical_vehicle_id
    LEFT JOIN public.person_records pr ON pr.id = o.person_record_id
    WHERE v_app IS NOT NULL
      AND o.organization_id = p_organization_id AND o.entity_kind = p_entity_kind AND o.appearance_vec IS NOT NULL
      AND o.review_state <> 'rejected' AND (p_exclude_observation_id IS NULL OR o.id <> p_exclude_observation_id)
    ORDER BY o.appearance_vec <=> v_app
    LIMIT v_n * 3
  ), plate_hits AS (
    SELECT 'canonical_vehicle'::text, cv.id, NULL::uuid, NULL::uuid,
           concat_ws(' ', cv.plate_number, cv.make, cv.model, cv.colour)::text,
           (CASE WHEN cv.plate_number = v_plate THEN 1.0 ELSE extensions.similarity(cv.plate_number, v_plate) END)::real,
           (CASE WHEN cv.plate_number = v_plate THEN 'plate_exact' ELSE 'plate_similar' END)::text, cv.last_seen_at,
           NULL::uuid, cv.plate_number::text, NULL::uuid, cv.id
    FROM public.canonical_vehicles cv
    WHERE v_plate IS NOT NULL AND p_entity_kind = 'vehicle'
      AND (cv.plate_number = v_plate OR extensions.similarity(cv.plate_number, v_plate) >= 0.6)
    ORDER BY (cv.plate_number = v_plate) DESC, extensions.similarity(cv.plate_number, v_plate) DESC
    LIMIT v_n
  ), all_hits AS (
    SELECT * FROM face_hits UNION ALL SELECT * FROM legacy_face_hits
    UNION ALL SELECT * FROM appearance_hits UNION ALL SELECT * FROM plate_hits
  )
  SELECT h.match_kind, h.match_id, h.observation_id, h.portfolio_key, h.display_name, h.score, h.basis,
         h.last_seen_at, h.canonical_place_id, h.plate_number, h.person_record_id, h.canonical_vehicle_id
  FROM all_hits h
  WHERE h.score >= CASE h.basis WHEN 'face' THEN 0.65 WHEN 'face_legacy' THEN 0.65 WHEN 'appearance' THEN 0.70 ELSE 0.60 END
  ORDER BY h.score DESC, h.last_seen_at DESC NULLS LAST
  LIMIT v_n;
END $function$;
REVOKE ALL ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_cctv_portfolio_matches"(p_organization_id uuid, p_entity_kind text, p_face_embedding jsonb, p_appearance_embedding jsonb, p_plate text, p_exclude_observation_id uuid, p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS TABLE(location_id uuid, name text, address text, suburb text, postcode text, site_count integer, zone_count integer, boundary_state text, match_reason text, belongs_to_account boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_query text := lower(trim(coalesce(p_query, '')));
  v_address_key text := nullif(regexp_replace(lower(trim(coalesce(p_address, ''))), '[^a-z0-9]+', '', 'g'), '');
BEGIN
  SELECT profile.organization_id INTO v_provider FROM public.user_profiles AS profile WHERE profile.id = v_actor AND profile.deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) OR NOT public.crm_actor_can_manage_account(p_account_organization_id) THEN RAISE EXCEPTION 'Active CRM administrator required for this organization'; END IF;
  IF char_length(v_query) < 2 AND coalesce(char_length(v_address_key), 0) < 4 THEN RAISE EXCEPTION 'Enter a location name or complete address to search'; END IF;

  RETURN QUERY
  WITH matches AS (
    SELECT location.id, location.organization_id, location.name, location.address, location.suburb, location.postcode,
      CASE WHEN v_address_key IS NOT NULL AND location.address_match_key = v_address_key THEN 0 WHEN lower(location.name) = v_query THEN 1 ELSE 2 END AS match_rank
    FROM public.locations AS location
    WHERE (v_address_key IS NOT NULL AND location.address_match_key = v_address_key)
       OR (char_length(v_query) >= 2 AND lower(location.name) LIKE '%' || v_query || '%')
  )
  SELECT match.id, match.name, match.address, match.suburb, match.postcode,
    (SELECT count(*)::integer FROM public.client_sites AS site WHERE site.location_id = match.id),
    (SELECT count(*)::integer FROM public.location_zones AS zone WHERE zone.location_id = match.id),
    CASE WHEN EXISTS (SELECT 1 FROM public.client_sites AS site WHERE site.location_id = match.id AND site.boundary_verification = 'verified') OR EXISTS (SELECT 1 FROM public.location_zones AS zone WHERE zone.location_id = match.id AND zone.boundary_verification = 'verified') THEN 'verified geometry available' WHEN EXISTS (SELECT 1 FROM public.client_sites AS site WHERE site.location_id = match.id AND site.boundary IS NOT NULL) OR EXISTS (SELECT 1 FROM public.location_zones AS zone WHERE zone.location_id = match.id AND zone.boundary IS NOT NULL) THEN 'geometry requires review' ELSE 'no geometry recorded' END,
    CASE match.match_rank WHEN 0 THEN 'Exact address match' WHEN 1 THEN 'Exact location name' ELSE 'Similar location name' END,
    match.organization_id = p_account_organization_id
  FROM matches AS match
  ORDER BY match.match_rank, match.name
  LIMIT 20;
END; $function$;
REVOKE ALL ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_location_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text, organization_type text, status text, nzbn text, parent_organization_id uuid, match_reason text, manageable boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_query text := lower(trim(coalesce(p_query, '')));
  v_nzbn text := nullif(regexp_replace(coalesce(p_nzbn, ''), '[^0-9]', '', 'g'), '');
begin
  select profile.organization_id into v_provider from public.user_profiles profile where profile.id = v_actor and profile.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required'; end if;
  if char_length(v_query) < 2 and v_nzbn is null then raise exception 'Enter at least two search characters or an NZBN'; end if;

  return query
  with matches as (
    select organization.*,
      case
        when v_nzbn is not null and regexp_replace(coalesce(organization.nzbn, ''), '[^0-9]', '', 'g') = v_nzbn then 0
        when lower(trim(organization.name)) = v_query then 1
        when lower(organization.name) like '%' || v_query || '%' then 2
        when exists (select 1 from public.client_sites site where site.client_organization_id = organization.id and (lower(site.name) like '%' || v_query || '%' or lower(coalesce(site.address, '')) like '%' || v_query || '%')) then 3
        when exists (select 1 from public.locations location where location.organization_id = organization.id and (lower(location.name) like '%' || v_query || '%' or lower(coalesce(location.address, '')) like '%' || v_query || '%')) then 4
        when extensions.word_similarity(v_query, lower(organization.name)) >= 0.5 then 5
        else 99
      end as match_rank
    from public.organizations organization
  )
  select match.id, match.name, match.organization_type, match.status, match.nzbn, match.parent_organization_id,
    case match.match_rank
      when 0 then 'Exact NZBN'
      when 1 then 'Exact organization name'
      when 2 then 'Name contains search'
      when 3 then 'Matched owned site'
      when 4 then 'Matched owned location'
      else 'Similar organization name'
    end,
    coalesce(match.id = v_provider or match.parent_organization_id = v_provider or public.crm_actor_can_manage_account(match.id), false)
  from matches match
  where match.match_rank < 99
  order by match.match_rank, case when match.match_rank = 5 then extensions.word_similarity(v_query, lower(match.name)) else 1 end desc, match.name
  limit 20;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_organization_candidates"(p_query text, p_nzbn text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text, address text, site_type text, active boolean, boundary_status text, boundary_verification text, match_reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_query text:=lower(trim(coalesce(p_query,'')));v_address_key text:=regexp_replace(lower(trim(coalesce(p_address,''))),'[^a-z0-9]+','','g');
begin
  if v_actor is null or not public.crm_actor_can_manage_account(p_account_organization_id) then raise exception 'Not authorised to review sites for this CRM account';end if;
  if char_length(v_query)<2 and char_length(v_address_key)<4 then raise exception 'Enter at least two name characters or a complete address';end if;
  return query select s.id,s.name,s.address,s.site_type,s.active,s.boundary_status,s.boundary_verification,
    case when char_length(v_address_key)>=4 and s.address_match_key=v_address_key then 'Exact address' when lower(trim(s.name))=v_query then 'Exact name' else 'Similar site' end
  from public.client_sites s
  where s.client_organization_id=p_account_organization_id
    and ((char_length(v_query)>=2 and lower(s.name) like '%'||v_query||'%') or (char_length(v_address_key)>=4 and s.address_match_key=v_address_key))
  order by case when char_length(v_address_key)>=4 and s.address_match_key=v_address_key then 0 when lower(trim(s.name))=v_query then 1 else 2 end,s.name limit 20;
end;$function$;
REVOKE ALL ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_crm_site_candidates"(p_account_organization_id uuid, p_query text, p_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision)
 RETURNS TABLE(site_id uuid, site_name text, address text, client_organization_id uuid, match_reason text, distance_m double precision, has_boundary boolean, boundary_verification text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key text := nullif(regexp_replace(lower(trim(coalesce(p_address, ''))), '[^a-z0-9]+', '', 'g'), '');
  v_point geometry;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access denied';
  END IF;
  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    v_point := ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326);
  END IF;
  RETURN QUERY
  SELECT s.id, s.name, s.address, s.client_organization_id,
    CASE WHEN v_key IS NOT NULL AND s.address_match_key = v_key THEN 'exact_address' ELSE 'within_50m' END,
    CASE WHEN v_point IS NULL OR s.center_point IS NULL THEN NULL
         ELSE ST_Distance(s.center_point::geography, v_point::geography) END,
    s.boundary IS NOT NULL,
    s.boundary_verification
  FROM public.client_sites s
  WHERE public.org_access_allowed(s.client_organization_id)
    AND ((v_key IS NOT NULL AND s.address_match_key = v_key)
      OR (v_point IS NOT NULL AND s.center_point IS NOT NULL
          AND ST_DWithin(s.center_point::geography, v_point::geography, 50)))
  ORDER BY CASE WHEN v_key IS NOT NULL AND s.address_match_key = v_key THEN 0 ELSE 1 END,
           ST_Distance(s.center_point::geography, v_point::geography) NULLS LAST
  LIMIT 5;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."find_existing_site_for_address"(p_organization_id uuid, p_address text, p_lat double precision, p_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date)
 RETURNS TABLE(invoice_id uuid, invoice_number text, client_organization_id uuid, subtotal numeric, gst_amount numeric, total_amount numeric, line_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_agreement public.service_agreements%rowtype; v_invoice public.invoices%rowtype; v_inv_number text; v_count integer:=0; v_qline record; v_comm public.crm_commercial_settings%rowtype;
BEGIN
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id=p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Not authorised to invoice for this agreement'; END IF;
  IF v_agreement.invitation_status <> 'accepted' AND NOT v_agreement.client_portal_finance_enabled THEN
    RAISE EXCEPTION 'Client approval or an active finance-share invite is required before invoicing this agreement';
  END IF;
  IF p_service_period_end < p_service_period_start THEN RAISE EXCEPTION 'Service period end cannot precede service period start'; END IF;
  SELECT 'INV-'||to_char(now(),'YYYYMMDD')||'-'||upper(substring(gen_random_uuid()::text,1,4)) INTO v_inv_number;
  INSERT INTO public.invoices(organization_id,client_organization_id,service_agreement_id,invoice_number,invoice_date,due_date,status,service_period_start,service_period_end,created_by)
  VALUES(v_agreement.provider_organization_id,v_agreement.client_organization_id,v_agreement.id,v_inv_number,current_date,(current_date+interval '14 days')::date,'draft',p_service_period_start,p_service_period_end,v_actor) RETURNING * INTO v_invoice;
  FOR v_qline IN SELECT line.description,line.quantity,line.unit_charge FROM public.quotes quote JOIN public.quote_lines line ON line.quote_id=quote.id WHERE quote.service_agreement_id=v_agreement.id AND quote.status='accepted' LOOP
    v_count:=v_count+1; INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id) VALUES(v_invoice.id,v_count,v_qline.description,v_qline.quantity,v_qline.unit_charge,round(v_qline.quantity*v_qline.unit_charge,2),v_invoice.organization_id);
  END LOOP;
  IF v_count=0 THEN
    SELECT * INTO v_comm FROM public.crm_commercial_settings WHERE service_agreement_id=v_agreement.id;
    IF FOUND AND v_comm.base_rate_per_hour IS NOT NULL AND v_comm.base_rate_per_hour>0 THEN
      v_count:=1; INSERT INTO public.invoice_line_items(invoice_id,line_number,description,quantity,unit_price,line_total,organization_id) VALUES(v_invoice.id,1,'Service Agreement Base Retainer',1,v_comm.base_rate_per_hour,v_comm.base_rate_per_hour,v_invoice.organization_id);
    ELSE RAISE EXCEPTION 'Commercial configuration incomplete: an accepted quote line or positive agreement rate is required before invoicing'; END IF;
  END IF;
  UPDATE public.invoices invoice SET subtotal=totals.subtotal,gst_amount=round(totals.subtotal*.15,2),total_amount=round(totals.subtotal*1.15,2),updated_at=now() FROM (SELECT coalesce(sum(line.line_total),0)::numeric(12,2) subtotal FROM public.invoice_line_items line WHERE line.invoice_id=v_invoice.id) totals WHERE invoice.id=v_invoice.id RETURNING invoice.* INTO v_invoice;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_invoice.organization_id,v_actor,'crm_invoice_generated_from_agreement','invoices',v_invoice.id,jsonb_build_object('service_agreement_id',v_agreement.id,'invoice_number',v_invoice.invoice_number,'subtotal',v_invoice.subtotal,'total_amount',v_invoice.total_amount,'line_item_count',v_count,'client_request_id',p_client_request_id));
  RETURN QUERY SELECT v_invoice.id,v_invoice.invoice_number,v_invoice.client_organization_id,v_invoice.subtotal,v_invoice.gst_amount,v_invoice.total_amount,v_count;
EXCEPTION WHEN OTHERS THEN
  IF v_invoice.id IS NOT NULL THEN DELETE FROM public.invoices WHERE id=v_invoice.id; END IF;
  RAISE;
END; $function$;
REVOKE ALL ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_agreement"(p_client_request_id uuid, p_service_agreement_id uuid, p_service_period_start date, p_service_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid DEFAULT NULL::uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date)
 RETURNS invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_invoice public.invoices%rowtype;
  v_count integer := 0;
  v_row record;
  v_line_id uuid;
  v_start date := coalesce(p_period_start, date '1970-01-01');
  v_end date := coalesce(p_period_end, current_date);
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if p_organization_id is null or p_client_organization_id is null then raise exception 'Organisation and client are required'; end if;
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Finance administrator access required'; end if;
  if v_end < v_start then raise exception 'Period end cannot precede period start'; end if;
  -- Idempotent on the request id via the audit receipt.
  select i.* into v_invoice from public.audit_log a join public.invoices i on i.id = a.target_id
   where a.organization_id = p_organization_id and a.action = 'crm_invoice_generated_from_completed_work' and a.metadata->>'client_request_id' = p_client_request_id::text limit 1;
  if found then return v_invoice; end if;

  insert into public.invoices (organization_id, client_organization_id, service_agreement_id, invoice_number, invoice_date, due_date, status, service_period_start, service_period_end, created_by)
  values (p_organization_id, p_client_organization_id, p_service_agreement_id,
          'INV-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text, 1, 4)),
          current_date, (current_date + interval '14 days')::date, 'draft', p_period_start, p_period_end, v_actor)
  returning * into v_invoice;

  -- Completed workshop work for this client that has not been invoiced yet.
  for v_row in
    select l.id as line_id, wo.order_number, wo.title, l.description, l.quantity, l.unit_price, l.unit_cost, l.line_kind, l.item_id, l.unit_of_measure
      from public.workshop_work_order_lines l join public.workshop_work_orders wo on wo.id = l.work_order_id
     where wo.organization_id = p_organization_id and wo.client_organization_id = p_client_organization_id and wo.status = 'completed'
       and l.invoice_line_item_id is null and wo.completed_at::date between v_start and v_end
       and (p_service_agreement_id is null or wo.service_agreement_id is null or wo.service_agreement_id = p_service_agreement_id)
     order by wo.completed_at, l.position
  loop
    v_count := v_count + 1;
    insert into public.invoice_line_items (invoice_id, line_number, description, quantity, unit_price, line_total, organization_id, finance_item_catalog_id, item_type, unit_of_measure, internal_cost_amount, created_by)
    values (v_invoice.id, v_count, v_row.order_number || ' · ' || v_row.title || ' — ' || v_row.description, v_row.quantity, v_row.unit_price, round(v_row.quantity * v_row.unit_price, 2),
            p_organization_id, v_row.item_id, v_row.line_kind, v_row.unit_of_measure, round(v_row.quantity * v_row.unit_cost, 2), v_actor)
    returning id into v_line_id;
    update public.workshop_work_order_lines set invoice_line_item_id = v_line_id where id = v_row.line_id;
  end loop;

  -- Completed dispatch jobs' charge lines for this client that were never invoiced (invoice_line_item_id had no writer before this migration).
  for v_row in
    select c.id as charge_id, c.source_dispatch_id, c.description, c.quantity, c.unit_rate, c.line_total, c.rate_type, c.created_at
      from public.dispatch_job_charge_lines c
     where c.organization_id = p_organization_id and c.client_organization_id = p_client_organization_id and c.invoice_line_item_id is null
       and c.created_at::date between v_start and v_end
       and (p_service_agreement_id is null or c.service_agreement_id is null or c.service_agreement_id = p_service_agreement_id)
     order by c.created_at
  loop
    v_count := v_count + 1;
    insert into public.invoice_line_items (invoice_id, line_number, description, quantity, unit_price, line_total, organization_id, item_type, source_dispatch_id, created_by)
    values (v_invoice.id, v_count, coalesce(v_row.description, 'Dispatch ' || v_row.rate_type), coalesce(v_row.quantity, 1), coalesce(v_row.unit_rate, v_row.line_total), v_row.line_total,
            p_organization_id, 'other', v_row.source_dispatch_id, v_actor)
    returning id into v_line_id;
    update public.dispatch_job_charge_lines set invoice_line_item_id = v_line_id where id = v_row.charge_id;
  end loop;

  if v_count = 0 then
    delete from public.invoices where id = v_invoice.id;
    raise exception 'No completed, uninvoiced work for this client in the period';
  end if;

  update public.invoices i set subtotal = t.subtotal, gst_amount = round(t.subtotal * 0.15, 2), total_amount = round(t.subtotal * 1.15, 2), updated_at = now()
    from (select coalesce(sum(line_total), 0) as subtotal from public.invoice_line_items where invoice_id = v_invoice.id) t
   where i.id = v_invoice.id returning i.* into v_invoice;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'crm_invoice_generated_from_completed_work', 'invoices', v_invoice.id,
          jsonb_build_object('client_request_id', p_client_request_id, 'client_organization_id', p_client_organization_id, 'lines', v_count, 'total_amount', v_invoice.total_amount,
                             'period_start', p_period_start, 'period_end', p_period_end));
  return v_invoice;
end;
$function$;
COMMENT ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) IS 'Sweep every completed, uninvoiced workshop line and dispatch charge line for one client into a single draft invoice (GST 15%). Stamps invoice_line_item_id on the source lines so nothing is billed twice. Idempotent on client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_crm_invoice_from_completed_work"(p_client_request_id uuid, p_organization_id uuid, p_client_organization_id uuid, p_service_agreement_id uuid, p_period_start date, p_period_end date) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_agreement record;
  v_count integer := 0;
  v_data jsonb;
  v_start_ts timestamptz := p_period_start::timestamptz;
  v_end_ts timestamptz := (p_period_end::timestamptz + interval '1 day');
  v_sla_met integer;
  v_sla_breached integer;
  v_sla_running integer;
  v_inc_total integer;
  v_inc_by_sev jsonb;
  v_checkpoints integer;
  v_breaches integer;
  v_facilities jsonb;
BEGIN
  IF p_period_start IS NULL OR p_period_end IS NULL OR p_period_start > p_period_end OR p_period_end - p_period_start > 366 THEN
    RAISE EXCEPTION 'Select a valid report period of 366 days or less';
  END IF;

  SELECT organization_id INTO v_provider
  FROM public.user_profiles
  WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_provider IS NULL OR NOT public.is_admin_for_org(v_provider) THEN
    RAISE EXCEPTION 'Active provider administrator required';
  END IF;

  FOR v_agreement IN
    SELECT id, provider_organization_id, monthly_report_template_code
    FROM public.service_agreements
    WHERE provider_organization_id = v_provider
      AND monthly_report_template_code IS NOT NULL
  LOOP
    SELECT count(*) FILTER (WHERE status = 'met'), count(*) FILTER (WHERE status = 'breached'), count(*) FILTER (WHERE status = 'running')
    INTO v_sla_met, v_sla_breached, v_sla_running
    FROM public.sla_clocks
    WHERE service_agreement_id = v_agreement.id
      AND started_at >= v_start_ts AND started_at < v_end_ts;

    SELECT count(*), coalesce(jsonb_object_agg(severity, n), '{}'::jsonb)
    INTO v_inc_total, v_inc_by_sev
    FROM (
      SELECT severity, count(*) AS n
      FROM public.incidents
      WHERE organization_id = v_agreement.provider_organization_id
        AND occurred_at >= v_start_ts AND occurred_at < v_end_ts
      GROUP BY severity
    ) s;

    SELECT count(*) INTO v_checkpoints
    FROM public.patrol_checkpoint_visits
    WHERE organization_id = v_agreement.provider_organization_id
      AND visited_at >= v_start_ts AND visited_at < v_end_ts;

    SELECT count(*) INTO v_breaches
    FROM public.breach_alerts
    WHERE organization_id = v_agreement.provider_organization_id
      AND created_at >= v_start_ts AND created_at < v_end_ts;

    SELECT coalesce(jsonb_agg(jsonb_build_object('siteName', site_name, 'expected', expected, 'completed', completed) ORDER BY site_name), '[]'::jsonb)
    INTO v_facilities
    FROM (
      SELECT coalesce(cs.name, 'Unknown site') AS site_name,
             count(*) AS expected,
             count(*) FILTER (WHERE ss.status = 'completed') AS completed
      FROM public.shift_stops ss
      LEFT JOIN public.client_sites cs ON cs.id = ss.site_id
      WHERE ss.organization_id = v_agreement.provider_organization_id
        AND ss.sla_arrive_by >= v_start_ts AND ss.sla_arrive_by < v_end_ts
      GROUP BY coalesce(cs.name, 'Unknown site')
    ) f;

    v_data := jsonb_build_object(
      'slaMet', coalesce(v_sla_met, 0),
      'slaBreached', coalesce(v_sla_breached, 0),
      'slaRunning', coalesce(v_sla_running, 0),
      'incidentsTotal', coalesce(v_inc_total, 0),
      'incidentsBySeverity', coalesce(v_inc_by_sev, '{}'::jsonb),
      'checkpointVisits', coalesce(v_checkpoints, 0),
      'breachAlerts', coalesce(v_breaches, 0),
      'facilities', coalesce(v_facilities, '[]'::jsonb)
    );

    INSERT INTO public.monthly_report_packs (
      organization_id, service_agreement_id, template_code, period_start,
      period_end, status, data, generated_at, generated_by, updated_at
    ) VALUES (
      v_agreement.provider_organization_id, v_agreement.id,
      v_agreement.monthly_report_template_code, p_period_start, p_period_end,
      'generated', v_data, now(), v_actor, now()
    )
    ON CONFLICT (service_agreement_id, template_code, period_start)
    DO UPDATE SET
      data = excluded.data,
      status = CASE WHEN monthly_report_packs.status = 'sent' THEN 'sent' ELSE 'generated' END,
      generated_at = now(), generated_by = v_actor, updated_at = now();

    v_count := v_count + 1;
  END LOOP;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, metadata)
  VALUES (v_provider, v_actor, 'monthly_report_packs_generated', 'monthly_report_packs', jsonb_build_object('period_start', p_period_start, 'period_end', p_period_end, 'pack_count', v_count));
  RETURN v_count;
END;
$function$;
COMMENT ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) IS 'Assembles + upserts monthly_report_packs for every agreement with a template code over the given period. Mirrors the client-side assembler so generation can be scheduled (pg_cron). Does not re-downgrade an already-sent pack.';
REVOKE ALL ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."generate_due_report_packs"(p_period_start date, p_period_end date) TO "service_role";

