CREATE OR REPLACE FUNCTION "public"."get_officer_data_package"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_zones jsonb;
  v_matrix jsonb;
  v_flags jsonb;
  v_rules jsonb;
  v_stops jsonb;
  v_welfare jsonb;
  v_package jsonb;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active officer profile required for data package download'; end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  -- 1. Active location zones (address is the house address)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', z.id,
    'location_id', z.location_id,
    'name', z.name,
    'address', l.address,
    'zone_type', z.zone_type,
    'module_key', z.module_key,
    'rule_type', z.rule_type,
    'is_active', z.is_active
  )), '[]'::jsonb) into v_zones
  from public.location_zones z
  left join public.locations l on l.id = z.location_id
  where z.organization_id = v_org_id and z.is_active = true;

  -- 2. Current zone compliance matrix
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'zone_id', m.zone_id,
    'max_consecutive_nights', m.max_consecutive_nights,
    'max_nights_per_month', m.max_nights_per_month,
    'scv_required', m.scv_required,
    'is_current', m.is_current
  )), '[]'::jsonb) into v_matrix
  from public.zone_compliance_matrix m
  where m.organization_id = v_org_id and m.is_current = true;

  -- 3. Active entity flags (vehicle/person)
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', f.id,
    'entity_type', f.entity_type,
    'entity_id', f.entity_id,
    'plate_number', cv.plate_number,
    'flag_type', f.flag_type,
    'flag_reason', f.reason,
    'severity', f.alert_level,
    'is_active', f.active
  )), '[]'::jsonb) into v_flags
  from public.entity_flags f
  left join public.canonical_vehicles cv on f.entity_type = 'vehicle' and cv.id = f.entity_id
  where f.organization_id = v_org_id and f.active = true;

  -- 4. Module rule sets
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'module_key', r.module_key,
    'name', r.name,
    'evidence_requirements', r.evidence_requirements,
    'approval_policy', r.approval_policy
  )), '[]'::jsonb) into v_rules
  from public.module_rule_sets r
  where r.organization_id = v_org_id;

  -- 5. Patrol stops for current shift if supplied
  if p_shift_id is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', st.id,
      'site_id', st.site_id,
      'zone_id', st.zone_id,
      'status', st.status,
      'sla_respond_by', st.sla_arrive_by,
      'sla_depart_by', st.sla_depart_by,
      'notes', st.officer_notes,
      'officer_instructions', st.officer_instructions
    )), '[]'::jsonb) into v_stops
    from public.shift_stops st
    where st.shift_id = p_shift_id and st.organization_id = v_org_id;
  else
    v_stops := '[]'::jsonb;
  end if;

  -- 6. Welfare settings
  select to_jsonb(w.*) into v_welfare
  from public.officer_welfare_settings w
  where w.organization_id = v_org_id limit 1;

  v_package := jsonb_build_object(
    'package_timestamp', clock_timestamp(),
    'organization_id', v_org_id,
    'officer_id', v_user_id,
    'shift_id', p_shift_id,
    'location_zones', v_zones,
    'zone_compliance_matrix', v_matrix,
    'entity_flags', v_flags,
    'module_rule_sets', v_rules,
    'shift_stops', v_stops,
    'welfare_settings', coalesce(v_welfare, '{}'::jsonb)
  );

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'officer_data_package_downloaded', 'user_profiles', v_user_id,
    jsonb_build_object('shift_id', p_shift_id, 'zone_count', jsonb_array_length(v_zones), 'flag_count', jsonb_array_length(v_flags))
  );

  return v_package;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_data_package"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_shift_id is not null then
    select * into v_shift from public.shifts where id = p_shift_id and officer_user_id = v_actor;
  else
    select * into v_shift from public.shifts
    where officer_user_id = v_actor and status in ('in_progress', 'accepted')
    order by case status when 'in_progress' then 0 else 1 end, scheduled_start desc limit 1;
  end if;
  if not found then return null; end if;

  return jsonb_build_object(
    'shift', jsonb_build_object('id', v_shift.id, 'status', v_shift.status, 'scheduled_start', v_shift.scheduled_start, 'scheduled_end', v_shift.scheduled_end,
      'route_name', (select r.name from public.patrol_routes r where r.id = v_shift.patrol_route_id)),
    'stops', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', st.id, 'stop_order', st.stop_order, 'visit_number', st.visit_number,
        'visits_total', (select count(*) from public.shift_stops v where v.shift_id = st.shift_id and v.patrol_config_id is not distinct from st.patrol_config_id and v.site_id is not distinct from st.site_id and v.zone_id is not distinct from st.zone_id and v.is_adhoc = false),
        'status', st.status, 'sla_status', st.sla_status,
        'sla_window_open', st.sla_window_open, 'sla_arrive_by', st.sla_arrive_by, 'sla_depart_by', st.sla_depart_by,
        'required_dwell_minutes', st.required_dwell_minutes, 'officer_instructions', st.officer_instructions,
        'actual_arrived_at', st.actual_arrived_at, 'actual_departed_at', st.actual_departed_at,
        'arrival_verification', st.arrival_verification, 'arrival_distance_m', st.arrival_distance_m, 'officer_notes', st.officer_notes,
        'module_key', st.module_key,
        'place', case
          when st.site_id is not null then (select jsonb_build_object('kind', 'site', 'name', cs.name, 'address', cs.address, 'access_instructions', cs.access_instructions, 'hs_notes', cs.hs_notes) from public.client_sites cs where cs.id = st.site_id)
          when st.zone_id is not null then (select jsonb_build_object('kind', 'zone', 'name', lz.name, 'address', null, 'access_instructions', null, 'hs_notes', null) from public.location_zones lz where lz.id = st.zone_id)
          else jsonb_build_object('kind', 'unknown', 'name', 'Contracted place', 'address', null, 'access_instructions', null, 'hs_notes', null) end
      ) order by st.stop_order, st.visit_number)
      from public.shift_stops st
      where st.shift_id = v_shift.id and st.is_adhoc = false and st.module_key <> 'static_guarding'
    ), '[]'::jsonb)
  );
end;
$function$;
COMMENT ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) IS 'Officer-scoped read of the contracted (non-adhoc, non-static) shift stops for one of the caller''s shifts, with place brief, timing window, instructions, and attendance evidence. Returns null when the caller has no such shift.';
REVOKE ALL ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_patrol_stops"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_static_post"(p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_shift public.shifts%rowtype;
  v_stop public.shift_stops%rowtype;
  v_module public.shift_stop_modules%rowtype;
  v_site public.client_sites%rowtype;
  v_zone public.location_zones%rowtype;
  v_arrival_receipt jsonb;
  v_departure_receipt jsonb;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select s.* into v_shift from public.shifts s
  where s.officer_user_id=v_actor and s.service_type='static_guarding'
    and s.status in('accepted','in_progress') and (p_shift_id is null or s.id=p_shift_id)
  order by
    case
      when s.status='in_progress' then 0
      when now() between s.scheduled_start and s.scheduled_end then 1
      when s.scheduled_start>now() then 2
      else 3
    end,
    case when s.scheduled_start>now() then s.scheduled_start end,
    s.scheduled_start desc
  limit 1;
  if not found then return null;end if;

  select st.* into v_stop from public.shift_stops st
  where st.shift_id=v_shift.id and st.module_key='static_guarding'
  order by st.stop_order limit 1;
  if not found then raise exception 'Static guarding stop is missing';end if;
  select sm.* into v_module from public.shift_stop_modules sm
  where sm.shift_stop_id=v_stop.id and sm.module_key='static_guarding' and sm.is_required
  order by sm.created_at limit 1;
  if not found then raise exception 'Static guarding module task is missing';end if;
  if not exists(select 1 from public.service_agreement_modules sam join public.service_agreement_locations sal on sal.service_agreement_id=sam.service_agreement_id where sam.id=v_module.service_agreement_module_id and sal.id=v_module.service_agreement_location_id and sam.module_key='static_guarding' and sam.enabled and sal.status='active') then raise exception 'Static guarding contract is no longer active';end if;

  if v_stop.site_id is not null then select cs.* into v_site from public.client_sites cs where cs.id=v_stop.site_id and cs.active;end if;
  if v_stop.zone_id is not null then select z.* into v_zone from public.location_zones z where z.id=v_stop.zone_id;end if;
  select a.receipt into v_arrival_receipt from public.shift_stop_actions a where a.shift_stop_id=v_stop.id and a.action_type='static_post_arrived' order by a.performed_at desc limit 1;
  select a.receipt into v_departure_receipt from public.shift_stop_actions a where a.shift_stop_id=v_stop.id and a.action_type='static_post_departed' order by a.performed_at desc limit 1;

  return jsonb_build_object(
    'shift',jsonb_build_object('id',v_shift.id,'status',v_shift.status,'scheduled_start',v_shift.scheduled_start,'scheduled_end',v_shift.scheduled_end,'notes',v_shift.notes),
    'stop',jsonb_build_object('id',v_stop.id,'status',v_stop.status,'sla_arrive_by',v_stop.sla_arrive_by,'actual_arrived_at',v_stop.actual_arrived_at,'actual_departed_at',v_stop.actual_departed_at,'officer_notes',v_stop.officer_notes),
    'module',jsonb_build_object('id',v_module.id,'status',v_module.status,'started_at',v_module.started_at,'completed_at',v_module.completed_at),
    'place',jsonb_build_object('id',coalesce(v_site.id,v_zone.id),'name',coalesce(v_site.name,v_zone.name),'address',v_site.address,'risk_level',v_site.risk_level,'site_brief',v_site.site_brief,'access_instructions',v_site.access_instructions,'hs_notes',v_site.hs_notes),
    'attendance_evidence',jsonb_build_object('arrival',v_arrival_receipt,'departure',v_departure_receipt)
  );
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_static_post"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date)
 RETURNS TABLE(source_type text, source_id uuid, work_status text, started_at timestamp with time zone, ended_at timestamp with time zone, calculated_minutes integer, label text, metadata jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_period_start timestamptz := p_period_start::timestamptz;
  v_period_end timestamptz := (p_period_end + 1)::timestamptz;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_period_start is null or p_period_end is null or p_period_start > p_period_end then raise exception 'Invalid timesheet period'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active staff profile required'; end if;

  return query
  with shift_work(source_type, id, work_status, started_at, ended_at, label, metadata) as (
    select 'shift'::text, s.id, 'completed'::text,
      greatest(s.actual_start, v_period_start), least(s.actual_end, v_period_end),
      coalesce(s.service_type, 'shift'),
      jsonb_build_object('shift_id', s.id, 'service_type', s.service_type, 'status', s.status, 'scheduled_start', s.scheduled_start, 'scheduled_end', s.scheduled_end, 'actual_start', s.actual_start, 'actual_end', s.actual_end)
    from public.shifts s
    where s.organization_id = v_org_id and s.officer_user_id = v_user_id
      and s.status = 'completed' and s.actual_start is not null and s.actual_end is not null
      and s.actual_end > v_period_start and s.actual_start < v_period_end
  ), job_work(source_type, id, work_status, started_at, ended_at, label, metadata) as (
    select 'dispatch_job'::text, d.id, 'completed'::text,
      greatest(coalesce(d.on_scene_at, d.en_route_at, d.acknowledged_at, d.dispatched_at, d.created_at), v_period_start),
      least(d.completed_at, v_period_end), coalesce(d.job_type, 'Dispatch job'),
      jsonb_build_object('dispatch_job_id', d.id, 'job_type', d.job_type, 'status', d.status, 'shift_id', d.shift_id, 'shift_stop_id', d.shift_stop_id, 'dispatched_at', d.dispatched_at, 'on_scene_at', d.on_scene_at, 'completed_at', d.completed_at)
    from public.dispatch_jobs d
    left join public.shifts s on s.id = d.shift_id and s.officer_user_id = v_user_id
    where d.organization_id = v_org_id
      and (s.id is not null or d.dispatch_resource_id in (select dr.id from public.dispatch_resources dr where dr.assigned_officer_id = v_user_id))
      and d.status = 'completed' and d.completed_at is not null and d.shift_id is null
      and d.completed_at > v_period_start
      and coalesce(d.on_scene_at, d.en_route_at, d.acknowledged_at, d.dispatched_at, d.created_at) < v_period_end
  ), sources as (
    select * from shift_work union all select * from job_work
  ), bounded as (
    select *, greatest(0, floor(extract(epoch from (ended_at - started_at)) / 60))::integer as minutes
    from sources where ended_at > started_at
  )
  select source_type, id, work_status, started_at, ended_at, minutes, label,
    metadata || jsonb_build_object('calculated_minutes', minutes)
  from bounded order by started_at, source_type, id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_officer_timesheet_work"(p_period_start date, p_period_end date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_open_jobs"(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(source text, job_id uuid, organization_id uuid, status text, priority text, title text, starts_at timestamp with time zone, created_at timestamp with time zone, payload jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with jobs as (
    select
      'dispatch'::text as source,
      dj.id as job_id,
      dj.organization_id,
      dj.status::text as status,
      dj.priority::text as priority,
      coalesce(dj.job_type, 'dispatch job')::text as title,
      coalesce(dj.dispatched_at, dj.created_at) as starts_at,
      dj.created_at,
      jsonb_build_object(
        'client_site_id', dj.client_site_id,
        'shift_id', dj.shift_id,
        'dispatch_resource_id', dj.dispatch_resource_id,
        'sla_respond_by', dj.sla_respond_by
      ) as payload
    from public.dispatch_jobs dj
    where dj.status in ('pending', 'dispatched', 'en_route', 'on_scene')
      and public.org_access_allowed(dj.organization_id)

    union all

    select
      'shift_coverage'::text as source,
      scr.id as job_id,
      scr.organization_id,
      scr.status::text as status,
      scr.urgency::text as priority,
      'open shift coverage'::text as title,
      (scr.shift_date::timestamp + scr.start_time) at time zone 'UTC' as starts_at,
      scr.created_at,
      jsonb_build_object(
        'site_id', scr.site_id,
        'patrol_route_id', scr.patrol_route_id,
        'required_staff_count', scr.required_staff_count,
        'required_credentials', scr.required_credentials
      ) as payload
    from public.shift_coverage_requests scr
    where scr.status = 'open'
      and public.org_access_allowed(scr.organization_id)
  )
  select
    j.source,
    j.job_id,
    j.organization_id,
    j.status,
    j.priority,
    j.title,
    j.starts_at,
    j.created_at,
    j.payload
  from jobs j
  order by j.created_at desc
  limit greatest(coalesce(p_limit, 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$function$;
REVOKE ALL ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_open_jobs"(p_limit integer, p_offset integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid)
 RETURNS TABLE(user_id uuid, staff_id uuid, display_name text, email text, employment_type text, work_ready boolean, credential_expiry date, credential_verified boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR NOT public.user_can_operate_organization(p_operating_organization_id) THEN
    RAISE EXCEPTION 'Active authorized operating branch required';
  END IF;
  IF NOT public.is_admin_for_org(p_operating_organization_id)
     AND NOT EXISTS(
       SELECT 1 FROM public.staff_branch_authorisations manager_assignment
       WHERE manager_assignment.user_id = v_actor
         AND manager_assignment.branch_org_id = p_operating_organization_id
         AND manager_assignment.status = 'active'
         AND manager_assignment.role_at_branch = 'branch_manager'
     )
     AND NOT EXISTS(
       SELECT 1 FROM public.resolve_access_grants(v_actor,p_operating_organization_id) authority_grant
       WHERE authority_grant.area = 'roster_impact_approve'
         AND authority_grant.level IN ('approve','adjust','manage')
     ) THEN
    RAISE EXCEPTION 'Branch roster authority required';
  END IF;

  RETURN QUERY
  SELECT user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready,min(credential.expiry_date),bool_and(credential.verified)
  FROM public.staff_branch_authorisations assignment
  JOIN public.user_profiles user_profile ON user_profile.id=assignment.user_id AND user_profile.deactivated_at IS NULL
  JOIN public.staff_profiles staff ON staff.id=coalesce(user_profile.id,staff.user_id) OR staff.user_id=user_profile.id
  LEFT JOIN public.staff_credentials credential ON credential.staff_id=staff.id
  WHERE assignment.branch_org_id=p_operating_organization_id
    AND assignment.status='active'
    AND assignment.can_be_rostered
    AND (assignment.ends_on IS NULL OR assignment.ends_on>=current_date)
    AND (assignment.starts_on IS NULL OR assignment.starts_on<=current_date)
  GROUP BY user_profile.id,staff.id,user_profile.display_name,user_profile.email,staff.employment_type,staff.work_ready
  ORDER BY user_profile.display_name NULLS LAST,user_profile.email;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_operating_branch_roster_staff"(p_operating_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_operating_organization_contexts"()
 RETURNS TABLE(organization_id uuid, organization_name text, authority_basis text, role_at_branch text, module_access text[], can_be_rostered boolean, is_default boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with actor as (
    select organization_id, employer_organization_id, role
    from public.user_profiles
    where id = auth.uid() and deactivated_at is null
  ), candidates as (
    -- The provider organisation itself, for its administrators.
    select
      home.id as organization_id,
      home.name as organization_name,
      'organisation_home'::text as authority_basis,
      null::text as role_at_branch,
      array[]::text[] as module_access,
      false as can_be_rostered,
      0 as authority_rank
    from actor
    join public.organizations home
      on home.id = actor.organization_id
     and home.organization_type in ('owner', 'service_provider')
     and home.active
    where actor.role in ('grand_master', 'master', 'admin')

    union all

    select
      branch.id as organization_id,
      branch.name as organization_name,
      'branch_authorisation'::text as authority_basis,
      authorisation.role_at_branch,
      authorisation.module_access,
      authorisation.can_be_rostered,
      1 as authority_rank
    from actor
    join public.staff_branch_authorisations authorisation
      on authorisation.user_id = auth.uid() and authorisation.status = 'active'
    join public.organizations branch
      on branch.id = authorisation.branch_org_id
     and branch.organization_type = 'branch'
     and branch.active

    union all

    select
      branch.id,
      branch.name,
      'corporate_oversight'::text,
      null::text,
      array[]::text[],
      false,
      2
    from actor
    join public.organizations branch
      on branch.organization_type = 'branch'
     and branch.active
     and branch.id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
    where actor.role in ('grand_master', 'master', 'admin')
  ), ranked as (
    select distinct on (organization_id)
      organization_id, organization_name, authority_basis, role_at_branch,
      module_access, can_be_rostered
    from candidates
    order by organization_id, authority_rank
  )
  select
    ranked.organization_id,
    ranked.organization_name,
    ranked.authority_basis,
    ranked.role_at_branch,
    ranked.module_access,
    ranked.can_be_rostered,
    ranked.organization_id = actor.organization_id as is_default
  from ranked
  cross join actor
  order by (ranked.organization_id = actor.organization_id) desc, ranked.organization_name;
$function$;
COMMENT ON FUNCTION "public"."get_operating_organization_contexts"() IS 'Operating contexts for the caller: their own provider organisation (organisation_home, for grand_master/master/admin), branches they are authorised at (branch_authorisation), and branches in their organisation tree (corporate_oversight). Ranked so an explicit authorisation wins over oversight; the home organisation is the default.';
REVOKE ALL ON FUNCTION "public"."get_operating_organization_contexts"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_operating_organization_contexts"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text DEFAULT NULL::text, p_default integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT COALESCE(
    -- Try zone-type-specific override first
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type = p_zone_type
     LIMIT 1),
    -- Then org-wide (zone_type IS NULL)
    (SELECT config_value FROM public.org_geofence_config
     WHERE organization_id = p_org_id
       AND config_key = p_config_key
       AND zone_type IS NULL
     LIMIT 1),
    -- Platform default
    p_default
  );
$function$;
COMMENT ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) IS 'Reads an org geofence config value with zone-type-specific override -> org-wide -> platform default fallback. Platform defaults: site_provisional_radius_m=50, zone_provisional_radius_m=100, checkpoint_radius_m=5.';
REVOKE ALL ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_org_geofence_config"(p_org_id uuid, p_config_key text, p_zone_type text, p_default integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  WITH pt AS (
    SELECT ST_SetSRID(ST_Point(p_lng, p_lat), 4326) AS geom
  ),
  -- All orgs whose VERIFIED jurisdiction contains the point
  containing_orgs AS (
    SELECT o.id, o.name
    FROM public.organizations o, pt
    WHERE o.jurisdiction_geom IS NOT NULL
      AND o.jurisdiction_verification = 'verified'
      AND ST_Contains(o.jurisdiction_geom, pt.geom)
  ),
  -- Sites whose boundary contains the point (for ownership + agreement lookups)
  containing_sites AS (
    SELECT cs.id AS site_id, cs.client_organization_id
    FROM public.client_sites cs, pt
    WHERE cs.boundary IS NOT NULL
      AND cs.boundary_verification = 'verified'
      AND ST_IsValid(cs.boundary)
      AND NOT ST_IsEmpty(cs.boundary)
      AND ST_Contains(cs.boundary, pt.geom)
  ),
  -- Zones whose boundary contains the point (for agreement lookups)
  containing_zones AS (
    SELECT lz.id AS zone_id, lz.organization_id
    FROM public.location_zones lz, pt
    WHERE lz.boundary IS NOT NULL
      AND lz.boundary_verification = 'verified'
      AND ST_IsValid(lz.boundary)
      AND NOT ST_IsEmpty(lz.boundary)
      AND ST_Contains(lz.boundary, pt.geom)
  ),
  -- (a) Agreement-based standing: org has an active service_agreement
  --     covering the module at a site/zone containing the point.
  agreement_standing AS (
    SELECT DISTINCT sa.client_organization_id AS org_id
    FROM public.service_agreements sa
    JOIN public.service_agreement_locations sal
      ON sal.service_agreement_id = sa.id
      AND sal.status = 'active'
    LEFT JOIN public.service_agreement_modules sam
      ON sam.service_agreement_id = sa.id
      AND sam.enabled = true
    WHERE (sa.ends_on IS NULL OR sa.ends_on >= current_date)
      AND (
        -- Location match: site or zone containing the point
        (sal.site_id IS NOT NULL AND sal.site_id IN (SELECT site_id FROM containing_sites))
        OR
        (sal.zone_id IS NOT NULL AND sal.zone_id IN (SELECT zone_id FROM containing_zones))
      )
      AND (
        -- Module match: when p_module_key provided, require module enabled
        p_module_key IS NULL
        OR sam.module_key = p_module_key
      )
  ),
  -- (b) Self-request standing: org OWNS the site AND module is enabled
  --     at the site via site_services.
  ownership_standing AS (
    SELECT DISTINCT cs.client_organization_id AS org_id
    FROM containing_sites cs
    WHERE (
      p_module_key IS NULL
      OR EXISTS (
        SELECT 1 FROM public.site_services ss
        WHERE ss.site_id = cs.site_id
          AND ss.organization_id = cs.client_organization_id
          AND ss.module_key = p_module_key
          AND ss.enabled = true
      )
    )
  ),
  -- Union of all orgs with standing
  standing_orgs AS (
    SELECT org_id FROM agreement_standing
    UNION
    SELECT org_id FROM ownership_standing
  )
  SELECT co.id, co.name
  FROM containing_orgs co
  WHERE (
    -- When module_key is provided, only return orgs with standing
    p_module_key IS NULL
    OR co.id IN (SELECT org_id FROM standing_orgs)
  )
  ORDER BY
    -- Standing-bearing orgs sort first even when p_module_key is NULL
    (CASE WHEN co.id IN (SELECT org_id FROM standing_orgs) THEN 0 ELSE 1 END),
    co.name;
$function$;
COMMENT ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) IS 'Role-aware requester picklist (0290). Returns orgs whose verified jurisdiction contains the point. When p_module_key is provided, filters to orgs with requester standing for that module (active agreement or site ownership + site_services). When omitted, backward-compatible but standing-bearing orgs sort first. Replaces geometry-only 0286.';
REVOKE ALL ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_orgs_by_jurisdiction_point"(p_lng double precision, p_lat double precision, p_module_key text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer DEFAULT 15, p_from timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_to timestamp with time zone DEFAULT (now() + '24:00:00'::interval))
 RETURNS TABLE(shift_id uuid, officer_user_id uuid, service_type text, scheduled_start timestamp with time zone, scheduled_end timestamp with time zone, status text, exception_type text, minutes_overdue integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Roster administrator required'; end if;
  if p_grace_minutes < 0 or p_grace_minutes > 240 then raise exception 'Grace period is outside the accepted range'; end if;
  return query
  select s.id, s.officer_user_id, s.service_type, s.scheduled_start, s.scheduled_end, s.status,
    case when s.status in ('scheduled', 'published', 'accepted') and s.scheduled_start + make_interval(mins => p_grace_minutes) < clock_timestamp() then 'late_start' else 'active_overrun' end,
    case when s.status in ('scheduled', 'published', 'accepted') then greatest(0, floor(extract(epoch from (clock_timestamp() - (s.scheduled_start + make_interval(mins => p_grace_minutes)))) / 60)::integer) else greatest(0, floor(extract(epoch from (clock_timestamp() - s.scheduled_end)) / 60)::integer) end
  from public.shifts s
  where s.organization_id = p_organization_id
    and s.scheduled_start >= p_from and s.scheduled_start <= p_to
    and ((s.status in ('scheduled', 'published', 'accepted') and s.scheduled_start + make_interval(mins => p_grace_minutes) < clock_timestamp() and s.actual_start is null)
      or (s.status = 'in_progress' and s.scheduled_end < clock_timestamp()))
  order by s.scheduled_start;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_attendance_exceptions"(p_organization_id uuid, p_grace_minutes integer, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid)
 RETURNS TABLE(slot_id uuid, reason text, work_unit_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select target_id, metadata->>'error', (metadata->>'work_unit_id')::uuid
  from public.audit_log
  where action = 'roster_batch_publish_materialization_failed'
    and metadata->>'client_request_id' = p_client_request_id::text
  order by created_at;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_batch_publish_failures"(p_client_request_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(slot_id uuid, pay_status text, billing_status text, quote_status text, geofence_status text, cost_centre_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to view roster commercial readiness';end if;
  if p_from is null or p_to is null or p_from>=p_to or p_to-p_from>interval '62 days' then raise exception 'Readiness window must be between 1 and 62 days';end if;
  return query
  select s.id,
    case when exists(select 1 from public.rate_rules r where r.organization_id=s.organization_id and r.rule_kind='pay' and r.active and (r.service_type is null or r.service_type=u.service_type) and (r.effective_from is null or r.effective_from<=s.scheduled_start::date) and (r.effective_to is null or r.effective_to>=s.scheduled_start::date)) then 'ready' else 'missing_rule' end,
    case
      when u.work_unit_type='internal' then 'not_applicable'
      when u.work_unit_type='static' and not exists(select 1 from public.service_agreement_locations l join public.service_agreements a on a.id=l.service_agreement_id join public.service_agreement_modules m on m.id=u.service_agreement_module_id and m.service_agreement_id=a.id and m.enabled where l.id=u.service_agreement_location_id and l.status='active' and a.agreement_type='operational' and (a.starts_on is null or a.starts_on<=s.scheduled_start::date) and (a.ends_on is null or a.ends_on>=s.scheduled_start::date)) then 'missing_contract'
      when u.work_unit_type='static' and public.roster_agreement_billing_ready((select l.service_agreement_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.site_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.zone_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id)) then 'ready'
      when u.work_unit_type='static' then 'missing_rate'
      when s.linked_shift_id is null then 'pending_materialization'
      when not exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required where st.shift_id=s.linked_shift_id) or exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required where st.shift_id=s.linked_shift_id and (sm.service_agreement_location_id is null or sm.service_agreement_module_id is null)) then 'missing_attribution'
      when exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required join public.service_agreement_locations l on l.id=sm.service_agreement_location_id where st.shift_id=s.linked_shift_id and not public.roster_agreement_billing_ready(l.service_agreement_id,l.site_id,l.zone_id)) then 'missing_rate'
      else 'ready' end,
    case
      when u.work_unit_type='internal' then 'not_applicable'
      when u.work_unit_type='static' and exists(select 1 from public.service_agreement_locations l join public.quotes q on q.service_agreement_id=l.service_agreement_id and q.status='accepted' where l.id=u.service_agreement_location_id) then 'accepted'
      when u.work_unit_type='static' then 'missing'
      when s.linked_shift_id is null then 'pending_materialization'
      when exists(select 1 from public.shift_stops st join public.shift_stop_modules sm on sm.shift_stop_id=st.id and sm.is_required left join public.service_agreement_locations l on l.id=sm.service_agreement_location_id left join public.quotes q on q.service_agreement_id=l.service_agreement_id and q.status='accepted' where st.shift_id=s.linked_shift_id and q.id is null) then 'missing'
      else 'accepted' end,
    case
      when u.work_unit_type='internal' then 'not_applicable'
      when u.work_unit_type='static' then public.roster_place_geofence_state((select l.site_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id),(select l.zone_id from public.service_agreement_locations l where l.id=u.service_agreement_location_id))
      when s.linked_shift_id is null then 'pending_materialization'
      when not exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id) then 'pending_materialization'
      when exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id and public.roster_place_geofence_state(st.site_id,st.zone_id)='missing') then 'missing'
      when not exists(select 1 from public.shift_stops st where st.shift_id=s.linked_shift_id and public.roster_place_geofence_state(st.site_id,st.zone_id)<>'verified') then 'verified'
      else 'mapped_unverified' end,
    case when u.work_unit_type<>'internal' then 'not_applicable' when u.cost_centre_id is not null then 'ready' else 'missing' end
  from public.roster_slots s join public.roster_work_units u on u.id=s.work_unit_id
  where s.organization_id=p_organization_id and s.scheduled_start<p_to and s.scheduled_end>p_from and s.status<>'cancelled';
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_commercial_readiness"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(slot_id uuid, work_unit_name text, staff_id uuid, scheduled_hours numeric, pay_rate numeric, charge_rate numeric, pay_cost numeric, billable numeric, margin numeric, rate_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to view labour cost for this organization'; end if;
  return query
  select s.id, work_unit.name, s.staff_id,
    round(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    pay.amount, bill.amount,
    round(coalesce(pay.amount, 0) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    round(coalesce(bill.amount, 0) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    round((coalesce(bill.amount, 0) - coalesce(pay.amount, 0)) * extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0, 2),
    case when pay.amount is null and bill.amount is null then 'no_rules' when pay.amount is null then 'no_pay_rule' when bill.amount is null then 'no_billing_rule' else 'resolved' end
  from public.roster_slots s
  join public.roster_work_units work_unit on work_unit.id = s.work_unit_id
  left join public.staff_profiles staff on staff.id = s.staff_id
  left join lateral public.resolve_rate_rule(p_organization_id, 'pay', s.scheduled_start, work_unit.service_type, null, null, null, null, null, staff.role_code, null, null, 'hourly') pay on true
  left join lateral public.resolve_rate_rule(p_organization_id, 'billing', s.scheduled_start, work_unit.service_type, null, null, null, null, null, staff.role_code, null, null, 'hourly') bill on true
  where s.organization_id = p_organization_id and s.status not in ('cancelled', 'declined') and s.scheduled_start >= p_from and s.scheduled_start < p_to
  order by s.scheduled_start;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_roster_labour_cost"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[])
 RETURNS TABLE(id uuid, entity_type text, entity_id uuid, requested_id uuid, hazard_class text, alert_level text, raised_at timestamp with time zone, organization_id uuid, organization_name text, contact_email text, contact_phone text, is_own_organization boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_ids uuid[] := coalesce(p_entity_ids, '{}'::uuid[]);
begin
  -- Service-role callers (edge functions such as the officer scan) have no auth.uid(); they see the same redacted rows.
  if v_actor is not null then
    select up.organization_id into v_org from public.user_profiles up where up.id = v_actor and up.deactivated_at is null;
    if v_org is null then raise exception 'Active user required'; end if;
  elsif current_setting('request.jwt.claim.role', true) is distinct from 'service_role' and current_user <> 'postgres' then
    raise exception 'Active user required';
  end if;
  if cardinality(v_ids) = 0 or cardinality(v_ids) > 200 then return; end if;

  return query
  with requested as (
    select r.requested_id, e.entity_type, e.entity_id
    from unnest(v_ids) as r(requested_id)
    cross join lateral public.resolve_flag_entity(p_entity_type, r.requested_id) e
  )
  select f.id, f.entity_type, f.entity_id, q.requested_id, f.hazard_class, f.alert_level, f.raised_at,
         o.id, o.name, o.contact_email, o.contact_phone,
         (f.organization_id = v_org),
         case when f.organization_id = v_org then f.reason else null end
  from requested q
  join public.entity_flags f on f.entity_type = q.entity_type and f.entity_id = q.entity_id
  join public.organizations o on o.id = f.organization_id
  where f.active and f.hazard_class is not null
  order by case f.alert_level when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, f.raised_at desc;
end;
$function$;
COMMENT ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) IS 'Platform-wide health-and-safety warnings for vehicles, people, places (or sites/zones, resolved to their place): every organisation''s active hazard-classed flag, redacted to hazard class, severity, raised_at and the raising organisation''s contact path. reason is returned only for the caller''s own organisation. HSWA 2015 s.34/s.36 with Privacy Act 2020 IPP 11(1)(f); owner ruling 2026-09-15.';
REVOKE ALL ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_safety_warnings"(p_entity_type text, p_entity_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid)
 RETURNS TABLE(worked_hours numeric, rest_breaks_required integer, meal_breaks_required integer, rest_breaks_taken integer, meal_breaks_taken integer, compliant boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_shift public.shifts%rowtype;
  v_hours numeric;
  v_rest_req integer;
  v_meal_req integer;
  v_rest_taken integer;
  v_meal_taken integer;
begin
  select s.* into v_shift from public.shifts s where s.id = p_shift_id;
  if not found then
    raise exception 'Shift not found';
  end if;

  v_hours := extract(epoch from (coalesce(v_shift.actual_end, v_shift.scheduled_end)
    - coalesce(v_shift.actual_start, v_shift.scheduled_start))) / 3600.0;

  v_rest_req := case
    when v_hours < 2 then 0
    when v_hours < 4 then 1
    when v_hours < 6 then 1
    when v_hours < 8 then 2
    else 2 + floor((v_hours - 8) / 4)::integer
  end;

  v_meal_req := case
    when v_hours < 4 then 0
    when v_hours < 8 then 1
    else 1 + floor((v_hours - 8) / 4)::integer
  end;

  select
    count(*) filter (where b.break_type = 'rest' and b.ended_at is not null),
    count(*) filter (where b.break_type = 'meal' and b.ended_at is not null)
  into v_rest_taken, v_meal_taken
  from public.shift_breaks b
  where b.shift_id = v_shift.id;

  return query select
    round(v_hours, 2),
    v_rest_req,
    v_meal_req,
    coalesce(v_rest_taken, 0),
    coalesce(v_meal_taken, 0),
    coalesce(v_rest_taken, 0) >= v_rest_req and coalesce(v_meal_taken, 0) >= v_meal_req;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_shift_break_entitlement"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid)
 RETURNS TABLE(requirement_id uuid, induction_name text, required boolean, completed boolean, expires_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.id, r.induction_name, r.required,
    exists(select 1 from public.staff_site_inductions si where si.requirement_id = r.id and si.staff_id = p_staff_id and (si.expires_at is null or si.expires_at >= current_date)),
    (select si.expires_at from public.staff_site_inductions si where si.requirement_id = r.id and si.staff_id = p_staff_id order by si.completed_at desc limit 1)
  from public.site_induction_requirements r
  where r.service_agreement_location_id = p_service_agreement_location_id and r.active;
$function$;
REVOKE ALL ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_site_induction_state"(p_staff_id uuid, p_service_agreement_location_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid)
 RETURNS TABLE(id uuid, branch_organization_id uuid, branch_name text, role_at_branch text, module_access text[], can_be_rostered boolean, status text, starts_on date, ends_on date, authorised_by uuid, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'Authenticated user required'; end if;
  if p_user_id <> v_actor and not exists (
    select 1 from public.user_profiles actor
    join public.user_profiles target on target.id = p_user_id
    where actor.id = v_actor
      and actor.deactivated_at is null
      and (actor.role = 'grand_master' or (target.employer_organization_id = coalesce(actor.employer_organization_id, actor.organization_id) and (actor.role in ('master', 'admin') or cardinality(public.user_managed_branch_ids()) > 0)))
  ) then
    raise exception 'Not authorised to view this staff member branch access';
  end if;
  return query
    select assignment.id, assignment.branch_org_id, branch.name, assignment.role_at_branch,
      assignment.module_access, assignment.can_be_rostered, assignment.status,
      assignment.starts_on, assignment.ends_on, assignment.authorised_by, assignment.updated_at
  from public.staff_branch_authorisations assignment
  join public.organizations branch on branch.id = assignment.branch_org_id
  where assignment.user_id = p_user_id
    and (p_user_id = v_actor or exists(select 1 from public.user_profiles actor where actor.id = v_actor and actor.role in ('grand_master', 'master', 'admin')) or assignment.branch_org_id = any(public.user_managed_branch_ids()))
  order by branch.name;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_branch_authorisations"(p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid)
 RETURNS TABLE(ledger_id uuid, staff_id uuid, user_id uuid, display_name text, current_stage text, status text, version integer, target_start date, identity_status text, employment_status text, evidence_status text, supervision_status text, induction_status text, work_status text, blockers text[], next_action text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to assess staff onboarding'; end if;
  return query
  select l.id, sp.id, sp.user_id, coalesce(up.display_name, up.email, 'Unnamed staff'), l.current_stage, l.status, l.version, l.target_start,
    case when up.id is not null and up.deactivated_at is null and up.email is not null and up.display_name is not null then 'complete' else 'blocked' end,
    case when sp.start_date is not null and (sp.end_date is null or sp.end_date >= current_date) then 'complete' else 'blocked' end,
    case when exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and (c.expiry_date is null or c.expiry_date>=current_date))
      and exists(select 1 from public.staff_documents d where d.staff_id=sp.id)
      and exists(select 1 from public.staff_skills sk where sk.staff_id=sp.id) then 'complete' else 'blocked' end,
    case when exists(select 1 from public.staff_reporting sr where sr.user_id=coalesce(sp.user_id,sp.id) and sr.scope_org_id=p_organization_id and sr.relationship_type='line_manager' and sr.effective_to is null) then 'complete' else 'blocked' end,
    case when exists(select 1 from public.staff_training_records tr where tr.staff_id=sp.id and tr.training_type='induction' and coalesce(tr.passed,true) and (tr.expiry_date is null or tr.expiry_date>=current_date)) then 'complete' else 'blocked' end,
    case when sp.work_ready then 'ready' else 'blocked' end,
    array_remove(array[
      case when up.id is null or up.deactivated_at is not null or up.email is null or up.display_name is null then 'Complete active identity and invitation' end,
      case when sp.start_date is null or (sp.end_date is not null and sp.end_date<current_date) then 'Set a current employment start date' end,
      case when not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and (c.expiry_date is null or c.expiry_date>=current_date)) then 'Verify a current credential' end,
      case when not exists(select 1 from public.staff_documents d where d.staff_id=sp.id) then 'Upload an employment or credential document' end,
      case when not exists(select 1 from public.staff_skills sk where sk.staff_id=sp.id) then 'Record at least one staff skill' end,
      case when not exists(select 1 from public.staff_reporting sr where sr.user_id=coalesce(sp.user_id,sp.id) and sr.scope_org_id=p_organization_id and sr.relationship_type='line_manager' and sr.effective_to is null) then 'Assign a line manager' end,
      case when not exists(select 1 from public.staff_training_records tr where tr.staff_id=sp.id and tr.training_type='induction' and coalesce(tr.passed,true) and (tr.expiry_date is null or tr.expiry_date>=current_date)) then 'Record completed induction' end,
      case when not sp.work_ready then 'Complete human work-readiness review' end
    ], null)::text[],
    case when up.id is null or up.deactivated_at is not null or up.email is null or up.display_name is null then 'Complete identity'
      when sp.start_date is null then 'Set employment start date'
      when not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and (c.expiry_date is null or c.expiry_date>=current_date)) then 'Verify credential'
      when not exists(select 1 from public.staff_documents d where d.staff_id=sp.id) then 'Upload evidence'
      when not exists(select 1 from public.staff_skills sk where sk.staff_id=sp.id) then 'Record skill'
      when not exists(select 1 from public.staff_reporting sr where sr.user_id=coalesce(sp.user_id,sp.id) and sr.scope_org_id=p_organization_id and sr.relationship_type='line_manager' and sr.effective_to is null) then 'Assign line manager'
      when not exists(select 1 from public.staff_training_records tr where tr.staff_id=sp.id and tr.training_type='induction' and coalesce(tr.passed,true) and (tr.expiry_date is null or tr.expiry_date>=current_date)) then 'Record induction'
      when not sp.work_ready then 'Review work readiness' else 'Ready' end
  from public.staff_onboarding_ledgers l
  join public.staff_profiles sp on sp.id=l.staff_id
  left join public.user_profiles up on up.id=coalesce(sp.user_id,sp.id)
  where l.organization_id=p_organization_id
  order by l.current_stage, up.display_name nulls last;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_onboarding_readiness"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid)
 RETURNS TABLE(staff_id uuid, user_id uuid, work_ready boolean, identity_status text, employment_status text, credential_status text, training_status text, blockers text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to assess staff readiness';end if;
  return query
  select sp.id,sp.user_id,sp.work_ready,
    case when up.id is null then 'unlinked' when up.deactivated_at is not null then 'deactivated' when up.role not in('officer','admin_officer') then 'not_field_role' else 'active' end,
    case when sp.start_date is not null and sp.start_date>current_date then 'not_started' when sp.end_date is not null and sp.end_date<current_date then 'ended' else 'current' end,
    case when up.role not in('officer','admin_officer') then 'not_applicable' when not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and (c.expiry_date is null or c.expiry_date>=current_date)) then 'missing_valid' when exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and (not c.verified or (c.expiry_date is not null and c.expiry_date<current_date))) then 'attention' else 'current' end,
    case when exists(select 1 from public.staff_training_records tr where tr.staff_id=sp.id and (tr.passed=false or (tr.expiry_date is not null and tr.expiry_date<current_date))) then 'attention' else 'clear' end,
    array_remove(array[
      case when up.id is null then 'Identity is not linked' when up.deactivated_at is not null then 'User access is deactivated' when up.role not in('officer','admin_officer') then 'User is not assigned a field role' end,
      case when sp.start_date is not null and sp.start_date>current_date then 'Employment has not started' when sp.end_date is not null and sp.end_date<current_date then 'Employment has ended' end,
      case when up.role in('officer','admin_officer') and not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and (c.expiry_date is null or c.expiry_date>=current_date)) then 'No verified current credential' end
    ],null)::text[]
  from public.staff_profiles sp left join public.user_profiles up on up.id=sp.user_id where sp.organization_id=p_organization_id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_staff_readiness_assessment"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid)
 RETURNS TABLE(user_id uuid, identity_status text, employment_status text, access_status text, credential_status text, work_status text, blockers text[], next_action text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to assess users';end if;
  return query select u.id,
    case when u.deactivated_at is not null then 'deactivated' when u.email is null or u.display_name is null then 'incomplete' else 'active' end,
    case when u.role in('officer','admin_officer') and sp.id is null then 'missing' when sp.id is null then 'not_applicable' when sp.end_date is not null and sp.end_date<current_date then 'ended' else 'current' end,
    case when u.role in('grand_master','master','admin','admin_officer') and not exists(select 1 from public.preset_assignments pa where pa.user_id=u.id and pa.scope_org_id=u.organization_id and pa.status='active') then 'missing_preset' else 'role_scoped' end,
    case when u.role in('officer','admin_officer') and sp.id is not null and not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and(c.expiry_date is null or c.expiry_date>=current_date)) then 'missing_valid' when u.role in('officer','admin_officer') then 'current' else 'not_applicable' end,
    case when u.role in('officer','admin_officer') and coalesce(sp.work_ready,false) then 'ready' when u.role in('officer','admin_officer') then 'blocked' else 'not_applicable' end,
    array_remove(array[case when u.deactivated_at is not null then 'Reactivate the identity before assigning work' end,case when u.display_name is null or u.email is null then 'Complete the identity profile' end,case when u.role in('officer','admin_officer') and sp.id is null then 'Create the employment profile' end,case when u.role in('grand_master','master','admin','admin_officer') and not exists(select 1 from public.preset_assignments pa where pa.user_id=u.id and pa.scope_org_id=u.organization_id and pa.status='active') then 'Assign an access preset' end,case when u.role in('officer','admin_officer') and sp.id is not null and not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and(c.expiry_date is null or c.expiry_date>=current_date)) then 'Verify a current credential' end,case when u.role in('officer','admin_officer') and sp.id is not null and not sp.work_ready then 'Complete work-readiness review' end],null),
    case when u.deactivated_at is not null then 'Reactivate identity' when u.display_name is null or u.email is null then 'Complete identity profile' when u.role in('officer','admin_officer') and sp.id is null then 'Create employment profile' when u.role in('grand_master','master','admin','admin_officer') and not exists(select 1 from public.preset_assignments pa where pa.user_id=u.id and pa.scope_org_id=u.organization_id and pa.status='active') then 'Assign access preset' when u.role in('officer','admin_officer') and sp.id is not null and not exists(select 1 from public.staff_credentials c where c.staff_id=sp.id and c.verified and(c.expiry_date is null or c.expiry_date>=current_date)) then 'Verify credential' when u.role in('officer','admin_officer') and sp.id is not null and not sp.work_ready then 'Review work readiness' else 'Ready for assigned responsibilities' end
  from public.user_profiles u left join public.staff_profiles sp on sp.user_id=u.id or sp.id=u.id where u.organization_id=p_organization_id order by u.display_name nulls last,u.email;
end;$function$;
REVOKE ALL ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."get_user_spine_readiness"(p_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text)
 RETURNS staff_area_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_grant public.staff_area_grants%rowtype;v_reason text:=nullif(trim(coalesce(p_reason,'')), '');
begin
  if v_reason is null then raise exception 'A change reason is required';end if;
  if p_area not in('timesheet_local_review','leave_branch_approve','roster_impact_approve','credentials_supervise','hr_case_local_investigate','incident_manage_local') then raise exception 'Unsupported branch authority area';end if;
  if p_level not in('view','verify','approve','adjust','manage') then raise exception 'Unsupported access level';end if;
  if p_user_id=v_actor then raise exception 'You cannot grant yourself branch authority';end if;
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.staff_branch_authorisation_manager_can_manage(v_actor,p_operating_organization_id,p_user_id) then raise exception 'Not authorised to grant branch authority';end if;
  if not exists(select 1 from public.staff_branch_authorisations assignment where assignment.user_id=p_user_id and assignment.branch_org_id=p_operating_organization_id and assignment.status='active') then raise exception 'Active staff branch authorization required';end if;
  select * into v_grant from public.staff_area_grants where user_id=p_user_id and scope_org_id=p_operating_organization_id and area=p_area and status='active' for update;
  if found then raise exception 'An active grant already exists for this area';end if;
  insert into public.staff_area_grants(user_id,scope_org_id,area,level,status,source_preset,granted_by) values(p_user_id,p_operating_organization_id,p_area,p_level,'active',null,v_actor) returning * into v_grant;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_operating_organization_id,v_actor,'branch_area_grant_created','staff_area_grants',v_grant.id,jsonb_build_object('user_id',p_user_id,'area',p_area,'level',p_level,'reason',v_reason));
  return v_grant;
end;$function$;
REVOKE ALL ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."grant_branch_area_access"(p_operating_organization_id uuid, p_user_id uuid, p_area text, p_level text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text DEFAULT 'provider_reads_client'::text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_grand_master()
    or (p_site_id is not null and exists (select 1 from public.client_sites site where site.id = p_site_id and public.org_access_allowed(site.client_organization_id)))
    or (p_zone_id is not null and exists (select 1 from public.location_zones zone where zone.id = p_zone_id and public.org_access_allowed(zone.organization_id)))
    or (p_direction = 'provider_reads_client' and exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational' and agreement.invitation_status = 'accepted'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and public.org_access_allowed(agreement.provider_organization_id)
    ))
    or (p_direction = 'client_reads_provider' and exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational' and agreement.invitation_status = 'accepted'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and public.org_access_allowed(agreement.client_organization_id)
    ))
    or exists (
      select 1 from public.service_agreement_locations location
      join public.service_agreements agreement on agreement.id = location.service_agreement_id
      where location.status = 'active' and agreement.agreement_type = 'operational' and agreement.invitation_status = 'accepted'
        and (location.site_id = p_site_id or location.zone_id = p_zone_id)
        and location.head_contractor_org_id is not null and public.org_access_allowed(location.head_contractor_org_id)
    );
$function$;
COMMENT ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) IS 'Returns true when the calling user''s org has access to a location (site or zone), either by ownership, via an active service_agreement_locations row, or as a head contractor with subcontracted work at the location. Direction controls cross-org read: provider_reads_client (provider reads client location data) or client_reads_provider (client reads Tier 1 operational results at their location). QA gaps G1+G2 from epic #179; head-contractor visibility from epic #203 R2 #205.';
REVOKE ALL ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."has_location_access"(p_site_id uuid, p_zone_id uuid, p_direction text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer DEFAULT 900)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  UPDATE public.inference_jobs
     SET stage = COALESCE(NULLIF(trim(p_stage), ''), stage), heartbeat_at = clock_timestamp(),
         lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds)
   WHERE id = p_job_id AND status = 'processing' AND lease_token = p_lease_token;
  RETURN FOUND;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."heartbeat_cctv_inference_job"(p_job_id uuid, p_lease_token uuid, p_stage text, p_lease_seconds integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."identity_role_level"(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_role when 'grand_master' then 6 when 'master' then 5 when 'admin' then 4 when 'admin_officer' then 4 when 'officer' then 2 when 'scan_operator' then 2 when 'nzscv_monitor' then 1 when 'client_admin' then 1 when 'client_officer' then 1 when 'client_viewer' then 1 else 0 end;
$function$;
REVOKE ALL ON FUNCTION "public"."identity_role_level"(p_role text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."identity_role_level"(p_role text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."identity_role_level"(p_role text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."import_approved_freedom_places"(p_places jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_place jsonb; v_client uuid; v_provider uuid; v_agreement uuid; v_location uuid; v_site uuid; v_zone uuid; v_geojson jsonb; v_created jsonb := '[]'::jsonb;
BEGIN
  IF NOT has_table_privilege(current_user, 'public.locations', 'INSERT') THEN RAISE EXCEPTION 'Service role table privilege required'; END IF;
  IF jsonb_typeof(p_places) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Places must be a JSON array'; END IF;
  FOR v_place IN SELECT value FROM jsonb_array_elements(p_places) LOOP
    v_client := (v_place->>'client_organization_id')::uuid; v_provider := (v_place->>'provider_organization_id')::uuid; v_agreement := (v_place->>'service_agreement_id')::uuid;
    IF v_client IS NULL OR v_provider IS NULL OR v_agreement IS NULL THEN RAISE EXCEPTION 'Client, provider, and agreement are required'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.service_agreements WHERE id=v_agreement AND provider_organization_id=v_provider AND client_organization_id=v_client) THEN RAISE EXCEPTION 'Agreement does not bind the supplied organizations'; END IF;
    v_geojson := v_place->'geojson'; IF v_geojson IS NULL OR v_geojson->>'type' NOT IN ('Polygon','MultiPolygon') THEN RAISE EXCEPTION 'Approved place geometry must be Polygon or MultiPolygon'; END IF;
    SELECT id INTO v_location FROM public.locations WHERE organization_id=v_client AND lower(name)=lower(v_place->>'location_name') ORDER BY created_at LIMIT 1;
    IF v_location IS NULL THEN
      INSERT INTO public.locations(organization_id,name,address,notes,created_by) VALUES(v_client,v_place->>'location_name',NULL,'Imported from approved Freedom Camping jurisdiction source. Source project: '||coalesce(v_place->>'source_project','unknown')||'; source id: '||coalesce(v_place->>'source_id','unknown'),v_actor) RETURNING id INTO v_location;
    END IF;
    INSERT INTO public.client_sites(client_organization_id,organization_id,location_id,name,address,active,site_origin,ownership_status,ownership_signals,boundary,boundary_status,boundary_verification,boundary_verified_by,boundary_verified_at,external_refs) VALUES(v_client,v_client,v_location,v_place->>'site_name',NULL,true,'contracted','resolved',jsonb_build_object('source','FreedomCamp-Manager','approval','user_directed_live_import'),ST_GeomFromGeoJSON(v_geojson::text),'authoritative','verified',v_actor,clock_timestamp(),jsonb_build_object('source_project',v_place->>'source_project','source_id',v_place->>'source_id','source_sha256',v_place->>'source_sha256')) ON CONFLICT DO NOTHING RETURNING id INTO v_site;
    IF v_site IS NULL THEN SELECT id INTO v_site FROM public.client_sites WHERE client_organization_id=v_client AND location_id=v_location AND name=v_place->>'site_name' ORDER BY created_at DESC LIMIT 1; END IF;
    INSERT INTO public.location_zones(organization_id,location_id,name,zone_type,module_key,is_active,boundary,boundary_verification,boundary_status,boundary_verified_by,boundary_verified_at,metadata,bylaw_clause,nightly_limit_consecutive,nightly_limit_monthly,scv_required) VALUES(v_client,v_location,v_place->>'zone_name',coalesce(v_place->>'zone_type','freedom_camping'),v_place->>'module_key',true,ST_Multi(ST_GeomFromGeoJSON(v_geojson::text)),'verified','authoritative',v_actor,clock_timestamp(),jsonb_build_object('source_project',v_place->>'source_project','source_id',v_place->>'source_id','source_sha256',v_place->>'source_sha256','source_policy',v_place->'policy'),(v_place->'policy'->>'bylaw_clause'),(v_place->'policy'->>'nightly_limit_consecutive')::integer,(v_place->'policy'->>'nightly_limit_monthly')::integer,coalesce((v_place->'policy'->>'scv_required')::boolean,false)) ON CONFLICT DO NOTHING RETURNING id INTO v_zone;
    IF v_zone IS NULL THEN SELECT id INTO v_zone FROM public.location_zones WHERE organization_id=v_client AND location_id=v_location AND name=v_place->>'zone_name' ORDER BY created_at DESC LIMIT 1; END IF;
    INSERT INTO public.service_agreement_locations(service_agreement_id,zone_id,status,created_by) VALUES(v_agreement,v_zone,'active',v_actor) ON CONFLICT DO NOTHING;
    v_created := v_created || jsonb_build_object('location_id',v_location,'site_id',v_site,'zone_id',v_zone,'agreement_id',v_agreement,'source_id',v_place->>'source_id');
  END LOOP;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES((p_places->0->>'provider_organization_id')::uuid,v_actor,'freedom_places_imported','service_agreement_locations',NULL,jsonb_build_object('count',jsonb_array_length(p_places),'source_project',p_places->0->>'source_project','approval','user_directed_live_import'));
  RETURN v_created;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."import_approved_freedom_places"(p_places jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_shift     record;
  v_stop_id   uuid;
  v_max_order integer;
begin
  select * into v_shift from shifts where id = p_shift_id;
  if not found then
    raise exception 'Shift % not found', p_shift_id;
  end if;

  -- Place adhoc stop at end of current sequence.
  select coalesce(max(stop_order), 0) into v_max_order
  from shift_stops
  where shift_id = p_shift_id
    and status = 'pending';

  insert into shift_stops (
    organization_id,
    shift_id,
    dispatch_job_id,
    site_id,
    module_key,
    stop_order,
    visit_number,
    is_adhoc,
    sla_arrive_by,
    required_dwell_minutes,
    status,
    sla_status
  ) values (
    v_shift.organization_id,
    p_shift_id,
    p_dispatch_job_id,
    p_site_id,
    p_module_key,
    v_max_order + 10,
    1,
    true,
    p_sla_respond_by,
    15,  -- default dwell for adhoc; API can update after insertion
    'pending',
    'on_track'
  )
  returning id into v_stop_id;

  -- Mark dispatch job as inserted into shift.
  update dispatch_jobs
  set shift_id          = p_shift_id,
      shift_stop_id     = v_stop_id,
      adhoc_inserted_at = now(),
      insert_gps_lat    = p_officer_gps_lat,
      insert_gps_lng    = p_officer_gps_lng,
      status            = 'dispatched'
  where id = p_dispatch_job_id;

  -- Invalidate solve cache so API re-solves with new stop.
  update patrol_solve_cache
  set invalidated_at      = now(),
      invalidation_reason = 'adhoc_inserted'
  where shift_id = p_shift_id;

  return v_stop_id;
end;
$function$;
COMMENT ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) IS 'Inserts an adhoc dispatch job as a shift stop and invalidates the solve cache. Called by apps/api dispatch engine.';
REVOKE ALL ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."insert_adhoc_stop"(p_shift_id uuid, p_dispatch_job_id uuid, p_site_id uuid, p_module_key text, p_sla_respond_by timestamp with time zone, p_officer_gps_lat double precision, p_officer_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text)
 RETURNS onboarding_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_invite_kind text;
  v_email text := lower(trim(coalesce(p_email, '')));
  v_token text := encode(extensions.gen_random_bytes(32), 'hex');
  v_invite public.onboarding_invites%rowtype;
BEGIN
  IF p_capability NOT IN ('reporting', 'finance') THEN
    RAISE EXCEPTION 'capability must be reporting or finance';
  END IF;
  v_invite_kind := p_capability || '_share';
  IF v_email = '' OR v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'A valid email is required';
  END IF;

  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;

  INSERT INTO public.onboarding_invites (target_organization_id, service_agreement_id, invited_by, email, token_hash, invite_kind, status, expires_at)
  VALUES (v_agreement.client_organization_id, v_agreement.id, v_actor, v_email, encode(extensions.digest(v_token, 'sha256'), 'hex'), v_invite_kind, 'pending', now() + interval '14 days')
  RETURNING * INTO v_invite;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_agreement.provider_organization_id, v_actor, 'client_capability_share_invited', 'onboarding_invites', v_invite.id, jsonb_build_object('service_agreement_id', v_agreement.id, 'capability', p_capability, 'email', v_email));

  -- Plaintext token returned once, to the inviter, for delivery out-of-band.
  v_invite.token_hash := v_token;
  RETURN v_invite;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."invite_client_capability_share"(p_service_agreement_id uuid, p_capability text, p_email text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."is_admin_for_org"(target_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from user_profiles
    where id = auth.uid()
      and deactivated_at is null
      and role in ('grand_master', 'master', 'admin')
      and (
        role = 'grand_master'
        or (role = 'master' and (
          target_org_id = any (public.get_descendant_organizations(employer_organization_id))
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.agreement_type = 'operational'
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
        or (role = 'admin' and (
          organization_id = target_org_id
          or target_org_id = any (public.get_descendant_organizations(organization_id))
          or exists (
            select 1 from public.service_agreements sa
            where (sa.ends_on is null or sa.ends_on >= current_date)
              and sa.agreement_type = 'operational'
              and sa.client_organization_id = target_org_id
              and (organization_id = sa.provider_organization_id
                   or employer_organization_id = sa.provider_organization_id)
          )
        ))
      )
  );
$function$;
COMMENT ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) IS 'Returns true if the current active user is admin, master, or grand_master for the target org. Admin/master check the org descendant tree (via get_descendant_organizations) and agreement-based provider access on OPERATIONAL agreements only (0271 Model A; financial agreements excluded — owner ruling 2026-09-15). Grand master has unrestricted access.';
REVOKE ALL ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_admin_for_org"(target_org_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."is_enforcement_operator_for_org"(target_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles p
    WHERE p.id = auth.uid()
      AND p.role IN ('grand_master', 'master', 'admin', 'admin_officer', 'officer')
      AND (
        p.role = 'grand_master'
        OR target_org_id = p.organization_id
        OR target_org_id = ANY(public.get_descendant_organizations(p.organization_id))
        OR (p.employer_organization_id IS NOT NULL
            AND target_org_id = ANY(public.get_descendant_organizations(p.employer_organization_id)))
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."is_enforcement_operator_for_org"(target_org_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_enforcement_operator_for_org"(target_org_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_enforcement_operator_for_org"(target_org_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_enforcement_operator_for_org"(target_org_id uuid) TO "service_role";

