CREATE OR REPLACE FUNCTION "public"."is_platform_owner"(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
begin
  -- Resolve email from auth.users (the authoritative identity store).
  select lower(trim(email)) into v_email
  from auth.users
  where id = p_user_id;

  -- Fail-closed: no auth row or no email => not an owner.
  if v_email is null or v_email = '' then
    return false;
  end if;

  -- Canonical owner emails (mirrors supabase/functions/_shared/auth.ts OWNER_EMAILS).
  return v_email in (
    'don.squires@firstsecurity.co.nz',
    'squires.don@live.com',
    'squires.don@gmail.com'
  );
end;
$function$;
COMMENT ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) IS 'Returns true iff the given user_profiles.id resolves to a platform-owner email in auth.users. Fail-closed: no auth row or no email => false. Mirrors OWNER_EMAILS from supabase/functions/_shared/auth.ts.';
REVOKE ALL ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_platform_owner"(p_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select jsonb_build_object(
    'closed',       true,
    'closure_id',   c.id,
    'closure_type', c.closure_type,
    'reason',       c.reason,
    'effective_from', c.effective_from,
    'effective_to',   c.effective_to
  )
  from zone_closures c
  where c.zone_id = p_zone_id
    and c.status <> 'lifted'
    and c.effective_from <= (p_at at time zone 'Pacific/Auckland')::date
    and (c.effective_to is null
         or c.effective_to >= (p_at at time zone 'Pacific/Auckland')::date)
  order by
    case c.closure_type
      when 'prohibited' then 0
      when 'restricted' then 1
      else 2
    end asc,
    c.effective_from desc
  limit 1;
$function$;
COMMENT ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) IS 'Returns the in-force closure for a zone at p_at as JSON (closed, closure_id, closure_type, reason, dates), or NULL when the zone is open. prohibited > restricted > temporary_closure. Dates compared in Pacific/Auckland.';
REVOKE ALL ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."is_zone_closed"(p_zone_id uuid, p_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text)
 RETURNS cctv_exports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  export_row public.cctv_exports;
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF p_artifact_bucket IS NULL OR trim(p_artifact_bucket) = ''
     OR p_artifact_path IS NULL OR trim(p_artifact_path) = '' THEN
    RAISE EXCEPTION 'Private artifact bucket and path are required';
  END IF;

  SELECT * INTO export_row
    FROM public.cctv_exports
   WHERE id = p_export_id
   FOR UPDATE;

  IF NOT FOUND OR NOT public.org_access_allowed(export_row.organization_id) THEN
    RAISE EXCEPTION 'CCTV export not found or access denied';
  END IF;
  IF export_row.approval_state <> 'sealed' THEN
    RAISE EXCEPTION 'Only sealed exports may be issued';
  END IF;

  UPDATE public.cctv_exports
     SET approval_state = 'issued',
         artifact_bucket = trim(p_artifact_bucket),
         artifact_path = trim(p_artifact_path),
         issued_at = clock_timestamp()
   WHERE id = p_export_id
   RETURNING * INTO export_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    export_row.organization_id,
    actor_id,
    'cctv_export_issued',
    'cctv_exports',
    p_export_id,
    jsonb_build_object(
      'artifact_bucket', p_artifact_bucket,
      'artifact_path', p_artifact_path,
      'manifest_sha256', export_row.manifest_sha256
    )
  );

  RETURN export_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_export"(p_export_id uuid, p_artifact_bucket text, p_artifact_path text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb)
 RETURNS TABLE(report_id uuid, generated_at timestamp with time zone, observation_count integer, sha256 text, provenance jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  generated timestamptz := clock_timestamp();
  receipt_id uuid := gen_random_uuid();
  v_evidence public.evidence_items%rowtype;
  v_job public.inference_jobs%rowtype;
  v_import public.cctv_imports%rowtype;
  v_place record;
  v_result record;
  v_review record;
  v_legacy record;
  v_prior record;
  v_provenance jsonb;
  v_payload jsonb;
  payload_hash text;
  count_observations integer;
  v_claimed_status text := p_payload->>'report_status';
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV report access denied'; END IF;
  IF jsonb_typeof(p_payload) <> 'object' THEN RAISE EXCEPTION 'CCTV report payload must be an object'; END IF;

  SELECT * INTO v_job FROM public.inference_jobs
   WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id AND domain IN ('video_motion', 'vehicle', 'face');
  IF v_job.id IS NULL THEN RAISE EXCEPTION 'CCTV job or evidence is missing or outside the organization'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id AND organization_id = p_organization_id;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'CCTV job or evidence is missing or outside the organization'; END IF;
  IF v_evidence.cctv_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_evidence.cctv_import_id;
    SELECT l.name, l.address INTO v_place FROM public.locations l WHERE l.id = v_import.location_id;
  END IF;
  SELECT r.id, r.status, r.created_at, r.result->'classification_plan' AS classification_plan,
         r.result->>'worker_version' AS worker_version, r.result->>'model_version' AS model_version
    INTO v_result
    FROM public.inference_results r WHERE r.inference_job_id = v_job.id ORDER BY r.created_at DESC LIMIT 1;
  SELECT count(*) AS total,
         count(*) FILTER (WHERE o.review_state = 'accepted') AS accepted,
         count(*) FILTER (WHERE o.review_state = 'rejected') AS rejected,
         count(*) FILTER (WHERE o.review_state = 'unreviewed') AS unreviewed,
         count(*) FILTER (WHERE o.review_state IN ('uncertain', 'needs_more_context')) AS undecided,
         max(o.reviewed_at) AS last_reviewed_at
    INTO v_review
    FROM public.cctv_entity_observations o WHERE o.evidence_item_id = v_evidence.id;
  SELECT count(*) AS decisions, max(d.decided_at) AS last_decided_at INTO v_legacy
    FROM public.cctv_review_decisions d WHERE d.evidence_item_id = v_evidence.id;
  SELECT count(*) AS receipts, max(r.generated_at) AS latest_at,
         (array_agg(r.id ORDER BY r.generated_at DESC))[1] AS latest_id
    INTO v_prior
    FROM public.cctv_report_receipts r WHERE r.evidence_item_id = v_evidence.id;

  count_observations := jsonb_array_length(CASE WHEN jsonb_typeof(p_payload->'observations') = 'array' THEN p_payload->'observations' ELSE '[]'::jsonb END);

  v_provenance := jsonb_strip_nulls(jsonb_build_object(
    'receipt_id', receipt_id,
    'issued_at', generated,
    'issued_by', actor_id,
    'claimed_report_status', v_claimed_status,
    'evidence', jsonb_build_object(
      'id', v_evidence.id, 'storage_path', v_evidence.storage_path, 'captured_at', v_evidence.captured_at,
      'sha256_hash', v_evidence.sha256_hash, 'source_size_bytes', (v_evidence.metadata->>'source_size_bytes')::bigint,
      'is_court_ready', v_evidence.is_court_ready, 'locked_at', v_evidence.locked_at, 'retention_hold', v_evidence.retention_hold,
      'integrity_state', v_evidence.metadata->'integrity'->>'state', 'integrity_checked_at', v_evidence.metadata->'integrity'->>'checked_at'),
    'import', CASE WHEN v_import.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_import.id, 'camera_label', v_import.camera_label, 'camera_key', v_import.camera_key,
      'source_device_kind', v_import.source_device_kind, 'source_timezone', v_import.source_timezone,
      'location_id', v_import.location_id, 'canonical_place_id', v_import.canonical_place_id,
      'place_name', v_place.name, 'place_address', v_place.address) END,
    'job', jsonb_build_object('id', v_job.id, 'domain', v_job.domain, 'status', v_job.status, 'completed_at', v_job.completed_at, 'attempt_count', v_job.attempt_count),
    'result', CASE WHEN v_result.id IS NULL THEN NULL ELSE jsonb_build_object(
      'inference_result_id', v_result.id, 'status', v_result.status, 'created_at', v_result.created_at,
      'classification_plan', v_result.classification_plan, 'worker_version', v_result.worker_version, 'model_version', v_result.model_version) END,
    'review', jsonb_build_object(
      'observations_total', v_review.total, 'accepted', v_review.accepted, 'rejected', v_review.rejected,
      'unreviewed', v_review.unreviewed, 'undecided', v_review.undecided, 'last_reviewed_at', v_review.last_reviewed_at,
      'legacy_decisions', v_legacy.decisions, 'legacy_last_decided_at', v_legacy.last_decided_at),
    'review_consistency', CASE
      WHEN v_claimed_status = 'review_ready' AND (v_review.unreviewed + v_review.undecided) > 0 THEN 'client_claims_review_ready_but_database_holds_undecided_sightings'
      WHEN v_claimed_status = 'review_ready' THEN 'consistent'
      ELSE 'draft' END,
    'supersedes', CASE WHEN v_prior.receipts > 0 THEN jsonb_build_object('receipt_id', v_prior.latest_id, 'issued_at', v_prior.latest_at, 'earlier_receipts', v_prior.receipts) ELSE NULL END
  ));

  v_payload := p_payload || jsonb_build_object('provenance', v_provenance);
  payload_hash := encode(digest(convert_to(v_payload::text, 'UTF8'), 'sha256'), 'hex');

  INSERT INTO public.cctv_report_receipts (id, organization_id, inference_job_id, evidence_item_id, batch_id, generated_by, generated_at, observation_count, payload, sha256)
  VALUES (receipt_id, p_organization_id, p_job_id, p_evidence_id, NULLIF(trim(p_batch_id), ''), actor_id, generated, count_observations, v_payload, payload_hash);

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, actor_id, 'cctv_report_receipt_issued', 'cctv_report_receipts', receipt_id,
          jsonb_strip_nulls(jsonb_build_object('inference_job_id', p_job_id, 'evidence_item_id', p_evidence_id, 'batch_id', p_batch_id,
            'observation_count', count_observations, 'sha256', payload_hash, 'evidence_sha256', v_evidence.sha256_hash,
            'claimed_report_status', v_claimed_status, 'review_consistency', v_provenance->>'review_consistency',
            'supersedes_receipt_id', v_provenance->'supersedes'->>'receipt_id')));

  RETURN QUERY SELECT receipt_id, generated, count_observations, payload_hash, v_provenance;
END $function$;
COMMENT ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) IS 'Issues an immutable receipt for a CCTV report. The server appends a provenance block (evidence hash/lock/integrity, camera and place, job and inference result, database review counts, superseded receipts, review_consistency) before hashing. Returns the hash and the provenance for printing.';
REVOKE ALL ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."issue_cctv_report_receipt"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_batch_id text, p_payload jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text)
 RETURNS investigation_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_item public.investigations%rowtype; v_link public.investigation_links%rowtype;
BEGIN
  SELECT * INTO v_item FROM public.investigations WHERE id=p_investigation_id FOR UPDATE;
  IF NOT FOUND OR v_actor IS NULL OR NOT public.is_admin_for_org(v_item.organization_id) THEN RAISE EXCEPTION 'Investigation access denied'; END IF;
  IF nullif(trim(p_link_reason),'') IS NULL THEN RAISE EXCEPTION 'Link reason is required'; END IF;
  SELECT * INTO v_link FROM public.investigation_links WHERE investigation_id=p_investigation_id AND entity_type=p_entity_type AND entity_id=p_entity_id;
  IF FOUND THEN RETURN v_link; END IF;
  INSERT INTO public.investigation_links (investigation_id, organization_id, entity_type, entity_id, link_role, link_reason, linked_by)
  VALUES (p_investigation_id, v_item.organization_id, p_entity_type, p_entity_id, p_link_role, trim(p_link_reason), v_actor)
  RETURNING * INTO v_link;
  IF p_entity_type='field_report' THEN UPDATE public.officer_field_reports SET investigation_id=p_investigation_id WHERE id=p_entity_id AND organization_id=v_item.organization_id; END IF;
  IF p_entity_type='incident' THEN UPDATE public.incidents SET investigation_id=p_investigation_id WHERE id=p_entity_id AND organization_id=v_item.organization_id; END IF;
  INSERT INTO public.investigation_events (investigation_id, organization_id, event_type, description, source_table, source_id, created_by)
  VALUES (p_investigation_id, v_item.organization_id, 'entity_linked', p_entity_type || ' linked: ' || trim(p_link_reason), p_entity_type, p_entity_id, v_actor);
  RETURN v_link;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."link_investigation_entity"(p_investigation_id uuid, p_entity_type text, p_entity_id uuid, p_link_role text, p_link_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid DEFAULT NULL::uuid, p_person_record_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid)
 RETURNS observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result public.observations;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Observation access denied';
  END IF;
  IF p_person_record_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.person_records
    WHERE id = p_person_record_id AND public.org_access_allowed(organization_id)
  ) THEN RAISE EXCEPTION 'Person record is outside the accessible organization'; END IF;
  IF p_site_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.client_sites
    WHERE id = p_site_id AND public.has_location_access(id, NULL, 'client_reads_provider')
  ) THEN RAISE EXCEPTION 'Site is outside the accessible organization'; END IF;
  IF p_zone_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.location_zones
    WHERE id = p_zone_id AND public.org_access_allowed(organization_id)
  ) THEN RAISE EXCEPTION 'Zone is outside the accessible organization'; END IF;
  IF p_incident_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.incidents
    WHERE id = p_incident_id AND public.org_access_allowed(organization_id)
  ) THEN RAISE EXCEPTION 'Incident is outside the accessible organization'; END IF;
  IF p_canonical_vehicle_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.canonical_vehicles WHERE id = p_canonical_vehicle_id
  ) THEN RAISE EXCEPTION 'Vehicle record not found'; END IF;

  UPDATE public.observations
  SET canonical_vehicle_id = p_canonical_vehicle_id,
      person_record_id = p_person_record_id,
      site_id = COALESCE(p_site_id, site_id),
      zone_id = COALESCE(p_zone_id, zone_id),
      location_id = COALESCE(p_location_id, location_id),
      incident_id = p_incident_id
  WHERE id = p_observation_id AND organization_id = p_organization_id
  RETURNING * INTO result;
  IF result.id IS NULL THEN RAISE EXCEPTION 'Observation not found'; END IF;
  RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."link_observation_entities"(p_observation_id uuid, p_organization_id uuid, p_canonical_vehicle_id uuid, p_person_record_id uuid, p_site_id uuid, p_zone_id uuid, p_location_id uuid, p_incident_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid)
 RETURNS TABLE(id uuid, organization_id uuid, display_name text, email text, role text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT u.id, u.organization_id, u.display_name, u.email, u.role
  FROM public.user_profiles u
  JOIN public.service_agreements sa
    ON sa.id = p_service_agreement_id
  JOIN public.organizations officer_org
    ON officer_org.id = u.organization_id
  WHERE u.deactivated_at IS NULL
    AND u.role IN ('officer', 'admin_officer')
    AND (sa.ends_on IS NULL OR sa.ends_on >= current_date)
    AND (
      officer_org.id = sa.provider_organization_id
      OR sa.provider_organization_id = ANY(public.get_descendant_organizations(officer_org.id))
    )
    AND public.org_access_allowed(sa.provider_organization_id)
  ORDER BY coalesce(u.display_name, u.email), u.email;
$function$;
REVOKE ALL ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."list_dispatch_target_officers"(p_service_agreement_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_evidence public.evidence_items%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_reason IS NULL OR char_length(v_reason) < 5 THEN RAISE EXCEPTION 'An evidence lock needs a stated reason (at least 5 characters)'; END IF;

  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id FOR UPDATE;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;
  IF NOT public.is_admin_for_org(v_evidence.organization_id) THEN RAISE EXCEPTION 'Only an administrator of the custodian organisation can lock evidence'; END IF;
  IF v_evidence.locked_at IS NOT NULL THEN
    RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'locked_at', v_evidence.locked_at, 'already_locked', true);
  END IF;
  IF nullif(trim(coalesce(v_evidence.sha256_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'This recording has no integrity hash yet; wait for analysis to record it before locking';
  END IF;

  UPDATE public.evidence_items
     SET is_court_ready = true,
         locked_at = clock_timestamp(),
         retention_hold = true,
         retention_reason = 'evidence_lock: ' || v_reason,
         metadata = metadata || jsonb_build_object('evidence_lock', jsonb_build_object('locked_by', v_actor, 'reason', v_reason, 'locked_at', clock_timestamp()))
   WHERE id = v_evidence.id
   RETURNING * INTO v_evidence;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, v_actor, 'cctv_evidence_locked', 'evidence_items', v_evidence.id,
          jsonb_build_object('reason', v_reason, 'sha256_hash', v_evidence.sha256_hash, 'locked_at', v_evidence.locked_at, 'cctv_import_id', v_evidence.cctv_import_id));

  RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'locked_at', v_evidence.locked_at, 'already_locked', false);
END $function$;
COMMENT ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) IS 'Admin-only evidence lock for a CCTV recording: sets is_court_ready, locked_at and retention_hold so retention cannot purge it. Refused without a recorded sha256_hash. Audited; not reversible from the browser.';
REVOKE ALL ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."lock_cctv_evidence"(p_evidence_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_identity_id uuid;
  v_event_id uuid;
  v_payload jsonb;
begin
  if p_event_type not in ('sign_request','sign_success','sign_failure','identity_check') then
    raise exception 'invalid event_type';
  end if;

  if p_fingerprint_sha256 is distinct from 'SHA256:ckUO3+2YpwZcGZFGvqu/R4cZpO1iXq8IaAL9pKQl3Y4' then
    raise exception 'fingerprint not allowlisted';
  end if;

  select id
  into v_identity_id
  from public.bob_signing_identities
  where provider = 'gitea'
    and key_name = 'bob-gitea'
    and fingerprint_sha256 = p_fingerprint_sha256
    and enabled = true
  order by created_at desc
  limit 1;

  if v_identity_id is null then
    raise exception 'active signing identity not found';
  end if;

  v_payload := jsonb_build_object(
    'namespace', 'gitea',
    'key_name', 'bob-gitea',
    'fingerprint_sha256', p_fingerprint_sha256,
    'success', p_success,
    'reason', p_reason,
    'request_id', p_request_id
  );

  insert into public.bob_signing_audit (
    identity_id,
    event_type,
    event_payload,
    actor_user_id
  )
  values (
    v_identity_id,
    p_event_type,
    v_payload,
    auth.uid()
  )
  returning id into v_event_id;

  return v_event_id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."log_bob_signing_event"(p_event_type text, p_fingerprint_sha256 text, p_success boolean, p_reason text, p_request_id text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_organization_id is null or p_target_user_id is null or p_action_type is null or p_performed_by is null then raise exception 'Complete audit provenance is required';end if;
  insert into public.user_management_audit(target_user_id,action_type,performed_by,old_value,new_value,metadata)
  values(p_target_user_id,p_action_type,p_performed_by,p_old_value,p_new_value,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('organization_id',p_organization_id)) returning id into v_id;
  return v_id;
end;$function$;
REVOKE ALL ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."log_user_management_action"(p_organization_id uuid, p_target_user_id uuid, p_action_type text, p_performed_by uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_active_shift"(p_shift_id uuid, p_expected_status text, p_action text, p_notes text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_shift public.shifts%rowtype;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id=p_shift_id FOR UPDATE;
  IF NOT FOUND OR NOT public.is_admin_for_org(v_shift.organization_id) THEN RAISE EXCEPTION 'Shift not found or access denied'; END IF;
  IF v_shift.status <> p_expected_status THEN RAISE EXCEPTION 'Shift changed since it was opened'; END IF;
  IF p_action NOT IN ('amend','escalate','cancel') THEN RAISE EXCEPTION 'Unsupported active shift action'; END IF;
  IF nullif(trim(coalesce(p_reason,'')), '') IS NULL THEN RAISE EXCEPTION 'A reason is required'; END IF;
  IF p_action='cancel' AND v_shift.actual_start IS NOT NULL THEN RAISE EXCEPTION 'An active shift cannot be cancelled after it has started'; END IF;
  UPDATE public.shifts SET notes=coalesce(nullif(trim(p_notes),''),notes), shift_health=CASE WHEN p_action='escalate' THEN 'critical' ELSE shift_health END, status=CASE WHEN p_action='cancel' THEN 'cancelled' ELSE status END, updated_at=clock_timestamp() WHERE id=v_shift.id RETURNING * INTO v_shift;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_shift.organization_id,v_actor,'shift_'||p_action,'shifts',v_shift.id,jsonb_build_object('reason',trim(p_reason),'status',v_shift.status,'shift_health',v_shift.shift_health));
  RETURN v_shift;
END; $function$;
REVOKE ALL ON FUNCTION "public"."manage_active_shift"(p_shift_id uuid, p_expected_status text, p_action text, p_notes text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_shift_id uuid, p_expected_status text, p_action text, p_notes text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_shift_id uuid, p_expected_status text, p_action text, p_notes text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_active_shift"(p_shift_id uuid, p_expected_status text, p_action text, p_notes text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid DEFAULT NULL::uuid, p_asset_type text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_serial_number text DEFAULT NULL::text, p_registration text DEFAULT NULL::text, p_make text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_year integer DEFAULT NULL::integer, p_status text DEFAULT NULL::text, p_next_inspection_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_asset public.assets%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select actor.organization_id into v_provider from public.user_profiles actor
  where actor.id = v_actor and actor.deactivated_at is null;

  if v_provider is null or not public.is_admin_for_org(v_provider) then
    raise exception 'Active fleet administrator required';
  end if;

  if p_action = 'create' then
    if v_name is null then
      raise exception 'Asset name is required';
    end if;
    if p_asset_type not in ('vehicle', 'radio', 'body_camera', 'torch', 'uniform', 'first_aid_kit', 'ems_device', 'other') then
      raise exception 'Unsupported asset type';
    end if;

    insert into public.assets(
      organization_id, asset_type, name, serial_number, registration,
      make, model, year, status, next_inspection_date, notes
    )
    values (
      v_provider, p_asset_type, v_name,
      nullif(trim(coalesce(p_serial_number, '')), ''),
      nullif(trim(coalesce(p_registration, '')), ''),
      nullif(trim(coalesce(p_make, '')), ''),
      nullif(trim(coalesce(p_model, '')), ''),
      p_year, coalesce(p_status, 'available'), p_next_inspection_date,
      nullif(trim(coalesce(p_notes, '')), '')
    )
    returning * into v_asset;

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_provider, v_actor, 'asset_created', 'assets', v_asset.id,
      jsonb_build_object('asset_type', v_asset.asset_type, 'name', v_asset.name, 'client_request_id', p_client_request_id));

    return v_asset;
  elsif p_action = 'update' then
    select a.* into v_asset from public.assets a where a.id = p_asset_id and a.organization_id = v_provider for update;
    if not found then
      raise exception 'Asset not found';
    end if;

    if p_status is not null and p_status not in ('available', 'in_use', 'maintenance', 'retired', 'lost') then
      raise exception 'Unsupported asset status';
    end if;

    if p_status = 'available' and exists (
      select 1 from public.shift_assets l where l.asset_id = v_asset.id and l.returned_at is null
    ) then
      raise exception 'Asset is still assigned to an active shift';
    end if;

    update public.assets set
      name = coalesce(v_name, name),
      serial_number = coalesce(nullif(trim(coalesce(p_serial_number, '')), ''), serial_number),
      registration = coalesce(nullif(trim(coalesce(p_registration, '')), ''), registration),
      make = coalesce(nullif(trim(coalesce(p_make, '')), ''), make),
      model = coalesce(nullif(trim(coalesce(p_model, '')), ''), model),
      year = coalesce(p_year, year),
      status = coalesce(p_status, status),
      next_inspection_date = coalesce(p_next_inspection_date, next_inspection_date),
      notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes)
    where id = v_asset.id
    returning * into v_asset;

    insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
    values (v_provider, v_actor, 'asset_updated', 'assets', v_asset.id,
      jsonb_build_object('status', v_asset.status, 'name', v_asset.name));

    return v_asset;
  else
    raise exception 'Unsupported manage_asset action %', p_action;
  end if;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_asset"(p_client_request_id uuid, p_action text, p_asset_id uuid, p_asset_type text, p_name text, p_serial_number text, p_registration text, p_make text, p_model text, p_year integer, p_status text, p_next_inspection_date date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text)
 RETURNS TABLE(assessment_id uuid, review_status text, review_version integer, review_priority text, assigned_reviewer_id uuid, review_due_at timestamp with time zone, species_review_decision text, confirmed_species_name text, species_confirmed boolean, follow_up_required boolean, reviewed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_item public.biosecurity_assessments%rowtype;
  v_next_status text;
  v_notes text := NULLIF(BTRIM(COALESCE(p_notes, '')), '');
  v_species_name text := NULLIF(BTRIM(COALESCE(p_confirmed_species_name, '')), '');
  v_officer uuid;
  v_now timestamptz := clock_timestamp();
BEGIN
  SELECT assessment.* INTO v_item
  FROM public.biosecurity_assessments assessment
  WHERE assessment.id = p_assessment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Biosecurity assessment not found';
  END IF;
  IF NOT public.is_admin_for_org(v_item.organization_id) THEN
    RAISE EXCEPTION 'Active Biosecurity administrator required';
  END IF;
  IF v_item.review_version <> p_expected_review_version THEN
    RAISE EXCEPTION 'Biosecurity review changed from expected version % to %', p_expected_review_version, v_item.review_version;
  END IF;
  IF v_notes IS NULL OR char_length(v_notes) < 10 THEN
    RAISE EXCEPTION 'Review rationale must contain at least 10 characters';
  END IF;
  IF p_priority NOT IN ('urgent', 'high', 'routine', 'monitor') THEN
    RAISE EXCEPTION 'Unsupported biosecurity review priority';
  END IF;
  IF p_assigned_reviewer_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.user_profiles reviewer
    WHERE reviewer.id = p_assigned_reviewer_id
      AND reviewer.organization_id = v_item.organization_id
      AND reviewer.deactivated_at IS NULL
      AND reviewer.role IN ('grand_master', 'master', 'admin', 'admin_officer')
  ) THEN
    RAISE EXCEPTION 'Active organization reviewer required';
  END IF;

  IF p_action = 'triage' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'triaged';
    IF p_species_decision <> 'pending' THEN
      RAISE EXCEPTION 'Triage cannot make the final species decision';
    END IF;
  ELSIF p_action = 'require_follow_up' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'follow_up';
    IF p_species_decision <> 'insufficient_evidence' THEN
      RAISE EXCEPTION 'Follow-up requires an insufficient-evidence decision';
    END IF;
  ELSIF p_action = 'close' AND v_item.review_status IN ('awaiting_review', 'triaged', 'follow_up') THEN
    v_next_status := 'closed';
    IF p_species_decision NOT IN ('confirmed', 'rejected') THEN
      RAISE EXCEPTION 'Closure requires a confirmed or rejected species decision';
    END IF;
    IF p_species_decision = 'confirmed' AND v_species_name IS NULL THEN
      RAISE EXCEPTION 'Confirmed species name is required';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported Biosecurity review transition from % using %', v_item.review_status, p_action;
  END IF;

  IF v_next_status <> 'closed' THEN
    IF p_review_due_at IS NULL OR p_review_due_at <= v_now THEN
      RAISE EXCEPTION 'An active review requires a future due date';
    END IF;
    IF (p_priority = 'urgent' AND p_review_due_at > v_now + interval '2 days')
       OR (p_priority = 'high' AND p_review_due_at > v_now + interval '7 days')
       OR (p_priority = 'routine' AND p_review_due_at > v_now + interval '30 days')
       OR (p_priority = 'monitor' AND p_review_due_at > v_now + interval '90 days') THEN
      RAISE EXCEPTION 'Review due date exceeds the selected priority window';
    END IF;
  END IF;

    UPDATE public.biosecurity_assessments AS assessment
  SET review_status = v_next_status,
      review_version = assessment.review_version + 1,
      review_priority = p_priority,
      assigned_reviewer_id = p_assigned_reviewer_id,
      review_due_at = CASE WHEN v_next_status = 'closed' THEN NULL ELSE p_review_due_at END,
      species_review_decision = p_species_decision,
      confirmed_species_name = CASE WHEN p_species_decision = 'confirmed' THEN v_species_name ELSE NULL END,
      species_confirmed = p_species_decision = 'confirmed',
      reviewed_by = v_actor,
      reviewed_at = v_now,
      review_notes = v_notes,
      follow_up_required = v_next_status = 'follow_up',
      status = CASE WHEN v_next_status = 'closed' THEN 'closed' ELSE 'open' END
  WHERE assessment.id = v_item.id
  RETURNING * INTO v_item;

  v_officer := COALESCE(v_item.officer_user_id, v_item.officer_id);
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_item.organization_id,
    v_actor,
    'biosecurity_assessment_reviewed',
    'biosecurity_assessments',
    v_item.id,
    jsonb_build_object(
      'review_action', p_action,
      'review_status', v_item.review_status,
      'review_version', v_item.review_version,
      'priority', v_item.review_priority,
      'assigned_reviewer_id', v_item.assigned_reviewer_id,
      'species_decision', v_item.species_review_decision,
      'source_officer_id', v_officer,
      'rationale', v_notes
    )
  );

  IF v_officer IS NOT NULL THEN
    PERFORM public.enqueue_notification(
      p_organization_id => v_item.organization_id,
      p_category => 'biosecurity_review',
      p_title => CASE
        WHEN v_next_status = 'follow_up' THEN 'Biosecurity evidence follow-up required'
        WHEN v_next_status = 'closed' THEN 'Biosecurity assessment decision recorded'
        ELSE 'Biosecurity assessment triaged'
      END,
      p_body => v_notes,
      p_severity => CASE WHEN v_item.review_priority IN ('urgent', 'high') OR v_next_status = 'follow_up' THEN 'warning' ELSE 'info' END,
      p_recipient_user_id => v_officer,
      p_link_page => 'biosecurity-review',
      p_link_payload => jsonb_build_object('assessment_id', v_item.id),
      p_dedup_key => 'biosecurity_review:' || v_item.id::text || ':' || v_item.review_version::text
    );
  END IF;

  RETURN QUERY SELECT
    v_item.id,
    v_item.review_status,
    v_item.review_version,
    v_item.review_priority,
    v_item.assigned_reviewer_id,
    v_item.review_due_at,
    v_item.species_review_decision,
    v_item.confirmed_species_name,
    v_item.species_confirmed,
    v_item.follow_up_required,
    v_item.reviewed_at;
END;
$function$;
COMMENT ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) IS 'Versioned administrator review boundary for biosecurity triage, evidence follow-up, and explicit human species decisions. Audits and personally notifies the reporting officer.';
REVOKE ALL ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_version integer, p_action text, p_priority text, p_assigned_reviewer_id uuid, p_review_due_at timestamp with time zone, p_species_decision text, p_confirmed_species_name text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text)
 RETURNS TABLE(assessment_id uuid, review_state text, reviewed_by uuid, reviewed_at timestamp with time zone, follow_up_required boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_item public.biosecurity_assessments%rowtype;
  v_officer uuid;
  v_next text;
  v_notes text := nullif(trim(coalesce(p_notes, '')), '');
begin
  select b.* into v_item from public.biosecurity_assessments b where b.id = p_assessment_id for update;
  if not found then raise exception 'Biosecurity assessment not found'; end if;
  if not public.is_admin_for_org(v_item.organization_id) then raise exception 'Active Biosecurity administrator required'; end if;
  if v_item.review_state <> p_expected_review_state then
    raise exception 'Biosecurity review changed from expected state % to %', p_expected_review_state, v_item.review_state;
  end if;
  if v_notes is null then raise exception 'Review notes are required'; end if;

  if p_action = 'triage' and v_item.review_state in ('submitted', 'requires_supervisor_review') then
    v_next := 'triaged';
  elsif p_action = 'require_review' then
    v_next := 'requires_supervisor_review';
  elsif p_action = 'close' and v_item.review_state in ('submitted', 'requires_supervisor_review', 'triaged') then
    v_next := 'closed';
  else
    raise exception 'Unsupported biosecurity review transition from % using %', v_item.review_state, p_action;
  end if;

  update public.biosecurity_assessments
    set review_state = v_next,
        reviewed_by = v_actor,
        reviewed_at = clock_timestamp(),
        review_notes = v_notes,
        follow_up_required = case when v_next = 'requires_supervisor_review' then true when v_next = 'closed' then false else biosecurity_assessments.follow_up_required end
    where id = v_item.id
    returning * into v_item;

  v_officer := coalesce(v_item.officer_user_id, v_item.officer_id);

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_item.organization_id, v_actor, 'biosecurity_assessment_reviewed', 'biosecurity_assessments', v_item.id,
    jsonb_build_object('previous_review_state', p_expected_review_state, 'review_state', v_next, 'action', p_action, 'source_officer_id', v_officer, 'notes', v_notes)
  );

  if v_officer is not null then
    perform public.enqueue_notification(
      p_organization_id => v_item.organization_id,
      p_category => 'report_reviewed',
      p_title => 'Biosecurity assessment reviewed',
      p_body => v_notes,
      p_severity => case when v_next = 'requires_supervisor_review' then 'warning' else 'info' end,
      p_recipient_user_id => v_officer,
      p_link_page => 'biosecurity-review',
      p_link_payload => jsonb_build_object('assessment_id', v_item.id),
      p_dedup_key => 'biosecurity_review:' || v_item.id::text || ':' || v_item.review_state
    );
  end if;

  return query select v_item.id, v_item.review_state, v_item.reviewed_by, v_item.reviewed_at, v_item.follow_up_required;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_biosecurity_assessment_review"(p_assessment_id uuid, p_expected_review_state text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text)
 RETURNS TABLE(alert_id uuid, alert_status text, action_type text, actioned_at timestamp with time zone, source_officer_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_alert public.breach_alerts%rowtype;v_officer uuid;v_next_status text;v_action_type text;v_notes text:=nullif(trim(coalesce(p_notes,'')),'');
begin
  select b.* into v_alert from public.breach_alerts b where b.id=p_alert_id for update;if not found then raise exception 'Breach alert not found';end if;
  if not public.is_admin_for_org(v_alert.organization_id) then raise exception 'Active compliance administrator required';end if;
  if v_alert.status<>p_expected_status then raise exception 'Breach alert changed from expected status % to %',p_expected_status,v_alert.status;end if;
  if v_notes is null then raise exception 'Breach decision notes are required';end if;
  if v_alert.status='open' and p_action in('verbal_warning','written_warning','notice_to_vacate','infringement','tow_request','welfare_referral') then v_next_status:='actioned';v_action_type:=p_action;
  elsif v_alert.status='open' and p_action='dismissed' then v_next_status:='dismissed';v_action_type:='dismissed';
  elsif v_alert.status='actioned' and p_action in('resolved','exempt_homeless') then v_next_status:=p_action;v_action_type:=v_alert.action_type;
  else raise exception 'Unsupported breach transition from % using %',v_alert.status,p_action;end if;
  update public.breach_alerts set status=v_next_status,action_type=v_action_type,actioned_by=v_actor,actioned_at=clock_timestamp(),notes=concat_ws(E'\n',nullif(notes,''),'Decision: '||v_notes) where id=v_alert.id returning * into v_alert;
  select o.officer_id into v_officer from public.observations o where o.id=v_alert.observation_id;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_alert.organization_id,v_actor,'breach_alert_managed','breach_alerts',v_alert.id,jsonb_build_object('previous_status',p_expected_status,'status',v_alert.status,'action',p_action,'source_officer_id',v_officer,'notes',v_notes));
  if v_officer is not null then perform public.enqueue_notification(p_organization_id=>v_alert.organization_id,p_category=>'breach_decision',p_title=>'Breach review updated',p_body=>v_notes,p_severity=>'info',p_recipient_user_id=>v_officer,p_link_page=>'breach-decision',p_link_payload=>jsonb_build_object('breach_alert_id',v_alert.id),p_dedup_key=>'breach_decision:'||v_alert.id::text||':'||v_alert.status);end if;
  return query select v_alert.id,v_alert.status,v_alert.action_type,v_alert.actioned_at,v_officer;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_breach_alert"(p_alert_id uuid, p_expected_status text, p_action text, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text)
 RETURNS TABLE(job_id uuid, action text, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job public.inference_jobs%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV job access denied';
  END IF;

  SELECT * INTO v_job
    FROM public.inference_jobs
   WHERE id = p_job_id
     AND organization_id = p_organization_id
     AND domain = 'video_motion'
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CCTV job not found';
  END IF;

  IF p_action = 'retry' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'manual_review_required') THEN
      RAISE EXCEPTION 'Only failed or reviewable CCTV jobs can be retried';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'queued', completed_at = NULL, created_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'queued'::text;
    RETURN;
  END IF;

  IF p_action = 'cancel' THEN
    IF v_job.status NOT IN ('queued', 'processing') THEN
      RAISE EXCEPTION 'Only queued or processing CCTV jobs can be cancelled';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'cancelled', completed_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'cancelled'::text;
    RETURN;
  END IF;

  IF p_action = 'close' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'manual_review_required') THEN
      RAISE EXCEPTION 'Only failed or reviewable CCTV jobs can be closed';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'cancelled', completed_at = clock_timestamp()
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'cancelled'::text;
    RETURN;
  END IF;

  IF p_action = 'archive' THEN
    IF v_job.status IN ('queued', 'processing') THEN
      RAISE EXCEPTION 'Running CCTV jobs must be cancelled before archiving';
    END IF;
    UPDATE public.inference_jobs
       SET status = 'archived', completed_at = COALESCE(completed_at, clock_timestamp())
     WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'archived'::text;
    RETURN;
  END IF;

  IF p_action = 'delete' THEN
    IF v_job.status NOT IN ('failed', 'inconclusive', 'cancelled', 'archived') THEN
      RAISE EXCEPTION 'Only terminal CCTV jobs can be deleted';
    END IF;
    DELETE FROM public.inference_jobs WHERE id = v_job.id;
    RETURN QUERY SELECT v_job.id, p_action, 'deleted'::text;
    RETURN;
  END IF;

  RAISE EXCEPTION 'Unsupported CCTV job action';
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_cctv_inference_job"(p_job_id uuid, p_organization_id uuid, p_action text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_effective_from date DEFAULT NULL::date, p_effective_to date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS commercial_discount_schedules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_provider uuid;
  v_schedule public.commercial_discount_schedules%rowtype;
  v_name text := nullif(trim(coalesce(p_name, '')), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select organization_id into v_provider from public.user_profiles where id = v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active finance administrator required'; end if;
  if p_action = 'create' then
    if v_name is null then raise exception 'Discount schedule name is required'; end if;
    if p_effective_to is not null and p_effective_to < coalesce(p_effective_from, current_date) then raise exception 'Effective end cannot precede effective start'; end if;
    select * into v_schedule from public.commercial_discount_schedules where provider_organization_id = v_provider and client_request_id = p_client_request_id;
    if found then return v_schedule; end if;
    insert into public.commercial_discount_schedules(provider_organization_id,name,effective_from,effective_to,notes,client_request_id,created_by)
    values(v_provider,v_name,coalesce(p_effective_from,current_date),p_effective_to,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id,v_actor)
    returning * into v_schedule;
  else
    select * into v_schedule from public.commercial_discount_schedules where id = p_schedule_id for update;
    if not found or v_schedule.provider_organization_id <> v_provider then raise exception 'Discount schedule not found in your organization'; end if;
    if p_action = 'activate' then
      if not exists (select 1 from public.commercial_discount_schedule_rules where schedule_id = v_schedule.id) then raise exception 'An active discount schedule needs at least one rule'; end if;
      update public.commercial_discount_schedules set status = 'active', updated_at = now() where id = v_schedule.id returning * into v_schedule;
    elsif p_action = 'retire' then
      update public.commercial_discount_schedules set status = 'retired', updated_at = now() where id = v_schedule.id returning * into v_schedule;
    else
      raise exception 'Unsupported discount schedule action';
    end if;
  end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_provider,v_actor,'commercial_discount_schedule_' || p_action,'commercial_discount_schedules',v_schedule.id,jsonb_build_object('status',v_schedule.status,'version',v_schedule.version,'client_request_id',p_client_request_id));
  return v_schedule;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule"(p_client_request_id uuid, p_action text, p_schedule_id uuid, p_name text, p_effective_from date, p_effective_to date, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text DEFAULT NULL::text, p_client_organization_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_discount_kind text DEFAULT NULL::text, p_discount_value numeric DEFAULT NULL::numeric, p_minimum_subtotal numeric DEFAULT NULL::numeric, p_priority integer DEFAULT 0)
 RETURNS commercial_discount_schedule_rules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_schedule public.commercial_discount_schedules%rowtype;
  v_rule public.commercial_discount_schedule_rules%rowtype;
begin
  select * into v_schedule from public.commercial_discount_schedules where id = p_schedule_id for update;
  if not found or not public.is_admin_for_org(v_schedule.provider_organization_id) then raise exception 'Discount schedule not found in your organization'; end if;
  if v_schedule.status <> 'draft' then raise exception 'Only draft discount schedules can be changed'; end if;
  if p_module_key is not null and not exists (select 1 from public.module_catalog where module_key = p_module_key and active) then raise exception 'Active module catalog entry required'; end if;
  if p_discount_kind not in ('percentage', 'fixed_amount') or p_discount_value is null or p_discount_value < 0 or (p_discount_kind = 'percentage' and p_discount_value > 100) then raise exception 'Discount kind and value are invalid'; end if;
  if p_minimum_subtotal is not null and p_minimum_subtotal < 0 then raise exception 'Minimum subtotal cannot be negative'; end if;
  if p_site_id is not null and p_zone_id is not null then raise exception 'A discount rule can target a Site or Zone, not both'; end if;
  if (p_site_id is not null or p_zone_id is not null) and p_client_organization_id is null then raise exception 'A Site or Zone discount requires its client organization'; end if;
  if p_site_id is not null and not exists (select 1 from public.client_sites where id = p_site_id and client_organization_id = p_client_organization_id) then raise exception 'Site does not belong to the selected client organization'; end if;
  if p_zone_id is not null and not exists (select 1 from public.location_zones zone join public.locations location on location.id = zone.location_id where zone.id = p_zone_id and location.organization_id = p_client_organization_id) then raise exception 'Zone does not belong to the selected client organization'; end if;

  insert into public.commercial_discount_schedule_rules(schedule_id,module_key,client_organization_id,site_id,zone_id,discount_kind,discount_value,minimum_subtotal,priority)
  values(p_schedule_id,p_module_key,p_client_organization_id,p_site_id,p_zone_id,p_discount_kind,p_discount_value,p_minimum_subtotal,coalesce(p_priority,0))
  returning * into v_rule;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_schedule.provider_organization_id,v_actor,'commercial_discount_rule_created','commercial_discount_schedule_rules',v_rule.id,jsonb_build_object('schedule_id',v_schedule.id,'module_key',p_module_key,'client_organization_id',p_client_organization_id,'site_id',p_site_id,'zone_id',p_zone_id,'discount_kind',p_discount_kind,'discount_value',p_discount_value));
  return v_rule;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_commercial_discount_schedule_rule"(p_schedule_id uuid, p_module_key text, p_client_organization_id uuid, p_site_id uuid, p_zone_id uuid, p_discount_kind text, p_discount_value numeric, p_minimum_subtotal numeric, p_priority integer) TO "postgres";
