CREATE OR REPLACE FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text)
 RETURNS crm_activation_handoffs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_handoff public.crm_activation_handoffs%rowtype;v_task public.crm_activation_handoff_tasks%rowtype;v_note text:=trim(coalesce(p_note,''));v_all_complete boolean;
begin
  select organization_id into v_provider from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active CRM administrator required';end if;
  select * into v_handoff from public.crm_activation_handoffs h where h.id=p_handoff_id and h.provider_organization_id=v_provider for update;
  if not found then raise exception 'Activation handoff not found';end if;
  if v_handoff.version<>p_expected_version then raise exception 'Activation handoff changed since it was opened';end if;
  select * into v_task from public.crm_activation_handoff_tasks t where t.id=p_task_id and t.handoff_id=v_handoff.id for update;
  if not found then raise exception 'Activation handoff task not found';end if;
  if char_length(v_note) not between 3 and 1000 then raise exception 'Completion note must be between 3 and 1000 characters';end if;
  if p_complete and v_task.task_key='first_roster_action' and not exists(select 1 from public.roster_slots rs join public.roster_work_units wu on wu.id=rs.work_unit_id join public.service_agreement_locations sal on sal.id=wu.service_agreement_location_id where sal.service_agreement_id=v_handoff.agreement_id and rs.status in('published','accepted','completed') and rs.scheduled_start>=v_handoff.activated_at) then raise exception 'Publish the first post-activation roster action before completing this task';end if;
  update public.crm_activation_handoff_tasks set status=case when p_complete then 'completed' else 'pending' end,completion_note=v_note,completed_at=case when p_complete then clock_timestamp() else null end,completed_by=case when p_complete then v_actor else null end where id=v_task.id;
  select not exists(select 1 from public.crm_activation_handoff_tasks t where t.handoff_id=v_handoff.id and t.status<>'completed') into v_all_complete;
  update public.crm_activation_handoffs set status=case when v_all_complete then 'completed' else 'open' end,version=version+1,completed_at=case when v_all_complete then clock_timestamp() else null end,completed_by=case when v_all_complete then v_actor else null end,updated_at=clock_timestamp() where id=v_handoff.id returning * into v_handoff;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_provider,v_actor,'crm_activation_handoff_task_'||case when p_complete then 'completed' else 'reopened' end,'crm_activation_handoff_tasks',v_task.id,jsonb_build_object('handoff_id',v_handoff.id,'task_key',v_task.task_key,'handoff_status',v_handoff.status,'handoff_version',v_handoff.version,'note',v_note));
  return v_handoff;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_activation_handoff_task"(p_handoff_id uuid, p_task_id uuid, p_expected_version integer, p_complete boolean, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
BEGIN
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id=p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Provider administrator required'; END IF;
  IF v_agreement.agreement_type <> 'operational' OR v_agreement.invitation_status <> 'accepted' THEN RAISE EXCEPTION 'Only accepted operational agreements can be configured'; END IF;
  IF v_agreement.invitation_status IS DISTINCT FROM p_expected_invitation_status THEN RAISE EXCEPTION 'Service agreement changed since it was opened'; END IF;

  UPDATE public.service_agreements
  SET client_portal_finance_enabled = coalesce(p_client_portal_finance_enabled, false)
  WHERE id = v_agreement.id
  RETURNING * INTO v_agreement;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_agreement.provider_organization_id,v_actor,'crm_agreement_finance_updated','service_agreements',v_agreement.id,jsonb_build_object('client_portal_finance_enabled',v_agreement.client_portal_finance_enabled));

  RETURN jsonb_build_object('agreement_id',v_agreement.id,'client_portal_finance_enabled',v_agreement.client_portal_finance_enabled);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_finance"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_finance_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_obligation"(p_agreement_id uuid, p_action text, p_obligation_id uuid DEFAULT NULL::uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_obligation_code text DEFAULT NULL::text, p_obligation_type text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sla_target_minutes integer DEFAULT NULL::integer, p_requires_proof boolean DEFAULT false, p_proof_artifact_type text DEFAULT NULL::text, p_escalation_minutes integer DEFAULT NULL::integer, p_escalation_contact text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_frequency_rule jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_obligation public.agreement_obligations%rowtype;
  v_code text:=upper(nullif(btrim(p_obligation_code),''));
begin
  select sa.* into v_agreement from public.service_agreements sa where sa.id=p_agreement_id for update;
  if not found then raise exception 'Service agreement not found';end if;
  if v_actor is null or not public.is_admin_for_org(v_agreement.provider_organization_id) then raise exception 'Provider administrator required';end if;
  if v_agreement.agreement_type<>'operational' or v_agreement.invitation_status<>'accepted' then raise exception 'Only accepted operational agreements can be configured';end if;
  if p_action is null or p_action not in('save','deactivate') then raise exception 'Unsupported obligation action';end if;

  if p_obligation_id is not null then
    select ao.* into v_obligation from public.agreement_obligations ao where ao.id=p_obligation_id and ao.service_agreement_id=v_agreement.id for update;
    if not found then raise exception 'Agreement obligation not found';end if;
    if p_expected_updated_at is null or v_obligation.updated_at is distinct from p_expected_updated_at then raise exception 'Agreement obligation changed since it was opened';end if;
  end if;

  if p_action='deactivate' then
    if p_obligation_id is null then raise exception 'Agreement obligation required';end if;
    update public.agreement_obligations set active=false,updated_at=clock_timestamp() where id=v_obligation.id returning * into v_obligation;
  else
    if v_code is null or v_code!~'^[A-Z0-9][A-Z0-9._-]{1,63}$' then raise exception 'Obligation code must be 2-64 letters, numbers, dots, dashes, or underscores';end if;
    if nullif(btrim(p_description),'') is null then raise exception 'Obligation description required';end if;
    if p_obligation_type is null or p_obligation_type not in('response_time','patrol_frequency','report_delivery','incident_escalation','compliance_check','custom') then raise exception 'Valid obligation type required';end if;
    if p_sla_target_minutes is not null and p_sla_target_minutes<1 then raise exception 'SLA target must be positive';end if;
    if p_escalation_minutes is not null and p_escalation_minutes<1 then raise exception 'Escalation time must be positive';end if;
    if coalesce(p_requires_proof,false) and (p_proof_artifact_type is null or p_proof_artifact_type not in('photo','gps_track','report','signature','timestamp','other')) then raise exception 'Proof artifact type required';end if;
    if p_site_id is not null and not exists(select 1 from public.service_agreement_locations sal where sal.service_agreement_id=v_agreement.id and sal.site_id=p_site_id and sal.status='active') then raise exception 'Obligation site must be in active agreement coverage';end if;

    if p_obligation_id is null then
      insert into public.agreement_obligations(service_agreement_id,obligation_code,obligation_type,description,sla_target_minutes,requires_proof,proof_artifact_type,escalation_minutes,escalation_contact,site_id,frequency_rule,active)
      values(v_agreement.id,v_code,p_obligation_type,btrim(p_description),p_sla_target_minutes,coalesce(p_requires_proof,false),case when coalesce(p_requires_proof,false) then p_proof_artifact_type else null end,p_escalation_minutes,nullif(btrim(p_escalation_contact),''),p_site_id,p_frequency_rule,true)
      returning * into v_obligation;
    else
      update public.agreement_obligations set obligation_code=v_code,obligation_type=p_obligation_type,description=btrim(p_description),sla_target_minutes=p_sla_target_minutes,requires_proof=coalesce(p_requires_proof,false),proof_artifact_type=case when coalesce(p_requires_proof,false) then p_proof_artifact_type else null end,escalation_minutes=p_escalation_minutes,escalation_contact=nullif(btrim(p_escalation_contact),''),site_id=p_site_id,frequency_rule=p_frequency_rule,active=true,updated_at=clock_timestamp() where id=v_obligation.id returning * into v_obligation;
    end if;
  end if;

  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_agreement.provider_organization_id,v_actor,'crm_agreement_obligation_'||p_action,'agreement_obligations',v_obligation.id,jsonb_build_object('agreement_id',v_agreement.id,'obligation_code',v_obligation.obligation_code,'active',v_obligation.active));
  return to_jsonb(v_obligation);
exception when unique_violation then
  raise exception 'Obligation code already exists for this agreement';
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_obligation"(p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_obligation"(p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_obligation"(p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_obligation"(p_agreement_id uuid, p_action text, p_obligation_id uuid, p_expected_updated_at timestamp with time zone, p_obligation_code text, p_obligation_type text, p_description text, p_sla_target_minutes integer, p_requires_proof boolean, p_proof_artifact_type text, p_escalation_minutes integer, p_escalation_contact text, p_site_id uuid, p_frequency_rule jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_reporting"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_reports_enabled boolean, p_monthly_report_template_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_agreement public.service_agreements%rowtype;
  v_template text := nullif(trim(coalesce(p_monthly_report_template_code, '')), '');
BEGIN
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id=p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Provider administrator required'; END IF;
  IF v_agreement.agreement_type <> 'operational' THEN RAISE EXCEPTION 'Only operational agreements can be configured'; END IF;
  IF v_agreement.invitation_status <> 'accepted' AND NOT v_agreement.client_portal_reports_enabled THEN
    RAISE EXCEPTION 'Client approval or an active reporting-share invite is required to configure reporting';
  END IF;
  IF v_agreement.invitation_status IS DISTINCT FROM p_expected_invitation_status THEN RAISE EXCEPTION 'Service agreement changed since it was opened'; END IF;
  IF p_client_portal_reports_enabled AND v_template IS NULL THEN RAISE EXCEPTION 'A monthly report template is required when client report delivery is enabled'; END IF;
  IF v_template IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.report_templates rt WHERE rt.organization_id=v_agreement.provider_organization_id AND rt.template_code=v_template) THEN RAISE EXCEPTION 'Monthly report template is not configured for this provider'; END IF;

  UPDATE public.service_agreements
  SET client_portal_reports_enabled = coalesce(p_client_portal_reports_enabled, false),
      monthly_report_template_code = CASE WHEN coalesce(p_client_portal_reports_enabled, false) THEN v_template ELSE NULL END
  WHERE id = v_agreement.id
  RETURNING * INTO v_agreement;

  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_agreement.provider_organization_id,v_actor,'crm_agreement_reporting_updated','service_agreements',v_agreement.id,jsonb_build_object('client_portal_reports_enabled',v_agreement.client_portal_reports_enabled,'monthly_report_template_code',v_agreement.monthly_report_template_code));

  RETURN jsonb_build_object('agreement_id',v_agreement.id,'client_portal_reports_enabled',v_agreement.client_portal_reports_enabled,'monthly_report_template_code',v_agreement.monthly_report_template_code);
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_reporting"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_reports_enabled boolean, p_monthly_report_template_code text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_reporting"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_reports_enabled boolean, p_monthly_report_template_code text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_reporting"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_reports_enabled boolean, p_monthly_report_template_code text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_reporting"(p_agreement_id uuid, p_expected_invitation_status text, p_client_portal_reports_enabled boolean, p_monthly_report_template_code text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_setup"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_site_id uuid DEFAULT NULL::uuid, p_module_key text DEFAULT NULL::text, p_enabled boolean DEFAULT true, p_sla_minutes integer DEFAULT NULL::integer, p_allows_client_submission boolean DEFAULT false, p_allows_auto_dispatch boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_agreement public.service_agreements%rowtype;v_link public.service_agreement_locations%rowtype;v_module public.service_agreement_modules%rowtype;
begin
  select sa.* into v_agreement from public.service_agreements sa where sa.id=p_agreement_id for update;
  if not found then raise exception 'Service agreement not found';end if;
  if v_actor is null or not public.is_admin_for_org(v_agreement.provider_organization_id) then raise exception 'Provider administrator required';end if;
  if v_agreement.agreement_type<>'operational' or v_agreement.invitation_status<>'accepted' then raise exception 'Only accepted operational agreements can be configured';end if;
  if v_agreement.invitation_status is distinct from p_expected_invitation_status then raise exception 'Service agreement changed since it was opened';end if;
  if p_action in('link_site','unlink_site') then
    if p_site_id is null or not exists(select 1 from public.client_sites s where s.id=p_site_id and s.client_organization_id=v_agreement.client_organization_id and s.active) then raise exception 'Active client site required';end if;
    if p_action='link_site' then
      insert into public.service_agreement_locations(service_agreement_id,site_id,status,created_by) values(v_agreement.id,p_site_id,'active',v_actor)
      on conflict(service_agreement_id,site_id) do update set status='active',updated_at=clock_timestamp() returning * into v_link;
    else
      update public.service_agreement_locations set status='ended',updated_at=clock_timestamp() where service_agreement_id=v_agreement.id and site_id=p_site_id returning * into v_link;
      if not found then raise exception 'Covered site link not found';end if;
    end if;
  elsif p_action='set_module' then
    if p_module_key is null or not exists(select 1 from public.module_catalog mc where mc.module_key=p_module_key and mc.active) then raise exception 'Active module catalog entry required';end if;
    if p_sla_minutes is not null and (p_sla_minutes<1 or p_sla_minutes>10080) then raise exception 'Module SLA must be between 1 and 10080 minutes';end if;
    insert into public.service_agreement_modules(service_agreement_id,module_key,enabled,sla_minutes,allows_client_submission,allows_auto_dispatch)
    values(v_agreement.id,p_module_key,coalesce(p_enabled,true),p_sla_minutes,p_allows_client_submission,p_allows_auto_dispatch)
    on conflict(service_agreement_id,module_key) do update set enabled=excluded.enabled,sla_minutes=excluded.sla_minutes,allows_client_submission=excluded.allows_client_submission,allows_auto_dispatch=excluded.allows_auto_dispatch returning * into v_module;
    update public.service_agreements set enabled_modules=coalesce((select array_agg(sam.module_key order by sam.module_key) from public.service_agreement_modules sam where sam.service_agreement_id=v_agreement.id and sam.enabled),'{}'::text[]) where id=v_agreement.id returning * into v_agreement;
  else raise exception 'Unsupported agreement setup action';end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_agreement.provider_organization_id,v_actor,'crm_agreement_'||p_action,'service_agreements',v_agreement.id,jsonb_build_object('site_id',p_site_id,'module_key',p_module_key,'enabled',p_enabled,'sla_minutes',p_sla_minutes));
  return jsonb_build_object('agreement_id',v_agreement.id,'action',p_action,'site_link_id',v_link.id,'module_id',v_module.id,'enabled_modules',v_agreement.enabled_modules);
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_setup"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_site_id uuid, p_module_key text, p_enabled boolean, p_sla_minutes integer, p_allows_client_submission boolean, p_allows_auto_dispatch boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_setup"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_site_id uuid, p_module_key text, p_enabled boolean, p_sla_minutes integer, p_allows_client_submission boolean, p_allows_auto_dispatch boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_setup"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_site_id uuid, p_module_key text, p_enabled boolean, p_sla_minutes integer, p_allows_client_submission boolean, p_allows_auto_dispatch boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_crm_agreement_setup"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_site_id uuid, p_module_key text, p_enabled boolean, p_sla_minutes integer, p_allows_client_submission boolean, p_allows_auto_dispatch boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_crm_agreement_zone_coverage"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_zone_id uuid)
 RETURNS service_agreement_locations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid:=auth.uid();v_agreement public.service_agreements%rowtype;v_link public.service_agreement_locations%rowtype;
BEGIN
  SELECT sa.* INTO v_agreement FROM public.service_agreements sa WHERE sa.id=p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found';END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_agreement.provider_organization_id) THEN RAISE EXCEPTION 'Provider administrator required';END IF;
  IF v_agreement.agreement_type<>'operational' OR v_agreement.invitation_status<>'accepted' THEN RAISE EXCEPTION 'Only accepted operational agreements can be configured';END IF;
  IF v_agreement.invitation_status IS DISTINCT FROM p_expected_invitation_status THEN RAISE EXCEPTION 'Service agreement changed since it was opened';END IF;
  IF p_action NOT IN ('link_zone','unlink_zone') THEN RAISE EXCEPTION 'Unsupported agreement zone coverage action';END IF;
  IF p_zone_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.location_zones z WHERE z.id=p_zone_id AND z.organization_id=v_agreement.client_organization_id AND z.is_active) THEN RAISE EXCEPTION 'Active client zone required';END IF;
  IF p_action='link_zone' THEN
    INSERT INTO public.service_agreement_locations(service_agreement_id,zone_id,status,created_by) VALUES(v_agreement.id,p_zone_id,'active',v_actor)
    ON CONFLICT(service_agreement_id,zone_id) DO UPDATE SET status='active',updated_at=clock_timestamp() RETURNING * INTO v_link;
  ELSE
    UPDATE public.service_agreement_locations SET status='ended',updated_at=clock_timestamp() WHERE service_agreement_id=v_agreement.id AND zone_id=p_zone_id RETURNING * INTO v_link;
    IF NOT FOUND THEN RAISE EXCEPTION 'Covered zone link not found';END IF;
  END IF;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) VALUES(v_agreement.provider_organization_id,v_actor,'crm_agreement_'||p_action,'service_agreement_locations',v_link.id,jsonb_build_object('agreement_id',v_agreement.id,'zone_id',p_zone_id,'status',v_link.status));
  RETURN v_link;
END;$function$;
REVOKE ALL ON FUNCTION "public"."manage_crm_agreement_zone_coverage"(p_agreement_id uuid, p_expected_invitation_status text, p_action text, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
