CREATE OR REPLACE FUNCTION "public"."manage_recruitment_candidate"(p_candidate_id uuid, p_expected_stage text, p_next_stage text, p_note text, p_offer_role text DEFAULT NULL::text, p_offer_employment_type text DEFAULT NULL::text, p_offer_start_date date DEFAULT NULL::date)
 RETURNS recruitment_candidates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_row public.recruitment_candidates%rowtype; v_note text := nullif(trim(coalesce(p_note,'')), ''); v_status text;
begin
  select * into v_row from public.recruitment_candidates where id=p_candidate_id for update;
  if not found or not public.is_admin_for_org(v_row.organization_id) then raise exception 'Candidate not found in your organization'; end if;
  if v_row.stage<>p_expected_stage then raise exception 'Candidate changed from expected stage % to %',p_expected_stage,v_row.stage; end if;
  if v_note is null then raise exception 'A stage note is required'; end if;
  if p_next_stage not in ('screening','interview','reference_check','offer','declined','withdrawn') then raise exception 'Unsupported candidate stage'; end if;
  if p_next_stage='offer' and (p_offer_role is null or p_offer_employment_type not in ('permanent','part_time','casual','contractor','volunteer') or p_offer_start_date is null) then raise exception 'Offer role, employment type, and start date are required'; end if;
  v_status:=case when p_next_stage='offer' then 'offered' when p_next_stage='declined' then 'declined' when p_next_stage='withdrawn' then 'withdrawn' else 'active' end;
  update public.recruitment_candidates set stage=p_next_stage,status=v_status,offer_role=case when p_next_stage='offer' then trim(p_offer_role) else offer_role end,offer_employment_type=case when p_next_stage='offer' then p_offer_employment_type else offer_employment_type end,offer_start_date=case when p_next_stage='offer' then p_offer_start_date else offer_start_date end,offer_sent_at=case when p_next_stage='offer' then now() else offer_sent_at end where id=v_row.id returning * into v_row;
  insert into public.recruitment_candidate_events(candidate_id,organization_id,from_stage,to_stage,note,actor_user_id) values(v_row.id,v_row.organization_id,p_expected_stage,p_next_stage,v_note,v_actor);
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_row.organization_id,v_actor,'recruitment_candidate_progressed','recruitment_candidates',v_row.id,jsonb_build_object('from_stage',p_expected_stage,'to_stage',p_next_stage));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_recruitment_candidate"(p_candidate_id uuid, p_expected_stage text, p_next_stage text, p_note text, p_offer_role text, p_offer_employment_type text, p_offer_start_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_candidate"(p_candidate_id uuid, p_expected_stage text, p_next_stage text, p_note text, p_offer_role text, p_offer_employment_type text, p_offer_start_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_candidate"(p_candidate_id uuid, p_expected_stage text, p_next_stage text, p_note text, p_offer_role text, p_offer_employment_type text, p_offer_start_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_candidate"(p_candidate_id uuid, p_expected_stage text, p_next_stage text, p_note text, p_offer_role text, p_offer_employment_type text, p_offer_start_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_recruitment_vacancy"(p_client_request_id uuid, p_action text, p_vacancy_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_employment_type text DEFAULT NULL::text, p_location_summary text DEFAULT NULL::text, p_opens_on date DEFAULT NULL::date, p_closes_on date DEFAULT NULL::date, p_description text DEFAULT NULL::text, p_required_skills text[] DEFAULT '{}'::text[])
 RETURNS recruitment_vacancies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_org uuid; v_row public.recruitment_vacancies%rowtype; v_title text := nullif(trim(coalesce(p_title,'')), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select organization_id into v_org from public.user_profiles where id=v_actor and deactivated_at is null;
  if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Active HR administrator required'; end if;
  if p_action='create' then
    if v_title is null or p_employment_type not in ('permanent','part_time','casual','contractor','volunteer') then raise exception 'Vacancy title and employment type are required'; end if;
    insert into public.recruitment_vacancies(organization_id,title,employment_type,location_summary,status,opens_on,closes_on,description,required_skills,created_by)
    values(v_org,v_title,p_employment_type,nullif(trim(coalesce(p_location_summary,'')),''),'draft',p_opens_on,p_closes_on,nullif(trim(coalesce(p_description,'')),''),coalesce(p_required_skills,'{}'),v_actor)
    returning * into v_row;
  else
    select * into v_row from public.recruitment_vacancies where id=p_vacancy_id and organization_id=v_org for update;
    if not found then raise exception 'Vacancy not found'; end if;
    if p_action='open' then update public.recruitment_vacancies set status='open',opens_on=coalesce(p_opens_on,current_date) where id=v_row.id returning * into v_row;
    elsif p_action='close' then update public.recruitment_vacancies set status='closed',closes_on=coalesce(p_closes_on,current_date) where id=v_row.id returning * into v_row;
    elsif p_action='cancel' then update public.recruitment_vacancies set status='cancelled' where id=v_row.id returning * into v_row;
    else raise exception 'Unsupported vacancy action'; end if;
  end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'recruitment_vacancy_managed','recruitment_vacancies',v_row.id,jsonb_build_object('action',p_action,'client_request_id',p_client_request_id));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_recruitment_vacancy"(p_client_request_id uuid, p_action text, p_vacancy_id uuid, p_title text, p_employment_type text, p_location_summary text, p_opens_on date, p_closes_on date, p_description text, p_required_skills text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_vacancy"(p_client_request_id uuid, p_action text, p_vacancy_id uuid, p_title text, p_employment_type text, p_location_summary text, p_opens_on date, p_closes_on date, p_description text, p_required_skills text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_vacancy"(p_client_request_id uuid, p_action text, p_vacancy_id uuid, p_title text, p_employment_type text, p_location_summary text, p_opens_on date, p_closes_on date, p_description text, p_required_skills text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_recruitment_vacancy"(p_client_request_id uuid, p_action text, p_vacancy_id uuid, p_title text, p_employment_type text, p_location_summary text, p_opens_on date, p_closes_on date, p_description text, p_required_skills text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_report_template"(p_agreement_id uuid, p_module_key text, p_template_code text, p_name text, p_output_policy jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_organization_id uuid;
  v_template_code text := nullif(trim(coalesce(p_template_code, '')), '');
  v_name text := nullif(trim(coalesce(p_name, '')), '');
  v_module text := nullif(trim(coalesce(p_module_key, '')), '');
  v_row public.report_templates%rowtype;
BEGIN
  SELECT provider_organization_id INTO v_organization_id FROM public.service_agreements WHERE id = p_agreement_id;
  IF v_organization_id IS NULL THEN RAISE EXCEPTION 'Service agreement not found'; END IF;
  IF v_actor IS NULL OR NOT public.is_admin_for_org(v_organization_id) THEN
    RAISE EXCEPTION 'Provider administrator required';
  END IF;
  IF v_template_code IS NULL OR v_name IS NULL OR v_module IS NULL THEN
    RAISE EXCEPTION 'module_key, template_code, and name are required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.module_catalog WHERE module_key = v_module AND active) THEN
    RAISE EXCEPTION 'module_key is not a recognized active module';
  END IF;

  INSERT INTO public.report_templates (organization_id, module_key, template_code, name, output_policy)
  VALUES (v_organization_id, v_module, v_template_code, v_name, coalesce(p_output_policy, '{}'::jsonb))
  ON CONFLICT (organization_id, template_code)
  DO UPDATE SET module_key = excluded.module_key, name = excluded.name, output_policy = excluded.output_policy
  RETURNING * INTO v_row;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_organization_id, v_actor, 'report_template_saved', 'report_templates', v_row.id,
          jsonb_build_object('template_code', v_row.template_code, 'module_key', v_row.module_key, 'name', v_row.name));

  RETURN jsonb_build_object(
    'id', v_row.id, 'organization_id', v_row.organization_id, 'module_key', v_row.module_key,
    'template_code', v_row.template_code, 'name', v_row.name, 'output_policy', v_row.output_policy
  );
END;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_report_template"(p_agreement_id uuid, p_module_key text, p_template_code text, p_name text, p_output_policy jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_report_template"(p_agreement_id uuid, p_module_key text, p_template_code text, p_name text, p_output_policy jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_report_template"(p_agreement_id uuid, p_module_key text, p_template_code text, p_name text, p_output_policy jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_report_template"(p_agreement_id uuid, p_module_key text, p_template_code text, p_name text, p_output_policy jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_roster_skill_catalog"(p_skill_id uuid DEFAULT NULL::uuid, p_skill_name text DEFAULT NULL::text, p_skill_category text DEFAULT NULL::text, p_action text DEFAULT 'create'::text)
 RETURNS roster_skill_catalog
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_org uuid; v_skill public.roster_skill_catalog%rowtype; v_name text := nullif(trim(coalesce(p_skill_name, '')), ''); v_key text;
begin
  select organization_id into v_org from public.user_profiles where id = v_actor and deactivated_at is null;
  if v_org is null or not public.is_admin_for_org(v_org) then raise exception 'Roster administrator required'; end if;
  if p_action not in ('create','update','deactivate') then raise exception 'Unsupported skill catalog action'; end if;
  if p_action in ('create','update') and v_name is null then raise exception 'Skill name is required'; end if;
  v_key := regexp_replace(lower(v_name), '[^a-z0-9]+', '_', 'g');
  if p_action = 'create' then
    insert into public.roster_skill_catalog(organization_id, skill_name, skill_key, skill_category, created_by) values (v_org, v_name, v_key, nullif(trim(p_skill_category), ''), v_actor) returning * into v_skill;
  elsif p_action = 'update' then
    select * into v_skill from public.roster_skill_catalog where id = p_skill_id and organization_id = v_org for update;
    if not found then raise exception 'Skill not found'; end if;
    update public.roster_skill_catalog set skill_name = v_name, skill_key = v_key, skill_category = nullif(trim(p_skill_category), '') where id = v_skill.id returning * into v_skill;
  else
    update public.roster_skill_catalog set active = false where id = p_skill_id and organization_id = v_org returning * into v_skill;
    if not found then raise exception 'Skill not found'; end if;
  end if;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_org, v_actor, 'roster_skill_catalog_' || p_action, 'roster_skill_catalog', v_skill.id, jsonb_build_object('skill_name', v_skill.skill_name, 'skill_key', v_skill.skill_key));
  return v_skill;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_roster_skill_catalog"(p_skill_id uuid, p_skill_name text, p_skill_category text, p_action text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_skill_catalog"(p_skill_id uuid, p_skill_name text, p_skill_category text, p_action text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_skill_catalog"(p_skill_id uuid, p_skill_name text, p_skill_category text, p_action text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_skill_catalog"(p_skill_id uuid, p_skill_name text, p_skill_category text, p_action text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_roster_slot"(p_slot_id uuid, p_expected_status text, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(slot_id uuid, slot_status text, shift_id uuid, shift_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_slot public.roster_slots%rowtype;v_unit public.roster_work_units%rowtype;v_shift public.shifts%rowtype;v_materialized record;
begin
  select s.* into v_slot from public.roster_slots s where s.id=p_slot_id for update;if not found then raise exception 'Roster slot not found';end if;
  if not public.is_admin_for_org(v_slot.organization_id) then raise exception 'Not authorised to manage this roster slot';end if;
  if v_slot.status<>p_expected_status then raise exception 'Roster slot changed from expected status % to %',p_expected_status,v_slot.status;end if;
  select u.* into v_unit from public.roster_work_units u where u.id=v_slot.work_unit_id;
  if p_action='publish' then
    if v_slot.status<>'draft' then raise exception 'Only draft roster slots can be published';end if;
    update public.roster_slots rs set status='published' where rs.id=v_slot.id returning rs.* into v_slot;
    if v_unit.work_unit_type in('patrol','static') then select * into v_materialized from public.materialize_roster_slot(v_slot.id,'published');v_slot.linked_shift_id:=v_materialized.shift_id;end if;
  elsif p_action='cancel' then
    if v_slot.status not in('draft','published','accepted') then raise exception 'This roster slot can no longer be cancelled';end if;
    if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Cancellation reason is required';end if;
    if v_slot.linked_shift_id is not null then
      select s.* into v_shift from public.shifts s where s.id=v_slot.linked_shift_id for update;if not found then raise exception 'Linked field shift not found';end if;
      if v_shift.status not in('scheduled','published','accepted') or v_shift.actual_start is not null then raise exception 'Field shift has started or is no longer cancellable';end if;
      if exists(select 1 from public.patrols p where p.shift_id=v_shift.id and p.status='in_progress') then raise exception 'Active patrol prevents cancellation';end if;
      if exists(select 1 from public.dispatch_jobs d where d.shift_id=v_shift.id and d.status in('pending','pending_approval','dispatched','acknowledged','en_route','on_scene')) then raise exception 'Active dispatch work prevents cancellation';end if;
      if exists(select 1 from public.shift_stop_actions a where a.shift_id=v_shift.id) then raise exception 'Recorded field activity prevents cancellation';end if;
      update public.shift_stop_modules m set status='skipped',updated_at=clock_timestamp() from public.shift_stops st where m.shift_stop_id=st.id and st.shift_id=v_shift.id and m.status in('pending','in_progress');
      update public.shift_stops st set status='cancelled',updated_at=clock_timestamp() where st.shift_id=v_shift.id and st.status in('pending','en_route','on_scene');
      update public.shifts sh set status='cancelled',notes=concat_ws(E'\n',nullif(sh.notes,''),'Cancelled: '||trim(p_reason)) where sh.id=v_shift.id returning sh.* into v_shift;
    end if;
    update public.roster_slots rs set status='cancelled',notes=concat_ws(E'\n',nullif(rs.notes,''),'Cancelled: '||trim(p_reason)) where rs.id=v_slot.id returning rs.* into v_slot;
  else raise exception 'Unsupported roster slot action';end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_slot.organization_id,v_actor,case when p_action='publish' then 'roster_slot_published' else 'roster_slot_cancelled' end,'roster_slots',v_slot.id,jsonb_build_object('work_unit_type',v_unit.work_unit_type,'linked_shift_id',v_slot.linked_shift_id,'reason',case when p_action='cancel' then trim(p_reason) else null end));
  return query select v_slot.id,v_slot.status,v_slot.linked_shift_id,case when v_shift.id is null then null else v_shift.status end;
end;$function$;
REVOKE ALL ON FUNCTION "public"."manage_roster_slot"(p_slot_id uuid, p_expected_status text, p_action text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_slot"(p_slot_id uuid, p_expected_status text, p_action text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_slot"(p_slot_id uuid, p_expected_status text, p_action text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_slot"(p_slot_id uuid, p_expected_status text, p_action text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_roster_work_unit_skill_ids"(p_work_unit_id uuid, p_required_skill_ids uuid[])
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_unit public.roster_work_units%rowtype; v_ids uuid[];
begin
  select * into v_unit from public.roster_work_units where id = p_work_unit_id for update;
  if not found or not public.is_admin_for_org(v_unit.organization_id) then raise exception 'Roster administrator required'; end if;
  select coalesce(array_agg(distinct id order by id), '{}') into v_ids from public.roster_skill_catalog where organization_id = v_unit.organization_id and active and id = any(coalesce(p_required_skill_ids, '{}'));
  update public.roster_work_units set required_skill_ids = v_ids, required_skill_names = coalesce((select array_agg(skill_name order by skill_name) from public.roster_skill_catalog where id = any(v_ids)), '{}') where id = v_unit.id returning * into v_unit;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_unit.organization_id, v_actor, 'roster_work_unit_skill_ids_updated', 'roster_work_units', v_unit.id, jsonb_build_object('required_skill_ids', v_ids));
  return v_unit;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_roster_work_unit_skill_ids"(p_work_unit_id uuid, p_required_skill_ids uuid[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_ids"(p_work_unit_id uuid, p_required_skill_ids uuid[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_ids"(p_work_unit_id uuid, p_required_skill_ids uuid[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_ids"(p_work_unit_id uuid, p_required_skill_ids uuid[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_roster_work_unit_skill_requirements"(p_work_unit_id uuid, p_required_skill_names text[])
 RETURNS roster_work_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_unit public.roster_work_units%rowtype; v_names text[];
begin
  select wu.* into v_unit from public.roster_work_units wu where wu.id = p_work_unit_id for update;
  if not found then raise exception 'Roster work unit not found'; end if;
  if not public.is_admin_for_org(v_unit.organization_id) then raise exception 'Roster administrator required'; end if;
  select coalesce(array_agg(distinct lower(trim(name)) order by lower(trim(name))), '{}') into v_names from unnest(coalesce(p_required_skill_names, '{}')) name where nullif(trim(name), '') is not null;
  update public.roster_work_units set required_skill_names = v_names where id = v_unit.id returning * into v_unit;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_unit.organization_id, v_actor, 'roster_work_unit_skills_updated', 'roster_work_units', v_unit.id, jsonb_build_object('required_skill_names', v_names));
  return v_unit;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."manage_roster_work_unit_skill_requirements"(p_work_unit_id uuid, p_required_skill_names text[]) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_requirements"(p_work_unit_id uuid, p_required_skill_names text[]) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_requirements"(p_work_unit_id uuid, p_required_skill_names text[]) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."manage_roster_work_unit_skill_requirements"(p_work_unit_id uuid, p_required_skill_names text[]) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."manage_service_agreement_continuity_policy"(p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_continuity_mode text, p_client_coverage_start time without time zone DEFAULT NULL::time without time zone, p_client_coverage_end time without time zone DEFAULT NULL::time without time zone, p_provider_coverage_start time without time zone DEFAULT NULL::time without time zone, p_provider_coverage_end time without time zone DEFAULT NULL::time without time zone, p_share_active_cases boolean DEFAULT false, p_share_open_tasks boolean DEFAULT false, p_share_recent_history_hours integer DEFAULT 24, p_share_attachments_mode text DEFAULT 'none'::text, p_share_presence_mode text DEFAULT 'none'::text, p_require_handoff_ack boolean DEFAULT true, p_continuity_retention_hours integer DEFAULT 24)
 RETURNS service_agreement_continuity_policies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_location public.service_agreement_locations%rowtype; v_module public.service_agreement_modules%rowtype; v_row public.service_agreement_continuity_policies%rowtype;
begin
  select * into v_location from public.service_agreement_locations where id = p_service_agreement_location_id for update;
  if not found then raise exception 'Agreement location not found'; end if;
  select * into v_module from public.service_agreement_modules where id = p_service_agreement_module_id;
  if not found or v_module.service_agreement_id <> v_location.service_agreement_id then raise exception 'Module does not belong to this agreement location'; end if;
  if not exists (select 1 from public.service_agreements agreement where agreement.id = v_location.service_agreement_id and public.is_admin_for_org(agreement.provider_organization_id)) then raise exception 'Only the servicing provider can configure continuity policy'; end if;
  if p_continuity_mode <> 'none' and not v_module.enabled then raise exception 'Continuity requires an enabled agreement module'; end if;
  insert into public.service_agreement_continuity_policies(service_agreement_location_id,service_agreement_module_id,continuity_mode,client_coverage_start,client_coverage_end,provider_coverage_start,provider_coverage_end,share_active_cases,share_open_tasks,share_recent_history_hours,share_attachments_mode,share_presence_mode,require_handoff_ack,continuity_retention_hours,created_by,updated_by)
  values(p_service_agreement_location_id,p_service_agreement_module_id,p_continuity_mode,p_client_coverage_start,p_client_coverage_end,p_provider_coverage_start,p_provider_coverage_end,p_share_active_cases,p_share_open_tasks,p_share_recent_history_hours,p_share_attachments_mode,p_share_presence_mode,p_require_handoff_ack,p_continuity_retention_hours,v_actor,v_actor)
  on conflict(service_agreement_location_id,service_agreement_module_id) do update set continuity_mode=excluded.continuity_mode,client_coverage_start=excluded.client_coverage_start,client_coverage_end=excluded.client_coverage_end,provider_coverage_start=excluded.provider_coverage_start,provider_coverage_end=excluded.provider_coverage_end,share_active_cases=excluded.share_active_cases,share_open_tasks=excluded.share_open_tasks,share_recent_history_hours=excluded.share_recent_history_hours,share_attachments_mode=excluded.share_attachments_mode,share_presence_mode=excluded.share_presence_mode,require_handoff_ack=excluded.require_handoff_ack,continuity_retention_hours=excluded.continuity_retention_hours,updated_by=v_actor,updated_at=clock_timestamp()
  returning * into v_row;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values((select provider_organization_id from public.service_agreements where id=v_location.service_agreement_id),v_actor,'service_agreement_continuity_policy_managed','service_agreement_continuity_policies',v_row.id,jsonb_build_object('agreement_location_id',v_location.id,'agreement_module_id',v_module.id,'mode',v_row.continuity_mode));
  return v_row;
end; $function$;
REVOKE ALL ON FUNCTION "public"."manage_service_agreement_continuity_policy"(p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_continuity_mode text, p_client_coverage_start time without time zone, p_client_coverage_end time without time zone, p_provider_coverage_start time without time zone, p_provider_coverage_end time without time zone, p_share_active_cases boolean, p_share_open_tasks boolean, p_share_recent_history_hours integer, p_share_attachments_mode text, p_share_presence_mode text, p_require_handoff_ack boolean, p_continuity_retention_hours integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."manage_service_agreement_continuity_policy"(p_service_agreement_location_id uuid, p_service_agreement_module_id uuid, p_continuity_mode text, p_client_coverage_start time without time zone, p_client_coverage_end time without time zone, p_provider_coverage_start time without time zone, p_provider_coverage_end time without time zone, p_share_active_cases boolean, p_share_open_tasks boolean, p_share_recent_history_hours integer, p_share_attachments_mode text, p_share_presence_mode text, p_require_handoff_ack boolean, p_continuity_retention_hours integer) TO "postgres";
