CREATE OR REPLACE FUNCTION "public"."patrol_checkpoints_geometry_guard"()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.radius_meters IS NULL OR NEW.radius_meters < 1 OR NEW.radius_meters > 500 THEN
    RAISE EXCEPTION 'Checkpoint radius must be between 1 and 500 metres';
  END IF;
  IF (NEW.gps_lat IS NULL) <> (NEW.gps_lng IS NULL) THEN
    RAISE EXCEPTION 'Checkpoint position needs both latitude and longitude';
  END IF;
  IF NEW.gps_lat IS NOT NULL AND (NEW.gps_lat NOT BETWEEN -90 AND 90 OR NEW.gps_lng NOT BETWEEN -180 AND 180) THEN
    RAISE EXCEPTION 'Checkpoint position is out of range';
  END IF;
  IF TG_OP = 'INSERT'
     OR (NEW.gps_lat, NEW.gps_lng, NEW.radius_meters) IS DISTINCT FROM (OLD.gps_lat, OLD.gps_lng, OLD.radius_meters) THEN
    NEW.checkpoint_verification := 'unverified';
    NEW.checkpoint_verified_by := NULL;
    NEW.checkpoint_verified_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."patrol_checkpoints_geometry_guard"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid)
 RETURNS TABLE(stop_id uuid, site_id uuid, zone_id uuid, lat double precision, lng double precision, place_type text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select
    ss.id as stop_id,
    ss.site_id,
    ss.zone_id,
    case
      when ss.site_id is not null then cs.gps_lat
      when ss.zone_id is not null then st_y(lz.center_point::geometry)
      else null
    end as lat,
    case
      when ss.site_id is not null then cs.gps_lng
      when ss.zone_id is not null then st_x(lz.center_point::geometry)
      else null
    end as lng,
    case
      when ss.site_id is not null then 'site'
      when ss.zone_id is not null then 'zone'
      else 'unknown'
    end as place_type
  from public.shift_stops ss
  left join public.client_sites   cs on cs.id = ss.site_id
  left join public.location_zones lz on lz.id = ss.zone_id
  where ss.shift_id = p_shift_id
    and ss.status in ('pending', 'en_route')
  order by ss.stop_order;
$function$;
COMMENT ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) IS 'Resolves each pending/en_route shift stop coordinate to plain lat/lng regardless of place type: site_id -> client_sites.gps_*, zone_id -> ST_Y/ST_X(location_zones.center_point). Unified stop model (!709); lets the patrol engine read zone-stops (which client_sites!inner previously dropped).';
REVOKE ALL ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_coords"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid)
 RETURNS SETOF text
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select module_key
  from public.shift_stop_modules
  where shift_stop_id = p_stop_id
  order by module_key;
$function$;
COMMENT ON FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid) IS 'Returns the module_key list for a shift stop from shift_stop_modules (canonical many-modules-per-stop, unified stop model !709). The engine/solver should carry all of these, not just the legacy singular shift_stops.module_key.';
REVOKE ALL ON FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."patrol_stop_module_keys"(p_stop_id uuid) TO "anon";
