CREATE OR REPLACE FUNCTION "public"."preview_batch_publish_roster_slots"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(draft_count integer, leave_conflict_count integer, unassigned_count integer, field_shift_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Active roster administrator required'; end if;
  return query
  select count(*)::integer,
    count(*) filter (where s.staff_id is not null and exists (select 1 from public.leave_requests l where l.staff_id = s.staff_id and l.status = 'approved' and daterange(l.starts_on, l.ends_on, '[]') && daterange(s.scheduled_start::date, s.scheduled_end::date, '[]')))::integer,
    count(*) filter (where s.staff_id is null)::integer,
    count(*) filter (where wu.work_unit_type <> 'internal')::integer
  from public.roster_slots s
  join public.roster_work_units wu on wu.id = s.work_unit_id
  where s.organization_id = p_organization_id and s.status = 'draft' and s.scheduled_start >= p_from and s.scheduled_start < p_to;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."preview_batch_publish_roster_slots"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."preview_batch_publish_roster_slots"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."preview_batch_publish_roster_slots"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."preview_batch_publish_roster_slots"(p_organization_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."preview_roster_from_templates"(p_organization_id uuid, p_from_date date, p_to_date date)
 RETURNS TABLE(templates_applied integer, candidate_slots integer, existing_slots integer, new_slots integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_unit_id uuid; v_templates integer := 0; v_candidates integer := 0; v_existing integer := 0;
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Active roster administrator required'; end if;
  if p_from_date is null or p_to_date is null or p_from_date > p_to_date or p_to_date - p_from_date > 92 then raise exception 'Preview period must be between 1 and 93 days'; end if;
  select wu.id into v_unit_id from public.roster_work_units wu where wu.organization_id = p_organization_id and wu.active order by wu.name limit 1;
  if v_unit_id is null then raise exception 'Active work unit required to preview roster slots'; end if;
  with candidates as (
    select st.id, d.day::date as roster_date, st.start_time, st.end_time
    from public.shift_templates st cross join lateral generate_series(p_from_date, p_to_date, interval '1 day') d(day)
    where st.organization_id = p_organization_id and st.is_active and extract(isodow from d.day)::integer = any(st.active_days)
  ), counted as (
    select c.*, exists(select 1 from public.roster_slots rs where rs.organization_id = p_organization_id and rs.work_unit_id = v_unit_id and rs.scheduled_start = c.roster_date + c.start_time) as exists_already
    from candidates c
  )
  select count(distinct id)::integer, count(*)::integer, count(*) filter (where exists_already)::integer into v_templates, v_candidates, v_existing from counted;
  return query select v_templates, v_candidates, v_existing, greatest(0, v_candidates - v_existing);
end;
$function$;
REVOKE ALL ON FUNCTION "public"."preview_roster_from_templates"(p_organization_id uuid, p_from_date date, p_to_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."preview_roster_from_templates"(p_organization_id uuid, p_from_date date, p_to_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."preview_roster_from_templates"(p_organization_id uuid, p_from_date date, p_to_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."preview_roster_from_templates"(p_organization_id uuid, p_from_date date, p_to_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc_id uuid;
  v_org_id uuid;
  v_class record;
  v_title text := nullif(btrim(coalesce(p_metadata->>'title', '')), '');
  v_publisher text := nullif(btrim(coalesce(p_metadata->>'publisher', '')), '');
  v_doc_type text := nullif(btrim(coalesce(p_metadata->>'document_type', '')), '');
  v_effective text := coalesce(p_metadata->>'effective_from', p_metadata->>'version_label');
  v_is_global boolean := (p_target_scope = 'global_reference');
  v_entry_id uuid;
begin
  if p_target_scope not in ('global_reference','tenant_reference') then
    return jsonb_build_object('ok', false, 'error', 'target_scope must be global_reference or tenant_reference');
  end if;

  select dv.document_id, d.organization_id
  into v_doc_id, v_org_id
  from public.document_versions dv
  join public.documents d on d.id = dv.document_id
  where dv.id = p_document_version_id;

  if v_doc_id is null then
    return jsonb_build_object('ok', false, 'error', 'document_version not found');
  end if;

  -- Latest classification is required before any promotion.
  select * into v_class
  from public.document_classifications
  where document_version_id = p_document_version_id
  order by created_at desc
  limit 1;

  if v_class is null then
    return jsonb_build_object('ok', false, 'error', 'document must be classified before promotion');
  end if;

  -- HARD routing rules for global promotion.
  if v_is_global then
    if v_class.privacy_class not in ('public','internal_non_sensitive') then
      return jsonb_build_object('ok', false, 'error',
        format('privacy_class %s is not eligible for global reference; tenant-scope only', v_class.privacy_class));
    end if;
    if v_class.contains_pii or v_class.contains_financial_data or v_class.contains_legal_privilege then
      return jsonb_build_object('ok', false, 'error', 'document flagged PII/financial/legal-privilege; global promotion blocked');
    end if;
    -- Require human review OR confident, unambiguous classification.
    if v_class.classifier_source <> 'human_review'
       and coalesce(v_class.confidence, 0) < 0.85 then
      return jsonb_build_object('ok', false, 'error', 'low-confidence classification requires human review before global promotion');
    end if;
    -- Provenance floor for durable global references.
    if v_title is null or v_publisher is null or v_doc_type is null or v_effective is null then
      return jsonb_build_object('ok', false, 'error', 'global promotion requires title, publisher, document_type and effective date/version');
    end if;
  end if;

  -- Physical bytes stay put; routing is logical (update scope + catalogue).
  update public.documents
  set current_scope = case when v_is_global then 'global_reference' else 'tenant' end
  where id = v_doc_id;

  insert into public.reference_catalog_entries (
    document_version_id, organization_id, title, topic, publisher, jurisdiction,
    document_type, trust_level, searchable_tags, is_global_reference,
    approval_status, approved_by, approved_at
  ) values (
    p_document_version_id,
    case when v_is_global then null else v_org_id end,
    coalesce(v_title, 'Untitled document'),
    p_metadata->>'topic',
    v_publisher,
    p_metadata->>'jurisdiction',
    v_doc_type,
    coalesce(nullif(p_metadata->>'trust_level',''), 'provisional'),
    coalesce((select array_agg(value::text) from jsonb_array_elements_text(coalesce(p_metadata->'searchable_tags','[]'::jsonb))), '{}'),
    v_is_global,
    'approved',
    p_approver_id,
    now()
  )
  returning id into v_entry_id;

  return jsonb_build_object(
    'ok', true,
    'catalog_entry_id', v_entry_id,
    'target_scope', p_target_scope,
    'is_global_reference', v_is_global,
    'privacy_class', v_class.privacy_class
  );
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$function$;
COMMENT ON FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb) IS 'Governed promotion of a classified document version to the tenant or global reference library. Hard-rejects global promotion of tenant_sensitive/restricted, PII/financial/legal-privilege, low-confidence/unreviewed, or under-provenanced material. service_role execute only; the edge function verifies the approver is admin/GM first.';
REVOKE ALL ON FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."promote_document_to_reference_library"(p_document_version_id uuid, p_target_scope text, p_approver_id uuid, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."propose_boundary"(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_geojson jsonb, p_source text, p_source_ref jsonb DEFAULT '{}'::jsonb, p_address_candidate jsonb DEFAULT NULL::jsonb, p_zone_type text DEFAULT NULL::text, p_proposed_via text DEFAULT 'workbench'::text)
 RETURNS TABLE(proposal_id uuid, area_m2 numeric, gate_ok boolean, gate_reason text, drift_from_current_m double precision, current_has_boundary boolean, proposed_geojson jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_geom geometry;
  v_area numeric;
  v_gate record;
  v_current geometry;
  v_drift double precision;
  v_zone_type text := p_zone_type;
  v_row public.boundary_proposals%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) AND NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access denied';
  END IF;
  IF p_entity_type NOT IN ('client_site','location_zone','organization','patrol_checkpoint') THEN
    RAISE EXCEPTION 'Unsupported entity_type %', p_entity_type;
  END IF;

  v_geom := ST_Multi(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(p_geojson::text), 4326)));
  IF v_geom IS NULL OR ST_IsEmpty(v_geom) OR NOT ST_IsValid(v_geom) THEN
    RAISE EXCEPTION 'Proposed geometry is empty or invalid';
  END IF;
  IF GeometryType(v_geom) <> 'MULTIPOLYGON' THEN
    RAISE EXCEPTION 'Proposed geometry must be a polygon, got %', GeometryType(v_geom);
  END IF;
  v_area := ST_Area(v_geom::geography);

  IF p_entity_id IS NOT NULL THEN
    IF p_entity_type = 'client_site' THEN
      SELECT boundary INTO v_current FROM public.client_sites WHERE id = p_entity_id;
      v_zone_type := coalesce(v_zone_type, 'site');
    ELSIF p_entity_type = 'location_zone' THEN
      SELECT boundary, coalesce(v_zone_type, zone_type) INTO v_current, v_zone_type FROM public.location_zones WHERE id = p_entity_id;
    ELSIF p_entity_type = 'organization' THEN
      SELECT jurisdiction_geom INTO v_current FROM public.organizations WHERE id = p_entity_id;
      v_zone_type := coalesce(v_zone_type, 'jurisdiction');
    END IF;
    IF v_current IS NOT NULL THEN
      v_drift := ST_HausdorffDistance(ST_Transform(ST_SetSRID(v_current::geometry, 4326), 2193), ST_Transform(ST_SetSRID(v_geom::geometry, 4326), 2193));
    END IF;
  ELSE
    v_zone_type := coalesce(v_zone_type, CASE p_entity_type WHEN 'client_site' THEN 'site' WHEN 'organization' THEN 'jurisdiction' END);
  END IF;

  SELECT * INTO v_gate FROM public.geofence_area_gate(v_area, v_zone_type);

  -- Any older open proposal for the same entity is superseded by this one.
  IF p_entity_id IS NOT NULL THEN
    UPDATE public.boundary_proposals SET status = 'superseded', decided_at = clock_timestamp()
    WHERE entity_type = p_entity_type AND entity_id = p_entity_id AND status = 'proposed';
  END IF;

  INSERT INTO public.boundary_proposals (
    organization_id, entity_type, entity_id, proposed_boundary, center_point, area_m2,
    source, source_ref, address_candidate, zone_type, gate_ok, gate_reason,
    drift_from_current_m, proposed_by, proposed_via
  ) VALUES (
    p_organization_id, p_entity_type, p_entity_id, v_geom, ST_Centroid(v_geom), v_area,
    p_source, coalesce(p_source_ref, '{}'::jsonb), p_address_candidate, v_zone_type, v_gate.ok, v_gate.reason,
    v_drift, v_actor, CASE WHEN p_proposed_via IN ('workbench','batch','bob') THEN p_proposed_via ELSE 'workbench' END
  ) RETURNING * INTO v_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'boundary_proposed', 'boundary_proposals', v_row.id,
    jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id, 'source', p_source,
      'area_m2', round(v_area), 'gate_ok', v_gate.ok, 'gate_reason', v_gate.reason, 'drift_m', v_drift));

  RETURN QUERY SELECT v_row.id, v_area, v_gate.ok, v_gate.reason, v_drift, v_current IS NOT NULL, ST_AsGeoJSON(v_geom)::jsonb;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."propose_boundary"(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_geojson jsonb, p_source text, p_source_ref jsonb, p_address_candidate jsonb, p_zone_type text, p_proposed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."propose_boundary"(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_geojson jsonb, p_source text, p_source_ref jsonb, p_address_candidate jsonb, p_zone_type text, p_proposed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."propose_boundary"(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_geojson jsonb, p_source text, p_source_ref jsonb, p_address_candidate jsonb, p_zone_type text, p_proposed_via text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."propose_boundary"(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_geojson jsonb, p_source text, p_source_ref jsonb, p_address_candidate jsonb, p_zone_type text, p_proposed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."propose_document_promotion"(p_document_version_id uuid, p_target_type text, p_proposed_payload jsonb DEFAULT '{}'::jsonb, p_source_map jsonb DEFAULT '{}'::jsonb)
 RETURNS document_promotion_proposals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_proposal public.document_promotion_proposals%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_target_type NOT IN ('crm_agreement','site_brief','credential','finance_reconciliation','hr_case','evidence_link','investigation_link') THEN
    RAISE EXCEPTION 'Unsupported document promotion target';
  END IF;
  SELECT d.organization_id INTO v_org_id
  FROM public.document_versions dv JOIN public.documents d ON d.id = dv.document_id
  WHERE dv.id = p_document_version_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Document promotion proposal denied'; END IF;
  INSERT INTO public.document_promotion_proposals (organization_id, document_version_id, target_type, proposed_payload, source_map, requested_by)
  VALUES (v_org_id, p_document_version_id, p_target_type, coalesce(p_proposed_payload, '{}'::jsonb), coalesce(p_source_map, '{}'::jsonb), v_actor)
  RETURNING * INTO v_proposal;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'document_promotion_proposed', 'document_promotion_proposals', v_proposal.id,
    jsonb_build_object('document_version_id', p_document_version_id, 'target_type', p_target_type));
  RETURN v_proposal;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."propose_document_promotion"(p_document_version_id uuid, p_target_type text, p_proposed_payload jsonb, p_source_map jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."propose_document_promotion"(p_document_version_id uuid, p_target_type text, p_proposed_payload jsonb, p_source_map jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."propose_document_promotion"(p_document_version_id uuid, p_target_type text, p_proposed_payload jsonb, p_source_map jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."propose_document_promotion"(p_document_version_id uuid, p_target_type text, p_proposed_payload jsonb, p_source_map jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."publish_location_event_continuity"(p_client_request_id uuid, p_location_event_id uuid, p_safe_summary text, p_severity text DEFAULT 'standard'::text, p_hazard_flags jsonb DEFAULT '[]'::jsonb, p_action_required text DEFAULT NULL::text)
 RETURNS operational_continuity_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid(); v_event public.location_events%rowtype; v_policy public.service_agreement_continuity_policies%rowtype; v_agreement public.service_agreements%rowtype; v_recipient uuid; v_item public.operational_continuity_items%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select * into v_event from public.location_events where id=p_location_event_id for update;
  if not found or not public.is_admin_for_org(v_event.organization_id) then raise exception 'Event not found in your organization'; end if;
  select policy.* into v_policy from public.service_agreement_continuity_policies policy join public.service_agreement_locations location on location.id=policy.service_agreement_location_id join public.service_agreement_modules module on module.id=policy.service_agreement_module_id and module.service_agreement_id=location.service_agreement_id and module.enabled and module.module_key=v_event.module_key join public.service_agreements agreement on agreement.id=location.service_agreement_id and agreement.invitation_status='accepted' where policy.continuity_mode in ('live_read','live_read_and_receive') and (location.site_id=v_event.client_site_id or location.zone_id=v_event.zone_id) and (agreement.provider_organization_id=v_event.organization_id or agreement.client_organization_id=v_event.organization_id) order by policy.updated_at desc limit 1;
  if not found then raise exception 'No active continuity policy covers this event location and module'; end if;
  select * into v_agreement from public.service_agreements where id = (select service_agreement_id from public.service_agreement_locations where id = v_policy.service_agreement_location_id);
  if v_event.organization_id=v_agreement.provider_organization_id then
    if not public.continuity_party_on_duty(v_policy.provider_coverage_start,v_policy.provider_coverage_end,v_event.occurred_at) then raise exception 'Provider coverage window is not active'; end if;
    v_recipient:=v_agreement.client_organization_id;
  else
    if not public.continuity_party_on_duty(v_policy.client_coverage_start,v_policy.client_coverage_end,v_event.occurred_at) then raise exception 'Client coverage window is not active'; end if;
    v_recipient:=v_agreement.provider_organization_id;
  end if;
  insert into public.operational_continuity_items(policy_id,service_agreement_id,source_organization_id,recipient_organization_id,source_location_event_id,client_site_id,zone_id,module_key,severity,safe_summary,hazard_flags,action_required,source_occurred_at,expires_at,created_by)
  values(v_policy.id,v_agreement.id,v_event.organization_id,v_recipient,v_event.id,v_event.client_site_id,v_event.zone_id,v_event.module_key,p_severity,trim(p_safe_summary),coalesce(p_hazard_flags,'[]'::jsonb),nullif(trim(coalesce(p_action_required,'')),''),v_event.occurred_at,v_event.occurred_at+(v_policy.continuity_retention_hours||' hours')::interval,v_actor)
  on conflict(source_location_event_id,recipient_organization_id) do update set safe_summary=excluded.safe_summary,severity=excluded.severity,hazard_flags=excluded.hazard_flags,action_required=excluded.action_required,operational_status='active',expires_at=excluded.expires_at
  returning * into v_item;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_event.organization_id,v_actor,'location_event_continuity_published','operational_continuity_items',v_item.id,jsonb_build_object('location_event_id',v_event.id,'recipient_organization_id',v_recipient,'policy_id',v_policy.id));
  return v_item;
end; $function$;
REVOKE ALL ON FUNCTION "public"."publish_location_event_continuity"(p_client_request_id uuid, p_location_event_id uuid, p_safe_summary text, p_severity text, p_hazard_flags jsonb, p_action_required text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."publish_location_event_continuity"(p_client_request_id uuid, p_location_event_id uuid, p_safe_summary text, p_severity text, p_hazard_flags jsonb, p_action_required text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."publish_location_event_continuity"(p_client_request_id uuid, p_location_event_id uuid, p_safe_summary text, p_severity text, p_hazard_flags jsonb, p_action_required text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."publish_location_event_continuity"(p_client_request_id uuid, p_location_event_id uuid, p_safe_summary text, p_severity text, p_hazard_flags jsonb, p_action_required text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."purge_aam_e2e_dataset"(p_provider_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id constant uuid := 'a1000000-0000-4000-8000-000000000001';
  v_agreement_id constant uuid := 'a1000000-0000-4000-8000-000000000004';
  v_location_id constant uuid := 'a1000000-0000-4000-8000-000000000002';
  v_site_id constant uuid := 'a1000000-0000-4000-8000-000000000003';
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=v_account_id AND (o.parent_organization_id IS DISTINCT FROM p_provider_organization_id OR o.external_refs->>'dataset' IS DISTINCT FROM 'aam_e2e_20260831')) THEN RAISE EXCEPTION 'AAM dataset identity collision'; END IF;
  PERFORM set_config('app.place_delete_scope', 'test_dataset_purge', true);
  DELETE FROM public.debrief_followups WHERE shift_id IN (SELECT id FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%');
  DELETE FROM public.shift_debriefs WHERE shift_id IN (SELECT id FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%');
  DELETE FROM public.finance_service_item_consumption WHERE shift_id IN (SELECT id FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%');
  DELETE FROM public.finance_inventory_transactions WHERE shift_id IN (SELECT id FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%');
  DELETE FROM public.finance_service_costs WHERE shift_id IN (SELECT id FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%');
  DELETE FROM public.observations WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR site_id=v_site_id;
  DELETE FROM public.breach_alerts WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.breach_records WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.enforcement_cases WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.infringement_notices WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.notices_to_vacate WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.parking_sessions WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.patrol_checkpoint_visits WHERE checkpoint_id IN (SELECT id FROM public.patrol_checkpoints WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id));
  DELETE FROM public.patrol_checkpoints WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.patrols WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.vehicle_overnight_sessions WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.officer_field_reports WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.officer_gps_log WHERE detected_zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.location_events WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR client_site_id=v_site_id;
  DELETE FROM public.location_notes WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR site_id=v_site_id;
  DELETE FROM public.zone_compliance_matrix WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.zone_legal_config WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.zone_signage_evidence WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.client_site_patrol_config WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR site_id=v_site_id;
  DELETE FROM public.site_services WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR site_id=v_site_id;
  DELETE FROM public.site_financial_config WHERE zone_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id) OR site_id=v_site_id;
  DELETE FROM public.shifts WHERE organization_id=p_provider_organization_id AND notes LIKE '[AAM E2E]%';
  DELETE FROM public.roster_slots WHERE organization_id=p_provider_organization_id AND (notes LIKE '[AAM E2E]%' OR work_unit_id IN (SELECT id FROM public.roster_work_units WHERE organization_id=p_provider_organization_id AND name LIKE '[AAM E2E]%'));
  DELETE FROM public.shift_templates WHERE organization_id=p_provider_organization_id AND name LIKE '[AAM E2E]%';
  DELETE FROM public.roster_work_units WHERE organization_id=p_provider_organization_id AND name LIKE '[AAM E2E]%';
  DELETE FROM public.invoice_line_items WHERE invoice_id IN (SELECT id FROM public.invoices WHERE client_organization_id=v_account_id);
  DELETE FROM public.invoices WHERE client_organization_id=v_account_id;
  DELETE FROM public.crm_activation_handoff_tasks t USING public.crm_activation_handoffs h WHERE t.handoff_id=h.id AND h.account_organization_id=v_account_id;
  DELETE FROM public.crm_activation_handoffs WHERE account_organization_id=v_account_id;
  DELETE FROM public.crm_onboarding_events WHERE account_organization_id=v_account_id;
  DELETE FROM public.crm_onboarding_ledgers WHERE account_organization_id=v_account_id;
  DELETE FROM public.geofence_boundary_history WHERE (entity_type='client_site' AND entity_id=v_site_id) OR (entity_type='location_zone' AND entity_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id));
  DELETE FROM public.service_agreement_locations WHERE service_agreement_id=v_agreement_id;
  DELETE FROM public.service_agreement_modules WHERE service_agreement_id=v_agreement_id;
  DELETE FROM public.crm_commercial_settings WHERE service_agreement_id=v_agreement_id;
  DELETE FROM public.crm_contacts WHERE organization_id=v_account_id;
  DELETE FROM public.canonical_place_links WHERE source_table='location_zones' AND source_id IN (SELECT id FROM public.location_zones WHERE location_id=v_location_id);
  DELETE FROM public.canonical_place_links WHERE (source_table='client_sites' AND source_id=v_site_id) OR (source_table='locations' AND source_id=v_location_id);
  DELETE FROM public.location_zones WHERE location_id=v_location_id;
  DELETE FROM public.client_sites WHERE id=v_site_id;
  DELETE FROM public.locations WHERE id=v_location_id;
  DELETE FROM public.service_agreements WHERE id=v_agreement_id;
  DELETE FROM public.organizations WHERE id=v_account_id;
  RETURN jsonb_build_object('purged',true,'dataset','aam_e2e_20260831');
END;
$function$;
REVOKE ALL ON FUNCTION "public"."purge_aam_e2e_dataset"(p_provider_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."purge_aam_e2e_dataset"(p_provider_organization_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."purge_aam_e2e_dataset"(p_provider_organization_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."queue_dispatch_job_for_officer"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_officer_user_id uuid, p_work_unit_id uuid, p_module_key text, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, status text, assigned_officer_id uuid, work_unit_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_job record; v_unit public.roster_work_units%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN RAISE EXCEPTION 'Active organization administrator required'; END IF;
  SELECT * INTO v_unit FROM public.roster_work_units WHERE roster_work_units.id=p_work_unit_id AND roster_work_units.organization_id=p_organization_id AND roster_work_units.active FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active work unit is required'; END IF;
  IF v_unit.service_type IS DISTINCT FROM p_module_key THEN RAISE EXCEPTION 'Work unit module does not match requested module'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles u
    JOIN public.service_agreements sa ON sa.id=p_service_agreement_id
    JOIN public.organizations officer_org ON officer_org.id=u.organization_id
    WHERE u.id=p_officer_user_id AND u.deactivated_at IS NULL AND u.role IN ('officer','admin_officer')
      AND (officer_org.id=sa.provider_organization_id OR sa.provider_organization_id=ANY(public.get_descendant_organizations(officer_org.id)))
  ) THEN RAISE EXCEPTION 'Target officer is not authorized for this service agreement'; END IF;
  SELECT * INTO v_job FROM public.create_dispatch_job(p_organization_id,p_service_agreement_id,p_client_site_id,p_client_request_id,p_job_type,p_priority,p_sla_minutes,NULL,p_briefing_notes,NULL);
  UPDATE public.dispatch_jobs AS job
    SET assigned_officer_id=p_officer_user_id, work_unit_id=p_work_unit_id, module_key=p_module_key
    WHERE job.id=v_job.id;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(p_organization_id,v_actor,'dispatch_job_queued_for_officer','dispatch_jobs',v_job.id,jsonb_build_object('officer_user_id',p_officer_user_id,'work_unit_id',p_work_unit_id,'module_key',p_module_key,'roster_independent',true));
  RETURN QUERY SELECT v_job.id,v_job.created,v_job.status,p_officer_user_id,p_work_unit_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."queue_dispatch_job_for_officer"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_officer_user_id uuid, p_work_unit_id uuid, p_module_key text, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."queue_dispatch_job_for_officer"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_officer_user_id uuid, p_work_unit_id uuid, p_module_key text, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."queue_dispatch_job_for_officer"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_officer_user_id uuid, p_work_unit_id uuid, p_module_key text, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."queue_dispatch_job_for_officer"(p_organization_id uuid, p_service_agreement_id uuid, p_client_site_id uuid, p_client_request_id uuid, p_officer_user_id uuid, p_work_unit_id uuid, p_module_key text, p_job_type text, p_priority text, p_sla_minutes integer, p_briefing_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."raise_entity_flag"(p_client_request_id uuid, p_entity_type text, p_entity_id uuid, p_flag_type text, p_alert_level text, p_reason text, p_hazard_class text DEFAULT NULL::text)
 RETURNS entity_flags
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_org uuid;
  v_entity record;
  v_flag public.entity_flags%rowtype;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_flag_type text := nullif(lower(trim(coalesce(p_flag_type, ''))), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select organization_id into v_org from public.user_profiles where id = v_actor and deactivated_at is null;
  if v_org is null then raise exception 'Active user required'; end if;
  select * into v_flag from public.entity_flags where organization_id = v_org and client_request_id = p_client_request_id;
  if found then return v_flag; end if;

  select * into v_entity from public.resolve_flag_entity(p_entity_type, p_entity_id);
  if v_entity.entity_type = 'vehicle' and not exists (select 1 from public.canonical_vehicles v where v.id = v_entity.entity_id) then raise exception 'Vehicle not found'; end if;
  if v_entity.entity_type = 'person' and not exists (select 1 from public.canonical_people p where p.id = v_entity.entity_id) then raise exception 'Person not found'; end if;
  if v_entity.entity_type = 'place' and not exists (select 1 from public.canonical_places p where p.id = v_entity.entity_id) then raise exception 'Place not found'; end if;
  if p_alert_level not in ('low', 'medium', 'high', 'critical') then raise exception 'Severity must be low, medium, high or critical'; end if;
  if v_flag_type is null then v_flag_type := case when p_hazard_class is not null then 'safety_warning' else 'watchlist' end; end if;
  if p_hazard_class is not null and v_reason is null then raise exception 'A safety warning needs a short note of what to expect'; end if;

  insert into public.entity_flags (organization_id, entity_type, entity_id, flag_type, alert_level, reason, hazard_class, active, raised_by, client_request_id)
  values (v_org, v_entity.entity_type, v_entity.entity_id, v_flag_type, p_alert_level, v_reason, p_hazard_class, true, v_actor, p_client_request_id)
  returning * into v_flag;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_org, v_actor, case when p_hazard_class is null then 'entity_flag_raised' else 'safety_warning_raised' end, 'entity_flags', v_flag.id,
          jsonb_build_object('entity_type', v_flag.entity_type, 'entity_id', v_flag.entity_id, 'flag_type', v_flag.flag_type, 'alert_level', v_flag.alert_level, 'hazard_class', v_flag.hazard_class, 'client_request_id', p_client_request_id));
  return v_flag;
end;
$function$;
COMMENT ON FUNCTION "public"."raise_entity_flag"(p_client_request_id uuid, p_entity_type text, p_entity_id uuid, p_flag_type text, p_alert_level text, p_reason text, p_hazard_class text) IS 'Raise an of-interest flag, or (with p_hazard_class) a platform-wide safety warning, on a vehicle / person / place / site / zone for the caller''s organisation. Any active member may raise; idempotent on client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."raise_entity_flag"(p_client_request_id uuid, p_entity_type text, p_entity_id uuid, p_flag_type text, p_alert_level text, p_reason text, p_hazard_class text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."raise_entity_flag"(p_client_request_id uuid, p_entity_type text, p_entity_id uuid, p_flag_type text, p_alert_level text, p_reason text, p_hazard_class text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."raise_entity_flag"(p_client_request_id uuid, p_entity_type text, p_entity_id uuid, p_flag_type text, p_alert_level text, p_reason text, p_hazard_class text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."raise_officer_sos"(p_client_request_id uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(alert_id uuid, triggered_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_alert public.welfare_alerts%rowtype;v_at timestamptz:=clock_timestamp();
begin
 if v_actor is null or p_client_request_id is null then raise exception 'Authentication and client_request_id are required';end if;
 select organization_id into v_org from public.user_profiles where id=v_actor and deactivated_at is null;if v_org is null then raise exception 'Active officer identity required';end if;
 if p_shift_id is not null and not exists(select 1 from public.shifts s where s.id=p_shift_id and s.organization_id=v_org and s.officer_user_id=v_actor and s.status='in_progress') then raise exception 'SOS shift must be your active shift';end if;
 select * into v_alert from public.welfare_alerts where organization_id=v_org and officer_user_id=v_actor and client_request_id=p_client_request_id;if found then return query select v_alert.id,v_alert.triggered_at,false;return;end if;
 insert into public.welfare_alerts(organization_id,officer_user_id,shift_id,alert_type,status,triggered_at,last_activity_at,gps_lat,gps_lng,escalation_level,notes,client_request_id) values(v_org,v_actor,p_shift_id,'sos','pending',v_at,v_at,p_gps_lat,p_gps_lng,1,nullif(trim(coalesce(p_notes,'')),'SOS triggered by officer'),p_client_request_id) returning * into v_alert;
 perform public.enqueue_notification(v_org,'welfare','Officer SOS', 'An officer has triggered SOS. Open the welfare alert immediately.','critical',null,'admin','welfare-outcome',jsonb_build_object('welfare_alert_id',v_alert.id),'officer_sos:'||v_alert.id::text);
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'officer_sos_raised','welfare_alerts',v_alert.id,jsonb_build_object('shift_id',p_shift_id,'client_request_id',p_client_request_id));
 return query select v_alert.id,v_alert.triggered_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."raise_officer_sos"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_sos"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_sos"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_sos"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."raise_officer_welfare_alert"(p_client_request_id uuid, p_alert_type text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(alert_id uuid, triggered_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_alert public.welfare_alerts%rowtype;v_at timestamptz:=clock_timestamp();
begin
 if v_actor is null or p_client_request_id is null then raise exception 'Authentication and client_request_id are required';end if;
 if p_alert_type not in ('sos','man_down','inactivity','gps_lost','missed') then raise exception 'Unsupported officer welfare alert type';end if;
 select organization_id into v_org from public.user_profiles where id=v_actor and deactivated_at is null;if v_org is null then raise exception 'Active officer identity required';end if;
 if p_shift_id is not null and not exists(select 1 from public.shifts s where s.id=p_shift_id and s.organization_id=v_org and s.officer_user_id=v_actor and s.status='in_progress') then raise exception 'Welfare alert shift must be your active shift';end if;
 select * into v_alert from public.welfare_alerts where organization_id=v_org and officer_user_id=v_actor and client_request_id=p_client_request_id;if found then return query select v_alert.id,v_alert.triggered_at,false;return;end if;
 insert into public.welfare_alerts(organization_id,officer_user_id,shift_id,alert_type,status,triggered_at,last_activity_at,gps_lat,gps_lng,escalation_level,notes,client_request_id)
 values(v_org,v_actor,p_shift_id,p_alert_type,'pending',v_at,v_at,p_gps_lat,p_gps_lng,1,nullif(trim(coalesce(p_notes,'')),''),p_client_request_id) returning * into v_alert;
 perform public.enqueue_notification(v_org,'welfare',case when p_alert_type='sos' then 'Officer SOS' else 'Officer welfare alert' end,case when p_alert_type='sos' then 'An officer has triggered SOS. Open the welfare alert immediately.' else 'An officer welfare alert requires review.' end,case when p_alert_type='sos' then 'critical' else 'warning' end,null,'admin','welfare-outcome',jsonb_build_object('welfare_alert_id',v_alert.id),'officer_welfare_alert:'||v_alert.id::text);
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'officer_welfare_alert_raised','welfare_alerts',v_alert.id,jsonb_build_object('alert_type',p_alert_type,'shift_id',p_shift_id,'client_request_id',p_client_request_id));
 return query select v_alert.id,v_alert.triggered_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."raise_officer_welfare_alert"(p_client_request_id uuid, p_alert_type text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_welfare_alert"(p_client_request_id uuid, p_alert_type text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_welfare_alert"(p_client_request_id uuid, p_alert_type text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."raise_officer_welfare_alert"(p_client_request_id uuid, p_alert_type text, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text)
 RETURNS TABLE(slot_id uuid, slot_status text, staff_id uuid, shift_id uuid, shift_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_slot public.roster_slots%rowtype;v_unit public.roster_work_units%rowtype;v_staff public.staff_profiles%rowtype;v_shift public.shifts%rowtype;v_old_staff_id uuid;v_new_status text;
begin
  select s.* into v_slot from public.roster_slots s where s.id=p_slot_id for update;if not found then raise exception 'Roster slot not found';end if;
  if not public.is_admin_for_org(v_slot.organization_id) then raise exception 'Not authorised to reassign this roster slot';end if;
  if v_slot.status<>p_expected_status then raise exception 'Roster slot changed from expected status % to %',p_expected_status,v_slot.status;end if;
  if v_slot.status not in('draft','published','accepted','declined') then raise exception 'This roster slot can no longer be reassigned';end if;
  if p_new_staff_id=v_slot.staff_id then raise exception 'Select a different staff member';end if;
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Reassignment reason is required';end if;
  select u.* into v_unit from public.roster_work_units u where u.id=v_slot.work_unit_id and u.organization_id=v_slot.organization_id and u.active;if not found then raise exception 'Active work unit not found';end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.id=p_new_staff_id and sp.organization_id=v_slot.organization_id and sp.work_ready;if not found then raise exception 'Work-ready staff profile required';end if;
  if v_staff.user_id is null or not exists(select 1 from public.user_profiles up where up.id=v_staff.user_id and up.organization_id=v_slot.organization_id and up.deactivated_at is null and up.role in('officer','admin_officer')) then raise exception 'Replacement staff is not an active roster officer';end if;
  if exists(select 1 from public.leave_requests l where l.staff_id=p_new_staff_id and l.status='approved' and daterange(l.starts_on,l.ends_on,'[]')&&daterange(v_slot.scheduled_start::date,v_slot.scheduled_end::date,'[]')) then raise exception 'Replacement staff member has approved leave';end if;
  if exists(select 1 from public.roster_slots s where s.id<>v_slot.id and s.staff_id=p_new_staff_id and s.status not in('declined','cancelled') and s.scheduled_start<v_slot.scheduled_end and s.scheduled_end>v_slot.scheduled_start) then raise exception 'Replacement staff member has an overlapping roster slot';end if;
  if exists(select 1 from public.shifts s where s.id<>coalesce(v_slot.linked_shift_id,'00000000-0000-0000-0000-000000000000'::uuid) and s.officer_user_id=v_staff.user_id and s.status not in('declined','cancelled') and s.scheduled_start<v_slot.scheduled_end and s.scheduled_end>v_slot.scheduled_start) then raise exception 'Replacement officer has an overlapping field shift';end if;
  if v_slot.linked_shift_id is not null then
    select s.* into v_shift from public.shifts s where s.id=v_slot.linked_shift_id for update;if not found then raise exception 'Linked field shift not found';end if;
    if v_shift.status not in('published','accepted','declined') or v_shift.actual_start is not null then raise exception 'Field shift has started or is no longer reassignable';end if;
    if exists(select 1 from public.patrols p where p.shift_id=v_shift.id and p.status='in_progress') then raise exception 'Active patrol prevents reassignment';end if;
    if exists(select 1 from public.dispatch_jobs d where d.shift_id=v_shift.id and d.status in('pending','pending_approval','dispatched','acknowledged','en_route','on_scene')) then raise exception 'Active dispatch work prevents reassignment';end if;
    if exists(select 1 from public.shift_stop_actions a where a.shift_id=v_shift.id) then raise exception 'Recorded field activity prevents reassignment';end if;
    update public.shifts sh set officer_user_id=v_staff.user_id,status='published',notes=concat_ws(E'\n',nullif(sh.notes,''),'Reassigned: '||trim(p_reason)) where sh.id=v_shift.id returning sh.* into v_shift;
  end if;
  v_old_staff_id:=v_slot.staff_id;v_new_status:=case when v_slot.status='draft' then 'draft' else 'published' end;
  update public.roster_slots rs set staff_id=p_new_staff_id,status=v_new_status,notes=concat_ws(E'\n',nullif(rs.notes,''),'Reassigned: '||trim(p_reason)) where rs.id=v_slot.id returning rs.* into v_slot;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_slot.organization_id,v_actor,'roster_slot_reassigned','roster_slots',v_slot.id,jsonb_build_object('work_unit_id',v_unit.id,'old_staff_id',v_old_staff_id,'new_staff_id',p_new_staff_id,'linked_shift_id',v_slot.linked_shift_id,'reason',trim(p_reason)));
  return query select v_slot.id,v_slot.status,v_slot.staff_id,v_slot.linked_shift_id,case when v_shift.id is null then null else v_shift.status end;
end;$function$;
REVOKE ALL ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reassign_roster_slot"(p_slot_id uuid, p_expected_status text, p_new_staff_id uuid, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer DEFAULT 1000)
 RETURNS TABLE(scanned_rows integer, linked_rows integer, unresolved_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scanned_rows integer;
  v_linked_rows integer;
  v_unresolved_rows integer;
begin
  with candidates as (
    select raw.source_id,
      coalesce(nullif(btrim(raw.normalized_plate), ''), nullif(regexp_replace(upper(coalesce(raw.rego, '')), '[^A-Z0-9]', '', 'g'), '')) as plate
    from public._seed_downer_linz_vehicle_log_raw raw
    where raw.processed_at is null
      and raw.canonical_vehicle_id is null
    order by raw.created_at, raw.source_id
    limit greatest(1, least(coalesce(p_limit, 1000), 5000))
  ), reconciled as (
    select candidate.source_id, vehicle.id as vehicle_id
    from candidates candidate
    left join public.canonical_vehicles vehicle on vehicle.plate_number = candidate.plate
  ), updated as (
    update public._seed_downer_linz_vehicle_log_raw raw
    set canonical_vehicle_id = reconciled.vehicle_id,
      processed_at = now(),
      error = case when reconciled.vehicle_id is null then 'No exact canonical vehicle match' else null end
    from reconciled
    where raw.source_id = reconciled.source_id
    returning reconciled.vehicle_id
  )
  select count(*)::integer,
    count(*) filter (where vehicle_id is not null)::integer,
    count(*) filter (where vehicle_id is null)::integer
  into v_scanned_rows, v_linked_rows, v_unresolved_rows
  from updated;

  return query select v_scanned_rows, v_linked_rows, v_unresolved_rows;
end;
$function$;
COMMENT ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) IS 'Service-role staging reconciliation: links Downer/LINZ rows to exact existing canonical vehicles only. Every attempt is marked processed; unmatched rows retain a review reason and it never creates observations or vehicles.';
REVOKE ALL ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reconcile_downer_linz_vehicle_log"(p_limit integer) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb DEFAULT '[]'::jsonb, p_transactions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_request public.finance_external_connection_requests%rowtype; v_item jsonb; v_transactions integer := 0;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.provider_name <> 'ANZ' THEN RAISE EXCEPTION 'ANZ connection request not found'; END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_transactions, '[]'::jsonb)) LOOP
    INSERT INTO public.finance_external_bank_transactions(organization_id, connection_request_id, bank_account_id, external_transaction_id, transaction_date, description, amount, currency_code, direction, raw_summary)
    VALUES (v_request.organization_id, p_request_id, v_request.bank_account_id, COALESCE(v_item->>'id', v_item->>'transaction_id'), NULLIF(v_item->>'date', '')::date, NULLIF(v_item->>'description', ''), NULLIF(v_item->>'amount', '')::numeric, COALESCE(v_item->>'currency', 'NZD'), CASE WHEN (v_item->>'amount')::numeric >= 0 THEN 'credit' ELSE 'debit' END, v_item)
    ON CONFLICT (connection_request_id, external_transaction_id) DO UPDATE SET transaction_date = EXCLUDED.transaction_date, description = EXCLUDED.description, amount = EXCLUDED.amount, currency_code = EXCLUDED.currency_code, raw_summary = EXCLUDED.raw_summary;
    v_transactions := v_transactions + 1;
  END LOOP;
  UPDATE public.finance_external_connection_requests SET status = 'connected', provider_connection_reference = p_provider_reference, connected_at = now(), last_sync_at = now(), last_error = NULL, updated_at = now() WHERE id = p_request_id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_request.organization_id, NULL, 'anz_transactions_imported', 'finance_external_bank_transactions', p_request_id, jsonb_build_object('transaction_count', v_transactions, 'credentials_stored', false));
  RETURN jsonb_build_object('transaction_count', v_transactions, 'account_count', jsonb_array_length(COALESCE(p_accounts, '[]'::jsonb)));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_import"(p_request_id uuid, p_provider_reference text, p_accounts jsonb, p_transactions jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text DEFAULT NULL::text)
 RETURNS finance_akahu_personal_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := p_actor_user_id; v_org uuid; v_check public.finance_akahu_personal_checks%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Personal Akahu adapter execution only'; END IF;
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND role = 'grand_master' AND deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Grandmaster test access required'; END IF;
  INSERT INTO public.finance_akahu_personal_checks(organization_id, requested_by, app_reference, account_count, connected_account_summary, status, error_category)
  VALUES (v_org, v_actor, p_app_reference, COALESCE(p_account_count, 0), COALESCE(p_account_summary, '[]'::jsonb), p_status, p_error_category)
  RETURNING * INTO v_check;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'akahu_personal_test_checked', 'finance_akahu_personal_checks', v_check.id, jsonb_build_object('account_count', v_check.account_count, 'status', v_check.status, 'personal_test_only', true, 'transactions_imported', false));
  RETURN v_check;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_akahu_personal_check"(p_actor_user_id uuid, p_app_reference text, p_account_count integer, p_account_summary jsonb, p_status text, p_error_category text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_reference text DEFAULT NULL::text, p_source_hash text DEFAULT NULL::text)
 RETURNS fuel_price_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source public.fuel_price_sources%rowtype;
  v_row public.fuel_price_observations%rowtype;
  v_url text := nullif(trim(coalesce(p_source_url, '')), '');
  v_base text;
  v_base_origin text;
  v_url_origin text;
  v_next_char text;
begin
  select * into v_source from public.fuel_price_sources where id = p_source_id and organization_id = p_organization_id and active;
  if not found then raise exception 'Choose an active approved fuel price source'; end if;
  v_base := trim(trailing '/' from v_source.source_url);
  if v_url is null or v_url !~ '^https?://' or v_base !~ '^https?://' then
    raise exception 'Observation URL must be a public http(s) URL';
  end if;
  v_base_origin := lower(regexp_replace(v_base, '^https?://([^/]+).*$','\1'));
  v_url_origin := lower(regexp_replace(v_url, '^https?://([^/]+).*$','\1'));
  v_next_char := substr(v_url, length(v_base) + 1, 1);
  if v_url_origin <> v_base_origin or not (v_url = v_base or v_next_char in ('/', '?', '#')) then
    raise exception 'Observation URL must be under the approved source URL';
  end if;
  v_row := public.record_fuel_price_observation(p_client_request_id, p_organization_id, v_source.fuel_type, p_observed_on, p_price_per_litre, v_source.name, v_url, p_source_published_at, p_source_reference, p_source_hash);
  update public.fuel_price_observations set source_id = v_source.id where id = v_row.id returning * into v_row;
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_approved_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_source_id uuid, p_observed_on date, p_price_per_litre numeric, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer DEFAULT NULL::integer, p_fuel_level text DEFAULT NULL::text, p_defects_noted text DEFAULT NULL::text, p_action_required text DEFAULT NULL::text)
 RETURNS asset_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_asset public.assets%rowtype;
  v_check public.asset_checks%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select a.* into v_asset from public.assets a where a.id = p_asset_id for update;
  if not found then
    raise exception 'Asset not found';
  end if;

  if not public.org_access_allowed(v_asset.organization_id) then
    raise exception 'Not authorised to check this asset';
  end if;

  if p_check_type not in ('pre_shift', 'post_shift', 'weekly', 'monthly', 'defect_report') then
    raise exception 'Unsupported asset check type';
  end if;

  if p_condition not in ('good', 'minor_issue', 'major_issue', 'unserviceable') then
    raise exception 'Unsupported asset condition';
  end if;

  if p_fuel_level is not null and p_fuel_level not in ('full', 'three_quarter', 'half', 'quarter', 'empty') then
    raise exception 'Unsupported fuel level';
  end if;

  insert into public.asset_checks(
    organization_id, asset_id, checked_by, check_type, condition,
    odometer_reading, fuel_level, defects_noted, action_required
  )
  values (
    v_asset.organization_id, v_asset.id, v_actor, p_check_type, p_condition,
    p_odometer_reading, p_fuel_level,
    nullif(trim(coalesce(p_defects_noted, '')), ''),
    nullif(trim(coalesce(p_action_required, '')), '')
  )
  returning * into v_check;

  if p_condition in ('major_issue', 'unserviceable') then
    update public.assets set status = 'maintenance' where id = v_asset.id;
    perform public.enqueue_notification(
      v_asset.organization_id, 'system', 'Asset requires maintenance',
      format('%s reported %s during a %s check.', v_asset.name, replace(p_condition, '_', ' '), replace(p_check_type, '_', ' ')),
      'warning', null, 'admin', 'roster',
      jsonb_build_object('asset_id', v_asset.id, 'asset_check_id', v_check.id),
      'asset_defect:' || v_check.id::text
    );
  end if;

  update public.assets set last_inspection_date = current_date where id = v_asset.id;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_asset.organization_id, v_actor, 'asset_check_recorded', 'asset_checks', v_check.id,
    jsonb_build_object(
      'asset_id', v_asset.id,
      'check_type', p_check_type,
      'condition', p_condition,
      'odometer_reading', p_odometer_reading,
      'client_request_id', p_client_request_id
    )
  );

  return v_check;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_asset_check"(p_client_request_id uuid, p_asset_id uuid, p_check_type text, p_condition text, p_odometer_reading integer, p_fuel_level text, p_defects_noted text, p_action_required text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text)
 RETURNS callout_shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_callout public.callout_shifts%rowtype;
  v_at timestamptz := now();
  v_next_status text;
begin
  select c.* into v_callout from public.callout_shifts c where c.id = p_callout_id for update;
  if not found then
    raise exception 'Callout not found';
  end if;

  if v_callout.officer_user_id <> v_actor and not public.is_admin_for_org(v_callout.organization_id) then
    raise exception 'Only the called-out officer or an administrator can record milestones';
  end if;

  if v_callout.status <> p_expected_status then
    raise exception 'Callout changed from expected status % to %', p_expected_status, v_callout.status;
  end if;

  v_next_status := case p_milestone
    when 'departed' then 'responding'
    when 'arrived' then 'on_site'
    when 'work_started' then 'working'
    when 'work_ended' then 'returning'
    when 'returned' then 'completed'
    else null
  end;

  if v_next_status is null then
    raise exception 'Unsupported callout milestone %', p_milestone;
  end if;

  if array_position(array['raised','responding','on_site','working','returning','completed'], v_next_status)
     <> array_position(array['raised','responding','on_site','working','returning','completed'], v_callout.status) + 1 then
    raise exception 'Callout milestone % cannot follow status %', p_milestone, v_callout.status;
  end if;

  update public.callout_shifts
  set
    status = v_next_status,
    departed_at = case when p_milestone = 'departed' then v_at else departed_at end,
    arrived_at = case when p_milestone = 'arrived' then v_at else arrived_at end,
    work_started_at = case when p_milestone = 'work_started' then v_at else work_started_at end,
    work_ended_at = case when p_milestone = 'work_ended' then v_at else work_ended_at end,
    returned_at = case when p_milestone = 'returned' then v_at else returned_at end
  where id = v_callout.id
  returning * into v_callout;

  if v_next_status = 'completed' then
    update public.on_call_periods set status = 'completed'
    where id = v_callout.on_call_period_id and status = 'accepted';
  end if;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_callout.organization_id, v_actor, 'callout_milestone_recorded', 'callout_shifts', v_callout.id,
    jsonb_build_object('milestone', p_milestone, 'status', v_next_status, 'recorded_at', v_at)
  );

  return v_callout;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_callout_milestone"(p_callout_id uuid, p_milestone text, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_import public.cctv_imports%rowtype; v_n integer;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin')
     AND (v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id)) THEN
    RAISE EXCEPTION 'CCTV import access denied';
  END IF;
  IF jsonb_typeof(p_events) <> 'array' THEN RAISE EXCEPTION 'Events must be an array'; END IF;
  INSERT INTO public.cctv_device_events (cctv_import_id, organization_id, source, source_ref, event_start_at, event_end_at, severity, thumbnail_path, metadata)
  SELECT v_import.id, v_import.organization_id, e->>'source', e->>'source_ref', (e->>'event_start_at')::timestamptz, nullif(e->>'event_end_at', '')::timestamptz,
         coalesce(nullif(e->>'severity', ''), 'motion'), nullif(e->>'thumbnail_path', ''),
         CASE WHEN jsonb_typeof(e->'metadata') = 'object' THEN e->'metadata' ELSE '{}'::jsonb END
  FROM jsonb_array_elements(p_events) e
  WHERE e->>'source' IN ('device_snapshot', 'device_index', 'inference') AND nullif(e->>'source_ref', '') IS NOT NULL AND nullif(e->>'event_start_at', '') IS NOT NULL
    AND coalesce(nullif(e->>'severity', ''), 'motion') IN ('motion', 'detection', 'alert')
  ON CONFLICT (cctv_import_id, source, source_ref) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_device_events"(p_import_id uuid, p_events jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  observation jsonb;
  saved_count integer := 0;
  v_id uuid;
  v_kind text;
  v_import public.cctv_imports%rowtype;
  v_import_id uuid;
  v_face public.vector;
  v_app public.vector;
  v_candidates jsonb;
  v_key uuid;
  v_best_key uuid;
  v_best_score real;
  v_state text;
  v_person_id uuid;
  v_canonical_id uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF jsonb_typeof(p_observations) <> 'array' THEN
    RAISE EXCEPTION 'CCTV entity observations must be an array';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id
      AND domain = 'video_motion'
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;
  SELECT evidence.cctv_import_id
    INTO v_import_id
    FROM public.evidence_items AS evidence
   WHERE evidence.id = p_evidence_id;
  IF v_import_id IS NOT NULL THEN
    SELECT * INTO v_import FROM public.cctv_imports WHERE id = v_import_id;
  END IF;

  FOR observation IN SELECT value FROM jsonb_array_elements(p_observations)
  LOOP
    v_kind := observation->>'entity_kind';
    IF v_kind NOT IN ('person', 'vehicle', 'animal')
       OR NULLIF(observation->>'source_event_id', '') IS NULL
       OR NULLIF(observation->>'observed_at', '') IS NULL THEN
      CONTINUE;
    END IF;
    v_face := CASE WHEN v_kind = 'person' THEN public.cctv_jsonb_to_vector(observation->'candidate_embedding', 128) END;
    v_app := public.cctv_jsonb_to_vector(observation->'appearance_embedding', 256);
    v_id := NULL;

    INSERT INTO public.cctv_entity_observations (
      organization_id, inference_job_id, evidence_item_id, source_event_id, entity_kind,
      observed_at, observed_to, cctv_import_id, location_id, canonical_place_id, site_id, zone_id,
      candidate_label, candidate_plate, animal_type, species_confidence, is_pest,
      candidate_embedding, appearance_embedding, face_vec, appearance_vec,
      model_confidence, quality_state, attributes, frame_sha256, thumbnail
    ) VALUES (
      p_organization_id, p_job_id, p_evidence_id, observation->>'source_event_id', v_kind,
      (observation->>'observed_at')::timestamptz, NULLIF(observation->>'observed_to', '')::timestamptz,
      v_import.id, v_import.location_id, v_import.canonical_place_id,
      COALESCE(v_import.site_id, NULLIF(observation->>'site_id', '')::uuid),
      COALESCE(v_import.zone_id, NULLIF(observation->>'zone_id', '')::uuid),
      NULLIF(observation->>'candidate_label', ''),
      NULLIF(public.normalize_plate_number(observation->>'candidate_plate'), ''),
      NULLIF(lower(observation->>'animal_type'), ''),
      NULLIF(observation->>'species_confidence', '')::real,
      CASE WHEN observation ? 'is_pest' THEN (observation->>'is_pest')::boolean END,
      CASE WHEN jsonb_typeof(observation->'candidate_embedding') = 'array' THEN observation->'candidate_embedding' END,
      CASE WHEN jsonb_typeof(observation->'appearance_embedding') = 'array' THEN observation->'appearance_embedding' END,
      v_face, v_app,
      NULLIF(observation->>'model_confidence', '')::real,
      CASE WHEN observation->>'quality_state' IN ('clear', 'glitch', 'flare', 'ir_switch', 'degraded', 'occluded') THEN observation->>'quality_state' ELSE 'clear' END,
      CASE WHEN jsonb_typeof(observation->'attributes') = 'object' THEN observation->'attributes' ELSE '{}'::jsonb END,
      NULLIF(observation->>'frame_sha256', ''),
      CASE WHEN observation->>'thumbnail' LIKE 'data:image/%' THEN observation->>'thumbnail' ELSE NULL END
    )
    ON CONFLICT (inference_job_id, source_event_id, entity_kind) DO UPDATE SET
      observed_to = EXCLUDED.observed_to,
      candidate_label = EXCLUDED.candidate_label,
      candidate_plate = EXCLUDED.candidate_plate,
      animal_type = EXCLUDED.animal_type,
      species_confidence = EXCLUDED.species_confidence,
      is_pest = EXCLUDED.is_pest,
      candidate_embedding = EXCLUDED.candidate_embedding,
      appearance_embedding = EXCLUDED.appearance_embedding,
      face_vec = EXCLUDED.face_vec,
      appearance_vec = EXCLUDED.appearance_vec,
      model_confidence = EXCLUDED.model_confidence,
      quality_state = EXCLUDED.quality_state,
      attributes = EXCLUDED.attributes,
      frame_sha256 = EXCLUDED.frame_sha256,
      thumbnail = EXCLUDED.thumbnail
    WHERE public.cctv_entity_observations.review_state = 'unreviewed'
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
      CONTINUE;
    END IF;
    saved_count := saved_count + 1;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'match_kind', match.match_kind,
             'match_id', match.match_id,
             'observation_id', match.observation_id,
             'portfolio_key', match.portfolio_key,
             'display_name', match.display_name,
             'score', match.score,
             'basis', match.basis,
             'last_seen_at', match.last_seen_at,
             'plate_number', match.plate_number,
             'person_record_id', match.person_record_id,
            'canonical_vehicle_id', match.canonical_vehicle_id
               ) ORDER BY match.score DESC), '[]'::jsonb)
      INTO v_candidates
      FROM public.find_cctv_portfolio_matches(
        p_organization_id,
        v_kind,
        observation->'candidate_embedding',
        observation->'appearance_embedding',
        observation->>'candidate_plate',
        v_id,
        5
      ) AS match;

    SELECT match.portfolio_key, match.score
      INTO v_best_key, v_best_score
      FROM public.find_cctv_portfolio_matches(
        p_organization_id,
        v_kind,
        observation->'candidate_embedding',
        observation->'appearance_embedding',
        NULL,
        v_id,
        5
      ) AS match
     WHERE match.match_kind = 'observation'
       AND match.portfolio_key IS NOT NULL
       AND match.score >= CASE match.basis WHEN 'face' THEN 0.72 ELSE 0.80 END
     ORDER BY match.score DESC
     LIMIT 1;

    v_key := COALESCE(v_best_key, gen_random_uuid());
    v_state := CASE WHEN jsonb_array_length(v_candidates) > 0 THEN 'candidate' ELSE 'unmatched' END;
    UPDATE public.cctv_entity_observations
       SET portfolio_candidates = v_candidates,
           portfolio_key = COALESCE(portfolio_key, v_key),
           portfolio_state = CASE WHEN portfolio_state IN ('linked', 'new_identity', 'rejected') THEN portfolio_state ELSE v_state END
     WHERE id = v_id;
    SELECT portfolio_key INTO v_key FROM public.cctv_entity_observations WHERE id = v_id;

    IF v_kind = 'person' THEN
      SELECT profile.person_record_id, profile.canonical_person_id
        INTO v_person_id, v_canonical_id
        FROM public.ensure_cctv_person_profile(
          p_organization_id,
          v_key,
          v_id,
          p_evidence_id,
          (observation->>'observed_at')::timestamptz
        ) AS profile;

      UPDATE public.cctv_entity_observations
         SET person_record_id = v_person_id,
             canonical_person_id = v_canonical_id
       WHERE organization_id = p_organization_id
         AND entity_kind = 'person'
         AND portfolio_key = v_key
         AND review_state = 'unreviewed'
         AND (person_record_id IS NULL OR person_record_id = v_person_id)
         AND (canonical_person_id IS NULL OR canonical_person_id = v_canonical_id);
    END IF;
  END LOOP;
  RETURN saved_count;
END;
$function$;
COMMENT ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) IS 'Service-only CCTV writer. Person face/body portfolios receive a canonical Unknown Person #N profile while remaining unreviewed; a human names or merges the profile before it is relied on as an identity.';
REVOKE ALL ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_entity_observations"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_observations jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb DEFAULT '[]'::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS cctv_identity_drafts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  draft_row public.cctv_identity_drafts;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV identity draft access denied';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id
      AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id
      AND domain IN ('video_motion', 'vehicle', 'face')
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;

  IF jsonb_typeof(COALESCE(p_candidate_matches, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Candidate matches must be an array';
  END IF;

  IF p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe') THEN
    RAISE EXCEPTION 'Invalid CCTV event type';
  END IF;

  IF p_subject_kind NOT IN ('person', 'vehicle', 'location', 'entity', 'case') THEN
    RAISE EXCEPTION 'Invalid subject kind';
  END IF;

  IF p_proposed_person_record_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.person_records pr
      WHERE pr.id = p_proposed_person_record_id AND pr.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'Proposed person record is not in the organization';
    END IF;
  END IF;

  INSERT INTO public.cctv_identity_drafts (
    organization_id,
    inference_job_id,
    evidence_item_id,
    event_id,
    event_type,
    subject_kind,
    proposed_person_record_id,
    proposed_display_name,
    candidate_matches,
    status,
    authority_level,
    reason,
    created_by,
    updated_at
  ) VALUES (
    p_organization_id,
    p_job_id,
    p_evidence_id,
    NULLIF(trim(p_event_id), ''),
    p_event_type,
    p_subject_kind,
    p_proposed_person_record_id,
    NULLIF(trim(p_proposed_display_name), ''),
    COALESCE(p_candidate_matches, '[]'::jsonb),
    'draft',
    'draft',
    NULLIF(trim(p_reason), ''),
    auth.uid(),
    clock_timestamp()
  )
  ON CONFLICT (inference_job_id, event_id, subject_kind)
  DO UPDATE SET
    proposed_person_record_id = EXCLUDED.proposed_person_record_id,
    proposed_display_name = EXCLUDED.proposed_display_name,
    candidate_matches = EXCLUDED.candidate_matches,
    status = 'draft',
    authority_level = 'draft',
    reason = EXCLUDED.reason,
    updated_at = clock_timestamp(),
    approved_by = NULL,
    approved_at = NULL
  RETURNING * INTO draft_row;

  RETURN draft_row;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_identity_draft"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_subject_kind text, p_proposed_person_record_id uuid, p_proposed_display_name text, p_candidate_matches jsonb, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint DEFAULT NULL::bigint, p_checked_by text DEFAULT 'vision_worker'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_observed text := lower(nullif(trim(coalesce(p_sha256_observed, '')), ''));
  v_evidence public.evidence_items%rowtype;
  v_expected text;
  v_state text;
  v_checked_at timestamptz := clock_timestamp();
  v_record jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF v_observed IS NULL OR v_observed !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A 64-character hex sha256 is required'; END IF;
  SELECT * INTO v_evidence FROM public.evidence_items WHERE id = p_evidence_id FOR UPDATE;
  IF v_evidence.id IS NULL THEN RAISE EXCEPTION 'Recording not found'; END IF;

  v_expected := lower(coalesce(v_evidence.sha256_hash, v_evidence.metadata->>'source_sha256'));
  v_state := CASE WHEN v_expected IS NULL THEN 'unanchored' WHEN v_expected = v_observed THEN 'verified' ELSE 'mismatch' END;
  v_record := jsonb_strip_nulls(jsonb_build_object(
    'state', v_state, 'checked_at', v_checked_at, 'checked_by', p_checked_by,
    'observed_sha256', v_observed, 'expected_sha256', v_expected, 'observed_size_bytes', p_size_bytes,
    'check_count', coalesce((v_evidence.metadata->'integrity'->>'check_count')::int, 0) + 1,
    'first_verified_at', CASE WHEN v_state = 'verified' THEN coalesce((v_evidence.metadata->'integrity'->>'first_verified_at')::timestamptz, v_checked_at) ELSE (v_evidence.metadata->'integrity'->>'first_verified_at')::timestamptz END,
    'mismatch_count', coalesce((v_evidence.metadata->'integrity'->>'mismatch_count')::int, 0) + CASE WHEN v_state = 'mismatch' THEN 1 ELSE 0 END
  ));

  UPDATE public.evidence_items SET metadata = metadata || jsonb_build_object('integrity', v_record) WHERE id = v_evidence.id;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_evidence.organization_id, NULL,
          CASE v_state WHEN 'verified' THEN 'cctv_evidence_integrity_verified' WHEN 'mismatch' THEN 'cctv_evidence_integrity_mismatch' ELSE 'cctv_evidence_integrity_unanchored' END,
          'evidence_items', v_evidence.id,
          v_record || jsonb_strip_nulls(jsonb_build_object('cctv_import_id', v_evidence.cctv_import_id, 'locked_at', v_evidence.locked_at, 'storage_path', v_evidence.storage_path)));

  RETURN jsonb_build_object('evidence_item_id', v_evidence.id, 'state', v_state, 'expected_sha256', v_expected, 'observed_sha256', v_observed, 'checked_at', v_checked_at);
END $function$;
COMMENT ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) IS 'Service-only: compares a fresh hash of the stored bytes with the sealed/recorded hash. Writes metadata.integrity (state verified|mismatch|unanchored, counts, timestamps) and an audit_log row. Never changes the sealed hash.';
REVOKE ALL ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_integrity_check"(p_evidence_id uuid, p_sha256_observed text, p_size_bytes bigint, p_checked_by text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text)
 RETURNS cctv_review_decisions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result public.cctv_review_decisions;
BEGIN
  IF auth.uid() IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN RAISE EXCEPTION 'CCTV review access denied'; END IF;
  IF p_decision NOT IN ('confirmed', 'dismissed') OR p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe') THEN RAISE EXCEPTION 'Invalid CCTV review decision'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.inference_jobs WHERE id = p_job_id AND evidence_item_id = p_evidence_id AND organization_id = p_organization_id AND domain = 'video_motion') THEN RAISE EXCEPTION 'CCTV job not found'; END IF;
  INSERT INTO public.cctv_review_decisions (organization_id, inference_job_id, evidence_item_id, event_id, event_type, decision, reason, decided_by)
  VALUES (p_organization_id, p_job_id, p_evidence_id, NULLIF(trim(p_event_id), ''), p_event_type, p_decision, trim(p_reason), auth.uid())
  ON CONFLICT (inference_job_id, event_id) DO UPDATE SET decision = EXCLUDED.decision, reason = EXCLUDED.reason, decided_by = EXCLUDED.decided_by, decided_at = clock_timestamp()
  RETURNING * INTO result;
  RETURN result;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_decision"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_event_id text, p_event_type text, p_decision text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text DEFAULT NULL::text, p_confidence_override real DEFAULT NULL::real, p_person_record_id uuid DEFAULT NULL::uuid, p_vehicle_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid)
 RETURNS cctv_review_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  current_event public.cctv_review_events;
  saved_event public.cctv_review_events;
BEGIN
  IF actor_id IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'CCTV review access denied';
  END IF;
  IF p_source_event_id IS NULL OR trim(p_source_event_id) = '' THEN
    RAISE EXCEPTION 'Source event ID is required';
  END IF;
  IF p_event_type NOT IN ('video', 'vehicle', 'person', 'face', 'keyframe')
     OR p_review_state NOT IN ('unreviewed', 'accepted', 'rejected', 'uncertain', 'needs_more_context', 'superseded') THEN
    RAISE EXCEPTION 'Invalid CCTV review event type or state';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.inference_jobs
    WHERE id = p_job_id AND evidence_item_id = p_evidence_id
      AND organization_id = p_organization_id AND domain IN ('video_motion', 'vehicle', 'face')
  ) THEN
    RAISE EXCEPTION 'CCTV inference job is missing or outside the organization';
  END IF;
  IF p_person_record_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.person_records WHERE id = p_person_record_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Person record is outside the organization';
  END IF;
  IF p_vehicle_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Vehicle record is outside the organization';
  END IF;
  IF p_incident_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.incidents WHERE id = p_incident_id AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Incident is outside the organization';
  END IF;
  IF p_review_state = 'accepted' AND p_event_type IN ('face', 'person') AND p_person_record_id IS NULL THEN
    RAISE EXCEPTION 'Accepted person events require an explicit person record link';
  END IF;
  IF p_review_state = 'accepted' AND p_event_type = 'vehicle' AND p_vehicle_id IS NULL THEN
    RAISE EXCEPTION 'Accepted vehicle events require an explicit vehicle record link';
  END IF;

  SELECT * INTO current_event
    FROM public.cctv_review_events
   WHERE inference_job_id = p_job_id AND source_event_id = trim(p_source_event_id) AND event_type = p_event_type
   FOR UPDATE;

  INSERT INTO public.cctv_review_events (
    organization_id, inference_job_id, evidence_item_id, source_event_id, event_type,
    review_state, reviewer_notes, confidence_override,
    linked_person_record_id, linked_vehicle_id, linked_incident_id
  ) VALUES (
    p_organization_id, p_job_id, p_evidence_id, trim(p_source_event_id), p_event_type,
    p_review_state, NULLIF(trim(p_reviewer_notes), ''), p_confidence_override,
    p_person_record_id, p_vehicle_id, p_incident_id
  )
  ON CONFLICT (inference_job_id, source_event_id, event_type)
  DO UPDATE SET
    review_state = EXCLUDED.review_state,
    reviewer_notes = EXCLUDED.reviewer_notes,
    confidence_override = EXCLUDED.confidence_override,
    linked_person_record_id = EXCLUDED.linked_person_record_id,
    linked_vehicle_id = EXCLUDED.linked_vehicle_id,
    linked_incident_id = EXCLUDED.linked_incident_id,
    updated_at = clock_timestamp()
  RETURNING * INTO saved_event;

  INSERT INTO public.cctv_review_event_decisions (
    organization_id, review_event_id, previous_state, next_state, reviewer_notes,
    confidence_override, linked_person_record_id, linked_vehicle_id, linked_incident_id, decided_by
  ) VALUES (
    p_organization_id, saved_event.id, current_event.review_state, p_review_state,
    NULLIF(trim(p_reviewer_notes), ''), p_confidence_override,
    p_person_record_id, p_vehicle_id, p_incident_id, actor_id
  );

  RETURN saved_event;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_review_event"(p_job_id uuid, p_evidence_id uuid, p_organization_id uuid, p_source_event_id text, p_event_type text, p_review_state text, p_reviewer_notes text, p_confidence_override real, p_person_record_id uuid, p_vehicle_id uuid, p_incident_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid)
 RETURNS cctv_camera_scene_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile public.cctv_camera_scene_profiles;
  v_result jsonb;
  v_vehicle_count integer := 0;
  v_person_count integer := 0;
  v_review_count integer := 0;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  IF p_camera_key IS NULL OR length(trim(p_camera_key)) < 3 THEN
    RAISE EXCEPTION 'camera key is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.evidence_items e
    WHERE e.id = p_evidence_id AND e.organization_id = p_organization_id
  ) THEN RAISE EXCEPTION 'evidence item not found for organization'; END IF;

  SELECT r.result INTO v_result
  FROM public.inference_results r
  WHERE r.inference_job_id = p_inference_job_id AND r.evidence_item_id = p_evidence_id
  ORDER BY r.created_at DESC
  LIMIT 1;

  v_vehicle_count := COALESCE(jsonb_array_length(v_result #> '{consolidated_events,vehicle_events}'), 0);
  v_person_count := COALESCE(jsonb_array_length(v_result #> '{consolidated_events,person_events}'), 0)
    + COALESCE(jsonb_array_length(v_result #> '{consolidated_events,face_events}'), 0);
  v_review_count := COALESCE((v_result #>> '{consolidated_events,quality_summary,review_required_count}')::integer, 0);

  INSERT INTO public.cctv_camera_scene_profiles (
    organization_id, location_id, site_id, zone_id, camera_key, scene_fingerprint,
    first_seen_at, last_seen_at, evidence_count, recidivism_summary
  ) VALUES (
    p_organization_id, p_location_id, p_site_id, p_zone_id, trim(p_camera_key), COALESCE(p_scene_fingerprint, '{}'::jsonb),
    clock_timestamp(), clock_timestamp(), 1,
    jsonb_build_object('vehicle_events', v_vehicle_count, 'person_events', v_person_count, 'review_required', v_review_count)
  )
  ON CONFLICT (organization_id, camera_key) DO UPDATE SET
    location_id = COALESCE(EXCLUDED.location_id, cctv_camera_scene_profiles.location_id),
    site_id = COALESCE(EXCLUDED.site_id, cctv_camera_scene_profiles.site_id),
    zone_id = COALESCE(EXCLUDED.zone_id, cctv_camera_scene_profiles.zone_id),
    scene_fingerprint = EXCLUDED.scene_fingerprint,
    last_seen_at = clock_timestamp(),
    evidence_count = cctv_camera_scene_profiles.evidence_count + 1,
    recidivism_summary = jsonb_build_object(
      'vehicle_events', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'vehicle_events')::integer, 0) + v_vehicle_count,
      'person_events', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'person_events')::integer, 0) + v_person_count,
      'review_required', COALESCE((cctv_camera_scene_profiles.recidivism_summary->>'review_required')::integer, 0) + v_review_count
    )
  RETURNING * INTO v_profile;

  RETURN v_profile;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_scene_observation"(p_organization_id uuid, p_evidence_id uuid, p_inference_job_id uuid, p_camera_key text, p_scene_fingerprint jsonb, p_location_id uuid, p_site_id uuid, p_zone_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_hash text := lower(nullif(trim(coalesce(p_sha256, '')), ''));
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'A 64-character hex sha256 is required'; END IF;
  UPDATE public.evidence_items
     SET sha256_hash = v_hash,
         metadata = metadata || jsonb_strip_nulls(jsonb_build_object('source_sha256', v_hash, 'source_size_bytes', p_size_bytes, 'source_hashed_at', clock_timestamp()))
   WHERE id = p_evidence_id AND locked_at IS NULL AND (sha256_hash IS NULL OR lower(sha256_hash) = v_hash);
  RETURN FOUND;
END $function$;
COMMENT ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) IS 'Service-only, write-once: records the sha256 (and size/time provenance) of the stored source bytes. Repeating the same hash refreshes provenance; a different hash or a sealed row changes nothing and returns false.';
REVOKE ALL ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_cctv_source_hash"(p_evidence_id uuid, p_sha256 text, p_size_bytes bigint) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actual_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_outcome text DEFAULT NULL::text)
 RETURNS court_appearances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_appearance public.court_appearances%rowtype;
  v_outcome text := nullif(trim(coalesce(p_outcome, '')), '');
begin
  select c.* into v_appearance from public.court_appearances c where c.id = p_appearance_id for update;
  if not found then
    raise exception 'Court appearance not found';
  end if;

  if v_appearance.officer_user_id <> v_actor and not public.is_admin_for_org(v_appearance.organization_id) then
    raise exception 'Not authorised to update this court appearance';
  end if;

  if v_appearance.status <> p_expected_status then
    raise exception 'Court appearance changed from expected status % to %', p_expected_status, v_appearance.status;
  end if;

  if p_status not in ('attended', 'adjourned', 'cancelled', 'excused') then
    raise exception 'Unsupported court appearance outcome status';
  end if;

  if p_status = 'attended' and (p_actual_start is null or p_actual_end is null) then
    raise exception 'Attended appearances require actual start and end times';
  end if;

  if p_actual_end is not null and p_actual_start is not null and p_actual_end <= p_actual_start then
    raise exception 'Court appearance must end after it starts';
  end if;

  update public.court_appearances
  set status = p_status, actual_start = p_actual_start, actual_end = p_actual_end, outcome = v_outcome
  where id = v_appearance.id
  returning * into v_appearance;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_appearance.organization_id, v_actor, 'court_appearance_outcome_recorded', 'court_appearances', v_appearance.id,
    jsonb_build_object(
      'status', p_status,
      'actual_start', p_actual_start,
      'actual_end', p_actual_end,
      'is_overtime', v_appearance.is_overtime,
      'outcome', v_outcome
    )
  );

  return v_appearance;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_court_appearance_outcome"(p_appearance_id uuid, p_expected_status text, p_status text, p_actual_start timestamp with time zone, p_actual_end timestamp with time zone, p_outcome text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Provider adapter execution only'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  UPDATE public.finance_external_connection_requests
  SET status = CASE WHEN p_error IS NULL THEN 'connected' ELSE 'failed' END, sync_cursor = COALESCE(p_sync_cursor, sync_cursor), last_sync_at = CASE WHEN p_error IS NULL THEN now() ELSE last_sync_at END, last_error = nullif(trim(p_error), ''), updated_at = now()
  WHERE id = p_request_id
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_request.organization_id, NULL, 'finance_external_sync_recorded', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', v_request.adapter_name, 'success', p_error IS NULL));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_external_sync"(p_request_id uuid, p_sync_cursor text, p_error text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text DEFAULT NULL::text, p_target_location_id uuid DEFAULT NULL::uuid, p_asset_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_investigation_id uuid DEFAULT NULL::uuid)
 RETURNS finance_inventory_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_item public.finance_item_catalog%rowtype;
  v_location public.finance_inventory_locations%rowtype;
  v_transaction public.finance_inventory_transactions%rowtype;
  v_balance public.finance_inventory_balances%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance or operations administrator required'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_unit_cost IS NULL OR p_unit_cost < 0 THEN RAISE EXCEPTION 'Quantity and unit cost must be valid positive values'; END IF;
  IF p_idempotency_key IS NULL OR trim(p_idempotency_key) = '' THEN RAISE EXCEPTION 'Idempotency key is required'; END IF;
  SELECT * INTO v_item FROM public.finance_item_catalog WHERE id = p_item_id AND organization_id = v_org AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active inventory item not found in organization'; END IF;
  SELECT * INTO v_location FROM public.finance_inventory_locations WHERE id = p_location_id AND organization_id = v_org AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active inventory location not found in organization'; END IF;
  SELECT * INTO v_transaction FROM public.finance_inventory_transactions WHERE organization_id = v_org AND idempotency_key = trim(p_idempotency_key);
  IF FOUND THEN RETURN v_transaction; END IF;
  IF p_transaction_type IN ('issue','consumption','write_off','transfer_out','quarantine') THEN
    SELECT * INTO v_balance FROM public.finance_inventory_balances WHERE item_id = p_item_id AND location_id = p_location_id FOR UPDATE;
    IF NOT FOUND OR v_balance.on_hand - v_balance.reserved < p_quantity THEN RAISE EXCEPTION 'Insufficient available inventory'; END IF;
    UPDATE public.finance_inventory_balances SET on_hand = on_hand - p_quantity, updated_at = now() WHERE item_id = p_item_id AND location_id = p_location_id;
  ELSE
    INSERT INTO public.finance_inventory_balances(item_id, location_id, organization_id, on_hand) VALUES (p_item_id, p_location_id, v_org, p_quantity)
    ON CONFLICT (item_id, location_id) DO UPDATE SET on_hand = public.finance_inventory_balances.on_hand + excluded.on_hand, updated_at = now();
  END IF;
  INSERT INTO public.finance_inventory_transactions(organization_id,item_id,location_id,transaction_type,quantity,unit_cost,idempotency_key,source_reference,location_id_target,dispatch_job_id,investigation_id,asset_id,created_by)
  VALUES(v_org,p_item_id,p_location_id,p_transaction_type,p_quantity,p_unit_cost,trim(p_idempotency_key),nullif(trim(p_source_reference),''),p_target_location_id,p_dispatch_job_id,p_investigation_id,p_asset_id,v_actor)
  RETURNING * INTO v_transaction;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  VALUES(v_org,v_actor,'finance_inventory_transaction_recorded','finance_inventory_transactions',v_transaction.id,jsonb_build_object('item_id',p_item_id,'location_id',p_location_id,'transaction_type',p_transaction_type,'quantity',p_quantity,'unit_cost',p_unit_cost,'idempotency_key',trim(p_idempotency_key)));
  RETURN v_transaction;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_finance_inventory_transaction"(p_item_id uuid, p_location_id uuid, p_transaction_type text, p_quantity numeric, p_unit_cost numeric, p_idempotency_key text, p_source_reference text, p_target_location_id uuid, p_asset_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_investigation_id uuid DEFAULT NULL::uuid, p_asset_id uuid DEFAULT NULL::uuid)
 RETURNS finance_service_costs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_period public.finance_pl_periods%rowtype;
  v_agreement public.service_agreements%rowtype;
  v_cost public.finance_service_costs%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 OR p_unit_cost IS NULL OR p_unit_cost < 0 THEN RAISE EXCEPTION 'Quantity and unit cost must be valid positive values'; END IF;
  
  SELECT * INTO v_period FROM public.finance_pl_periods WHERE id = p_pl_period_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'P&L period not found in organization'; END IF;
  IF v_period.status = 'closed' THEN RAISE EXCEPTION 'Cannot record costs in a closed P&L period'; END IF;
  
  SELECT * INTO v_agreement FROM public.service_agreements WHERE id = p_service_agreement_id AND provider_organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Service agreement not found in organization'; END IF;
  
  INSERT INTO public.finance_service_costs(
    organization_id, pl_period_id, service_agreement_id, client_organization_id, cost_type, 
    work_unit_id, shift_id, dispatch_job_id, investigation_id, asset_id,
    source_document_type, source_reference, quantity, unit_cost, total_cost, created_by
  )
  VALUES (
    v_org, p_pl_period_id, p_service_agreement_id, v_agreement.client_organization_id, p_cost_type,
    p_work_unit_id, p_shift_id, p_dispatch_job_id, p_investigation_id, p_asset_id,
    p_source_document_type, trim(p_source_reference), p_quantity, p_unit_cost, round(p_quantity * p_unit_cost, 2), v_actor
  )
  RETURNING * INTO v_cost;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'finance_service_cost_recorded', 'finance_service_costs', v_cost.id, 
    jsonb_build_object('pl_period_id', p_pl_period_id, 'service_agreement_id', p_service_agreement_id, 
      'cost_type', p_cost_type, 'quantity', p_quantity, 'unit_cost', p_unit_cost, 'source_reference', trim(p_source_reference)));
  
  RETURN v_cost;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_finance_service_cost"(p_pl_period_id uuid, p_service_agreement_id uuid, p_cost_type text, p_quantity numeric, p_unit_cost numeric, p_source_document_type text, p_source_reference text, p_work_unit_id uuid, p_shift_id uuid, p_dispatch_job_id uuid, p_investigation_id uuid, p_asset_id uuid) TO "authenticated";
