CREATE OR REPLACE FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_reference text DEFAULT NULL::text, p_source_hash text DEFAULT NULL::text)
 RETURNS fuel_price_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_row public.fuel_price_observations%rowtype;
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if v_actor is null or not public.is_admin_for_org(p_organization_id) then raise exception 'Active organisation administrator required'; end if;
  if p_fuel_type not in ('petrol', 'diesel', 'lpg', 'other') then raise exception 'Unsupported fuel type'; end if;
  if p_observed_on is null or p_price_per_litre is null or p_price_per_litre <= 0 then raise exception 'Observed date and positive price are required'; end if;
  if nullif(trim(coalesce(p_source_name, '')), '') is null or nullif(trim(coalesce(p_source_url, '')), '') is null then raise exception 'Source name and URL are required'; end if;
  select * into v_row from public.fuel_price_observations where organization_id = p_organization_id and source_reference = p_client_request_id::text;
  if found then return v_row; end if;
  insert into public.fuel_price_observations (organization_id, fuel_type, observed_on, price_per_litre, source_name, source_url, source_published_at, source_reference, source_hash, created_by)
  values (p_organization_id, p_fuel_type, p_observed_on, p_price_per_litre, trim(p_source_name), trim(p_source_url), p_source_published_at, coalesce(nullif(trim(p_source_reference), ''), p_client_request_id::text), nullif(trim(p_source_hash), ''), v_actor)
  on conflict (organization_id, fuel_type, observed_on, source_url, source_reference) do update
    set price_per_litre = excluded.price_per_litre, source_published_at = excluded.source_published_at, source_hash = excluded.source_hash
  returning * into v_row;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, v_actor, 'fuel_price_observation_recorded', 'fuel_price_observations', v_row.id,
          jsonb_build_object('fuel_type', v_row.fuel_type, 'observed_on', v_row.observed_on, 'price_per_litre', v_row.price_per_litre, 'source_name', v_row.source_name, 'source_url', v_row.source_url));
  return v_row;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_fuel_price_observation"(p_client_request_id uuid, p_organization_id uuid, p_fuel_type text, p_observed_on date, p_price_per_litre numeric, p_source_name text, p_source_url text, p_source_published_at timestamp with time zone, p_source_reference text, p_source_hash text) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone DEFAULT now(), p_summary text DEFAULT NULL::text, p_noise_assessment_id uuid DEFAULT NULL::uuid, p_shift_stop_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_gps_accuracy double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id uuid, created boolean, occurred_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_job public.dispatch_jobs%rowtype;
  v_existing public.job_party_interactions%rowtype;
  v_row public.job_party_interactions%rowtype;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_party_role NOT IN ('complainant', 'occupant', 'witness', 'police', 'other') THEN RAISE EXCEPTION 'Unsupported party role'; END IF;
  IF p_mode NOT IN ('in_person', 'phone', 'message', 'no_answer') THEN RAISE EXCEPTION 'Unsupported interaction mode'; END IF;
  IF p_occurred_at IS NULL OR p_occurred_at > now() + interval '5 minutes' OR p_occurred_at < now() - interval '24 hours' THEN
    RAISE EXCEPTION 'occurred_at is outside the accepted capture window';
  END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_existing FROM public.job_party_interactions i WHERE i.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.officer_user_id <> v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
    RETURN QUERY SELECT v_existing.id, false, v_existing.occurred_at; RETURN;
  END IF;

  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found in the officer organisation'; END IF;
  IF NOT (v_job.assigned_officer_id = v_user OR public.is_admin_for_org(v_org)
      OR EXISTS (SELECT 1 FROM public.dispatch_resources dr WHERE dr.id = v_job.dispatch_resource_id AND dr.assigned_officer_id = v_user)) THEN
    RAISE EXCEPTION 'Only the assigned officer may record interactions for this job';
  END IF;
  IF p_noise_assessment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.noise_assessments na WHERE na.id = p_noise_assessment_id AND na.organization_id = v_org) THEN
    RAISE EXCEPTION 'Noise assessment not found in the officer organisation';
  END IF;
  IF p_shift_stop_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.shift_stops st WHERE st.id = p_shift_stop_id AND st.dispatch_job_id = v_job.id) THEN
    RAISE EXCEPTION 'Stop does not belong to this job';
  END IF;

  INSERT INTO public.job_party_interactions (organization_id, dispatch_job_id, noise_assessment_id, shift_stop_id, party_role, mode, occurred_at,
    gps_lat, gps_lng, gps_accuracy, summary, protected, officer_user_id, client_request_id)
  VALUES (v_org, v_job.id, p_noise_assessment_id, p_shift_stop_id, p_party_role, p_mode, p_occurred_at,
    p_gps_lat, p_gps_lng, p_gps_accuracy, nullif(trim(coalesce(p_summary, '')), ''), p_party_role IN ('complainant', 'witness'), v_user, p_client_request_id)
  RETURNING * INTO v_row;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'job_party_interaction_recorded', 'job_party_interactions', v_row.id,
    jsonb_build_object('dispatch_job_id', v_job.id, 'party_role', p_party_role, 'mode', p_mode, 'noise_assessment_id', p_noise_assessment_id, 'shift_stop_id', p_shift_stop_id));

  RETURN QUERY SELECT v_row.id, true, v_row.occurred_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_job_party_interaction"(p_client_request_id uuid, p_dispatch_job_id uuid, p_party_role text, p_mode text, p_occurred_at timestamp with time zone, p_summary text, p_noise_assessment_id uuid, p_shift_stop_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint DEFAULT NULL::smallint, p_entry_notice_left boolean DEFAULT NULL::boolean)
 RETURNS TABLE(assessment_id uuid, end_given_orally boolean, end_recipient_role text, end_expires_at timestamp with time zone, entry_notice_left boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_assessment public.noise_assessments%rowtype;
  v_receipt public.officer_command_requests%rowtype;
  v_cap smallint := 192;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_recipient_role NOT IN ('occupier', 'responsible_person', 'unoccupied_notice_left') THEN
    RAISE EXCEPTION 'recipient_role must be occupier, responsible_person or unoccupied_notice_left';
  END IF;
  SELECT p.organization_id INTO v_org FROM public.user_profiles p
  WHERE p.id = v_user AND p.deactivated_at IS NULL AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;

  SELECT * INTO v_receipt FROM public.officer_command_requests r WHERE r.request_id = p_client_request_id::text;
  IF FOUND AND v_receipt.actor_user_id IS DISTINCT FROM v_user THEN RAISE EXCEPTION 'client_request_id belongs to another actor'; END IF;
  IF FOUND AND v_receipt.command_status = 'completed' THEN
    RETURN QUERY SELECT (v_receipt.response->>'assessment_id')::uuid, (v_receipt.response->>'end_given_orally')::boolean,
      v_receipt.response->>'end_recipient_role', (v_receipt.response->>'end_expires_at')::timestamptz, (v_receipt.response->>'entry_notice_left')::boolean;
    RETURN;
  END IF;

  SELECT * INTO v_assessment FROM public.noise_assessments na WHERE na.id = p_assessment_id AND na.organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Noise assessment not found in the officer organisation'; END IF;
  IF NOT (v_assessment.officer_user_id = v_user OR public.is_admin_for_org(v_org)) THEN
    RAISE EXCEPTION 'Only the assessing officer may record direction particulars';
  END IF;
  IF v_assessment.action_taken NOT IN ('direction_notice', 'equipment_seized') THEN
    RAISE EXCEPTION 'Direction particulars apply to an excessive noise direction or a seizure under it';
  END IF;
  -- s328(5): an unoccupied entry must leave the written direction and the entry notice.
  IF p_recipient_role = 'unoccupied_notice_left' AND NOT coalesce(p_entry_notice_left, false) THEN
    RAISE EXCEPTION 'Entry where no occupier can be identified requires the written direction and entry notice to be left (RMA s328(5))';
  END IF;
  IF p_recipient_role = 'unoccupied_notice_left' AND coalesce(p_given_orally, false) THEN
    RAISE EXCEPTION 'A direction left at an unoccupied place must be written (RMA s328(5)(a))';
  END IF;

  -- s327(3): the officer may specify a shorter period; never longer than the council rule, which is capped at the statute.
  SELECT n.end_validity_hours INTO v_cap FROM public.noise_module_config n
  WHERE n.organization_id = v_org AND n.is_current AND n.effective_from <= current_date AND (n.effective_to IS NULL OR n.effective_to >= current_date)
  ORDER BY n.effective_from DESC, n.version DESC LIMIT 1;
  IF v_cap IS NULL THEN v_cap := 192; END IF;
  IF p_period_hours IS NOT NULL AND (p_period_hours < 1 OR p_period_hours > v_cap) THEN
    RAISE EXCEPTION 'Direction period must be between 1 and % hours (RMA s327(3); council rule)', v_cap;
  END IF;

  UPDATE public.noise_assessments
  SET end_given_orally = p_given_orally,
      end_recipient_role = p_recipient_role,
      entry_notice_left = COALESCE(p_entry_notice_left, noise_assessments.entry_notice_left),
      end_expires_at = CASE
        WHEN p_period_hours IS NOT NULL THEN noise_assessments.assessed_at + make_interval(hours => p_period_hours)
        ELSE COALESCE(noise_assessments.end_expires_at, noise_assessments.assessed_at + make_interval(hours => v_cap))
      END
  WHERE id = v_assessment.id
  RETURNING * INTO v_assessment;

  INSERT INTO public.officer_command_requests (request_id, organization_id, actor_user_id, shift_id, site_id, command_type, command_status, response)
  VALUES (p_client_request_id::text, v_org, v_user, v_assessment.shift_id, v_assessment.site_id, 'record_noise_direction_particulars', 'completed',
    jsonb_build_object('assessment_id', v_assessment.id, 'end_given_orally', v_assessment.end_given_orally, 'end_recipient_role', v_assessment.end_recipient_role,
      'end_expires_at', v_assessment.end_expires_at, 'entry_notice_left', v_assessment.entry_notice_left))
  ON CONFLICT (request_id) DO UPDATE SET command_status = 'completed', response = EXCLUDED.response;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_user, 'noise_direction_particulars_recorded', 'noise_assessments', v_assessment.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'end_given_orally', v_assessment.end_given_orally,
      'end_recipient_role', v_assessment.end_recipient_role, 'period_hours', p_period_hours, 'end_expires_at', v_assessment.end_expires_at,
      'entry_notice_left', v_assessment.entry_notice_left));

  RETURN QUERY SELECT v_assessment.id, v_assessment.end_given_orally, v_assessment.end_recipient_role, v_assessment.end_expires_at, v_assessment.entry_notice_left;
END;
$function$;
COMMENT ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) IS 'Records how an excessive noise direction was given (oral/written, recipient), an officer-specified shorter period within the council rule (RMA s327(3)), and the s328(5) entry notice for an unoccupied place. Officer-owned, idempotent by client_request_id, audited.';
REVOKE ALL ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_noise_direction_particulars"(p_client_request_id uuid, p_assessment_id uuid, p_given_orally boolean, p_recipient_role text, p_period_hours smallint, p_entry_notice_left boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision DEFAULT NULL::double precision, p_heading double precision DEFAULT NULL::double precision, p_speed_kmh double precision DEFAULT NULL::double precision, p_activity_type text DEFAULT 'gps_update'::text, p_shift_id uuid DEFAULT NULL::uuid, p_physical_address text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.officer_gps_log%rowtype;
  v_created public.officer_gps_log%rowtype;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT up.organization_id INTO v_org_id FROM public.user_profiles up
  WHERE up.id = v_user_id AND up.deactivated_at IS NULL AND up.role IN ('officer', 'scan_operator');
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Active officer profile not found'; END IF;
  IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'client_event_id is required'; END IF;
  IF p_recorded_at IS NULL OR p_recorded_at > now() + interval '5 minutes' OR p_recorded_at < now() - interval '24 hours' THEN
    RAISE EXCEPTION 'recorded_at is outside the accepted capture window';
  END IF;
  IF p_gps_lat NOT BETWEEN -90 AND 90 OR p_gps_lng NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid GPS coordinates'; END IF;
  IF p_accuracy_meters IS NOT NULL AND p_accuracy_meters < 0 THEN RAISE EXCEPTION 'GPS accuracy cannot be negative'; END IF;
  IF p_activity_type NOT IN ('gps_update', 'shift_start', 'shift_end', 'scan', 'welfare_checkin', 'sos', 'checkpoint_scan') THEN
    RAISE EXCEPTION 'Unsupported breadcrumb activity type';
  END IF;
  IF p_shift_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.id = p_shift_id AND s.organization_id = v_org_id AND s.officer_user_id = v_user_id
  ) THEN RAISE EXCEPTION 'Shift does not belong to the authenticated officer'; END IF;

  SELECT g.* INTO v_existing FROM public.officer_gps_log g
  WHERE g.organization_id = v_org_id AND g.officer_id = v_user_id AND g.client_event_id = p_client_event_id;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id, false, v_existing.created_at; RETURN; END IF;

  BEGIN
    INSERT INTO public.officer_gps_log (
      organization_id, officer_id, client_event_id, recorded_at, gps_lat, gps_lng,
      accuracy_meters, heading, speed_kmh, activity_type, shift_id, physical_address
    ) VALUES (
      v_org_id, v_user_id, p_client_event_id, p_recorded_at, p_gps_lat, p_gps_lng,
      p_accuracy_meters, p_heading, p_speed_kmh, p_activity_type, p_shift_id, NULLIF(trim(p_physical_address), '')
    ) RETURNING * INTO v_created;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO v_created FROM public.officer_gps_log
    WHERE organization_id = v_org_id AND officer_id = v_user_id AND client_event_id = p_client_event_id;
    RETURN QUERY SELECT v_created.id, false, v_created.created_at; RETURN;
  END;
  RETURN QUERY SELECT v_created.id, true, v_created.created_at;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_breadcrumb"(p_client_event_id uuid, p_recorded_at timestamp with time zone, p_gps_lat double precision, p_gps_lng double precision, p_accuracy_meters double precision, p_heading double precision, p_speed_kmh double precision, p_activity_type text, p_shift_id uuid, p_physical_address text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision DEFAULT NULL::double precision, p_gps_distance_from_checkpoint double precision DEFAULT NULL::double precision, p_within_radius boolean DEFAULT NULL::boolean)
 RETURNS TABLE(visit_id uuid, patrol_id uuid, visited_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_checkpoint public.patrol_checkpoints%ROWTYPE;
  v_patrol public.patrols%ROWTYPE;
  v_visit public.patrol_checkpoint_visits%ROWTYPE;
  v_stop_id uuid;
  v_stop_count integer;
  v_at timestamptz := clock_timestamp();
  v_distance double precision := NULL;
  v_within boolean := NULL;
BEGIN
  IF v_actor IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'Authentication and client_request_id are required';
  END IF;

  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active officer identity required'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.shifts s
    WHERE s.id = p_shift_id AND s.organization_id = v_org AND s.officer_user_id = v_actor AND s.status = 'in_progress'
  ) THEN RAISE EXCEPTION 'Checkpoint visit must be recorded for your active shift'; END IF;

  SELECT * INTO v_checkpoint FROM public.patrol_checkpoints WHERE id = p_checkpoint_id AND organization_id = v_org AND active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Checkpoint is not active for your organization'; END IF;

  SELECT * INTO v_visit FROM public.patrol_checkpoint_visits
  WHERE organization_id = v_org AND officer_user_id = v_actor AND client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_visit.id, v_visit.patrol_id, v_visit.visited_at, false;
    RETURN;
  END IF;

  -- P1: presence is measured here, from the recorded point. The client's p_gps_distance_from_checkpoint /
  -- p_within_radius are accepted for signature compatibility only. No point or no GPS -> NULL, not a guess.
  IF p_gps_lat IS NOT NULL AND p_gps_lng IS NOT NULL AND v_checkpoint.gps_lat IS NOT NULL AND v_checkpoint.gps_lng IS NOT NULL THEN
    v_distance := round(ST_Distance(ST_SetSRID(ST_MakePoint(v_checkpoint.gps_lng, v_checkpoint.gps_lat), 4326)::geography,
                                    ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326)::geography)::numeric, 1);
    v_within := v_distance <= v_checkpoint.radius_meters;
  END IF;

  SELECT * INTO v_patrol FROM public.patrols
  WHERE organization_id = v_org AND shift_id = p_shift_id AND officer_user_id = v_actor AND status = 'in_progress'
  ORDER BY started_at DESC LIMIT 1;
  IF NOT FOUND THEN
    INSERT INTO public.patrols(organization_id, shift_id, officer_user_id, zone_id, status, started_at)
    VALUES(v_org, p_shift_id, v_actor, v_checkpoint.zone_id, 'in_progress', v_at)
    RETURNING * INTO v_patrol;
  END IF;

  SELECT count(*) INTO v_stop_count FROM (
    SELECT ss.id FROM public.shift_stops ss
    WHERE ss.shift_id = p_shift_id AND ss.status IN ('pending', 'en_route', 'on_scene')
      AND ((v_checkpoint.client_site_id IS NOT NULL AND ss.site_id = v_checkpoint.client_site_id)
        OR (v_checkpoint.zone_id IS NOT NULL AND ss.zone_id = v_checkpoint.zone_id))
    ORDER BY ss.stop_order LIMIT 2
  ) candidates;
  IF v_stop_count = 1 THEN
    SELECT ss.id INTO v_stop_id FROM public.shift_stops ss
    WHERE ss.shift_id = p_shift_id AND ss.status IN ('pending', 'en_route', 'on_scene')
      AND ((v_checkpoint.client_site_id IS NOT NULL AND ss.site_id = v_checkpoint.client_site_id)
        OR (v_checkpoint.zone_id IS NOT NULL AND ss.zone_id = v_checkpoint.zone_id))
    ORDER BY ss.stop_order LIMIT 1;
  END IF;

  INSERT INTO public.patrol_checkpoint_visits(
    organization_id, patrol_id, checkpoint_id, officer_user_id, gps_lat, gps_lng,
    gps_accuracy, gps_distance_from_checkpoint, within_radius, scan_method,
    shift_stop_id, notes, visited_at, client_request_id, checkpoint_verification_at_visit
  ) VALUES (
    v_org, v_patrol.id, v_checkpoint.id, v_actor, p_gps_lat, p_gps_lng,
    p_gps_accuracy, v_distance, v_within, 'qr_camera',
    v_stop_id, 'QR checkpoint scan from mobile app', v_at, p_client_request_id, v_checkpoint.checkpoint_verification
  ) RETURNING * INTO v_visit;

  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES(v_org, v_actor, 'officer_checkpoint_visit_recorded', 'patrol_checkpoint_visits', v_visit.id,
    jsonb_build_object('patrol_id', v_patrol.id, 'checkpoint_id', v_checkpoint.id, 'shift_id', p_shift_id,
      'client_request_id', p_client_request_id, 'gps_distance_from_checkpoint', v_distance, 'within_radius', v_within,
      'checkpoint_verification', v_checkpoint.checkpoint_verification, 'client_claimed_within_radius', p_within_radius));
  RETURN QUERY SELECT v_visit.id, v_patrol.id, v_visit.visited_at, true;
END;
$function$;
COMMENT ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) IS 'Officer QR checkpoint visit. Since 20260915100000 the distance and within_radius are computed by the server from the checkpoint point + radius (client values accepted for compatibility only) and the checkpoint verification state is recorded with the visit (P1/P2). Idempotent by client_request_id; audited.';
REVOKE ALL ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_checkpoint_visit"(p_client_request_id uuid, p_shift_id uuid, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_gps_distance_from_checkpoint double precision, p_within_radius boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision, p_shift_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(check_id uuid, checked_in_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_org uuid;v_check public.welfare_checks%rowtype;v_at timestamptz:=clock_timestamp();
begin
 if v_actor is null or p_client_request_id is null then raise exception 'Authentication and client_request_id are required';end if;
 select organization_id into v_org from public.user_profiles where id=v_actor and deactivated_at is null;if v_org is null then raise exception 'Active officer identity required';end if;
 if p_shift_id is not null and not exists(select 1 from public.shifts s where s.id=p_shift_id and s.organization_id=v_org and s.officer_user_id=v_actor and s.status='in_progress') then raise exception 'Check-in shift must be your active shift';end if;
 select * into v_check from public.welfare_checks where organization_id=v_org and officer_user_id=v_actor and client_request_id=p_client_request_id;if found then return query select v_check.id,v_check.checked_in_at,false;return;end if;
 insert into public.welfare_checks(organization_id,officer_user_id,shift_id,status,notes,gps_lat,gps_lng,checked_in_at,client_request_id) values(v_org,v_actor,p_shift_id,'ok',nullif(trim(coalesce(p_notes,'')),''),p_gps_lat,p_gps_lng,v_at,p_client_request_id) returning * into v_check;
 insert into public.officer_welfare_settings(organization_id,officer_user_id,last_checkin_at) values(v_org,v_actor,v_at) on conflict(officer_user_id,organization_id) do update set last_checkin_at=excluded.last_checkin_at;
 insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_org,v_actor,'officer_welfare_checkin','welfare_checks',v_check.id,jsonb_build_object('shift_id',p_shift_id,'client_request_id',p_client_request_id));
 return query select v_check.id,v_check.checked_in_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_officer_welfare_checkin"(p_client_request_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(visit_id uuid, created boolean, visited_at timestamp with time zone, scan_method text, notes text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_patrol record;v_checkpoint record;v_existing public.patrol_checkpoint_visits%rowtype;v_visit public.patrol_checkpoint_visits%rowtype;
  v_radius double precision;v_distance double precision;v_shift_stop_id uuid;v_regular_id uuid;v_route_id uuid;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select p.*,s.patrol_route_id,s.zone_id as shift_zone_id into v_patrol from public.patrols p join public.shifts s on s.id=p.shift_id where p.id=p_patrol_id for update of p;
  if not found or v_patrol.organization_id is distinct from v_profile.organization_id or v_patrol.officer_user_id is distinct from v_actor then raise exception 'Active assigned Patrol session not found';end if;
  if v_patrol.status<>'in_progress' then raise exception 'Patrol session is not in progress';end if;
  if p_gps_lat is null or p_gps_lng is null or p_gps_accuracy is null or p_gps_lat not between -90 and 90 or p_gps_lng not between -180 and 180 or p_gps_accuracy<0 or p_gps_accuracy>1000 then raise exception 'Valid checkpoint GPS and accuracy are required';end if;
  if p_checkpoint_kind='route' then
    select id,gps_lat,gps_lng,geofence_radius_meters as radius,patrol_route_id,is_active,null::uuid as client_site_id,null::uuid as zone_id into v_checkpoint from public.patrol_route_checkpoints where id=p_checkpoint_id;
    if not found or not v_checkpoint.is_active or v_checkpoint.patrol_route_id is distinct from v_patrol.patrol_route_id then raise exception 'Assigned route checkpoint not found';end if;
    v_route_id:=v_checkpoint.id;
  elsif p_checkpoint_kind='site' then
    select id,gps_lat,gps_lng,radius_meters as radius,null::uuid as patrol_route_id,active as is_active,client_site_id,zone_id into v_checkpoint from public.patrol_checkpoints where id=p_checkpoint_id and organization_id=v_patrol.organization_id;
    if not found or not v_checkpoint.is_active or not((v_checkpoint.zone_id is not null and v_checkpoint.zone_id=v_patrol.shift_zone_id) or exists(select 1 from public.shift_stops st where st.shift_id=v_patrol.shift_id and((v_checkpoint.client_site_id is not null and st.site_id=v_checkpoint.client_site_id)or(v_checkpoint.zone_id is not null and st.zone_id=v_checkpoint.zone_id)))) then raise exception 'Assigned Patrol checkpoint not found';end if;
    v_regular_id:=v_checkpoint.id;
    select st.id into v_shift_stop_id from public.shift_stops st where st.shift_id=v_patrol.shift_id and(st.site_id=v_checkpoint.client_site_id or st.zone_id=v_checkpoint.zone_id) and st.status not in('completed','skipped','cancelled') order by st.stop_order limit 1;
  else raise exception 'Checkpoint kind must be route or site';end if;
  if v_checkpoint.gps_lat is null or v_checkpoint.gps_lng is null then raise exception 'Checkpoint has no verified GPS anchor';end if;
  v_radius:=greatest(coalesce(v_checkpoint.radius,0),1);
  if p_gps_accuracy>v_radius then raise exception 'GPS accuracy is too poor for this checkpoint';end if;
  v_distance:=st_distance(st_setsrid(st_makepoint(p_gps_lng,p_gps_lat),4326)::geography,st_setsrid(st_makepoint(v_checkpoint.gps_lng,v_checkpoint.gps_lat),4326)::geography);
  if v_distance>v_radius then raise exception 'GPS position is outside the checkpoint radius';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_patrol_id::text||':'||p_checkpoint_kind||':'||p_checkpoint_id::text,0));
  select * into v_existing from public.patrol_checkpoint_visits where patrol_id=p_patrol_id and((p_checkpoint_kind='route' and route_checkpoint_id=p_checkpoint_id)or(p_checkpoint_kind='site' and checkpoint_id=p_checkpoint_id)) order by visited_at limit 1;
  if found then return query select v_existing.id,false,v_existing.visited_at,v_existing.scan_method,v_existing.notes;return;end if;
  insert into public.patrol_checkpoint_visits(organization_id,patrol_id,checkpoint_id,route_checkpoint_id,officer_user_id,gps_lat,gps_lng,gps_accuracy,gps_distance_from_checkpoint,within_radius,scan_method,notes,shift_stop_id)
  values(v_patrol.organization_id,v_patrol.id,v_regular_id,v_route_id,v_actor,p_gps_lat,p_gps_lng,p_gps_accuracy,v_distance,true,'gps',nullif(trim(coalesce(p_notes,'')),''),v_shift_stop_id) returning * into v_visit;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_visit.organization_id,v_actor,'patrol.checkpoint_recorded','patrol_checkpoint_visits',v_visit.id,jsonb_build_object('patrol_id',v_visit.patrol_id,'checkpoint_kind',p_checkpoint_kind,'checkpoint_id',p_checkpoint_id,'distance_metres',round(v_distance::numeric,1),'shift_stop_id',v_shift_stop_id));
  return query select v_visit.id,true,v_visit.visited_at,v_visit.scan_method,v_visit.notes;
end;$function$;
REVOKE ALL ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_patrol_checkpoint_visit"(p_patrol_id uuid, p_checkpoint_kind text, p_checkpoint_id uuid, p_gps_lat double precision, p_gps_lng double precision, p_gps_accuracy double precision, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid DEFAULT NULL::uuid, p_transaction_reference text DEFAULT NULL::text)
 RETURNS payment_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org uuid;
  v_invoice public.invoices%rowtype;
  v_receipt public.payment_receipts%rowtype;
  v_remaining_balance numeric(14,2);
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_payment_amount IS NULL OR p_payment_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id AND organization_id = v_org;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found in organization'; END IF;
  SELECT COALESCE(v_invoice.total_amount - SUM(payment_amount), v_invoice.total_amount) INTO v_remaining_balance
  FROM public.payment_receipts WHERE invoice_id = p_invoice_id;
  IF p_payment_amount > v_remaining_balance + 0.01 THEN RAISE EXCEPTION 'Payment amount (%) exceeds remaining balance (%)', p_payment_amount, v_remaining_balance; END IF;
  INSERT INTO public.payment_receipts(organization_id, invoice_id, payment_date, payment_amount, payment_method, bank_account_id, transaction_reference, created_by)
  VALUES (v_org, p_invoice_id, p_payment_date, p_payment_amount, p_payment_method, p_bank_account_id, p_transaction_reference, v_actor)
  RETURNING * INTO v_receipt;
  UPDATE public.invoices SET updated_at = now(), paid_at = CASE WHEN p_payment_amount >= v_remaining_balance - 0.01 THEN now() ELSE paid_at END,
    status = CASE WHEN p_payment_amount >= v_remaining_balance - 0.01 THEN 'paid' ELSE status END WHERE id = p_invoice_id;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org, v_actor, 'payment_receipt_recorded', 'payment_receipts', v_receipt.id, jsonb_build_object('invoice_id', p_invoice_id, 'payment_amount', p_payment_amount, 'transaction_reference', p_transaction_reference));
  RETURN v_receipt;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_payment_receipt"(p_invoice_id uuid, p_payment_date date, p_payment_amount numeric, p_payment_method text, p_bank_account_id uuid, p_transaction_reference text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real DEFAULT 1.0, p_is_final boolean DEFAULT true)
 RETURNS TABLE(segment_id uuid, transmission_id uuid, sequence integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_trans public.ptt_transmissions%rowtype;
  v_segment public.radio_transcript_segments%rowtype;
  v_clean_text text := nullif(trim(coalesce(p_text, '')), '');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if v_clean_text is null then raise exception 'Transcript text is required'; end if;

  select t.* into v_trans from public.ptt_transmissions t where t.id = p_transmission_id;
  if not found then raise exception 'PTT transmission not found'; end if;
  if v_trans.speaker_user_id <> v_user_id and not public.is_admin_for_org(v_trans.organization_id) then
    raise exception 'Not authorised to transcribe this PTT transmission';
  end if;

  insert into public.radio_transcript_segments (
    organization_id, transmission_id, sequence, text, confidence, is_final
  ) values (
    v_trans.organization_id, v_trans.id, coalesce(p_sequence, 1), v_clean_text, coalesce(p_confidence, 1.0), coalesce(p_is_final, true)
  ) returning * into v_segment;

  return query select v_segment.id, v_segment.transmission_id, v_segment.sequence, v_segment.created_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_radio_transcript_segment"(p_transmission_id uuid, p_sequence integer, p_text text, p_confidence real, p_is_final boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_clock   sla_clocks%rowtype;
  v_elapsed integer;
  v_status  text;
begin
  select * into v_clock from sla_clocks where id = p_clock_id;
  if not found then
    raise exception 'SLA clock not found';
  end if;
  if not org_access_allowed(v_clock.organization_id) then
    raise exception 'Access denied';
  end if;

  v_elapsed := ceil(extract(epoch from (p_arrived_at - v_clock.started_at)) / 60.0);

  if v_clock.target_minutes is null then
    v_status := 'met'; -- no target = informational only
  elsif v_elapsed <= v_clock.target_minutes then
    v_status := 'met';
  else
    v_status := 'breached';
  end if;

  update sla_clocks
  set arrived_at      = p_arrived_at,
      elapsed_minutes = v_elapsed,
      status          = v_status,
      updated_at      = now()
  where id = p_clock_id;

  return v_status;
end;
$function$;
COMMENT ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) IS 'Stops an SLA clock at arrival, computes elapsed minutes, records met/breached vs target_minutes, and returns the resulting status.';
REVOKE ALL ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."record_sla_arrival"(p_clock_id uuid, p_arrived_at timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."recover_stale_cctv_inference_jobs"()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE recovered integer;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;
  UPDATE public.inference_jobs
     SET status = 'queued', stage = 'queued', lease_token = NULL,
         lease_expires_at = NULL, heartbeat_at = NULL,
         error_message = 'Recovered after orphaned worker claim'
   WHERE domain = 'video_motion'
     AND status = 'processing'
     AND (lease_token IS NULL OR lease_expires_at IS NULL OR lease_expires_at < clock_timestamp());
  GET DIAGNOSTICS recovered = ROW_COUNT;
  RETURN recovered;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."recover_stale_cctv_inference_jobs"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text DEFAULT 'nzta_featureserver'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_count integer;
  v_name text;
BEGIN
  -- Guard: never wipe the table with an empty input (Q6 ruling)
  IF p_names IS NULL OR array_length(p_names, 1) IS NULL OR array_length(p_names, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'REFRESH_REFUSED: input names array is empty. The NZTA source may be unavailable. The existing canonical_ta_names data has been preserved (Q6: never silently degrade).'
    );
  END IF;

  -- Upsert each name
  v_count := 0;
  FOREACH v_name IN ARRAY p_names LOOP
    INSERT INTO public.canonical_ta_names (ta_name, source, last_refreshed_at)
    VALUES (trim(v_name), p_source, now())
    ON CONFLICT (ta_name) DO UPDATE
      SET source = EXCLUDED.source,
          last_refreshed_at = EXCLUDED.last_refreshed_at;
    v_count := v_count + 1;
  END LOOP;

  -- Remove names that are no longer in the authoritative source
  -- (but only if we received a reasonable number of names -- at least 50
  -- to avoid accidental wipe from a partial fetch)
  IF v_count >= 50 THEN
    DELETE FROM public.canonical_ta_names
    WHERE ta_name NOT IN (SELECT unnest(p_names));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'upserted', v_count,
    'source', p_source,
    'refreshed_at', now()
  );
END;
$function$;
COMMENT ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) IS 'Upsert canonical TA names from a live NZTA fetch. Called by the bob-refresh-canonical-ta-names edge function. Refuses empty input (Q6: never silently degrade). Phase 2 geofence redesign (epic #226).';
REVOKE ALL ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."refresh_canonical_ta_names"(p_names text[], p_source text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."refresh_fs_nelson_clients_clean"()
 RETURNS TABLE(raw_rows integer, clean_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_raw_rows integer;
  v_clean_rows integer;
begin
  select count(*)::integer into v_raw_rows from public._seed_fs_nelson_clients_raw;

  truncate public.fs_nelson_clients_clean;

  insert into public.fs_nelson_clients_clean (
    bureau_id, bureau_name, client_id, client_name, client_address, client_suburb,
    client_postcode, client_state, patrol_type, onsite_datetime, offsite_datetime,
    comments, is_incident_report, patrol_complete_status, visit_charge_ex_gst,
    despatch_zone, subcontractor, onsite_distance_from_site, time_onsite_variation_mins,
    despatch_datetime, internal_clientid, internal_despatchid
  )
  select distinct on (
    coalesce(nullif(btrim(raw.client_id), ''), nullif(btrim(raw.internal_clientid), ''),
      lower(btrim(coalesce(raw.client_name, ''))) || '|' || lower(btrim(coalesce(raw.client_address, ''))))
  )
    nullif(btrim(raw.bureau_id), ''), nullif(btrim(raw.bureau_name), ''),
    nullif(btrim(raw.client_id), ''), nullif(btrim(raw.client_name), ''),
    nullif(btrim(raw.client_address), ''), nullif(btrim(raw.client_suburb), ''),
    nullif(btrim(raw.client_postcode), ''), nullif(btrim(raw.client_state), ''),
    nullif(btrim(raw.patrol_type), ''), nullif(btrim(raw.onsite_datetime), ''),
    nullif(btrim(raw.offsite_datetime), ''), nullif(btrim(raw.comments), ''),
    nullif(btrim(raw.is_incident_report), ''), nullif(btrim(raw.patrol_complete_status), ''),
    nullif(btrim(raw.visit_charge_ex_gst), ''), nullif(btrim(raw.despatch_zone), ''),
    nullif(btrim(raw.subcontractor), ''), nullif(btrim(raw.onsite_distance_from_site), ''),
    nullif(btrim(raw.time_onsite_variation_mins), ''), nullif(btrim(raw.despatch_datetime), ''),
    nullif(btrim(raw.internal_clientid), ''), nullif(btrim(raw.internal_despatchid), '')
  from public._seed_fs_nelson_clients_raw raw
  where nullif(btrim(raw.client_name), '') is not null
     or nullif(btrim(raw.client_address), '') is not null
  order by coalesce(nullif(btrim(raw.client_id), ''), nullif(btrim(raw.internal_clientid), ''),
      lower(btrim(coalesce(raw.client_name, ''))) || '|' || lower(btrim(coalesce(raw.client_address, '')))),
    raw.client_name, raw.client_address;

  get diagnostics v_clean_rows = row_count;
  return query select v_raw_rows, v_clean_rows;
end;
$function$;
COMMENT ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() IS 'Service-role staging reconciliation: normalizes and deduplicates Nelson client rows for canonical client/site comparison. It never creates organizations or sites.';
REVOKE ALL ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."refresh_fs_nelson_clients_clean"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  attachment public.bob_attachments%rowtype;
  evidence_id uuid;
  job_id uuid;
BEGIN
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Service identity required';
  END IF;

  SELECT * INTO attachment
    FROM public.bob_attachments
   WHERE id = p_attachment_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bob attachment not found';
  END IF;
  IF attachment.file_type NOT LIKE 'video/%' THEN
    RAISE EXCEPTION 'Bob attachment is not a video';
  END IF;

  SELECT id INTO evidence_id
    FROM public.evidence_items
   WHERE metadata->>'bob_attachment_id' = attachment.id::text
   LIMIT 1;
  IF evidence_id IS NULL THEN
    INSERT INTO public.evidence_items (
      organization_id,
      module_key,
      evidence_kind,
      storage_path,
      captured_by_user_id,
      metadata
    ) VALUES (
      attachment.organization_id,
      'cctv_review',
      'video',
      attachment.storage_path,
      attachment.uploaded_by,
      jsonb_build_object(
        'bob_attachment_id', attachment.id,
        'bob_conversation_id', attachment.conversation_id,
        'file_name', attachment.file_name,
        'file_type', attachment.file_type,
        'file_size_bytes', attachment.file_size_bytes,
        'storage_bucket', attachment.storage_bucket
      ) || jsonb_strip_nulls(jsonb_build_object(
        'desktop_review_batch', attachment.extraction_payload->'desktop_review_batch'
      ))
    ) RETURNING id INTO evidence_id;
  END IF;

  SELECT id INTO job_id
    FROM public.inference_jobs
   WHERE evidence_item_id = evidence_id
     AND domain = 'video_motion'
   LIMIT 1;
  IF job_id IS NULL THEN
    INSERT INTO public.inference_jobs (
      organization_id,
      evidence_item_id,
      domain,
      status,
      requested_by_user_id
    ) VALUES (
      attachment.organization_id,
      evidence_id,
      'video_motion',
      'queued',
      attachment.uploaded_by
    ) RETURNING id INTO job_id;
  END IF;

  UPDATE public.bob_attachments
     SET purpose = 'video_intake',
         processing_state = 'processing',
         extraction_summary = 'Queued for CCTV motion and risk review.',
         extraction_payload = coalesce(extraction_payload, '{}'::jsonb)
           || jsonb_build_object('evidence_item_id', evidence_id, 'inference_job_id', job_id),
         updated_at = now()
   WHERE id = attachment.id;

  RETURN job_id;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_bob_video_attachment_for_review"(p_attachment_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text DEFAULT NULL::text, p_recorded_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recorded_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_ref text DEFAULT NULL::text, p_content_type text DEFAULT 'video/mp4'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_import public.cctv_imports%rowtype; v_prefix text; v_ref text; v_evidence uuid; v_job uuid;
BEGIN
  SELECT * INTO v_import FROM public.cctv_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_import.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  v_prefix := 'org/' || v_import.organization_id::text || '/cctv/' || v_import.id::text || '/';
  IF p_storage_path IS NULL OR position(v_prefix in p_storage_path) <> 1 THEN
    RAISE EXCEPTION 'Video must be stored under %', v_prefix;
  END IF;
  IF coalesce(p_content_type, '') NOT LIKE 'video/%' THEN RAISE EXCEPTION 'Only video files are registered for CCTV review'; END IF;
  v_ref := coalesce(nullif(trim(p_source_ref), ''), nullif(trim(p_file_name), ''), p_storage_path);

  SELECT id INTO v_evidence FROM public.evidence_items WHERE cctv_import_id = v_import.id AND metadata->>'source_ref' = v_ref;
  IF v_evidence IS NULL THEN
    INSERT INTO public.evidence_items (organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, sha256_hash, cctv_import_id, metadata)
    VALUES (v_import.organization_id, 'cctv_review', 'video', p_storage_path, v_actor, coalesce(p_recorded_start_at, clock_timestamp()), nullif(trim(p_sha256), ''), v_import.id,
            jsonb_strip_nulls(jsonb_build_object(
              'file_name', p_file_name, 'file_type', coalesce(p_content_type, 'video/mp4'), 'file_size_bytes', p_file_size_bytes,
              'storage_bucket', 'bob-uploads', 'source_ref', v_ref, 'recorded_start_at', p_recorded_start_at, 'recorded_end_at', p_recorded_end_at,
              'cctv_import_id', v_import.id, 'camera_label', v_import.camera_label, 'camera_key', v_import.camera_key,
              'source_device_kind', v_import.source_device_kind, 'source_timezone', v_import.source_timezone,
              'location_id', v_import.location_id, 'canonical_place_id', v_import.canonical_place_id)))
    RETURNING id INTO v_evidence;
  END IF;
  SELECT id INTO v_job FROM public.inference_jobs WHERE evidence_item_id = v_evidence AND domain = 'video_motion' LIMIT 1;
  IF v_job IS NULL THEN
    INSERT INTO public.inference_jobs (organization_id, evidence_item_id, domain, status, requested_by_user_id)
    VALUES (v_import.organization_id, v_evidence, 'video_motion', 'queued', v_actor)
    RETURNING id INTO v_job;
  END IF;
  UPDATE public.cctv_imports SET status = CASE WHEN status IN ('draft', 'uploading') THEN 'registered' ELSE status END WHERE id = v_import.id;
  RETURN jsonb_build_object('evidence_item_id', v_evidence, 'inference_job_id', v_job, 'source_ref', v_ref);
END $function$;
REVOKE ALL ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_cctv_import_video"(p_import_id uuid, p_storage_path text, p_file_name text, p_file_size_bytes bigint, p_sha256 text, p_recorded_start_at timestamp with time zone, p_recorded_end_at timestamp with time zone, p_source_ref text, p_content_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_evidence_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Only trusted evidence-processing services may register edge photos';
  end if;

  insert into public.evidence_items (
    organization_id, module_key, evidence_kind, storage_path, captured_at,
    retention_days, metadata
  ) values (
    p_organization_id, p_module_key, 'photo', p_storage_path, p_captured_at,
    2555, p_metadata
  ) returning id into v_evidence_id;

  insert into public.audit_log (organization_id, action, target_table, target_id, metadata)
  values (p_organization_id, 'edge_court_photo_registered', 'evidence_items', v_evidence_id, p_metadata);

  return v_evidence_id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_edge_court_photo"(p_organization_id uuid, p_module_key text, p_storage_path text, p_captured_at timestamp with time zone, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text DEFAULT NULL::text, p_is_court_ready boolean DEFAULT false, p_retention_days integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, organization_id uuid, module_key text, evidence_kind text, storage_path text, sha256_hash text, is_court_ready boolean, retention_days integer, captured_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_item public.evidence_items%rowtype;
  v_retention integer := p_retention_days;
  v_clean_path text := nullif(trim(coalesce(p_storage_path, '')), '');
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active profile required for evidence registration'; end if;

  if nullif(trim(coalesce(p_module_key, '')), '') is null then
    raise exception 'module_key is required';
  end if;

  if p_evidence_kind not in ('photo', 'video', 'audio', 'document', 'note') then
    raise exception 'Unsupported evidence kind %', p_evidence_kind;
  end if;

  if v_clean_path is null then
    raise exception 'storage_path is required';
  end if;

  -- Derive retention_days from retention_policies if not explicitly provided
  if v_retention is null then
    select r.retention_days into v_retention
    from public.retention_policies r
    where (r.organization_id = v_org_id or r.organization_id is null)
      and (r.module_key = p_module_key or r.module_key is null)
      and r.is_active = true
    order by r.organization_id nulls last, r.module_key nulls last
    limit 1;
    if v_retention is null then v_retention := 2555; end if; -- Default 7 years (2555 days)
  end if;

  insert into public.evidence_items (
    organization_id, module_key, evidence_kind, storage_path, captured_by_user_id,
    captured_at, sha256_hash, is_court_ready, retention_days, metadata
  ) values (
    v_org_id, p_module_key, p_evidence_kind, v_clean_path, v_user_id,
    clock_timestamp(), nullif(trim(coalesce(p_sha256_hash, '')), ''), coalesce(p_is_court_ready, false), v_retention, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_item;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'evidence_media_registered', 'evidence_items', v_item.id,
    jsonb_build_object(
      'module_key', v_item.module_key,
      'evidence_kind', v_item.evidence_kind,
      'storage_path', v_item.storage_path,
      'sha256_hash', v_item.sha256_hash,
      'is_court_ready', v_item.is_court_ready,
      'retention_days', v_item.retention_days
    )
  );

  return query select v_item.id, v_item.organization_id, v_item.module_key, v_item.evidence_kind, v_item.storage_path, v_item.sha256_hash, v_item.is_court_ready, v_item.retention_days, v_item.captured_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_evidence_media_item"(p_module_key text, p_evidence_kind text, p_storage_path text, p_sha256_hash text, p_is_court_ready boolean, p_retention_days integer, p_metadata jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text DEFAULT 'expo'::text, p_device_name text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, push_token text, platform text, is_active boolean, last_seen_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_token public.officer_device_tokens%rowtype;
  v_clean_token text := trim(coalesce(p_push_token, ''));
  v_clean_platform text := lower(trim(coalesce(p_platform, 'expo')));
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null;
  if v_org_id is null then raise exception 'Active profile required for device registration'; end if;
  if v_clean_token = '' then raise exception 'push_token is required'; end if;
  if v_clean_platform not in ('expo', 'ios', 'android', 'web') then
    raise exception 'Unsupported device platform %', p_platform;
  end if;

  insert into public.officer_device_tokens (
    organization_id, user_id, push_token, platform, device_name, app_version, is_active, last_seen_at, updated_at
  ) values (
    v_org_id, v_user_id, v_clean_token, v_clean_platform, nullif(trim(coalesce(p_device_name, '')), ''), nullif(trim(coalesce(p_app_version, '')), ''), true, clock_timestamp(), clock_timestamp()
  )
  on conflict (organization_id, user_id, push_token) do update set
    platform = excluded.platform,
    device_name = coalesce(excluded.device_name, officer_device_tokens.device_name),
    app_version = coalesce(excluded.app_version, officer_device_tokens.app_version),
    is_active = true,
    last_seen_at = clock_timestamp(),
    updated_at = clock_timestamp()
  returning * into v_token;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'officer_device_token_registered', 'officer_device_tokens', v_token.id,
    jsonb_build_object('platform', v_token.platform, 'device_name', v_token.device_name, 'app_version', v_token.app_version)
  );

  return query select v_token.id, v_token.push_token, v_token.platform, v_token.is_active, v_token.last_seen_at;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_officer_device_token"(p_push_token text, p_platform text, p_device_name text, p_app_version text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text DEFAULT NULL::text, p_storage_path text DEFAULT NULL::text, p_asset_url text DEFAULT NULL::text, p_mime_type text DEFAULT NULL::text, p_sha256 text DEFAULT NULL::text, p_alt_text text DEFAULT NULL::text, p_usage_scope text DEFAULT 'documents'::text)
 RETURNS organization_brand_assets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_asset public.organization_brand_assets;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.is_admin_for_org(p_organization_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Brand asset registration denied'; END IF;
  IF nullif(trim(coalesce(p_label, '')), '') IS NULL THEN RAISE EXCEPTION 'Brand asset label is required'; END IF;
  IF p_storage_path IS NULL AND p_asset_url IS NULL THEN RAISE EXCEPTION 'Brand asset source is required'; END IF;

  INSERT INTO public.organization_brand_assets (
    organization_id, asset_kind, variant, label, storage_bucket, storage_path, asset_url,
    mime_type, sha256, alt_text, usage_scope, status, created_by
  ) VALUES (
    p_organization_id, p_asset_kind, p_variant, trim(p_label), p_storage_bucket, p_storage_path,
    p_asset_url, p_mime_type, p_sha256, nullif(trim(coalesce(p_alt_text, '')), ''), p_usage_scope,
    'pending', v_actor
  ) RETURNING * INTO v_asset;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'organization_brand_asset_registered', 'organization_brand_assets', v_asset.id,
    jsonb_build_object('asset_kind', p_asset_kind, 'variant', p_variant, 'usage_scope', p_usage_scope));
  RETURN v_asset;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."register_organization_brand_asset"(p_organization_id uuid, p_asset_kind text, p_variant text, p_label text, p_storage_bucket text, p_storage_path text, p_asset_url text, p_mime_type text, p_sha256 text, p_alt_text text, p_usage_scope text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_p public.boundary_proposals%rowtype;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF nullif(trim(coalesce(p_note, '')), '') IS NULL THEN RAISE EXCEPTION 'A rejection reason is required'; END IF;
  SELECT * INTO v_p FROM public.boundary_proposals WHERE id = p_proposal_id FOR UPDATE;
  IF NOT FOUND OR NOT public.org_access_allowed(v_p.organization_id) THEN RAISE EXCEPTION 'Proposal not found or access denied'; END IF;
  IF v_p.status <> 'proposed' THEN RAISE EXCEPTION 'Proposal is already %', v_p.status; END IF;
  UPDATE public.boundary_proposals SET status = 'rejected', decided_by = v_actor, decided_at = clock_timestamp(), decision_note = trim(p_note) WHERE id = v_p.id;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_p.organization_id, v_actor, 'boundary_proposal_rejected', 'boundary_proposals', v_p.id, jsonb_build_object('entity_type', v_p.entity_type, 'entity_id', v_p.entity_id, 'source', v_p.source, 'note', trim(p_note)));
  RETURN true;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reject_boundary_proposal"(p_proposal_id uuid, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid)
 RETURNS TABLE(invoice_id uuid, subtotal numeric, gst_amount numeric, total_amount numeric, removed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_invoice public.invoices%rowtype;
  v_line public.invoice_line_items%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select i.* into v_invoice from public.invoices i where i.id = p_invoice_id for update;
  if not found then
    raise exception 'Invoice not found';
  end if;

  if not public.is_admin_for_org(v_invoice.organization_id) then
    raise exception 'Not authorised to manage invoices for this organization';
  end if;

  if v_invoice.status <> 'draft' then
    raise exception 'Only draft invoices can be modified';
  end if;

  select l.* into v_line from public.invoice_line_items l where l.id = p_line_id and l.invoice_id = v_invoice.id;
  if not found then
    return query select v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, false;
    return;
  end if;

  delete from public.invoice_line_items where id = v_line.id;

  update public.invoices i set
    subtotal = totals.subtotal,
    gst_amount = round(totals.subtotal * 0.15, 2),
    total_amount = round(totals.subtotal * 1.15, 2),
    updated_at = now()
  from (
    select coalesce(sum(l.line_total), 0)::numeric(12,2) subtotal
    from public.invoice_line_items l
    where l.invoice_id = v_invoice.id
  ) totals
  where i.id = v_invoice.id
  returning i.* into v_invoice;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_invoice.organization_id,
    v_actor,
    'crm_invoice_line_removed',
    'invoice_line_items',
    v_line.id,
    jsonb_build_object(
      'invoice_id', v_invoice.id,
      'description', v_line.description,
      'line_total', v_line.line_total,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_invoice.id, v_invoice.subtotal, v_invoice.gst_amount, v_invoice.total_amount, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_invoice_line"(p_client_request_id uuid, p_invoice_id uuid, p_line_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text)
 RETURNS TABLE(quote_id uuid, total_cost numeric, subtotal_charge numeric, discount_amount numeric, gst_amount numeric, total_charge numeric, removed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_quote public.quotes%rowtype;
  v_line public.quote_lines%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select q.* into v_quote from public.quotes q where q.id = p_quote_id for update;
  if not found then
    raise exception 'Quote not found';
  end if;

  if not public.is_admin_for_org(v_quote.provider_org_id) then
    raise exception 'Not authorised to price this quote';
  end if;

  if v_quote.status <> p_expected_status then
    raise exception 'Quote changed from expected status % to %', p_expected_status, v_quote.status;
  end if;

  if v_quote.status <> 'draft' then
    raise exception 'Only draft quotes can be modified';
  end if;

  select l.* into v_line from public.quote_lines l where l.id = p_line_id and l.quote_id = v_quote.id;
  if not found then
    return query select v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge, false;
    return;
  end if;

  delete from public.quote_lines where id = v_line.id;

  update public.quotes q set
    total_cost = totals.total_cost,
    subtotal_charge = totals.subtotal_charge,
    discount_amount = round(totals.subtotal_charge * q.discount_pct / 100, 2),
    gst_amount = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * q.gst_rate, 2),
    total_charge = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * (1 + q.gst_rate), 2),
    updated_by = v_actor,
    updated_at = now()
  from (
    select
      coalesce(sum(l.quantity * l.unit_cost), 0)::numeric(12,2) total_cost,
      coalesce(sum(l.quantity * l.unit_charge), 0)::numeric(12,2) subtotal_charge
    from public.quote_lines l
    where l.quote_id = v_quote.id
  ) totals
  where q.id = v_quote.id
  returning q.* into v_quote;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_quote.provider_org_id,
    v_actor,
    'crm_quote_line_removed',
    'quote_lines',
    v_line.id,
    jsonb_build_object(
      'quote_id', v_quote.id,
      'kind', v_line.kind,
      'description', v_line.description,
      'total_cost', v_quote.total_cost,
      'total_charge', v_quote.total_charge,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."remove_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wo public.workshop_work_orders%rowtype;
  v_actor uuid := auth.uid();
  v_role text;
  v_line public.workshop_work_order_lines%rowtype;
begin
  select * into v_wo from public.workshop_work_orders w where w.id = p_work_order_id for update;
  if not found then raise exception 'Work order not found'; end if;
  v_role := public.workshop_line_actor_role(v_wo);
  if v_wo.status in ('completed', 'cancelled') then raise exception 'Lines cannot be removed once the work order is %', v_wo.status; end if;
  select * into v_line from public.workshop_work_order_lines l where l.id = p_line_id and l.work_order_id = v_wo.id;
  if not found then return; end if;
  if v_role = 'worker' and v_line.created_by is distinct from v_actor then
    raise exception 'You can only remove lines you added yourself';
  end if;
  delete from public.workshop_work_order_lines where id = v_line.id;
  update public.workshop_work_orders set updated_at = now(), updated_by = v_actor where id = v_wo.id;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."remove_workshop_work_order_line"(p_work_order_id uuid, p_line_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text)
 RETURNS TABLE(credential_id uuid, staff_id uuid, verified boolean, verified_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_source public.staff_credentials%rowtype;v_renewal public.staff_credentials%rowtype;v_number text:=nullif(trim(coalesce(p_credential_number,'')),'');v_authority text:=nullif(trim(coalesce(p_issuing_authority,'')),'');v_notes text:=nullif(trim(coalesce(p_evidence_notes,'')),'');
begin
  if p_client_request_id is null then raise exception 'Client request ID is required';end if;
  select c.* into v_source from public.staff_credentials c where c.id=p_source_credential_id for update;if not found then raise exception 'Source credential not found';end if;
  if not public.is_admin_for_org(v_source.organization_id) then raise exception 'Active provider administrator required';end if;
  if v_source.expiry_date is distinct from p_expected_expiry_date then raise exception 'Credential expiry changed from expected state';end if;
  if v_source.expiry_date is null then raise exception 'Only expiring credentials can be renewed';end if;
  if v_number is null or v_authority is null or v_notes is null or length(v_notes)<10 then raise exception 'Credential number, issuing authority, and evidence notes are required';end if;
  if p_issued_date is null or p_expiry_date is null or p_issued_date>p_expiry_date or p_expiry_date<=v_source.expiry_date then raise exception 'Renewal dates must establish a later valid credential';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_client_request_id::text,0));
  select c.* into v_renewal from public.staff_credentials c where c.organization_id=v_source.organization_id and c.client_request_id=p_client_request_id;
  if found then if v_renewal.replaces_credential_id<>v_source.id then raise exception 'Credential renewal request identity collision';end if;return query select v_renewal.id,v_renewal.staff_id,v_renewal.verified,v_renewal.verified_at,false;return;end if;
  insert into public.staff_credentials(staff_id,organization_id,credential_type,credential_number,issuing_authority,issued_date,expiry_date,authorized_activities,verified,verified_by,verified_at,notes,client_request_id,replaces_credential_id) values(v_source.staff_id,v_source.organization_id,v_source.credential_type,v_number,v_authority,p_issued_date,p_expiry_date,v_source.authorized_activities,true,v_actor,clock_timestamp(),v_notes,p_client_request_id,v_source.id) returning * into v_renewal;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_source.organization_id,v_actor,'staff_credential_renewed','staff_credentials',v_renewal.id,jsonb_build_object('source_credential_id',v_source.id,'staff_id',v_source.staff_id,'credential_type',v_source.credential_type,'previous_expiry_date',v_source.expiry_date,'expiry_date',v_renewal.expiry_date,'evidence_notes',v_notes));
  return query select v_renewal.id,v_renewal.staff_id,v_renewal.verified,v_renewal.verified_at,true;
end;$function$;
REVOKE ALL ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."renew_staff_credential"(p_client_request_id uuid, p_source_credential_id uuid, p_expected_expiry_date date, p_credential_number text, p_issuing_authority text, p_issued_date date, p_expiry_date date, p_evidence_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date)
 RETURNS TABLE(created_count integer, skipped_conflict_count integer, leave_conflict_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid := auth.uid(); v_source public.roster_slots%rowtype; v_day date; v_start timestamptz; v_end timestamptz; v_created integer := 0; v_skipped integer := 0; v_leave integer := 0; v_duration interval;
begin
  select s.* into v_source from public.roster_slots s where s.id = p_source_slot_id for update;
  if not found then raise exception 'Roster slot not found'; end if;
  if not public.is_admin_for_org(v_source.organization_id) then raise exception 'Roster administrator required'; end if;
  if v_source.status in ('completed', 'cancelled') then raise exception 'Completed or cancelled slots cannot be repeated'; end if;
  if p_from_date is null or p_to_date is null or p_from_date > p_to_date or p_to_date - p_from_date > 92 then raise exception 'Repeat period must be between 1 and 93 days'; end if;
  v_duration := v_source.scheduled_end - v_source.scheduled_start;
  for v_day in select generate_series(p_from_date, p_to_date, interval '1 day')::date loop
    v_start := v_day + (v_source.scheduled_start::time);
    v_end := v_start + v_duration;
    if exists (select 1 from public.leave_requests l where l.staff_id = v_source.staff_id and l.status = 'approved' and daterange(l.starts_on, l.ends_on, '[]') && daterange(v_start::date, v_end::date, '[]')) then v_leave := v_leave + 1; continue; end if;
    if exists (select 1 from public.roster_slots s where s.staff_id = v_source.staff_id and s.status not in ('declined','cancelled') and s.scheduled_start < v_end and s.scheduled_end > v_start) then v_skipped := v_skipped + 1; continue; end if;
    insert into public.roster_slots (organization_id, work_unit_id, staff_id, scheduled_start, scheduled_end, status, client_request_id, notes, created_by) values (v_source.organization_id, v_source.work_unit_id, v_source.staff_id, v_start, v_end, 'draft', gen_random_uuid(), coalesce(v_source.notes, '') || ' · Repeated assignment', v_actor);
    v_created := v_created + 1;
  end loop;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_source.organization_id, v_actor, 'roster_slot_repeated', 'roster_slots', v_source.id, jsonb_build_object('from_date', p_from_date, 'to_date', p_to_date, 'created_count', v_created, 'skipped_conflict_count', v_skipped, 'leave_conflict_count', v_leave));
  return query select v_created, v_skipped, v_leave;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."repeat_roster_slot_range"(p_source_slot_id uuid, p_from_date date, p_to_date date) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text DEFAULT 'approved_provider'::text, p_requested_scopes text[] DEFAULT ARRAY['account_transactions'::text, 'balances'::text, 'payment_matches'::text], p_consent_confirmed boolean DEFAULT false)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_account public.bank_accounts%rowtype; v_request public.finance_external_connection_requests%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_connection_mode NOT IN ('oauth','approved_provider','secure_file_import','manual_review') THEN RAISE EXCEPTION 'Unsupported ANZ connection method'; END IF;
  IF NOT p_consent_confirmed THEN RAISE EXCEPTION 'ANZ connection consent is required'; END IF;
  SELECT * INTO v_account FROM public.bank_accounts WHERE id = p_bank_account_id AND organization_id = v_org AND is_active AND bank_name ILIKE '%ANZ%';
  IF NOT FOUND THEN RAISE EXCEPTION 'Select an active ANZ bank account'; END IF;
  INSERT INTO public.finance_external_connection_requests(organization_id, provider_type, provider_name, connection_mode, requested_scopes, bank_account_id, consent_confirmed, consent_confirmed_by, consent_confirmed_at, status, setup_summary, created_by)
  VALUES (v_org, 'bank', 'ANZ', p_connection_mode, COALESCE(p_requested_scopes, ARRAY['account_transactions','balances','payment_matches']), p_bank_account_id, true, v_actor, now(), 'awaiting_authorisation', jsonb_build_object('bank', 'ANZ', 'credentials_collected', false, 'human_approval_required', true, 'data_minimised', true, 'adapter_required', 'approved ANZ/Open Banking provider'), v_actor)
  ON CONFLICT (organization_id, provider_type, bank_account_id) DO UPDATE SET provider_name = 'ANZ', connection_mode = EXCLUDED.connection_mode, requested_scopes = EXCLUDED.requested_scopes, consent_confirmed = true, consent_confirmed_by = EXCLUDED.consent_confirmed_by, consent_confirmed_at = now(), status = CASE WHEN finance_external_connection_requests.status = 'connected' THEN finance_external_connection_requests.status ELSE 'awaiting_authorisation' END, setup_summary = EXCLUDED.setup_summary, updated_at = now()
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'anz_bank_connection_requested', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_name', 'ANZ', 'bank_account_id', p_bank_account_id, 'credentials_collected', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_anz_bank_connection"(p_bank_account_id uuid, p_connection_mode text, p_requested_scopes text[], p_consent_confirmed boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text)
 RETURNS bob_generated_document_outputs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_org_id uuid;
  v_status text;
  v_output public.bob_generated_document_outputs;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_output_format NOT IN ('pdf', 'docx', 'print') THEN RAISE EXCEPTION 'Unsupported output format'; END IF;

  SELECT d.organization_id, coalesce(dv.metadata_json->>'authoring_status', '')
  INTO v_org_id, v_status
  FROM public.documents d JOIN public.document_versions dv ON dv.document_id = d.id
  WHERE d.id = p_document_id AND dv.id = p_document_version_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Document version not found'; END IF;
  IF NOT public.is_admin_for_org(v_org_id) AND NOT public.is_grand_master() THEN RAISE EXCEPTION 'Document output request denied'; END IF;
  IF v_status <> 'approved' THEN RAISE EXCEPTION 'Only approved document versions can produce outputs'; END IF;

  INSERT INTO public.bob_generated_document_outputs (
    organization_id, document_id, document_version_id, output_format, requested_by, approved_by, approved_at
  ) VALUES (v_org_id, p_document_id, p_document_version_id, p_output_format, v_actor, v_actor, clock_timestamp())
  RETURNING * INTO v_output;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_actor, 'bob_document_output_requested', 'bob_generated_document_outputs', v_output.id,
    jsonb_build_object('document_id', p_document_id, 'document_version_id', p_document_version_id, 'output_format', p_output_format));
  RETURN v_output;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_bob_document_output"(p_document_id uuid, p_document_version_id uuid, p_output_format text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[] DEFAULT '{}'::text[], p_bank_account_id uuid DEFAULT NULL::uuid, p_consent_confirmed boolean DEFAULT false)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_org uuid; v_request public.finance_external_connection_requests%rowtype; v_account public.bank_accounts%rowtype;
BEGIN
  SELECT organization_id INTO v_org FROM public.user_profiles WHERE id = v_actor AND deactivated_at IS NULL;
  IF v_org IS NULL OR NOT public.is_admin_for_org(v_org) THEN RAISE EXCEPTION 'Active finance administrator required'; END IF;
  IF p_provider_type NOT IN ('ird','bank') THEN RAISE EXCEPTION 'Unsupported finance connection'; END IF;
  IF p_connection_mode NOT IN ('oauth','approved_provider','secure_file_import','manual_review') THEN RAISE EXCEPTION 'Unsupported connection method'; END IF;
  IF p_provider_type = 'bank' AND p_bank_account_id IS NULL THEN RAISE EXCEPTION 'Select the bank account to connect'; END IF;
  IF p_provider_type = 'bank' THEN
    SELECT * INTO v_account FROM public.bank_accounts WHERE id = p_bank_account_id AND organization_id = v_org AND is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active bank account not found in organization'; END IF;
  END IF;
  IF NOT p_consent_confirmed THEN RAISE EXCEPTION 'Connection consent is required'; END IF;
  INSERT INTO public.finance_external_connection_requests(organization_id, provider_type, connection_mode, requested_scopes, bank_account_id, consent_confirmed, consent_confirmed_by, consent_confirmed_at, status, setup_summary, created_by)
  VALUES (v_org, p_provider_type, p_connection_mode, COALESCE(p_requested_scopes, '{}'), p_bank_account_id, true, v_actor, now(), 'awaiting_authorisation', jsonb_build_object('credentials_collected', false, 'human_approval_required', true, 'data_minimised', true, 'next_action', CASE WHEN p_provider_type = 'ird' THEN 'Complete the approved IRD/provider authorization window' ELSE 'Complete the approved bank-provider authorization window' END), v_actor)
  ON CONFLICT (organization_id, provider_type, bank_account_id) DO UPDATE SET connection_mode = EXCLUDED.connection_mode, requested_scopes = EXCLUDED.requested_scopes, consent_confirmed = true, consent_confirmed_by = EXCLUDED.consent_confirmed_by, consent_confirmed_at = now(), status = CASE WHEN finance_external_connection_requests.status = 'connected' THEN finance_external_connection_requests.status ELSE 'awaiting_authorisation' END, setup_summary = EXCLUDED.setup_summary, updated_at = now()
  RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_org, v_actor, 'finance_external_connection_requested', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', p_provider_type, 'connection_mode', p_connection_mode, 'requested_scopes', p_requested_scopes, 'credentials_collected', false));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_finance_external_connection"(p_provider_type text, p_connection_mode text, p_requested_scopes text[], p_bank_account_id uuid, p_consent_confirmed boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid DEFAULT NULL::uuid, p_swap_type text DEFAULT 'open'::text, p_reason text DEFAULT NULL::text)
 RETURNS shift_swaps
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid(); v_shift public.shifts%rowtype; v_original_staff public.staff_profiles%rowtype; v_replacement public.staff_profiles%rowtype; v_swap public.shift_swaps%rowtype; v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  if p_swap_type not in ('open', 'direct', 'coverage_request') then raise exception 'Unsupported shift swap type'; end if;
  if v_reason is null then raise exception 'A reason is required for a shift swap request'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_actor then raise exception 'Only the assigned officer can request a swap'; end if;
  if v_shift.status not in ('scheduled', 'published', 'accepted') then raise exception 'Only unstarted shifts can be swapped'; end if;
  select sp.* into v_original_staff from public.staff_profiles sp where sp.organization_id = v_shift.organization_id and (sp.user_id = v_actor or sp.id = v_actor) and sp.work_ready;
  if not found then raise exception 'Active work-ready staff profile required'; end if;
  if p_swap_with_staff_id is not null then
    if p_swap_type <> 'direct' then raise exception 'A replacement officer requires a direct swap'; end if;
    select sp.* into v_replacement from public.staff_profiles sp where sp.id = p_swap_with_staff_id and sp.organization_id = v_shift.organization_id and sp.work_ready;
    if not found or v_replacement.id = v_original_staff.id then raise exception 'Replacement officer is not eligible'; end if;
    if exists (select 1 from public.roster_slots rs where rs.staff_id = v_replacement.id and rs.status not in ('declined', 'cancelled') and rs.scheduled_start < v_shift.scheduled_end and rs.scheduled_end > v_shift.scheduled_start) then raise exception 'Replacement officer has an overlapping roster assignment'; end if;
  end if;
  select sw.* into v_swap from public.shift_swaps sw where sw.organization_id = v_shift.organization_id and sw.original_shift_id = v_shift.id and sw.status = 'pending' order by sw.created_at desc limit 1;
  if found then return v_swap; end if;
  insert into public.shift_swaps (organization_id, original_shift_id, original_staff_id, swap_with_staff_id, swap_type, reason, status, requested_by, requested_at) values (v_shift.organization_id, v_shift.id, v_original_staff.id, p_swap_with_staff_id, p_swap_type, v_reason, 'pending', v_actor, clock_timestamp()) returning * into v_swap;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata) values (v_shift.organization_id, v_actor, 'shift_swap_requested', 'shift_swaps', v_swap.id, jsonb_build_object('shift_id', v_shift.id, 'swap_type', p_swap_type, 'replacement_staff_id', p_swap_with_staff_id, 'reason', v_reason, 'client_request_id', p_client_request_id));
  if p_swap_with_staff_id is not null and v_replacement.user_id is not null then perform public.enqueue_notification(v_shift.organization_id, 'roster', 'Direct shift swap requested', 'An officer has requested you take a rostered shift. Await roster approval.', 'warning', v_replacement.user_id, null, 'schedule', jsonb_build_object('shift_swap_id', v_swap.id, 'shift_id', v_shift.id), 'shift_swap_requested:' || v_swap.id::text); end if;
  return v_swap;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."request_shift_swap"(p_client_request_id uuid, p_shift_id uuid, p_swap_with_staff_id uuid, p_swap_type text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text DEFAULT 'INF'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_sequence integer;
  v_prefix text := coalesce(nullif(trim(p_prefix), ''), 'INF');
BEGIN
  IF v_actor IS NULL OR NOT public.org_access_allowed(p_organization_id) THEN
    RAISE EXCEPTION 'Organization access required';
  END IF;
  INSERT INTO public.infringement_notice_counters (organization_id, module_key, last_number, prefix)
  VALUES (p_organization_id, p_module_key, 1, v_prefix)
  ON CONFLICT (organization_id, module_key)
  DO UPDATE SET last_number = infringement_notice_counters.last_number + 1,
                updated_at = now()
  RETURNING last_number, prefix INTO v_sequence, v_prefix;
  RETURN format('%s-%s-%s', v_prefix, to_char(current_date, 'YYYYMMDD'), lpad(v_sequence::text, 4, '0'));
END;
$function$;
REVOKE ALL ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."reserve_infringement_notice_number"(p_organization_id uuid, p_module_key text, p_prefix text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."resolve_access_basis"(p_user uuid DEFAULT auth.uid(), p_observation_id uuid DEFAULT NULL::uuid, p_noise_assessment_id uuid DEFAULT NULL::uuid, p_smoke_assessment_id uuid DEFAULT NULL::uuid, p_biosecurity_assessment_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid, p_notice_id uuid DEFAULT NULL::uuid, p_enforcement_case_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ref_count      int;
  v_caller         uuid := auth.uid();
  v_basis          text := null;
  v_expiry         text := null;
begin
  -- ========================================================
  -- 0329 IDENTITY GUARD (SELF-ONLY). Server-derived caller; reject any request
  -- to resolve someone else's basis. This is the ONLY change from the 0327
  -- body; every basis branch below is reproduced verbatim.
  --
  -- p_user defaults to auth.uid() (UI sends no id). If a caller explicitly
  -- passes a p_user that is not themselves, or is unauthenticated, resolve to
  -- NO basis -- an informative, content-free statement (reject by
  -- non-appearance, never an error that would itself confirm anything).
  -- ========================================================
  if v_caller is null or p_user is null or p_user <> v_caller then
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- COMPOSITION CONTRACT (ACCESS_MODEL.md section 7): this resolver returns on
  -- the FIRST basis found, and the branch order below IS the composition rule -
  -- strongest depth first (ownership -> dispatch on-scene -> dispatch en-route
  -- -> roster -> supervisory), so "first match" == "maximum depth". This
  -- ordering is LOAD-BEARING: do not reorder without switching to an explicit
  -- resolve-all-then-take-max-depth form, or a weaker basis could shadow a
  -- stronger one and under-grant (a lockout).
  -- Exactly-one-record guard (mirrors task_assignments chk_one_record).
  v_ref_count :=
      (case when p_observation_id            is not null then 1 else 0 end)
    + (case when p_noise_assessment_id       is not null then 1 else 0 end)
    + (case when p_smoke_assessment_id       is not null then 1 else 0 end)
    + (case when p_biosecurity_assessment_id is not null then 1 else 0 end)
    + (case when p_incident_id               is not null then 1 else 0 end)
    + (case when p_notice_id                 is not null then 1 else 0 end)
    + (case when p_enforcement_case_id       is not null then 1 else 0 end);

  if v_ref_count <> 1 then
    -- Malformed call: no basis. (section 0: absent basis, not a verdict.)
    return jsonb_build_object(
      'decision_state',       'no_task_entitlement',
      'granted_basis',        null,
      'failed_gate',          'task',
      'expiry_end_condition', null,
      'sensitivity_mode',     'informative',
      'message_key',          'access.no_live_basis'
    );
  end if;

  -- ========================================================
  -- OWNERSHIP-DERIVED bases (task_assignments 0323; geofence NOT required).
  -- follow_up_ownership + direct_module_initiation resolve FULL depth.
  -- A live row with ended_at IS NULL is a LIVE basis.
  -- ========================================================
  select ta.basis,
         'basis_ends: ' || coalesce(ta.end_reason, 'live until ended_at set')
    into v_basis, v_expiry
  from public.task_assignments ta
  where ta.user_id = p_user
    and ta.ended_at is null
    and (
         (p_observation_id            is not null and ta.observation_id            = p_observation_id)
      or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
      or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
      or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
      or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
      or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
      or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
    )
    -- Prefer the strongest ownership basis first (follow_up/initiation = full;
    -- backup graduates and is handled in the presence block for its depth).
    order by case ta.basis
               when 'follow_up_ownership'       then 1
               when 'direct_module_initiation'  then 2
               when 'backup_attachment'         then 3
               else 4 end
    limit 1;

  if v_basis in ('follow_up_ownership', 'direct_module_initiation') then
    -- Ownership-derived: FULL working depth (section 3: geofence may be false;
    -- report writing / QA / handover must not break). S12 no-lockout case.
    return jsonb_build_object(
      'decision_state',       'full_access',
      'granted_basis',        v_basis,
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.' || v_basis
    );
  elsif v_basis = 'backup_attachment' then
    -- R1: backup graduates. Without a live-geofence gate in v1, the task record
    -- itself is the presence proof; a live backup attachment earns operational
    -- depth (on-scene upgrade is a v-next hardening, ACCESS_MODEL section 3).
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'backup_attachment',
      'failed_gate',          'none',
      'expiry_end_condition', v_expiry,
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.backup_attachment'
    );
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: dispatch_response (TIMESTAMP-LED graduation, S3/S13).
  -- Officer link: dispatch_jobs.dispatch_resource_id
  --   -> dispatch_resources.assigned_officer_id (live-verified path).
  -- Depth: dispatched_at set -> operational_only (en route);
  --        on_scene_at set   -> full_access (arrived).
  -- 0327 PLACE-LINK (Bug 2 fix): the dispatch job must be for the SAME SITE as
  -- the observation -- dj.client_site_id = o.site_id (the only place pair
  -- anchored in the live schema at both ends). FAIL-CLOSED: an observation with
  -- no site_id gets no dispatch basis (the join cannot match a null).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and dj.on_scene_at is not null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      return jsonb_build_object(
        'decision_state',       'full_access',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.on_scene'
      );
    end if;

    perform 1
      from public.dispatch_jobs dj
      join public.dispatch_resources dr on dr.id = dj.dispatch_resource_id
      join public.observations o on o.id = p_observation_id
     where dr.assigned_officer_id = p_user
       and dj.dispatched_at is not null
       and dj.completed_at is null
       and o.site_id is not null
       and dj.client_site_id = o.site_id;
    if found then
      -- En route (dispatched, not yet on-scene): operational_only (S13/S3).
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'dispatch_response',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: dispatch completed_at set, reassignment, or 24h grace (Q1)',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.dispatch_response.en_route'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE-DERIVED: rostered_presence.
  -- Officer link: shift_stops JOIN shifts (shifts.officer_user_id) - shift_stops
  -- has NO direct officer column (live-verified; the substrate-note trap).
  -- Live presence = a non-terminal stop (status not in the done set).
  -- Depth: presence-alone caps at operational_only (section 7 composition, S11).
  -- v1: the roster record is the presence proof (geofence deferred).
  -- ========================================================
  if p_observation_id is not null then
    perform 1
      from public.shift_stops ss
      join public.shifts s on s.id = ss.shift_id
      join public.observations o on o.id = p_observation_id
     where s.officer_user_id = p_user
       and ss.status not in ('completed', 'skipped', 'cancelled')
       and (
              (ss.site_id is not null and ss.site_id = o.site_id)
           or (ss.zone_id is not null and ss.zone_id = o.zone_id)
       );
    if found then
      -- S11: inside the tasked place, presence basis -> operational_only, NEVER
      -- narrative history from presence alone.
      return jsonb_build_object(
        'decision_state',       'operational_only',
        'granted_basis',        'rostered_presence',
        'failed_gate',          'none',
        'expiry_end_condition', 'basis_ends: stop completed/skipped/cancelled or shift end',
        'sensitivity_mode',     'informative',
        'message_key',          'access.granted.rostered_presence'
      );
    end if;
  end if;

  -- ========================================================
  -- PRESENCE/RESPONSIBILITY: supervisory_review (R2 scoped default).
  -- staff_reporting: this user is the reports_to for an officer who holds a live
  -- task basis on THIS record; active line = effective_to IS NULL.
  -- Default depth (sensitive subject-matter): operational_only (R2). The
  -- officer-SAFETY inversion (full_access) is NOT auto-resolved here - it is a
  -- named, record-bound escalation basis (R2 exception / S10), reserved for the
  -- welfare/duress path, never a broad supervisor read.
  -- ========================================================
  perform 1
    from public.staff_reporting sr
    join public.task_assignments ta on ta.user_id = sr.user_id and ta.ended_at is null
   where sr.reports_to_user_id = p_user
     and sr.effective_to is null
     and (
           (p_observation_id            is not null and ta.observation_id            = p_observation_id)
        or (p_noise_assessment_id       is not null and ta.noise_assessment_id       = p_noise_assessment_id)
        or (p_smoke_assessment_id       is not null and ta.smoke_assessment_id       = p_smoke_assessment_id)
        or (p_biosecurity_assessment_id is not null and ta.biosecurity_assessment_id = p_biosecurity_assessment_id)
        or (p_incident_id               is not null and ta.incident_id               = p_incident_id)
        or (p_notice_id                 is not null and ta.notice_id                 = p_notice_id)
        or (p_enforcement_case_id       is not null and ta.enforcement_case_id       = p_enforcement_case_id)
     );
  if found then
    return jsonb_build_object(
      'decision_state',       'operational_only',
      'granted_basis',        'supervisory_review',
      'failed_gate',          'none',
      'expiry_end_condition', 'basis_ends: reporting responsibility ends or supervised task ends (R2)',
      'sensitivity_mode',     'informative',
      'message_key',          'access.granted.supervisory_review'
    );
  end if;

  -- ========================================================
  -- No live task basis found. section 0: this is ABSENT BASIS, not a verdict on
  -- the reader. operator_custody + lawful_production are SEPARATE named bases,
  -- resolved elsewhere (R3) - deliberately NOT granted here.
  -- ========================================================
  return jsonb_build_object(
    'decision_state',       'no_task_entitlement',
    'granted_basis',        null,
    'failed_gate',          'task',
    'expiry_end_condition', null,
    'sensitivity_mode',     'informative',
    'message_key',          'access.no_live_basis'
  );
end;
$function$;
COMMENT ON FUNCTION "public"."resolve_access_basis"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) IS 'BASIS ENGINE (ACCESS_MODEL.md sections 8/11). SECURITY DEFINER + fixed search_path (0326). 0327: dispatch branch SITE-ANCHORED. 0329: SELF-ONLY - p_user defaults to auth.uid() and any p_user <> auth.uid() (or unauthenticated) resolves to no-basis. Closes the caller-supplied-identity impersonation surface on the direct-RPC / UI path. No supervisor/GM cross-user carve-out (separate privileged path if ever needed). Narrow contract: one SELF user, one record, verdict only.';
