CREATE OR REPLACE FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text DEFAULT NULL::text)
 RETURNS cctv_imports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_row public.cctv_imports%rowtype;
BEGIN
  SELECT * INTO v_row FROM public.cctv_imports WHERE id = p_import_id FOR UPDATE;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'CCTV import not found'; END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_row.organization_id) THEN RAISE EXCEPTION 'CCTV import access denied'; END IF;
  IF jsonb_typeof(p_manifest) <> 'array' THEN RAISE EXCEPTION 'Manifest must be an array'; END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('draft', 'uploading', 'registered', 'processing', 'review_ready', 'archived', 'failed') THEN
    RAISE EXCEPTION 'Unknown import status %', p_status;
  END IF;
  UPDATE public.cctv_imports SET
    source_manifest = p_manifest,
    video_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' = 'video'),
    skipped_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' = 'skipped_empty'),
    snapshot_count = (SELECT count(*) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' = 'snapshot'),
    bytes_total = (SELECT coalesce(sum((f->>'size_bytes')::bigint), 0) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' IN ('video', 'snapshot')),
    recorded_from = (SELECT min((f->>'slot_start_at')::timestamptz) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' = 'video' AND nullif(f->>'slot_start_at', '') IS NOT NULL),
    recorded_to = (SELECT max(coalesce((f->>'slot_end_at')::timestamptz, (f->>'slot_start_at')::timestamptz)) FROM jsonb_array_elements(p_manifest) f WHERE f->>'kind' = 'video' AND nullif(f->>'slot_start_at', '') IS NOT NULL),
    status = coalesce(p_status, status)
  WHERE id = p_import_id RETURNING * INTO v_row;
  RETURN v_row;
END $function$;
REVOKE ALL ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_import_manifest"(p_import_id uuid, p_manifest jsonb, p_status text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_allowed jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND session_user NOT IN ('postgres', 'supabase_admin') THEN RAISE EXCEPTION 'Service identity required'; END IF;
  IF p_playback IS NULL OR jsonb_typeof(p_playback) <> 'object' THEN RAISE EXCEPTION 'Playback details must be a JSON object'; END IF;
  -- Only the playback keys may arrive through this path; the source provenance is untouchable here.
  SELECT coalesce(jsonb_object_agg(key, value), '{}'::jsonb) INTO v_allowed
    FROM jsonb_each(p_playback)
   WHERE key IN ('playback_storage_path', 'playback_content_type', 'playback_transcode_profile', 'playback_source_codec', 'playback_source_preserved', 'playback_prepared_at');
  IF v_allowed = '{}'::jsonb THEN RAISE EXCEPTION 'No playback keys supplied'; END IF;
  UPDATE public.evidence_items
     SET metadata = metadata || v_allowed || jsonb_build_object('playback_prepared_at', coalesce(v_allowed->>'playback_prepared_at', clock_timestamp()::text))
   WHERE id = p_evidence_id;
  RETURN FOUND;
END $function$;
COMMENT ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) IS 'Service-only: merges the derived playback-copy keys into evidence_items.metadata (jsonb ||) so the source hash provenance recorded moments earlier is never overwritten by a stale read.';
REVOKE ALL ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_cctv_playback_copy"(p_evidence_id uuid, p_playback jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text)
 RETURNS quote_proposal_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote public.quotes%rowtype;
  v_module public.quote_proposal_modules%rowtype;
begin
  select * into v_quote from public.quotes where id = p_quote_id for update;
  if not found or not public.is_admin_for_org(v_quote.provider_org_id) then raise exception 'Quote not found in your organization'; end if;
  if v_quote.status <> 'draft' then raise exception 'Work model can only be changed on a draft quote'; end if;
  if p_work_model not in ('scheduled_patrol', 'scheduled_static', 'on_demand_callout', 'inspection_or_notice', 'recurring_service') then raise exception 'Unsupported proposal work model'; end if;
  update public.quote_proposal_modules set work_model = p_work_model where quote_id = v_quote.id and module_key = p_module_key returning * into v_module;
  if not found then raise exception 'Proposal module not found'; end if;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
  values(v_quote.provider_org_id,auth.uid(),'crm_quote_proposal_work_model_set','quote_proposal_modules',v_module.id,jsonb_build_object('quote_id',v_quote.id,'module_key',p_module_key,'work_model',p_work_model));
  return v_module;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_crm_quote_proposal_work_model"(p_quote_id uuid, p_module_key text, p_work_model text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid DEFAULT NULL::uuid, p_harmed_party_address text DEFAULT NULL::text, p_party_role text DEFAULT 'complainant'::text, p_display_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_harmed_party_lat double precision DEFAULT NULL::double precision, p_harmed_party_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(out_dispatch_job_id uuid, out_harmed_party_site_id uuid, protected_party_recorded boolean, place_created boolean, house_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_org uuid;
  v_role text;
  v_job public.dispatch_jobs%rowtype;
  v_client_org uuid;
  v_site_id uuid := p_harmed_party_site_id;
  v_address text := nullif(trim(coalesce(p_harmed_party_address, '')), '');
  v_place record;
  v_place_created boolean := false;
  v_house_action text := NULL;
  v_has_identity boolean;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  SELECT p.organization_id, p.role INTO v_org, v_role FROM public.user_profiles p WHERE p.id = v_user AND p.deactivated_at IS NULL;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Active profile required'; END IF;
  SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job not found'; END IF;
  IF NOT (public.is_admin_for_org(v_job.organization_id) OR (v_role = 'admin_officer' AND v_org = v_job.organization_id)) THEN
    RAISE EXCEPTION 'Dispatcher or administrator of the custodian organisation required';
  END IF;
  IF p_party_role NOT IN ('complainant', 'occupant', 'witness', 'landowner') THEN RAISE EXCEPTION 'Unsupported party role'; END IF;
  SELECT a.client_organization_id INTO v_client_org FROM public.service_agreements a WHERE a.id = v_job.service_agreement_id;

  IF v_site_id IS NOT NULL THEN
    -- The harmed-party site grants its owner the harmed-party read (W1), so it must be the job's client or the custodian.
    IF NOT EXISTS (SELECT 1 FROM public.client_sites cs WHERE cs.id = v_site_id
                   AND cs.client_organization_id IN (v_job.organization_id, COALESCE(v_client_org, v_job.organization_id))) THEN
      RAISE EXCEPTION 'Harmed-party site must belong to the job''s client or custodian organisation';
    END IF;
  ELSIF v_address IS NOT NULL AND p_harmed_party_lat IS NOT NULL AND p_harmed_party_lng IS NOT NULL THEN
    -- Address-only place resolved to coordinates: same pipeline as the work place. The platform's
    -- autolink trigger attaches every client-org site to its current agreement (that is what gives
    -- the custodian access to the place); site_origin = 'adhoc' marks it as not contracted.
    SELECT * INTO v_place FROM public.resolve_or_create_dispatch_place_site(
      v_job.organization_id, COALESCE(v_client_org, v_job.organization_id), v_address, v_address, p_harmed_party_lat, p_harmed_party_lng, v_user);
    v_site_id := v_place.site_id;
    v_place_created := v_place.site_created;
    v_house_action := v_place.house_action;
  END IF;

  UPDATE public.dispatch_jobs
  SET harmed_party_site_id = COALESCE(v_site_id, dispatch_jobs.harmed_party_site_id),
      harmed_party_address = COALESCE(v_address, dispatch_jobs.harmed_party_address)
  WHERE id = v_job.id;

  v_has_identity := nullif(trim(coalesce(p_display_name, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_phone, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_email, '')), '') IS NOT NULL
    OR nullif(trim(coalesce(p_notes, '')), '') IS NOT NULL;
  IF v_has_identity THEN
    INSERT INTO public.dispatch_job_protected_parties (organization_id, dispatch_job_id, party_role, display_name, phone, email, notes, created_by, updated_by)
    VALUES (v_job.organization_id, v_job.id, p_party_role, nullif(trim(coalesce(p_display_name, '')), ''), nullif(trim(coalesce(p_phone, '')), ''), nullif(trim(coalesce(p_email, '')), ''), nullif(trim(coalesce(p_notes, '')), ''), v_user, v_user)
    ON CONFLICT (dispatch_job_id, party_role) DO UPDATE
      SET display_name = COALESCE(EXCLUDED.display_name, dispatch_job_protected_parties.display_name),
          phone = COALESCE(EXCLUDED.phone, dispatch_job_protected_parties.phone),
          email = COALESCE(EXCLUDED.email, dispatch_job_protected_parties.email),
          notes = COALESCE(EXCLUDED.notes, dispatch_job_protected_parties.notes),
          updated_by = v_user, updated_at = now();
  END IF;

  -- Audit carries the fact of the record, never the identity values.
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_job.organization_id, v_user, 'dispatch_job_harmed_party_set', 'dispatch_jobs', v_job.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'party_role', p_party_role,
      'harmed_party_site_id', v_site_id, 'identity_recorded', v_has_identity, 'place_created', v_place_created, 'house_action', v_house_action));

  RETURN QUERY SELECT v_job.id, COALESCE(v_site_id, v_job.harmed_party_site_id), v_has_identity, v_place_created, v_house_action;
END;
$function$;
COMMENT ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) IS 'Dispatcher records the harmed-party place on the job (known site of the client/custodian, or an address resolved to coordinates which becomes a provisional site through resolve_or_create_dispatch_place_site) and the protected identity behind dispatch_job_protected_parties. Audited without identity values.';
REVOKE ALL ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_dispatch_job_harmed_party"(p_client_request_id uuid, p_dispatch_job_id uuid, p_harmed_party_site_id uuid, p_harmed_party_address text, p_party_role text, p_display_name text, p_phone text, p_email text, p_notes text, p_harmed_party_lat double precision, p_harmed_party_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean)
 RETURNS organization_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_module public.organization_modules%rowtype;
begin
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.is_admin_for_org(p_operating_organization_id) then raise exception 'Active authorized operating branch administrator required';end if;
  if not exists(select 1 from public.organizations branch where branch.id=p_operating_organization_id and branch.organization_type in ('owner','service_provider','branch') and branch.active) then raise exception 'Active operating organisation not found';end if;
  if not exists(select 1 from public.module_catalog module where module.module_key=p_module_key and module.active) then raise exception 'Active platform module required';end if;
  if p_enabled and exists(select 1 from public.organizations b where b.id=p_operating_organization_id and b.parent_organization_id is not null and not exists(select 1 from public.organization_modules pm where pm.organization_id=b.parent_organization_id and pm.module_key=p_module_key and pm.enabled)) then raise exception 'Enable this module for the organisation before enabling it for a branch';end if;
  insert into public.organization_modules(organization_id,module_key,enabled)values(p_operating_organization_id,p_module_key,p_enabled) on conflict(organization_id,module_key) do update set enabled=excluded.enabled returning * into v_module;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(p_operating_organization_id,v_actor,'operating_branch_module_set','organization_modules',v_module.id,jsonb_build_object('module_key',v_module.module_key,'enabled',v_module.enabled));return v_module;
end;$function$;
REVOKE ALL ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_operating_branch_module"(p_operating_organization_id uuid, p_module_key text, p_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_geom         geometry;
  v_area_m2      numeric;
  v_prev_geom    geometry;
  v_prev_verif   text;
  v_prev_vby     uuid;
  v_prev_vat     timestamptz;
  v_source       text;
  v_via          text;
BEGIN
  IF p_polygons IS NULL OR jsonb_typeof(p_polygons) <> 'array' OR jsonb_array_length(p_polygons) = 0 THEN
    RAISE EXCEPTION 'p_polygons must be a non-empty JSON array of GeoJSON geometries';
  END IF;

  SELECT st_multi(st_setsrid(st_makevalid(st_union(st_makevalid(st_geomfromgeojson(elem.value)))), 4326))
    INTO v_geom
    FROM jsonb_array_elements(p_polygons) AS elem;

  IF v_geom IS NULL THEN
    RAISE EXCEPTION 'Could not build geometry from supplied GeoJSON';
  END IF;

  IF st_isempty(v_geom) THEN
    RAISE EXCEPTION 'Geometry is empty after ST_MakeValid + ST_Union';
  END IF;

  IF NOT st_isvalid(v_geom) THEN
    RAISE EXCEPTION 'Geometry is still invalid after ST_MakeValid: %', st_isvalidreason(v_geom);
  END IF;

  v_area_m2 := st_area(v_geom::geography);

  -- Capture previous state for history BEFORE overwriting
  SELECT jurisdiction_geom, jurisdiction_verification,
         jurisdiction_verified_by, jurisdiction_verified_at
    INTO v_prev_geom, v_prev_verif, v_prev_vby, v_prev_vat
    FROM public.organizations
   WHERE id = p_org_id;

  -- Write the new geometry
  UPDATE public.organizations
     SET jurisdiction_geom = v_geom
   WHERE id = p_org_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization % not found', p_org_id;
  END IF;

  -- Resolve provenance: use caller-supplied source when provided,
  -- else fall back to 'UNKNOWN_SOURCE' (P1: loud, explicit).
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history: snapshot of the NEW geometry with current state
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'organization', p_org_id, v_geom, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Jurisdiction geometry set via set_org_jurisdiction_geom',
    public._gbh_next_version('organization', p_org_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes organizations.jurisdiction_geom by ST_Union-ing an array of GeoJSON polygons into one MultiPolygon(4326) with ST_MakeValid. Returns the written area in m^2. Records a history row in geofence_boundary_history with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_org_jurisdiction_geom"(p_org_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text)
 RETURNS organization_calendar_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_row public.organization_calendar_settings%rowtype;v_region text:=nullif(upper(trim(coalesce(p_region_code,''))), '');
begin
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Not authorised to configure this organization calendar';end if;
  if v_region is not null and v_region not in('AUK','BOP','CAN','CIT','GIS','HKB','MBH','MWT','NSN','NTL','OTA','STL','TAS','TKI','WKO','WGN','WTC') then raise exception 'Unsupported New Zealand holiday region';end if;
  insert into public.organization_calendar_settings(organization_id,region_code,updated_by) values(p_organization_id,v_region,v_actor)
  on conflict(organization_id) do update set region_code=excluded.region_code,updated_by=v_actor,updated_at=clock_timestamp()
  returning * into v_row;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(p_organization_id,v_actor,'organization_calendar_region_set','organization_calendar_settings',p_organization_id,jsonb_build_object('country_code','NZ','region_code',v_region));
  return v_row;
end;$function$;
REVOKE ALL ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_organization_calendar_region"(p_organization_id uuid, p_region_code text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean)
 RETURNS organization_modules
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_module public.organization_modules%rowtype;
BEGIN
  IF v_actor IS NULL OR NOT public.is_admin_for_org(p_organization_id) THEN
    RAISE EXCEPTION 'Active organisation administrator required';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.module_catalog module WHERE module.module_key = p_module_key AND module.active) THEN
    RAISE EXCEPTION 'Active platform module required';
  END IF;

  INSERT INTO public.organization_modules (organization_id, module_key, enabled)
  VALUES (p_organization_id, p_module_key, p_enabled)
  ON CONFLICT (organization_id, module_key) DO UPDATE SET enabled = excluded.enabled
  RETURNING * INTO v_module;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (p_organization_id, v_actor, 'organization_module_subscription_set', 'organization_modules', v_module.id, jsonb_build_object('module_key', v_module.module_key, 'enabled', v_module.enabled));

  RETURN v_module;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_organization_module_subscription"(p_organization_id uuid, p_module_key text, p_enabled boolean) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb DEFAULT NULL::jsonb, p_center_lat double precision DEFAULT NULL::double precision, p_center_lng double precision DEFAULT NULL::double precision, p_provisional_radius_m double precision DEFAULT 50, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_boundary   geometry;
  v_center     geometry;
  v_area_m2    numeric;
  v_source     text;
  v_via        text;
BEGIN
  IF p_boundary IS NOT NULL THEN
    v_boundary := st_makevalid(st_setsrid(st_geomfromgeojson(p_boundary::text), 4326));
    IF v_boundary IS NULL THEN
      RAISE EXCEPTION 'set_site_geometry: could not build geometry from p_boundary GeoJSON';
    END IF;
    IF geometrytype(v_boundary) <> 'POLYGON' THEN
      v_boundary := st_convexhull(v_boundary);
    END IF;
    -- Polygon path: use caller-supplied source, else 'UNKNOWN_SOURCE' (P1).
    v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');
  ELSIF p_center_lat IS NOT NULL AND p_center_lng IS NOT NULL THEN
    v_boundary := st_setsrid(
      st_buffer(
        st_setsrid(st_makepoint(p_center_lng, p_center_lat), 4326)::geography,
        greatest(coalesce(p_provisional_radius_m, 50), 1)
      )::geometry,
      4326
    );
    IF geometrytype(v_boundary) <> 'POLYGON' THEN
      v_boundary := st_convexhull(v_boundary);
    END IF;
    -- Point-radius path: source is always 'point_radius' regardless of caller.
    v_source := 'point_radius';
  ELSE
    RAISE EXCEPTION 'set_site_geometry: supply either p_boundary (GeoJSON polygon) or p_center_lat + p_center_lng (provisional point)';
  END IF;

  v_center  := st_centroid(v_boundary);
  v_area_m2 := st_area(v_boundary::geography);

  UPDATE public.client_sites
     SET boundary     = v_boundary,
         center_point = v_center
   WHERE id = p_site_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_site_geometry: site % not found', p_site_id;
  END IF;

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'client_site', p_site_id, v_boundary, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Site geometry set via set_site_geometry',
    public._gbh_next_version('client_site', p_site_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_site_geometry"(p_site_id uuid, p_boundary jsonb, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes client_sites.boundary (GeoJSON polygon with ST_MakeValid, or a buffered provisional point) and center_point = ST_Centroid(boundary). Returns area in m^2. Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
