CREATE OR REPLACE FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_geom    geometry;
  v_center  geometry;
  v_area_m2 numeric;
  v_source  text;
  v_via     text;
BEGIN
  IF p_polygons IS NULL OR jsonb_array_length(p_polygons) = 0 THEN
    RAISE EXCEPTION 'set_zone_geometry: p_polygons must be a non-empty JSON array';
  END IF;

  SELECT st_union(array_agg(st_makevalid(st_setsrid(st_geomfromgeojson(elem::text), 4326))))
    INTO v_geom
    FROM jsonb_array_elements(p_polygons) AS elem;

  IF v_geom IS NULL OR st_isempty(v_geom) THEN
    RAISE EXCEPTION 'set_zone_geometry: could not build geometry from supplied polygons';
  END IF;

  v_geom := st_multi(st_makevalid(v_geom));

  IF NOT st_isvalid(v_geom) THEN
    RAISE EXCEPTION 'set_zone_geometry: geometry still invalid after ST_MakeValid: %', st_isvalidreason(v_geom);
  END IF;

  v_center  := st_centroid(v_geom);
  v_area_m2 := st_area(v_geom::geography);

  UPDATE location_zones
     SET boundary     = v_geom,
         center_point = v_center
   WHERE id = p_zone_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_zone_geometry: zone % not found', p_zone_id;
  END IF;

  -- Resolve provenance: use caller-supplied source, else 'UNKNOWN_SOURCE' (P1).
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'UNKNOWN_SOURCE');

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'location_zone', p_zone_id, v_geom, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Zone geometry set via set_zone_geometry (polygon)',
    public._gbh_next_version('location_zone', p_zone_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes a zone boundary from a GeoJSON polygon array (union, ST_MakeValid, MultiPolygon) and returns its real area (m^2). Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_polygons jsonb, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision DEFAULT 100, p_boundary_source text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid, p_changed_via text DEFAULT 'governed_proposal'::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_point   geometry;
  v_buffer  geometry;
  v_area_m2 numeric;
  v_source  text;
  v_via     text;
BEGIN
  IF p_center_lat IS NULL OR p_center_lng IS NULL THEN
    RAISE EXCEPTION 'set_zone_geometry: p_center_lat and p_center_lng are required for provisional fence';
  END IF;

  v_point  := st_setsrid(st_point(p_center_lng, p_center_lat), 4326);
  v_buffer := st_transform(
                st_buffer(
                  st_transform(v_point, 2193),
                  coalesce(p_provisional_radius_m, 100)
                ),
                4326
              );

  v_buffer  := st_multi(v_buffer);
  v_area_m2 := st_area(v_buffer::geography);

  UPDATE location_zones
     SET boundary     = v_buffer,
         center_point = v_point
   WHERE id = p_zone_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'set_zone_geometry: zone % not found', p_zone_id;
  END IF;

  -- Point-radius path: source is always 'point_radius' regardless of caller,
  -- unless the caller explicitly overrides (unlikely but supported).
  v_source := COALESCE(NULLIF(TRIM(p_boundary_source), ''), 'point_radius');

  -- Resolve changed_via: validate against the CHECK constraint values.
  v_via := CASE
    WHEN p_changed_via IN ('governed_proposal', 'direct_edit', 'reconciliation', 'refresh', 'verification', 'backfill')
    THEN p_changed_via
    ELSE 'governed_proposal'
  END;

  -- Record history
  INSERT INTO public.geofence_boundary_history (
    entity_type, entity_id, boundary, boundary_source,
    verification_state, verified_by, verified_at,
    changed_by, changed_via, change_reason, version
  ) VALUES (
    'location_zone', p_zone_id, v_buffer, v_source,
    'unverified', NULL, NULL,
    p_changed_by, v_via, 'Zone geometry set via set_zone_geometry (provisional point)',
    public._gbh_next_version('location_zone', p_zone_id)
  );

  RETURN v_area_m2;
END;
$function$;
COMMENT ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) IS 'Writes a provisional circular boundary from a GPS point + radius (NZTM2000 metric buffer, wrapped as MultiPolygon) and returns its area (m^2). Records a history row with real provenance. Phase 1+4 geofence redesign (#226).';
REVOKE ALL ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."set_zone_geometry"(p_zone_id uuid, p_center_lat double precision, p_center_lng double precision, p_provisional_radius_m double precision, p_boundary_source text, p_changed_by uuid, p_changed_via text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.user_profiles actor
    join public.user_profiles target on target.id = p_target_user_id
    where actor.id = p_actor_id
      and actor.deactivated_at is null
      and target.employer_organization_id is not null
      and (
        actor.role = 'grand_master'
        or (
          target.employer_organization_id = coalesce(actor.employer_organization_id, actor.organization_id)
          and p_branch_organization_id = any(public.get_descendant_organizations(coalesce(actor.employer_organization_id, actor.organization_id)))
          and (actor.role in ('master', 'admin') or p_branch_organization_id = any(public.user_managed_branch_ids()))
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_branch_authorisation_manager_can_manage"(p_actor_id uuid, p_branch_organization_id uuid, p_target_user_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid;
  v_rules public.organization_fatigue_rules%rowtype;
  v_gap_hours numeric;
  v_week_hours numeric;
  v_consecutive integer;
begin
  select sp.organization_id into v_org from public.staff_profiles sp where sp.id = p_staff_id;
  if v_org is null then
    return null;
  end if;

  select r.* into v_rules from public.organization_fatigue_rules r where r.organization_id = v_org;
  if not found or not v_rules.enforced then
    return null;
  end if;

  select min(
    case
      when s.scheduled_start >= p_scheduled_end
        then extract(epoch from (s.scheduled_start - p_scheduled_end)) / 3600.0
      else extract(epoch from (p_scheduled_start - s.scheduled_end)) / 3600.0
    end
  ) into v_gap_hours
  from public.roster_slots s
  where s.staff_id = p_staff_id
    and s.status not in ('declined', 'cancelled')
    and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
    and not tstzrange(s.scheduled_start, s.scheduled_end, '[)') && tstzrange(p_scheduled_start, p_scheduled_end, '[)');

  if v_gap_hours is not null and v_gap_hours < v_rules.min_rest_hours_between_shifts then
    return format('Minimum rest of %s hours not met (%s hours between shifts)',
      v_rules.min_rest_hours_between_shifts, round(v_gap_hours, 1));
  end if;

  select coalesce(sum(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600.0), 0)
  into v_week_hours
  from public.roster_slots s
  where s.staff_id = p_staff_id
    and s.status not in ('declined', 'cancelled')
    and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
    and s.scheduled_start >= p_scheduled_start - interval '7 days'
    and s.scheduled_start < p_scheduled_start + interval '7 days';

  v_week_hours := v_week_hours + extract(epoch from (p_scheduled_end - p_scheduled_start)) / 3600.0;

  if v_week_hours > v_rules.max_hours_per_week then
    return format('Weekly hours limit exceeded (%s of %s hours)',
      round(v_week_hours, 1), v_rules.max_hours_per_week);
  end if;

  select count(distinct (s.scheduled_start at time zone 'Pacific/Auckland')::date)
  into v_consecutive
  from public.roster_slots s
  where s.staff_id = p_staff_id
    and s.status not in ('declined', 'cancelled')
    and (p_exclude_slot_id is null or s.id <> p_exclude_slot_id)
    and s.scheduled_start >= p_scheduled_start - (v_rules.max_consecutive_days || ' days')::interval
    and s.scheduled_start <= p_scheduled_start;

  if v_consecutive >= v_rules.max_consecutive_days then
    return format('Maximum of %s consecutive working days reached', v_rules.max_consecutive_days);
  end if;

  return null;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."staff_fatigue_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_exclude_slot_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1
    from public.staff_availability a
    cross join lateral generate_series(
      (p_scheduled_start at time zone 'Pacific/Auckland')::date,
      ((p_scheduled_end-interval '1 microsecond') at time zone 'Pacific/Auckland')::date,
      interval '1 day'
    ) as roster_day
    where a.staff_id=p_staff_id
      and a.availability_type in('unavailable','leave')
      and (a.specific_date=roster_day::date or (a.specific_date is null and a.day_of_week=extract(isodow from roster_day)::integer))
      and (
        a.all_day
        or a.available_from is null
        or a.available_to is null
        or tstzrange(p_scheduled_start,p_scheduled_end,'[)') && tstzrange(
          (roster_day::date+a.available_from) at time zone 'Pacific/Auckland',
          ((roster_day::date+case when a.available_to>a.available_from then 0 else 1 end)+a.available_to) at time zone 'Pacific/Auckland',
          '[)'
        )
      )
  );
$function$;
REVOKE ALL ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."staff_has_roster_availability_conflict"(p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid DEFAULT NULL::uuid, p_zone_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_profile public.user_profiles%rowtype; v_unit public.roster_work_units%rowtype; v_shift public.shifts%rowtype;
BEGIN
  SELECT * INTO v_profile FROM public.user_profiles WHERE id=v_actor AND deactivated_at IS NULL AND role IN ('officer','admin_officer');
  IF NOT FOUND THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  SELECT * INTO v_unit FROM public.roster_work_units WHERE id=p_work_unit_id AND organization_id=v_profile.organization_id AND active FOR SHARE;
  IF NOT FOUND OR v_unit.service_type IS DISTINCT FROM p_module_key THEN RAISE EXCEPTION 'Authorized active work unit/module required'; END IF;
  IF EXISTS (SELECT 1 FROM public.shifts WHERE officer_user_id=v_actor AND status='in_progress') THEN RAISE EXCEPTION 'Officer already has an active shift'; END IF;
  INSERT INTO public.shifts (organization_id,officer_user_id,service_type,location_id,zone_id,scheduled_start,scheduled_end,actual_start,status,notes,work_unit_id,module_key,shift_origin)
  VALUES(v_profile.organization_id,v_actor,p_module_key,p_location_id,p_zone_id,clock_timestamp(),clock_timestamp()+interval '12 hours',clock_timestamp(),'in_progress',nullif(trim(p_notes),''),p_work_unit_id,p_module_key,'ad_hoc')
  RETURNING * INTO v_shift;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_profile.organization_id,v_actor,'officer_ad_hoc_shift_started','shifts',v_shift.id,jsonb_build_object('work_unit_id',p_work_unit_id,'module_key',p_module_key));
  RETURN v_shift;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_ad_hoc_officer_shift"(p_work_unit_id uuid, p_module_key text, p_location_id uuid, p_zone_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text)
 RETURNS finance_external_connection_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_request public.finance_external_connection_requests%rowtype;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'OAuth adapter execution only'; END IF;
  IF nullif(trim(p_state_hash), '') IS NULL OR p_state_expires_at <= now() OR nullif(trim(p_adapter_name), '') IS NULL THEN RAISE EXCEPTION 'Invalid OAuth start parameters'; END IF;
  SELECT * INTO v_request FROM public.finance_external_connection_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finance connection request not found'; END IF;
  IF v_request.status NOT IN ('awaiting_authorisation','requested','connected','failed') THEN RAISE EXCEPTION 'Connection request is not available for OAuth'; END IF;
  UPDATE public.finance_external_connection_requests SET status = 'awaiting_authorisation', adapter_name = p_adapter_name, oauth_state_hash = p_state_hash, oauth_state_expires_at = p_state_expires_at, oauth_started_at = now(), last_error = NULL, updated_at = now() WHERE id = p_request_id RETURNING * INTO v_request;
  INSERT INTO public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata) VALUES (v_request.organization_id, NULL, 'finance_external_oauth_started', 'finance_external_connection_requests', v_request.id, jsonb_build_object('provider_type', v_request.provider_type, 'adapter_name', p_adapter_name, 'reauthorisation', true));
  RETURN v_request;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_finance_external_oauth"(p_request_id uuid, p_state_hash text, p_state_expires_at timestamp with time zone, p_adapter_name text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(shift_id uuid, shift_status text, started_at timestamp with time zone, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_at timestamptz := now();
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then
    raise exception 'Shift not found';
  end if;

  if v_shift.officer_user_id <> v_actor and not public.is_admin_for_org(v_shift.organization_id) then
    raise exception 'Only the assigned officer or an administrator can start this shift';
  end if;

  if v_shift.status = 'in_progress' and v_shift.actual_start is not null then
    return query select v_shift.id, v_shift.status, v_shift.actual_start, false;
    return;
  end if;

  if v_shift.status <> p_expected_status then
    raise exception 'Shift changed from expected status % to %', p_expected_status, v_shift.status;
  end if;

  if v_shift.status not in ('scheduled', 'published', 'accepted') then
    raise exception 'Shift cannot be started from status %', v_shift.status;
  end if;

  update public.shifts
  set status = 'in_progress', actual_start = coalesce(actual_start, v_at), updated_at = v_at
  where id = v_shift.id
  returning * into v_shift;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'officer_shift_started', 'shifts', v_shift.id,
    jsonb_build_object(
      'previous_status', p_expected_status,
      'actual_start', v_shift.actual_start,
      'gps_lat', p_gps_lat,
      'gps_lng', p_gps_lng,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_shift.id, v_shift.status, v_shift.actual_start, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_officer_shift"(p_client_request_id uuid, p_shift_id uuid, p_expected_status text, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_patrol_session"(p_shift_id uuid)
 RETURNS patrols
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_shift public.shifts%rowtype;v_patrol public.patrols%rowtype;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('grand_master','master','admin','admin_officer','officer') then raise exception 'Active Patrol officer required';end if;
  select * into v_shift from public.shifts where id=p_shift_id for update;
  if not found or v_shift.organization_id is distinct from v_profile.organization_id or v_shift.officer_user_id is distinct from v_actor then raise exception 'Assigned Patrol shift not found';end if;
  if v_shift.status not in('published','accepted','in_progress') then raise exception 'Patrol shift is not active';end if;
  select * into v_patrol from public.patrols where shift_id=v_shift.id and officer_user_id=v_actor and status='in_progress' order by started_at desc limit 1;
  if found then return v_patrol;end if;
  insert into public.patrols(organization_id,shift_id,officer_user_id,zone_id,status,started_at) values(v_shift.organization_id,v_shift.id,v_actor,v_shift.zone_id,'in_progress',clock_timestamp()) returning * into v_patrol;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_patrol.organization_id,v_actor,'patrol.started','patrols',v_patrol.id,jsonb_build_object('shift_id',v_shift.id,'patrol_route_id',v_shift.patrol_route_id));
  return v_patrol;
end;$function$;
REVOKE ALL ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_patrol_session"(p_shift_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text)
 RETURNS shift_breaks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_break public.shift_breaks%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  if p_break_type not in ('rest', 'meal') then
    raise exception 'Break type must be rest or meal';
  end if;

  select s.* into v_shift from public.shifts s where s.id = p_shift_id for update;
  if not found then
    raise exception 'Shift not found';
  end if;

  if v_shift.officer_user_id <> v_actor then
    raise exception 'Only the assigned officer can record a break';
  end if;

  select b.* into v_break from public.shift_breaks b
  where b.organization_id = v_shift.organization_id and b.client_request_id = p_client_request_id;
  if found then
    return v_break;
  end if;

  if v_shift.status <> 'in_progress' then
    raise exception 'Breaks can only be recorded while the shift is in progress';
  end if;

  if exists (select 1 from public.shift_breaks b where b.shift_id = v_shift.id and b.ended_at is null) then
    raise exception 'An open break is already in progress for this shift';
  end if;

  insert into public.shift_breaks(
    organization_id, shift_id, officer_user_id, break_type, started_at, is_paid, client_request_id
  )
  values (
    v_shift.organization_id, v_shift.id, v_actor, p_break_type, now(), p_break_type = 'rest', p_client_request_id
  )
  returning * into v_break;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_shift.organization_id, v_actor, 'shift_break_started', 'shift_breaks', v_break.id,
    jsonb_build_object('shift_id', v_shift.id, 'break_type', p_break_type, 'is_paid', v_break.is_paid)
  );

  return v_break;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_shift_break"(p_client_request_id uuid, p_shift_id uuid, p_break_type text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_target_start date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS staff_onboarding_ledgers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_ledger public.staff_onboarding_ledgers%rowtype;
  v_note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;
  select sp.* into v_staff from public.staff_profiles sp where sp.id = p_staff_id for update;
  if not found then raise exception 'Staff profile not found'; end if;
  if not public.is_admin_for_org(v_staff.organization_id) then raise exception 'Active HR administrator required'; end if;
  if p_assigned_to is not null and not exists (
    select 1 from public.user_profiles u where u.id = p_assigned_to and u.organization_id = v_staff.organization_id and u.deactivated_at is null
  ) then raise exception 'Onboarding owner must be an active member of this organization'; end if;
  select l.* into v_ledger from public.staff_onboarding_ledgers l where l.staff_id = v_staff.id;
  if found then return v_ledger; end if;
  insert into public.staff_onboarding_ledgers(organization_id, staff_id, assigned_to, target_start, stage_note)
  values (v_staff.organization_id, v_staff.id, p_assigned_to, p_target_start, coalesce(v_note, 'Staff onboarding started'))
  returning * into v_ledger;
  insert into public.staff_onboarding_events(ledger_id, organization_id, to_stage, to_status, note, actor_user_id, version)
  values (v_ledger.id, v_ledger.organization_id, v_ledger.current_stage, v_ledger.status, coalesce(v_note, 'Staff onboarding started'), v_actor, v_ledger.version);
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_ledger.organization_id, v_actor, 'staff_onboarding_started', 'staff_onboarding_ledgers', v_ledger.id,
    jsonb_build_object('staff_id', v_staff.id, 'assigned_to', p_assigned_to, 'target_start', p_target_start, 'client_request_id', p_client_request_id));
  return v_ledger;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."start_staff_onboarding"(p_client_request_id uuid, p_staff_id uuid, p_assigned_to uuid, p_target_start date, p_note text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."stop_officer_shift"(p_shift_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_shift public.shifts%rowtype;
BEGIN
  SELECT * INTO v_shift FROM public.shifts WHERE id=p_shift_id AND officer_user_id=v_actor FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'in_progress' THEN RAISE EXCEPTION 'Active officer shift not found'; END IF;
  UPDATE public.shifts SET actual_end=clock_timestamp(), scheduled_end=clock_timestamp(), status='completed', notes=coalesce(nullif(trim(p_notes),''),notes), updated_at=clock_timestamp() WHERE public.shifts.id=p_shift_id RETURNING * INTO v_shift;
  INSERT INTO public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)
    VALUES(v_shift.organization_id,v_actor,'officer_shift_stopped','shifts',v_shift.id,jsonb_build_object('work_unit_id',v_shift.work_unit_id,'module_key',v_shift.module_key,'actual_start',v_shift.actual_start,'actual_end',v_shift.actual_end));
  RETURN v_shift;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."stop_officer_shift"(p_shift_id uuid, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."stop_officer_shift"(p_shift_id uuid, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."stop_officer_shift"(p_shift_id uuid, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."stop_officer_shift"(p_shift_id uuid, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text DEFAULT NULL::text, p_density_estimate text DEFAULT 'scattered'::text, p_action_taken text DEFAULT 'no_action'::text, p_scene_description text DEFAULT NULL::text, p_location_name text DEFAULT NULL::text, p_protected_land_address text DEFAULT NULL::text, p_protected_land_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_mpi_referral_number text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, review_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.biosecurity_assessments%rowtype;
  v_assessment public.biosecurity_assessments%rowtype;
  v_review_state text;
  v_evidence_state text := 'verified';
  v_item jsonb;
  v_evidence_id uuid;
  v_photo_arr jsonb := '[]'::jsonb;
  v_ordinal integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null and p.role in ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  if v_org_id is null then raise exception 'Active officer profile required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  if p_assessed_at is null or p_assessed_at > now() + interval '5 minutes' or p_assessed_at < now() - interval '24 hours' then
    raise exception 'assessed_at is outside the accepted capture window';
  end if;

  if nullif(trim(coalesce(p_location_name, '')), '') is null then
    raise exception 'Observed location name is required';
  end if;

  if p_density_estimate <> 'not_found' and nullif(trim(coalesce(p_species_name, '')), '') is null then
    raise exception 'Species name is required when pest/species is present';
  end if;

  if p_action_taken in ('notice_of_direction', 'infringement_notice') and nullif(trim(coalesce(p_notice_number, '')), '') is null then
    raise exception 'Notice number is required for direction or infringement actions';
  end if;

  if p_action_taken = 'mpi_referral' and nullif(trim(coalesce(p_mpi_referral_number, '')), '') is null then
    raise exception 'MPI referral number is required for MPI referrals';
  end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  if p_dispatch_job_id is not null and not exists (select 1 from public.dispatch_jobs d where d.id = p_dispatch_job_id and d.organization_id = v_org_id) then
    raise exception 'Dispatch job does not belong to the officer organisation';
  end if;

  -- Idempotency check
  select b.* into v_existing from public.biosecurity_assessments b
    where b.organization_id = v_org_id and b.officer_user_id = v_user_id and b.client_request_id = p_client_request_id;
  if found then
    return query select v_existing.id, false, v_existing.created_at, v_existing.evidence_state, v_existing.review_state;
    return;
  end if;

  -- Derive initial review state
  if p_classification is null or coalesce(p_classification->>'classification', '') = '' or coalesce(p_classification->>'status', '') = 'unavailable' then
    v_review_state := 'requires_supervisor_review';
  else
    v_review_state := 'submitted';
  end if;

  insert into public.biosecurity_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    species_name, species_identified, density_estimate, action_taken, scene_description,
    location_name, protected_land_address, protected_land_site_id, notice_number, mpi_referral_number,
    follow_up_required, shift_id, dispatch_job_id, status, evidence_state, review_state,
    bob_classification, bob_confidence
  ) values (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    nullif(trim(coalesce(p_species_name, '')), ''), nullif(trim(coalesce(p_species_name, '')), ''), p_density_estimate, p_action_taken, nullif(trim(coalesce(p_scene_description, '')), ''),
    trim(p_location_name), nullif(trim(coalesce(p_protected_land_address, '')), ''), p_protected_land_site_id, nullif(trim(coalesce(p_notice_number, '')), ''), nullif(trim(coalesce(p_mpi_referral_number, '')), ''),
    coalesce(p_follow_up_required, false), p_shift_id, p_dispatch_job_id, 'open', v_evidence_state, v_review_state,
    nullif(trim(coalesce(p_classification->>'classification', '')), ''), (p_classification->>'confidence')::real
  ) returning * into v_assessment;

  -- Process evidence items
  if jsonb_array_length(p_evidence_items) > 0 then
    for v_item in select * from jsonb_array_elements(p_evidence_items) loop
      v_evidence_id := gen_random_uuid();
      insert into public.evidence_items (
        id, organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, metadata
      ) values (
        v_evidence_id, v_org_id, 'biosecurity', coalesce(v_item->>'evidence_kind', 'photo'), v_item->>'watermarked_path', v_user_id, p_assessed_at, coalesce(v_item, '{}'::jsonb)
      );

      insert into public.biosecurity_assessment_evidence (
        organization_id, biosecurity_assessment_id, evidence_item_id, ordinal, purpose
      ) values (
        v_org_id, v_assessment.id, v_evidence_id, v_ordinal, coalesce(v_item->>'purpose', 'primary_evidence')
      );

      v_photo_arr := v_photo_arr || jsonb_build_array(jsonb_build_object(
        'id', v_evidence_id,
        'storage_path', v_item->>'watermarked_path',
        'original_path', v_item->>'original_path',
        'captured_at', p_assessed_at
      ));
      v_ordinal := v_ordinal + 1;
    end loop;

    update public.biosecurity_assessments
      set photo_urls = v_photo_arr,
          photo_url = coalesce(v_item->>'watermarked_path', photo_url)
      where biosecurity_assessments.id = v_assessment.id;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'biosecurity_assessment_submitted', 'biosecurity_assessments', v_assessment.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'species_name', v_assessment.species_name,
      'density_estimate', v_assessment.density_estimate,
      'action_taken', v_assessment.action_taken,
      'review_state', v_review_state,
      'evidence_count', v_ordinal
    )
  );

  return query select v_assessment.id, true, v_assessment.created_at, v_assessment.evidence_state, v_assessment.review_state;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text, p_density_estimate text, p_action_taken text, p_scene_description text, p_location_name text, p_protected_land_address text, p_protected_land_site_id uuid, p_notice_number text, p_mpi_referral_number text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_biosecurity_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_species_name text, p_density_estimate text, p_action_taken text, p_scene_description text, p_location_name text, p_protected_land_address text, p_protected_land_site_id uuid, p_notice_number text, p_mpi_referral_number text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
