CREATE OR REPLACE FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text DEFAULT 'no_action'::text, p_volume_score smallint DEFAULT 0, p_time_score smallint DEFAULT 1, p_tone_score smallint DEFAULT 0, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_end_number text DEFAULT NULL::text, p_occupant_name text DEFAULT NULL::text, p_occupant_dob date DEFAULT NULL::date, p_is_large_event_or_commercial boolean DEFAULT false, p_police_requested boolean DEFAULT false, p_police_present boolean DEFAULT false, p_scene_description text DEFAULT NULL::text, p_incident_report_text text DEFAULT NULL::text, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_gps_lat double precision DEFAULT NULL::double precision, p_gps_lng double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, review_status text, matrix_total smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.noise_assessments%rowtype;
  v_assessment public.noise_assessments%rowtype;
  v_job public.dispatch_jobs%rowtype;
  v_matrix_total smallint;
  v_threshold smallint := 5;
  v_end_validity_hours smallint := 192;
  v_excessive boolean;
  v_site_id uuid;
  v_complainant_site_id uuid := p_complainant_site_id;
  v_complaint_address text := nullif(trim(coalesce(p_complaint_address, '')), '');
  v_source_stop_id uuid;
  v_complainant_stop_id uuid;
  v_point geometry;
  v_dist_complainant numeric;
  v_dist_source numeric;
  v_end_expires_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT p.organization_id INTO v_org_id FROM public.user_profiles p
  WHERE p.id = v_user_id AND p.deactivated_at IS NULL
    AND p.role IN ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'Active officer profile required'; END IF;
  IF p_client_request_id IS NULL THEN RAISE EXCEPTION 'client_request_id is required'; END IF;
  IF p_assessed_at IS NULL OR p_assessed_at > now() + interval '5 minutes' OR p_assessed_at < now() - interval '24 hours' THEN RAISE EXCEPTION 'assessed_at is outside the accepted capture window'; END IF;
  IF nullif(trim(coalesce(p_noise_source_address, '')), '') IS NULL THEN RAISE EXCEPTION 'Noise source address is required'; END IF;
  IF nullif(trim(coalesce(p_noise_source, '')), '') IS NULL THEN RAISE EXCEPTION 'Noise source type is required'; END IF;
  IF p_volume_score NOT BETWEEN 0 AND 4 THEN RAISE EXCEPTION 'Volume score must be between 0 and 4'; END IF;
  IF p_time_score NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Time score must be between 1 and 4'; END IF;
  IF p_tone_score NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'Tone score must be between 0 and 2'; END IF;

  v_matrix_total := coalesce(p_volume_score, 0) + coalesce(p_time_score, 1) + coalesce(p_tone_score, 0);
  SELECT n.excessive_threshold, n.end_validity_hours INTO v_threshold, v_end_validity_hours
  FROM public.noise_module_config n
  WHERE n.organization_id = v_org_id AND n.is_current
    AND n.effective_from <= current_date
    AND (n.effective_to IS NULL OR n.effective_to >= current_date)
  ORDER BY n.effective_from DESC, n.version DESC
  LIMIT 1;
  IF v_threshold IS NULL THEN v_threshold := 5; END IF;
  IF v_end_validity_hours IS NULL THEN v_end_validity_hours := 192; END IF;
  v_excessive := (v_matrix_total >= v_threshold);

  IF p_action_taken IN ('abatement_notice', 'direction_notice', 'enforcement_notice', 'equipment_seized')
    AND nullif(trim(coalesce(p_notice_number, coalesce(p_end_number, ''))), '') IS NULL THEN
    RAISE EXCEPTION 'Notice or END number is required for statutory noise enforcement actions';
  END IF;
  -- RMA s327(1)(a): an excessive noise direction follows a received complaint.
  IF p_action_taken = 'direction_notice' AND p_dispatch_job_id IS NULL THEN
    RAISE EXCEPTION 'An excessive noise direction requires a linked complaint (dispatch job); use the abatement path for officer-initiated noise';
  END IF;
  -- RMA s328(3) / s323(2): seizure is exercised accompanied by a constable.
  IF p_action_taken = 'equipment_seized' AND NOT coalesce(p_police_present, false) THEN
    RAISE EXCEPTION 'Equipment seizure requires Police present (RMA s328(3))';
  END IF;
  IF p_shift_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.shifts s WHERE s.id = p_shift_id AND s.organization_id = v_org_id) THEN RAISE EXCEPTION 'Shift does not belong to the officer organisation'; END IF;
  IF p_dispatch_job_id IS NOT NULL THEN
    SELECT * INTO v_job FROM public.dispatch_jobs d WHERE d.id = p_dispatch_job_id AND d.organization_id = v_org_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Dispatch job does not belong to the officer organisation'; END IF;
  END IF;

  SELECT n.* INTO v_existing FROM public.noise_assessments n
  WHERE n.organization_id = v_org_id AND n.officer_user_id = v_user_id AND n.client_request_id = p_client_request_id;
  IF FOUND THEN RETURN QUERY SELECT v_existing.id, false, v_existing.created_at, v_existing.review_status, v_existing.matrix_total; RETURN; END IF;

  -- Both places come from the job when the officer did not supply them (rule #157: site_id = source).
  IF v_job.id IS NOT NULL THEN
    v_site_id := v_job.client_site_id;
    v_complainant_site_id := COALESCE(v_complainant_site_id, v_job.harmed_party_site_id);
    v_complaint_address := COALESCE(v_complaint_address, v_job.harmed_party_address);
    SELECT st.id INTO v_source_stop_id FROM public.shift_stops st
    WHERE st.dispatch_job_id = v_job.id AND st.place_role = 'work_place' AND st.actual_arrived_at IS NOT NULL ORDER BY st.visit_number DESC LIMIT 1;
    SELECT st.id INTO v_complainant_stop_id FROM public.shift_stops st
    WHERE st.dispatch_job_id = v_job.id AND st.place_role = 'harmed_party_place' AND st.actual_arrived_at IS NOT NULL ORDER BY st.visit_number DESC LIMIT 1;
  END IF;

  -- Measured position: how close the officer assessed to the complainant, and to the source.
  IF p_gps_lat IS NOT NULL AND p_gps_lng IS NOT NULL THEN
    v_point := ST_SetSRID(ST_MakePoint(p_gps_lng, p_gps_lat), 4326);
    SELECT round(ST_Distance(COALESCE(cs.boundary, cs.center_point)::geography, v_point::geography)::numeric, 1) INTO v_dist_complainant
    FROM public.client_sites cs WHERE cs.id = v_complainant_site_id AND (cs.boundary IS NOT NULL OR cs.center_point IS NOT NULL);
    SELECT round(ST_Distance(COALESCE(cs.boundary, cs.center_point)::geography, v_point::geography)::numeric, 1) INTO v_dist_source
    FROM public.client_sites cs WHERE cs.id = v_site_id AND (cs.boundary IS NOT NULL OR cs.center_point IS NOT NULL);
  END IF;

  IF p_action_taken = 'direction_notice' THEN
    v_end_expires_at := p_assessed_at + make_interval(hours => v_end_validity_hours);
  END IF;

  INSERT INTO public.noise_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    noise_source, noise_source_address, assessment_location, action_taken, action,
    volume_score, time_score, tone_score, matrix_total, complaint_address,
    complainant_site_id, notice_number, end_number, occupant_name, occupant_dob,
    is_large_event_or_commercial, police_requested, police_present, scene_description,
    incident_report_text, follow_up_required, shift_id, dispatch_job_id, status,
    review_status, assessment_gps_lat, assessment_gps_lng,
    site_id, complainant_protected, source_stop_id, complainant_stop_id,
    assessment_distance_to_complainant_m, assessment_distance_to_source_m, end_expires_at
  ) VALUES (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    trim(p_noise_source), trim(p_noise_source_address), trim(p_noise_source_address),
    p_action_taken, p_action_taken, p_volume_score, p_time_score, p_tone_score,
    v_matrix_total, v_complaint_address,
    v_complainant_site_id, nullif(trim(coalesce(p_notice_number, '')), ''),
    nullif(trim(coalesce(p_end_number, '')), ''), nullif(trim(coalesce(p_occupant_name, '')), ''),
    p_occupant_dob, coalesce(p_is_large_event_or_commercial, false),
    coalesce(p_police_requested, false), coalesce(p_police_present, false),
    nullif(trim(coalesce(p_scene_description, '')), ''),
    nullif(trim(coalesce(p_incident_report_text, '')), ''),
    coalesce(p_follow_up_required, false), p_shift_id, p_dispatch_job_id, 'open', 'open',
    p_gps_lat, p_gps_lng,
    v_site_id, true, v_source_stop_id, v_complainant_stop_id,
    v_dist_complainant, v_dist_source, v_end_expires_at
  ) RETURNING * INTO v_assessment;

  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (v_org_id, v_user_id, 'noise_assessment_submitted', 'noise_assessments', v_assessment.id,
    jsonb_build_object('client_request_id', p_client_request_id, 'noise_source', v_assessment.noise_source,
      'matrix_total', v_matrix_total, 'excessive', v_excessive, 'action_taken', v_assessment.action_taken,
      'notice_number', v_assessment.notice_number, 'dispatch_job_id', p_dispatch_job_id,
      'source_stop_id', v_source_stop_id, 'complainant_stop_id', v_complainant_stop_id,
      'assessment_distance_to_complainant_m', v_dist_complainant, 'assessment_distance_to_source_m', v_dist_source,
      'end_expires_at', v_end_expires_at));

  RETURN QUERY SELECT v_assessment.id, true, v_assessment.created_at, v_assessment.review_status, v_assessment.matrix_total;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_noise_assessment"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_noise_source text, p_noise_source_address text, p_action_taken text, p_volume_score smallint, p_time_score smallint, p_tone_score smallint, p_complaint_address text, p_complainant_site_id uuid, p_notice_number text, p_end_number text, p_occupant_name text, p_occupant_dob date, p_is_large_event_or_commercial boolean, p_police_requested boolean, p_police_present boolean, p_scene_description text, p_incident_report_text text, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_gps_lat double precision, p_gps_lng double precision) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_timesheet"(p_client_event_id uuid, p_period_start date, p_period_end date, p_actual_hours numeric, p_overtime_hours numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user_id uuid:=auth.uid(); v_staff public.staff_profiles%rowtype; v_sheet public.timesheets%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select sp.* into v_staff from public.staff_profiles sp join public.user_profiles up on up.id=v_user_id and up.deactivated_at is null
  where (sp.user_id=v_user_id or sp.id=v_user_id) and sp.organization_id=up.organization_id limit 1;
  if not found then raise exception 'Active staff profile required'; end if;
  if p_client_event_id is null then raise exception 'client_event_id is required'; end if;
  if p_period_start is null or p_period_end is null or p_period_start>p_period_end or p_period_end-p_period_start>31 then raise exception 'Timesheet period must be between 1 and 32 days'; end if;
  if p_period_end>current_date then raise exception 'Future timesheet periods cannot be submitted'; end if;
  if p_actual_hours is null or p_actual_hours<0 or p_actual_hours>744 then raise exception 'Actual hours are outside the accepted range'; end if;
  if coalesce(p_overtime_hours,0)<0 or coalesce(p_overtime_hours,0)>p_actual_hours then raise exception 'Overtime hours must be between zero and actual hours'; end if;
  select t.* into v_sheet from public.timesheets t where t.organization_id=v_staff.organization_id and t.staff_id=v_staff.id and t.client_event_id=p_client_event_id;
  if found then return query select v_sheet.id,false,v_sheet.submitted_at; return; end if;
  if exists(select 1 from public.timesheets t where t.staff_id=v_staff.id and daterange(t.period_start,t.period_end,'[]') && daterange(p_period_start,p_period_end,'[]')) then raise exception 'A timesheet already overlaps this period'; end if;
  insert into public.timesheets(organization_id,staff_id,period_start,period_end,actual_hours,overtime_hours,status,notes,submitted_at,client_event_id)
  values(v_staff.organization_id,v_staff.id,p_period_start,p_period_end,p_actual_hours,coalesce(p_overtime_hours,0),'submitted',nullif(trim(coalesce(p_notes,'')),''),clock_timestamp(),p_client_event_id) returning * into v_sheet;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_staff.organization_id,v_user_id,'timesheet_submitted','timesheets',v_sheet.id,jsonb_build_object('staff_id',v_staff.id,'period_start',p_period_start,'period_end',p_period_end,'actual_hours',p_actual_hours,'overtime_hours',coalesce(p_overtime_hours,0)));
  return query select v_sheet.id,true,v_sheet.submitted_at;
end;$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_timesheet"(p_client_event_id uuid, p_period_start date, p_period_end date, p_actual_hours numeric, p_overtime_hours numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet"(p_client_event_id uuid, p_period_start date, p_period_end date, p_actual_hours numeric, p_overtime_hours numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet"(p_client_event_id uuid, p_period_start date, p_period_end date, p_actual_hours numeric, p_overtime_hours numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet"(p_client_event_id uuid, p_period_start date, p_period_end date, p_actual_hours numeric, p_overtime_hours numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, submitted_at timestamp with time zone, work_derived_hours numeric, actual_hours numeric, source_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_staff public.staff_profiles%rowtype;
  v_sheet public.timesheets%rowtype;
  v_work record;
  v_work_json jsonb := '[]'::jsonb;
  v_work_minutes integer := 0;
  v_source_count integer := 0;
  v_adjustment numeric := coalesce(p_adjustment_hours, 0);
  v_actual numeric;
  v_scheduled numeric;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select sp.* into v_staff from public.staff_profiles sp join public.user_profiles up on up.id = v_user_id and up.deactivated_at is null where (sp.user_id = v_user_id or sp.id = v_user_id) and sp.organization_id = up.organization_id limit 1;
  if not found then raise exception 'Active staff profile required'; end if;
  if p_client_event_id is null then raise exception 'client_event_id is required'; end if;
  if p_period_start is null or p_period_end is null or p_period_start > p_period_end or p_period_end - p_period_start > 31 then raise exception 'Timesheet period must be between 1 and 32 days'; end if;
  if p_period_end > current_date then raise exception 'Future timesheet periods cannot be submitted'; end if;
  if v_adjustment < -744 or v_adjustment > 744 then raise exception 'Adjustment hours are outside the accepted range'; end if;

  select t.* into v_sheet from public.timesheets t where t.organization_id = v_staff.organization_id and t.staff_id = v_staff.id and t.client_event_id = p_client_event_id;
  if found then
    return query select v_sheet.id, false, v_sheet.submitted_at, coalesce(v_sheet.work_derived_hours, 0), v_sheet.actual_hours, (select count(*)::integer from public.timesheet_work_entries e where e.timesheet_id = v_sheet.id);
    return;
  end if;
  if exists (select 1 from public.timesheets t where t.staff_id = v_staff.id and daterange(t.period_start, t.period_end, '[]') && daterange(p_period_start, p_period_end, '[]')) then raise exception 'A timesheet already overlaps this period'; end if;

  for v_work in select * from public.get_officer_timesheet_work(p_period_start, p_period_end) loop
    v_work_minutes := v_work_minutes + v_work.calculated_minutes;
    v_source_count := v_source_count + 1;
    v_work_json := v_work_json || jsonb_build_array(jsonb_build_object('source_type', v_work.source_type, 'source_id', v_work.source_id, 'work_status', v_work.work_status, 'started_at', v_work.started_at, 'ended_at', v_work.ended_at, 'calculated_minutes', v_work.calculated_minutes, 'label', v_work.label, 'metadata', v_work.metadata));
  end loop;

  v_actual := round((v_work_minutes::numeric / 60) + v_adjustment, 2);
  if v_actual < 0 or v_actual > 744 then raise exception 'Derived actual hours are outside the accepted range'; end if;

  select coalesce(sum(extract(epoch from (s.scheduled_end - s.scheduled_start)) / 3600), 0) into v_scheduled from public.shifts s where s.organization_id = v_staff.organization_id and s.officer_user_id = v_user_id and s.scheduled_start::date between p_period_start and p_period_end and s.status in ('accepted', 'in_progress', 'completed');

  insert into public.timesheets (organization_id, staff_id, period_start, period_end, scheduled_hours, actual_hours, overtime_hours, adjustment_hours, work_derived_hours, work_summary, status, notes, submitted_at, client_event_id)
  values (v_staff.organization_id, v_staff.id, p_period_start, p_period_end, round(v_scheduled, 2), v_actual, greatest(0, v_actual - round(v_scheduled, 2)), v_adjustment, round(v_work_minutes::numeric / 60, 2), jsonb_build_object('source_count', v_source_count, 'work_minutes', v_work_minutes, 'entries', v_work_json), 'submitted', nullif(trim(coalesce(p_notes, '')), ''), clock_timestamp(), p_client_event_id)
  returning * into v_sheet;

  for v_work in select value from jsonb_array_elements(v_work_json) loop
    insert into public.timesheet_work_entries (organization_id, timesheet_id, source_type, source_id, work_status, started_at, ended_at, calculated_minutes, metadata)
    values (v_staff.organization_id, v_sheet.id, (v_work.value)->>'source_type', ((v_work.value)->>'source_id')::uuid, (v_work.value)->>'work_status', ((v_work.value)->>'started_at')::timestamptz, ((v_work.value)->>'ended_at')::timestamptz, ((v_work.value)->>'calculated_minutes')::integer, coalesce((v_work.value)->'metadata', '{}'::jsonb));
  end loop;

  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_staff.organization_id, v_user_id, 'timesheet_submitted_from_work', 'timesheets', v_sheet.id, jsonb_build_object('staff_id', v_sheet.staff_id, 'period_start', p_period_start, 'period_end', p_period_end, 'work_derived_hours', v_sheet.work_derived_hours, 'adjustment_hours', v_adjustment, 'actual_hours', v_sheet.actual_hours, 'source_count', v_source_count));

  return query select v_sheet.id, true, v_sheet.submitted_at, v_sheet.work_derived_hours, v_sheet.actual_hours, v_source_count;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_officer_timesheet_from_work"(p_client_event_id uuid, p_period_start date, p_period_end date, p_adjustment_hours numeric, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean DEFAULT false, p_equipment_issue_reported boolean DEFAULT false, p_follow_up_required boolean DEFAULT false, p_follow_up_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, created boolean, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_shift public.shifts%rowtype;
  v_debrief public.shift_debriefs%rowtype;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_client_event_id is null then raise exception 'client_event_id is required'; end if;
  if char_length(trim(coalesce(p_summary, ''))) not between 10 and 5000 then raise exception 'Debrief summary must be between 10 and 5000 characters'; end if;
  if p_follow_up_required and nullif(trim(coalesce(p_follow_up_notes, '')), '') is null then raise exception 'Follow-up notes are required'; end if;
  select s.* into v_shift from public.shifts s where s.id = p_shift_id for share;
  if not found then raise exception 'Shift not found'; end if;
  if v_shift.officer_user_id <> v_user_id then raise exception 'Shift does not belong to the authenticated officer'; end if;
  if v_shift.status not in ('accepted', 'in_progress', 'completed') then raise exception 'Shift is not eligible for debrief'; end if;
  select d.* into v_debrief from public.shift_debriefs d
  where d.organization_id = v_shift.organization_id and d.officer_user_id = v_user_id and d.client_event_id = p_client_event_id;
  if found then return query select v_debrief.id, false, v_debrief.submitted_at; return; end if;
  if exists (select 1 from public.shift_debriefs d where d.shift_id = p_shift_id) then raise exception 'A debrief has already been submitted for this shift'; end if;
  insert into public.shift_debriefs (organization_id, shift_id, officer_user_id, client_event_id, summary, safety_incident_reported, equipment_issue_reported, follow_up_required, follow_up_notes)
  values (v_shift.organization_id, p_shift_id, v_user_id, p_client_event_id, trim(p_summary), coalesce(p_safety_incident_reported, false), coalesce(p_equipment_issue_reported, false), coalesce(p_follow_up_required, false), nullif(trim(coalesce(p_follow_up_notes, '')), ''))
  returning * into v_debrief;
  insert into public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_shift.organization_id, v_user_id, 'shift_debrief_submitted', 'shift_debriefs', v_debrief.id,
    jsonb_build_object('shift_id', p_shift_id, 'safety_incident_reported', v_debrief.safety_incident_reported, 'equipment_issue_reported', v_debrief.equipment_issue_reported, 'follow_up_required', v_debrief.follow_up_required));
  return query select v_debrief.id, true, v_debrief.submitted_at;
end;
$function$;
COMMENT ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) IS 'Creates one retry-safe, self-owned, append-only handover per eligible shift and audits submission.';
REVOKE ALL ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_shift_debrief"(p_shift_id uuid, p_client_event_id uuid, p_summary text, p_safety_incident_reported boolean, p_equipment_issue_reported boolean, p_follow_up_required boolean, p_follow_up_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_smoke_assessment"(p_client_request_id uuid, p_payload jsonb)
 RETURNS TABLE(assessment_id uuid, created boolean, assessed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid:=auth.uid();v_profile public.user_profiles%rowtype;v_existing public.smoke_assessments%rowtype;v_item public.smoke_assessments%rowtype;
  v_site public.client_sites%rowtype;v_site_id uuid;v_complainant_site_id uuid;v_complaint_source text;v_source_type text;v_severity text;
  v_checklist jsonb:=coalesce(p_payload->'checklist','[]'::jsonb);v_photos jsonb:=coalesce(p_payload->'photo_urls','[]'::jsonb);
  v_lat double precision;v_lng double precision;v_accuracy double precision;
begin
  if v_actor is null then raise exception 'Authentication required';end if;
  if p_client_request_id is null then raise exception 'Client request ID is required';end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'Smoke assessment payload is required';end if;
  select * into v_profile from public.user_profiles where id=v_actor and deactivated_at is null;
  if not found or v_profile.role not in('officer','admin_officer','admin','master','grand_master') then raise exception 'Active Smoke Control officer required';end if;
  perform pg_advisory_xact_lock(hashtextextended(p_client_request_id::text,0));
  select * into v_existing from public.smoke_assessments where organization_id=v_profile.organization_id and client_request_id=p_client_request_id;
  if found then return query select v_existing.id,false,v_existing.assessed_at;return;end if;
  begin
    v_site_id:=(p_payload->>'site_id')::uuid;v_complainant_site_id=nullif(p_payload->>'complainant_site_id','')::uuid;
    v_lat:=(p_payload->>'gps_lat')::double precision;v_lng:=(p_payload->>'gps_lng')::double precision;v_accuracy=nullif(p_payload->>'gps_accuracy','')::double precision;
  exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'Site and GPS values must be valid';end;
  select * into v_site from public.client_sites where id=v_site_id and active and public.org_access_allowed(client_organization_id);
  if not found then raise exception 'Smoke source site is unavailable or access denied';end if;
  if v_complainant_site_id is not null and not exists(select 1 from public.client_sites where id=v_complainant_site_id and active and public.org_access_allowed(client_organization_id)) then raise exception 'Complainant site is unavailable or access denied';end if;
  v_complaint_source:=p_payload->>'complaint_source';v_source_type:=p_payload->>'smoke_source_type';v_severity:=p_payload->>'severity';
  if v_complaint_source not in('neighbour','council_hotline','self_report','other') then raise exception 'Unsupported complaint source';end if;
  if v_source_type not in('domestic_solid_fuel','industrial','vehicle_exhaust','agricultural','nuisance_burning','unknown') then raise exception 'Unsupported smoke source type';end if;
  if v_severity not in('low','moderate','high','critical') then raise exception 'Unsupported smoke severity';end if;
  if nullif(trim(coalesce(p_payload->>'scene_description','')),'') is null or nullif(trim(coalesce(p_payload->>'complaint_address','')),'') is null or nullif(trim(coalesce(p_payload->>'source_address','')),'') is null then raise exception 'Scene, complaint address, and source address are required';end if;
  if coalesce((p_payload->>'source_confirmed')::boolean,false) is false then raise exception 'Officer must confirm the observed smoke source';end if;
  if jsonb_typeof(v_checklist)<>'array' or jsonb_array_length(v_checklist)<4 or exists(select 1 from jsonb_array_elements(v_checklist) item where item<>'true'::jsonb) then raise exception 'All Smoke health and safety confirmations are required';end if;
  if jsonb_typeof(v_photos)<>'array' or jsonb_array_length(v_photos)<1 or jsonb_array_length(v_photos)>3 then raise exception 'Between one and three Smoke evidence photos are required';end if;
  if exists(select 1 from jsonb_array_elements(v_photos) photo where coalesce(photo->>'storage_bucket','')<>'scans' or coalesce(photo->>'storage_path','') not like 'org/'||v_profile.organization_id::text||'/smoke/'||p_client_request_id::text||'/%') then raise exception 'Smoke evidence path is outside the authorized case';end if;
  if exists(select 1 from jsonb_array_elements(v_photos) photo left join storage.objects object on object.bucket_id='scans' and object.name=photo->>'storage_path' where object.id is null) then raise exception 'Smoke evidence object does not exist';end if;
  if v_lat not between -90 and 90 or v_lng not between -180 and 180 or (v_accuracy is not null and (v_accuracy<0 or v_accuracy>1000)) then raise exception 'GPS coordinates are outside the accepted range';end if;
  insert into public.smoke_assessments(organization_id,officer_user_id,officer_id,officer_name,site_id,complainant_site_id,client_request_id,complaint_source,smoke_source_type,severity,scene_description,notes,address,complaint_address,source_confirmed,checklist,photo_urls,gps_lat,gps_lng,gps_accuracy,action_taken,legal_basis,follow_up_required,status)
  values(v_profile.organization_id,v_actor,v_actor,coalesce(nullif(trim(v_profile.display_name),''),v_profile.email),v_site.id,v_complainant_site_id,p_client_request_id,v_complaint_source,v_source_type,v_severity,trim(p_payload->>'scene_description'),nullif(trim(coalesce(p_payload->>'notes','')),''),trim(p_payload->>'source_address'),trim(p_payload->>'complaint_address'),true,v_checklist,v_photos,v_lat,v_lng,v_accuracy,'no_action',null,false,'open') returning * into v_item;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata) values(v_item.organization_id,v_actor,'smoke_assessment_submitted','smoke_assessments',v_item.id,jsonb_build_object('client_request_id',p_client_request_id,'site_id',v_item.site_id,'severity',v_item.severity));
  return query select v_item.id,true,v_item.assessed_at;
end;$function$;
REVOKE ALL ON FUNCTION "public"."submit_smoke_assessment"(p_client_request_id uuid, p_payload jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment"(p_client_request_id uuid, p_payload jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment"(p_client_request_id uuid, p_payload jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment"(p_client_request_id uuid, p_payload jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text DEFAULT 'domestic_solid_fuel'::text, p_complaint_source text DEFAULT 'neighbour'::text, p_severity text DEFAULT 'medium'::text, p_action_taken text DEFAULT 'no_action'::text, p_scene_description text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_complaint_address text DEFAULT NULL::text, p_complainant_site_id uuid DEFAULT NULL::uuid, p_site_id uuid DEFAULT NULL::uuid, p_notice_number text DEFAULT NULL::text, p_legal_basis text DEFAULT 'RMA s.17A'::text, p_is_out_of_hours boolean DEFAULT false, p_follow_up_required boolean DEFAULT false, p_shift_id uuid DEFAULT NULL::uuid, p_dispatch_job_id uuid DEFAULT NULL::uuid, p_evidence_items jsonb DEFAULT '[]'::jsonb, p_classification jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(id uuid, created boolean, received_at timestamp with time zone, evidence_state text, review_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_existing public.smoke_assessments%rowtype;
  v_assessment public.smoke_assessments%rowtype;
  v_review_state text;
  v_evidence_state text := 'verified';
  v_item jsonb;
  v_evidence_id uuid;
  v_photo_arr jsonb := '[]'::jsonb;
  v_ordinal integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id and p.deactivated_at is null and p.role in ('officer', 'admin_officer', 'admin', 'master', 'grand_master');
  if v_org_id is null then raise exception 'Active officer profile required'; end if;
  if p_client_request_id is null then raise exception 'client_request_id is required'; end if;

  if p_assessed_at is null or p_assessed_at > now() + interval '5 minutes' or p_assessed_at < now() - interval '24 hours' then
    raise exception 'assessed_at is outside the accepted capture window';
  end if;

  if nullif(trim(coalesce(p_address, '')), '') is null then
    raise exception 'Observed smoke location address is required';
  end if;

  if p_action_taken in ('abatement_notice', 'infringement_notice') and nullif(trim(coalesce(p_notice_number, '')), '') is null then
    raise exception 'Notice number is required for statutory abatement or infringement notices';
  end if;

  if p_shift_id is not null and not exists (select 1 from public.shifts s where s.id = p_shift_id and s.organization_id = v_org_id) then
    raise exception 'Shift does not belong to the officer organisation';
  end if;

  if p_dispatch_job_id is not null and not exists (select 1 from public.dispatch_jobs d where d.id = p_dispatch_job_id and d.organization_id = v_org_id) then
    raise exception 'Dispatch job does not belong to the officer organisation';
  end if;

  -- Idempotency check
  select s.* into v_existing from public.smoke_assessments s
    where s.organization_id = v_org_id and s.officer_user_id = v_user_id and s.client_request_id = p_client_request_id;
  if found then
    return query select v_existing.id, false, v_existing.created_at, v_existing.evidence_state, v_existing.review_state;
    return;
  end if;

  -- Derive initial review state
  if p_classification is null or coalesce(p_classification->>'classification', '') = '' or coalesce(p_classification->>'status', '') = 'unavailable' then
    v_review_state := 'requires_supervisor_review';
  else
    v_review_state := 'submitted';
  end if;

  insert into public.smoke_assessments (
    organization_id, officer_user_id, officer_id, client_request_id, assessed_at,
    smoke_source_type, smoke_source, complaint_source, severity, action_taken, action,
    scene_description, address, complaint_address, complainant_site_id, site_id,
    notice_number, legal_basis, is_out_of_hours, follow_up_required,
    shift_id, dispatch_job_id, status, evidence_state, review_state,
    bob_classification, bob_confidence
  ) values (
    v_org_id, v_user_id, v_user_id, p_client_request_id, p_assessed_at,
    p_smoke_source_type, p_smoke_source_type, p_complaint_source, p_severity, p_action_taken, p_action_taken,
    nullif(trim(coalesce(p_scene_description, '')), ''), trim(p_address), nullif(trim(coalesce(p_complaint_address, '')), ''), p_complainant_site_id, p_site_id,
    nullif(trim(coalesce(p_notice_number, '')), ''), coalesce(p_legal_basis, 'RMA s.17A'), coalesce(p_is_out_of_hours, false), coalesce(p_follow_up_required, false),
    p_shift_id, p_dispatch_job_id, 'open', v_evidence_state, v_review_state,
    nullif(trim(coalesce(p_classification->>'classification', '')), ''), (p_classification->>'confidence')::real
  ) returning * into v_assessment;

  -- Process evidence items
  if jsonb_array_length(p_evidence_items) > 0 then
    for v_item in select * from jsonb_array_elements(p_evidence_items) loop
      v_evidence_id := gen_random_uuid();
      insert into public.evidence_items (
        id, organization_id, module_key, evidence_kind, storage_path, captured_by_user_id, captured_at, metadata
      ) values (
        v_evidence_id, v_org_id, 'smoke_complaints', coalesce(v_item->>'evidence_kind', 'photo'), v_item->>'watermarked_path', v_user_id, p_assessed_at, coalesce(v_item, '{}'::jsonb)
      );

      insert into public.smoke_assessment_evidence (
        organization_id, smoke_assessment_id, evidence_item_id, ordinal, purpose
      ) values (
        v_org_id, v_assessment.id, v_evidence_id, v_ordinal, coalesce(v_item->>'purpose', 'primary_evidence')
      );

      v_photo_arr := v_photo_arr || jsonb_build_array(jsonb_build_object(
        'id', v_evidence_id,
        'storage_path', v_item->>'watermarked_path',
        'original_path', v_item->>'original_path',
        'captured_at', p_assessed_at
      ));
      v_ordinal := v_ordinal + 1;
    end loop;

    update public.smoke_assessments
      set photo_urls = v_photo_arr
      where id = v_assessment.id;
  end if;

  insert into public.audit_log (
    organization_id, actor_user_id, action, target_table, target_id, metadata
  ) values (
    v_org_id, v_user_id, 'smoke_assessment_submitted', 'smoke_assessments', v_assessment.id,
    jsonb_build_object(
      'client_request_id', p_client_request_id,
      'smoke_source_type', v_assessment.smoke_source_type,
      'severity', v_assessment.severity,
      'action_taken', v_assessment.action_taken,
      'is_out_of_hours', v_assessment.is_out_of_hours,
      'review_state', v_review_state,
      'evidence_count', v_ordinal
    )
  );

  return query select v_assessment.id, true, v_assessment.created_at, v_assessment.evidence_state, v_assessment.review_state;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."submit_smoke_assessment_receipt"(p_client_request_id uuid, p_assessed_at timestamp with time zone, p_smoke_source_type text, p_complaint_source text, p_severity text, p_action_taken text, p_scene_description text, p_address text, p_complaint_address text, p_complainant_site_id uuid, p_site_id uuid, p_notice_number text, p_legal_basis text, p_is_out_of_hours boolean, p_follow_up_required boolean, p_shift_id uuid, p_dispatch_job_id uuid, p_evidence_items jsonb, p_classification jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_authorised_org_ids"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  affected uuid;
begin
  affected := coalesce(new.user_id, old.user_id);
  update public.user_profiles up
    set authorized_organization_ids = (
      select coalesce(array_agg(branch_org_id), array[]::uuid[])
      from public.staff_branch_authorisations
      where user_id = affected and status = 'active'
    )
  where up.id = affected;
  return null;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_authorised_org_ids"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_authorised_org_ids"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_authorised_org_ids"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_authorised_org_ids"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_authorised_org_ids"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_authorised_org_ids"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_bob_self_memory_content"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.memory_text IS NULL AND NEW.content IS NOT NULL THEN
    NEW.memory_text := NEW.content;
  ELSIF NEW.content IS NULL AND NEW.memory_text IS NOT NULL THEN
    NEW.content := NEW.memory_text;
  ELSIF NEW.content IS NOT NULL AND NEW.memory_text IS NOT NULL AND NEW.content <> NEW.memory_text THEN
    NEW.memory_text := NEW.content;
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_bob_self_memory_content"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_bob_self_memory_content"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_bob_self_memory_content"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_bob_self_memory_content"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_bob_self_memory_content"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_bob_self_memory_content"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_client_sites_org_ids"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.organization_id is null and new.client_organization_id is not null then
    new.organization_id := new.client_organization_id;
  end if;

  if new.client_organization_id is null and new.organization_id is not null then
    new.client_organization_id := new.organization_id;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_client_sites_org_ids"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_client_sites_org_ids"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_client_sites_org_ids"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_client_sites_org_ids"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_client_sites_org_ids"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_client_sites_org_ids"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_face_observation_reference"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  reference jsonb;
BEGIN
  SELECT metadata->'face_reference' INTO reference
    FROM public.person_records WHERE id = NEW.person_record_id;
  IF jsonb_typeof(NEW.metadata->'embedding') IS DISTINCT FROM 'array'
     AND jsonb_typeof(reference->'embedding') = 'array' THEN
    NEW.metadata := NEW.metadata || jsonb_build_object(
      'embedding', reference->'embedding',
      'original_thumbnail', COALESCE(NEW.metadata->>'original_thumbnail', reference->>'thumbnail')
    );
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_face_observation_reference"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_face_observation_reference"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_face_observation_reference"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_face_observation_reference"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_face_observation_reference"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_face_observation_reference"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_invitation_status"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Only sync if the invite is linked to an agreement
  IF NEW.service_agreement_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Never overwrite 'accepted' (acceptance is permanent)
  IF (SELECT invitation_status FROM public.service_agreements
      WHERE id = NEW.service_agreement_id) = 'accepted' THEN
    RETURN NEW;
  END IF;

  -- On INSERT of a pending invite: set agreement to 'invited'
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    UPDATE public.service_agreements
    SET invitation_status = 'invited'
    WHERE id = NEW.service_agreement_id;
    RETURN NEW;
  END IF;

  -- On status change FROM pending: derive the new agreement status
  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status != 'pending' THEN
    UPDATE public.service_agreements
    SET invitation_status = CASE NEW.status
      WHEN 'accepted' THEN 'accepted'
      WHEN 'declined' THEN 'declined'
      WHEN 'revoked' THEN 'not_invited'
      WHEN 'expired' THEN 'expired'
    END
    WHERE id = NEW.service_agreement_id;
    RETURN NEW;
  END IF;

  -- All other changes: no-op (historical invites don't affect the agreement)
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_invitation_status"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_invitation_status"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."sync_observation_to_location_event"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid;
BEGIN
  IF NEW.site_id IS NOT NULL AND NEW.zone_id IS NOT NULL THEN
    RAISE EXCEPTION 'Observation must reference a Site or Zone, not both';
  END IF;

  -- Unresolved historical-style captures remain in the source table and receive
  -- context provenance, but do not create an invalid location_events row.
  IF NEW.site_id IS NULL AND NEW.zone_id IS NULL THEN
    INSERT INTO public.event_context_snapshots (
      source_table, source_event_id, location_id, module_key, provider_organization_id,
      client_organization_id, authority_snapshot, source_refs, captured_at
    ) VALUES (
      'observations', NEW.id, NEW.location_id, NEW.module_key, NEW.organization_id,
      NEW.client_org_id, jsonb_build_object('officer_id', NEW.officer_id),
      jsonb_build_object('source', 'observation_trigger', 'unresolved_reason', 'no_site_or_zone'), NEW.observed_at
    ) ON CONFLICT (source_table, source_event_id) DO NOTHING;
    RETURN NEW;
  END IF;

  INSERT INTO public.location_events (
    organization_id, client_site_id, zone_id, event_type, module_key, occurred_at,
    status, source, external_ref, payload, observed_entity_type, observed_entity_id, created_by
  ) VALUES (
    NEW.organization_id, NEW.site_id, NEW.zone_id, 'observation', NEW.module_key, NEW.observed_at,
    coalesce(NEW.compliance_status, 'recorded'), 'observation_trigger', NEW.id::text,
    jsonb_build_object('observation_id', NEW.id, 'plate_number', NEW.plate_number,
      'compliance_status', NEW.compliance_status), 'vehicle', NEW.id, NEW.officer_id
  ) RETURNING id INTO v_event_id;

  INSERT INTO public.event_context_snapshots (
    source_table, source_event_id, location_id, client_site_id, zone_id, module_key,
    provider_organization_id, client_organization_id, authority_snapshot, source_refs, captured_at
  ) VALUES (
    'observations', NEW.id, NEW.location_id, NEW.site_id, NEW.zone_id, NEW.module_key,
    NEW.organization_id, NEW.client_org_id, jsonb_build_object('officer_id', NEW.officer_id),
    jsonb_build_object('location_event_id', v_event_id, 'source', 'observation_trigger'), NEW.observed_at
  ) ON CONFLICT (source_table, source_event_id) DO NOTHING;

  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION "public"."sync_observation_to_location_event"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."sync_observation_to_location_event"() TO "service_role";

