CREATE OR REPLACE FUNCTION "public"."tg_observations_enforce_lock"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- CONDITION A: post-lock edit (row was already locked before this UPDATE).
  if old.locked_at is not null then
    -- Block clearing or rewriting locked_at.
    if new.locked_at is distinct from old.locked_at then
      raise exception
        'observation % is locked. locked_at may not be cleared or rewritten. Use the authorised correction path.',
        old.id
        using errcode = 'P0001';
    end if;
    -- Block changes to frozen fact fields.
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % is locked (locked_at = %). Frozen fact fields may not be edited after lock. Authorised corrections require the correction workflow (Part 2, not yet built).',
        old.id, old.locked_at
        using errcode = 'P0001';
    end if;
  end if;

  -- CONDITION B: lock-transition tamper (this UPDATE causes the row to become locked).
  -- The normal completion write sets photo fields only and must pass through.
  -- A tampered write that also changes frozen fields must be blocked.
  if old.locked_at is null and new.locked_at is not null then
    if (
      new.observed_at       is distinct from old.observed_at       or
      new.gps_lat           is distinct from old.gps_lat           or
      new.gps_lng           is distinct from old.gps_lng           or
      new.plate_number      is distinct from old.plate_number      or
      new.is_compliant      is distinct from old.is_compliant      or
      new.compliance_reason is distinct from old.compliance_reason or
      new.officer_id        is distinct from old.officer_id        or
      new.zone_id           is distinct from old.zone_id
    ) then
      raise exception
        'observation % cannot be locked with mutated frozen fields. Frozen fact fields must be unchanged at the moment of lock.',
        old.id
        using errcode = 'P0001';
    end if;
  end if;

  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_observations_enforce_lock"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_enforce_lock"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_observations_lock_on_completion"()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Transition-based: only fire when photo_captured_at goes NULL -> NOT NULL.
  -- Never fires if photo_captured_at was already set, or if it stays null.
  if (old.photo_captured_at is null and new.photo_captured_at is not null) then
    -- Write-once: only set locked_at if not already set (idempotent).
    if new.locked_at is null then
      new.locked_at := now();
    end if;
  end if;
  return new;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."tg_observations_lock_on_completion"() FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "anon";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."tg_observations_lock_on_completion"() TO "service_role";

CREATE OR REPLACE FUNCTION "public"."tg_place_permanence"()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.place_delete_scope', true) = 'test_dataset_purge' THEN RETURN OLD; END IF;
  -- A service or admin session may roll back a row it created moments ago (proposal compensation).
  IF (auth.role() = 'service_role' OR session_user IN ('postgres', 'supabase_admin'))
     AND OLD.created_at > clock_timestamp() - interval '15 minutes' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Places are permanent: %.% cannot be deleted. Retire or merge it instead.', TG_TABLE_NAME, OLD.id
    USING ERRCODE = 'P0001', HINT = 'docs/canon/LOCATION_HOUSE_MODEL.md, ruling 2026-09-15';
END $function$;
REVOKE ALL ON FUNCTION "public"."tg_place_permanence"() FROM PUBLIC, "anon", "authenticated", "service_role";
