CREATE OR REPLACE FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when line.id is null then 'missing pay evidence for dispatch work'
    when line.pay_code = 'UNRESOLVED' then 'unresolved dispatch pay evidence'
    when latest.decision is null then 'unreviewed dispatch pay evidence'
    when latest.decision <> 'approved' then 'rejected dispatch pay evidence'
  end
  from public.timesheet_work_entries work
  left join public.dispatch_job_pay_lines line
    on line.organization_id = work.organization_id
   and line.source_dispatch_id = work.source_id
  left join lateral (
    select review.decision
    from public.dispatch_job_pay_line_reviews review
    where review.pay_line_id = line.id
    order by review.reviewed_at desc, review.id desc
    limit 1
  ) latest on true
  where work.timesheet_id = p_timesheet_id
    and work.source_type = 'dispatch_job'
    and (line.id is null or line.pay_code = 'UNRESOLVED' or latest.decision is distinct from 'approved')
  order by work.created_at, line.created_at nulls first
  limit 1;
$function$;
REVOKE ALL ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."timesheet_dispatch_pay_review_blocker"(p_timesheet_id uuid) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."unpublish_roster_slot"(p_client_request_id uuid, p_slot_id uuid, p_expected_status text, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(slot_id uuid, slot_status text, shift_cancelled boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_slot public.roster_slots%rowtype;
  v_shift public.shifts%rowtype;
  v_shift_canc boolean := false;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select s.* into v_slot from public.roster_slots s where s.id = p_slot_id for update;
  if not found then
    raise exception 'Roster slot not found';
  end if;

  if not public.is_admin_for_org(v_slot.organization_id) then
    raise exception 'Not authorised to manage roster slots for this organization';
  end if;

  if v_slot.status <> p_expected_status then
    raise exception 'Roster slot changed from expected status % to %', p_expected_status, v_slot.status;
  end if;

  if v_slot.status not in ('published', 'accepted') then
    raise exception 'Only published or accepted roster slots can be recalled to draft';
  end if;

  -- Update slot back to draft
  update public.roster_slots set status = 'draft', updated_at = now() where id = v_slot.id returning * into v_slot;

  -- Cancel linked shift if present and not in progress / completed
  select sh.* into v_shift from public.shifts sh where sh.roster_slot_id = v_slot.id;
  if found then
    if v_shift.status = 'scheduled' then
      update public.shifts set status = 'cancelled', updated_at = now() where id = v_shift.id;
      v_shift_canc := true;
    elsif v_shift.status in ('in_progress', 'completed') then
      raise exception 'Cannot recall roster slot while linked shift is %', v_shift.status;
    end if;
  end if;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_slot.organization_id,
    v_actor,
    'roster_slot_unpublished',
    'roster_slots',
    v_slot.id,
    jsonb_build_object(
      'reason', v_reason,
      'shift_cancelled', v_shift_canc,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_slot.id, v_slot.status, v_shift_canc;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."unpublish_roster_slot"(p_client_request_id uuid, p_slot_id uuid, p_expected_status text, p_reason text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."unpublish_roster_slot"(p_client_request_id uuid, p_slot_id uuid, p_expected_status text, p_reason text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."unpublish_roster_slot"(p_client_request_id uuid, p_slot_id uuid, p_expected_status text, p_reason text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."unpublish_roster_slot"(p_client_request_id uuid, p_slot_id uuid, p_expected_status text, p_reason text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."unregister_officer_device_token"(p_push_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_clean_token text := trim(coalesce(p_push_token, ''));
  v_count integer;
  v_org_id uuid;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.organization_id into v_org_id from public.user_profiles p where p.id = v_user_id;

  update public.officer_device_tokens
    set is_active = false, updated_at = clock_timestamp()
    where user_id = v_user_id and push_token = v_clean_token;
  get diagnostics v_count = row_count;

  if v_count > 0 and v_org_id is not null then
    insert into public.audit_log (
      organization_id, actor_user_id, action, target_table, target_id, metadata
    ) values (
      v_org_id, v_user_id, 'officer_device_token_unregistered', 'officer_device_tokens', v_user_id,
      jsonb_build_object('push_token', v_clean_token)
    );
  end if;

  return v_count > 0;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."unregister_officer_device_token"(p_push_token text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."unregister_officer_device_token"(p_push_token text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."unregister_officer_device_token"(p_push_token text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."unregister_officer_device_token"(p_push_token text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb DEFAULT '{}'::jsonb, p_notes text DEFAULT NULL::text)
 RETURNS cctv_entity_observations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_observation public.cctv_entity_observations%rowtype;
  v_person public.person_records%rowtype;
  v_canonical_id uuid;
  v_display_name text := nullif(trim(coalesce(p_display_name, '')), '');
  v_detail_keys jsonb;
BEGIN
  SELECT * INTO v_observation
    FROM public.cctv_entity_observations
   WHERE id = p_observation_id
   FOR UPDATE;
  IF v_observation.id IS NULL THEN
    RAISE EXCEPTION 'CCTV observation not found';
  END IF;
  IF v_actor IS NULL OR NOT public.org_access_allowed(v_observation.organization_id) THEN
    RAISE EXCEPTION 'CCTV person profile access denied';
  END IF;
  IF v_observation.entity_kind <> 'person' THEN
    RAISE EXCEPTION 'Only a person observation can update a person profile';
  END IF;
  IF v_display_name IS NULL OR char_length(v_display_name) > 200 THEN
    RAISE EXCEPTION 'A person name between 1 and 200 characters is required';
  END IF;
  IF jsonb_typeof(coalesce(p_profile_details, '{}'::jsonb)) <> 'object'
     OR octet_length(coalesce(p_profile_details, '{}'::jsonb)::text) > 16384 THEN
    RAISE EXCEPTION 'Person profile details must be an object no larger than 16 KB';
  END IF;
  SELECT * INTO v_person
    FROM public.person_records
   WHERE id = v_observation.person_record_id
     AND organization_id = v_observation.organization_id
   FOR UPDATE;
  IF v_person.id IS NULL THEN
    RAISE EXCEPTION 'No inference person profile is attached to this observation';
  END IF;
  v_canonical_id := COALESCE(
    v_observation.canonical_person_id,
    (SELECT link.canonical_person_id FROM public.canonical_person_links AS link WHERE link.source_table = 'person_records' AND link.source_id = v_person.id LIMIT 1),
    public.ensure_canonical_person_for_record(v_person.id)
  );

  UPDATE public.person_records
     SET display_name = v_display_name,
         review_state = 'manual_review_required',
         metadata = metadata || jsonb_build_object(
           'identity_status', 'named_by_human_review',
           'named_at', clock_timestamp(),
           'named_by', v_actor,
          'profile_details', coalesce(metadata->'profile_details', '{}'::jsonb) || coalesce(p_profile_details, '{}'::jsonb)
         )
   WHERE id = v_person.id;
  UPDATE public.canonical_people
     SET display_name = v_display_name,
         normalized_name = regexp_replace(lower(v_display_name), '[^a-z0-9]+', '', 'g'),
         review_state = 'manual_review_required',
         metadata = metadata || jsonb_build_object(
           'identity_status', 'named_by_human_review',
           'named_at', clock_timestamp(),
           'named_by', v_actor
         ),
         updated_at = clock_timestamp()
   WHERE id = v_canonical_id;
  UPDATE public.cctv_entity_observations
     SET person_record_id = v_person.id,
         canonical_person_id = v_canonical_id,
         review_state = 'accepted',
         portfolio_state = 'linked',
         reviewed_by = v_actor,
         reviewed_at = clock_timestamp(),
         review_notes = nullif(trim(p_notes), '')
   WHERE id = v_observation.id
   RETURNING * INTO v_observation;
  SELECT COALESCE(jsonb_agg(key ORDER BY key), '[]'::jsonb)
    INTO v_detail_keys
    FROM jsonb_object_keys(coalesce(p_profile_details, '{}'::jsonb)) AS key;
  INSERT INTO public.audit_log (organization_id, actor_user_id, action, target_table, target_id, metadata)
  VALUES (
    v_observation.organization_id,
    v_actor,
    'cctv_person_profile_updated',
    'person_records',
    v_person.id,
    jsonb_build_object(
      'observation_id', v_observation.id,
      'canonical_person_id', v_canonical_id,
      'profile_detail_keys', v_detail_keys,
      'profile_name_changed', true
    )
  );
  -- Biometric templates never leave the database through a review response: matching happens in
  -- find_cctv_portfolio_matches, and the reviewer only needs the decision, labels and thumbnail back.
  v_observation.face_vec := NULL; v_observation.appearance_vec := NULL; v_observation.candidate_embedding := NULL; v_observation.appearance_embedding := NULL;
  RETURN v_observation;
END;
$function$;
COMMENT ON FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb, p_notes text) IS 'Human-review path to name and enrich an inferred CCTV person profile without creating a duplicate canonical person.';
REVOKE ALL ON FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_cctv_person_profile"(p_observation_id uuid, p_display_name text, p_profile_details jsonb, p_notes text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric)
 RETURNS TABLE(line_id uuid, quote_id uuid, total_cost numeric, subtotal_charge numeric, discount_amount numeric, gst_amount numeric, total_charge numeric, updated boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_quote public.quotes%rowtype;
  v_line public.quote_lines%rowtype;
  v_description text := nullif(trim(coalesce(p_description, '')), '');
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;

  select q.* into v_quote from public.quotes q where q.id = p_quote_id for update;
  if not found then
    raise exception 'Quote not found';
  end if;

  if not public.is_admin_for_org(v_quote.provider_org_id) then
    raise exception 'Not authorised to price this quote';
  end if;

  if v_quote.status <> p_expected_status then
    raise exception 'Quote changed from expected status % to %', p_expected_status, v_quote.status;
  end if;

  if v_quote.status <> 'draft' then
    raise exception 'Only draft quotes can be modified';
  end if;

  if v_description is null then
    raise exception 'Line description is required';
  end if;

  if p_quantity is null or p_quantity <= 0 or p_quantity > 100000
     or p_unit_cost is null or p_unit_cost < 0 or p_unit_cost > 1000000
     or p_unit_charge is null or p_unit_charge < 0 or p_unit_charge > 1000000 then
    raise exception 'Quote line amounts are outside the accepted range';
  end if;

  select l.* into v_line from public.quote_lines l where l.id = p_line_id and l.quote_id = v_quote.id;
  if not found then
    raise exception 'Quote line not found';
  end if;

  update public.quote_lines
  set
    description = v_description,
    quantity = p_quantity,
    unit_cost = p_unit_cost,
    unit_charge = p_unit_charge
  where id = v_line.id;

  update public.quotes q set
    total_cost = totals.total_cost,
    subtotal_charge = totals.subtotal_charge,
    discount_amount = round(totals.subtotal_charge * q.discount_pct / 100, 2),
    gst_amount = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * q.gst_rate, 2),
    total_charge = round((totals.subtotal_charge - round(totals.subtotal_charge * q.discount_pct / 100, 2)) * (1 + q.gst_rate), 2),
    updated_by = v_actor,
    updated_at = now()
  from (
    select
      coalesce(sum(l.quantity * l.unit_cost), 0)::numeric(12,2) total_cost,
      coalesce(sum(l.quantity * l.unit_charge), 0)::numeric(12,2) subtotal_charge
    from public.quote_lines l
    where l.quote_id = v_quote.id
  ) totals
  where q.id = v_quote.id
  returning q.* into v_quote;

  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (
    v_quote.provider_org_id,
    v_actor,
    'crm_quote_line_updated',
    'quote_lines',
    v_line.id,
    jsonb_build_object(
      'quote_id', v_quote.id,
      'description', v_description,
      'quantity', p_quantity,
      'unit_cost', p_unit_cost,
      'unit_charge', p_unit_charge,
      'total_cost', v_quote.total_cost,
      'total_charge', v_quote.total_charge,
      'client_request_id', p_client_request_id
    )
  );

  return query select v_line.id, v_quote.id, v_quote.total_cost, v_quote.subtotal_charge, v_quote.discount_amount, v_quote.gst_amount, v_quote.total_charge, true;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."update_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_crm_quote_line"(p_client_request_id uuid, p_quote_id uuid, p_line_id uuid, p_expected_status text, p_description text, p_quantity numeric, p_unit_cost numeric, p_unit_charge numeric) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_operating_branch_profile"(p_operating_organization_id uuid, p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_branch public.organizations%rowtype;
begin
  if not public.user_can_operate_organization(p_operating_organization_id) or not public.is_admin_for_org(p_operating_organization_id) then raise exception 'Active authorized operating branch administrator required';end if;
  select * into v_branch from public.organizations where id=p_operating_organization_id and organization_type in ('owner','service_provider','branch') and active for update;if not found then raise exception 'Active operating organisation not found';end if;
  if v_branch.updated_at<>p_expected_updated_at then raise exception 'Organization changed since it was opened';end if;if p_enforcement_workflow_mode not in('admin_first','officer_direct','hybrid') then raise exception 'Unsupported enforcement workflow mode';end if;
  update public.organizations set contact_email=nullif(lower(trim(coalesce(p_contact_email,''))),''),contact_phone=nullif(trim(coalesce(p_contact_phone,'')),''),billing_email=nullif(lower(trim(coalesce(p_billing_email,''))),''),billing_address=nullif(trim(coalesce(p_billing_address,'')),''),enforcement_workflow_mode=p_enforcement_workflow_mode,updated_at=clock_timestamp() where id=v_branch.id returning * into v_branch;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_branch.id,v_actor,'operating_branch_profile_updated','organizations',v_branch.id,jsonb_build_object('enforcement_workflow_mode',v_branch.enforcement_workflow_mode,'billing_configured',v_branch.billing_email is not null));return v_branch;
end;$function$;
REVOKE ALL ON FUNCTION "public"."update_operating_branch_profile"(p_operating_organization_id uuid, p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_operating_branch_profile"(p_operating_organization_id uuid, p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_operating_branch_profile"(p_operating_organization_id uuid, p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_operating_branch_profile"(p_operating_organization_id uuid, p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_organization_profile"(p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_actor uuid:=auth.uid();v_provider uuid;v_org public.organizations%rowtype;
begin
  select actor.organization_id into v_provider from public.user_profiles actor where actor.id=v_actor and actor.deactivated_at is null;
  if v_provider is null or not public.is_admin_for_org(v_provider) then raise exception 'Active organization administrator required';end if;
  select o.* into v_org from public.organizations o where o.id=v_provider for update;if not found then raise exception 'Organization not found';end if;
  if v_org.updated_at<>p_expected_updated_at then raise exception 'Organization changed since it was opened';end if;
  if p_enforcement_workflow_mode not in('admin_first','officer_direct','hybrid') then raise exception 'Unsupported enforcement workflow mode';end if;
  update public.organizations set contact_email=nullif(lower(trim(coalesce(p_contact_email,''))),''),contact_phone=nullif(trim(coalesce(p_contact_phone,'')),''),billing_email=nullif(lower(trim(coalesce(p_billing_email,''))),''),billing_address=nullif(trim(coalesce(p_billing_address,'')),''),enforcement_workflow_mode=p_enforcement_workflow_mode,updated_at=clock_timestamp() where id=v_provider returning * into v_org;
  insert into public.audit_log(organization_id,actor_user_id,action,target_table,target_id,metadata)values(v_provider,v_actor,'organization_profile_updated','organizations',v_provider,jsonb_build_object('enforcement_workflow_mode',v_org.enforcement_workflow_mode,'billing_configured',v_org.billing_email is not null));
  return v_org;
end;$function$;
REVOKE ALL ON FUNCTION "public"."update_organization_profile"(p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_organization_profile"(p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_organization_profile"(p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_organization_profile"(p_expected_updated_at timestamp with time zone, p_contact_email text, p_contact_phone text, p_billing_email text, p_billing_address text, p_enforcement_workflow_mode text) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS roster_slots
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_slot public.roster_slots%rowtype;
  v_staff public.staff_profiles%rowtype;
begin
  select s.* into v_slot from public.roster_slots s where s.id = p_slot_id for update;
  if not found then raise exception 'Roster slot not found'; end if;
  if not public.is_admin_for_org(v_slot.organization_id) then raise exception 'Not authorised to edit this roster slot'; end if;
  if v_slot.status <> p_expected_status then raise exception 'Roster slot changed from expected status % to %', p_expected_status, v_slot.status; end if;
  if v_slot.status <> 'draft' then raise exception 'Only draft roster slots can be edited'; end if;
  if p_scheduled_end <= p_scheduled_start then raise exception 'Roster slot must end after it starts'; end if;

  select sp.* into v_staff from public.staff_profiles sp where sp.id = p_staff_id;
  if not found or v_staff.organization_id <> v_slot.organization_id or not v_staff.work_ready then raise exception 'Assigned staff member is not work-ready'; end if;
  if public.staff_has_roster_availability_conflict(v_staff.id, p_scheduled_start, p_scheduled_end) then raise exception 'Staff member is unavailable during this roster slot'; end if;
  if public.staff_fatigue_conflict(v_staff.id, p_scheduled_start, p_scheduled_end, v_slot.id) is not null then raise exception 'Fatigue rule breach for assigned staff'; end if;

  update public.roster_slots set staff_id = p_staff_id, scheduled_start = p_scheduled_start, scheduled_end = p_scheduled_end, notes = nullif(trim(coalesce(p_notes, '')), '') where id = v_slot.id returning * into v_slot;
  insert into public.audit_log(organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_slot.organization_id, v_actor, 'roster_slot_human_edited', 'roster_slots', v_slot.id, jsonb_build_object('staff_id', p_staff_id, 'scheduled_start', p_scheduled_start, 'scheduled_end', p_scheduled_end));
  return v_slot;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."update_roster_slot"(p_slot_id uuid, p_expected_status text, p_staff_id uuid, p_scheduled_start timestamp with time zone, p_scheduled_end timestamp with time zone, p_notes text) TO "service_role";

