CREATE OR REPLACE FUNCTION "public"."user_has_task_entitlement"(p_user uuid DEFAULT auth.uid(), p_observation_id uuid DEFAULT NULL::uuid, p_noise_assessment_id uuid DEFAULT NULL::uuid, p_smoke_assessment_id uuid DEFAULT NULL::uuid, p_biosecurity_assessment_id uuid DEFAULT NULL::uuid, p_incident_id uuid DEFAULT NULL::uuid, p_notice_id uuid DEFAULT NULL::uuid, p_enforcement_case_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (public.resolve_access_basis(
        p_user, p_observation_id, p_noise_assessment_id, p_smoke_assessment_id,
        p_biosecurity_assessment_id, p_incident_id, p_notice_id, p_enforcement_case_id
     ) ->> 'decision_state') not in ('no_task_entitlement', 'hard_stop'),
    false
  );
$function$;
COMMENT ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) IS 'STRICT BOOLEAN for RLS (ACCESS_MODEL.md section 8). Derived from resolve_access_basis so boolean and UI object can never disagree. SECURITY DEFINER + fixed search_path (0326). 0329: p_user defaults to auth.uid(); the self-only guard lives in resolve_access_basis. On the 0325 observations RLS path the policy passes the authenticated reader (p_user = auth.uid()), so the boolean behaviour is unchanged.';
REVOKE ALL ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."user_has_task_entitlement"(p_user uuid, p_observation_id uuid, p_noise_assessment_id uuid, p_smoke_assessment_id uuid, p_biosecurity_assessment_id uuid, p_incident_id uuid, p_notice_id uuid, p_enforcement_case_id uuid) TO "service_role";

