CREATE OR REPLACE FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text DEFAULT NULL::text, _actor_type wf_actor_type DEFAULT 'user'::wf_actor_type)
 RETURNS wf_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _job public.wf_jobs%rowtype;
  _from_state public.wf_job_state;
  _uid uuid := (select auth.uid());
  _allowed boolean := false;
begin
  if _uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into _job
  from public.wf_jobs
  where id = _job_id
  for update;

  if not found then
    raise exception 'Job not found: %', _job_id;
  end if;

  _from_state := _job.state;

  if _from_state = _to_state then
    raise exception 'No-op transition % -> % is not allowed', _from_state, _to_state;
  end if;

  _allowed :=
    ((_from_state = 'draft' and _to_state = 'verify_pending') and (_job.created_by = _uid or (select public.wf_has_role('operator'))))
    or ((_from_state = 'verify_pending' and _to_state = 'verified') and (select public.wf_has_role('verifier')))
    or ((_from_state = 'verified' and _to_state = 'ratify_pending') and ((select public.wf_has_role('operator')) or (select public.wf_has_role('verifier'))))
    or ((_from_state = 'ratify_pending' and _to_state = 'ratified') and (select public.wf_has_role('ratifier')))
    or ((_from_state = 'ratified' and _to_state = 'running') and ((select public.wf_has_role('runner')) or (select public.wf_has_role('operator'))))
    or ((_from_state = 'running' and _to_state = 'promoted') and (select public.wf_has_role('operator')) and exists (
      select 1 from public.wf_runs r where r.job_id = _job_id and r.status = 'succeeded'
    ))
    or (_to_state = 'failed' and (
      _job.created_by = _uid
      or (select public.wf_has_role('verifier'))
      or (select public.wf_has_role('ratifier'))
      or (select public.wf_has_role('operator'))
      or (select public.wf_has_role('runner'))
    ));

  if not _allowed then
    raise exception 'Illegal transition % -> % for user %', _from_state, _to_state, _uid;
  end if;

  update public.wf_jobs
  set
    state = _to_state,
    verified_at = case when _to_state = 'verified' then now() else verified_at end,
    ratified_at = case when _to_state = 'ratified' then now() else ratified_at end,
    promoted_at = case when _to_state = 'promoted' then now() else promoted_at end
  where id = _job_id
  returning * into _job;

  insert into public.wf_state_events (job_id, from_state, to_state, reason, actor_user_id, actor_type)
  values (_job_id, _from_state, _to_state, _reason, _uid, _actor_type);

  return _job;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "postgres";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "anon";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "authenticated";
GRANT EXECUTE ON FUNCTION "public"."wf_transition_job_state"(_job_id uuid, _to_state wf_job_state, _reason text, _actor_type wf_actor_type) TO "service_role";

CREATE OR REPLACE FUNCTION "public"."workshop_actor_org"(p_organization_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_home uuid;
begin
  if p_organization_id is null then raise exception 'organization_id is required'; end if;
  select up.organization_id into v_home from public.user_profiles up where up.id = v_actor and up.deactivated_at is null;
  if v_home is null then raise exception 'Active user required'; end if;
  if not public.is_admin_for_org(p_organization_id) then raise exception 'Workshop administrator access required'; end if;
  if not exists (select 1 from public.organization_modules m where m.organization_id = p_organization_id and m.module_key = 'workshop' and m.enabled) then
    raise exception 'The workshop module is not enabled for this organisation';
  end if;
  return v_actor;
end;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_actor_org"(p_organization_id uuid) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_actor_org"(p_organization_id uuid) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text)
 RETURNS record
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(pb.unit_cost, 0), coalesce(pb.unit_price, 0), pb.unit_of_measure, pb.name
  from public.finance_price_book pb where pb.item_id = p_item_id;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_current_prices"(p_item_id uuid, OUT unit_cost numeric, OUT unit_price numeric, OUT unit_of_measure text, OUT item_name text) TO "postgres";

CREATE OR REPLACE FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'Active user required'; end if;
  if public.is_admin_for_org(p_work_order.organization_id) then
    perform public.workshop_actor_org(p_work_order.organization_id);
    return 'admin';
  end if;
  if p_work_order.assigned_user_id = v_actor
     and p_work_order.status in ('approved', 'in_progress')
     and exists (select 1 from public.user_profiles up where up.id = v_actor and up.deactivated_at is null)
     and exists (select 1 from public.organization_modules m where m.organization_id = p_work_order.organization_id and m.module_key = 'workshop' and m.enabled) then
    return 'worker';
  end if;
  raise exception 'Only a workshop administrator, or the assigned worker while the job is approved or in progress, can change these lines';
end;
$function$;
REVOKE ALL ON FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders) FROM PUBLIC, "anon", "authenticated", "service_role";
GRANT EXECUTE ON FUNCTION "public"."workshop_line_actor_role"(p_work_order workshop_work_orders) TO "postgres";

