CASE entity_type
    WHEN 'organization'::text THEN org_access_allowed(entity_id)
    WHEN 'location_zone'::text THEN org_access_allowed(( SELECT location_zones.organization_id
       FROM location_zones
      WHERE (location_zones.id = geofence_boundary_history.entity_id)))
    WHEN 'client_site'::text THEN org_access_allowed(( SELECT client_sites.client_organization_id
       FROM client_sites
      WHERE (client_sites.id = geofence_boundary_history.entity_id)))
    ELSE false
END);

